[Theorem th:MLSI-MF of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] Let $h\in{\ensuremath{\mathbb R}} ^{Nn}$, let \(J\in{\ensuremath{\mathbb R}} ^{n\times n}\) be a nonnegative definite matrix with largest eigenvalue \(\lambda(J) < 1/2\), and let  
\(\overline{J}=\max_{i\in [n]} \sum_{j\in [n]}|J_{i,j}|\), \(\overline{h}=\max_{\ell\in [n], i\in[N]}|h_\ell(i)|\). 

For any $N\ge 2$, and $\r\in \ensuremath{\mathcal D}_{\ensuremath{\mathcal A},N}$, 
\begin{equation}
\bar{\mathcal{E}}_{N, J,h,\r}(F, \log F) \ge \a\operatorname{Ent}_{\mu_{N,J,h,\r}}(F),
\end{equation}
for all $F\ge 0$, with constant  $\a$ such that  
  \begin{equation}
        \alpha \ge \tfrac14(1 - 2\lambda(J))\,e^{-8(\overline{J}+\overline{h})}.
   \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 ({\cite[Theorem~4.19) of arXiv:2506.10511, '2506.10511'] {Morters_Peres_2010}}]
Recall \eqref{hausdorff}. Suppose that $(E,\widehat{D})$ is a metric space and $\Delta\geq 0$. If there exists a mass distribution $\zeta$ on $E$ along with constants $C <\infty$ and $\delta > 0$ such that
\begin{equation*}
	\zeta(V)\leq C\left({\rm diam}(V;\widehat{D})\right)^\Delta,
\end{equation*}
for all closed sets $V$ with ${\rm diam}(V;\widehat{D})\leq \delta$, then
\begin{equation*}
	C_\Delta(E,\widehat{D})\geq C^{-1}\zeta(E)>0
\end{equation*}
and hence $\mathrm{dim}_{\mathrm{H}}(E;\widehat{D})\geq \Delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Let $\Lambda$ be a compact subset of $\Delta_I$ and let $k_t:\Lambda\to\N^d$ be Borel and satisfy

\begin{equation*}
\sup_{\lambda\in\Lambda}|k_t(\lambda)-t\lambda|_1=o(\sqrt t).
\end{equation*}

If $\Ee_{\mathfrak a}[L_1^2]<\infty$, then

\begin{equation*}
\sup_{\lambda\in\Lambda}
\frac{|N(k_t(\lambda))-D_{\mathfrak N(k_t(\lambda))}|}{\sqrt t}
\xrightarrow[t\to\infty]{\mathbb P}0.
\end{equation*}

If, in addition, $\Ee_{\mathfrak a}[(R_1^*(g))^2]<\infty$, then the reward accumulated in the incomplete cycle which intersects the boundary is $o_{\Pp}(\sqrt t)$ uniformly over $\lambda\in\Lambda$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm h-continuous of arXiv:2605.21366, 'The Martin boundary of the Directed Landscape'] The following holds on a full probability event. For any $t>s$ and any function $\mathfrak h:\mathbb{R}\to[-\infty,\infty)$ satisfying 
\begin{align}
    \lim_{|y|\to\infty} |y|^{-1}\bigl(\mathfrak h(y)-y^2/(t-s)\bigr) = -\infty,
\end{align}
$x\mapsto\sup_{y\in\mathbb{R}}\{\mathcal L(x,s;y,t)+\mathfrak h(y)\}$ is continuous.

[Lem high-randomization of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] There is a finitely supported random
vector $\bm{u}$ such that 
\begin{equation}
\mathbb{E}[\bm{u}]=\sigma_{\mathrm{small}},\qquad\mathbb{E}\normtwo{\bm{u}}^{2}\le\frac{\normone{\sigma_{\mathrm{tail}}}^{2}}{k-r_{\star}},
\end{equation}
 and, almost surely, 
\begin{equation}
\operatorname{supp}(\bm{u})\subseteq\operatorname{supp}(\sigma_{\mathrm{small}}),\qquad\normzero{\sigma_{\mathrm{big}}}+\normzero{\bm{u}}\le k.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem Taylor1 of arXiv:2510.23430, 'On the Martin boundary for discrete TASEP'] (1) Assume that $\alpha\in \mathbb R_{>0}$. We have $h'_\alpha(u^{crt})=0$ where $u^{crt}=\frac{\alpha}{1+\alpha}$.

(2)  Assume that $\alpha\in \mathbb R_{>0}$. Then $h_\alpha(\frac{\alpha}{1+\alpha})$ is the unique minimum of $h_\alpha(x)$ on $(0,1)$.

(3) Let $D$ be a convex compact set avoiding $0,1$. Then there exists a constant $K>0$ such that for any $z\in D$ and $\alpha\in \mathbb R_{>0}$ satisfying $u^{crt}=\frac{\alpha}{1+\alpha}\in D$ we have
\begin{equation}

\left|h_\alpha(u)-h_\alpha(u^{crt})-\frac{(1+\alpha)^3}{2\alpha}(u-u^{crt})^2\right|<K|u-u^{crt}|^3
\end{equation}

[Cor 31 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Assume we are under the assumptions of Theorem \ref{Théorème central}. We denote $\mc{N}(\widetilde{q}_N,\alpha)$ the number of eigenvalues of $\widetilde{q}_N$ in the interval $[0,\alpha]$. We moreover assume that $\alpha$ satisfies
    \begin{equation}
        N^{-\varrho\eta}\alpha^{-1}\ll\alpha^{{\kappa_2}}\ll 1\mm\mm\text{and}\mm\mm N^{-{\kappa_1}\eta}\ll \alpha^{\kappa_2}\ll 1.
    \end{equation}
    Then, it holds,
    \begin{equation}
        \mc{N}(\widetilde{q}_N,\alpha)=\mc{O}(N^d\alpha^{\kappa_2}).
    \end{equation}

