\begin{align*}
\langle P_{\theta}^{*}[\nu], h_{p} \rangle
  &=\tau[(e^{-\theta}x+\sqrt{1-e^{-2\theta}}y)^{p}]\\
  &=\sum_{\epsilon_{1},\dots, \epsilon_{p}\in\{0,1\}}
  e^{-\theta\sum_{l=1}^p\epsilon_l}(1-e^{-2\theta})^{\frac{p-\sum_{l=1}^p\epsilon_l}{2}}\tau[a_{\epsilon_1}\dots a_{\epsilon_{p}}],
\end{align*}
where the $a_{\epsilon_j}$'s are defined by 
