    Then
    \begin{equation}

        \lim_{k \to \infty}
        \limsup_{r \to \infty}
        \frac{1}{\# B(r)^2}
        \mathbf{E}_{\beta}
        \left[
            \sum_{u,v \in V(\mathcal{G}_r)}
            \mathbf{1}
            \left(
                \# 
