[Proposition prop:chk of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] [\texorpdfstring{[Keeler,hoerm1968,canzani_MRWsurvey,CH20]}{}]
We have the following pointwise Weyl's laws on $(M,g)$, a compact Riemannian manifold without boundary. The next asymptotic relations hold, as $\ell\to +\infty$, for all $k\in \mathbb{N}$ but not necessarily uniformly in $k$.
\begin{enumerate}
    \item Without additional assumptions (result by H\"ormander [hoerm1968], equivalent to (thm:hoermplaw of the paper))
    \begin{equation} 
\delta_{[0,\ell]}^M=O\left( \frac{1}{\ell}\right),
    \end{equation}
  with $\rho_\ell=\rho(M)$ fixed small enough. 
    \item On a manifold without self-focal points (result by Canzani and Hanin [canzani_hanin_2018_cinfscasymp,CH20] reported in [Keeler])
   \begin{equation} 
\delta_{[0,\ell]}^M=o\left( \frac{1}{\ell}\right)
    \end{equation} 
    with $\rho_\ell=o(1)$. Such $M$ is a particular case of what Canzani and Hanin [CH20] define as a \emph{manifold of isotropic scaling}, that is a manifold $M$ such that: with $\alpha=1$ one has $\delta_{[\ell-1,\ell]}=o(1)$ in infinitesimal range $\rho_\ell=o(1)$.
    \item On a manifold without conjugate points (result by Keeler  [Keeler]):
   \begin{equation} 
\delta_{[0,\ell]}^M=O\left( \frac{1}{\ell\log(\ell)}\right)
    \end{equation} 
in constant range $\rho_\ell=\frac12 \mathrm{inj}(M,g)$, where $\mathrm{inj}(M,g)>0$ is the injectivity radius.
\item If $M=\mathbb{R}^n$, then (obviously, and by (lem:euclidWeyl of the paper))
\begin{equation} 
\delta_{[0,\ell]}^{\mathbb{R}^n}=0,
\end{equation} 
in any range $\rho$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 6 of arXiv:2609.03777, '2609.03777'] Let $k=k_1+\cdots+k_r$, where $k_1\geq3$ and $k_2,\dots,k_r\geq2$.  Then
\begin{align}
\tau_N^{k}G_{k_1,\dots,k_r}(\tau_N)
=G^{(N)}_{k_1,\dots,k_r}(\tau)\,.
\end{align}

