[Definition 27 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] We introduce the following notions:
\begin{enumerate}
\item We say that a path $Y \in \calc^{\alpha}([0,T],\bar{W})$ is \emph{controlled} by $X$ if there exists $Y' \in \calc^{\alpha}([0,T], L(V,\bar{W}))$ such that for the remainder term $R^Y : [0,T]^2 \to \bar{W}$ given by
\begin{align}
R_{s,t}^Y := Y_{s,t} - Y_s' X_{s,t} \quad \text{for all $s,t \in [0,T]$}
\end{align}
we have $R^Y \in \calc_2^{2 \alpha}([0,T]^2,\bar{W})$.

\item This defines the space of \emph{controlled rough paths}, and we write
\begin{align*}
(Y,Y') \in \scrd_X^{2 \alpha}([0,T], \bar{W}).
\end{align*}
\item We call $Y'$ a \emph{Gubinelli derivative} of $Y$ (with respect to $X$).
\end{enumerate}

[Definition HN' of arXiv:2505.11721, 'Variational principles for Hausdorff and packing dimensions of fractal percolation on self'] Recall the notations of Definition~(HN of the paper), all associated with a fixed $\boldsymbol{p}\in P_{\mathcal I}^{\mathbb{N}^+}$. If $\boldsymbol{q}\in P_{\mathcal I}^{\mathbb{N}^+}$, for $N\ge 1$, define
\begin{align*}
H_{N,k}^{\boldsymbol{p}}(\boldsymbol{q})=\sum_{n=1}^k H({W_{\boldsymbol{q}}^{(n)}})+\sum_{n=k+1}^{g_s(N)} h(\Pi_{r_n}q^{(n)})\quad (0\le k\le g_s(N)),
\end{align*}
where $r_n$ is the index $r$ such that $g_{r-1}(N)+1\le n\le g_{r}(N)$. 

Also, set 
\begin{align*}
d^{\boldsymbol{p}}_N(\boldsymbol{q})&=\frac{1}{N}\min \Big (\min_{g_1(N)\le k\le  g_s(N)-1} H^{\boldsymbol{p}}_{N,k}(\boldsymbol{q}),\min_{N'\ge g_s(N)} \sum_{n=1}^{N'} H(W_{\boldsymbol{q}}^{(n)})\Big )\\
\text{and}\quad
\widetilde d^{\boldsymbol{p}}_N(\boldsymbol{q})&=\frac{1}{N}\min_{g_1(N)\le k\le  g_s(N)} H^{\boldsymbol{p}}_{N,k}(\boldsymbol{q}).
\end{align*}
In particular, $d_N(\boldsymbol{p})$ and $\widetilde d_N(\boldsymbol{p})$ equal $d^{\boldsymbol{p}}_N(\boldsymbol{p})$ and $\widetilde d^{\boldsymbol{p}}_N(\boldsymbol{p})$ respectively.

[Thm replacement of arXiv:2607.28817, 'Limiting spectral distribution for the adjacency matrix of the Watts--Strogatz random grap'] Let $(A_n)_{n\ge1}$, $(B_n)_{n\ge1}$, $(X_n)_{n\ge1}$, and $(Y_n)_{n\ge1}$ be sequences of $n \times n$ real symmetric matrices, where $A_n$ is a deterministic sparsity profile, $B_n$ is deterministic, and $X_n$ and $Y_n$ are both inhomogeneous Wigner matrices.  
    Let $(K_n)_{n\ge1}$ be a sequence of positive real numbers. 
    Assume:
    \begin{enumerate}
        \item (Moment matching) For each $n \geq 1$, $X_n$ and $Y_n$ match moments per Definition (def:moments of the paper).
        \item (Sparsity profile) We have
        \begin{equation} 
            \limsup_{n \to \infty} \frac{1}{n K_n} \sum_{1 \leq i < j \leq n} (A_n)_{ij} \left( \mathbb{E} |(X_n)_{ij}|^2 + \mathbb{E}  |(Y_n)_{ij}|^2 \right) < \infty.
        \end{equation}
        \item (Lindeberg's condition) For every $\varepsilon > 0$
        \begin{equation} 
            \lim_{n \to \infty} \left[ \frac{1}{nK_n} \sum_{1 \leq i \leq j \leq n} (A_n)_{ij} \left( \mathbb{E} \left[ (X_n)_{ij}^2 \chi_{\{|(X_n)_{ij}| > \varepsilon \sqrt{K_n}\} } \right] + \mathbb{E} \left[ (Y_n)_{ij}^2 \chi_{\{|(Y_n)_{ij}| > \varepsilon \sqrt{K_n}\} } \right] \right) \right] = 0,
        \end{equation}
        where $\chi_E$ denotes the indicator function of the event $E$. 
    \end{enumerate}
    Then 
    \[ \mu_{\frac{1}{\sqrt{K_n}} A_n \odot X_n + B_n} - \mu_{\frac{1}{\sqrt{K_n}} A_n \odot Y_n + B_n} \;\xrightarrow[n\to\infty]{}\; 0 \qquad\mbox{ weakly in probability}.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def 23 (Sub-local group) of arXiv:2608.30990, 'Convergence of symmetries: nilpotency, dimension, and perfectness'] Given a local group $G$, a symmetric subset $H \subset G$ is called a \emph{sub-local group} if there is an open symmetric set $V \subset G$  such that 
\begin{itemize}
    \item $H \subset V$ and $H$ is closed in $V$.
    \item Whenever $h_1, h_2 \in H$ and $h_1  h_2 \in V$, one has $h_1 h_2 \in H$.
\end{itemize}
In such a case, $V$ is called an \emph{associated neighborhood} for $H$.

[Corollary coro_subharmonic of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, $N\ge 1$, $x\in \mathbb{Z}^d\setminus B(3N)$ and $D\subset \widetilde{\mathbb{Z}}^d$, 
		\begin{equation}
		\widetilde{\mathbb{P}}^{D}\big(x\xleftrightarrow{\ge 0} B(N) \big)
		\lesssim  |x|^{2-d} N^{[(\frac{d}{2}-1)\boxdot  (d-4)]+\varsigma_d(N)}. 
	\end{equation}

