[Defn whitenoise of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] A family of random elements $(W(t))_{t\in[0,T]}$, $W(t):\Omega\rightarrow X$, is called a Wiener process if
\begin{itemize}
\item $W(0)=0$ almost surely (a.s.);
\item $W(t_{i+1})-W(t_{i}) (i=0,1,\ldots, n-1)$ are independent random elements for every $0\leq t_{0}<t_{1}<\cdots t_{n}\leq T$;
\item for every $t\in [0,T]$, $W(t)$ is a Gaussian random element with mean zero and covariance operator $tQ$, where $Q:X^{\ast}\rightarrow X$ is a fixed Gaussian covariance.
\end{itemize}

[Lemma lem:DDapprox of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] (An Approximation for Donsker's Delta) For all $x\in (0,1)$ it holds that
	\begin{equation}
		L_+^2(\mathcal{S}'(\mathbb{R}), \mu) \mathrel{\reflectbox{$\in$}} \gamma_{\varepsilon}(\beta_x) \xrightarrow{\varepsilon \downarrow 0} \delta_0(\beta_x) \;\,\text{in $(\mathcal{S})'$},
	\end{equation}
	and for all $\varepsilon >0$, $x\in (0,1)$ and $\varphi \in \mathcal{S}(\mathbb{R})$ it holds
	\begin{align*}
		&\mathrm{T}(\gamma_{\varepsilon}(\langle q_x, \cdot \rangle))(\varphi)
		= \frac{1}{\sqrt{2\pi (x(1-x)+\varepsilon)}}\\
		&\quad\quad\quad \cdot\exp\left( -\frac{1}{2}\int_{\mathbb{R}}\varphi^2ds + \left(\frac{1}{2x(1-x)}-\frac{\varepsilon}{2(x(1-x)+\varepsilon)}\right) \left(\int_{\mathbb{R}} q_x \varphi ds\right)^2\right),
	\end{align*}
	and further, for all $z\in\mathbb{C}$, we have
	the bound
	\begin{equation}
		|\mathrm{T}(\gamma_{\varepsilon}(\langle q_x, \cdot \rangle))(z\varphi)|\leq \frac{1}{\sqrt{2\pi x(1-x)}}\exp\left(\frac{3}{2}|z|^2\|\varphi\|_{L^2(\mathbb{R})}^2\right).
	\end{equation}

[Definition 18 of arXiv:2609.00736, 'Modalities in non-classical variations of S4'] Let $\mgsf = \tuple{W, W^\bot, \preceq, \R, V}$ be defined as follows.
    Set $W := \{a\} \cup \{b_i \mid i\in\omega\} \cup \{c_i \mid i\in\omega\}$ and $W^\bot := \emptyset$.
    We have $w\preceq v$ iff one of the following holds:
    \begin{itemize}
        \item $w = v$; or
        \item $w = c_i$ and $v = b_i$.
    \end{itemize}
    We have $w\sqsubseteq v$ iff one of the following holds:
    \begin{itemize}
        \item $w = v$;
        \item $w = b_i$ and $v = a$;
        \item $w = b_i$, $v = b_j$, and $j\leq i$; or
        \item $w = b_i$, $v = c_j$, and $j < i$.
    \end{itemize}
    At last, set $V(P) := \{w\}$.

