body:
[Theorem thm: continuum Z introduction of arXiv:2602.04429, 'Disordered systems and (subcritical) polynomial chaos\\ with heavy-tail disorder'] Let \(\boldsymbol\zeta\) be a \(\gamma\)-stable Lévy white noise with \(\gamma \in (1,2)\).
Assume that there is some \(q\in (\gamma,2]\) such that for every $C \, \geqslant\, 0$,
\begin{equation}

	\sum_{k\geq 1} C^k \|\boldsymbol\psi^{(k)}\|_{q} <+\infty \,,
\end{equation}
where \(\|\cdot\|_{q}\) denotes the symmetric \(L^q \)-norm (see its definition (equation eq: def of symmetric norms of the paper) below).
Then, the continuum partition function 
\begin{equation}

	{\ensuremath{\mathcal Z}}_{\Omega}^{\boldsymbol\zeta,\hat{\beta}} = 1 + \sum\limits_{k \, \geqslant\, 1} \frac{\hat{\beta}^k}{k!} \int_{\Omega^k} \boldsymbol\psi^{(k)}(x_1,\dots,x_k) \prod\limits_{j=1}^k \boldsymbol\zeta(\mathrm{d} x_j)
\end{equation}
is a well-defined (and non-degenerate) \(\boldsymbol\zeta\)-measurable random variable in \(\mathbb{L}^p\) for every $ p \in [0,\gamma) $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] Let $\kappa\geq \kappa_c$. For a finite subset of vertices $F$,
\begin{equation}
    \mu_\kappa(\ell : \ell \cap F \neq \emptyset)
    =
    \log \det\big( G^\kappa|_{F} \big),
\end{equation}
where $G^\kappa$ is the Green function viewed as a matrix $(G^\kappa(x,y))_{x,y}$, and $G^\kappa|_{F}$ is its submatrix indexed by $F \times F$.
In particular, for $n$ distinct vertices $v_1, \ldots, v_n$,
\begin{equation}
    \mu_\kappa\big( \ell : v_i \in \ell \text{ for } i \in \{1,\ldots,n\} \big)
    =
    \sum_{\substack{A \subset \{v_1,\ldots,v_n\} \\ A \neq \emptyset}}
    (-1)^{\# A + 1}
    \log \det\big( G^\kappa|_{A} \big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2608.24352, 'Second moments associated with finite free multiplicative convolution'] \cite[Theorem 6.2.3, Remark 6.2.4] {ceccherini1945harmonic}
	Let $0\leq h\leq \min(k,l)$ and $\lambda = (k+l-h,h)$. Let $I$ be a $k$-element subset of $[k+l]$. Write $\delta_{I,x}$ for the function on $S_{k+l}$ whose value on $\sigma \in S_{k+l}$ is 1 if $|\sigma(I) \cap I| = k-x$ and 0 otherwise. The spherical function $\omega_h$ associated to the irreducible representation of $S_{k+l}$ indexed by the partition $\lambda$ 
	\begin{equation*}
		\omega_h = \sum_{x=0}^{\min(k,l)} Q_h(x;l,k) \delta_{I,x},
	\end{equation*}
	where the $Q_h(x;l,k)$ are a family of orthogonal polynomials known as {\rm Hahn polynomials}. (Proof in the paper; no proof environment follows the statement in the TeX.)

