&= \sum_{x=z}^{\infty} \p(X=x)\p(T_{a}(X)=z \mid X=x) \\
&= \sum_{x=z}^{\infty} f(x) T^{x} e^{-T}
    \frac{1}{z!(x-z)!}a^{z}(1-a)^{x-z} \\
&= \frac{(aT)^{z}}{z!} e^{-aT}
    \sum_{x=z}^{\infty}
    f(x)\frac{(T(1-a))^{x-z}}{(x-z)!}
    e^{-T(1-a)} \\
&= \frac{(aT)^{z}}{z!} e^{-aT}
    \sum_{x=0}^{\infty}
    f(x+z)\frac{(T(1-a))^{x}}{x!}
    e^{-T(1-a)} \\
&= P_{T(1-a)}f(z)\,\pi_{aT}(z).
\end{align*}
Observe that when $a=0,$ the random variable $T_{a}(X) = 0 $ with probability $1.$ This agrees with the measure $P_{T}f \pi_{0},$ as $\pi_{0}$ is the Dirac mass at $0$ and","release_manifest_digest":"sha256:d5d2eb6782dee30a27c2670c025a509127242780a853979032d2959b247b78d7","revision_digest":"sha256:c618751740b4af3599f5522bcc2aa5cfba69ac0a556c14db4860c6bb6b358839","source_id":"arxiv:2608.02927","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

