[Definition 2.7 of arXiv:2609.03926, 'Overcolored Partition $k$-tuples Restricted by Parity of the Parts'] {wom}}}]
	Let $m$ be a positive integer and $f(z) = \sum_{n=0}^ \infty a(n)q^n \in  M_k(\Gamma_0(N), \chi ).$ The Hecke operator $T_m$ acts on $f(z)$ by 
	\begin{align}
		f(z)\mid {T_m} := \sum_{n=0}^\infty \bigg( \sum_{d\mid gcd(n,m)} \chi (d) d^{k-1}a \bigg(\frac{nm}{d^2} \bigg) \bigg)q^n.
	\end{align}
	In particular, if $m=p$ is a prime, then 
	\begin{align}
		f(z)\mid {T_p} := \sum_{n=0}^\infty \bigg( a(pn)+ \chi (p) p^{k-1}a \bigg(\frac{n}{p} \bigg) \bigg)q^n.
	\end{align}
	We adopt the convention that $a(n/p)=0$ whenever $p\nmid n$.

[Lemma D:bd of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Under (equation alphaH=3/2 of the paper),
    \begin{align}
        &\|\mathscr{D}(z)-\mathscr{D}(z')\|_2 \lesssim \sqrt{|z-z'|}  \quad \text{and} \quad 
        \|\mathscr{D}(z)\|_2 \lesssim \sqrt{z}
    \end{align}
    uniformly for all $z,z'\ge 1$, and
    \begin{align}
        &\|\mathscr{E}_n(h)-\mathscr{E}_n(h')\|_2 \lesssim \varphi_2(|h-h'|) \quad \text{and} \quad 
        \|\mathscr{E}_n(h)\|_2 \lesssim e^{-n}
    \end{align}
    uniformly for all $n \ge 1$ and $|h|, |h'| \le e^{-n}$.

[Proposition prop:functional-upper-inclusion of arXiv:2606.21006, 'Law of the Iterated Logarithm for Weighted Sums of Functionals of Long-Memory Gaussian Seq'] Let the assumptions of Theorem~(thm:functional-nonlinear-lil of the paper) hold. Then the sequence
\[
    \left\{
        \frac{\mathcal S_{n,m}(\cdot)}
        {A_n(2\log\log n)^{m/2}}
        : n\ge3
    \right\}
\]
is almost surely relatively compact in \(C[0,T]\), and every cluster point belongs to
\(\mathcal K_T\).

[Definition 20 (Discrepancy~\citep{marx2020predictive}) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] The discrepancy of $\emprashomonset$, at a test instance x, is the fraction of conflicting predictions of models in $\emprashomonset$ w.r.t. a reference model and is defined as,
\begin{align}
     \disagens(x) =  \frac{1}{\abs{\emprashomonset}}\sum_{h_k \in  \emprashomonset}\Indic{h_k(x) \ne h_0(x)},
\end{align}
where we choose the reference model as $h_{0}(x) = \Indic{\frac{1}{\abs{\emprashomonset}}\sum_{f_k \in  \emprashomonset}f_k(x) \ge \frac{1}{2}}$.

[Theorem thm:KS of arXiv:2510.13572, 'Coalescence in Markov chains'] Let $P=(p_{i,j}:i,j\in S)$.
Let $\mathcal S$ be a partition of $S$, and let
\begin{equation}
\lambda_{r,s}^{(i)}= \sum_{j \in S_s} p_{i,j}, \quad i \in S_r.
\end{equation}
A Markov chain $X$ with transition matrix $P$ 

 is $\mathcal S$-lumpable if and only if, 
\begin{equation}
\text{for every $r$, $s$, we have that $\lambda_{r,s} := \lambda_{r,s}^{(i)}$ is constant 
for $i\in S_r$.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

