[Defstar def:accessibility of arXiv:2605.06488, 'Continuous-state branching processes with L\'evy-Khintchine drift-interaction: Laplace dua'] \
\begin{enumerate}
\item \textbf{Accessibility.} The boundary $\Delta\in \{0,\infty\}$ is said to be accessible if $$\forall x\in (0,\infty), \ \mathbb{P}_x(\exists t\geq 0: X_t=\Delta)>0.$$ 
\item \textbf{Absorption.} The boundary $\Delta\in \{0,\infty\}$ is absorbing if $$\mathbb{P}_{\Delta}(\exists t\geq 0: X_t\neq \Delta)=0.$$ 
\end{enumerate}

[Lemma bounds on cL of arXiv:2605.19894, 'Sharp Spectral Thresholds for Multi-View Spiked Wigner Models'] Uniformly over $z\in\CC^+$, the following bounds hold:
    \begin{itemize}
        \item[(i)] The solution and its inverse satisfy
        \begin{align}
            \nbr{M(z;\Gamma)} &\le \frac{C(B,\Gamma)}{\mathrm{dist}\rbr{z,\supp \mu_{\Gamma}}}, \\
            \nbr{M(z;\Gamma)^{-1}} &\le C(B,\lambda,\Gamma)\rbr{1+\abr{z}+\nbr{M(z;\Gamma)}}. 
        \end{align}

        \item[(ii)] The inverse of the stability operator satisfies
        \begin{equation}
            \nbr{\cL_z^{-1}} \le C(B,\lambda,\Gamma) \frac{\nbr{M(z;\Gamma)}\nbr{M(z;\Gamma)^{-1}}^{9}}{\mathrm{dist}\rbr{z,\supp \mu_{\Gamma}}^8}.
        \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2609.01142, 'Lagrangian Foliations on compact K\"ahler manifolds'] We have 
\begin{itemize}
\item[i)]  $g(R(X,Y)Z,V) = 0$ for $X,Y,Z\in \Gamma(\cH),\ V\in\Gamma(\cV)$;
\item[ii)] for every $U,V\in\Gamma(\cV)$ we have $R(U,V)(\cV)\subseteq \cV$ and 
\beqR(U,V)|_{\mathcal V} = [T_U,T_V] = - [B_U,B_V]\eeq
\item[iii)] for $X,Y\in \Gamma(\cH)$ and $U,V\in\Gamma(\cV)$ we have
\begin{equation}
g(R(X,U)V,Y)
=
g((\bar\nabla_XT)_UV,Y)
+g(T_{T_UX}V,Y);
\end{equation}
\item[iv)] the leaves of $\mathcal F$ are flat.
\end{itemize}

[Lem 7 of arXiv:2506.19008, 'Sprinkled Decoupling for Hammersley's Process'] Let $\lambda<\lambda'$ and assume that $\epsilon\df\left(\lambda^{-2}-\lambda'^{-2}\right)\in\left(0,\frac{3}{2}\lambda'^{-2}\right)$.  Under the basic coupling $(\eta^{\lambda},\eta^{\lambda'})$, with $\eta_0^{\lambda}$ independent of  $\eta_0^{\lambda'}$, we have that $\eta^{\lambda'}$ is independent of $\eta^{\lambda}_0$. Furthermore, for all $a\geq b$ and $s\geq 0$ we have that 
$$\P\left[\forall\,u\in[t,t+s]\,,\,\forall\,(x,y]\subseteq(a,b]\,,\,\eta^{\lambda}_u((x,y])\leq\eta^{\lambda'}_u((x,y]) \right]\geq 1- 10 e^{-\frac{c_0\lambda^7}{4^4}\epsilon^4 t}\,,$$
for all $t>4\epsilon^{-1}\left(b-a+s\lambda^{-2}\right)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:uprho-bound-p of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] Fix $1 < p < 2$, and $n \geq 0$. There exists a constant $\delta_p > 0$ such that
        \begin{align}

         \frac{\upxi^{(p)}_n}{{\widehat\pi}^{(p)}_\infty(\phi_o > H+1-n)} &\in [1 - L^{-\delta_p+o(1)},  1 -L^{-1/2+\delta_p+o(1)}]\,,\\

        \uprho^{(p)}_n &\in [1 - L^{-\delta_p+o(1)},  1 -L^{-1/2+\delta_p+o(1)}]\,.
        \end{align}
        For $p > 2$, there exists $c_0(\beta), c_1(\beta) > 0$ such that
        \begin{align}

         \frac{\upxi^{(p)}_n}{{\widehat\pi}^{(p)}_\infty(\phi_o > H+1-n)} &\in [1 - e^{-c_0(\beta) \sqrt{\log L}^{\frac{p}{p-1}}},  1 - e^{-c_1(\beta) \sqrt{\log L}^{\frac{p}{p-1}}}]\,,\\

        \uprho^{(p)}_n &\in [1-e^{-c_0(\beta) \sqrt{\log L}^{\frac{p}{p-1}}},  1 + L^{-1+o(1)}]\,.
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 46 of arXiv:2512.00213, 'On strong sharp phase transition in the random connection model'] Let $t\in\R_+$. Then
    \begin{align*}
        \lim_{\gamma \to 0}\widebar{M}(t,\gamma) = \bar\theta(t), \quad
        \lim_{\gamma \to 0}\bar{c}(t,\gamma) = \bar{c}_{f}(t).
    \end{align*}

[Thm moment theorem 1_intro of arXiv:2505.11700, 'Distribution of the cokernels of determinantal row-sparse matrices'] (Theorem (thm: moment theorem 1 of the paper)) Let $G$ be a finite abelian group. Assume that a sequence $(k_n)_{n=1}^{\infty}$ satisfies the following:
\begin{enumerate}
    \item $\gcd(|G|, k_n)=1$ for all sufficiently large $n$;
    \item for every $\epsilon>0$, $k_n < n^{\epsilon}$ for all sufficiently large $n$;
    \item if $|G|$ is even, then for every $\delta>0$, $\delta \log\log n < k_n$ for all sufficiently large $n$.
\end{enumerate}
Then
\begin{equation}

\lim_{n\to \infty} \mathbb{E}(\# \mathrm{Sur}(\mathrm{cok}(A_n), G)) = 1.     
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

