[Lemma 29 (Resolvent invariance of spectral directions) of arXiv:2608.15805, 'Spectral duality structures and the Fisher--Rao geometry of reset distributions'] Assume the active eigenvalues $\{\lambda_k : P_k\xi\neq 0\}$ are
pairwise distinct. Then
\begin{equation}
\operatorname{span}\{R(\tau)\xi : \tau\in J\}
= \bigoplus_{k:\,P_k\xi\neq 0}\operatorname{span}\{P_k\xi\}.

\end{equation}
The conclusion is unchanged if $R(\tau)$ is multiplied by any
nowhere-vanishing scalar function of $\tau$, since each individual
vector $R(\tau)\xi$ is then merely rescaled by a nonzero scalar.

[Lemma lem:scalar-powers-app of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] Let \(x,y>0\) and \(0<\sigma\leq1\). Then
\begin{equation}
 (x-y)(x^\sigma-y^\sigma)\geq0.
\end{equation}
Moreover,
\begin{equation}
 \left(\frac yx-1\right)(y^\sigma-x^\sigma)
 \geq x^{-\sigma}|y^\sigma-x^\sigma|^2.
\end{equation}
Finally, if \(0<s\leq\sigma/2\) and \(0<x\leq1\), then
\begin{equation}
 0\leq
 \frac{s+\sigma/2}{s}(1-x^s)
 \leq x^{-\sigma/2}.
\end{equation}

[Lem 7 (Lemma 4.1.1 in \cite{exact}) of arXiv:2604.01748, 'Largest-loop-first loop-erased random walk on $\mathbb{Z}^{4}$'] Suppose that $\phi (n)$ satisfies the following two conditions (A1) and (A2).
\begin{itemize}
   \item[(A1)] $\phi (n)$ is slowly varying.
    \item[(A2)] For all $\epsilon \in (0,1)$ there exists $N = N_{\epsilon}$ such that for every $n \ge N$ we have 
    \begin{equation}
     \phi (2n) \le \phi (n) \Big\{ 1 - \frac{\log 2}{2 \log n} (1 - \epsilon ) \Big\}. 
     \end{equation}
\end{itemize}
    Then for all $\epsilon \in (0,1)$ we have 
    $$ \limsup_{n \to \infty} \, (\log n)^{\frac{1}{2} - \epsilon} \phi (n) = 0. $$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 (Regularity of $\psi_\circ$) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] The function $\psi_\circ$ given in~\eqref{e.psi_single=} can be extended to $\mcl Q_1$ and satisfies
\begin{align*}
    \Ll|\psi_\circ(q)-\psi_\circ(q')\Rr|\leq |q-q'|_{L^1},\quad\forall q,q'\in\mcl Q_1.
\end{align*}
The restriction $\psi_\circ:\mcl Q_2\to\R$ is Gateaux differentiable everywhere; we denote its Gateaux derivative by $\dr_q \psi_\circ(q) = \dr_q \psi_\circ(q, \cdot) \in L^2([0,1])$. We have, for every $q \in \mcl Q_2$,
\begin{equation}

\partial_q\psi_\circ(q) \in \mcl Q_{\infty,\leq 1},
\end{equation}
and, for every $q \in \mcl Q_\infty$ and $\pi \in L^2([0,1]; \R)$,  \begin{equation*}
\la \pi,\dr_q \psi_\circ(q)\ra_{L^2} = \E \la \pi \Ll(\alpha\wedge\alpha'\Rr)\tau\tau'\ra_{q}
\end{equation*}
where $\la\cdot\ra_q \propto  \exp\Ll(\sqrt{2}w^q(\alpha)\cdot \tau-q(1) \tau\tau\Rr)\d \fR(\alpha) \d P_{\{-1,1\}}(\tau)$, and $(\tau',\al')$ denotes an inpendent copy of the canonical random variable $(\tau,\al)$ under $\la \cdot \ra_q$.
Moreover, for every $r \in [1,+\infty]$ and $q, q' \in \mcl Q_2$ with $q-q' \in L^r$, we have
\begin{equation}

\Ll|\dr_q \psi_\circ(q) -\dr_q \psi_\circ(q')\Rr|_{L^r}\leq 16\Ll|q-q'\Rr|_{L^r}.
\end{equation}
In particular, the mapping $q \mapsto \dr_q \psi_\circ(q)$ can be extended to $\mcl Q_1$ by continuity, and the properties in \eqref{e.bound.der.psi} and \eqref{e.continuity.der.psi} remain valid with $q, q' \in \mcl Q_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:time-reversed of arXiv:2507.12502, 'Quantitative Edge Eigenvector Universality for Random Regular Graphs: Berry-Esseen Bounds '] The backward evolution of the overlap process from time $t_*$ to 0 satisfies the time-reversed SDE: for $s \in [0, t_*]$,
\begin{equation}
\mathrm{d} X_i^{(\mathbf{q})}(t_*-s) = -b_i(X(t_*-s)) \mathrm{d} s + \sum_{j=2}^{K+1} \frac{\partial}{\partial X_j}[\Sigma\Sigma^{*}]_{ij}(X(t_*-s)) \mathrm{d} s + \sigma_{ij}(X(t_*-s)) \mathrm{d} \tilde{B}_j(s)
\end{equation}
where $\tilde{B}_j(s)$ are independent Brownian motions and the second term is the Itô correction arising from time reversal.

[Definition 4 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let $(t, \mathbf{x}, \mathbf{z}, \mathsf{m}^\star, \mathsf{n}^\star, \mathsf{z}^{m,\star}, \mathsf{z}^{n,\star}) \in [0,T] \times \cC_{m \times N} \times (\R^{d \times N})^N \times \R^N \times \R^N \times (\R^{d \times N})^N \times (\R^{d \times N})^N$. A vector $\mathbf{a}^N \coloneqq (a^{1,N},\ldots,a^{N,N})\in A^N$ is said to be a fixed-point of the Hamiltonian $H^N$ if, for any $i \in \{1,\ldots,N\}$, it holds that
\begin{align*}
a^{i,N} \in \argmax_{a \in A} \big\{H^{i,N}_t\big(\mathbf{x},\mathbf{z}^i,\mathsf{m}^{i,\star},\mathsf{n}^{i,\star},\mathsf{z}^{i,m,\star},\mathsf{z}^{i,n,\star},a,\mathbf{a}^N\big)\big\}.
\end{align*}
We denote the set of such fixed-points by $\cO_{N}(t, \mathbf{x}, \mathbf{z}, \mathsf{m}^\star, \mathsf{n}^\star, \mathsf{z}^{m,\star}, \mathsf{z}^{n,\star})$.

