[Proposition 13 of arXiv:2609.03455, '2609.03455'] The curve attached to $\Gtwo\cap\G_1(7)$ has model
\begin{equation}
 C_2: \ 
 W^2=X(X-1)(X^3-8X^2+5X+1),
\end{equation}
and genus $2$.

[Theorem thm-slow-ordering-sub-critical of arXiv:2607.22324, 'The conclave process'] {}
    For any $0<\alpha<1$ and $M \in \mathbb Z_{>0}$, there exists $C_{(thm-slow-ordering-sub-critical of the paper)}=C_{(thm-slow-ordering-sub-critical of the paper)}(\alpha)>0$ such that
    \begin{equation}{}
  	    \mathbb{P}_n^{\alpha}\big( \mathcal{T} > M \big) \ge \big(1-e^{-C_{(thm-slow-ordering-sub-critical of the paper)}n} \big)^{M} \,. 
    \end{equation}  
    As a result, $\mathcal{T}$ is at least $\exp(\Omega_{\alpha}(n))$ with probability $1-o(1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma prop_cons_of_energy of arXiv:2603.26307, '\LARGE The incompressible Navier--Stokes--Fourier system with thermal noise'] Let Assumption (Ass:noise of the paper) hold, $(\Omega,\mathfrak{A},\mathbb{P})$ be a probability space equipped with a filtration $\mathscr{F}$ satisfying the usual conditions and $3$-dimensional standard $\mathscr{F}$-Brownian motions $(W_n)_{n\in \mathbb{Z}^3}$ and $3\times 3$-matrix valued $\mathscr{F}$-Brownian motions $(B_n)_{n\in \mathbb{Z}^3}$ with covariance structure (equation Eq_noise_matrix_covariation of the paper) be independent. Then, any local strong solution $(U,\Psi)$ to (equation Eq_new_var of the paper), defined up to a stopping time $\tau>0$, satisfies 
	\begin{equation}
		\frac{1}{2}\int_{\mathbb{T}^3}   |U_t|^2 + |\Psi_t |^2\,\mathrm{d} x \,=\, 	\frac{1}{2}\int_{\mathbb{T}^3}   |U_0|^2 + |\Psi_0 |^2\,\mathrm{d} x,
	\end{equation}
	for all $t\in [0,\tau)$, $\mathbb{P}$-almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] Let $1 \leqslant \rho < 2$. The covariance function $\phi$ is said to have \textit{finite (2D) $\rho$-variation} if
\begin{equation*}
    V_{\rho}(R;[0,T]\times[0,T])^{\rho} 
    := \sup_{\mathcal{D},\mathcal{D}'} 
    \sum_{\substack{[s,t]\in \mathcal{D} \\ [u,v]\in \mathcal{D}'}} 
    \big| R \left(s,t;v,u\right) \big|^{\rho} < \infty,
\end{equation*}
where $R \left(s,t;v,u\right):=\mathbb{E}[(Z_t-Z_s)(Z_u-Z_v)]$ and $\mathcal{D},\mathcal{D}'$ are any finite partitions of $[0,T]$. The function $\phi$ is said to have \textit{finite (2D) H\"older-controlled $\rho$-variation}, if there exists $C>0$ such that 
$$
V_\rho(R;[s,t] \times [s,t]) \leqslant C (t-s)^{1/\rho}
$$for all $0 \leqslant s \leqslant t \leqslant T$.

[Theorem thm:main-comp of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] Let $\Omega$ be a bounded simple convex polygon satisfying (equation eq:strict-convexity of the paper). Choose the parameters in the order specified in Section~(subsec:parameters-data of the paper), fix the lifting normalization of Section~(subsec:harmonic-lifts-comp of the paper) and the cutoffs, extensions and length scales of Section~(sec:matching-realization of the paper), and suppose the inflow satisfies Assumption~(ass:primitive-data-comp of the paper). Let $U_{\mathrm{app}}^{\varepsilon,[N]}(\delta_\varepsilon)$ be the composite (equation eq:forward-composite-definition of the paper) formed from those choices. There are $\varepsilon_0>0$ and $C>0$, depending only on the polygon, on those choices and on the data norms of Assumption~(ass:primitive-data-comp of the paper), and not on $\varepsilon$, such that the unique bounded mild solution $u^\varepsilon$ of (equation eq:physical-model of the paper), given by Lemma~(lem:physical-wellposed-comp of the paper), satisfies
\begin{align}
 \nm{u^\varepsilon-U_{\mathrm{app}}^{\varepsilon,[N]}(\delta_\varepsilon)}_\infty
 \le C\Lambda_\varepsilon\left[
 \varepsilon^{q_\ast}+\varepsilon^{(1-a_\ast)N-1-a_\ast}+\varepsilon^{T-2}\right]
 +C\varepsilon^3.

\end{align}
Therefore, for every $0<q<q_\ast$ there is $C_q$ with
\begin{align}
 \nm{u^\varepsilon-U_{\mathrm{app}}^{\varepsilon,[N]}(\delta_\varepsilon)}_\infty
 \le C_q\varepsilon^q.

\end{align}
The leading scalar interior solution is the ordinary weak solution of
\begin{align}
 \Delta\rho_0=0\quad\text{in }\Omega,
 \qquad
 \rho_0\big|_{E_j}=\mathcal E_{\mu_j}(g_{j,0}(s,\cdot),0).

\end{align}
Here the end-state operator is defined in (equation eq:milne-maps-comp of the paper). For every compact $K_0\Subset\Omega$,
\begin{align}
 \nm{u^\varepsilon-\rho_0}_{L^\infty(K_0\times\mathbb S^1)}\rightarrow0
 \quad \text{as }\varepsilon\to0.

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] Let $T<\infty$. For every $t\in[0,T]$ the map $x\mapsto V_T(t,x)$ is $\llip{(0,1)}$. Specifically, for the optimal stopping time $\tau^* :=\tau^*_T(t,x)$, 
    \begin{equation}
        \partial_x V_T(t,x)=\mathbb{E}\left[g'(X^x_{\tau^*})\partial_x X^x_{\tau^*}\right],
    \end{equation}
    for almost every $x\in(0,1)$. In particular, for $x,y\in[a,b]\subset(0,1)$,
    \begin{equation}
        |V_T(t,x)-V_T(t,y)|\leq K_\text{space}|x-y|,
    \end{equation}
    where $K_\text{space}:=\|g'\|_\infty$ under Assumption \ref{asmp:bounded:g'}, and there exists an interval $[A,B]\subset(0,1)$ independent of $t$ and $T$ such that $K_\text{space}:=\|g'\|_{L^\infty([a,b]\cup[A,B])}<\infty$ if Assumption \ref{asmp:bounded:c} holds.

[Definition 9 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] The \emph{white noise truncation} $h_{\ell}$ of the augmented field $h$ is defined by the centered Gaussian field
	\begin{align}
		h_{\ell}(x) := & \int_{M\setminus B_{1/\ell}(x)}{ g}(x,y)d W(y), \quad x \in M.
	\end{align}	
	The correlation function is given by 
	\begin{align}
		k_{\ell}(x,y):=\E[h_{\ell}(x)h_{\ell}(y)]=\int_{M\setminus(B_{1/\ell}(x)\cup B_{1/\ell}(y))}{ g}(x,z) { g}(y,z)\,d\vol(z)\ge0.
	\end{align}

[Proposition 7 of arXiv:2609.03847, 'A counterexample to McKean's conjecture for the Landau-Coulomb equation'] The functional $\delta_{f_R}$ for $f_R$ defined in~\eqref{def:fR}  has the expansion
	\begin{equation}
		\delta_{f_R}(v)	=\lp \delta_{R,1} +\delta_{R,2} +\delta_{R,3} +  \delta_{R,4}\rp (v/R)  
		+	\mc E_R^\delta(v) \qquad \text{for all $ v \in \Omega_R^{\rm out}$},
	\end{equation}
where
\begin{align}
		\delta_{R,1}	=\frac{2}{R|\cdot|},
		\qquad	\delta_{R,2}	=\frac{8}{R^3|\cdot|}\beta,
		\qquad	\delta_{R,3} 	=\frac{8}{R^5|\cdot|}\beta^2, \qquad \delta_{R,4} = R^{-K-3}\delta_G ,
\end{align}
and $\beta (y) \coloneq |y|^{-4} -1$.

For every $N\geq0$, there exist constants $c,C_N>0$ such that, for all sufficiently large $R$,
	\begin{equation}
		\int_{\Omega_R^{\rm out}}	g_R(v)\langle v \rangle^N
		\lp	|\mathcal E_R^\delta(v)|	+	|\mathcal E_R^\delta(v)|^2 \rp \d v
		\leq
		C_N \exp \lp -cR^{\frac45} \rp.
	\end{equation}

