[Theorem thm:R1c of arXiv:2509.17319, 'Non-directed polymers in random environments with range penalties: the high-dimensional ca'] Let $\alpha\in(0,\frac{d}{2})$ and $(\zeta,\gamma)\in R_1$ (see Figure (diagram3 of the paper)). Then $(S_n)_{0\leq n \leq N}$ has end-to-end fluctuations of order $N^{\xi}$ under ${\ensuremath{\mathbf P}} _N$ with $\xi=\frac12$ and we have the following scaling limits of ${\ensuremath{\mathbf Z}} _N$.

\noindent{\rm (i)} If $\alpha\in(\frac{d}{d-2},\frac{d}{2})$ (in particular $d\geq5$, $\alpha>1$), then
\begin{equation}
\frac{1}{\beta_N}\left({\ensuremath{\mathbf Z}} _N-{\ensuremath{\mathbf E}} \left[e^{-h_N|{\ensuremath{\mathcal R}} _N|}\right]\right)\overset{(d)}{\longrightarrow}{\ensuremath{\mathcal X}} ,
\end{equation}
where ${\ensuremath{\mathcal X}} $ has been defined in (equation def:cX of the paper).

\noindent{\rm (ii)} If $\alpha<(\frac{d}{d-2}\wedge\frac{d}{2})$ (in particular $\alpha<2$) and $\alpha\neq1$, then we have the following.

{\rm (iia)} If $\zeta\in(1,\gamma+\frac{d(\alpha-1)}{2\alpha})$, then we have that
\begin{equation}
\frac{1}{h_N{\ensuremath{\mathbf E}} [|{\ensuremath{\mathcal R}} _N|]}\log{\ensuremath{\mathbf Z}} _N\overset{{\ensuremath{\mathbbm P}} }{\longrightarrow}-1.
\end{equation}

{\rm (iib)} If $\zeta>\gamma+\frac{d(\alpha-1)}{2\alpha}$, then setting $v_N=\log N$ for $d=2$ and $v_N=N^{\frac{d}{2}-1}$ for $d\geq3$, we have that
\begin{equation}
\frac{v_N}{\beta_N N^{\frac{d}{2\alpha}}}\log{\ensuremath{\mathbf Z}} _N\overset{(d)}{\longrightarrow}{\ensuremath{\mathcal W}} ,
\end{equation}
where ${\ensuremath{\mathcal W}} $ has been defined in (equation def:cW of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma connect of arXiv:2607.00753, 'Threatening excursions in large population\\ quasi-stationary birth and death systems.\\ O'] For any $t\ge0$ and $\underline s\in \Omega_{*}$,
\begin{equation}

\frac{d\widehat { \mathds P}^{({\scriptscriptstyle K})}}{d{{\mathds P}}^{({\scriptscriptstyle K})}}\Big|_{\mathscr{F}_{0,t}^{K,*}}(\underline s)
=\frac{e^{\lambda_{{\scriptscriptstyle K}}\,t}u_{{\scriptscriptstyle K}}(\underline s(t))}{u_{{\scriptscriptstyle K}}(\underline s(0))}.
\end{equation}

For any $K>0$ and $t\ge0$ 
and  ${\cal A}\in\mathscr{F}_{0,t}^{K,*}$ ,
\begin{equation}

\big|\widehat { \mathds P}^{({\scriptscriptstyle K})}_{\mu_{{\scriptscriptstyle K}}}\big({\cal A}\big)
-{{\mathds P}}^{({\scriptscriptstyle K})}_{\nu_{{\scriptscriptstyle K}}}\big({\cal A}\big)\big|\leq  \int_{\mathds Z^d_{+}\backslash\{{\ushort{0}}\}} |1-u_{{\scriptscriptstyle K}}|\,d\nu_{{\scriptscriptstyle K}}+\left(e^{\lambda_{{\scriptscriptstyle K}}\,t}-1\right).
\end{equation}
Let $t(\raisebox{0.4mm}{\scalebox{0.6}{\textbullet}})$ be a positive function on $\mathds R_{+}$ such that
\begin{equation}

\lim_{K\to\infty}\lambda_{{\scriptscriptstyle K}}\,t(K)=0\;.
\end{equation}
Then
\begin{equation}

\lim_{K\to\infty}d_{\mathrm{TV}}\left({{\mathds P}}^{({\scriptscriptstyle K})}_{\nu_{{\scriptscriptstyle K}}}\big|_{\mathscr{F}_{0,t(K)}^{K,*}}\,,\,
\widehat { \mathds P}^{({\scriptscriptstyle K})}_{\mu_{{\scriptscriptstyle K}}}\big|_{\mathscr{F}_{0,t(K)}^{K,*}}\right)=0\;.
\end{equation}

\medskip 
Moreover, there exists $D>1$ independent of $K$ such that 
if $(F_{{\scriptscriptstyle K}})_{{\scriptscriptstyle K}\in\mathds R_{+}}$ is a family of positive functions
 on  $\Omega_{*}$ such that  for each
$K>0$, $F_{K}$ is measurable with respect to $\mathscr{F}_{0,t(K)}^{K,*}$, then
for any $K>0$
\begin{equation}

\frac{1}{D}\,\int_{\Omega_{*}} F_{K} \,d {{\mathds P}}^{({\scriptscriptstyle K})}_{\nu_{{\scriptscriptstyle K}}} \le 
\int_{\Omega_{*}} F_{K} \,d \widehat { \mathds P}^{({\scriptscriptstyle K})}_{\mu_{{\scriptscriptstyle K}}} \le D\,\int_{\Omega_{*}}
F_{K} \,
d {{\mathds P}}^{({\scriptscriptstyle K})}_{\nu_{{\scriptscriptstyle K}}}\;.
\end{equation}

[Lemma LargeDevBalls of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] The following holds:
    \begin{enumerate}[(i)]
        \item Let $\zeta \in \{y\in \mathbb{R}^d: \Phi(y)> 0\}$ and $\epsilon \in (0,1)$ be such that $B(\zeta, \epsilon)\subset \{y\in \mathbb{R}^d: \Phi(y)\geq \epsilon\}$, then
    \begin{equation}
        \mathbf{E}_0\Bigg[\sum_{v\in \mathcal{N}_t}\mathds{1}_{\{X_v(t)\in tB(\zeta,\epsilon)\}}\Bigg] \to 0 \ \ \mathrm{ as } \ \ t\to +\infty.
    \end{equation}
        \item Let $\zeta \in \mathrm{int}(\{y\in \mathbb{R}^d: \Phi(y)\leq 0\})$ and $\epsilon \in (0,1)$ be such that $B(\zeta, \epsilon)\subset \{y\in \mathbb{R}^d: \Phi(y)\leq \epsilon\}$, then
    \begin{equation}
        \mathbf{E}_0\Bigg[\sum_{v\in \mathcal{N}_t}\mathds{1}_{\{X_v(t)\in tB(\zeta,\epsilon)\}}\Bigg] \to + \infty \ \ \mathrm{ as } \ \ t\to +\infty.
    \end{equation}
    \end{enumerate}

