[Corollary 42 (Uniform Gradient Estimates) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] Let Assumptions \ref{ass:smoothing}, \ref{ass:coefficients}, and \ref{ass:problem_data} hold. Let the dynamic obstacle $\Phi$ be admissible in the sense of Definition \ref{def:admissible_obstacle}, and let $u_\varepsilon$ be the unique mild solution of equation \eqref{eq:hjb_penalized}. For any $t \in [0, T)$, the family of continuous Fréchet gradients $\{\nabla u_\varepsilon(t, \cdot)\}_{\varepsilon > 0}$ satisfies the following uniform bounds:
\begin{enumerate}[label={(\textit{\roman*})}, leftmargin=*]
    \item \emph{Uniform Boundedness.} There exists a continuous temporal envelope $K_1(t) > 0$, independent of $\varepsilon$, such that:
    \begin{equation}

        \sup_{\varepsilon > 0} \|\nabla u_\varepsilon(t, x)\|_H \le K_1(t) w_m(x), \quad \forall x \in H.
    \end{equation}

    \item \emph{Uniform Equi-Hölder Continuity.} For any closed ball $B_R \subset H$ of radius $R$, and any exponent $\beta \in (0, 1)$ satisfying $\gamma(1+\beta) < 1$, there exists a continuous temporal envelope $L_{R, T}(t) > 0$, independent of $\varepsilon$, such that:
    \begin{equation}

        \sup_{\varepsilon > 0} \|\nabla u_\varepsilon(t, x) - \nabla u_\varepsilon(t, y)\|_H \le L_{R, T}(t) \|x - y\|_H^\beta, \quad \forall x, y \in \mathcal{B}_R.
    \end{equation}
\end{enumerate}

