n$ and $\scaling \psi_n/n \ge C \log(n)$, then for any $z \in \mathcal{B}(0,R)$ it holds
\begin{equation} 
    \p\left( 
    \bigcup^{n-1}_{i=3\psi_n}
\left\{\sigma_{n-i}\left(\tfrac{1}{\sqrt{\scaling}}{{A}_n}-zI_n\right)\le c\frac{i}{n}\right\}\right)\le\frac{4}{n^2}.
\end{equation}

