[Theorem 7 (Soft Edge) of arXiv:2511.12623, 'The eigenvector bead process'] Fix an integer $\ell \ge 1$.
For $1 \le i,j \le \ell$, the overlap matrix converges to the identity matrix, that is,
\[
\lim_{N \to \infty} \bigl(\Omega^{(N)}_{i,j}\bigr)_{1 \le i,j \le \ell} = I_\ell.
\]
Moreover, there exists a constant $c_q > 0$, depending only on the aspect ratio $q$, such that the leading-order correction scales as $O(N^{-1/3})$ and satisfies
\begin{equation}
  N^{1/3}\bigl(\Omega^{(N)}_{i,j} - (I_\ell)_{i,j}\bigr)
  \;\underset{N \to \infty}{\overset{d}{\sim}}\;
  \begin{cases}
    c_q\,\dfrac{g_i g_j}{\alpha_j - \alpha_i}, & i \ne j,\\[0.8ex]
    0, & i = j,
  \end{cases}
  \qquad 1 \le i,j \le \ell.
\end{equation}
Here \((\alpha_i)_{i=1}^\ell\) follow the Airy$_{\beta}$ point process, and \((g_i)_{i=1}^\ell\) are i.i.d.\ standard Gaussians \(\mathcal{N}(0,1)\) independent of \((\alpha_i)\). For the right edge, set \(c_q = (1+\sqrt{q})^{-1/3}\) and for the left edge, set \(c_q = (1-\sqrt{q})^{-1/3}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 33 of arXiv:2506.15044, '2506.15044'] Let $M\in (\mathcal{M}_{\mathrm{loc}})^\mathbb{C}$ and $H\in \mathcal{L}_m^\mathbb{C}(M)$.
\begin{itemize}
  \item [$(1)$] If $(\tau_n)$ is an FS for $\mathbb{C}$, then $(\tau_n,H^{\tau_n}.M^{\tau_n})$ is an FCS for $H_{\bullet}M\in(\mathcal{M}_{\mathrm{loc}})^\mathbb{C}$, and $H_{\bullet}M$ can be expressed as
      \begin{equation}
      H_{\bullet}M=\left((H_0M_0)I_{\llbracket{0}\rrbracket}+\sum\limits_{n=1}^{{+\infty}}
      (H^{\tau_n}.M^{\tau_n})I_{\rrbracket{\tau_{n-1},\tau_n}
      \rrbracket}\right)\mathfrak{I}_\mathbb{C},\quad \tau_0=0,
      \end{equation}
      which is independent of the choice of the FS $(\tau_n)$ for $\mathbb{C}$.

  \item [$(2)$] If $(T_n,H^{(n)})$ is an FCS for $H\in\mathcal{P}^\mathbb{C}$ and $(T_n,M^{(n)})$ is an FCS for $M\in(\mathcal{M}_{\mathrm{loc}})^\mathbb{C}$ such that for each $n\in \mathbf{N}^+$, $H^{(n)}\in\mathcal{L}_m(M^{(n)})$, then $(T_n,H^{(n)}.M^{(n)})$ is an FCS for $H_{\bullet}M\in(\mathcal{M}_{\mathrm{loc}})^\mathbb{C}$, and $H_{\bullet}M$ can be expressed as
      \begin{equation}
      H_{\bullet}M=\left((H_0M_0)I_{\llbracket{0}\rrbracket}+\sum\limits_{n=1}^{{+\infty}}
      (H^{(n)}.M^{(n)})I_{\rrbracket{T_{n-1},T_n}
      \rrbracket}\right)\mathfrak{I}_\mathbb{C},\quad T_0=0.
      \end{equation}
      which is independent of the choice of FCSs $(T_n, H^{(n)})$ for $H\in\mathcal{P}^\mathbb{C}$ and $(T_n,M^{(n)})$ for $M\in(\mathcal{M}_{\mathrm{loc}})^\mathbb{C}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

