[Lem lemma: estimate for g^2 if sv is in 0 1 of arXiv:2607.27472, 'The stochastic Keller--Segel system in critical spaces'] Assume (equation Eq_standard of the paper) and  (equation Eq_pc1_new of the paper)--(equation Eq_pc5_new of the paper) and that $g^2$ satisfies Assumption (Ass_noise of the paper)~(equation Aii of the paper).
			If $s_v \in (0,1]$, then for every $\eta >0$
			\begin{align}\begin{split}
					&\|g^2(v) - g^2(\overline v)\|_{H^{1+s_v,q_v}(\mathbb{T}^d;\ell^2)} \\
					& \lesssim_{(\eta ,g^2)}\Big(1 + \|v\|_{H^{2,q_v}(\mathbb{T}^d)}+\|\overline{v}\|_{H^{2,q_v}(\mathbb{T}^d)} \Big)  \|v - \overline v\|_{H^{\zeta_\eta,q_v}(\mathbb{T}^d)}
					\\&
					\quad + \left(\|v\|_{H^{1+\frac{d}{2q_v},q_v}(\mathbb{T}^d)}^{1+s_v}+\|\overline{v}\|_{H^{1+\frac{d}{2q_v},q_v}(\mathbb{T}^d)}^{1+s_v}\right)\|v - \overline v\|_{H^{\zeta_\eta,q_v}(\mathbb{T}^d)},
				\end{split}
			\end{align}
			and 
			\begin{align}\begin{split}
					& \|g^2(v)\|_{H^{1+s_v,q_v}(\mathbb{T}^d;\ell^2)} \\
					& \lesssim_{(\eta  ,g^2)}\left(1 + \|v\|_{H^{2,q_v}(\mathbb{T}^d)}\right) \|v\|_{H^{\zeta_\eta,q_v}(\mathbb{T}^d)}
					+ \|v\|_{H^{1+\frac{d}{2q_v},q_v}(\mathbb{T}^d)}^{1+s_v}\|v\|_{H^{\zeta_\eta,q_v}(\mathbb{T}^d)},
				\end{split}
			\end{align}
			for all $v,\overline{v}\in H^{\max\{2, \zeta_\eta\}, q_v}(\mathbb{T}^d)$, where $\zeta_\eta = s_v+2-2\frac{1+\kappa}{p}+\eta$.

