body:
[Lemma 41 (Global Regularity and Gradient Estimates) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] Let Assumptions \ref{ass:smoothing}, \ref{ass:coefficients}, and \ref{ass:problem_data} hold. For any $\varepsilon > 0$ and $t \in [0, T)$, the mild solution $u_\varepsilon \in \mathcal{C}_m([0, T] \times H)$ to equation \eqref{eq:hjb_penalized} satisfies:
\begin{enumerate}[label={(\textit{\roman*})}, leftmargin=*]
    \item \emph{Continuous Differentiability.} The mapping $u_\varepsilon(t, \cdot)$ is continuously Fréchet differentiable on $H$. Defining the penalty term $\Pi_\varepsilon := \frac{1}{\varepsilon}(u_\varepsilon - \Phi)^+$, the spatial gradient satisfies:
    \begin{equation}

        \|\nabla u_\varepsilon(t, x)\|_H \le C_1 \left[ \|\Psi\|_{\mathcal{B}_m} (T-t)^{-\gamma} + \big( \|f\|_{\mathcal{B}_{m, T}} + \|\Pi_\varepsilon\|_{\mathcal{B}_{m, T}} \big) \frac{(T-t)^{1-\gamma}}{1-\gamma} \right] w_m(x), \quad \forall x \in H.
    \end{equation}

    \item \emph{Local Equi-Hölder Continuity.} For any radius $R > 0$ and exponent $\beta \in (0, 1)$ satisfying $\gamma(1+\beta) < 1$, the spatial gradient is locally $\beta$-Hölder continuous. Setting $C_R := C_{3}(1 + R^m)$, for all $x, y \in B_R \subset H$:
    \begin{equation}

        \|\nabla u_\varepsilon(t, x) - \nabla u_\varepsilon(t, y)\|_H \le C_R \left[ \|\Psi\|_{\mathcal{B}_m} (T-t)^{-\gamma(1+\beta)} + \big( \|f\|_{\mathcal{B}_{m, T}} + \|\Pi_\varepsilon\|_{\mathcal{B}_{m, T}} \big) \frac{(T-t)^{1-\gamma(1+\beta)}}{1-\gamma(1+\beta)} \right] \|x - y\|_H^\beta.
    \end{equation}
\end{enumerate}

