\begin{equation} 

    u_\varepsilon(t, x) = P_{t,T}[\Psi](x) + \int_t^T P_{t,s} [H_\varepsilon(s, \cdot)](x) \, \mathrm{d}s,
\end{equation}
where the effective source term is defined as $H_\varepsilon(s, x) := f(s, x) - \Pi_\varepsilon(s, x)$. Since $f, \Phi, u_\varepsilon \in \mathcal{B}_m([0, T] \times H)$, the penalty term $\Pi_\varepsilon$ and the source $H_\varepsilon$ belong to the same space. By the triangle inequality, we have the norm bound ...","release_manifest_digest":"sha256:062c66949def55f18acb59ee2a842442844dabcaa0c21299f452061c9d24f554","revision_digest":"sha256:c8f1af4a0c4731ac68db258f34616f5cd7403761ce680557ff4840450915324d","source_id":"arxiv:2607.03318","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

