[Thm partitionFunctionBound of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Fix $\beta\ge0$ and assume $0\le\mathsf{s}<\mathsf{d}/2$ and $\mu\in L^\infty\cap\mathcal{P}({\mathbb{R}}^\mathsf{d})$; if $\mathsf{s}=0$, assume in addition
\begin{align}
\int_{({\mathbb{R}}^\mathsf{d})^2}|\log |x-y||\,\mathop{}\!\mathrm d\mu^{\otimes2}(x,y)<\infty.
\end{align}
\begin{enumerate}[(i)]
\item\emph{(Uniform bound.)}  There is a finite constant $C_{\mathrm{ub}}(\beta,\mu)$ such that
\begin{align}
\sup_{N\ge1}{\mathsf{K}}_{N,\beta}(\mu)\le C_{\mathrm{ub}}(\beta,\mu).
\end{align}
\item\emph{(Quantitative convergence.)}  If $\mathsf{s}=0$, assume moreover that
\begin{align}
\int_{{\mathbb{R}}^\mathsf{d}}e^{-4\beta h_\mu}\,\mathop{}\!\mathrm d\mu<\infty,
\qquad \tilde{\mathsf{g}}\in L^2(\mu^{\otimes2}).
\end{align}
Then there are constants $C_{\mathrm{rate}}(\beta,\mu)<\infty$ and, in the logarithmic case, $c_{\log}(\beta,\mu)>0$ such that, for all $N\ge1$,
\begin{align}
\Big|{\mathsf{K}}_{N,\beta}(\mu)-{\mathsf{K}}_{\infty,\beta}(\mu)\Big|
\le C_{\mathrm{rate}}(\beta,\mu)
\begin{cases}
(\log(e+N))^{-\frac{\mathsf{d}-2\mathsf{s}}{2\mathsf{s}}}, & 0<\mathsf{s}<\mathsf{d}/2,\\[0.4em]
(e+N)^{-c_{\log}(\beta,\mu)}, & \mathsf{s}=0.
\end{cases}
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop-4corr of arXiv:2607.25567, 'Random Trees in Hyperbolic FPP'] If {$[ 1: \xi: a: b]\ll 0$, }then $c_{a1\xi}(\omega)$ and $X_{b1\xi}(\omega)$
	are {nearly independent}.
	If {$[ 1: \xi: a: b] \gg 0$, }  then $c_{a1\xi}(\omega)$ and $c_{b1\xi}(\omega)$
	are nearly the same.

	More precisely, there exists $C\geq 1, \, c\in (0,1)$ such that 
	\begin{enumerate}
		\item in the first case, {the total variation distance between the joint distribution of $(c_{a1\xi}(\omega),c_{a1\xi}(\omega))$ and the product of the two marginals is smaller than $\exp(c'\langle 1,\xi,a, b \rangle)$.} 


		\item  in the second case, there exists $\kappa > 0$ such that
		 $\mathbb{P}[{d(c_{a1\xi}(\omega), c_{b1\xi}(\omega))}\geq N]\leq e^{-\kappa N}$. 
	\end{enumerate}

