[Lemma 13 of arXiv:2607.11608, '2607.11608'] Let  $\mu$ as in \eqref{mu_def}.  Then, for every $K\in \R$ and $\eps>0$,
\begin{equation*}
\mu\bigg(\int_{\R^d}:\!|\P_{N}u|^2\!:dx \in [K-\eps,K+\eps]\bigg)\les \eps,
\end{equation*}
where the implicit constant is independent of $K$ and $\eps$. 
In particular, the same holds true for $\int_{\R^d}:\!|u|^2\!:dx=\lim_{N\to +\infty}\int_{\R^d}:\!|\P_{N}u|^2\!: dx$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:wcutoff of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] For fixed $\varepsilon$ and $\delta$,
\begin{equation*}

   \mathbb{P}(L_{\mathrm{RW}}\ne L_{\mathrm{RW}}^R)
   \le \frac{C\delta^{-1}\varepsilon^{-1}}{R}+o_n(1).
\end{equation*}

[Theorem thm23 of arXiv:2411.05369, 'Stochastic games of parental vaccination decision making and bounded rationality'] If $R_0^s>1$ and $\bar{x}(t)\to x_0$, then a disease-endemic equilibrium will persist in the temporal mean. That is
\begin{enumerate}
\item For all $x_0\in [0,1]$, 
\begin{equation}  
 \dfrac{\mu\,(1-x_0)}{\mu+\beta} \leq \liminf_{t\to \infty} \bar{S}(t)\leq \limsup_{t\to \infty} \bar{S}(t)\leq 1-x_0
\end{equation} and
    \item If $x_0<1-\frac{1}{R_0^s}$, then \begin{equation}
    \liminf_{t \to \infty} \bar{I}(t)\geq \frac{\mu}{\mu+\gamma}[1-\frac{1}{R_0^s}-x_0]\end{equation} 
    and 
    \begin{equation}
    \limsup_{t \to \infty} \bar{S}(t)\leq \frac{1}{R_0^s}.
\end{equation}
Equation (equation upS of the paper) holds true also when $x_0\geq 1-\frac{1}{R_0^s}$ from the upper inequality in Part (1).
    \item If $x_0<\frac{\beta}{\beta-\sigma_1^2}(1-\frac{1}{R_0^s})$ and $\beta>\sigma_1^2$ then \begin{equation}
    \limsup_{t\to \infty} \bar{I}(t)\leq \frac{\mu}{\mu+\gamma}[\frac{\beta}{\beta-\sigma_1^2}(1-\frac{1}{R_0^s})-x_0].
    \end{equation} 
\end{enumerate}

