[Lemma lem:c_perturbed of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] \begin{equation}
        \left(\frac{1}{m} U_{m-1}(x)\right) \left(\frac{1}{m+1} U_m(x)\right)^{t-1} = \sum_{k \ge 0} \tilde{c}_t(m; k) \, \frac{1}{k+1}U_k(x),
    \end{equation}
    where $\tilde{c}_t(m; k) = 0$ unless $k \equiv tm-1 \pmod 2$.
    As $m \to \infty$, for $k \equiv tm-1 \pmod 2$ and $k = \lfloor \xi m \rfloor$,
    \begin{equation}
        \tilde{c}_t(m; k) \sim \frac{2}{m}   \xi \, \mathcal{P}_t(\xi).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma RR_TT of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] Consider the setting of Lemma~(AJSJAsd of the paper). Then the following statements are valid.
	\begin{itemize}
		\item For every \( \omega^-, \omega^+ \in \mathcal{B}_H \) and all \( 0 \leq \tau \leq s \leq t \), the following identity holds:
		\begin{align}
			\begin{split}            
				\mathcal{D}_{H} P_{t}(\omega^-, \omega^+)(\tau - t)
				&- \mathcal{D}_{H} P_{t}(\omega^-, \omega^+)(-t)
				\\&= \mathcal{D}_{H} P_{s}(\omega^-, \omega^+)(\tau - s)
				- \mathcal{D}_{H} P_{s}(\omega^-, \omega^+)(-s).
			\end{split}
		\end{align}

		\item For all \( r \leq 0 \) and \( \omega^- \in \mathcal{B}_H \), we have 
		\begin{align}
			(\mathcal{D}_{H} \vartheta_{t} \omega^-)(r)
			= \mathcal{D}_{H} \omega^-(-t + r)
			- \mathcal{D}_{H} \omega^-(-t).
		\end{align}







		Define the process \( (B_t^H)_{t \in \mathbb{R}} \) by
		\begin{align*}
			B_t^H =B_{t}^{H}(\omega^-,\omega^+):=
			\begin{cases}
				- \bigl( \mathcal{D}_H P_t(\omega^-, \omega^+) \bigr)(-t), & t \geq 0, \\[6pt]
				\mathcal{D}_H \omega^-(t), & t \leq 0.
			\end{cases}
		\end{align*}
		Then \( (B_t^H)_{t \in \mathbb{R}} \) denotes a two-sided fractional Brownian motion with Hurst parameter \( H \), adapted to the canonical filtration \( (\mathcal{F}_{-\infty}^t)_{t \in \mathbb{R}} \) generated by the underlying Brownian motion appearing in the Mandelbrot-van Ness representation.

	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.28964, '2608.28964'] For the equation given by \eqref{eq NS},\eqref{eq eta}, assume that the sequence $\{b_j\}_{j\in\N^+}$ satisfies $\sum_{j\in\N^+}b_j^2<\infty$. Then there exist constants $c,C,\gamma_0>0$ such that the solution $U_t=U(t,U_0)=(u_t,\eta_t)$ satisfies the following estimates.  
    \begin{itemize}
        \item [(1)] For any $\gamma\in(0,\gamma_0]$, $U_0\in \mathcal X$ and $t\geq0$, 
	\begin{align}
	\E\exp\left(\gamma\|U_t\|_{\mathcal X}^2\right)\leq C\exp\left(C\gamma e^{-ct}\|U_0\|_{\mathcal X}^2\right).
	\end{align}
        \item [(2)] For any $\gamma\in(0,\gamma_0]$, $U_0\in \mathcal X$ and $n\in\N$, 
	\begin{align}
	\E\exp\left(\gamma\sum_{0\leq k\leq n}\|U_k\|_{\mathcal X}^2\right)\leq\exp\left(C\gamma\|U_0\|_{\mathcal X}^2\right)\exp\left(Cn\right).
	\end{align}
        \item [(3)]  For any $\gamma\in(0,\gamma_0]$, $U_0\in \mathcal X$ and $n\in\N$, 
	\begin{align}
	\E\left(\exp\left(\gamma\|u\|_{L^\infty((n+1,n+2)\times D)}^2\right)|\mathcal{F}_{n}\right)&\leq C\exp\left(C\gamma\|U_{n}\|_{\mathcal X}^2\right),\\
	\E\left(\exp\left(\gamma\|u\|_{L^2(n,n+2;\mathcal H^2)}^2\right)|\mathcal{F}_{n}\right)&\leq C\exp\left(C\gamma\|U_{n}\|_{\mathcal X}^2\right).
	\end{align}
        \item [(4)]  For any $m\in\N^+$, there exists a constant $C_m>0$ such that for any $U_0\in \mathcal X$ and $n\in\N$, 
	\begin{equation}
	\E\left(\|\partial_tu\|_{L^2(n+1,n+2;L^4(D))}^m|\mathcal{F}_{n}\right)\leq C_m(1+\|U_{n}\|_{\mathcal X}^{2m}).
	\end{equation}
    \end{itemize}

