[Lemma 5 of arXiv:2608.29984, 'On Cauchy Problems for Parabolic Equations with Rough Coefficients'] For $1\leq p\leq\infty, k \geq 0$,
\begin{equation}
\begin{split}
&\|\nabla^{k}(S_{0}u)\|_{L^{p}(\R^{d})}\lesssim \|S_{0}u\|_{L^{p}(\R^{d})},\\
&\|\nabla^{k}(\Delta_{j}u)\|_{L^{p}(\R^{d})} \sim 2^{kj}\|\Delta_{j}u\|_{L^{p}(\R^{d})}.
\end{split}
\end{equation}
For $1<p<q<\infty, k\geq 0$,
\begin{equation}
\begin{split}
&\|\nabla^{k}(S_{0}u)\|_{L^{\infty}(\R^{d})}\lesssim \|S_{0}u\|_{L^{p,\infty}(\R^{d})},\\
&\|\nabla^{k}(S_{0}u)\|_{L^{q,1}(\R^{d})}\lesssim \|S_{0}u\|_{L^{p,\infty}(\R^{d})},\\
&\|\nabla^{k}(\Delta_{j}u)\|_{L^{\infty}(\R^{d})}\lesssim 2^{(k+\frac{d}{p})j}\|\Delta_{j}u\|_{L^{p,\infty}(\R^{d})},\\
&\|\nabla^{k}(\Delta_{j}u)\|_{L^{q,1}(\R^{d})}\lesssim 2^{(k+\frac{d}{p}-\frac{d}{q})j}\|\Delta_{j}u\|_{L^{p,\infty}(\R^{d})}.
\end{split}
\end{equation}

[Proposition prop:CE1_old of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] {ChenLubetzky25}}]
    Fix $n\geq 1$. Let $V\subset \mathbb Z^2$ be a connected domain, and consider the \ensuremath{\mathbb Z\textsc{gff}}\xspace model $\pi_{V;F}^{\xi}$ with a floor at~0 imposed only on a subset $F \subset V$, and boundary conditions $\xi$ that are $H+1-n$ on a $*$-connected path in $\partial_{\mathtt v} V$ and $H-n$ elsewhere so that they induce a unique disagreement polymer $(\gamma,\{D_i\},\{h_i\})$ in $V\cup \partial_{\mathtt v} V$ that contains boundary disagreements. Then for $\beta\geq \beta_0$, the law of this unique disagreement polymer $\gamma$ is given by 
		\begin{align}
			\pi^{\eta}_{V;F}(\gamma) =\frac1{Z_{V;F}^\eta} \exp\Big(-{\ensuremath{\mathscr E}}_\beta(\gamma) + \mathfrak{I}_V(\gamma)
			\Big)\prod_{i\geq 0}{\widehat\pi}_{D_i^\circ}^{h_i}\big(\phi_x \geq 0,\, \forall x \in D_i^{\circ}\cap F\big)\,,
		\end{align}
		for $Z_{V;F}^\eta = Z_{V;F}^\eta(\beta,n)$ 
        and $\mathfrak{I}_V$ from (eq:IU(gamma)-def of the paper) featuring a decoration function $\Phi$ as per (def:disagree-polymer-len-energy-decor of the paper).

		Moreover, if we further have $|F| \leq L e^{\kappa\sqrt{\log L}}$ and $|\partial F|\leq L^{1-\delta}$ for fixed $\kappa>0$ and $0<\delta<\frac13$, denote by $D_0$ and $D_1$ the regions of $\gamma$ containing the boundary vertices of $V$ at heights $H+1-n$ and $H-n$, respectively, and let
		\begin{align*} E:=\left\{|\gamma|\leq L^{1-\delta}\,,\;
			\;|F| - |D_0 \cap F| - |D_1 \cap F| \leq L^{1-\delta}\right\}\,,\end{align*}
		then the following holds
		for all $\beta\geq \beta_0$. The probability distribution given~by 
		\begin{equation}
        \mathfrak{p}_{V;F}^{\eta}(\gamma) := 
		\frac1{\widetilde{Z}^\eta_{V;F}} \exp\bigg(-{\ensuremath{\mathscr E}}_\beta(\gamma) + \frac{|D_0\cap F|}{N_n}+ \mathfrak{I}_V(\gamma)\bigg)\prod_{i \geq 2}{\widehat\pi}_{D_i^\circ}^{h_i}(\phi_x \geq 0,\, \forall x \in D_i^{\circ} \cap F)
		\end{equation}
        for $\gamma\in E$, 
		with $N_n$ from (eq:Nn-def of the paper) and $\widetilde{Z}^\eta_{V;F}$ a normalizer, satisfies that for every $\gamma\in E$,
		\begin{align}
			\pi^\eta_{V;F}(\gamma \mid E) =(1+o(1))\mathfrak{p}_{V;F}^{\eta}(\gamma)\,.
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Let $\emprashomonset$, $\rretailset$, and $x$ satisfy Assumption \ref{assume:rashomon} for parameters $\sigma, \rashlexpctparam > 0$. Let $\rlocaltestmat =  \{\rlocaltest_{j}: j \in [\nogaussianpts]\}$ be a random set of perturbations of $x$, distributed $\iid \Unif(\ltwohsphere(x,\sigma))$, and $\ensmretset(\retailset,\localtestmat)$ be the ensemble model defined in \ref{def: local ensemble}.
Define
\begin{align}
   \lallavg(x) = \abs*{\ensmretset(\rretailset,\rlocaltestmat) - \frac{1}{2}}.
\end{align}
Then for any $\slackgap > 0$, 
    \begin{align}
    \prob_{\rretailset,\rlocaltestmat}*{
        \abs*{  \lallavg(x) - \explallavg(x)}
    \ge \slackgap }
    \le 2\exp\parens*{ \frac{-S\slackgap^2}{8\eta^2\sigma^{2}} } +
        2\exp\parens*{ \frac{-\Nretail\slackgap^2}{8\rashlexpctparam^2} }.
    \end{align}

