[Thm clt:Wiener of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] For all $n \in {\mathbb N}$ and $m \ge 2$ we have
    \begin{align}
        \Var(W_n) &= \frac{n^3(m-1)(m-2)(m+1)(m+2)}{180m^2}\\
        &\quad\quad~+\frac{n^2(m-1)(m+1)(m^3+m^2-4m+11)}{90m^2}\nonumber\\
        &\quad\quad~+\frac{n(m-1)(m+1)(m^4-2m^3-7m^2+8m-18)}{180m^2}.\nonumber
   \end{align}

     For $m=2$ as $n\to\infty$, we have
    \begin{equation*}
        \frac{W_n-\,{\mathbb{E}}[W_n]}{n} \overset{d}{\longrightarrow} 3N_1N_2+N_1^2+N_2^2+\frac{1}{4}
    \end{equation*}
    with $(N_1,N_2)$ defined in (equation N_i of the paper).

    For $m \ge 3$ it holds
    \begin{equation*}
            \frac{W_n-\mathbb{E}[W_n]}{n^{3/2}} \overset{d}{\longrightarrow}
            \mathcal{N}\left(0,\frac{(m-1)(m-2)(m+1)(m+2)}{180m^2}\right).

    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 20 of arXiv:2609.02261, 'Quantization and process'] For any  $\lambda$ and $\mu$ satisfying
  $ 0 < \mu  < \lambda$, for every     multi-index $ \alpha $, 
  the operator  $\partial ^{\alpha} $ is bounded from
  $D_{\lambda } ( \R^{2n})$ into  $D_{\mu} ( \R^{2n})$ and we have, 

  $$  \Vert \partial ^{\alpha} F \Vert _{D_{\mu}( \R^{2n})} 
  \leq ( {\lambda  - \mu} ) ^{- 2n}  \sqrt {\alpha ! }
   \Big (\frac  {C }  {\lambda  - \mu} \Big )^{\frac{| \alpha|}{ 2}} 
   \Vert  F \Vert _{D_{\lambda}( \R^{2n}) }, $$

 for some constant real number $C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm eigenvalues distinct k_i of arXiv:2509.15790, 'Covariance matrices of volume power functionals of random simplicial complexes -- an asymp'] Let $\Sigma_n $ be as in ((Eq: Kov.matrix Laengen Potenz Funktional of the paper)) in the subcritical regime for $n\geq2$ with respect to the vector of distinct $k_i$-simplices $(\tilde{\mathcal{V}}_{k_1}^{(\alpha_1)},  \ldots,\tilde{\mathcal{V}}_{k_n}^{(\alpha_n)})$. Then the following statements hold:
\begin{enumerate}
    \item The determinant of $\Sigma_n$ is \[\det \Sigma_n=\prod_{i=1}^n \frac{\mu_{k_i}^{(2\alpha_i)}}{ (k_i + 1)!}  
.\]
    \item The eigenvalues of $\Sigma_n$ are its diagonal entries 
\[\lambda_i = \frac{\mu_{k_i}^{(2\alpha_i)}}{ (k_i + 1)!}.\]

    \item The eigenspaces of $\Sigma_n$ are given by \[\text{eig}(\lambda_i; \Sigma_n) = e_i, \]
    where $e_i$ denotes the $i$-th $n$-dimensional unit vector.
\end{enumerate}

