[Lemma frechet of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $A\in \mathcal{A}$ and $h\in C([0,1])$. Then 
\begin{equation}
DT_{A}[h](x)=\frac{-\int_{0}^{q(x)}(2-2t)\,h(t)\,dt+\tau
(x)\int_{0}^{1}(2-2t)\,h(t)\,dt}{M}.  
\end{equation}
Consequently, 
\begin{equation}
\Vert DT_{A}\Vert _{\infty \rightarrow \infty }\leq \sup_{x\in \lbrack 0,1]}
\frac{(1-\tau (x))p(x)+\tau (x)(1-p(x))}{M}.  
\end{equation}
For the indexed orbit this becomes 
\begin{equation}
K_{n}(x)=\frac{(1-\tau _{n}(x))p_{n}(x)+\tau _{n}(x)(1-p_{n}(x))}{M_{n}}
,\qquad \Vert DT_{A_{n}}\Vert _{\infty \rightarrow \infty }\leq \sup_{x\in
\lbrack 0,1]}K_{n}(x).  
\end{equation}

