body:
[Theorem thm2 of arXiv:2411.15881, 'Stable Approximation for Call Function Via Stein's method'] Keep the same assumptions and notation as in Theorem (thm1 of the paper). Then we have
\begin{align*}
\left|\mathbb{E}\left(S_n-M\right)_{+}-\mathbb{E}\left(S_\alpha (1,\delta)-M\right)_{+}\right|\leq c_{2,M}R_{n},
\end{align*}
where $R_{n}$ is defined by (Rn of the paper) and
\begin{align*}
c_{2,M}=&
\frac{4d_{\alpha}\mathbb{E}\left[\left|\xi_{1}-\mathbb{E}[\xi_{1}]\right|^{2-\alpha}\right]}{(2-\alpha)(\alpha-1)\sigma^{2-\alpha}}\frac{\eta_{3,\alpha,\delta}}{M^{\frac{2(\alpha-1)}{3\alpha-1}}}
+\frac{3\mathbb{E}\left[|\xi_{1}|\right]\left|\mathbb{E}[\xi_{1}]\right|}{\sigma^{2}}\frac{\eta_{3,\alpha,\delta}}{M^{\frac{2(\alpha-1)}{3\alpha-1}}}\\
&+\eta_{3,\alpha,\delta}
\begin{cases}
\frac{2(2A)^{\frac{2}{\alpha}}}{\sigma^{2}}\left[\frac{2}{2-\alpha}+\frac{2L}{\alpha+\gamma-2}(2A)^{-\frac{\alpha+\gamma}{\alpha}}\right]M^{-\frac{2(\alpha-1)}{3\alpha-1}},&\gamma\in(2-\alpha,\infty),\\
\frac{1}{\sigma^{2}}\left[\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{\alpha-1}\right)
+q_{1}\right]\frac{2(\alpha-1)\log M}{3\alpha-1}M^{-\frac{2(\alpha-1)}{3\alpha-1}},& \gamma=2-\alpha,\\
\sigma^{\frac{\alpha-\gamma}{\gamma-1}}\left[\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{2-\alpha-\gamma}\right)
+q_{1}\right]M^{-\frac{2(\alpha-1)^{2}}{(3\alpha-1)(1-\gamma)}}, &\gamma\in(0,2-\alpha),\\
\max\left\{\frac{2\alpha(2A)^{\frac{2}{\alpha}}}{(2-\alpha)\sigma^{2}},\frac{4}{\sigma^{2}},
\frac{8}{(2-\alpha)\sigma^{\alpha}}+\frac{2(2A)^{\frac{2}{\alpha}}}{\sigma^{\alpha}}+q_{1}\right\}M^{-\frac{2(\alpha-1)^{2}}{(3\alpha-1)}},
&\gamma=0,
\end{cases}
\end{align*}
with
\begin{align}
q_{1}=\frac{8\alpha^{2}(A+L)-4\alpha L}{(\alpha-1)\eta_{3,\alpha,\delta}}.
\end{align}

In particular, when $\delta=0$, the order of $M$ can be improved and the $c_{2,M}$ can be reduced to $c_{3,M}$, which is defined as follows:
\begin{align*}
c_{3,M}=&
\frac{4d_{\alpha}\mathbb{E}\left[\left|\xi_{1}-\mathbb{E}[\xi_{1}]\right|^{2-\alpha}\right]}{(2-\alpha)(\alpha-1)\sigma^{2-\alpha}}\frac{\eta_{4,\alpha}}{M^{\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}}}
+\frac{3\mathbb{E}\left[|\xi_{1}|\right]\left|\mathbb{E}[\xi_{1}]\right|}{\sigma^{2}}\frac{\eta_{4,\alpha}}{M^{\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}}}\\
&+\eta_{4,\alpha}
\begin{cases}
\frac{2(2A)^{\frac{2}{\alpha}}}{\sigma^{2}}\left[\frac{2}{2-\alpha}+\frac{2L}{\alpha+\gamma-2}(2A)^{-\frac{\alpha+\gamma}{\alpha}}\right]M^{-\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}},&\gamma\in(2-\alpha,\infty),\\
\frac{1}{\sigma^{2}}\left[\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{\alpha-1}\right)
+q_{2}\right]\frac{(\alpha^{2}-1)\log M}{\alpha^{2}+2\alpha-1}M^{-\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}},& \gamma=2-\alpha,\\
\sigma^{\frac{\alpha-\gamma}{\gamma-1}}\left[\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{2-\alpha-\gamma}\right)
+q_{2}\right]M^{-\frac{(\alpha^{2}-1)(\alpha-1)}{(\alpha^{2}+2\alpha-1)(1-\gamma)}}, &\gamma\in(0,2-\alpha),\\
\max\left\{\frac{2\alpha(2A)^{\frac{2}{\alpha}}}{(2-\alpha)\sigma^{2}},\frac{4}{\sigma^{2}},
\frac{8}{(2-\alpha)\sigma^{\alpha}}+\frac{2(2A)^{\frac{2}{\alpha}}}{\sigma^{\alpha}}+q_{2}\right\}M^{-\frac{(\alpha^{2}-1)(\alpha-1)}{\alpha^{2}+2\alpha-1}},
&\gamma=0,
\end{cases}
\end{align*}
with $q_{2}=\frac{8\alpha^{2}(A+L)-4\alpha L}{(\alpha-1)\eta_{4,\alpha}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:der-mart-multi-bis2 of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] There exists $t_{\textnormal{max}}\le -1$ and a constant $c > 0$ such that 
  \begin{equation}

    u(t, x) \geq c x\mathrm{e}^{-x}
  \end{equation}
  for all $t \leq t_{\textnormal{max}}$ and $x\in [4 \log \left |t \right|, \left |t \right|/8]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem l:104.4 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $W$ be a standard Gaussian, $Y, Y'$ be random variables taking values in some measurable space $\mathcal Y$ and independent of $W$, and 
$F: \mathcal Y \times \mathbb{R} \to \mathbb{R}$ a bounded measurable function. Then 
\begin{equation}
 \mathbb{E} F(Y,W+z) = \mathbb{E} F(Y',W+z) \,,\,\, \forall z \in \mathbb{R} \quad \Longrightarrow \quad \mathbb{E} F(Y,0) = \mathbb{E} F(Y',0) \,.
\end{equation}

