[Lemma lem:moment-bound:H^0_epsilon of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] Assume the hypotheses of~(thm:well-posed of the paper) and let $U_0=(u_0,\eta_0)\in \mathcal{H}^0_\mu$. Then

\begin{enumerate}[noitemsep,topsep=0pt,wide=0pt,label=\arabic*.,ref=\theassumption.\arabic*]
\item For all $\beta$ sufficiently small independent of $\mu\in\mathcal{M}_\delta$, 
\begin{equation}
\mathbb{E} \exp\left({\beta\Psi_0(U(t))}\right)\le e^{-c_0t}\exp\left({\beta\Psi_0(U_0)}\right)+C_0,\quad t\ge 0,
\end{equation}
where $\Psi_0$ is as in (equation form:Psi_0 of the paper) and $c_0=c_0(\beta)>0$, $C_0=C_0(\beta)>0$ do not depend on $U_0\in\mathcal{H}^0_\mu$, $t\ge 0$ and $\mu\in\mathcal{M}_\delta$. 

\item For all $n\ge 1$, there exist positive constants $c_{0,n},\tilde{c}_{0,n}$ and $C_{0,n}$ independent of $U_0\in\mathcal{H}^0_\mu$, $t\ge 0$ and $\mu\in\mathcal{M}_\delta$ such that
\begin{equation}  
\emph{d} \Psi_0(U(t))^n\le -c_{0,n} \Psi_0(U(t))^n\emph{d} t+\tilde{c}_{0,n}\emph{d} t+\emph{d} M_{0,n}(t),
\end{equation} 
where $M_{0,n}(t)$ is the semi-martingale given by
\begin{equation} 
M_{0,n}(t)=\int_0^t n\Psi_0(U(r))^{n-1}\langle u(t),Q\emph{d} w(r)\rangle_H. 
\end{equation}
Furthermore,
\begin{equation} 
\mathbb{E}\Psi_0(U(t))^n \le e^{-c_{0,n}t}\Psi_0(U_0)^n+C_{0,n},\quad t\ge 0.
\end{equation}
\end{enumerate}

