	Note that $G(\pi/2,t) = -1$ for all $t\geq 0$.

	\smallskip

	\noindent
	\textbf{Step 1: Stationary points of $G(\cdot,t)$:}
	Since $G(\cdot,t)$ has period $\pi$ it is enough to consider $\vartheta \in [-\pi/2,\pi/2]$.
	Make the change of variables $x = \tan(\vartheta)$. Then
	\begin{equation*}
		\cos^2(\vartheta) = \frac{1}{1+x^2}, \quad \sin(2\vartheta) = \frac{2x}{1+x^2}.
	\end{equation*}
	Substituting into $G(\vartheta,t)=0$ and multiplying by $1+x^2$ gives
	\begin{equation*}
		x^2-x f(t) + g(t) = 0.
	\end{equation*}
