[Lemma 51 of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] There exist constants $C,c$ such that for any $\delta\in (0,1/10],0<\beta<n$ and all $n\in \NN$, we have
  \begin{equation}

    \PP(\Gamma_{\0}^{(\beta n,n),t}\not\subseteq B_{\beta n^{2/3+\delta}}(\LL_{\0}^{(\beta n,n)})\textrm{ for some } t\in [0,1])\leq Ce^{-cn^{3\delta}}.
  \end{equation}

[Theorem existence_heat_eq of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $\bm p \in \mathcal B\,$, and $\bm u$ be as in Theorem (theorem:analyticity_general of the paper). Then,
\begin{enumerate}
    \item For all ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, the function $t \mapsto \bm u_t^{{\color{NavyBlue}{\mathbf{v}}}}$ is $C^1$ on $[0, T]\,$. 
    \item The following linear equation is satisfied:
    \begin{equation}

    \begin{cases}
         \dot \bm{u}_t + \mathscr{L}\bm{u}_t= 0\,, \quad t \in [0, T], \\
    \bm u_T = \exp^{\mathrel{\sqcup \mkern -3mu \sqcup}}\left({\bm p}\right).
    \end{cases}
    \end{equation}
    \item For any ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, there exists a constant $C_{\bm p, T, {\color{NavyBlue}{\mathbf{v}}}} \geq 0$ such that {for all $\sigX[] \in G$}
    \begin{equation}

    \sup_{t \in [0, T]}\,\|\bm u_t|_{{\color{NavyBlue}{\mathbf{v}}}}\|_{\sigX[]} \leq C_{\bm p, T, {\color{NavyBlue}{\mathbf{v}}}}\,(1 + M_{\bm p}(\sigX[]))^{|{\color{NavyBlue}{\mathbf{v}}}|}\,  \exp \left(C_{\bm p, T}\, (1 + M_{\bm p}(\sigX[]))^{\deg_{{\color{NavyBlue}{\mathbf{1}}}}(\bm p)} \right) < + \infty\,.
    \end{equation}
\end{enumerate}

