[Lemma bound2 of arXiv:2605.28194, 'Delayed Blow-up in 3D Fluids via Pseudo-Transport Noise'] Let $a,b\in \mathbb{R}$ and $M=2b+a-2(1+a+|a|)$. For every progressively measurable process $\varphi\in L^\infty(0,T;H^{2b+a})$, define 
		\begin{align*}
			S^N (\varphi)&=\frac{1}{2}\sum_k (\mathcal{L}_k^N)^2 \varphi=(-\Delta)^{-b}\Pi\big( \sigma_k^N\cdot\nabla (-\Delta)^{a}\Pi\big( \sigma_k^N\cdot\nabla (-\Delta)^{a+b} \varphi\big)\big),\\
			M_t^N &=\sum_k\int_{0}^{t} \mathcal{L}_k^N \varphi\,{\,\rm d} W^k=\sum_k\int_{0}^{t}(-\Delta)^{-b}\Pi\big( \sigma_k^N\cdot\nabla (-\Delta)^{a+b}\varphi\big)\,{\,\rm d} W^k.
		\end{align*}
		Then for every $t,s\in [0,T]$ and $1\leq p<\infty$, we have 
		\begin{align*}
			\|S^N (\varphi)\|_{H^M}&\lesssim_{a,\nu} \|\varphi\|_{H^{2b+a}},\quad \mathbb{P}\text{-a.s.}\\ \mathbb{E}\Big[\|M_t^N-M_s^N\|_{H^M}^p\Big]&\lesssim_{a,\nu,p} |t-s|^{p/2} \|\varphi\|_{L^\infty (0,T;H^{2b+a})}^p.
		\end{align*}

