[Lemma p_conditions of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] Let $T$ be a term of the form (equation general_term of the paper) and recall $d_q(j)$ from Definition (degree_def of the paper).  Assume wlog that the $d_q(j)$ are ordered as $d_q(1) \geq d_q(2) \geq \dots \geq d_q(\#_{\mathcal{I}})$, and recall the high probability bound $\mathcal{M}$ in (equation inFac_high_prob_bound of the paper). There exist non-negative integers $p_j, j = 1,\ldots,\#_{\mathcal{I}}$, and $\hat{p}_j, j=1, \dots, \#_{\mathcal{I}}-1$ satisfying,
		\begin{equation}
			\begin{split}
			& \sum_{j=1}^{\#_{\mathcal{I}}} p_j \leq \mathfrak{r}_2 + 2 \mathfrak{r}_3, \mathrm{ and } \, p_j \leq d_q(j), \; j = 1,\ldots,\#_{\mathcal{I}}, \\ 
			& \sum_{j=1}^{\#_{\mathcal{I}}} \hat{p}_j \leq \mathfrak{r}_2 + \mathfrak{r}_3, \mathrm{ and } \, \hat{p}_1 \leq d_q(1) + d_q(2), \, \hat{p}_j \leq d_q(j+1), \; j=2,\ldots,\#_{\mathcal{I}} - 1, 
			\end{split}

		\end{equation}
		such that for any (small) $\xi_7 > 0$ and sufficiently large $N$ we have 
		\begin{equation}
			\begin{split}
			& \abs{g(t) \frac{N^{d_N}}{N^{\#_{\mathcal{I}}}} \sum_{\mathcal{I}} \kappa(\mathcal{I}) \sum_{\beta \in [[1, K]]^{\#_{\beta}}} \EX\Bigg[(\partial_\beta F) (\widetilde{\mathcal{L}}_{\tau}(X(t))) \prod_{k=1}^{\#_{\beta}} \Bigg(\sum_{\mathcal{J} \in J^{r_k}} \mathfrak{w}_{\mathcal{J}}^{k} \prod_{s=1}^{r_k} \mathrm{IF}(k, s, \mathcal{I}, \mathcal{J}) \Bigg)\Bigg]} \\
			& \leq g(t) N^{\xi_7} N^{d_N} \mathcal{M}^{r_{\sum}} \Bigg( \prod_{k=1}^{\#_{\beta}} \frac{N^{100 \epsilon}}{\tau^{r_k - 1}} \Bigg) \Bigg(\Big(\frac{1}{N \tilde{\eta}}\Big)^{d + \mathfrak{r}_2 + \mathfrak{r}_3 + \mathfrak{c} - \sum_{j=1}^{\#_{\mathcal{I}}} \max\{p_j-3, 0\}}  + \frac{1}{N} \Big(\frac{1}{N \tilde{\eta}}\Big)^{\mathfrak{r}_2 + \mathfrak{r}_3 + n_2^{(\mathrm{tot})} - \sum_{j=1}^{\#_{\mathcal{I}}-1} \max\{\hat{p}_j - 3, 0\}} \Bigg).
			\end{split}

		\end{equation}

