[Lemma 15 (Sampling duality for the Binomial distribution) of arXiv:2606.00781, '2606.00781'] For all $N\in\nz$, $p\in[0,1]$ and $n,m\in\{0,\ldots,N\}$,
   \begin{equation}
      \me\bigg(\frac{(n+K_{N-n,p})_m}{(N)_m}\bigg)\ =\ \me\bigg(\frac{(n)_{m-K_{m,p}}}{(N)_{m-K_{m,p}}}\bigg).
   \end{equation}

