[Prop 87 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] With the notations above,
for every $n\geq 1$, the following decomposition holds:
\begin{displaymath}
:\Phi^{n}: ~=~
\sum_{j=0}^{n} \dfrac{n!}{j! (n-j)!} Q_{n-j}(h_{\mathcal{A}},V_{\mathcal{A}})\,:\Phi_{D\setminus \mathcal{A}}^{j} : \, ,
\end{displaymath}
In particular,
\begin{displaymath}
\E\big[ :\Phi^{n}: \big\vert \mathcal{A}, h_{\mathcal{A}}\big]
= Q_{n}(h_{\mathcal{A}},V_{\mathcal{A}}).
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemmaMoment of arXiv:2604.06012, 'Large fringe trees for random trees with given vertex degrees'] Let $\mathbf{n}$ and ${\mathbf{m}}$ be two degree statistics and let
$\mathcal{T}_{\mathbf{n}} \in {\rm Unif}(\mathbb{T}_{\mathbf{n}})$. 
Then, for every  $q \in \mathbb{N}$, 
we have
\begin{align} 
\operatorname{\mathbb E{}}[(N_{{\mathbf{m}}}(\mathcal{T}_{\mathbf{n}}))_{q}] = |\mathbb{T}_{{\mathbf{m}}}|^{q} \frac{|\mathbf{n}|}{(|\mathbf{n}|)_{q|{\mathbf{m}}|-q+1}} \prod_{i\geq 0} (n(i))_{qm(i)},
\end{align}
where we
(in the case $|\mathbf{n}|< q |{\mathbf{m}}| -q +1$)
interpret $\frac00=0$.
Equivalently, for any tree $T$ with degree statistic ${\mathbf{m}}$, we have
\begin{align} 
\operatorname{\mathbb E{}}[(N_{{\mathbf{m}}}(\mathcal{T}_{\mathbf{n}}))_{q}] = |\mathbb{T}_{{\mathbf{m}}}|^{q} 
\operatorname{\mathbb E{}}[(N_{T}(\mathcal{T}_{\mathbf{n}}))_{q}].
\end{align}

[Lemma lem: separate outer of arXiv:2609.03755, 'The Scramble Number of Outerplanar Graphs'] Let $G$ be a maximal outerplanar graph. Under the isomorphism that maps $G[N(v)\cup\{v\}]$ to $F_{\deg(v)}$, let $x,y\in N(v)$ map to non adjacent path vertices $u_i$ and $u_j$ such that $i<j$. We may produce a cut $C$ such that
    \begin{enumerate}
        \item $C$ disconnects at least two non-empty vertex sets,
        \item the vertices $u_{i+1}, \ldots, u_{j-1}$ lie in the same component, and $v$ lies in another component,
        \item $|C|\leq \deg(x)+\deg(y)+(j-i)$.
    \end{enumerate}

[Theorem 7 (Markov property) of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] For every $\mu$ in the support of the marginal distribution,
\begin{equation}
        \sum_{\lambda\in\SP}K_X^Y(\mu,\lambda)=1.
\end{equation}
Moreover,
\begin{equation}
        \Prob_q^{X,Y}(\mu,\lambda)
        =\pi_{qX,Y}(\mu)K_X^Y(\mu,\lambda),
\end{equation}
where
\begin{equation}
        \pi_{qX,Y}(\mu)=\frac{Q_\mu(qX)P_\mu(Y)}{\Ht(qX;Y)}.
\end{equation}

[Lemma 17 of arXiv:2608.30570, '2608.30570'] Let $\Sigma\subset \mathbb{R}^n$ be a  properly  immersed  surface with
\begin{enumerate}
\item ${\rm {Area}}(\Sigma\cap B_R)\le \Lambda R^2$ for all $R>0$,
\item the genus of $\Sigma$ is finite,
\item there exists $R_k\to \infty$ such that $\lim_{k\to \infty}\int_{(A_{\frac{R_k}{2},4R_k})\cap \Sigma}|{\bf A}|^2d\mu=0$. Here $A_{\frac{R_k}{2},4R_k}=B_{4R_k}(0)\backslash B_{\frac{R_k}{2}}(0)$.
\end{enumerate}
Then the number of ends of  $\Sigma$ is no more  than $2\Lambda$ and they are all annular. More precisely, there exists a large number $R_0>0$ such that $\Sigma\backslash B_{R_0}(0)$ contains finite many  non-compact connected   components
$\{\Sigma_j\}_{j=1}^{N\le 2\Lambda}$, which are all homeomorphic  to $\mathbb{D}^c=\{z\in \mathbb{C}||z|\ge 1\}$.
Moreover, for each $j\in \{1,2,\ldots, N\}$ and $k$ large, if $x_k\in \Sigma_j\cap \partial B_{\frac{3R_k}{2}}$, then,  there exist a positive integer $d= d_{j,k}\le \frac{\Lambda}{3\pi}$ and   a conformal parameterization $f: D_{(2R_k)^{\frac{1}{d}}}\backslash D_{R_k^{\frac{1}{d}}}\to \Omega_{R_k}$ for some domain $\Omega_{R_k}\subset \Sigma_j$  containing $x_k$ and satisfying
\begin{align*}
d_{H}(\left(\Sigma_j\cap (B_{2R_k}\backslash B_{R_k})\right)_{x},\Omega_{R_k})\le \psi(\epsilon_k)R_k
\end{align*}
such that  $df\otimes df=e^{2u}g_{\mathbb{R}^2}$ and  for any $ z\in D_{(2R_k)^{\frac{1}{d}}}\backslash D_{(R_k)^{\frac{1}{d}}}$, there holds
\begin{align} 
C^{-1}\le \frac{e^{2u}}{d^2|z|^{2d-2}}\le C
\end{align}
\begin{align}
1-\psi(\epsilon_k)\le \frac{|f(z)|}{|z|^d}\le 1+\psi(\epsilon_k).
\end{align}

[Prop 15 of arXiv:2606.21433, 'Central limit theorem for\\ the averaged Adam optimizer'] We assume the setting of \cref{thm-1}.
Let $n^*\in\N$ and consider the stopping time
\bas{ T_{n^*}'=\inf\{n\ge n^*: \theta_n\not \in V \}.
}
Moreover, let for all $k\in\N$, $r(k)=\lfloor k-(\log k)^2\rfloor$, $v^*$  as in \cref{def:v_star},
\bas{

  \cE'_k=\{\forall i\in\{1,\dots,d\}\exists \text{distinct }&\ell_1,\ell_2\in\{n^*+1,\dots, k-1\}\text{ with }
\\&
  (X^{(i)}(\theta_{\ell_1-1},U_{ \ell_1}))^2\wedge (X^{(i)}(\theta_{\ell_2-1},U_{ \ell_2}))^2\ge \delta\} ,
}
\bas{

  \tilde \cE'_k=\{\forall i\in\{1,\dots,d\}\exists \text{distinct }&\ell_1,\ell_2\in\{r(k),\dots, k-1\}\text{ with }
\\
&
  (X^{(i)}(\theta^*,U_{ \ell_1}))^2\wedge (X^{(i)}(\theta^*,U_{\ell_2}))^2\ge \delta\}
}
and
\bas{

  \tilde \cE''_k=\bigl\{\bigl\|(\1_{\{k+\ell<r(k)\}}\,X(\theta^*,U_{k+\ell}))_{\ell\in-\N_0}\bigr\|_{\ell_\varrho^d}\le 1\bigr\} .
}
One has
\bas{

  \lim_{ k \to \infty }
  \gamma_{ r( k ) }
  (\log k)^2/\sqrt{\gamma_{k-1}}=0
}
and there exists $ \kappa \in (0,\infty) $ such that the following is true:
\begin{enumerate}[label=(\roman*)]
\item

Almost surely, on $\{T_{n^*}'=\infty\}$, all but finitely of the events $(\cE'_k)_{k\in\N}$ occur and  for all $k\in\N$ with $k>n^*$ and all  $i\in\{1,\dots,d\}$
\bas{
\E\bigl[\1_{\{T_{n^*}'=\infty\}}\1_{\cE'_k}v^*(\bX^{(i)}(k))^{-1}\bigr]\le \kappa.
}
\item

Almost surely,  all but finitely many of the events $(\tilde \cE'_k)_{k\in\N}$ and $(\tilde \cE''_k)_{k\in\N}$ occur and there exists  $\kappa\in(0,\infty)$ such that for all $k\in\N$ with $r(k)\ge1$ and all  $i\in\{1,\dots,d\}$
\bas{
\E\bigl[\1_{\tilde \cE_k'}v^*(\tilde \bX^{(i)}(k-1))^{-1}\big|\cF_{r(k)-1}\bigr]\le \kappa,}
where $\tilde \bX(k)=(X(\theta^*,U_{k+\ell}))_{\ell\in-\N_0}$.
\end{enumerate}

