[Lemma lem:form_core_2 of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\Omega$ be an open subset of $\mathbb G$. Then, $((\mathcal{E}^\phi)^\Omega, (\mathcal{F}^\phi)^\Omega)$ is a regular Dirichlet form on $L^2(\Omega,dx)$. Moreover, $C^\infty_c(\Omega)$ is a form core for $\mathcal{E}^{\phi,\Omega}$. As a result, the generator associated with $\mathcal{E}^{\phi,\Omega}$ is the Friedrichs extension of $(\mathcal{L}^\phi_\Omega, C^\infty_c(\Omega))$ in $L^2(\Omega, dx)$, where for any $f\in C^\infty_c(\Omega)$,
    \begin{align*}
        \mathcal{L}^\phi_\Omega f = \left.\Delta^\phi_\Omega f^0\right|_{\Omega},
    \end{align*}
    with 
    \begin{align*}
        f^0(x)=\begin{cases}
            f(x) & \mbox{if $x\in\Omega$} \\ 
            0 & \mbox{if $x\in\Omega^c$}.
        \end{cases}
    \end{align*}

[Corollary fpcomm-onlyh of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] Let $ X=(X_t)_{t\in[0,T]} $ be the solutions of ((SDEscomxh of the paper)), if $ h(x) $ is $ C^{\infty} $ bounded function. Then the memory-dependent PDEE for PDFs $ p(x,t) $ of the solutions $ X_t $, satisfies the following equation
		\begin{align}
		\frac{\partial }{\partial t}p(x,t)=-\frac{\partial }{\partial x}\big\{Ht^{2H-1}h'(x)h(x)p(x,t)\big\}
		+\frac{\partial^2 }{\partial x^2}\big\{Ht^{2H-1}h^2(x)p(x,t)\big\},
		\end{align}
		which has the exact solution
		\begin{align*}
		p(x,t)=C_1\frac{1}{\sqrt{\frac{1}{2}t^{2H}h^2(x)}}\exp\bigg\{-\frac{\hat{x}^2(x)}{2t^{2H}}\bigg\},
		\end{align*}
		where $ C_1 $ is the normalization constant, $ \hat{x}(x)=\int_{x_0}^{x}\frac{1}{h(x)}\mathrm{d}x $, and the initial condition is given by $p(x,0)=\delta(x-x_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] Let $r\ge1$. The $r$th factorial moment $\Phi^\alpha(r,t)=\mathbb{E}(\hat{M}^\alpha(t)(\hat{M}^\alpha(t)-1)\dots(\hat{M}^\alpha(t)-r+1))$ of time-changed IGCP is given by
\begin{equation*}
\Phi^\alpha(r,t)=\sum_{n=1}^{r}\frac{r!}{\Gamma(n\alpha+1)}t^{n\alpha}\sum_{\substack{\sum_{l=1}^{n}m_l=r\\m_l\in\mathbb{N}}}\prod_{l=1}^{n}\sum_{j_0=1}^{k_0}\mu_{j_0}\sum_{s=0}^{\infty}\frac{j_0^s}{s!}\sum_{\substack{\sum_{i=1}^{s}x_i=m_l\\x_i\in\mathbb{N}_0}}\prod_{i=1}^{s}\frac{1}{x_i!}\sum_{j=1}^{k}\lambda_j(j)_{x_i},
\end{equation*}
where $(j)_{x_i}=j(j-1)\dots(j-x_i+1)$ denotes the falling factorial.

[Lemma 62 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $U,V$ be quasi-Banach spaces and let $T\colon U\to V$ be a compact linear map and let $t\in(0,\infty)$.
    Assume that 
    \begin{equation*}
       \limsup_{k\to \infty} \bigl( k^{t} \cdot \en_k(T)\bigr) <\infty.
    \end{equation*}
    Then $\bigl(T(\ball_U),\, \norm{\cdot \mid V}\bigr)$ is totally bounded and we have $\umd\bigl(T(\ball_U)\bigr) \le \frac{1}{t}$.

[Prop 79 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $K$ be a bounded kernel on $(E, \cb)$.

Then the following assertions hold.

\begin{enumerate}
    \item[(i)] There exists a right process $X^K=(\Omega^K, \mathcal{F}^K, \mathcal{F}^K_t , X^K(t), \theta^K(t) , \mathbb{P}^{K}_{x})$ with state space $E$, having the generator
    \begin{equation*}
        (\mathcal{L}-K1+ K, \mathcal{D}_b(\mathcal{L}-K1+K)) \quad \mbox{and} \quad \mathcal{D}_b(\mathcal{L}-K1+K)= \mathcal{D}_b(\mathcal{L}).
    \end{equation*}
    Moreover, the fine topology induced by (the resolvent of) $X^K$ coincides with that induced by $X$.
    \item[(ii)] 
    The process $X^K$ solves the martingale problem for $(\mathcal{L}-K1+ K, \mathcal{D}_b(\mathcal{L})))$ under $\mathbb{P}^{K}_x$. 
    More precisely, for every $f\in \mathcal{D}_b(\mathcal{L})$ and $x\in E$ the process
    \begin{equation}
        \left(f(X^K(t))-  f(X^K (0)) -\int_0^t (\mathcal{L}f-K1 f + Kf)(X^K (s)) ds\right)_{t\geqslant 0}
    \end{equation}
    is a c\`adl\`ag $(\mathcal{F}^K_t)$-martingale under $\mathbb{P}^{K}_{x}$.
\end{enumerate}

[Theorem Main-Theorem-1 of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] For every $\varepsilon,\delta(\varepsilon)>0$, let $\theta_{\varepsilon,\delta(\varepsilon)}$ be a stochastic generalized Leray solution of (equation SPDE-SQG of the paper) in the sense of Definition (def-stochastic-leray of the paper) with initial data $ \theta_{\varepsilon, \delta(\varepsilon)}(0)$ satisfying Assumption (Gaussian-initial-data of the paper). Let $\mu_{\varepsilon}=\mu_{\varepsilon,\delta(\varepsilon)}$ be the laws of $\theta_{\varepsilon,\delta(\varepsilon)}$ on $\mathbb{X}_{\alpha,\beta}$. Let $ \mathcal{C}_0\subset\mathbb{X}_{\alpha,\beta}$ be a weak-strong uniqueness class of (equation PDE-SQG of the paper) and   $\mathcal{C}=\overline{\mathcal{C}_0}^{\mathcal{I}}$. Assume that the scaling regime (equation scaling-delta of the paper) holds for $(\varepsilon,\delta(\varepsilon))$. Then for any closed set $F\subset\mathbb{X}_{\alpha,\beta}$,
	\begin{equation*}
		\limsup_{\varepsilon\rightarrow0}\varepsilon\log\mu_{\varepsilon}(F)\leqslant-\inf_{\theta\in F}\mathcal{I}(\theta),  	
	\end{equation*}
	and for any open set $G\subset\mathbb{X}_{\alpha,\beta}$, 	\begin{equation*}
		\liminf_{\varepsilon\rightarrow0}\varepsilon\log\mu_{\varepsilon}(G)\geqslant-\inf_{\theta\in G\cap \mathcal{C}}\mathcal{I}(\theta). 	
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

