body:
[Lemm l:regcomp of arXiv:2607.18194, 'Temperature chaos in directed polymers'] There exists $c>0$ such that for all sufficiently small $\varepsilon>0$,
    \begin{align*}
        \limsup_{n\to\infty}
        \mathbb{P}(\neg\mathsf{PolymerTF}_{\varepsilon,n})
        \leqslant
        e^{-c\log^2(1/\varepsilon)}. 
    \end{align*}

[Definition 58 of arXiv:2608.29086, '2608.29086'] [Edge-continuous sections] 
Given $M \subset H_0$ and $\sigma \in \Gamma (M)$, $\sigma$ is called \textit{edge-continuous} if 
\begin{equation*}
 e_{\sigma(abc)}(ab)= e_{\sigma(abd)}(ab)
\end{equation*}
for any pair $abc$, $abd \in Tri(M)$ sharing an edge $ab$.

[Corollary 7 of arXiv:2506.18063, 'Reduced critical branching processes in non-favorable random environment \thanks{ This wor'] Assume that Condition $B1$ is valid. Let $H_{1},H_{2},...,$
be a nonnegative sequence of random variables adapted to the filtration $
\mathcal{\tilde{F}=}\left\{ \mathcal{F}_{l},l\in \mathbb{N}\right\} ,$ and
converging $\mathbf{P}_{0}^{+}$-a.s. to a random variable $H_{\infty }$ as $
n\rightarrow \infty $. If either $k\sim \theta m,\theta >0,$ or $\min
(r,n-r)\gg k$, or $k\sim \theta r,\theta >0,$ or $k\gg r,$ then, for all
positive $y,t,$ and $\lambda $
\begin{equation*}
\lim_{k\bot r\rightarrow \infty }\mathbf{E}\left[ e^{-\lambda H_{n}}|S_{\tau
_{r,n}}\leq ya_{k\bot r},S_{n}\leq ta_{k},L_{n}\geq 0\right] =\mathbf{E}
_{0}^{+}\left[ e^{-\lambda H_{\infty }}\right] ,
\end{equation*}
and, therefore,
\begin{equation*}
\lim_{k\bot r\rightarrow \infty }\mathbf{P}\left( H_{n}>x|S_{\tau
_{r,n}}\leq ya_{k\bot r},S_{n}\leq ta_{k},L_{n}\geq 0\right) =\mathbf{P}
_{0}^{+}\left( H_{\infty }>x\right)
\end{equation*}
for any continuity point of the distribution of $H_{\infty }$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2608.01081, 'The Optimal Rate in the Averaged Random-Marginal Central Limit Theorem for Log-Concave Mea'] For $i+j\le3$,
\begin{align}
 |\partial_a^i\partial_b^jL(a,b)|
 &\le C_{i,j}n^{-1-i-j},\\
 |\partial_a^i\partial_b^jQ(a,b)|
 &\le C_{i,j}n^{-2-i-j}.
\end{align}
Moreover,
\begin{equation}
 |C_3(a,b)|\le Cn^{-3},
 \qquad
 |\nabla C_3(a,b)|\le Cn^{-4}.
\end{equation}
On the support of $\chi_n$, whenever $A-2z\ge\alpha_1 n$,
\begin{equation}
 |\mathcal R_4(a,b,z)|\le Cn^{-4}|z|^4.
\end{equation}

[Proposition CLTforUn of arXiv:2411.04603, 'The nonexplosive solution of explosive autoregressions'] {\rm(}Mixing CLT for $U_n$ and $Y_n${\rm)} We have
\begin{displaymath}
\frac{1}{\sqrt{n}}\sum_{k=1}^nU_k\rightarrow\frac{\sigma}{\sum_{i=1}^d\theta_i-1}
\begin{pmatrix}
1     \\
1     \\
\vdots\\
1
\end{pmatrix}
N_1\quad{\mathcal G}\text{-mixing as }n\to\infty\,,
\end{displaymath}
where ${\mathcal G}=\sigma\left(Z_j,j\geq1\right)$, $P^{N_1}=N\left(0,1\right)$ and $N_1$ is independent of ${\mathcal G}$.
In particular,
\begin{displaymath}
\frac{1}{\sqrt{n}}\sum_{k=1}^nY_k\rightarrow\frac{\sigma}{\sum_{i=1}^d\theta_i-1}
N_1\quad{\mathcal G}\text{-mixing as }n\to\infty\,.
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

