[Corollary 46 of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] Let~$w=w_{\ell x'+i',2y'+j'}$ and~$b=b_{\ell x+i,2y+j}$ be non-boundary vertices in the reduced Aztec diamond. 

The Coulomb gauge functions~$\mathcal F^\bullet$ and~$\mathcal F^\circ$ defined in Proposition~\ref{prop:FG} are given by
\begin{equation*}
 \mathcal F^\bullet(b)=
\frac{1}{2\pi\i}\int_{\tilde \Gamma}\left(f(z)Q(z,w)
  \prod_{m=1}^{2i}\phi_m(z)\right)_{j+1}(z-1)^{\ell N}\frac{w^{x-N}}{z^{y}}\frac{\d z}{z},
\end{equation*}
and
\begin{equation}
\mathcal F^\circ(w)
=\frac{1}{2\pi\i}\int_{\tilde \Gamma}\left(\left(\prod_{m=1}^{2i'+1}\phi_m(z)\right)^{-1}Q(z,w)
  g(z)
  \right)_{j'+1} \frac{z^{y'}}{(z-1)^{\ell N}w^{x'-N}}\d z,
\end{equation}
where 
\begin{equation}
f(z)=\sqrt{a+\i}\left(-\frac{\i\alpha_1}{z-1}
\begin{pmatrix}
1 & -\alpha_1^{-1}
\end{pmatrix}
-\frac{\beta_\ell a}{z-1}
\begin{pmatrix}
1 & \beta_\ell^{-1}
\end{pmatrix}
\right)
=\frac{\sqrt{a+\i}\left(\i-a\right)}{z-1}
\begin{pmatrix}
\i\sqrt{\alpha_1\beta_\ell} & 1
\end{pmatrix}
\end{equation}
and
\begin{equation}
g(z)=\sqrt{a-\i}\left(\frac{\i}{\sqrt{\alpha_1\beta_\ell}}\frac{1}{z}
\begin{pmatrix}
 1 \\
 0
\end{pmatrix}
+
\begin{pmatrix}
  0 \\
  1
\end{pmatrix}
\right)
\end{equation}

and~$\tilde \Gamma=\tilde \Gamma_s$ is as in Lemma~\ref{lem:bdry_bulk}.

