[Proposition propo-stab- of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] (Stability and uniqueness)
      Let $f_1$ and $f_2$ be two solutions to  (equation fom-limit-1 of the paper) with initial data $f_0^1\in H_0$ and $f_0^2\in H_0$ respectively. Then, we have
      \begin{align*}
          \Vert f_1(t)-f_2(t)\Vert_{H_0}^2+2\int_0^t\int_{\mathbb{T}^2}\int_D\bigl(\widetilde{\mathbf{M}}_0 (\dfrac{1}{\beta}+\dfrac{k_T}{2}\vert r\vert^2)\vert \nabla_r(\dfrac{f_1-f_2}{\widetilde{\mathbf{M}}_0})\vert^2 drdxds \leq   \Vert f_0^1-f_0^2\Vert_{H_0}^2.
      \end{align*}
      In particular, the solution to (equation fom-limit-1 of the paper) is unique. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 15 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] Let $h \in {T/{\mathbb N}^*}$
and $\varphi \in {\mathcal C}^1({\mathbb S}) \cap {\mathcal U}^2({\mathbb S})$ such that $\varphi'({\mathbf x})=0$ if,  for some $\varsigma \in (0,1/4)$, ${\mathbf x} 
\in \cup_{k \in {\mathbb Z}/2}
(k-\varsigma,k+\varsigma)$. For a given $\varepsilon >0$, let 
\begin{equation}
   E_\varepsilon(\mathbf{x}) := {\varepsilon}\begin{cases} 1& \,\,{x}\in [0,1/2)+{\mathbb Z},
   \\
   -1& \,\,  {x}\in [-1/2,0)+{\mathbb Z},
    \end{cases}
\end{equation} 
Then, for $g$, a smooth symmetric density on ${\mathbb R}$ with support included in $(-\varsigma,\varsigma)$, and for all $0 \leq s \leq t$,

\begin{equation}
	\langle \varphi\star g, \mathscr{J}_{t}(X^{(h)}) -\mathscr{J}_{s}(X^{(h)}) \rangle\geq\frac{1}{2}\sum_{j=N_s+1}^{N_t} \int_0^h\int_{\mathbb{S}} \phi'(\mathbf{x})\frac{1}{E_\varepsilon(\mathbf{x}) +[g\star D_{\mathbf{x}}F_{\mu_{j},r}^{-1}](\mathbf{x})}\mathrm{d}\mathbf{x}\mathrm{d}r.
\end{equation}

[Lemma 10 (Global smoothing by convolutions) of arXiv:2606.07290, 'Boundary behaviour of the Volterra square-root process'] Let $T > 0$, $K \in C^{\infty}((0,T])$ and assume that there exists $\rho \in (0,1)$ such that for every integer $m\ge 0$ there exists a constant $C_m > 0$ with the property
\begin{align}
|K^{(m)}(t)| \le C_m\, t^{\rho-1-m}, \qquad t \in (0,T].
\end{align} 
Let $\eta \in [0,1)$ such that $\eta+\rho \notin \mathbb{N}$ and $m \ge 0$. Then for each function $f \in C^{m, \eta}([0,T])$ satisfying $f(0) = f'(0) = \dots = f^{(m)}(0) = 0$, the convolution $\mathcal{K}f$ has the Hölder regularity
\[
\mathcal{K}f \in \begin{cases} 
C^{m,\eta+\rho}([0,T]), & \quad\text{if }\eta+\rho<1, \\ 
C^{m+1,\eta+\rho-1}([0,T]), & \quad\text{if } \eta+\rho>1. 
\end{cases}
\]

