[Proposition 18 (Laplace asymptotics in the bulk regime) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] Fix $1<p<\infty$, an integer $r\ge 1$, and complex parameters
\begin{equation}
\lambda_1,\dots,\lambda_r\in\mathbb C,
\qquad
\Re \lambda_j>\max\{-1,1-p\},\quad j=1,\dots,r.
\end{equation}
Put $\Lambda:=\lambda_1+\cdots+\lambda_r$.
For every integer $n\geq 2$ let  $j(n)\in \{0,\ldots, n-1\}$ and suppose that
\[
\alpha(n) := \frac{j(n)}{n}\to \alpha\in(0,1).
\]
For $\beta\in(0,1)$, let $\Psi_{p,\beta}: (0,\infty)\to\R$ and its unique global maximizer $\theta_{p,\beta}$  be defined as in Proposition~\ref{prop:maximizer_Phi_p_beta}. Then $\theta_{p,\alpha(n)}\to \theta_{p,\alpha}$ as $n\to\infty$, and the following assertions hold:

\vspace{2mm}
\noindent
(i) Absolute asymptotic: As $n\to\infty$, one has
\[
\begin{aligned}
I_{n,j(n)}&(\lambda_1,\dots,\lambda_r)
\sim
\frac{p(p-1)^{n-j(n)-1}\,n\binom{n-1}{j(n)}}{2\pi^{(n-j(n))/2}\,
\Gamma\!\left(\frac{j(n)+\Lambda+p}{p}\right)}
\,
\sqrt{\frac{2\pi}{n\,|\Psi_{p,\alpha(n)}''(\theta_{p,\alpha(n)})|}}
\,
\frac{\mathcal{K}_p(\theta_{p,\alpha(n)})}
{\theta_{p,\alpha(n)}\,\mathcal{J}_p(\theta_{p,\alpha(n)})}
\\
&\times
\,e^{\,n\Psi_{p,\alpha(n)}(\theta_{p,\alpha(n)})}
\prod_{j=1}^r
\left(
\alpha(n)\frac{\mathcal F_p(\theta_{p,\alpha(n)};\lambda_j)}{\mathcal F_p(\theta_{p,\alpha(n)};0)}
+
(1-\alpha(n)) \frac{\mathcal F_p(\theta_{p,\alpha(n)};\lambda_j+p-2)}{\mathcal F_p(\theta_{p,\alpha(n)};p-2)}
\right).
\end{aligned}
\]
In particular, for $\lambda_1= \ldots = \lambda_r = 0$ this formula takes the form
\begin{equation}
I_{n,j(n)}(0,\dots,0)
\sim
\frac{p(p-1)^{n-j(n)-1}\,n\binom{n-1}{j(n)}}{2\pi^{(n-j(n))/2}\,
\Gamma\!\left(\frac{j(n)+p}{p}\right)}
\,
\frac{\mathcal K_p(\theta_{p,\alpha(n)})}{\theta_{p,\alpha(n)}\,\mathcal J_p(\theta_{p,\alpha(n)})}
\,
e^{\,n\Psi_{p,\alpha(n)}(\theta_{p,\alpha(n)})}
\sqrt{\frac{2\pi}{n\,|\Psi_{p,\alpha(n)}''(\theta_{p,\alpha(n)})|}}.
\end{equation}

\vspace{2mm}
\noindent
(ii) Relative asymptotic: As $n\to\infty$, one has
\[
\frac{I_{n,j(n)}(\lambda_1,\dots,\lambda_r)}{I_{n,j(n)}(0,\ldots, 0)}
\sim
\left(\frac{p}{\alpha \, n}\right)^{\Lambda/p}
\prod_{j=1}^r
\left(
\alpha\frac{\mathcal F_p(\theta_{p,\alpha};\lambda_j)}{\mathcal F_p(\theta_{p,\alpha};0)}
+
(1-\alpha)\frac{\mathcal F_p(\theta_{p,\alpha};\lambda_j+p-2)}{\mathcal F_p(\theta_{p,\alpha};p-2)}
\right).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_exit_exp of arXiv:2603.29442, 'A compact support property for infinite-dimensional SDEs with Hölder continuous coefficien'] There are constants $C_1 \geq 1$ and $c_2> 0$ such that for sufficiently small $\zeta$, for all $\delta \in (0,1]$ and $\mathbb{P} \in \mathscr{M}_{\gamma,\delta}((0,2\zeta))$,
	\begin{equation*}
		\mathbb{P}(\tau_0 \wedge \tau_{2\zeta} > m \zeta^{2-2\gamma}) \leq C_1 e^{-c_2 m}
	\end{equation*}
	for all $m \in \mathbb{N}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 131 (Power range and diagonal logarithmic endpoint) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $1\le q<\infty$.
\begin{enumerate}
\item If
\begin{equation}

 a>\beta,\qquad b>\beta,\qquad
 a+b>\beta+\delta,
\end{equation}
then $\mathcal M\in\ell^q(\Dya^2)$ for arbitrary fixed
$\kappa,\alpha,\zeta\in\R$.  Every closed subregion with positive
distance from the three boundary hyperplanes has a polynomial
high-scale tail.  More precisely, if
\[
 \rho:=\min\{a-\beta,b-\beta,a+b-\beta-\delta\}>0,
\]
then, for every $0<\sigma<\rho$,
\begin{equation}

 \norm{\mathcal M\mathbf1_{\{L\vee M>R\}}}_{\ell^q(\Dya^2)}
 \lesssim_\sigma R^{-\sigma},\qquad R\ge2.
\end{equation}

\item Suppose
\begin{equation}

 a>\beta,\qquad b>\beta,\qquad
 a+b=\beta+\delta.
\end{equation}
This two-sided face is nonempty in $(a,b)$ precisely when $\beta<\delta$.
Then
\begin{equation}

 \mathcal M\in\ell^q(\Dya^2)
 \quad\Longleftrightarrow\quad
 \alpha+\zeta>\kappa+\frac1q.
\end{equation}
If this condition holds and
$\rho_{\log}:=\alpha+\zeta-\kappa-1/q$, then
\begin{equation}

 \norm{\mathcal M\mathbf1_{\{L\vee M>R\}}}_{\ell^q(\Dya^2)}
 \asymp \ell_R^{-\rho_{\log}},\qquad R\ge2.
\end{equation}
\end{enumerate}

[Prop long-term-est1 of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $M$ be an irreducible generator. 
    Then, for any $\delta \in (0,1)$ there exists an $\alpha_\ast>0$ such that for all initial data $\zeta_0, \mu_0 \in \mathcal{P}(\ensuremath{\mathbb{Z}})$ and corresponding solutions $\zeta_t, \mu_t$ of the forward Kolmogorov equation (equation eq:full-forw-K of the paper) holds 
    \begin{equation}
       0< \alpha_\ast \leq \alpha_{\gLSI}(\zeta_t) \leq 2\alpha_{\gPI} (\zeta_t)
    \end{equation}
    for all $t \geq \delta$ and 
    \begin{equation}
        \operatorname{var}_{\zeta_t} \biggl( \frac{\mu_t}{\zeta_t}\biggr)\leq \operatorname{var}_{\zeta_0}\biggl( \frac{\mu_0}{\zeta_0}\biggr) \min\left(1,e^{-\alpha_\ast (t - \delta)}\right),
        \ \  \mathscr{H}_{\zeta_t} \biggl( \frac{\mu_t}{\zeta_t}\biggr)\leq \mathscr{H}_{\zeta_0}\biggl( \frac{\mu_0}{\zeta_0}\biggr) \min\left(1,e^{-\alpha_\ast (t - \delta)}\right)
    \end{equation}
    for all $t \geq 0$.

