[Lemma eq:f^ER_dense of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Consider the Bass and {\rm SI} models~(equation eqs:Bass-ER-dense of the paper) on  $\lim_{M \to \infty}{\cal G}(M,\alpha)$.
	Then  
	\begin{equation}

		f^{\rm ER}_{\rm dense}(t;p,q,\alpha,I^0)
		= \frac{1-\displaystyle\frac{1-I^0}{p+q\alphaI^0}e^{-(p+q\alpha)t}}{1+q\alpha\displaystyle \frac{1-I^0}{p+q\alphaI^0}e^{-(p+q\alpha)t}}.
	\end{equation}
	In particular,
	\begin{itemize}
		\item 
		If there are no adopters at $t=0$, then
		\begin{subequations}

			\begin{equation}

				f^{\rm ER}_{\rm Bass, dense}(t;p,q,\alpha)=f_{\rm Bass}(t;p,q\alpha),
			\end{equation}
			where
			$f^{\rm ER}_{\rm Bass, dense}(\cdot):=f^{\rm ER}_{\rm  dense}(\cdot,I^0=0)$ and 
			$f_{\rm Bass}$ is given by~(equation eq:Bass_sol of the paper).

			\item 
			If there are no external influences, then
			\begin{equation}

				f^{\rm ER}_{\rm SI, \, dense}(t;q,\alpha,I^0)=I_{\rm SI}(t;q\alpha,I^0),
			\end{equation}
		\end{subequations}
		where 
		$f^{\rm ER}_{\rm SI, dense}(\cdot):=f^{\rm ER}_{\rm  dense}(\cdot,p=0)$ and 
		$I_{\rm SI}$ is given by~(equation eq:si-explicit-sol of the paper).
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 3 (Differentiation in the Cameron--Martin space directions) of arXiv:2608.02417, 'A Bismut--Elworthy--Li formula for linear stochastic evolution equations in Banach spaces'] Let \(R\in \gamma(\scrH,E)\), and let \(g:E\to\R\) be bounded and Borel measurable. Then for every \(h\in \scrH\) the map
\[
    \varepsilon\mapsto \E g(X_R+\varepsilon Rh)
\]
is differentiable at \(0\) and
\begin{equation}
    \Bigl.\frac{\rm d}{{\rm d}\varepsilon}\Bigr|_{\varepsilon=0}
    \E g(X_R+\varepsilon Rh) = \E[g(X_R)W(h)].
\end{equation}

[Lemma lem:logistic-moments-short of arXiv:2608.05123, 'A central limit theorem for the random assignment problem'] For the logistic law \(\ell(u)\,\mathrm d u\), let \(x=L(u)\) and
\(b(x)=-\log(1-x)\).  Then
\begin{equation}
 \overline F_\ell(d\mid u)=\frac{L(u-d)}{L(u)},\qquad
 m_\ell(u)=\frac{b(x)}x,\qquad
 \mathcal M(\ell)=\zeta(2),
\end{equation}
and
\begin{equation}
 v_{\rm row}:=\mathcal V(\ell)=4\zeta(3)-2\zeta(2).
\end{equation}

[Lemma L: fourth_moment_to_cumulants of arXiv:2606.18654, 'Rigidity of infinite exchangeable sequences with Gaussian marginals'] Let $\lambda$ be a probability measure on $\mathbb{R}$ with finite fourth moment. Let $Y_1$ and $Y_2$ be independent with common law $\lambda$. Let $v(\lambda)$ and $\kappa_4(\lambda)$ be the variance and fourth cumulant of $\lambda$, respectively. Then
        \begin{equation*}
            \mathbb{E}\left[(Y_1-Y_2)^4\right] = 12v(\lambda)^2 + 2 \kappa_4(\lambda).
        \end{equation*}

