body:
[Proposition 11 (Ricci and scalar curvature) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] For the metric \eqref{eq:ansatz-metric}, with $X, Y \in \mathcal{H}$ basic horizontal (block decomposition $X = \sum_i X_i$), $\xi^* = \xi/H$ the unit Reeb field, $\nu = \partial_s$, 

	\emph{(i) Vertical components.}
	\begin{align}

		\operatorname{Ric}(\nu, \nu) &\;=\; -\frac{H''}{H} \;-\; \sum_{i=1}^r n_i \left( \frac{q_i H' + \kappa_i'}{F_i^2} \;-\; \frac{(q_i H + \kappa_i)^2}{2 F_i^4} \right),\\

		\operatorname{Ric}(\xi^*, \xi^*) &\;=\; -\frac{H''}{H} \;+\; \sum_{i=1}^r n_i \left( \frac{q_i^2 H^2}{2 F_i^4} \;-\; \frac{H'}{H}\, \frac{q_i H + \kappa_i}{F_i^2} \right).
	\end{align}

	\emph{(ii) Mixed components vanish:} $\operatorname{Ric}(\nu, \xi^*) = 0$ and $\operatorname{Ric}(X, \nu) = \operatorname{Ric}(X, \xi^*) = 0$.

	\emph{(iii) Horizontal components.} $\operatorname{Ric}(X, Y) = \sum_{i=1}^r \mathcal{R}_i\; \pi^*g_i(X_i, Y_i)$, where
	\begin{equation}
		\mathcal{R}_i \;=\; p_i \;-\; \frac{q_i H' + \kappa_i'}{2} \;-\; \frac{H'}{2H}\,(q_i H + \kappa_i) \;+\; \frac{\kappa_i\,(2 q_i H + \kappa_i)}{2 F_i^2} \;-\; \frac{q_i H + \kappa_i}{2} \sum_{j=1}^r \frac{n_j\,(q_j H + \kappa_j)}{F_j^2} \,.
	\end{equation}

	\emph{(iv) Scalar curvature.}
		\begin{equation}
		\begin{aligned}
			&\mathrm{R}_g \;=\; -\frac{2H''}{H} \;+\; \sum_{i=1}^r n_i \left( \frac{2 p_i}{F_i^2} \;-\; \frac{q_i^2 H^2}{2 F_i^4} \;-\; \frac{2\,(q_i H' + \kappa_i')}{F_i^2} \;-\; \frac{2H'}{H}\, \frac{q_i H + \kappa_i}{F_i^2} \;+\; \frac{3\,(q_i H + \kappa_i)^2}{2 F_i^4} \right) \\
			&\qquad \;-\; \left( \sum_{i=1}^r \frac{n_i\,(q_i H + \kappa_i)}{F_i^2} \right)^{2} .
		\end{aligned}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 25 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] The $H$-algebra $A$ (of class $\mathcal{C}^{\infty}$) on $\mathbb{R}^{d}_{y}$ is said to be stochastic $\Phi$-proper (resp. stochastic $\Phi$-pseudoproper) if the following two conditions are satisfied: 
		\begin{itemize}
			\item[(i)] $A$ is $\Phi$-total.
			\item[(ii)] For each bounded open set $Q$ in $\mathbb{R}^{d}_{x}$, the Orlicz-Sobolev space $W^{1}L^{\Phi}_{D_{x}}(Q; L^{\Phi}(\Omega))$ (resp. $W^{1}_{0}L^{\Phi}_{D_{x}}(Q; L^{\Phi}(\Omega))$) is stochastically $\Sigma$-reflexive (for $A$).
		\end{itemize}

[Lem deter-lemma:no_bushes of arXiv:2601.00119, 'The largest common subtree of two random trees'] Assume that $2+4n^{1/2-2\alpha}<n^{1/2-\alpha}$. If $B_n^{(4)}$ occurs, then at least one of the two following situations happens.
\begin{enumerate}
    \item[\emph{(i)}] There exist $v\in\tau$ and $v'\in\tau'$ such that $n^{-\alpha}\operatorname{LCS}^\bullet(\theta_v\tau,\theta_{v'}\tau')>\mathrm{Ht}(\theta_v\tau)\wedge\mathrm{Ht}(\theta_{v'}\tau')+1$.
    \item[\emph{(ii)}] There exists $u\in\tau$ such that $\sum_{j=1}^{\mathrm{k}_u(\tau)}\big(\mathrm{Ht}(\theta_{u*j}\tau)+1\big)\wedge n^{1/2-3\alpha}>\tfrac{1}{2}n^{1/2-2\alpha}$.
\end{enumerate}

[Lemma Had1 of arXiv:2411.15830, 'Deformations of biorthogonal ensembles and universality'] For a $k\times k$ matrix $M$, denote its $j$-th column by $M_j \in \mathbb{C}^k$, and for a vector $v=(v_1,\cdots, v_k)^T\in \mathbb{C}^k$ denote

    $$
    \|v\|_2\mathrel{\vcenter{\baselineskip0.5ex \lineskiplimit0pt
                     \hbox{\scriptsize.}\hbox{\scriptsize.}}}
                     = \left(\sum_{i=1}^k |v_i|^2 \right)^{1/2},\quad \|v\|_\infty \mathrel{\vcenter{\baselineskip0.5ex \lineskiplimit0pt
                     \hbox{\scriptsize.}\hbox{\scriptsize.}}}
                     = \sup_{1\leq i\leq k} |v_i|.
    $$

    Then for any $k\times k$ matrices $M$ and $L$, the inequalities

\begin{equation}
    |\det M|\leq \prod_{i=1}^k \|M_i\|_2
\end{equation}

    and

\begin{equation}
    |\det M - \det L|\leq k^{k/2}\left(\max_{1\leq i\leq k} (\|M_i\|_\infty, \|L_i\|_\infty) \right)^{k-1}\max_{1\leq i\leq k} \|M_i-L_i\|_\infty
\end{equation}

    hold true.

