body:
[Theorem thm:HR_Wasserstein of arXiv:2412.07643, 'Ballistic Convergence in Hit-and-Run Monte Carlo and a Coordinate-free Randomized Kaczmarz'] Let $\varepsilon>0$, $\nu\in\mathcal P(\mathbb R^d)$ and $\rho$ as defined in (equation eq:rate of the paper).
Then generalized Hit-and-Run with respect to the Gaussian target measure $\gamma^\mathcal{C}$ starting from $\nu$ to accuracy $\varepsilon$ satisfies
\begin{equation}
    \inf\bigr\{ n \in \mathbb{N}\,:\,\boldsymbol{\mathcal{W}}^2\bigr(\nu\pi_{\mathrm{gH\&R}}^n,\,\gamma^\mathcal{C}\bigr)\leq \varepsilon \bigr\}\ \leq\ \rho^{-1}\log\bigr(\kappa^{1/2} \boldsymbol{\mathcal{W}}^2(\nu,\gamma^\mathcal{C})\varepsilon^{-1}\bigr)\;.
\end{equation}

[Definition 1 of arXiv:2608.30736, 'Stability results for distribution-dependent stochastic Volterra equations'] A probability measure $P$ on $(C([0,T];\R^d),\mathcal{B}(C([0,T];\R^d)))$ is called \textup{solution to the distribution-dependent Volterra local martingale problem} given $(\mu_0,b,\sigma,K_b,K_\sigma)$ if
  \begin{enumerate}
    \item[(i)] $(Z_t)_{t\in[0,T]}$ is a $d$-dimensional semimartingale and $Z_0 \sim \mu_0$, 
    \item[(ii)]the process $(\mathcal{M}^f_t)_{t\in[0,T]}$, given by
    \begin{equation}
      \mathcal{M}^f_t:= f(Z_t)-\int_0^t \mathcal{A}^f(s,X_s,\L(X_s),Z_s)\dd s,\quad \mathcal{F}_t, \quad t\in [0,T],
    \end{equation}
    is a local martingale for every $f\in C_0^2(\R^d)$, where 
	\begin{equation}
      \mathcal{A}^{f}(t,x,\rho,z):=\sum_{i=1}^d b_i(t,x,\rho)\frac{\partial f(z)}{\partial z_i}+\frac{1}{2}\sum_{i,j=1}^d (\sigma\sigma^\top)_{ij}(t,x,\rho) \frac{\partial^2 f(z)}{\partial z_i \partial z_j},
	\end{equation}
	and
    \begin{equation}
      X_t := Z_0 +\int_0^t K_b(s,t)\dd A_s + \int_0^tK_\sigma(s,t)\dd M_s, \quad t\in[0,T],
      \quad P\text{-a.s},
    \end{equation}
	$(A_t)_{t\in[0,T]}$ is predictable of bounded variation and $(M_t)_{t\in[0,T]}$ is a local martingale with $M_0=0$, such that $Z=A+M$. Here $\mathcal{F}_t = \mathcal{G}_{t+}$, and $(\mathcal{G}_t)_{t \in [0,T]}$ is the augmentation under $P$ of the canonical filtration $(\mathcal{B}_t)_{t \in [0,T]}$ with $\mathcal{B}_t := \sigma(Z_s\, :\, s\in [0,t])$.
  \end{enumerate}

[Corollary 2 of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] Suppose that \eqref{Assump2:A_n_to_infinite} and \eqref{Assump2:last_term} hold. Then, we have:
  \begin{enumerate}[label={(\roman*)}, ref={\roman*}]
    \item \begin{equation}
    \lim_{h\to 0}\mu\Biggl(\Biggl\{x\in \onetorus \colon \frac{ f_{r,a}(x+h)-f_{r,a}(x) }{  h\sqrt{\localmodulusofcont(|h|)} } \le y \Biggr\} \Biggr)= \int_{-\infty}^{y} \frac{1}{\sqrt{2\pi}} e^{-t^2/2}dt.
  \end{equation}

  \item For $\mu$-a.e.\ $x$, for each $y\in [-1,1]$ there exists a sequence $\{h_n\}_{n=1}^{\infty}$ with $\displaystyle \lim_{n\to \infty} h_n =0$ such that
    \begin{equation}
      \lim_{n\to\infty} \frac{f_{r,a}(x+h_n) -f_{r,a} (x)}{h_n\sqrt{2\localmodulusofcont(|h_n|) \log\log \localmodulusofcont(|h_n|)}} =y.
    \end{equation}

  \item For $\mu $-a.e.~$x$,
  \begin{equation}
    \liminf_{h \downarrow 0} \sqrt{\frac{\log\log \localmodulusofcont(h)}{\localmodulusofcont(h)}} \sup_{T \in (h, 1)} \frac{|f_{r,a}(x+T)-f_{r,a}(x)|}{T} = \frac{\pi}{\sqrt{8}}.
  \end{equation}

  \item We also assume that the sequence $\{V_n\}_{n\ge 1}$ is regularly varying with index $\beta>0$, i.e., $V_{\floor{nt}} /V_n \to t^{\beta}$ as $n\to \infty$ for all $t\in (0,\infty)$. Then, as $n\to \infty$, for a standard Brownian motion $\{B(t) \colon 0\le t\le 1\}$,
  \begin{equation}
    \biggl\{ \frac{f_{r,a } (x+r^{-\floor{n t^{1/\beta}}}) - f_{r, a}(x)}{r^{-\floor{n t^{1/\beta}}} \cdot \sqrt{V_n} } \colon 0\le t\le 1 \biggr\} \dlimit \{ B(t) \colon 0\le t\le 1\},
  \end{equation}
  where $\dlimit$ denotes convergence in distribution.

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm lemm 4.9 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Suppose Assumption (assum 4.8 of the paper) holds and let $H :\mathbb{R}^K\times \mathbb{R}^d\rightarrow \mathbb{R}$ be a bounded and measurable function. Then there is a Borel set $F\subseteq \mathbb{R}^K$ such that $F^{c}$ is of Lebesgue measure zero and such that for 
				\[ G(\bold{y};x):=\mathcal{X}_F(\bold{y})H(\bold{y};x)  \]
				and 
				\begin{equation*}
					U(\bold{y};t,x)=
					\begin{cases}
						Y_t^{\bold{y}:t,x} \text{ a.s.}&:\,\, r\leq t<R\\
						G(\bold{y};x)&:t=R,
					\end{cases}
				\end{equation*}	
				where $(Y_s^{\bold{y}:t,x})_{s\in [t,R]}$ is the $Y\text{-component}$ of the BSDE with respect to the forward $(X_s^{t,x})_{s\in [t,R]}$, the terminal condition $G(\bold{y};X_R^{t,x})$ with terminal time $R\in (0,T]$  and the generator $g$, the following assertions are satisfied
				\begin{itemize}
					\item[(i)] For fixed $\bold{y}\in \mathbb{R}^K$ we have that $U(\bold{y};\cdot,\cdot)\in C^{0,1}([r,R)\times \mathbb{R}^d)$.
					\item[(ii)] The functions $U:\mathbb{R}^K\times[r,R]\times\mathbb{R}^d\rightarrow\mathbb{R}$ and $\nabla_xU:\mathbb{R}^K\times[r,R]\times\mathbb{R}^d\rightarrow\mathbb{R}^{1\times d}$ are measurable.
					\item[(iii)] There is a constant $C$ such that for all $(\bold{y},t,x)\in \mathbb{R}^K \times[r,R]\times\mathbb{R}^d$ the following holds
					\begin{align*}
						\sup_{(\bold{y},t,x)\in \mathbb{R}^K \times[r,R]\times\mathbb{R}^d} \left(	|U(\bold{y};t,x)| + (R-t)^{1/2}|\nabla_x U(\bold{y};t,x)| \right) \leq C.
					\end{align*}
					\item[(iv)] For any $y\in \mathbb{R}^K$, the solution of the BSDE with the terminal value $G(\bold{y};X_R^{t,x})$, generator $g$ and forward diffusion $(X_s^{t,x})_{s\in[r,R]}$ can be represented as 
					\begin{align*}
						Y_t^{\bold{y};t,x} = U(\bold{y};t,X_t^{r,x}),\quad Z_t^{\bold{y};r,x} = \nabla_x U(\bold{y};t,X_t^{r,x}).
					\end{align*}
				\end{itemize}

