h\le \sigma^2=\beta^2 q.
\end{equation}
Then for all $\lambda$ such that $0\le \lambda\le \beta^2(1-q)$, 
\begin{equation}
a_2(\lambda)\le a_2(0)=\E[S^2]=\frac{\alpha}{\beta^2}.
