Further, if $\alpha\le 1$, then for all $t \in [q,1]$,
\[
\E[m_t^2]\le t.
\]

[Prop P: uniqueness HJ of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Let $F_{\text{in}} \in CDF(\overline{\mathbb{R}})$ and assume $Q = 0$.  If $\mathcal{F}(v,w) = -H(v)$ for a convex $H : \mathbb{R} \to \mathbb{R}$ satisfying $H(0) = 0$ and (equation E: superlinear of the paper), and if $\underline{F}$ and $\overline{F}$ are the maximal subsolution and minimal supersolution, respectively, of (equation E: initial value problem appendix of the paper), then, for any $(x,t) \in \mathbb{R} \times (0,+\infty)$,
		\begin{align} 
			\underline{F}(x,t) = \overline{F}(x,t) = \inf \left\{ F_{\text{in}}( y ) + t L \left( \frac{x - y}{t} \right) \, \mid \, y \in \mathbb{R} \right\}.
		\end{align}
	where $L$ is the Legendre-Fenchel transform of $H$. 

	Furthermore, the following statements hold:
		\begin{itemize}
			\item[(i)] For any $t > 0$, the functions $\underline{F}(\cdot,t)$ and $F_{\text{in}}$ coincide on the set $\{-\infty,+\infty\}$.
			\item[(ii)] If $\{ F^{(n)}_{\text{in}}\}$ is a sequence in $CDF(\overline{\mathbb{R}})$ converging vaguely to $F_{\text{in}}$, and if $\{ \underline{F}^{(n)} \}$ are the corresponding maximal subsolutions of (equation E: initial value problem appendix of the paper), then, for any compact set $K \subseteq \mathbb{R} \times (0,+\infty)$,
				\begin{align*}
					\lim_{ n \to \infty } \sup \left\{ | \underline{F}^{(n)}(x,t) - \underline{F}^{(n)}(x,t) | \, \mid \, (x,t) \in K \right\} = 0.
				\end{align*}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 (Gibbs variational principle) of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] Let $\mu \in \eP(T)$ be given. Then, for any $\beta > 0$,
	\begin{align}
		\Phi_\beta(X; \mu) = \langle \sm_{\beta,\mu}, X \rangle - \frac{1}{\beta}D(\sm_{\beta,\mu}\|\mu) = \sup_{\nu \in \eP(T)} \left[\langle \nu, X \rangle - \frac{1}{\beta}D(\nu \| \mu)\right].
	\end{align}

