[Lemma 20 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] Let $S \subset V$ be such that $|S| \leq 3$. Suppose any vertex $v \in S \setminus \Vis$ is only adjacent to vertices which are separated from $W$ by $S$. 
	Then, there is a classical spin model $ \widetilde{\vp}$ on the reduced graph $ \widetilde{G} = ( \widetilde{V}, \widetilde{E}) := R(G,S)$ and scaling factors $r_u > 0$ for each $u \in S$ such that
	\begin{enumerate}[(i)]
		\item the reference measure on all spins in $S \setminus \Vis$ becomes the Ising measure $\l\propto \delta_{1} + \delta_{-1}$,
			and remains the same on all other spins in $ \widetilde{V}$.
		\item  the boundary correlation functions satisfy
		\begin{equation}
			\langle \vp({A}) \rangle = \Big( \prod_{u \in A}  r_u \Big) \langle \widetilde{\vp}(A) \rangle_{ \widetilde{G}}
            \end{equation}
            for all $A \subset W$. 
	\end{enumerate}

[Lemma 25 (Composition and differences) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] Let $I\Subset\R$ be compact and $F\in C^{m+1}(I)$.
If $f$ takes values in $I$, $f\in L^\infty$, and
$\nabla f\in H^{m-1}$, then
\begin{equation}
 \norm{\nabla F(f)}_{H^{m-1}}
 \le C_{F,I,m}\left(1+\norm{\nabla f}_{H^{m-1}}^m\right).

\end{equation}
If $f_1,f_2$ take values in $I$, $f_1-f_2\in H^m$, and their relative
coefficient norms are bounded by $R$, then
\begin{equation}
 \norm{F(f_1)-F(f_2)}_{H^m}
 \le C_{F,I,m,R}\norm{f_1-f_2}_{H^m}.

\end{equation}
For a function $f\in H^m$ and a normalization $F(0)=0$, this also gives
\begin{equation}
 \norm{F(f)}_{H^m}
 \le C_{F,\norm f_\infty,m}
 (1+\norm f_{H^m}^{m-1})\norm f_{H^m}.

\end{equation}

