[Theorem 5 of arXiv:2511.14379, 'Stability of storage processes with general release rates'] Assume $\textbf{(C1)-(C3)}$ (or $\textbf{(\={C}1)-(\={C}2)}$ and  $\textbf{(C3)}$ in the case when $\bar\upnu(0)<\infty$).  Let  $p\ge1$ and $\beta:[0,\infty)\to[0,\infty)$ 
	be such that
	\begin{itemize}
		\item [(i)] $\displaystyle \int_{[0,\infty)}u\vee u^p\upnu(\D y)<\infty$;
		\item[(ii)] $\beta(t)$ is convex and $\beta(t)=0$ if, and only if, $t=0$;
		\item[(iii)] there exists $\Gamma>0$  such that
		\begin{equation} r(u)-r(v)\le
		-\Gamma\beta(v-u), \qquad 0\le u\le v.\end{equation}
	\end{itemize}  
	Then, the process $\process{X}$ admits a unique invariant  $\uppi\in\mathcal{P}_p$, and for any $\kappa>0$ and $\upmu\in\mathcal{P}_p$ it holds that: 
\begin{equation}\W_p\left(\int_{[0,\infty)}p(t,x,\D y)\upmu(\D x),\uppi(\D y)\right)\le \left(\frac{\W_p(\upmu,\uppi)}{\kappa}+1\right)B_\kappa^{-1}(\Gamma t),\qquad t\geq 0,\end{equation} 
 where $$B_\kappa(t):=\int_t^\kappa\frac{\D s}{\beta(s)},\qquad t\in(0,\kappa].$$ Furthermore, $$\limsup_{u\to\infty}u^p\bar\uppi(u)<\infty.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: 1D-cokernelWithoutSym of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Let $q \de p^{\deg(\beta)}$.
    Then, every $n\geq 2$, 
    \begin{align}
          \biggl\lvert\, \bbP\biggl(\coker\bigl(\bM_{p,\beta},\zeta_{p,\beta}\bigr)    \cong \frac{\bbF_{p}[x]}{\beta(x)\bbF_{p}[x]}\biggr) - \frac{1}{q^2} \prod_{i=2}^\infty\Bigl(1-\frac{1}{q^i}\Bigr)   \,  \biggr\rvert \leq \frac{6}{q^n}. 
    \end{align}

