\begin{equation}
    I_1(a,b)=\frac{ \big({\rm -res}_{x=x^*} \phi_2(x) \big ) \gamma_2(x^*, y^*)}{ \partial_y\gamma(x^*, y^*)} \exp(-ax^* -b y^* ) {\bf 1}_{ \alpha <\alpha^*}
\end{equation}
$$\quad\quad\quad+\ \frac{1}{ 2 \pi i } \int\limits_{T_{x, \alpha}}\frac{\phi_2(x) \gamma_2(x, Y^+(x))}{\partial_y\gamma(x, Y^+(x))} \exp(-ax -b Y^+(x))dx, $$
\begin{equation} I_2(a, b) = \frac{ \big({\rm -res}_{y=y^{**}} \phi_1(y) \big) \gamma_1(x^{**}, y^{**})}{ \partial_x\gamma(x^{**},y^{**})} \exp(-ax^{**} -by^{**}) {\bf 1}_{ \alpha >\alpha^{**}}
\end{equation}
$$\quad\quad\quad+ \frac{1}{2\pi i } \int\limits_{T_{y, \alpha}} 
\frac{\phi_1(y) \gamma_1(X^+(y), y)}{\partial_x\gamma(X^+(y), y)} \exp(-aX^+(y) -b y)dy,$$
\begin{equation} I_3(a,b)= \frac{1}{2\pi i }  \int\limits_{T_{x, \alpha}}   \exp((a_0-a) x + (b_0-b) Y^{+}(x)) 
  \frac{dx}{\partial_y\gamma(x, Y^{+}(x)) } \ \  \hbox{ if }b>b_0, 
  \end{equation}
\begin{equation}
 I_3(a,b)= \frac{1}{2\pi i }\int\limits_{ T_{y, \alpha}}
 \exp((a_0-a) X^{+}(y)  + (b_0-b) y ) 
 \frac{dy}{\partial_x\gamma(X^{+}(y), y) } \ \  \hbox{ if }a>a_0.
\end{equation}

