body:
[Theorem annealed of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $f\in\mathbb{R}$, $u\in(0,1)$, $q\in(0,1)$, and
		$\zeta\in\mathrm{Prefix}_2(u,q)$.
		Assume:
		\begin{enumerate}
			\item[\emph{(i)}]
			\emph{(Tail optimality.)}
			$\zeta$ minimizes $\mathcal{P}\mathrm{arisi}$ over $\mathrm{Prefix}_2(u,q)$.
			\item[\emph{(ii)}]
			\emph{(Stationarity.)}
			$(u,q)$ is a critical point of
			$(u',q')\mapsto u'\!\left(\inf_{\zeta'\in\mathrm{Prefix}_2(u',q')}\mathcal{P}\mathrm{arisi}(\zeta')-f\right)$.
		\end{enumerate}
		Let $\varepsilon\in(0,1)$ and let $\mathcal{N}_\varepsilon(f,\zeta)$ be the number of
		critical points of $F_{\mathrm{TAP},\zeta}$ with
		$\frac{1}{N}F_{\mathrm{TAP},\zeta}(\mathbf{m})\in(f-\varepsilon,f+\varepsilon)$.
		Then
		\begin{equation}
			\lim_{\varepsilon\to 0}\lim_{N\to\infty}
			\frac{1}{N}\log\mathbb{E}\bigl[\mathcal{N}_\varepsilon(f,\zeta)\bigr]
			\;\geq\;
			\zeta(\{0\})\,\bigl(\mathcal{P}\mathrm{arisi}(\zeta)-f\bigr).
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 21 (Crossing count) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Let
\begin{align*}
    L_j:=x+j\ell,
    \quad
    j=0,1,\ldots,m-1.
\end{align*}
Assume that every edge crossing over one of the levels $L_0,\ldots,L_{m-1}$ is heavy. Then any path that starts to the left of $L_0$, ends to the right of $L_{m-1}$, and avoids all vertices
\begin{align*}
    L_0,\ldots,L_{m-1},
\end{align*}
must contain at least $m$ heavy edges.

[Lemma 30 (Differentiation under the integral sign) of arXiv:2607.15872, 'Existence of $q$-Bass martingales in the semidiscrete setting'] Let $X\subseteq \RR$ be an open set, and $\Omega$ be a measure space. Suppose that a measurable function $f : X \times \Omega \rightarrow \RR$ satisfies the following conditions:
	\begin{enumerate}[label=(\roman*)]
		\item for any $x \in X$, $\int_\Omega |f(x, \omega)| d\omega<\infty$;
		\item for any $\omega \in \Omega$, $f(x, \omega)$ is an absolutely continuous function of $x$;
		\item one of the following holds:
			\begin{enumerate}
				\item $\int_a^b \int_\Omega \left | \frac{\partial }{\partial x}f(x,\omega) \right| d\omega dx < \infty$ for all $a, b \in X$, $a<b$, 
				\item $\frac{\partial }{\partial x}f(x,\omega) \geq 0$ for all $(x, \omega) \in X \times \Omega$.
			\end{enumerate}
	\end{enumerate}
	Then the map $x \mapsto \int_\Omega f(x, \omega) dw$ is  absolutely continuous and, for almost every $x \in X$, its derivative exists and is given by
	\begin{equation}

		\frac{d}{dx}\int f(x, \omega) d\omega = \int_\Omega \frac{\partial}{\partial x} f(x, \omega) d\omega.
	\end{equation}

