[Lemma 6 (Brownian weighted averaging) of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[lemma]{le:brownian_weighted_averaging}
Let \(G:\mathbb R^d\to\mathbb R\) be continuous.  Then, for
\(1\le\alpha,\gamma\le q\),
\begin{equation}
\begin{aligned}
    &n
    \int_0^\cdot
    G(\hat X_{\varphi_n(s)}^n)
    \bigl(1+\lfloor ns\rfloor-ns\bigr)^2
    \bigl(B_s^\alpha-B_{\varphi_n(s)}^\alpha\bigr)
    \bigl(B_s^\gamma-B_{\varphi_n(s)}^\gamma\bigr)ds
    \\
    &\qquad\qquad\qquad
    \xrightarrow{\mathrm{ucp}}
    \frac{\delta^{\alpha\gamma}}{12}
    \int_0^\cdot G(X_s)\,ds .
\end{aligned}
\end{equation}

[Theorem thm:trichotomy of arXiv:2607.24705, 'Derangetropy Operators'] The equations $R_{f} \equiv \kappa$ for
		$\kappa \in \{-2\pi^{2}, 0, +2\pi^{2}\}$ have complete solution
		families:
		\begin{itemize}[leftmargin=*, itemsep=2pt]
			\item \emph{Elliptic case:}
			\begin{align*}
				R \equiv -2\pi^{2}
				&\iff \tan\big(\pi(F-\tfrac12)\big) \text{ M\"obius in } x\\
				&\iff f \in \{\mathrm{Cauchy}(m,\gamma)\}.
			\end{align*}
			\item \emph{Parabolic case:}
			\begin{align*}
				R \equiv 0
				&\iff F \text{ M\"obius in } x\\
				&\iff F \ \text{an increasing M\"obius map of the support onto }
				(0,1).
			\end{align*}
			\item \emph{Hyperbolic case:}
			\begin{align*}
				R \equiv +2\pi^{2}
				&\iff \tanh\big(\pi(F-\tfrac12)\big) \text{ M\"obius in } x\\
				&\iff \tanh\big(\pi(F-\tfrac12)\big) = h,
				\quad h \ \text{M\"obius onto }
				\big({-}\tanh\tfrac{\pi}{2}, \tanh\tfrac{\pi}{2}\big).
			\end{align*}
		\end{itemize}
		Up to affine equivalence, the zero-curvature laws are the uniform
		law, the Lomax law $(1+x)^{-2}$ on $(0,\infty)$ and its reflection,
		and the truncated family
		\begin{equation}
			f_{c}(x) = \frac{1+c}{(1+cx)^{2}}\,\mathbf{1}_{(0,1)}(x),
			\qquad c > -1;

		\end{equation}
		the positive-curvature laws are supported on bounded intervals or
		half-lines, with symmetric representatives
		\begin{equation}
			f(x) = \frac{1}{\pi\gamma\big(1-(x-m)^{2}/\gamma^{2}\big)}
			\qquad\text{on } |x-m| < \gamma\tanh\tfrac{\pi}{2}.

		\end{equation}
		The uniformizing functions $\tan, \mathrm{id}, \tanh$ correspond to
		the elliptic, parabolic, and hyperbolic classes of
		$\mathrm{SL}(2,\mathbb{R})$.

