[Theorem 13 of arXiv:2605.14254, '2605.14254'] For every $h \in \mathcal{D}(A^{\lambda,z})$, the process
		\begin{multline}
			M_t^{\lambda,z}=h(\mathbb{I}_{\{t<\sigma_z^{\lambda}\}},\xi_t^{\lambda,z})-h(1,0)-\displaystyle\int_0^{t} \left(-\lambda\,\dfrac{\partial h}{\partial y_2}(1,\xi_s^{\lambda,z}) +  \dfrac{1}{2}\,\dfrac{\partial^2 h}{\partial ^2y_2}(1,\xi_s^{\lambda,z})\right) \mathbb{I}_{\{z<\xi_s^{\lambda,z}\}} \mathrm{d} s\\
			-\displaystyle\int_0^{t} \left(\lambda\,\dfrac{\partial h}{\partial y_2}(1,\xi_s^{\lambda,z}) +  \dfrac{1}{2}\,\dfrac{\partial^2 h}{\partial ^2y_2}(1,\xi_s^{\lambda,z})\right) \mathbb{I}_{\{\xi_s^{\lambda,z}<z\}} \mathrm{d} s
		\end{multline}
		is a martingale with respect to $\mathbb{F}^{\xi^{\lambda,z}}$.

[Prop Dteq of arXiv:2411.10586, 'A convergence framework for Airy$_\beta$ line ensemble\\ via pole evolution'] The following SDE is satisfied:
\begin{multline}
{\rm d} \Delta^{(n)}_t(w)={\rm d} M^{(n)}_t(w)
\\+\left(\frac{2-\beta}{2\beta}\del_w^2(\Delta^{(n)}_t(w)+\sqrt w)
+\frac{1}{2}\del_w(\Delta^{(n)}_t(w)+\sqrt w)^2-\frac{1}{2}+{\mathcal E}^{(n)}_t(w)\right){\rm d} t.
\end{multline}
Here ${\mathcal E}^{(n)}_t(w)$ is some error term,  
and $M^{(n)}_t(w)$ is the martingale term, with quadratic variation given by
\begin{equation}  
    \frac{{\rm d}}{{\rm d} t} \langle  M^{(n)}(w), M^{(n)}(w')\rangle_t
    =\frac{2}{\beta}\sum_{i=1}^n \frac{1}{(\widetilde \lambda^{(n)}_i(t)-w)^2(\widetilde \lambda^{(n)}_i(t)-w')^2} + {\hat{{\mathcal E}}}^{(n)}_t(w,w'),
\end{equation}
for any $w, w'\in {\mathbb C}\setminus {\mathbb R}$, where ${\hat{{\mathcal E}}}^{(n)}_t(w,w')$ is some other error term.

These error terms satisfy the following estimates.
Take any compact ${\mathcal K}\subset \mathbb{H}$.
For any $w, w' \in {\mathcal K}\cup \overline{{\mathcal K}}$, there is
\begin{equation}  
|{\mathcal E}^{(n)}_t(w)|,\; |\partial_w{\mathcal E}^{(n)}_t(w)| \lesssim n^{-1/3}(1+|\Delta^{(n)}_t(w)+\sqrt w|)^2,
\end{equation}
and
\begin{equation}
|{\hat{{\mathcal E}}}^{(n)}_t(w, w')|,\; |\partial_w\partial_{w'}{\hat{{\mathcal E}}}^{(n)}_t(w, w')| \lesssim n^{-2/3}(1+|\Delta^{(n)}_t(w)+\sqrt w|),
\end{equation}
where all the constants behind $\lesssim$ can depend on ${\mathcal K}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma decouple_label_degree_multiple_vertices of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Suppose that Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:geq1 of the paper) is satisfied. Fix $k\in\mathbb{N}$ and consider any truncation sequence $(t_n)_{n\in\mathbb{N}}$ such that $t_n\leq n$ for all $n\in\mathbb{N}$. Let $n\in\mathbb{N}$ and, for $v\in [k]$, let $u_v,d_v\in\mathbb{N}_0$, $\ell_v\in\Omega_1$. Furthermore, let $\overline{J^-},\overline{J^+}\in{\mathcal{P}(\Omega_1)}^k$ such that $J^-_v\cup J^+_v$ and $J^-_w\cup J^+_w$ are disjoint for $v\neq w\in[k]$. Then,
\begin{equation}
\begin{aligned}
&\mathbb{P}(u_{n,1}(a_v)\leq u_v,\ell_n(a_v)\geq \ell_v,\deg_n(a_v)\geq d_v,v\in [k]\,|\,\overline{\mathcal{S}^-_{n,1}}=\overline{J^-},\overline{\mathcal{S}^+_{n,1}}=\overline{J^+})\\
&= \prod_{v=1}^k\mathbb{P}(u_{n,1}(a_v)\leq u_v,\ell_n(a_v)\geq \ell_v,\deg_n(a_v)\geq d_v\,|\,\mathcal{S}^-_{n,1}(a_v)=J^-_v,\mathcal{S}^+_{n,1}(a_v)=J^+_v).
\end{aligned}
\end{equation}

[Definition defJt of arXiv:2506.10448, 'Hitting probabilities and the Ekstr\"om--Persson conjecture'] For a positive sequence $\underline{r}=(r_k)_{k=1}^\infty$, define the hitting operator 
$\Jmurz$ on compact sets $K\subset\mathbb{R}^d$ by setting
\begin{equation}
\Jmurz(K):=\Bigl\{x\in \mathbb{R}^d\mid\sum_{k=1}^\infty \mu\bigl(B(x,r)\cap K(r_k)\bigr) 
  =\infty\text{ for every }r>0\Bigr\}.
\end{equation}

[Thm 81 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $n\geq 1$.
Then
\begin{displaymath}
\psi_{n,j}
=
\lim_{\varepsilon\to 0}
Q_{n}(\nu_{j,\varepsilon},V_{\clus_j,\Gamma_j,\varepsilon}),
\end{displaymath}
with a convergence in $L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ for $\eta>0$.
Further,
\begin{displaymath}
\psi_{n,j}
=
\lim_{\gamma\to 0^{+}}
\ind_{\inter(\Gamma_j)\setminus \clus_j}
\He_{n}(\gamma V_{\clus_j,\Gamma_j}^{1/2})
V_{\clus_j,\Gamma_j}^{n/2} 
\exp\Big(-\dfrac{\gamma^{2}}{2} V_{\clus_j,\Gamma_j}\Big),
\end{displaymath}
with convergence both in $L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ 
and almost surely in $H^{-\eta}(\C)$, for $\eta>0$.
For $n$ odd, the field $\psi_{n,j}$ is a generalized function supported on $\clus_j$.
For $n=2k\geq 2$ even, the field $\psi_{n,j}$ also has an extension to
$\inter(\Gamma_j)\setminus \clus_j$, 
where it coincides with the function
\begin{displaymath}
(-1)^{k}\dfrac{(2k)!}{2^{k}k!}
V_{\clus_j,\Gamma_j}^{k} .
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 19 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$, $n \in \mathbb{N}_+$ and $A_n$ be an arbitrary subset of $\mathbb{Z}^{2}$. Let also $B_{r,v}^{H,n}: \mathbb{Z}^{2} \mapsto \mathbb{R}$ be a deterministic map depending only on $v,H,n$ and $r \in [0,T]$. Then
\begin{align*}
&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \int_s^t \dd r    \sum_{(x,y) \in A_n} B_{r,v}^{H,n}(x,y)  a(y-x)   \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _y^{\beta}( \eta_r^n ) \Bigg\}^{2} \Bigg]  \\
\leq & \chi(\rho_{\alpha}) \chi(\rho_{\beta})	  (t-s)  \int_s^t \sum_{(x,y) \in A_n} \big[  B_{r,v}^{H,n} (x,y) \big]^{2}  a^{2}(y-x) \; \dd r.
\end{align*}

[Theorem 10 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For every $K\in{\mathbb Z}_{>0}$, as $n\to\infty$,
\begin{equation}
d_{\rm TV}\left((M_{n,i}-b_n)_{i=1}^K\,,\,(\lceil\xi_i+ (e-1)\tau+c_n\rceil)_{i=1}^K\right)\to 0,
\end{equation}
where $\tau\stackrel{\rm d}{=}{\rm Gumbel}(\ell+1)$ is independent of\/ $\Xi$.

