[Theorem 5 (ergodicity of the sticky CIR
process) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] Let \(u_t\) be the sticky CIR process defined by \cref{eq-CIR4}
with parameters \(\lambda, \beta, \mu > 0\) and \(\delta \in (1,2)\). 
\begin{enumerate}
\def\labelenumi{\arabic{enumi}.}

\item There exists a unique invariant
  probability measure \(\pi_0\) on \([0,\infty)\) given by \[
  \pi_0(dx) = \frac{1}{Z} \left[ \frac{1}{\mu} \delta_0(dx) + \beta x^{\delta-1} e^{-\lambda\beta x^2/2} \, dx \right]
  \] where $Z = 1/{\mu} + \int_0^\infty \beta x^{\delta-1}
e^{-\lambda\beta x^2/2}\,dx<\infty$.
\item For any initial point \(x \in [0,\infty)\) and
  any bounded measurable function \(\phi\colon [0,\infty)\to \mathbb{R}\), \[
  \lim_{t \to \infty} P_t\phi(x) = \int_{[0,\infty)} \phi(y) \, \pi_0(dy).
  \]
\end{enumerate}

[Proposition Prop-Psi of arXiv:2512.13200, 'Martingales on a Euclidean manifold with a boundary and reflected BSDEs in non-convex doma'] {Let Assumption (ass:3 of the paper) hold.}
    {Then, the function $\Psi$ defined in (equation eq.Psi.d2.def of the paper) is an element of $C^1(\bar\mathcal{D})$, and $\nabla \Psi(x,y) = -2(\overrightarrow{xy},\overrightarrow{yx})$, where $\overrightarrow{xy}$ is given in Definition (def:re de rot-angle of the paper).}
    In addition, $\Psi$ is a special $\Gamma$-convex function vanishing precisely on the diagonal
    $\Delta = \{(x,x) | x \in \bar{\mathcal{D}}\}$: in particular, for all $(x,y)\in\bar\mathcal{D}\times\bar\mathcal{D}$, $(u,v) \in \mathfrak{n}(x) \times \mathfrak{n}(y)$, we have $\langle \nabla \Psi(x,y),(u,v) \rangle \geqslant 0$. Moreover, $\Psi$ is strongly $\Gamma$-convex, in the sense that, for all geodesics $\gamma^1$ and $\gamma^2$, and for all $t\in [0,1]$, we have
    \begin{align}

    \Psi(\gamma_t^1,\gamma_t^2) \geqslant& \Psi(\gamma_0^1,\gamma_0^2)+ \langle \nabla \Psi(\gamma^1_0,\gamma^2_0), (\dot{\gamma}^{1}_0,\dot{\gamma}^{2}_0) \rangle t \\% (\overrightarrow{\gamma^1_0 \gamma^1_t}\overrightarrow{\gamma^2_0 \gamma^2_t})\rangle\\
    \nonumber &+ 2\int_0^t (t-s) \left| \dot{\gamma}^1_s -R(\theta(\gamma_{s}^1,\gamma_{s}^2)) \dot{\gamma}^2_s \right|^2 \mathrm{d} s.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 35 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Let $\phi_n: [0,T] \to \newone{H}$, $n \in \mathbb{N}$ be functions such that
\begin{trivlist}
\item[(i)] $\sup_{n \in \mathbb{N}} \, \sup_{s \in [0,T]} \lvert \phi_n(s) \rvert_{\newone{H}} \leq r$.
\item[(ii)] $\phi_n \to \phi$ in $C([0,T];\newonep{V})$ as $n \to \infty$.
\end{trivlist}
Then $\phi,\, \phi_n \in C([0,T];\mathbb{B}_w)$ and $\phi_n \to \phi$ in $C([0,T];\mathbb{B}_w)$ as $n \to \infty$.

