[Theorem chain-rule of arXiv:2609.02769, 'Divergence-Free Approximation in Sobolev and Lebesgue Spaces on general unbounded domains '] Let $\mathcal{H}$ be a Hilbert space, and let $\mathcal{V}$ and $\mathcal{E}$ be Banach spaces satisfying the Gelfand triple (equation eqn-gelfand of the paper). Let $1<p<\infty$ and let $p'=\frac{p}{p-1}$. Suppose that
		\begin{align*}
			\boldsymbol{y},\boldsymbol{z}\in\mathrm{L}^2(0,T;\mathcal V)\cap\mathrm{L}^p(0,T;\mathcal E)
		\end{align*}
		and that, in $\mathcal D'(0,T;\mathcal{V}'+\mathcal{E}')$,
		\begin{align*}
			\boldsymbol{y}'=\boldsymbol{y}_1+\boldsymbol{y}_2,
			\ 
			\boldsymbol{z}'=\boldsymbol{z}_1+\boldsymbol{z}_2,
		\end{align*}
		where
		\begin{align*}
			\boldsymbol{y}_1,\boldsymbol{z}_1\in\mathrm{L}^2(0,T;\mathcal V'),
			\ 
			\boldsymbol{y}_2,\boldsymbol{z}_2\in\mathrm{L}^{p'}(0,T;\mathcal E').
		\end{align*}

		Then $\boldsymbol{y}$ and $\boldsymbol{z}$ admit representatives, still denoted by $\boldsymbol{y}$ and
		$\boldsymbol{z}$, such that
		$
		\boldsymbol{y},\boldsymbol{z}\in\mathrm{C}([0,T];\mathcal H).
		$
		Moreover, the map
		\begin{align*}
			t\mapsto (\boldsymbol{y}(t),\boldsymbol{z}(t))_{\mathcal H}
		\end{align*}
		is absolutely continuous on $[0,T]$, and
		\begin{align}
			\frac{\mathrm{d}}{\mathrm{d}t}(\boldsymbol{y}(t),\boldsymbol{z}(t))_{\mathcal H}
			=
			\langle \boldsymbol{y}_1(t),\boldsymbol{z}(t)\rangle_{\mathcal V',\mathcal V}
			+\langle \boldsymbol{y}_2(t),\boldsymbol{z}(t)\rangle_{\mathcal E',\mathcal E}
			+
			\langle \boldsymbol{z}_1(t),\boldsymbol{y}(t)\rangle
		\end{align}
			for a.e. $t\in[0,T]$.

[Proposition prop:uniform_approximation_fat_shattering of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Let $(X,\rho,\mathfrak{m})$ be a compact $d$-Ahlfors regular metric measure space, for some $d>0$, let $B,L>0$, and fix $\mathcal{F}\subseteq C(X,\mathbb{R})$. There exist constants $\varepsilon_0,c>0$ such that, if there is a fixed tolerance $0<\varepsilon<\min\{B/2,L\varepsilon_0\}$ such that, for every $f\in\operatorname{Lip}((X,\rho),[-B,B];L)$, there is some $\hat{f}\in\mathcal{F}$ satisfying
\begin{equation}

    \|f-\hat{f}\|_\infty
\le
    \varepsilon,
\end{equation}
then, for every $\varepsilon\le\gamma<\min\{B/2,L\varepsilon_0\}$,
\begin{equation}

    \operatorname{fat}_{\gamma}(\mathcal{F})
\ge
    c
    \left(
        \frac{L}{\gamma}
    \right)^d.
\end{equation}

[Cor 48 of arXiv:2608.20552, 'One-point fluctuations for exponential last passage percolation under upper-tail condition'] There exists $c>0$ such that
\beqq
	\frac{1}{\tP}
	\sum_{n_1,n_2\ge1}
	\frac{\mathcal R_{n_1,n_2}}{(n_1!n_2!)^2}
	=O(e^{-cL}).
\eeqq

[Lemma 30 of arXiv:2606.06757, 'Path-Dependent Ergodic Optimal Control \\ and Backward Stochastic Differential Equations'] Under the assumptions of Proposition \ref{prop:ergodicity}, the stochastic differential equation \eqref{SDE_variant_bounded_measurable} admits a weak solution unique in law for all time origin $\tau \in \mathbb{R}$. Denote by $p(s, x, t, y)$ its transition densities. Then under~\eqref{dissipativity_condition_inhom}, for all $R > 0$, there exist a non-negative measurable function $\varepsilon_R(s,t)$ and a probability measure on $B_R$ with density $q_R$ such that $\inf_{s\in\R} \varepsilon_R(s,s+1)>0$ and \begin{equation*}
        \begin{array}{cc}
             \displaystyle p(s, x, t, \cdot) \geq \varepsilon_R(s,t) \, q_R(\cdot) \, , & \text{for all } \,  x \in B_R \, , \;  s \leq t \in \R \, .
        \end{array}
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 3 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Under the same assumptions as in Lemma~\ref{lem:unifbound}, the weak solution \(p\) of~\eqref{eq:NFPE} belongs to the class \(C^{1+\beta/2,2+\beta}_{\mathrm{loc}}\bigl((0,T)\times\mathbb R^d\bigr)\) for some \(\beta\in(0,1)\) and any \(T>0\) fixed. In particular, it is a locally classical solution. Moreover, for any \(t\in(0,T)\) and \(x\in\R^d\) its gradient satisfies
    \begin{equation}
    \Vert \nabla p_t(x)\Vert_2
    \leq \frac{c_1(d,K,b_0,c_0,\Xi(0),L_{\mathrm{Lip}}(\Xi))}{\min\left(1,\sqrt{t/2}\right)}
    (1+\Vert x\Vert_2)\exp\left\{
    -\frac{\Xi(0)}{4}\Vert x\Vert_2^2
    \right\},
    \end{equation}
    where \(L_{\mathrm{Lip}}(\Xi)\) is the Lipschitz constant of \(\Xi\), and \(c_1(d,K,b_0,c_0,\Xi(0),L_{\mathrm{Lip}}(\Xi))\) is some constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

