[Lemma lemma_xinlandu of arXiv:2509.18045, 'Density convergence on Markov diffusion chaos via Stein's method'] Fix  $x\in (\ell, u)$ and $k\in \mathbb{N}$. Let the function $h$ in the ODE (equation equation_stein of the paper) be 
    \begin{align*}
        h(y)=h_{k,x}(y):=\mathds{1}_{\{y>x\}}\rho_{k+1}(y),\qquad y\in \mathbb{R}\setminus \left\{y\in [u,\infty):b(y)=0 \right\}\,, 
    \end{align*} 
where the function $\rho$ is defined by  (equation def_rho of the paper). Then the solution $g_{k,x}:\mathbb{R}\to\mathbb{R}$ to (equation equation_stein_pearson of the paper) exists and satisfies for every $y\in \mathbb{R}$, 

\begin{align*}
    & \abs{g_{k,x}(y)}\\
    &\leq \mathcal{U}_1(k,x,y):=\mathds{1}_{ \{y\geq u \} }C\frac{\sum_{j=0}^{k+1}\left\vert y \right\rvert^j }{\left\vert b(y) \right\rvert^{k+1}\left\vert y-m \right\rvert }+\mathds{1}_{ \{y\notin (\ell,u) \} }\frac{p_Z^{(k)}(x) }{\left\vert y-m \right\rvert}+\mathds{1}_{\{y\in(\ell,u) \}}C(x);
\end{align*}
and 
\begin{align*}
    &\abs{g'_{k,x}(y)}\\
    &\leq \mathcal{U}_2(k,x,y):=\mathds{1}_{\{y\in(\ell,u) \}}\brac{C(x)\frac{\left\vert y-m \right\rvert}{\left\vert b(y) \right\rvert}+\frac{p_\mathcal{Z}^{(k)}(x)}{\left\vert b(y) \right\rvert}+C'\frac{\sum_{j=0}^{k+1}\left\vert y \right\rvert^j}{\left\vert b(y) \right\rvert^{k+1}} }\\
    &\qquad\qquad\qquad\qquad\qquad+\mathds{1}_{ \{y\geq u \} }C'\frac{\sum_{j=0}^{k+1}\left\vert y \right\rvert^j }{\left\vert b(y) \right\rvert^{k+1}\left\vert y-m \right\rvert^2 }+\mathds{1}_{ \{y\notin (\ell,u) \} }C'\frac{p_Z^{(k)}(x) }{\left\vert y-m \right\rvert^2}\,,  
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:LSI:wu of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $\varphi \in C^2(\ensuremath{\mathbb{R}}^d)$. Define the differential operator $\mathcal{L}_\varphi := \Delta - 
abla \varphi \cdot 
abla$. Let  $\mathcal{L}_\varphi^{-1}$ denote the Poisson operator, which is the inverse of $\mathcal{L}_\varphi$ on the Banach space of Lipschitz continuous functions $C_{	ext{
ormalfont Lip}, 0}(\ensuremath{\mathbb{R}}^d)$. That is, for $f \in C_{	ext{
ormalfont Lip}, 0}(\ensuremath{\mathbb{R}}^d)$, $h = \mathcal{L}_\varphi^{-1} f$ if $\mathcal{L}_{\varphi} h = f$. Recall the definition of $w(r, \varphi)$ in (equation eq:LSI:w of the paper). If
     egin{align*}
        \hat{c}(\varphi) :=  rac{1}{4} \int_0^\infty s \exp igg(\int_0^s  rac{1}{4}w(r, \phi) dr  igg) ds < \infty,
    \end{align*}
    then $\mathcal{L}_\varphi^{-1}$ is a bounded operator on $C_{	ext{
ormalfont Lip}, 0}(\ensuremath{\mathbb{R}}^d)$ and we have $\|\mathcal{L}_\varphi^{-1} \|_{	ext{
ormalfont Lip}} < \hat{c}(\varphi).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Dtilde-implies-coupling of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] The event $\{\widetilde{D}_k(B) =0\}$ implies that $U_{T_k}^{B,\pi \wedge Q}(B) =  U_{T_k}^{B,\pi}(B)$. If moreover 
    \begin{align*}
        \mathsf{StatEquiv}_{\ge k}(B) & = \bigcap_{k'\ge k} \bigcap_{B' \in \mathscr{B}_{k'}: B\subset B'} \mathsf{StatEquiv}(B')\,.
    \end{align*}
    holds, then we have that $X_{T_k}^{\pi \wedge Q}(B) = X_{T_k}^{\pi}(B)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2606.24599, '\bf Perron--Frobenius theorem for a general tree-valued growth-fragmentation-isolation pro'] Let $V=|\, \cdot \,|^2$ and $h$ be the right eigenvector of $\L$, then there exist constants ${\tau>0}, \ {0<a<e^{\lambda \tau}},\ {b\geq 0}$ and $\ K\subset \TT$ such that: 
        \begin{enumerate}
            \item $M_{\tau}V\leq aV+b\Ind{K}h$, where $K$ is a non-empty finite subset of $\TT$;
            \item $M_{\tau}h=e^{\lambda\tau}h$;
            \item For any $\tt_1, \tt_2\in K$, 
            $$\delta_{\tt_1}M_{\tau}(\Ind{\tt_2})>0. $$
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (\cite{namba74}, see also Section 2.1 in \cite{Streets-Ustinovskiy21}) of arXiv:2608.30638, 'On compact steady pluriclosed soliton surfaces'] Let $(M,J)$ be a primary Hopf surface of class $1$, and we work over the open subset $\{z_1z_2\neq 0\}$. Consider the logarithmic coordinates
\begin{equation}
    w_j=x_j+\sqrt{-1}y_j=\log z_j.
\end{equation}
Define
\begin{equation}
    R_j=\partial_{x_j}, T_j= J R_j=\partial_{y_j}.
\end{equation}
Write
\begin{equation}
    a=\Re\log\alpha,\ b=\Re\log\beta,
\end{equation}
and consider
\begin{equation}
    Z=aR_1+b R_2.
\end{equation}
Then the maximal compact torus $T_{\mathrm {std}}\subset G$ has Lie algebra
\begin{equation}
    \mathfrak t_{\mathrm {std}}=\mathrm{span}_{\mathbb R}\{T_1, T_2, Z\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor entropicCommutatorTemperatureInterpolation of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Assume the hypotheses of (thm:entropicCommutator of the paper) and moreover that the sharp pointwise commutator bound holds with the scale $a_{N,\mathsf{s}}$ from (equation eq:temperatureInterpolationScale of the paper): there are constants $C_{\mathrm{pw}}(\mu,v,n),C_{\mathrm{pt}}(\mu)<\infty$ such that, for every $N\ge1$ and every configuration $X_N$,
\begin{align}
\big|\mathsf A_n(v,X_N,\mu)\big|
\le C_{\mathrm{pw}}(\mu,v,n)
\pa*{\mathsf{F}_N(X_N,\mu)+C_{\mathrm{pt}}(\mu)\frac{a_{N,\mathsf{s}}}{N}}.
\end{align}
Then, for every $f_N\in\mathcal{P}(({\mathbb{R}}^\mathsf{d})^N)$,
\begin{align}
\Big|{\mathbb{E}}_{X_N\sim f_N}\Big[N\mathsf A_n(v,X_N,\mu)\Big]\Big|
\le
\min\Big\{
&C_{\beta,n,v}N\mathsf{E}_N(f_N,\mu)+C_{\beta,\mu,v,n},\nonumber\\
&C_{\mathrm{pw}}(\mu,v,n)N\mathsf{E}_N(f_N,\mu)
+C_{\mathrm{pw}}'(\mu,v,n)a_{N,\mathsf{s}}
\Big\},
\end{align}
where one may take $C_{\mathrm{pw}}'(\mu,v,n)=C_{\mathrm{pw}}(\mu,v,n)C_{\mathrm{pt}}(\mu)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

