with the domains of integration given by 
    \begin{align}
        D_1 :=  [-R,R]^2,
        \qquad
        D_2 := [-R,R] \times (\mathbb{R} \setminus [-R,R]),
        \qquad
        D_3 := (\mathbb{R} \setminus [-R,R]) ...","release_manifest_digest":"sha256:ac687f511f9722d8c5488f90dd1f503a12e92bdb2f88ba121e0068499975a5a0","revision_digest":"sha256:d28ee65f14166c76f2ff5148ee576a2446c52fd34545c0c86fc6e891b04576f3","source_id":"arxiv:2608.23156","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

