[Prop p.ST of arXiv:2606.11043, 'Thick points under Gaussian free field dynamics'] Let $\Psi$ be a SHEF, $\gamma>0$ and define the set of $\gamma$-thick points as
    \begin{align*}
    T_\gamma:=\left \{(x,t): \gamma^+_x(t):=\limsup_{\varepsilon \to 0} \frac{ \Psi_\varepsilon(t,x)}{-\log(\varepsilon)}=\gamma\right \}.
    \end{align*}
    Then, 
    \begin{itemize}
        \item If $\gamma>\sqrt{8}$, a.s. $T_\gamma=\emptyset$, i.e., no $\gamma$-thick points exist.
        \item If $\gamma<\sqrt{8}$, a.s. $T_\gamma\neq \emptyset$ and the Hausdorff dimension of $T_\gamma$ is given by $(3-\gamma^2/4)\wedge (4-\gamma^2/2)$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2605.03206, 'The maximum-entropy median-martingale'] For every $p<0$, $\set{X_t}_{t\in\N}$ given by \cref{a9} almost surely converges to
\[
\Ber\pare{
\frac12-\frac{x^{p-1}-\left(1-x\right)^{p-1}}{2\left(x^{p}+\left(1-x\right)^{p}\right)^{\frac{p-1}{p}}}
}
\]

[Corollary 2 of arXiv:2608.29298, 'On Hypersurfaces of Space Forms that are Gradient Yamabe Solitons'] If the space form $\left(\overline{M}^n(C), \overline{g}\right)$ is simply connected and the isometric immersion $ \Sigma^{n-2}\hookrightarrow \overline{M}^n(C)$ is full then the equality for $\sup\limits_{\Sigma}\left|\Phi^{\Sigma}_{\overline{M}}\right|^2$ holds and is attained at some point of $\Sigma^{n-2}$ if, and only if, $\left(M^{n-1}, g\right)$ is isometric to either
    \begin{enumerate}
        \item a Riemannian product of $\mathbb{R}$ and irreducible symmetric $R$-spaces;
        \item or a Riemannian product of $\mathbb{R}$ and a hypersurface of a simply connected space form $\overline{M}^{n-1}\left(C+h^2\right)$ with constant scalar curvature, where $h>0$. 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 44 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $z,w\in D$ and $b> v\vee (2\lambda)$. Then
\begin{equation}

\PP\Big(z\stackrel{D\setminus A_{0,b}}{\longleftrightarrow} w, \ell_{0,b}(z) = b\Big)
\leq
\PP(\ED(\partial D,\Gamma_{0,b}(z))\leq G_{D}(z,w) + \log(2)/\pi, \ell_{0,b}(z) = b).
\end{equation}

