[Proposition prop:lumped-BE-kernel of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] Let $\overline K$ and $\overline\pi$ be the transition kernel and stationary distribution of the lumped twisted Bose--Einstein Markov chain on $\mathrm{Comp}_{n,k}$. Then for all $\bm{i},\bm{j}\in\mathrm{Comp}_{n,k}$,
\begin{equation}
 \overline K(\bm{i},\bm{j})
 =
 \sum_{M=(m_{a,b})\in\mathcal{M}(\bm{i},\bm{j})}
 \prod_{a=1}^k\frac{i_a!}{(\theta)_{(i_a)}}
 \prod_{a,b=1}^k
 \frac{(\theta/k)_{(m_{a,b})}}{m_{a,b}!}
\end{equation}
and
\begin{equation}
 \overline\pi(\bm{i})
 =
 \frac{n!}{(k\theta)_{(n)}}
 \prod_{a=1}^k\frac{(\theta)_{(i_a)}}{i_a!}.
\end{equation}
In particular, $\overline\pi$ is the Dirichlet--multinomial distribution with parameters $n$ and $(\theta,\ldots,\theta)$.

[Theorem T:PTLB of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] Suppose $\gamma d \le 1$. Let $K_0$ be defined by (equation D:K0 of the paper) and $C_2$ be the constant in Proposition (P:ETnLB of the paper).
Then there exists constants $C < \infty$ and $\delta_0 \in (0, 1)$ small such that for all $\varepsilon \in (0, \delta_0)$ and $1 \le u \le 4^{-1}C_2K_0 f(\varepsilon)$, we have
\begin{align}
{\mathbb P}\{ T_\varepsilon \ge u\varepsilon^d f(\varepsilon) \} \ge e^{-Cu}.
\end{align}

[Prop 6 (Large-noise equalization and upper crossover) of arXiv:2608.30374, 'Compact and Infinite-Order Error Analysis\\ for Null-Space SVD Estimation'] Assume additionally that \(\tau\geq m\), and that the ordered projector
expansion at inverse noise has an \(L^1\) remainder through fourth order.
Set \(\overline Z=Z/h_\star\), \(\overline B=B/h_\star^2\), and
\(t=\zeta^{-1}\).  Let
\begin{equation}
 \Pi_i(t)=\sum_{k\geq0}t^k\Pi_{i,k}^{(\infty)}

\end{equation}
be the ordered rank-one eigenprojector of
\((\cE+t\overline Z)(\cE+t\overline Z)^T\).  Then
\begin{equation}
 \varepsilon_{\mathrm{gen},i}^{\mathrm{ord}}(\sigma)
   =h_\star^2\left(
      \zeta^2+c_\infty+d_i^{(\infty)}\zeta^{-2}
      +O(\zeta^{-4})\right),

\end{equation}
where
\begin{equation}
 c_\infty=\frac{\operatorname{tr}(\overline B)}{m}
   =\frac{\|H\|_F^2}{m h_\star^2},
 \qquad
 d_i^{(\infty)}=\operatorname{tr}\!\left(
   \overline B\,\mathbb E_{\mathrm{tr}}
      [\Pi_{i,2}^{(\infty)}]\right).

\end{equation}
In unscaled variables, the common leading law is
\begin{equation}
 \boxed{
 \varepsilon_{\mathrm{gen},i}^{\mathrm{ord}}(\sigma)
   =\sigma^2+\frac{\|H\|_F^2}{m}+O(\sigma^{-2}).}

\end{equation}
Consequently,
\begin{equation}
 \Delta_{\mathrm{rank}}(\sigma)
   =C_H\zeta^{-4}+O(\zeta^{-6}),
 \qquad
 C_H=\frac{\max_i d_i^{(\infty)}-\min_i d_i^{(\infty)}}
          {\sqrt{q_0}}.

\end{equation}
When \(C_H>0\), the leading upper visibility crossover is
\begin{equation}
 \boxed{
 \sigma_{\mathrm{hi}}(\delta_{\mathrm{vis}})
   \simeq h_\star
       \left(\frac{C_H}{\delta_{\mathrm{vis}}}\right)^{1/4}.}

\end{equation}

