[Theorem thm_1.3 of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] For any $d\ge 3$ with $d\neq 6$ and for any $\lambda\ge 1$, there exist constants $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d),
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d,\lambda)>0$ such that for any $M\ge 1$ and  $N\ge \ensuremath{C_{\ref*{const_volume_sharp1}}}M$, 
		\begin{equation}
		\widehat{\mathbb{P}}_{d,N}\big(\mathcal{V}_{M}^{\ge 0}\ge \lambda M^{(\frac{d}{2}+1)\boxdot 4}  \big)  \ge \ensuremath{c_{\ref*{const_volume_sharp2}}}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem p1qlarge of arXiv:2509.24452, 'A family of non-uniform distributions on the set of parking functions generated by random '] Consider $\pi_1$ under the measure $\mathcal{P}_n^{(q_n)}$ with $q_n$ bounded and
$0<q_n-1=\omega(\frac1n)$ (equivalently, $\frac1n=o(q_n-1)$).
Then $\frac{\pi_1}n$ converges in distribution to the uniform  distribution on $[0,1]$.

Also, for fixed $q>1$,
\begin{equation}
\begin{aligned}
&\mathcal{P}_n^{(q)}(\pi_1=k)=\frac1nq^{k-1}(q-1)\sum_{j=k}^n\frac1{q^j-1},\ k=1,2,\cdots, n;\\
&\mathcal{P}_n^{(q)}(\pi_1=n-k)\sim\frac1n\left(1-\frac1{q^{k+1}}\right),\ k=0,1,\cdots.
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

