[Lemma 30 of arXiv:2604.00630, 'The contact process on a bipartite spatial network'] Let~$\pi=(\pi_0,\ldots,\pi_\ell)$ be a combinatorial path of length~$\ell$ with~$k$ distinct vertices; assume that~$\pi_\ell \notin\{\pi_0,\ldots,\pi_{\ell-1}\}$. Let~$T$ be the discovery tree of~$\pi$. Let~$\mathcal Q(\pi)$ be the probability that there exists an infection path in~$\mathcal G$ started at the root and having an ordered trace~$\Gamma$ satisfying the following properties:
\begin{itemize}
\item the combinatorial path associated to~$\Gamma$ is~$\pi$;
\item all vertices of~$\Gamma$ are blue.
\end{itemize}
Then,
	\[
		\mathcal Q(\pi) \le 
			(2\lambda^{a \wedge 1})^{(\ell-2k)\vee 0} \cdot F(T,\pi_0,\pi_\ell). 
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm -1 of arXiv:2411.13403, 'Path weighting method for spot sensitivities and its variance reduction'] If $F(S)$ has generalised derivatives with at most
polynomial growth a.e., then the random variables 
\begin{equation}
\xi=\frac{1}{\sqrt{\Delta t_{1}}}\Big(F(S)\Theta^{(1)}(s,Z_{1},\sqrt{\Delta t_{1}}Z_{1})-F(\hat{S})\Theta^{(1)}(s,Z_{1},\sqrt{\Delta t_{1}}\hat{Z}_{1})\Big),
\end{equation}
\begin{equation}
\eta_{1}=\frac{1}{\sqrt{\Delta t_{1}}}\Big(F(S)\Lambda^{(1)}(s,Z_{1},\sqrt{\Delta t_{1}}Z_{1})-F(\hat{S})\Lambda^{(1)}(s,Z_{1},\sqrt{\Delta t_{1}}\hat{Z}_{1})\Big),
\end{equation}
have variance of order
\begin{align}
\mathrm{Var}(\xi) & =\mathrm{O}(1),\;(\Delta t_{1}\to0),\\
\mathrm{Var}(\eta_{1}) & =\mathrm{O}(1),\;(\Delta t_{1}\to0).
\end{align}
If, in addition, $F(S)$ has second order generalised derivatives
with at most polynomial growth a.e., then the random variable
\begin{equation}
\eta_{2}=\frac{1}{\Delta t_{1}}\Big(F(S)\Lambda^{(2)}(s,Z_{1},\sqrt{\Delta t_{1}}Z_{1})-2F(\bar{S})\Lambda^{(2)}(s,Z_{1},\sqrt{\Delta t_{1}}\bar{Z}_{1})+F(\hat{S})\Lambda^{(2)}(s,Z_{1},\sqrt{\Delta t_{1}}\hat{Z}_{1})\Big)
\end{equation}
has variance of order
\begin{equation}
\mathrm{Var}(\eta_{1})=\mathrm{O}(1),\;(\Delta t_{1}\to0),
\end{equation}

Let f be an orientation-preserving homeomorphism of the circle and let F be any lift of f to the real line. The limit rho(F) = lim_n (F^n(x) - x)/n exists, is independent of x, and its class modulo 1 - the rotation number rho(f) - is independent of the lift; it is invariant under topological conjugacy by an orientation-preserving homeomorphism. Moreover rho(f) is RATIONAL if and only if f has a periodic orbit, and when rho(f) = p/q in lowest terms every periodic orbit has period exactly q. When rho(f) is irrational, f has no periodic point, every orbit has the same combinatorial order as an orbit of R_{rho}, and f is semi-conjugate to the rigid rotation R_{rho}; the semi-conjugacy is a conjugacy exactly when f has no wandering interval.
Orientation-preserving and merely a HOMEOMORPHISM - no smoothness is used here;
smoothness enters only in Denjoy's theorem to upgrade the semi-conjugacy to a conjugacy.

[Thm bigthm of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Let $r$ be large enough. Under (sass-A of the paper)-(SPDE-G-sass of the paper), for every $R \geq 0$, $\theta \in \Theta$, and initial condition $\tilde{x}_0 \in C(\overline D)_+$ there is a unique mild solution in $L^r$ (see (def:mild of the paper)), denoted by $\tilde{x}_t = (\tilde{u}_t, \tilde{z}_t)$, to
    \begin{equation}
        \tilde{x}_t =S(t) \tilde{x}_0 + (S * \tilde F(R,\tilde{x},\theta))_t + (S \diamond \tilde G(R, \tilde{x},\theta))_t
   \end{equation}
    Furthermore, the following properties hold:
    \begin{enumerate}[label=(\roman*)]
        \item  $\tilde{x}_t \geq 0$.
        \item  $\tilde{u}_t = 0 \iff \tilde{u}_0 = 0$.
        \item  $t \mapsto \tilde{x}_t$ is almost surely a continuous map from $[0,\infty)$ to $B$.
        \item  If $(R_n,\tilde{x}_0^{(n)},\theta_n) \to (R,\tilde{x}_0,\theta)$ in $[0,\infty) \times C(\overline D)_+ \times \Theta$, then $\tilde{x}^{(n)}$, the solutions to (equation eq:mild-solution of the paper) with initial condition $\tilde{x}_0^{(n)}$ and $R = R_n$, $\theta = \theta_n$, converge to $\tilde{x}$ in $L^p(\Omega;C([0,T];B))$ for all $p,T > 0$.
        \item  If $\tilde{u}_0 \neq 0$ then $(r_t,v_t) \coloneqq (R\|\tilde{u}_t\|_{L^1}, \tilde{u}_t/\|\tilde{u}_t\|_{L^1})$ satisfies
        \begin{equation}
            \begin{aligned}
            dr &= r[\ip{v}{\tilde e_u} + \ip{\tilde F_u(r,v,\tilde{z})}{1_u}]dt + r\ip{\tilde G_u(r,v,\tilde{z})^*1_u}{dW_t} \\
            dv &= A_uvdt + v[-\ip{v}{\tilde e_u} - \ip{\tilde F_u(r,v,\tilde{z})}{1_u} + \|\tilde G_u(r,v,\tilde{z})^*1_u\|_\mathcal{U}^2]dt \\
            &+ \tilde F_u(r,v,\tilde{z})dt - \tilde G_u(r,v,\tilde{z})\tilde G_u(r,v,\tilde{z})^*1_udt \\
            &+ \tilde G_u(r,v,\tilde{z})dW_t- \ip{\tilde G_u(r,v,\tilde{z})^*1_u}{dW_t}v \,,
        \end{aligned}
    \end{equation}
    where the equation for $v$ holds in the mild sense of (def:mild of the paper). We omitted the dependence on $\theta$ for brevity.

    \item  Let $\bar{x}_t \coloneqq (R\tilde{u}_t, \tilde{z}_t) = (r_tv_t,\tilde{z}_t)$, where $(r_t, v_t)$ was defined in (v). Then
    \begin{equation}
        d\|\bar x_t\|_{\beta,2}^2 = [-2\|\bar x_t\|_{\beta+1/2,2}^2 +2\ip{\bar x_t}{F(\bar x_t)}_\beta + \|G(\bar x_t)\|_{\beta,2}^2]dt + 2\ip{\bar x_t}{G(\bar x_t)dW_t}_\beta \,,
    \end{equation}
    where $\beta$ is as in (SPDE-G-lem of the paper). 
    \end{enumerate}

