[Theorem 14 of arXiv:2609.01333, '2609.01333'] Let $\gamma\in (0,\gamma_*)$ and $\lambda_{*}=\lambda_*(\gamma)$ be as in Theorem \ref{thm:Lambda-star}.  For every $f\in Y^\perp$ there exists a unique $w\in X^\perp$ such that
\begin{align}
L_{\lambda_*} (w)=f \quad \text{ on  $~\mathbb{R}$}.
\end{align}
In addition, the restriction $L_{\lambda_*} : X^\perp \to Y^\perp$ is bijective with range $R(L_{\lambda_*}) = Y^\perp$.

[Lemma 9 (Definition and triangularity of $\Gamma$) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $ (\pi^{(\n)} )_{\n\in\NN^{1+d}} \subset \RR [\![ z_{k}, z_{\n} ]\!]$ such that for all $\beta$ and $\n$ it holds that $\pi^{(\n)}_{ \beta} \neq 0$ implies $ |\n| < | \beta| $.
Then 
\begin{enumerate}
\item the map $ \Gamma :  \RR [\![ z_{k}, z_{\n} ]\!] \to  \RR [\![ z_{k}, z_{\n} ]\!]$ defined by 
\begin{equation}
\begin{aligned}
\Gamma z_{k}\coloneqq z_{k}\,, \quad 
\Gamma z_{\n}\coloneqq z_{\n}+ \pi^{(\n)}\,, \quad 
\Gamma 1\coloneqq 1\,, \quad \text{and}\quad 
\Gamma ( \pi_{1} \pi_{2}) = (\Gamma \pi_{1}) ( \Gamma \pi_{2})
\end{aligned}
\end{equation} 
for $\pi_1,\pi_2\in\RR[\![z_k,z_\n]\!]$
is well-defined on $\RR [\![ z_{k}, z_{\n} ]\!]$, 

\item for all $\beta,\gamma$ it holds that $ (\Gamma - \mathrm{id})_{ \beta}^{ \gamma}
\neq 0$ implies $ | \gamma| <
| \beta| $ and $\langle\gamma\rangle<\langle\beta\rangle$, and

\item if $ (\pi^{(\n)} )_{\n\in\NN^{1+d}} $ is such that $ \pi^{(\n)}_{ \beta'} = 0$ for all non populated $\beta'$, then for all $\beta,\gamma$
\begin{equation}
\begin{aligned}
(\Gamma - \mathrm{id})_{ \beta}^{ \gamma} \neq 0 \quad \implies \quad \gamma
\prec \beta\,.
\end{aligned}
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L_strTWB of arXiv:2510.26724, 'Sharp Fuss-Catalan thresholds in graph bootstrap percolation'] Let $T$ be a TWG and $S\subsetneq T$ a partial TWG. Then, 
\begin{enumerate}
\item $\mathcal E(S)\geqslant 0$, with equality 
if and only $S$ is obtained from $T$ 
by removing one of its branches; 
\item $\mathcal D(S,T)\leqslant c\mathcal E(S)+2$; and 
\item $\mathcal T(S)\leqslant c\mathcal E(S)$, 
\end{enumerate}
for some constant $c$ depending only on $r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition LAST of arXiv:2411.18374, 'Drawdowns of diffusions'] For $\delta>\rho$
\begin{align}

&{\bf P}_0\left( T^+_\rho>\delta\,|\, M_{\theta_\rho}=y\right)=
 \frac{S(y)-S(y-\rho)}{S(y)-S(y-\delta)},
\end{align}
and for $0<\delta<\rho$
\begin{align}

\nonumber
&{\bf P}_0\left( T^-_\rho<\delta\,|\, M_{\theta_\rho}=y\right)\\
&\hskip2cm =\exp\left(-\int_{0}^{y}\frac{S(dt)}{S(t)-S(t-\delta)} + \int_{0}^{y}\frac{S(dt)}{S(t)-S(t-\rho)}\right).
\end{align}

