[Prop Prop_AdmissibleZ2ZSpinor_NonDegenerate of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Assume that $\rk_\mathbb{A}\check S = 2$.
  Denote by $f \mskip0.5mu\colon\thinspace {\mathbf{E}}_{00}^* \subseteq {\mathbf{E}}_{00} \to \mathbf{Dir} \times \mathbf{Ram}$ the projection map and by
  \begin{equation*}
    {\mathbf{V}} \subseteq (p^*f)^* \check {\mathbf{S}}
  \end{equation*}
  the subbundle such that for every $({\mathbf{p}},[{\mathfrak l}];\Phi) \in {\mathbf{E}}_{00}^*$
  \begin{equation*}
    {\mathbf{V}}_{{\mathbf{p}},[{\mathfrak l}];\Phi} = \im {\mathbf{L}}_\Phi.
  \end{equation*}
  $({\mathbf{E}}_{00}^*,f,{\mathbf{V}})$ is a family of local residue conditions that satisfies the hypothesis of (Prop_TotallyReal=>UniformlyFredholm of the paper).

[Theorem thm::cvg_proba of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] Let $\Omega\subseteq \mathbb{C}$ be a simply connected domain and $z_1,\ldots,z_n\in \Omega$ be $n$ distinct points. Let $\Omega^{a}\subseteq a\mathbb{Z}^2$ be a sequence of simply connected domains that converges to $\Omega$ in the  Hausdorff metric\footnote{Our proofs can be generalized to the Carath\'edory convergence of discrete domains easily, which is weaker than the Hausdorff convergence used in this paper for simplicity.} as $a\to 0$. Suppose that $z_1^a,\ldots,z_{n}^a\in \Omega^a$ are vertices satisfying $\lim_{a\to 0}z_j^a = z_j$ for $1\leq j\leq n$. Let $\mathbf{Q}$ be a partition of $\{1,2,\ldots,n\}$ that contains no singletons. Then we have the following:
\begin{enumerate}[label=\textnormal{(\arabic*)}, ref=(\arabic*)]
    \item The limit 
    \begin{equation} 
		P(\Omega;\mathbf{Q};z_1,\ldots,z_n):=\lim_{a\to 0}a^{-\frac{n}{8}}\times \mathbb{P}^a_{\Omega}\left[G(\mathbf{Q};z_1^a,\ldots,z_{n}^a)\right]
	\end{equation}
exists and belongs to $(0,\infty)$.  
\item The function $P$ defined via~(equation eqn::def_P of the paper) satisfies the following conformal covariance property: if $\varphi$ is a conformal map from $\Omega$ onto some $\Omega'$ such that $\varphi(z_j)\neq \infty$ for $1\leq j\leq n$, then we have 
	\begin{equation} 
P(\Omega';\mathbf{Q};\varphi(z_1),\ldots,\varphi(z_n))=P(\Omega;\mathbf{Q};z_1,\ldots,z_n)\times \prod_{j=1}^n |\varphi'(z_j)|^{-\frac{1}{8}}.
	\end{equation} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2605.18136, 'L\'evy processes with partially stochastic resetting'] Let $p \in (0,1)$, $q,x,a,u \geq 0$ with $a \geq x$ and $z,\gamma \in \R$. Furthermore, for $f \in  C_{[0,a]}$, consider the integral operator 
		\begin{equation}
			\mathcal{A}f(x) = h(x-z) + \frac{\gamma}{p} \int^{xp}_{u} W^{(q)}(x - yp^{-1}) f(y) \dd y,  
		\end{equation}
		for a chosen $h \in  C_{[0,a]}$, and for which we shall denote $\mathcal{A}^0f(x) = f(x)$ and  $\mathcal{A}^{n+1}f(x) = \mathcal{A}[\mathcal{A}^{n}f(x)]$ for $n \geq 0$.  Then, the unique fixed point of $\mathcal{A}$ is $\mathcal{G}^{(q,p)}_\gamma h(x;u,z)$.

