[Lemma 6 (Cauchy-area theorem for Bernoulli width) of arXiv:2608.11031, 'A Bayesian Proof of the Bernoulli Theorem'] For any $x \in T$, the function $\Phi_x: [0,\infty) \rightarrow [0,+\infty)$ is nondecreasing and concave on $[0,\infty)$ with $\Phi_x(0)=0$. Moreover, it satisfies
\begin{equation}
  b(T)=\lim_{t \to \infty} \Phi_x(t)=\int_0^\infty \Phi_x'(t)\,dt.

\end{equation}
The derivative is understood almost everywhere.

[Corollary 37 of arXiv:2512.00213, 'On strong sharp phase transition in the random connection model'] Suppose that $\phi^*_t(r)$ decays 
exponentially as $r\to\infty$. Then, under the conditions of Corollary \ref{c:subcrit}, there exists $\delta=\delta(t,n)>0$ such that
    \begin{align*}
       \esssup_{v\in\BX} \BE_t e^{\delta D(V^{v})}<\infty.
    \end{align*}

[Lemma lem: bound T1 of arXiv:2512.12902, 'Non-equilibrium fluctuations for the \\stirring process with births and deaths'] Let $n\geq 2$. For any  $\underline{z}=(z_1,\dots,z_n)$ and $\underline{y}=(y_1,\dots,y_n)$ in $\Lambda_{N}^{n,\neq}$, the transition probability to go from $\underline{z}$ to $\underline{y}$ in a time $\lambda>0$ is bounded as:
\begin{equation}
\mathbf{P}_{\epsilon}(\underline{y}\overset{\lambda}\rightarrow\underline{z})\leq c_n \frac{1}{{{[\epsilon^{-2}\lambda]}^{n/2}+1}}\leq c_n \frac{1}{{{[\epsilon^{-2}\lambda]}^{1-\zeta}}}
\end{equation}
for some  constant $c_n>0$ which depends on $n$ and for some small $\zeta>0$. For $n=1$
\begin{equation}
\mathbf{P}_{\epsilon}(y\overset{\lambda}\rightarrow z)\leq c_1 \frac{1}{{[\epsilon^{-2}\lambda]}^{1/2}+1}.
\end{equation}

