[Theorem thm:rate of arXiv:2509.03048, 'Elephant random walks on infinite Cayley trees'] Let $p \in [0, 1)$. Then for any $m \in [1, 2]$,
    \begin{equation}
        \mathbb{E} \bigg|\frac{\Delta_n}{n} - \frac{d - 2}{d}\bigg|^m \lesssim r_n^{-m}.
    \end{equation}
    In the supercritical regime, (equation eq:upper-bd of the paper) holds for a larger range of $m$, namely, for all $m \in [1, \frac{d - 1}{d(1 - p)}]$.

    In fact, in the subcritical regime $p < p_d$, in a neighbourhood of $1/d$, we can show a matching lower bound: For any $m \in [1, 2)$, there is $\epsilon > 0$ such that for all $p \in (1/d - \epsilon, 1/d + \epsilon)$, one has
    \begin{equation}
        \mathbb{E} \bigg|\frac{\Delta_n}{n} - \frac{d - 2}{d}\bigg|^m \gtrsim n^{-m/2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemme 56 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let $\mu \in \mathcal{M}_1(\mathbb{R})$ and $\rho > 1$. Then $\op{s}_{\rho \#} \mu \to \mu$ as $\rho \searrow 1$ in the weak topology. Moreover,
\begin{align*}
   &\text{if } \int x \,  \mathrm{d} \op{s}_{\rho \#} \mu(x) =0   & &\text{ then } & & \int x \,  \mathrm{d} \mu(x) =0  \, , \\
   &\text{and if} \int |x|^\theta \,  \mathrm{d}\mu(x) < +\infty  & & \text{ then } & &  \int |x|^\theta \, \mathrm{d} \op{s}_{\rho \#} \mu(x) < +\infty \, .
\end{align*}
Furthermore,
if $\mu$ satisfies \eqref{cond1} then
\begin{align}

    1+\frac{2}{\ell} \Int{\mathbb{R}}{} \ln|x-y| \, \mathrm{d}(\op{s}_{\rho \#} \mu) (y) \, \geq \, 2\kappa := \frac{2}{\ell} \ln \rho > 0,\quad \op{s}_{\rho \#} \mu \quad a.s.

\end{align}

[Corollary cor:roleofFouriermodes of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Under the conditions of Theorem~(thm:NGlimit of the paper),  for $\vec{k} \in \mathbb{K}$,  as $N\rightarrow \infty$,
\begin{align}
	(\vec{k}=0) \qquad 
		& \chi_{g,\nu_c, N}^{(0)} \sim c_3^{-1/2} \E \big[ |Y|^{2} \big] \times \begin{cases}
		N^{1/2} L^{2 N} & (d = d_{c,u}) \\
		L^{\frac{d}{2} N} & (d > d_{c,u}) 
	\end{cases} \\
	(\vec{k} \neq 0) \qquad 
		& \chi_{g,\nu_c, N}^{(\vec{k})} \sim n c_4^{-1} |\vec{k}|^{-2+\eta} L^{(2-\eta) N} .
\end{align}

