[Lemma lem:GRR of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Let $\gamma < \frac{1}{2}$, $p > 2$, and let $\xi \colon [-r,0] \rightarrow \mathbb{R}^n$ be an $\gamma$-H\"older path. Then, there exists a constant $A_p$ such that
				\begin{align}
					\| \xi \|_{\gamma} = \sup_{-1 \leq s < t \leq 0}\frac{\|\xi_{s,t}\|}{(t-s)^{\gamma}} \leq A_p \left( \iint_{[-r,0]^2} \frac{\|\xi_u - \xi_v\|^p}{|u-v|^{p\gamma + 2}} \, du \, dv \right)^{\frac{1}{p}}.
				\end{align}
				If $X$ is $\gamma$-H\"older and $(\xi, \xi') \in \mathscr{D}_{X}^{\gamma}([-r,0])$, then
				\begin{align}
					\sup_{-r \leq s < t \leq 0}\frac{\|\xi^{\#}_{s,t}\|}{(t-s)^{2\gamma}} \leq A_p \left[ \left( \iint_{-r \leq u < v \leq 0} \frac{\|\xi^{\#}_{u,v}\|^p}{|u-v|^{2\gamma p + 2}} \, du \, dv \right)^{\frac{1}{p}} + \|\xi'\|_{\gamma} \|X\|_{\gamma} \right].
				\end{align}

[Lemma explexpr of arXiv:2411.06827, 'The Exponential Lie Series and a Chen--Strichartz Formula for L{\'e}vy Processes'] For $m\geq 1$, we have the explicit expression 
\begin{align*}
	(\overline i^{(m)})^0 & =\, 
	\sum_{n=1}^m\sum_{j_1+\cdots + j_n=m}
	\frac{(-1)^{n-1}}{n}\overline i^{(j_1)}\cdots \overline i^{(j_n)}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] Let $\alpha>-1/2$. Assume that $\me[\eta]=0$ and $\sigma^2=\me[\eta^2]\in(0,\infty)$. Then
\begin{equation}
C\Big(\Big(\Big(\frac{2^{2\alpha}}{\sigma^2 \Gamma(1+2\alpha)}\frac{s^{1+2\alpha}}{\log\log1/s}\Big)^{1/2}\sum_{k\geq 2} \frac{(\log k)^\alpha \eta_k}{k^{1/2+s}}: s\in(0, \eee^{-1})\Big)\Big)=[-1,1] \quad\text{\rm a.s.},
\end{equation}
where $\Gamma$ is the Euler gamma function.
In particular,
\begin{equation}
\limsup_{s\to 0+}\Big(\frac{s^{1+2\alpha}}{\log\log 1/s}\Big)^{1/2}\sum_{k\geq 2} \frac{(\log k)^\alpha \eta_k}{k^{1/2+s}}=\frac{(\Gamma(1+2\alpha))^{1/2}}{2^\alpha}\sigma
\quad\text{\rm a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:spectralgaplow of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] In the setting of Theorem (thm:characterizeRinfty of the paper), if $\left\lVertP - \Pi\right\rVert_F \leq \left\lVertP - I\right\rVert_F$ or equivalently
	\begin{align*}
		\mathrm{Tr}(P) \leq \dfrac{n+1}{2},
	\end{align*}
	then
	\begin{align*}
		\gamma(R_\infty) \geq \dfrac{1}{2}.
	\end{align*}

