body:
[Prop identity of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] Fixed $L\in\mathbb{N}$, it holds that 
    \begin{align}
    \mathbf{b}_{n,L}
    &=
    \sum_{\ell=n}^{L}
    (-1)^{\ell-n}
    \binom{L}{\ell}\binom{\ell}{n}
    \mathbf{p}_{\ell;L}
    &&\text{for each } 0\leq n\leq L
    ,
    \\
    \mathbf{p}_{\ell;L}
    &=\sum_{n=\ell}^L
    \frac{\binom{n}{\ell}}{\binom{L}{\ell}}
    \mathbf{b}_{n,L},
    &&\text{for each } 0\leq \ell\leq L

    \\
    \mathbf{b}_{n,L}(\eta)
    &\leq
    \binom{L}{n}
    \mathbf{p}_{n;L}(\eta),
    &&\text{for each } \eta\in\Omega_N
    .

    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5 of arXiv:2608.21787, 'Stability of extremal hyperplane projections of balls in $\ell_p^n(\R)$'] Let $Y_1$, $Y_2$ be i.i.d. square integrable random variables whose distribution is not a Dirac delta distribution. Let $a_1$, $a_2$, $b_1$, $b_2$, $s$ also be real numbers such that $s \ge 0$, $a_1^2 + a_2^2 = b_1^2 + b_2^2 = \sigma^2 > 0$ and $a_1^2 \ge b_1^2 \ge b_2^2 \ge a_2^2$. Then there exist positive constants $c$, $\eta$, depending only on the distribution of $Y_1$, such that
        \begin{align*}
            \E\sqrt{b_1^2Y_1^2 + b_2^2Y_2^2 + s} - \E\sqrt{a_1^2Y_1^2 + a_2^2Y_2^2 + s} \ge c\left(s + \eta\sigma^2\right)^{-\frac 3 2}\left(a_1^4 + a_2^4 - b_1^4 - b_2^4\right).
        \end{align*}

[Defi 27 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] Let $(E,\pi,M)$ be a Banach bundle and $U$ be an open set of $M$. A \emph{linear local}  vector field on $E$ is a pair $(\mathcal{X},X)$ where $\mathcal{X}$ is a vector field on $E_{U}$ and $X$ a vector field on $U$ such that
\begin{equation}
\begin{tikzcd}
E_U \arrow[r,"\mathcal{X}"] \arrow[d,"\pi"]& TE_U \arrow[d,"T\pi"] \\ U \arrow[r,"X"] & TU
\end{tikzcd}
\end{equation}
is a bundle morphism. When $U=M$ the pair $(\mathcal{X},X)$ is simply called a \emph{linear vector field} on $E$.

[Lemma lem:exponential-representative of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] The deformed moment admits the exact finite decomposition
\begin{equation}
  \mathcal M_N(\boldsymbol k;\boldsymbol\tau)
  =\sum_{\boldsymbol\varepsilon\in\{0,1\}^m}
    \left(\prod_{p=1}^m\mu_{p,N}^{\varepsilon_p}\right)
    \mathcal A_N(\boldsymbol\varepsilon;
      \boldsymbol k,\boldsymbol\tau).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:e2 of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] For any $N \in \mathbb N$, we have that
\begin{align}
\lVert g^n \rVert_{C^2(\bar \Omega_N)} \leq K(N) \quad \text{for all $n \geq N+10$},
\end{align}
where $K(N)$ is a positive constant depending only on $N$.

