[Korollar cortb of arXiv:2507.08692, 'Some notes on higher order concentration of measure'] Let $F\in L^1(\mathbb{P}_\eta)$. If $\mathbb{P}$-almost surely $V^+ \le L$ or $V^- \le L$ for some $L > 0$, we have that
\[
\mathbb{P} (F - {\mathbb E}[F] \ge t) \le e^{-ct^2/L}\qquad \text{or}\qquad \mathbb{P} (F - {\mathbb E}[F] \le -t) \le e^{-ct^2/L}
\]
for every $t \ge 4\sqrt{\kappa}$ and $c = \log(2)/(8\kappa)$, respectively. Moreover, if $\mathbb{P}$-almost surely $V \le L$ for some $L > 0$, we have that
\[
\mathbb{P} (|F - {\mathbb E}[F]| \ge t) \le 2e^{-ct^2/L}
\]
for every $t \ge 0$ and $c = \log(2)/(16\kappa)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: sumple bound on sums of dimensions of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $n\geq 2$. Let $r\geq 1$. We have
    \begin{equation}
        \sum_{\lambda \vdash n {\ensuremath{\;:\;}} r(\lambda) = r} d_\lambda \leq n^r.
    \end{equation}

[Definition 14 (Bernstein-Sato polynomial of an ideal) of arXiv:2609.03976, '2609.03976'] With the notation above, the Bernstein-Sato polynomial of $\mathfrak a$ on $U$, denoted by $b_{\mathfrak a,U}(s)$, is the monic polynomial of smallest degree such that
		\begin{align}
			b_{\mathfrak{a},U}(s)f_1^{s_1}\cdots f_r^{s_r}
			\in
			\sum_{\substack{u\in \mathbb{Z}^r\\ |u|=1}}
			\mathcal{D}_U[s_1,\ldots,s_r]\cdot
			\left(
			\prod_{u_i<0}\binom{s_i}{-u_i}
			\right)
			f_1^{s_1+u_1}\cdots f_r^{s_r+u_r},
		\end{align}
		where $|u|=u_1+\cdots+u_r$.
		This is the formulation used by Mustaţă in \cite[Introduction]{Mus22}; it is equivalent to the definition of Budur, Mustaţă, and Saito in \cite[Section 2.10]{Bernstein_Sato_polynomial_of_arbitrary_varieties}.

[Corollary eq:block-average-Chernoff of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:sharp-block-average}
In the ordered model, assume the stronger finite-\(N\) profile MGF
condition \(({\rm PSG})_p\).  Let
\(S\subset[N]\), \(\left\lvertS\right\rvert=k\), and set
\[
 \overline J_S=\frac1{k^p}\sum_{I\in S^p}J_I,
 \qquad
 u_S=k^{-1/2}\sum_{i\in S}e_i.
\]
For every \(b,a\ge0\),
\begin{align}
 \mathbb P\{\overline J_S\ge b\}
 &\le\exp\{-k^pb^2/2\},\\
 \mathbb P\{h_N^J(u_S)\ge a\}
 &\le e^{-Na^2/2}.
\end{align}
Moreover,
\begin{equation}
 \mathbb P\left\{\max_{\left\lvertS\right\rvert=k}h_N^J(u_S)\ge a\right\}
 \le\binom Nk e^{-Na^2/2}.
\end{equation}
Hence the right-hand side has exponential rate at most
\(-a^2/2\) whenever \(k=o(N)\).  If
\(k_N=N^{\gamma+o(1)}\), the coefficient level
\[
 b_{N,k_N}(a)=\frac{a\sqrt N}{k_N^{p/2}}
 =aN^{(1-p\gamma)/2+o(1)}
\]
interpolates, for \(0\le\gamma\le1/p\), between a quadratic-scale
spike (with endpoint \(k=1\)) and a fixed-amplitude mesoscopic coherent
block.

[Theorem thm:rad-sdp of arXiv:2606.14687, 'Lehner's operator norm formulas, semidefinite programming, and spiked matrix models'] For any $\bm A_0, \bm A_1, \dots, \bm A_n \in \mathbb{C}^{d \times d}_{\mathsf{herm}}$,
    \begin{align}
      \Lambda_{\mathsf{rad}}(\bm A_0, \bm A_1, \dots, \bm A_n)
      &= \left\{\begin{array}{ll} \text{minimum of} & c \\ \text{subject to} & \bm Z \succeq \bm 0, \\ & \left[\begin{array}{cc} \bm Y_i & \bm A_i \\ \bm A_i & \bm Y_i + \bm Z \end{array}\right] \succeq \bm 0 \text{ for all } i \in [n], \\ & \bm Z + \bm A_0 + \sum_{i = 1}^n \bm Y_i \preceq c \bm I_d, \\ & c \in \mathbb{R}, \bm Z, \bm Y_i \in \mathbb{C}^{d \times d}_{\mathsf{herm}}, \text{ for all } i \in [n] \end{array}\right\}  \\
      \intertext{}
      &= \left\{\begin{array}{ll} \text{maximum of} & \langle \bm A_0, \bm \Delta \rangle + \sum_{i = 1}^n \langle \bm A_i, \bm R_i + \bm R_i^{*} \rangle \\ \text{subject to} & \left[\begin{array}{cc} \bm S_i & -\bm R_i \\ -\bm R_i^{*} & \bm T_i \end{array}\right] \succeq \bm 0 \text{ for all } i \in [n], \\ & \bm S_i + \bm T_i = \bm\Delta \text{ for all } i \in [n], \\ & \bm\Delta - \sum_{i = 1}^n \bm T_i \succeq \bm 0, \\ & \Tr(\bm\Delta) = 1, \\ & \bm\Delta, \bm S_i, \bm T_i \in \mathbb{C}^{d \times d}_{\mathsf{herm}}, \bm R_i \in \mathbb{C}^{d \times d} \text{ for all } i \in [n] \end{array}\right\}. 
    \end{align}
    The two SDPs are Lagrangian duals of one another.
    The minimum in~(equation eq:rad-sdp-primal of the paper) and the maximum in~(equation eq:rad-sdp-dual of the paper) are both always achieved. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:prop4.19 of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] There exist a probability $p_0 := p_0(d) < 1$, an inverse temperature $\beta_0 \in (0 , \infty)$ and a constant $c_0 > 0$ such that for any $p \geq p_0$, any $\beta \geq \beta_0$ and any $L \in \mathbb{N}^*$,
\begin{equation*}
\mathbb{E}_p^{\mathrm{site}} \left[ \mathrm{Var}_{L , \beta, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}  \left[ \varphi(0) \right] \right] \geq c_0 \ln L ~~\mbox{and}~~ \mathbb{E}_p^{\mathrm{site}} \left[ \mathrm{Var}_{L , \beta, r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}}  \left[ \varphi(0) \right] \right] \geq c_0 \ln L.
\end{equation*}

