[Theorem thm:mp-mbic of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Let $ \mathbf{X} _1,\dots,  \mathbf{X} _n$ be $\mathcal{S}_d^{[0,1]}$-valued independent random matrices with common mean $ \mathbf{M} $ and variance $ \mathbf{V} $. We denote by $\overline{ \mathbf{X} }_n$ their sample average and $\widehat{ \mathbf{V} }_n$ the Bessel-corrected sample variance.
    Then, for any $\alpha \in (0,1)$,
    \begin{equation} 
     \mathbb P \left( \lambda_{\max} \left( \overline \mathbf{X} _n - \mathbf{M}  \right) \geqslant   D_n^{\mathsf{meb1c}} \right) \leqslant \alpha,
\end{equation}
where
\begin{equation}\small
    D_n^{\mathsf{meb1c}} =  \sqrt{  \frac{2 \log \frac{nd}{(n-1)\alpha}    }{n} } \left( \|\widehat \mathbf{V} _n\|^{1/2}  +  \sqrt{\frac{\log(2nd/\alpha)}{ 2 n \|\widehat{ \mathbf{V} }_n \| }} \wedge \left( \frac{2\log(2nd/\alpha)}{n} \right)^{1/4}  \right)   + \frac{ \log  \frac{nd}{(n-1)\alpha} }{3n} .
\end{equation}
Further, if $ \mathbf{X} _1,\dots,  \mathbf{X} _n$ are i.i.d.,
\begin{equation}
    \lim_{n\to\infty} \sqrt{n}   D_n^{\mathsf{meb1c}} = \sqrt{2\log(d/\alpha) \| \mathbf{V} \| }, \quad \text{almost surely}.
\end{equation}

