[Lemma 20 (Support growth) of arXiv:2605.27212, '2605.27212'] Fix \(\alpha\in(0,\alpha_*)\).  There is a constant \(C_{p,\alpha}<\infty\) such
that, for all sufficiently large \(r\), the hitting time
\[
    \tau_\alpha=\inf\{t:S_t\ge\alpha r\}
\]
satisfies
\begin{equation}
    \sup_{1\le s\le r}\E_s\tau_\alpha\le C_{p,\alpha}r\log r.
\end{equation}
Consequently, for a suitable \(B_{p,\alpha}<\infty\),
\begin{equation}
    \sup_{1\le s\le r}\Prob_s(\tau_\alpha>B_{p,\alpha}r\log r)\le\frac12.
\end{equation}

[Lemma 32 of arXiv:2608.30570, '2608.30570'] Assume $x$ is a critical point of an analytic function $f$ on a surface $\Sigma$ and $U\ni x$ is an open set with compact closure. Denote  $c=f(x)$ and
\begin{align*}
U^+=\{y\in U| f(y)>c\} \quad \text{ and } \quad U^-=\{y\in U|f(y)<c\}.
\end{align*}
For each $y\in U^+$, consider the negative gradient flow starting from $y$, that is, $\gamma:[0,T)\to \Sigma$ satisfying
\begin{align*}
\sigma(0)=y, \quad \text{ and } \quad \dot{\sigma}(t)=-\nabla f(\sigma(t)).
\end{align*}
Let
\begin{align*}
T_{\partial U}(y)=\sup \{t| \sigma(\tau)\in U, \forall \tau<t\} \quad \text{ and } \quad
T_{c}(y)=\sup\{t|f(\sigma(\tau))>c, \forall \tau<t\}
\end{align*}
 be the first time of touching $\partial U$ or the level set $f^{-1}(c)$ respectively.
Then,  there exists a smaller neighborhood $\hat{U}$ of $x$ such that
\begin{align}
T_c(y)\le T_{\partial U}(y),\quad  \forall y\in \hat{U}\cap U^+ .
\end{align}
Moreover, for any $y\in \hat{U}\cap U^+$, there exists a negative gradient curve $\sigma$ in $U$ joining $y$ to some point $y^-\in f^{-1}(c)\cap U$. For any $y\in \hat{U}\cap U^-$, there exists some point $y^+\in f^{-1}(c)\cap U$ and a negative gradient curve $\sigma$ joining $y^+$ to $y$.  See Figure \ref{fig:negative gradient} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem-tM_n is a martingale of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] \begin{enumerate}
\item[(i)] For every $n\in \mathbb{N}$, the process ${\overline{M}}_{n} $ is a square integrable $U^\prime$-valued ${\overline{\mathbb{F}}}_{n}$-martingale. Moreover,
\begin{equation}
 \sup_{n \in \mathbb{N}}  \overline{\mathbb{E}} \left[ \sup_{t\in [0,T]}\lvert \overline{M}_n(t) \rvert^2_{U^\prime} \right] <\infty.
\end{equation}
\item[(ii)] Moreover, if Assumption F.(assum-F5 of the paper)  is satisfied,  then for every $p\in [2, 4+\gamma] $ and for every $n \in \mathbb{N}$, the process
 ${\overline{M}}_{n} $ is a $p$-integrable $U^\prime$-valued ${\overline{\mathbb{F}}}_{n}$-martingale. Moreover,
\begin{equation}
 \sup_{n \in \mathbb{N}} \overline{\mathbb{E}} \left[ \sup_{t\in [0,T]}\lvert \overline{M}_n(t) \rvert^p_{U^\prime} \right] <\infty.
\end{equation}
\end{enumerate}

[Definition ass:ft of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] There exist constants $ \alpha \in (0, 2]$, $c_0 > 0$, $\varepsilon > 0$, and $0 < \rho < 1$ such that the following assumptions are satisfied:
\begin{enumerate}
  \item (normalization) $f$ is a probabiltiy density
  \begin{equation}
    f(x)\ge 0, \quad \int_{\mathbb R^d} f(u)\,du \;=\; 1;
  \end{equation}
  \item (small-frequency control) for all $|\xi|\le \varepsilon$,
  \begin{equation}
    |\widehat f(\xi)| \;\le\; \exp\!\bigl(-c_0 |\xi|^\alpha \bigr);
  \end{equation}
  \item (high-frequency contraction) for all $|\xi| > \varepsilon$,
  \begin{equation}
    |\widehat f(\xi)| \;\le\; \rho < 1;
  \end{equation}
  \item (regularity/decay) $f$ is a continuous function and for some   constants $T, K > d$ and $C_T, C_{K} > 1$,   
  \begin{equation}
      f(x)\le \frac{C_T}{(1+|x|)^{T}},
    \qquad |\widehat f(\xi)| \;\le\; \frac{C_K}{(1+|\xi|)^{K}} 
      \qquad  x,\xi \in \mathbb R^d.
  \end{equation}
\end{enumerate}

