[Theorem thm:discrete-binary of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] Let $L$ be as in Lemma~(lem:discrete-L of the paper), and let $\eta\in\cB$ be indecomposable. Suppose
    $\eta_1,\eta_2\in\cB$, and set $G_j(z)\coloneqq L(\eta_j(1-z)),$ $j=1,2.$ If
    \begin{align}
        \Phi_L(G_1(z),G_2(z))=L(\eta(1-z))
    \end{align}
    for all $z\in[0,1]$, then there exist $a_1,a_2\ge 0$ with $a_1+a_2=1$ such that
    \begin{align}
        G_j(z)=L(a_j\eta(1-z)), \qquad j=1,2.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 13 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] The family $\{\Phi_{0,\cdot,\sigma}^{\eps}u_0\}_{\eps\in(0,1]}$ of solutions of \eqref{e.080302} with time symbol $\sigma$ satisfies the Freidlin--Wentzell uniform LDP on $C([0,T];H)$ with rate function $I_{u_0,T}^{\sigma}$ if the following two conditions hold for the law $\nu_{u_0,\sigma}^{\eps}$ of the solution $\Phi_{0,\cdot,\sigma}^{\eps}u_0$:
    \begin{itemize}
        \item[(1)] For every $R>0$, $M\geq0$, and $\d,\d'>0$, there exists $\eps_0>0$ such that
        \begin{align*}
          \inf_{\|u_0\|\leq R}\inf_{\xi\in\{I_{u_0,T}^{\sigma}\leq M\}}
          \left(
          \nu_{u_0,\sigma}^{\eps}\bigl(\Nc_{\d'}(\xi)\bigr)
          -e^{-(I_{u_0,T}^{\sigma}(\xi)+\d)/\eps}
          \right)\geq0,
          \qquad \forall \eps\in(0,\eps_0],
        \end{align*}
        where $\Nc_{\d'}(\xi)$ is the $\d'$-neighborhood of $\xi$ in $C([0,T];H)$.

        \item[(2)] For every $R>0$, $M\geq0$, and $\d,\d'>0$, there exists $\eps_0>0$ such that
        \begin{align*}
          \sup_{\|u_0\|\leq R}
          \nu_{u_0,\sigma}^{\eps}
          \left(C([0,T];H)\setminus\Nc_{\d'}(I_{u_0,T}^{\sigma},M)\right)
          \leq e^{-(M-\d)/\eps},
          \qquad \forall \eps\in(0,\eps_0],
        \end{align*}
        where $\Nc_{\d'}(I_{u_0,T}^{\sigma},M)$ is the $\d'$-neighborhood of the level set $\{I_{u_0,T}^{\sigma}\leq M\}$.
    \end{itemize}

