[Lemma lem.detouring_path of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Every ${\scaleobj{1}{\square}} \in \mathcal{G}^{(N)}_k$ is $N$-$\mathsf{stable}$ for the statement: for every ${\scaleobj{1}{\square}}' \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}}) $ with $0 \leqslant h \leqslant k-1$, and every ${x \in \frac{16}{15}{\scaleobj{1}{\square}}' \cap {\scaleobj{1}{\square}}}$, the following properties hold.
		\begin{itemize}
			\item If $x \in \mathscr{C}^\#_*({\scaleobj{1}{\square}})$, then $x \in \mathscr{C}_{*}^\# \left(\frac{4}{3} {\scaleobj{1}{\square}}'\right) \subseteq \mathscr{C}_{*}^\# \left(\mathsf{r} {\scaleobj{1}{\square}}'\right)$.
			\item If $x \in \mathscr{C}_{\operatorname{bc}}^\#({\scaleobj{1}{\square}})$, then $x \in \mathscr{C}_{**}^\# \left(\frac{4}{3} {\scaleobj{1}{\square}}' \cap {\scaleobj{1}{\square}} \right) \subseteq \mathscr{C}_{**}^\# \left(\mathsf{r} {\scaleobj{1}{\square}}' \cap {\scaleobj{1}{\square}}\right)$. As a corollary, we also have 
			\begin{align}
				\bigcup_{{\scaleobj{1}{\square}}' \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}})} \mathscr{C}_{**}^\# \left(\frac{4}{3} {\scaleobj{1}{\square}}' \cap {\scaleobj{1}{\square}} \right) = \bigcup_{{\scaleobj{1}{\square}}' \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}})} \mathscr{C}_{**}^\# \left(\mathsf{r} {\scaleobj{1}{\square}}' \cap {\scaleobj{1}{\square}} \right) = \mathscr{C}_{\operatorname{bc}}^\# \left({\scaleobj{1}{\square}}\right).
			\end{align}
			\item If $x \notin \mathscr{C}_{\operatorname{bc}}^\#({\scaleobj{1}{\square}})$, then $\mathscr{O}^\#(x) \subseteq \frac{4}{3} {\scaleobj{1}{\square}}'$.
		\end{itemize}

