[Theorem 14 of arXiv:2604.07275, 'Some probabilistic properties and time-changed versions of a renewal process based on Mitt'] The pmf $\hat{p}_\alpha^f(n,t)=\Pr\{\hat{N}_\alpha^{f}(t)=n\},\ n \ge 0$ of $\{\hat{N}^f_\alpha(t)\}_{t \geq 0}$ is given by 
		\begin{align}
			\hat{p}_\alpha^f(n,t) &= \frac{\lambda^{2n}}{(2n)!}\sum_{k=0}^{\infty}\frac{(2n+k)!}{k!}  \frac{(-\lambda)^k}{\Gamma(\alpha(2n+k)+1)} \mathbb{E}\big(D_f^{\alpha(2n+k)}(t)\big) \nonumber \\ & \ \  + \frac{\lambda ^{2n+1}}{(2n+1)!}\sum_{k=0}^{\infty}\frac{(2n+k+1)!}{k!}  \frac{(-\lambda)^k}{\Gamma(\alpha(2n+k+1)+1)}  \mathbb{E}\big(D_f^{\alpha(2n+k+1)}(t)\big).
		\end{align}

[Prop 17 of arXiv:2607.11076, 'Smoluchowski-Kramers Approximation for Stochastic Differential Equations driven by Fractio'] Under the assumptions \textbf{(A1)}, \textbf{(A2)}, let \(\{h^{\varepsilon}\}_{\varepsilon>0}\subset\mathscr{A}_{N}\) for some \(N<\infty\). Then for any \(\delta>0\), we have
		\begin{eqnarray*}
			\lim\limits_{\varepsilon\to 0}\mathbb{P}\left\{d\left(\Gamma^{\varepsilon}\left({\varepsilon}^{H} B^H(t)
			+\int_0^{t}h^\varepsilon(s)ds\right),\Gamma^{0}\left(\int_0^{t}h^\varepsilon(s)ds\right)\right)>\delta\right\}
			&=& 0.
		\end{eqnarray*}

