[Theorem thm.main_next of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] Under Hypothesis~(hyp of the paper) and under the stationary measure $\mathbb{P}_{\rho}$, for every centered local function $f$, the additive functional has a scaling limit in $C(\mathbb{R}_+, \mathbb{R})$ for the following cases. 
		\begin{itemize}
			\item $d = 1$, $\deg(f) = 2$, then 
			\begin{align}
				\left(\frac{1}{\sqrt{N \log N}} \int_0^{Nt} f(\eta_s) \, {\mathrm{d}} s\right)_{t \geqslant 0} \Longrightarrow (B_t)_{t \geqslant 0}, 
			\end{align}
			has the scaling limit as a Brownian motion of covariance
			\begin{align}
				\mathbb{C}\mathrm{ov}[B_t, B_s] = \frac{\chi(\rho)^2}{4\pi\mathbf{D}(\rho)}\vert \overline{f}''(\rho)  \vert^2 (t \wedge s).
			\end{align}
			\item If $d_{\operatorname{eff}}(f) > 2$, i.e. $\deg(f)  > 2/d$, then 
			\begin{align}
				\left(\frac{1}{\sqrt{N}} \int_0^{Nt} f(\eta_s) \, {\mathrm{d}} s\right)_{t \geqslant 0} \Longrightarrow (B_t)_{t \geqslant 0}, 
			\end{align}
			has the scaling limit as a Brownian motion of covariance
			\begin{align}
				\mathbb{C}\mathrm{ov}[B_t, B_s] = 2 \left\Vert{f}\right\Vert^2_{-1} (t \wedge s).
			\end{align}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Let $\tau \in \{\<bs(2)0>, \<ps(2)0>\}$. Then for all $\kappa > 0$ and each compact set $\mfK$,
	\begin{align*}
		\mathbb{E}^{1/q} \Bigl [ \sup_{\|g\|_{L^2(\mathbb{R} \times \mathbb{T})} \le 1} \| \sup_{\psi \in \mathcal{B}^r} \langle D_g \tilde \Pi_z \tau  - \tilde \Pi_{z'} H_{\tau; \eps, \delta}^{z,g}(z'), \psi_{z'}^\mu \rangle \|_{L^2(\mfK; dz')}^q \Bigr ] \lesssim \mu^{- \kappa}
	\end{align*}
	uniformly over $0 < \delta < \eps < 1$ for every $q \in [2, \infty)$.

