[Defi def:skew_signature_functions of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] For any $n \geq 0, k \geq 1$ and $\lambda \in \Sig_{n+k}, \mu \in \Sig_{n}$, we let 
\begin{equation}
    P_{\lambda/\mu}(x_1,\ldots,x_k;t) = \sum_{T \in \GT_P(\lambda/\mu)} \psi(T) \mathbf{x}^{wt(T)}
\end{equation}
For any $\nu, \kappa \in \Sig_n$ we let 
\begin{equation}
    Q_{\kappa/\nu}(x_1,\ldots,x_k;t) = \sum_{T \in \GT_{Q,k}(\kappa/\nu)} \varphi(T) \mathbf{x}^{wt(T)}. 
\end{equation}

[Corollary 5 (Estimating entropic Brenier maps in self-transport problems) of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Suppose $\rho(x)\in\m C^\infty(\mb T^d)$ is a probability density function over $\mb T^d$ bounded away from zero. Let $\phi_\varepsilon^{\rm self}$ be the Schr\"odinger potential for the entropic optimal self-transport problem $\eot_\varepsilon(\rho, \rho)$. Then, for any given $K\in\mb N^\ast$ and $\alpha\in(0, 1)$, there exists functions $f_1, \cdots, f_{K-1}\in\m C^\infty(\mb T^d)$ and a constant $C> 0$ depending only on
\begin{align*}
\alpha,\,\,d,\,\,K,\,\,L_\rho,\,\,\mbox{and}\,\, \sup_{t\in[0, 1]}\big\{\|\rho_t^{(k)}\|_{\m C^{\max\{2+\lceil\frac{d+1}{2}\rceil, 12K\}+k',\alpha}}: , 2k+k'=12K+2,\,\,k,k'\in\mb N\big\}
\end{align*}
such that
\begin{align*}
\Big\|\nabla \phi_\varepsilon^{\rm self} - \sum_{k=1}^{K-1} \varepsilon^k \nabla f_k\Big\|_{L^2(\rho)} \leq C \varepsilon^K.
\end{align*}
\myqed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:codimension-four-cutoffs of arXiv:2608.30779, 'Some uniform estimates for K\"ahler--Ricci Shrinkers'] For every
\((X,d,\omega,J,f,p)\in\overline{\mathcal{KRS}(n)}\), there are smooth
functions \(\vartheta_\nu:\mathcal R\to[0,1]\) which vanish near
\(\mathcal S\), converge to \(1\) on compact subsets of \(\mathcal R\),
and satisfy
\begin{equation}
 \|\nabla\vartheta_\nu\|_{L^q(B(p,D)\cap\mathcal R)}
 \longrightarrow0
 \qquad\text{for every }D<\infty\text{ and }1\leq q<4.
\end{equation}

[Theo thm:random-SLE of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Fix $\alpha>0$. In the previous setup, for $t^{(\alpha)}_n= n^{-(\alpha+\frac{1}{3})}$, one has $\mathbf{P}$-almost surely
\begin{equation}
	\gamma^{(\delta_n)}_{\omega,t^{(\alpha)}_n} \underset{n\to \infty}{\overset{(d)}{\longrightarrow}}  \mathrm{SLE}_{16/3}(\Omega,a,b),
\end{equation}
where $\mathrm{SLE}_{16/3}(\Omega,a,b)$ is the standard chordal Schramm–Loewner-Evolution process in $\Omega$ that connects $a$ to $b$ in $\Omega $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2604.11385, 'Quantitative large population limit for non exchangeable diffusions in Fisher information'] We let $\displaystyle \delta_{N}=\max_{(i,j) \in v^{2}} \xi_{i,j}^{N}$ and
\[H_{t}^{v}=H \left( P_{t}^{v,N}|Q_{t}^{v,N} \right), \qquad \quad I_{t}^{v}=I\left(P_{t}^{v,N}|Q_{t}^{v,N} \right).\]
Fix a $T>0$ and suppose that there exists a constant $C$ such that
\begin{equation*}
\forall v \subset [N], \
    H_{0}^{v}+I_{0}^{v} \leq C \left(\delta_{N} |v|+1\right)\left( \sum_{(i,j)\in v^{2}} \left(\xi_{i,j}^{N} \right)^{2}+\delta_{N} \sum_{(i,j) \in v} \left(\xi^{T} \xi+\xi \xi^{T} \right)_{i,j}+\delta_{N}^{2} |v| \right).
\end{equation*}
Suppose moreover that $\left(P_{0}^{[N],N}, Q_{0}^{[N],N}\right)$ satisfies Hypothesis \ref{hyp-princ}.
We distinguish two set of assumptions:
\begin{itemize}
    \item Torus Case. Suppose that $b$ is smooth and assume that that  $\nabla^2 \log Q_{0}^{u,N}$ is bounded with constants that do not depend on $u$ or $N$.
    \item $\mathbb{R}^d$ case. Suppose that $b$ is smooth bounded, with bounded derivatives and assume that there exists $C>0$ such that 
    \begin{equation*}
   \forall u \in [0,1], \ \sup_{t\in [0,T]}\Vert \nabla^2 \log Q_{t}^{u,N}\Vert \leq C.
\end{equation*}

\end{itemize}
Then, there exists a constant $M_{T}$ (that does not depend on v,N) such that 
\begin{equation*}
\forall v \subset [N], \
    H_{T}^{v}+I_{T}^{v} \leq M_{T} \left(\delta_{N} |v|+1\right)\left( \sum_{(i,j)\in v^{2}} \left(\xi_{i,j}^{N} \right)^{2}+\delta_{N} \sum_{(i,j) \in v} \left(\xi^{T} \xi+\xi \xi^{T} \right)_{i,j}+\delta_{N}^{2} |v| \right).
\end{equation*}
In particular, if $\xi_{i,j}^{N}=G_{N} \left( \frac{i}{N}, \frac{j}{N} \right)$ with $G_{N}$ a graphon with values in $[0,1]$, we have 
\begin{equation*}
\forall v \subset [N], \
    H_{T}^{v}+I_{T}^{v} \leq M_{T} \frac{\left|v \right|^{2}}{N^{2}}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 6 ({Gronwall type lemma}) of arXiv:2604.20323, '2604.20323'] Let $f:[0,T]\to\R_+$ be bounded and such that for $h=T/N$ with $N\in\N$,
  \begin{equation}
   \forall t\in[0,T],\;f(t)\le \kappa +\lambda t^{a_1}
   \int_h^{h\vee t} f(\tau^h_s)s^{-a_1}(t-s)^{-a_2}ds,
 \end{equation}
 where $\kappa,\lambda\in [0,+\infty)$ and $a_1,a_2\in {[0,1)}$. Then $\sup_{t\in[0,T]}f(t)\le C\kappa$ for some constant $C(\lambda,a_1,a_2,T)$ not depending on $h$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 199 of arXiv:2601.16377, '2601.16377'] The master problem asks to find an $H$-tuple of functions $\boldsymbol{F}(z)=(F_h(z))_{h=1}^H$ with the following properties for any $h \in [H]$.
\begin{enumerate}
\item $F_h(z)$ is a holomorphic function of $z \in \amsmathbb C\setminus \amsmathbb{A}_h^{\mathfrak{m}}$.
\item There exists a holomorphic function $A_h(z)$ of $z \in \amsmathbb{M}_h$ such that
\begin{equation}

 A_h(z) = \sqrt{(z-\alpha_h) (z-\beta_h)} \,\big\langle \bth_h \cdot \boldsymbol{F}(z)\big\rangle + E_h(z).
 \end{equation}
 \item $F_h(z) = \frac{\kappa_h}{z}+O\big(\frac{1}{z^2}\big)$ as $z \rightarrow \infty$. This can be equivalently restated as
\[
F_h(z)\,\, \mathop{=}_{z \rightarrow \infty} \,\, O\bigg(\frac{1}{z}\bigg) \qquad \textnormal{and} \qquad \oint_{\gamma_h} \frac{\dd z}{2\ii\pi}\,F_h(z) = \kappa_h.
\]
\end{enumerate}

[Lemma 12 ({\cite[Lemma 2.3) of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] {ZB+JH-20}}]
		Assume that  $f \in L^2(\bO)$. Let $\Nn : L^2(\bO)\to L^2(\bO)$ be the map as defined in \eqref{eqn-map-B}. Then, for $v \in L^2(\bO)$, the Fr\'echet derivative $d_v\Nn$ exists and satisfies
		\begin{align}
			d_v\Nn(h)=- (f,v)h- (f,h)v ,\ \text{ for all }\ h\in L^2(\bO).
		\end{align}

