[Cor dominheight of arXiv:2609.01499, 'On the rigidity of sloped height functions in $d\ge 3$ \\ and non-crossing surfaces'] All the measures in the extremal decomposition of $\mu_{\mathfrak{s}}$ have the following dominant height profiles. For each $a\in \mathfrak{c}+ \frac{i}{n}$ there is some rational number of the form  $\frac{k}{n}$ such that 
\begin{equation}
   h_{\mu_{\mathfrak{s},a}}(x_{3},\ldots,x_{d}) = 
   \left\lfloor \frac{k}{n} + \sum_{j=3}^{d}\mathfrak{s}_j x_j \right\rfloor. 
\end{equation}

[Lemma 3 of arXiv:2506.18558, '2506.18558'] Suppose that Assumption {\rm\ref{A2}} holds. Then the following statements hold.
\begin{itemize}
\item[{\rm (1)}] For any $p\ge 4$, there exist constants $C_{1,p}$ and $C_{2,p}>0$ such that for all $t\ge s$, $x\in \RR^n$ and $y\in \RR^m$,
\begin{equation}
\EE|Y_{t}^{s,x,y} |^{p} \le e^{-C_{1,p}(t-s)}|y|^p+C_{2,p}(1+|x|^p);
\end{equation}
\item[{\rm (2)}] There exist constants $\beta$ and $C>0$ such that for any $t \ge s$, $x_1,x_2\in\RR^{n}$ and $y_1,y_2\in\RR^{m}$,
\begin{align}
\mathbb{W}_1 (\delta_{y_1}P^{x_1}_{s,t}, \delta_{y_2}P^{x_2}_{s,t} )\le Ce^{-\beta(t-s) }|y_1-y_2|+C|x_1-x_2|.
\end{align}
\end{itemize}

