[Lemma 6 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let $(\wtilde{\Omega},\wtilde{\Fn},\wtilde{\Fb},\wtilde{\Pr},\wtilde{W},u)$ be a solution, obtained in Proposition \ref{Prop-pre-martingale}, of \eqref{eqn-main-prob-Ito} on $[0, T]$ such that $u(t) \in\bM$, for $t\in [0, T]$, and
		\begin{equation}
			\wtilde{\E} \Big[\sup_{t\in[0,T]} \big(\|u(t)\|_{H_0^1(\bO)}^{4} + \|u(t)\|_{L^p(\bO)}^{2p}\big)\Big] + \wtilde{\E}\Big[\int_0^T\big(\|\Delta u(t)\|_{L^2(\bO)}^2+ \|u(t)\|_{L^{2p-2}(\bO)}^{2p-2}\big)dt\Big]<\infty.
		\end{equation}
		Then, for $\wtilde{\Pr}$ almost all $\omega\in\wtilde{\Omega}$, 
		\begin{equation}
			u(\cdot, \omega) \in C([0,T]; \Vp\cap \bM).
		\end{equation}
		Moreover, for every $t\in[0, T]$, \eqref{eqn-strong-form-1} is satisfied $\wtilde{\Pr} - $a.s. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma prop:CNfailB2new of arXiv:2510.12365, 'Planted clique recovery in \\ random geometric graphs'] In $G_k(n,r)$, if $\mu\ll n$ and $k \ll n/\mu$, then     
\begin{equation}
        \Prob{\mathcal{B}_2} \leq
        \begin{cases}
        \displaystyle \frac{\mu n}{2} \cdot \frac{(c_{2,d} \mu)^{k-2} e^{- c_{2,d} \mu}}{(k-2)!}+o(1) &\text{if $k-2 \leq c_{2,d} \mu$}, \\
        \displaystyle \frac{\mu n}{2} \cdot \frac{((k-2)/e)^{k-2}}{(k-2)!}+o(1) &\text{if $c_{2,d} \mu < k-2 < \mu$}, \\
        \displaystyle \frac{\mu n}{2} \cdot \frac{\mu^{k-2} e^{- \mu}}{(k-2)!}+o(1) &\text{if $k-2 \geq \mu$},
        \end{cases}
    \end{equation}
    for some $c_{2,d}>0$.

