body:
[Proposition 7 of arXiv:2604.04840, 'Bounding the Gap Between Zeros of the Variable-\\Parameter Confluent Hypergeometric Functi'] Let $a_{k+1}^* < a_k^*$ be two consecutive zeros of $\Phi(a,b,z_l)$ for the given values $(b, z_l) \in \mathbb{R}^+$. Suppose that $a_k^*$ lies in the interval $[-N,-N+1]$ for some positive integer $N$ so that there is a sequence of $N$ values $0<z_1<z_2 < \cdots < z_N$, of which $z_l$ is a member, that satisfy the equation $\Phi(a_k^*,b,z_n) = 0$, $n=1,\dots,N$. Now let $a^*(z)$ be the solution to the initial value problem (IVP)

	\begin{equation}

		\frac{\partial a^*}{\partial z} = \left( \frac{a^*}{b} \right)^2 z^b e^{-z} \frac{\Phi^2(a^*+1,b+1,z)}{\int_0^z t^{b-1} e^{-t} \Phi^2(a^*,b,t)dt}, \quad a^*(z_l) = a^*_{k+1}
	\end{equation}\\
	\noindent Then when $z_l \neq z_N$, $a^*(z_{l+1}) = a_k^*$. If $z_l = z_N$, $a^*(z) \rightarrow -N$ as $z \rightarrow \infty$.

