[Lemma normbound:hadamard of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Let $\lambda_1, \ldots, \lambda_d$ be a sequence of positive numbers.
	Set $\boldsymbol{\lambda} := (\lambda_1, \ldots, \lambda_d)$ and $\lambda_{\max} := \max_{i \in [d]} \lambda_i$.
	Let $q \in [-\infty, \infty]$ and $\widetilde{\mathbf{H}}_{\boldsymbol{\lambda}}^{(q)} \in \R^{d \times d}$ 
	be the matrix defined by
	\begin{equation*}
		(\widetilde{\mathbf{H}}_{\boldsymbol{\lambda}}^{(q)})_{ij} 
		:= 
		\mathcal{M}_q (\lambda_i, \lambda_j)
		\quad
		\text{ for }
		i,j \in [d],
	\end{equation*}
	where $\mathcal{M}_q$ is the power mean as in Definition (def:powermean of the paper). Recall $c_q$ from (eq:c_q:def of the paper), i.e., for $q \in [-\infty, \infty]$,
	\begin{equation*}
	c_q =
	\begin{cases}
	1, & \text{ if } q \in [-\infty,1], \\
	2^{2-1/q}-1, & \text{ if } q \in (1,\infty), \\
	3, & \text{ if } q = \infty.
	\end{cases}
	\end{equation*}
	Then for any unitarily invariant norm ${\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert \cdot 
    \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}$ on $\R^{d \times d}$ and any matrix $\mathbf{B} \in \R^{d \times d}$, it holds that
	\begin{equation*}
	\vertiii{ \widetilde{\mathbf{H}}_{\boldsymbol{\lambda}}^{(q)} \circ \mathbf{B} }
	\le c_q \lambda_{\max}\, \vertiii{ \mathbf{B} }
	\leq
	\begin{cases}
	\lambda_{\max}\, \vertiii{ \mathbf{B} }, & \text{ if } q \in [-\infty,1], \\
	3 \lambda_{\max}\, \vertiii{ \mathbf{B} }, & \text{ if } q \in (1, \infty].
	\end{cases}
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 60 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] \quad\par
  \begin{itemize}
    \item [$\rm{(i)}$]Suppose that $(F,R,\mu)$ satisfies assumption $\rm{(A2)}$.
  Then
for any $f\in\BL^{\kappa},\;\delta\in (0,1],\;\varepsilon\in (0,1]$, and $\eta\in (0,\varepsilon)$, we have 
\begin{align*}
  \sup_{\substack{t\geq 0\\x\in F}}|P_{t+\delta}f(x)-P_tf(x)|\lesssim
  \g{c}{12q2}\left\{\|f\|_{\Lip^{\kappa}}\varepsilon^{\kappa}
    +\|f\|_{F}\left[\frac{\eta^{\theta}}{\varepsilon^{\theta} }+\frac{\delta}{\eta^{s_0 \theta}(\varepsilon^{\theta}-\eta^{\theta})}\right]\right\} ,
\end{align*}
where
\begin{align*}
  \g{c}{12q2}=1+\frac{1}{c_l \left[ \frac{c_{\rm{LR}}(1\wedge \frac{1}{2}\diam F)^{\theta}}{1+(1\vee \frac{1}{\diam F})c_{\rm{LR}}(1\wedge \frac{1}{2}\diam F)^{\theta}} \right]^{1+s_0}}.
