[Defn def-harmonic of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] We say that $h : \mathcal V\mathcal G \to \mathbbm R$ is \textbf{discrete harmonic at $x$} if\footnote{If $\mathcal G$ is not locally finite, the relation~(equation eqn-harmonic of the paper) implicitly requires that the sum is convergent, i.e., $\sum_{y\sim x} \mathfrak c(x,y) |h(y) - h(x)|< \infty$.}
\begin{equation}   
\sum_{y\sim x} \mathfrak c(x,y) (h(y) - h(x)) = 0   .
\end{equation}  
For $f : \mathcal V\mathcal G\to\mathbbm R$, we define its \textbf{Dirichlet energy} by
\begin{equation} 
\operatorname{Energy}(f) :=  \sum_{(x,y) \in \mathcal E \mathcal G} \mathfrak c(x,y)  |f(y) - f(x)|^2  .
\end{equation}

[Lemma 14 (KL telescoping bound) of arXiv:2605.24937, '2605.24937'] Let $(Y_n')_{n=0}^N$ and $(\widetilde Y_n)_{n=0}^{N-1}$ be defined
by~\eqref{eq:tildeY-def}--\eqref{eq:aux-update}. Then
\begin{equation}
  \KL\!\bigl(\widehat\mu_N\,\|\,\nu_N\bigr)
  \;\le\;
  \sum_{n=0}^{N-1}
  \E\!\left[
    \KL\!\bigl(Q_n(\widetilde Y_n,\cdot)\,\big\|\,P(Y_n',\cdot)\bigr)
  \right].
\end{equation}
If~\eqref{eq:reg-framework}--\eqref{eq:crossreg-framework} hold, then
\begin{equation}
  \KL\!\bigl(\widehat\mu_N\,\|\,\nu_N\bigr)
  \;\le\;
  c\,\sum_{n=0}^{N-2}\eta_n^{2}\,\E\|\widehat X_n-Y_n'\|^{2}
  +c'\,\E\|\widehat X_{N-1}-Y_{N-1}'\|^{2}
  +\bar b^{\,2},
\end{equation}
where $\bar b^{\,2}:=\|b\|_{L^2(\widehat\mu_{N-1})}^{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2607.11608, '2607.11608'] Let  $n\in \N$ and $M>0.$ Let $h_n$ as in \eqref{EIGEN} and $f_M$ as in \eqref{fM}. Then, for any $M\gg 1$ the following hold:
\begin{itemize}
\item[(i)] If $d=1$ then
\begin{align}

|\langle f_M, h_n\rangle_{L^{2}(\R)}|\les \jb{n}^{-\frac{3}{2}} M^{\frac{5}{2}};
\end{align}
\item[(ii)] If $d\ge 2$ then
\begin{align}
|\langle f_M, h_n\rangle_{L^{2}(\R^d)}|\les \jb{n}^{-\frac{d+3}{4}} M^{\frac{3d}{2}}.
\end{align}
\end{itemize}

