body:
[Corollary coro:logsogen of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] For $a\in\mathcal{H}^{\beta,\theta}_K(\mathbb{R}^d,\mathbb{R})$ with $\beta\geq 0$, $\theta>1$ and $K>0$, define the probability measure $\mu$ having a density $d\mu(x) = \exp(-\|x\|^2/2+a(x)+c_a)dx$ with respect to the $d$-dimensional Lebesgue measure (with $c_a\in \mathbb{R}$ a normalizing constant). Then, for all $k\in \{1,...,\lfloor \beta \rfloor +1\}$, and $f:\mathbb{R}^d\rightarrow \mathbb{R}$ with $\|f\|_{L_{\mu}^2}=1$ we have
\begin{align*}
    \int |f(x)|^2|\log(|f(x)|)|^{k}d\mu\leq C \sum_{|\alpha|=0}^k\|D^\alpha f\|^2_{L_{\mu}^2}.
\end{align*}
\begin{proof}
    From Theorem (theo:wsobo of the paper) with $\phi(x)=\frac{\|x\|^2}{2}$, we have for all $g:\mathbb{R}^d\rightarrow \mathbb{R}$ with $\|g\|_{L_2(\gamma_d)}=1$
    \begin{align*}
    \int |g(x)|^2|\log(|g(x)|)|^{k}d\gamma_d(x)\leq C \sum_{|\alpha|=0}^k\|D^\alpha g\|^2_{L^2_{\gamma_d}}.
\end{align*}
Then, from Theorem (theo:thetheo of the paper), there exists a map $T\in C^{\lfloor \beta \rfloor+1}(\mathbb{R}^d,\mathbb{R}^d)$ with $\nabla T\in  \mathcal{H}^{\beta}_C \color{black} (\mathbb{R}^d,\mathbb{R}^d)$ such that
\begin{align*}
    \int |f(x)|^2|\log(|f(x)|)|^{k}d\mu(x)= &  \int |f\circ T(x)|^2|\log(|f\circ T(x)|)|^{k}d\gamma_d(x)\\
    \leq &C \sum_{|\alpha|=0}^k\|D^\alpha (f\circ T)\|^2_{L^2_{\gamma_d}}
    \\
    = &C \sum_{|\alpha|=0}^k\|D^\alpha f\|^2_{L_{\mu}^2}.
\end{align*}
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:finite-gram-bessel of arXiv:2609.00399, 'Shannon's problem on the monotonicity of entropy and a Conjecture of Tao'] Let $M\in\mathbb Z_{\geq1}$, let $e_1,\ldots,e_M$ lie in a complex
Hilbert space whose inner product is linear in the first argument, and put
$G_{jk}:=\langle e_j,e_k\rangle$.  If, for some $S\geq0$,
\begin{equation}
 \max_{1\leq j\leq M}\sum_{k=1}^{M}|G_{jk}|\leq S,
\end{equation}
then every $F$ in the Hilbert space satisfies
\begin{equation}
 \sum_{j=1}^{M}|\langle F,e_j\rangle|^2\leq S\,\|F\|^2.
\end{equation}

