[Proposition 24 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] For every compact connected $G$ there exist integers $A,M,N\ge0$ and constants $c,C>0$ such that, for $0<t\le1$ and $Y\in\gLie$,
		\begin{align}
			&j_G^{\nc}(Y)^{1/2}e^{-|Y|^2/(4t)}q_t^{\C}(e^{iY})
			=\vol(G)\frac{e^{t|\rho_G|^2}}{(4\pi t)^{\dim G/2}}
			+R_t(Y),

		\end{align}
		where
		\begin{equation}
			|R_t(Y)|\le Ct^{-N}e^{-c/t}(1+|Y|)^M.
		\end{equation}
		More precisely, each nonzero Weyl orbit $\mathcal O$ in the semisimple lattice satisfies
		\begin{equation}
			\left|
			\frac{\sum_{\gamma\in\mathcal O}\varepsilon_G(\gamma)
				\Pi_G(Y-i\gamma)e^{-i\langle\gamma,Y\rangle/(2t)}}
			{\Pi_G(Y)}
			\right|
			\le Ct^{-N}(1+|Y|+\ell_{\mathcal O})^A.
		\end{equation}

[Theorem of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] Assume that condition (equation third-grade-paremeters-res of the paper) holds. Then:
	\begin{enumerate}
		\item[(i)] on bounded domains, system (equation equationV1 of the paper) possesses pullback random attractors whenever the forcing satisfies  $\boldsymbol{\mathfrak{K}}\in\mathrm{L}^2_{\mathrm{loc}}(\mathbb{R};\mathbb{H}^{-1}(\mathbb{Q}))$ and there exists a number $\delta\in[0,\frac{\sigma^2}{2})$ such that for every $c>0$,
		\begin{align*}
			\lim_{s\to-\infty}e^{cs}\int_{-\infty}^{0} e^{\delta\zeta}\|\boldsymbol{\mathfrak{K}}(\cdot,\zeta+s)\|^2_{\mathbb{H}^{-1}}\/\mathrm{d}\/ \zeta=0.
		\end{align*}

		\item[(ii)] on unbounded domains, system (equation equationV1 of the paper) possesses a unique random attractor provided the forcing satisfies $\boldsymbol{\mathfrak{K}}\in\mathrm{L}^2_{\mathrm{loc}}(\mathbb{R};\mathbb{L}^{2}(\mathbb{Q}))$ and there exists a number $\delta\in[0,\frac{\sigma^2}{2})$ such that for every $c>0$,
		\begin{align*}
			\lim_{s\to-\infty}e^{cs}\int_{-\infty}^{0} e^{\delta\zeta}\|\boldsymbol{\mathfrak{K}}(\cdot,\zeta+s)\|^2_{2}\/\mathrm{d}\/ \zeta=0.
		\end{align*}

		\item[(iii)] on both bounded and unbounded domains, system (equation equationV1 of the paper) admits an invariant measure, corresponding to $\boldsymbol{\mathfrak{K}}\in\mathbb{H}^{-1}(\mathbb{Q})$ and $\boldsymbol{\mathfrak{K}}\in\mathbb{L}^{2}(\mathbb{Q})$, respectively.
		\item[(iv)] on both bounded and unbounded domains, system (equation equationV1 of the paper) admits at most one invariant measure for $\boldsymbol{\mathfrak{K}}=\boldsymbol{0}$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 of arXiv:2607.17943, 'Coadjoint averaging and cross-scale fluxes in a fast-slow stochastic Euler-Arnold system o'] For any $\Omega\in \su(N)$ and $\Theta, \Theta_1, \Theta_2\in \su(N)$ we have
\begin{equation}
[D c_k(\Omega)](\Theta)=(k+1)\operatorname{tr}(\Omega^k \Theta) \ , \ k = 1,...,N-1 \ ,
\end{equation}
and
\begin{equation}
[D^2 c_k(\Omega)](\Theta_1, \Theta_2)=(k+1)\sum\limits_{r=0}^{k-1} \operatorname{tr}(\Omega^r \Theta_2 \Omega^{k-1-r} \Theta_1) \ , \ k = 1,...,N-1 \ .
\end{equation}

