[Pr blprev of arXiv:2607.12795, 'Semi-open boundary for random walking shocks'] The (not necessarily probability) measure
 \begin{equation}
  \pi(d_0^1,\,\dots,\,d_0^M):\,=\Bigl(\bigotimes_{\ell=1}^Me^{\bigl(\beta(\ell^2-2\ell+1-M^2)+2\theta_0\cdot(M-\ell+1)\bigr)d^\ell_0}\Bigr)\cdot\Bigl(\bigotimes_{i=1}^K\prod_{n=1}^{m_i}\frac1{\text{\rm e}^{\beta n}-1}\Bigr),
 \end{equation}
 where the \(m_i\) are calculated from the \(d_0^\ell\) as in (equation eq:midef of the paper) and empty products are defined to be 1, is reversible stationary for the \(D_0^\ell(t)\)'s. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2605.30091, 'Computing lower expectations with respect to total variation distance and chi-squared dive'] With $r\in\{\ell,\ldots,n\}$ defined as above, we have that
\begin{equation}
    \underline{E}^{\chi^2}_{p,\delta}(f)
    =
    \begin{cases}
    \mu_r-\sigma_r\sqrt{m_r\delta-(1-m_r)} & \text{if } r>\ell,\\
    f(x_1) & \text{if } r=\ell.
    \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn of arXiv:2412.04527, 'Critical Drift for Brownian Bees and a Reflected Brownian Motion Invariance Principle'] Fix $T>0$ and let $\Lambda_T$ be the set of continuous and strictly increasing bijections $[0,T]\to[0,T]$. Then for $X,Y\in \mathcal{D}([0,T],\mathbb{R})$
\begin{align*}
    d_T(X,Y)&:=\inf_{\lambda \in \Lambda_T}\left\{\sup_{t\in [0,T]}|t-\lambda(t)|\vee \sup_{t\in [0,T]}|X(t)-Y(\lambda(T))|\right\} 
\end{align*}
and for $X,Y\in \mathcal{D}([0,\infty),\mathbb{R})$
\begin{align*}
    d_\infty(X,Y)&:=\sum_{T\in\mathbb{N}}^\infty 2^{-T}(1\wedge d_T(\psi_T(X),\psi_T(Y))).
\end{align*}

[Lemma 13 of arXiv:2604.10244, 'Ergodicity for regime-switching neutral stochastic functional differential equations with '] Let assumption (\hyperlink{A0}{A0}), (\hyperlink{H1}{H1}), and (\hyperlink{H2}{H2}) hold. Suppose that there exist a function \( V \in C^{2}\left(\mathbb{R}^{n} \times \mathbb{S} ; \mathbb{R}_{+}\right) \) and positive constants $ p$, $ c_{1} $, $ c_{2} $, $\lambda_0$, $\lambda_{1} $, $ \lambda_{2} $  such that \( \lambda_{1}>\frac{\lambda_{2}}{(1-\kappa_1)^{p}}\),
		\begin{equation}
			c_{1}|x|^{p} \leq V(x, k) \leq c_{2}|x|^{p}
		\end{equation}
		for \( (x, k) \in \mathbb{R}^{n} \times \mathbb{S} \) and
		\begin{equation}
			(\mathcal{L} V)(\varphi, k) \leq \lambda_0-\lambda_{1}|\varphi(0)-G(\varphi,k)|^{p}+\lambda_{2} \int_{-\infty}^{0} |\varphi(\theta)|^{p} \rho(\d \theta)
		\end{equation}
		for \( (\varphi,  k) \in C_r \times \mathbb{S} \). Then there exists a constant $C>0$  such that for any   $(\xi,i)\in C_r\times\S$ and  $t\geq 0 $,
		\begin{equation}
			\mbb{E}\left|Y^{\xi, i}(t)\right|^{p}\leq  C(1+\|\xi\|_{r}^{p}).
		\end{equation}

