[Theorem Thm-convergence of arXiv:2507.19222, 'Convergence of the KMP model to the KPZ equation'] The sequence  $(\mathfrak{F}_{N})_{N\in\mathbb{Z}_{\geqslant 0}}$ is tight with respect to the topology $D\left([0,T],\mathcal{S}^{'}(\mathbb{R})\right)$. Furthermore, any limit point lies in $C\left((0,T],C(\mathbb{R})\right)$ and coincides with the law of the It\=o solution to the multiplicative noise stochastic heat equation given by  
\begin{equation}
	\begin{cases}
		\partial_{t}\mathcal{U}(t,x)=\frac{1}{2}\partial_{xx}\mathcal{U}(t,x)+\frac{1}{2\sqrt{\alpha}}\mathcal{U}(t,x)\Xi(t,x)\\
		\mathcal{U}(0,x)=\delta_{0}(x)
	\end{cases}\,.
\end{equation}
Here, $\alpha>0$ is the parameter of the $\text{Beta}(\alpha,\alpha)$ distribution of the random environment and $\Xi(t,x)$ is the standard Gaussian space-time white noise.

[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ X(\cdot) $ be an $ \mathcal{X} $-valued stochastic process.
    \begin{enumerate}[(i)]
        \item  We say that $ X(\cdot) $ is measurable if the map $ (t , \omega) \mapsto X(t, \omega) $ is strongly $ (\mathcal{B}([0,T] )\times  \mathcal{F}) / \mathcal{B}(\mathcal{X}) $-measurable; 
        \item We say that $ X(\cdot) $ is $ \mathbf{F} $-adapted if it its measurable and for each $ t \in [0,T] $, the map $ \omega \mapsto X(t, \omega) $ is strongly $ \mathcal{F}_{t}/ \mathcal{B}(\mathcal{X}) $-measurable;
        \item We say that $ X(\cdot) $ is $ \mathbf{F} $-progressively measurable if for each $ t \in [0,T] $, the map $ (s, \omega) \mapsto X(s, \omega) $ from $ [0, t] \times \Omega $ is strongly $ ( \mathcal{B}([0,t]) \times \mathcal{F}_{t})/ \mathcal{B}(\mathcal{X}) $ -measurable.
    \end{enumerate}

