[Lemma E[sl]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e^{\textnormal{tail}} = \delta_e^{\textnormal{head}} = \delta \in O(1)$ and
\begin{enumerate}
    \item $\mathds{E}[(d_U^{\textnormal{in}}d_U^{\textnormal{out}})^{\delta}] \in o(n)$
    \item $\exists c>0: \mathds{P}(d_U^{\textnormal{out}},d_U^{\textnormal{in}} \geq \delta) \geq c$
\end{enumerate}
then
\begin{align*}
    \mathds{E}[S_n] = (\delta-1)! n \mathds{E}[d_U^{\textnormal{in}}] \Bigg( \frac{\mathds{E}[d_U^{\textnormal{in}}d_U^{\textnormal{out}}]}{n\mathds{E}[d_U^{\textnormal{in}}]^2} \Bigg)^{\delta} (1+o(1)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2607.26564, 'Stochastic Scalar Conservation Laws on Moving Hypersurfaces'] Let Assumptions \ref{Assumption1} and \ref{Assumption2} hold. Then for every $u_0 \in H^{1,1}(\Gamma_0) \cap L^{\infty}(\Gamma_0)$, there exists a martingale entropy solution $({\Omega}^*,{\mathcal{F}}^*,\{{\mathcal{F}}_t^*\}_{t \in [0,T]},\mathbb{P}^*,u^*,B^*)$ to the stochastic conservation law \eqref{eq74} started from $u_0$. Moreover, $\mathbb{P}^*$-a.s.
\begin{equation}
\|u^*\|_{L^{\infty}(Q_T)} \leq e^{C^*}(1+ \| u_0 \|_{L^\infty(\Gamma_0)}),
\end{equation}
where
\begin{eqnarray*}
C^*&=& (T+1)(L_1+1)(1+\sup_{t\in[0,T]}\|\nabla_{\Gamma_t} \cdot v(t)\|_{L^{\infty}(\Gamma_t)} +\sup_{t\in[0,T]}\|w^*(t)\|_{L^{\infty}(\Gamma_t)}  \nonumber\\
      & & + \sup_{t\in[0,T]}\|\nabla_{\Gamma_t}w^*(t)\|_{L^{\infty}(\Gamma_t)} + \sup_{t\in[0,T]}\|\Delta_{\Gamma_t}w^*(t)\|_{L^{\infty}(\Gamma_t)}  ),
\end{eqnarray*}
and $w^{*}(t,x) = \int_0^t \sigma(s, G(s, G^{-1}(t,x))) dB^{*}_s, \ (t,x) \in Q_T$.

[Lemma lem:SkotoFM of arXiv:2606.11677, 'Feynman--Kac formula for the heat equation with a one-center point interaction in $d=3$.'] Let  $f_n$ ($n\geq 1$) and $f$ be functions in  $\mathcal{D}$. Suppose that $f_n$ converges to $f$ in $(\mathcal{D},d_{\mathrm{S}})$ and that \begin{align}
\text{for any $L>0$, there exists an $R>0$ such that $f(R)\geq L$}.
\end{align} 

Then $R_{f_n}:=\overline{f_n([0,\infty))}$ converges to  $R_f:=\overline{f_n([0,\infty))}$ in $(\mathcal{C},d_{\mathrm{FM}})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition g1pn of arXiv:2411.16647, 'The stochastic evolution of an infinite population with logistic-type interaction'] Let $(A,\mathcal{D})$ and $(B,\mathcal{D})$ be linear operators on $\mathcal{X}$ which have the following properties
 \begin{itemize}
  \item [(i)] $-A: {\mathcal{D}}^{+} \to {\mathcal{X}}^{+}$ and $B: {\mathcal{D}}^{+} \to {\mathcal{X}}^{+}$; 
  \item [(ii)] $(A,\mathcal{D})$ is the generator of a substochastic semigroup, $S_0=\{S_0(t)\}_{t\geq 0}$, on $\mathcal{X}$ such that $S_0(t) : \widetilde{\mathcal{X}} \to \widetilde{\mathcal{X}}$, holding for all $t\geq 0$, and the restrictions  $S_0(t)|_{\widetilde{\mathcal{X}}}$, $t\geq 0$, constitute a $C_0$-semigroup on $\widetilde{\mathcal{X}}$ generated by $(A,\widetilde{\mathcal{D}})$;
  \item [(iii)] $B: \widetilde{\mathcal{D}} \to \widetilde{\mathcal{X}}$ and 
 \begin{equation*}

  \varphi_{{\mathcal{X}}} ((A+B)x) = 0, \qquad {\rm  for} \ \ {\rm all} 
 \  \ x \in \mathcal{D}^{+};
 \end{equation*}
 \item[(iv)] there exist positive $c$ and $\epsilon$ such that
 \begin{equation*}

  \varphi_{\widetilde{\mathcal{X}}} ((A+B)x) \leq c \varphi_{\widetilde{\mathcal{X}}} (x) - \epsilon \|Ax\|_{\mathcal{X}}, \qquad {\rm  for} \ \ {\rm all} 
 \  \ x \in \widetilde{\mathcal{D}} \cap \mathcal{X}^{+}.
 \end{equation*}
 \end{itemize}
Then the closure of $(A+B,\mathcal{D})$ in $\mathcal{X}$ is the generator of a stochastic semigroup, $S=\{S(t)\}_{t\geq 0}$, on $\mathcal{X}$ which leaves $\widetilde{\mathcal{X}}$ invariant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 19 (Theorem 3.1 of \cite{T2}) of arXiv:2606.17472, '2606.17472'] For all $a\in \R$ and $t\ge 0$, it holds that
\begin{align}

  h(X_t-a)=h(x-a)+M_t^a+L_t^a,
\end{align}
where
\begin{align*}
  M_t^a:=\int_0^t \int_{\R\setminus \{0\}}\Big(h(X_{s-}-a+y)-h(X_{s-}-a)\Big)\tilde{N}(ds,dy)
\end{align*}
is an $L^2$-martingale. Here, $\tilde{N}$ denotes the compensated Poisson random measure. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 102 of arXiv:2601.16377, '2601.16377'] Consider a variational datum satisfying Assumptions~\ref{Assumption_A}, \ref{Assumption_B} and \ref{Assumption_C} and having a single band per segment. For each $h \in [H]$, take a function $\Delta V_h$ which is holomorphic in a complex neighborhood of $[\hat{a}'_h,\hat{b}_h']$. Then consider the family of variational data parameterized by a real $\epsilon$ in a small neighborhood of $0$, differing from the original variational datum only by the potentials $V_h^\epsilon = V_h + \epsilon \Delta V_h$ for any $h \in [H]$. Then, denoting with an exponent ${}^{\epsilon}$ all the associated quantities, we have the second-order Taylor expansion
\begin{equation}

\I^{\epsilon}[\mu^\epsilon]\mathop{=}_{\epsilon \rightarrow 0} \I^0[\mu^0]+ \I'[\mu^0] \epsilon + \I''[\mu^0] \epsilon^2 +o(\epsilon^2),
 \end{equation}
The error $o(\epsilon^2)$ is uniform as long as $|\Delta V_h(z)|$ is uniformly bounded for any $h \in [H]$ and the constants in Assumptions~\ref{Assumption_A}, \ref{Assumption_B}, and \ref{Assumption_C} remain the same. The factors $\I'[\mu^0]$ and $\I''[\mu^0]$ do not depend on $\epsilon$ and are uniformly bounded under the same assumptions.

Furthermore, if we vary the original variational datum as in Proposition~\ref{Proposition_differentiability_filling_fraction} and Theorem~\ref{Theorem_differentiability_full}, then the factors $\I'[\mu^0]$ and $\I''[\mu^0]$ depend smoothly on the variation parameters and the remainder $o(\epsilon^2)$ remains uniform. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:standard subadditive of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},P,T)$ be a measure preserving system. Suppose that $\{f_n\}_{n\in\mathbb{N}}$ is a sequence of $\mathcal{F}$-measurable functions satisfying the following conditions:
	\begin{longlist}
		\item $\int |f_1|dP<\infty$;
		\medskip
		\item for each $k,n\in\mathbb{N}$, $f_{n+k}\le f_n+f_k\circ T^n$, $P$-a.s.
	\end{longlist} 
	Then there exists a $T$-invariant function $\phi:\Omega\to\mathbb{R}$ such that 
	\[\lim_{n\to\infty}\frac{1}{n}f_n=\phi\text{,   }P\text{-a.s. }\]
	Moreover, the function $\phi$ is given by
	\[\phi(\omega)=\inf_{n\in\mathbb{N}}\frac{1}{n}\mathbb{E}_P(f_n\mid \mathcal{I})(\omega)=\lim_{n\to\infty}\frac{1}{n}\mathbb{E}_P(f_n\mid \mathcal{I})(\omega)\text{ for each }\omega\in\Omega.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2607.29020, 'Entropic Symmetrization Resistance'] \label[lemma]{lem:automorphisms}
Let $G$ be a compact group with Haar measure $\mu$ and let $\varphi$ be an automorphism of $G$. 
Then
\[ g \in \Sym(f) \quad \text{ iff } \quad g \circ \varphi \in \Sym(f \circ \varphi). \]

\begin{proof}
Clearly $g \in \Sym(f)$ if and only if for all $x \in G$,
\begin{align*}
0 &= \int_G g(r) \big( f(r^{-1}x) - f(r^{-1}x^{-1}) \big) \,d\mu(r) 
\shortintertext{i.e.}
0 &= \int_G g(\varphi(\varphi^{-1}(r))) \big( f(\varphi(\varphi^{-1}(r^{-1}x))) - f(\varphi(\varphi^{-1}(r^{-1}x^{-1}))) \big) \,d\mu(r) ,

\intertext{so that, writing $s = \varphi^{-1}(r)$ and $y = \varphi^{-1}(x)$,}
0 &= \int_G g(\varphi(s)) \big( f(\varphi(s^{-1}y)) - f(\varphi(s^{-1}y^{-1})) \big) \,d\mu(s) . \qedhere
\end{align*}
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:projected-background of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] We have
\begin{equation}
\Pi_{\varepsilon,f}N_\varepsilon(U_{\varepsilon,f})
=
-\varepsilon\left[J_\Gamma f+\mathcal Q_\Gamma(f)\right]
+\varepsilon^3G_{\varepsilon,f},
\end{equation}
where
\begin{align}
\|G_{\varepsilon,f}\|_{C^{0,\alpha}_{\gamma+2}}
&\le C,
\\
\|G_{\varepsilon,f_1}-G_{\varepsilon,f_2}\|_{C^{0,\alpha}_{\gamma+2}}
&\le
C\|f_1-f_2\|_{C^{2,\alpha}_\gamma}.

\end{align}
Set
\begin{equation}
E^\perp_{\varepsilon,f}
:=
N_\varepsilon(U_{\varepsilon,f})
-
Z_{\varepsilon,f}\Pi_{\varepsilon,f}N_\varepsilon(U_{\varepsilon,f}).
\end{equation}
In the unclipped region,
\begin{equation}
\left|
E^\perp_{\varepsilon,f}
\bigl(\Theta_f(Y,\varepsilon s)\bigr)
\right|
\le
C\varepsilon^2(1+|s|)q'(s)\rho(Y)^{-2}
+
O_N(\varepsilon^N\rho(Y)^{-N}),
\end{equation}
and $E^\perp_{\varepsilon,f}$ is super-algebraically small outside this region.

[Theorem 6 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Assume that $\{\delta_{i}, 1\le i\le n \}$ and $\{\zeta_{i}, 1\le i\le n \}$ are two independent sequences of random variables, where $\delta_{i}\sim\textnormal{Bernoulli}(p)$ are independent and $\zeta_{i}$ are independent $\alpha$-sub-exponential random variables with mean $0$ and variance $1$.
    Consider a random vector $\xi=(\xi_{1}, \cdots, \xi_{n})$  with $\xi_{i}=\delta_{i}\cdot\zeta_{i}$. Let $A$ be an $m\times n$ fixed matrix. Then for $0<\alpha\le 2$ and $t\ge 0$,
    \begin{align}
        \mathbb{P}\Big\{ \big\vert \Vert A\xi\Vert_{2}-\sqrt{p}\Vert A\Vert_{F} \big\vert>L^{2}(\alpha)t \Big\}\le 2\exp\Big\{-c(\alpha)\min \big\{\big(\frac{t}{\Vert A\Vert_{l_2\to l_2}}\big)^{2}, \big(\frac{t}{\Vert A\Vert_{l_2\to l_2}} \big)^{\alpha} \big\}    \Big\},
    \end{align}
    where $L(\alpha)=\max_{i}\Vert \zeta_i\Vert_{\Psi_{\alpha}}$ and $c(\alpha)>0$ is a constant depending only on $\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem l.sum of arXiv:2507.16056, 'Conditional GMC within the stochastic heat flow'] For $m\in\mathbb{N}$ and $i\in[\![m]\!]$, let $\mathcal{T}_{i}(t):L^2(\mathbb{R}^{d_i},\mathrm{d} x) \to L^2(\mathbb{R}^{d_{i-1}},\mathrm{d} x)$ be a $t$-parameterized operator with a nonnegative kernel.
Assume that, for $c', c_1, \ldots, c_{m}\in[0,\infty)$, $b_i\in(0,1)$,  and for a partition $A_1,A_2,A_3$ of $[\![m]\!]$, the following bounds hold for all $t>0$.
\begin{subequations}

\begin{align}

	&\text{When } i \in A_1,
	\quad
	\Normop{ \mathcal{T}_{i}(t) }
	\leq
	c_{i} \, e^{c't} \, t^{-b_i}\ .
\\

	&\text{When } i \in A_2,
	\quad
	\Normop{ \mathcal{T}_{i}(t) }
	\leq
	c_{i} \, e^{c't} \,t^{-1} \, \big|\log(\tfrac{1}{2}\wedge t)\big|^{-2} \ .
\\

	&\text{When } i \in A_3,
	\quad
	\Normop{ \mathcal{T}_{i}(t) }
	\leq
	c_{i} \, e^{c't} \,t^{-1}
	\text{ and }
	\NOrmop{\int_{0}^\infty \mathrm{d} t\ e^{-c' t} \mathcal{T}_{i}(t) } \leq c_i\ .
\end{align}
\end{subequations}
There exists a universal $c>0$ such that for all $m\in\mathbb{N}$, $\ell=0,\dots,|A_2|-1$, $t>0$, and $\lambda \geq c'+2$
\begin{align}

\begin{split}
	\NOrmop{ \int_{\Sigma(t)} &\mathrm{d} \vec{u} \, \prod_{i\in[\![m]\!]} \mathcal{T}_{i}(u_{i}) }
	\leq
	c^m\, m^{2} \, t^{|A_1|-1} \,  e^{\lambda t} \,
	\prod_{i\in[\![m]\!]} c_i 
	\cdot 
	\prod_{j\in A_1}\frac{t^{-b_j}}{1-b_j}
\\
	&\cdot
	\begin{cases}
	\displaystyle
	\frac{1}{ |\log(\lambda-c'-1)|^{|A_2|-1-\ell} \, |\log(t\wedge\frac{1}{2})|^{\ell+1} } & \text{ when } |A_2|>0\ ,
	\\
	\ 1 &\text{ when } |A_2|=0\ .
	\end{cases}
\end{split}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and $q\geq 1$ two integer numbers. Let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $f_{N} \in H ^{\odot p}$ for all $N\geq 1$. Assume (\ref{c1}). Then

		\begin{enumerate}
			\item for every $ g\in H ^{\odot q}$, 
			\begin{equation*}
				\Vert f_{N} \otimes _{r} g\Vert _{ H ^{\otimes p+q-2r}} \to _{N \to \infty }0 \mbox{ for every } \begin{cases}
					r=1,..., p\wedge q, \mbox{ if } p\not =q\\
					r=1,..., p-1 \mbox{ if } p=q. 
				\end{cases}
			\end{equation*}

			\item  for every sequence $(g_{N}, N\geq 1)\subset H ^{\otimes q}$ which converges in $ H ^{\otimes q}$, we have 
			\begin{equation*}
				\Vert f_{N} \otimes _{r} g_{N}\Vert _{ H ^{\otimes p+q-2r}} \to _{N \to \infty }0 \mbox{ for every } \begin{cases}
					r=1,..., p\wedge q, \mbox{ if } p\not =q\\
					r=1,..., p-1 \mbox{ if } p=q. 
				\end{cases}
			\end{equation*}
			\item  for every bounded sequence $(g_{N}, N\geq 1)\subset H ^{\otimes q}$ with $q\leq p$ we have 
			\begin{equation*}
				\Vert f_{N} \otimes _{r} g_{N}\Vert _{ H ^{\otimes p+q-2r}} \to _{N \to \infty}0 \mbox{ for every } \begin{cases}
					r=1,...,q, \mbox{ if } p\not =q\\
					r=1,..., p-1 \mbox{ if } p=q. 
				\end{cases}
			\end{equation*}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main_u_R of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] For 
    $0\leq\gamma<\frac{1}{2}$

    and
    $0< \lambda < \widehat{\lambda}_c,$ we have, for all $\epsilon>0$, that \smallskip
    \begin{enumerate}
    \item[(1)] If $2 < \delta < 1/\gamma -1$, then  \begin{align*}   \theta_{(u), R} \asymp \pi_{(u), R}\asymp \begin{cases}          u^{-\gamma\delta}R^{d(1-\delta)} & \text{ on } \{R^{d(\frac1{\gamma\delta}-\frac 1 \gamma)}\leq u \leq R^{-\epsilon}\},\vspace{0.5mm}\\                 1 & \text{ on }                    \{ u \leq R^{d(\frac1{\gamma\delta}-\frac 1 \gamma)} \}.\\                \end{cases}
        \end{align*}\smallskip
     \item[(2)] If $1/\gamma - 1< \delta < 1/ \gamma$, then
     \begin{align*}
     \theta_{(u), R} \asymp 
       \begin{cases}
       \pi^{(2)}_{(u), R}\asymp
       u^{-\gamma}R^{d(1-\frac1\gamma)(1-\frac1\delta)} \phantom{IIJ}
            \text{ on } \{ R^{-\frac{d(1+\delta-\frac 1 \gamma)}{\gamma\delta}}\leq u \leq R^{-\epsilon}\}, \vspace{1mm}\\ 
          \pi_{(u), R}\asymp
          \begin{cases}
       u^{-\gamma\delta}R^{d(1-\delta)} \phantom{XX} & \text{ on } \{R^{d(\frac 1{\gamma\delta}-\frac1\gamma)}\leq u \leq
         \smash{R^{-\frac{d(1+\delta-\frac 1 \gamma)}{\gamma\delta}}}\}, \vspace{0.5mm}\\
        1 & \text{ on } 
               \{  u \leq R^{d(\frac 1{\gamma\delta}-\frac1\gamma)} \}.\\
              \end{cases}
             \end{cases}
      \end{align*}\smallskip
       \item[(3)] If $\delta> 1/\gamma$ or if $\delta = \infty$ (hard case), then 
       \begin{align*}
            \theta_{(u), R} \asymp 
          \begin{cases}
            \pi^{(2)}_{(u), R}\asymp
            u^{-\gamma}R^{d(1-\frac1\gamma)(1-\gamma)}
             \phantom{XJ}\text{ on } \{R^{-d}\leq u \leq R^{-\epsilon}\},\vspace{1mm}\\
           \pi_{(u), R}\asymp
           \begin{cases}
          u^{-1}R^{d(1-\frac1\gamma)} \phantom{XX} & \text{ on } \{R^{d(1-\frac1\gamma)}\leq u \leq R^{-d}\},\vspace{0.5mm}\\
           1 & \text{ on } 
                  \{ u\leq  R^{d(1-\frac1\gamma)} \}.\\
              \end{cases}
              \end{cases}
       \end{align*}
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

