$0<t\le t_0$ and every $\theta\in S^{n-1}$,
\begin{equation}
 W_1(\Law(S_\theta),\gamma_1)
 \ge c_0t^2|\alpha_3(\theta)|-C_0t^3\beta_4(\theta)-C_0t^8|\alpha_3(\theta)|^3.
\end{equation}

[Lemma lem:SDE-embedding of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Assume that the collection of variances $(\sigma_e^2)_{e\in E(\mathbb{Z}^2)}$ vanishes outside of some finite box $\Lambda$. Consider the stochastic differential system defined on corners of $ \Upsilon^{\times} \cap  \Lambda  $, whose initial condition is given by $\mathcal{Y}^{(0)}$ and whose dynamic is given for any $\frak{p} \in \Lambda $ by $ \mathcal{Y}^{(s)}_{\omega}(\frak{p}):=\mathcal{Y}(\frak{p},\omega,s)$
\begin{align}
		d \mathcal{Y}^{(s)}_{\omega} (\frak{p})=& \frac{1}{2} \sum\limits_{z_k \in \Lambda} \sigma_k\Bigg[ \mathcal{Y}^{(s)}_{\omega}(c^+_k) \langle \chi_{\frak{p}}\chi_{a^+_k} \rangle_{S_{\omega}(s)} -  \mathcal{Y}^{(s)}_{\omega}(a^+_k) \langle \chi_{\frak{p}}\chi_{c^+_k} \rangle_{S_{\omega}(s)} \Bigg] dB^{(e_k)}_s \nonumber \\
		& + \frac{1}{4} \sum\limits_{z_k \in \Lambda}   \sigma_k^2\Bigg( \frac{\cos(\theta^{(s)}_{e_k,_{\omega}})}{\sin(\theta^{(s)}_{e_k,_{\omega}})} -\frac{\mathbb{E}_{S_{\omega}(s)}[\varepsilon_{e_k}]}{\sin(\theta^{(s)}_{e_k,_{\omega}})}  
 \Bigg)\times \cdots \nonumber \\
 & \cdots \times \Bigg[ \mathcal{Y}^{(s)}_{\omega}(c_k^{+})\langle \chi_{\frak{p}}\chi_{a_k^{+}} \rangle_{S_{\omega}(s)} - \mathcal{Y}^{(s)}_{\omega}(a_k^{+})\langle \chi_{\frak{p}}\chi_{c_k^{+}} \rangle_{S_{\omega}(s)} ds  \Bigg].\end{align}
Then $\mathbf{P}$-almost surely :
\begin{enumerate}
	\item There exist $T_0(\Lambda,\omega)>0$ such that there exist a solution to the SDE (equation eq:SDE-embedding of the paper) on $[0;T_0(\Lambda,\omega)] $.
	\item For any time $0\leq s \leq T_0 (\Lambda,\omega)$, the propagator $\mathcal{Y}_{\omega}^{(s)} $ (seen as the solution to (equation eq:SDE-embedding of the paper)) is an s-embedding $\mathcal{S}^{(s)}_{\omega}$ of the Ising model $S_{\omega}(s)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 23 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Suppose that $(\bX^{(t)})_{t\in \mathbb Z^+}$ is randomized-$\mu$-like, we have
        \begin{equation} 
            \mathbb P \lt( \mathsf{Like}(\chi,\rho,\varphi) \rt)=1-o(1).
        \end{equation}

[Definition 8 of arXiv:2506.22085, '2506.22085'] Fix $T>0$ and $\mu_0,\mu_1\in \ms M_+(\bb T^d)$ which we assume to
  be absolutely continuous with respect to $dx$ and with the same
  mass. Fix also  $\bar J \in L^2(\bb T^d;\bb R^d)$ satisfying the
  compatibility condition 
  \begin{equation}

    \mu_1(f)-\mu_0(f) = T\int\!dx \, \bar J \cdot \nabla f,
    \qquad f\in\Omega_0.  
  \end{equation}
  \begin{itemize}
  \item[(HSPDC)]The \emph{hydrodynamic Schr\"odinger problem with
      density and current constrain\-ts} is the optimization problem 
     \begin{equation*}
       \psi_T(\mu_0,\mu_1; \bar J) :=
       \frac 1T \inf \Big\{ I(\pi,\ms J),\;\pi_0=\mu_0,\:\pi_T=\mu_1,\:
       \ms J(\omega)
       = \frac 1T\int\!dx\, \bar J\cdot \omega,\; \omega \in\Omega_1\Big\}.
     \end{equation*}
   \item[(MSPDC)]The \emph{measure Schr\"odinger problem with
      density and current constraint} is the optimization problem 
    \begin{equation*}
      \begin{split}
      \Psi_T(\mu_0,\mu_1; \bar J) :=&
      \frac 1T \inf \Big\{ \mf F(R),\;R_0=\mu_0,\:R_T=\mu_1,\:
      \\
      &\quad
      \frac 1T \int\!R(dX) \int_0^T\!\omega(X_t)\circ dX_t
      = \int\!dx\, \bar J\cdot \omega,\; \omega \in\Omega_1\Big\}.
    \end{split}
  \end{equation*}   
  \end{itemize}

[Definition of arXiv:2412.05030, 'Characterization of Subordinate Symmetric Markov Processes'] \begin{enumerate}[(i)]
    \item  We say that $(M,d,\mu)$ satisfies the volume doubling property (VD)
  if there exist constants $C \ge 1,d_2 > 0$ such that for all $x \in M$ and all $0 < r \le R$,
  \begin{equation}
    \frac{V(x,R)}{V(x,r)} \le C \left(\frac{R}{r}\right)^{d_2}.
  \end{equation}
  \item   We say that $(M,d,\mu)$ satisfies the reverse volume doubling property (RVD)
  if there exist constants $C > 0,d_1 > 0$ such that for all $x \in M$ and all $0 < r \le R$,
  \begin{equation}
   C \left(\frac{R}{r}\right)^{d_1} \le \frac{V(x,R)}{V(x,r)}.
  \end{equation}
  \end{enumerate}

[Lemma LB_lemma_1 of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $B_k := \{x \in \mathbb Z^d : \mathrm{D}_{\ell}(o, x) \le k \}$. Then, there exists a positive $C = C(d, \alpha, K, \ell)$ such that for any $m \ge 1$ and any $x \in \mathbb Z^d$ with $x \neq o$, we have
    \begin{align*}
        \mathbb P \left( \mathrm{D}_\ell(o, x) \le m \right) \le \lambda C \left(\frac{m}{|x|}\right)^{d + \alpha} \, \sum_{j=0}^{m-1} \mathbb{E} [|B_j|] \ \mathbb{E} [|B_{m-j-1}|].
    \end{align*}

