[Corollary cor:disInt of arXiv:2505.09604, 'Exceptional force, uncountably many solutions in the KPZ fixed point'] On the event $\Omega_1$, the following holds  for every $\xi\in\Xi$. \vspace{2pt}\\ 
       \begin{enumerate}[label=(\roman*), font=\normalfont]
           \item  For every $t\in\mathbb{R}$, there exist bijections $\sigma_t^-: \mathfrak S_{t,\xi}^L \to \mathcal{T}^{\xi,-}$ and $\sigma_t^+: \mathfrak S_{t,\xi}^R \to \mathcal{T}^{\xi,+}$  such that, for any $x\in \mathfrak S^L_{t,\xi}$,  $\sigma_{(x,t)}^- :=\sigma_t^-(x)$ is the unique element of $\mathcal{T}^{\xi,-}$ satisfying   $\sigma_{(x,t)}^-(t) = x$, and for $x \in \mathfrak S_{t,\xi}^R$, $\sigma_{(x,t)}^+ :=\sigma_t^+(x)$ is the unique element of $\mathcal{T}^{\xi,+}$ satisfying  $\sigma_{(x,t)}^+(t) = x$.  
           \item  For any $x<y$ in $\mathfrak S^L_{t,\xi}$ (resp $\mathfrak S_{t,\xi}^R$), we have
           \begin{equation}
               \sigma_{(x,t)}^-(r)<\sigma_{(y,t)}^-(r), \quad\text{\rm(resp. $\sigma_{(x,t)}^+(r)<\sigma_{(y,t)}^+(r)$)} \qquad \forall r\in\mathbb{R}.
           \end{equation}
           In other words, leftmost (resp. rightmost) bi-infinite interfaces associated with different points in $\mathfrak S^L_{t,\xi}$ (resp. $\mathfrak S^R_{t,\xi}$) never meet. In particular, the elements in $\mathcal{T}^{\xi,\pm}$ are disjoint.  
       \end{enumerate}

[Proposition 16 of arXiv:2604.26898, '\bf Stochastic Scaling Limits and Synchronization \\by Noise in Deep Transformer Models'] Let $\mu_0 \in \mathcal P_1(\S^{d-1})$ be the initial distribution, $\empmu_0$ be the empirical measure of \eqref{eq:dynamics_tokens} at initialization, sampled iid from $\mu_0$. Let $r_{d}(N)$ be the rate
    \begin{equ}
        r_{d}(N)=\begin{cases}
            N^{-1/2}& d<4\\
            N^{-1/2}\log(1+N)& d=4\\
            N^{-2/d} & d>4 
        \end{cases}.
    \end{equ}
    Then the following bound holds:
    \begin{equ}
        \E\left[\sup_{0\leq t\le T} \W_2^2(\empmu_t,\mu_t)\right]\le \mathsf c_{T}\, r_d(N)
    \end{equ}
    where $\mathsf c_{T}$ is a constant that depends only on $T, d, \act, \varbU,\varbW$ and the Lipschitz constants in Assumption~\ref{ass:att_reg}. Here, $\mathbb E$ is the unconditional expectation on the underlying probability space (including the initialization).

