body:
[Proposition 17 (Mixed moments of the surface measure) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] For $1<p<\infty$ and $n\geq 2$ consider the weighted $\ell_p$-ball $\mathbb B_p^n(a)$ with weights $a_1,\ldots, a_n >0$.
Let $\lambda_1,\dots,\lambda_n\in\mathbb C$ satisfy $\Re \lambda_k>-1$ for all $k=1,\dots,n$. Then
\begin{equation}
\int_{\partial \mathbb B_p^n(a)}
\prod_{k=1}^n |x_k|^{\lambda_k}\,d\mathcal H^{n-1}(x)
=
\frac{
p\, \prod_{k=1}^n a_k^{-\lambda_k-1}
}{
2\,\Gamma\!\left(\dfrac{n+\Lambda+p-1}{p}\right)\sqrt\pi
}
\int_0^\infty
\frac{G_\lambda(0)-G_\lambda(\theta)}{\theta^{3/2}}\,d\theta,
\end{equation}
where $\Lambda=\sum_{k=1}^n \lambda_k$ and
$$
G_\lambda(\theta):=\prod_{k=1}^n \mathcal F_p(\theta a_k^2;\lambda_k), \qquad \theta \geq 0,
\qquad
G_\lambda(0)
=
\left(\frac{2}{p}\right)^n
\prod_{k=1}^n
\Gamma\!\left(\frac{\lambda_k+1}{p}\right).
$$

