[Lemma lem:lemma5.5 of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Set 
\begin{equation}
    \mathcal{D}_n:=U_{n_j}(\frac{H}{2})-V_{n_j}=\sum_{k\ge 1}\sum_{a\in \{2,3\}^k}\sum_{l_0+\ldots +l_k=n}V_{l_0}\underline{\Phi_{a_1}V_{l_1}}\cdots\underline{\Phi_{a_k}V_{l_k}}
\end{equation}
and
\begin{equation}
\widehat{\mathcal{D}}_n
:= \sum_{k \geq 1} 8^k
\sum_{\substack{
    l_0 + \cdots + l_k = n
}}
\widehat{V}_{l_0} \,
\widehat{\underline{\Phi_{2} V_{l_1}}} \cdots
\widehat{\underline{\Phi_{2} V_{l_k}}},
\end{equation} then for all $s\ge 1$, 
    \begin{equation}
        |\mathbb{E}\big[\prod_{j=1}^s \mathrm{Tr} ({\mathcal{D}}_{n_j})\big]|\le \mathbb{E}\big[\prod_{j=1}^s \mathrm{Tr}( \widehat{\mathcal{D}}_{n_j})\big]
    \end{equation}

[Theorem t:IntroCheeger of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] In the setting of Assumption~(ass:IntroManifold of the paper), suppose further that~$\nu\in\msP_2$.
Then,
\begin{enumerate}[$(i)$]
\item the measure representation~$\mu_\bullet$ is properly associated with the form~$\mcE_\mcQ$ in~(equation eq:IntroCheeger of the paper) for~$\mcQ=\mcQ_{\pi,\nu}$;
\item its generator is the Friedrichs extension of the operator\footnote{Heuristically, this operator captures the infinitesimal motion of mass in~$\eta$ obtained by moving its atom at~$x$ according to~$\mssW$, weighted by local mass proportions.}
\begin{equation}
(\mcL u)(\eta)\eqdef \int_M \frac{\mssL^z\big\lvert_{z=x} u(\eta+\eta\!\left\{x\right\}\delta_z-\eta\!\left\{x\right\}\delta_x)}{(\eta\!\left\{x\right\})^2} \mathop{}\!\mathrm{d}\eta(x)
\end{equation}
on the algebra of extended cylinder functions~(equation eq:HCylinderFEps of the paper).
\item the form~$\mcE_\mcQ$ coincides with the Cheeger energy~$\Ch_{W_2,\mcQ}$;
\item the Rademacher Theorem holds for~$\mcE_\mcQ$ on~$(\msP_2,W_2)$, that is: every $W_2$-Lipschitz function~$u\colon\msP_2\to{\mathbb R}$ is an element of the form domain, is Fr\'echet differentiable $\mcQ$-a.e., and satisfies
\[
\left\lVert\boldsymbol\nabla u\right\rVert_{T_\eta\msP_2} \leq \Lip_{W_2}[u] \,\mathrm{.}
\]
\item the semigroup~$\mcH_\bullet$ of~$\mcE_\mcQ$ satisfies the following one-sided integral Varadhan short-time asymptotic estimate: for every pair of Borel sets~$A_1,A_2\subset\msP_2$ with~$\mcQ A_1, \mcQ A_2>0$,
\[
-2\, \lim_{t\downarrow 0} t \log \scalar{\car_{A_1}}{\mcH_t \car_{A_2}}_{L^2(\mcQ)} \ \geq\ \mcQ\text{-}\essinf_{\eta_i\in A_i} W_2(\eta_1,\eta_2)^2 \,\mathrm{,}\;\,
\]
while the opposite inequality fails as soon as~$\pi$ is not concentrated on a singleton.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem be of arXiv:2412.04013, 'Rate estimates for total variation distance with applications\thanks{The author gratefully'] Let Assumption (forclt of the paper) be in force. Then for each $\epsilon>0$, 
\begin{equation}
d_{TV}(S_{n},\Phi)\leq C_{\epsilon}n^{-\frac{1}{2}+\epsilon},\ n\geq 2
\end{equation}
holds for a suitable constant $C_{\epsilon}$, where $\Phi$ is a random variable with $d$-dimensional standard Gaussian law.
One also has
\begin{equation}
\sup_{x\in\mathbb{R}^{d}}|f_{S_{n}}(x)-f_{\Phi}(x)|\leq C_{\epsilon}'n^{-\frac{1}{2}+\epsilon}
\end{equation}
where $f_{S_{n}}$ denotes the density function of $S_{n}$ and $f_{\Phi}$ is the standard $d$-dimensional
Gaussian density. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_bound_on_last_point_if_close_to_mu_c of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] If $v^{\textup{c}} \in \Omega_{\textup{c}}$, then
\begin{equation*}
|v^{\textup{c}}_{-1}| \leq R+2 \varepsilon n.
\end{equation*}

[Prop microlocal-endpoints of arXiv:2609.03751, 'Sparse bounds for maximal rough singular integrals'] There exist constants \(\delta_3,\delta_4>0\), depending only on the
dimension and on the auxiliary parameters, such that
\[
\begin{aligned}
 \|\mathcal I_1\|_{L^1(\mathbb R^d)}
 &\lesssim_d
 2^{-2n}2^{-\kappa s}
 \|\Omega\|_{L^\infty(S^{d-1})}\|b\|_{\dot{\mathcal X}_1(\mathcal Q)}|Q_0|,
 &\quad&\text{\rm(i)}\\
 \|\mathcal I_2\|_{L^1(\mathbb R^d)}
 &\lesssim_d
 2^{-2n}2^{-(1-\kappa)s}
 \|\Omega\|_{L^\infty(S^{d-1})}\|b\|_{\dot{\mathcal X}_1(\mathcal Q)}|Q_0|,
 &&\text{\rm(ii)}\\
 \|\mathcal I_3\|_{L^2(\mathbb R^d)}
 &\lesssim_d
 2^{-n}2^{-\delta_3s}
 \|\Omega\|_{L^\infty(S^{d-1})}\|b\|_{\dot{\mathcal X}_1(\mathcal Q)}|Q_0|^{1/2},
 &&\text{\rm(iii)}\\
 \|\mathcal I_4\|_{L^2(\mathbb R^d)}
 &\lesssim_d
 2^{-n}2^{-\delta_4s}
 \|\Omega\|_{L^\infty(S^{d-1})}\|b\|_{\dot{\mathcal X}_1(\mathcal Q)}|Q_0|^{1/2}.
 &&\text{\rm(iv)}
\end{aligned}
\]
Consequently, if
\[
 \mathcal I_{34}:=\mathcal I_3+\mathcal I_4
 \quad\text{and}\quad
 \delta_0:=\min\{\delta_3,\delta_4\},
\]
then
\[
 \|\mathcal I_{34}\|_{L^2(\mathbb R^d)}
 \lesssim_d
 2^{-n}2^{-\delta_0s}
 \|\Omega\|_{L^\infty(S^{d-1})}\|b\|_{\dot{\mathcal X}_1(\mathcal Q)}|Q_0|^{1/2}.
\]

