[Theorem 3 ({\cite[(1.16)) of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] {BurchardSchmuckenschlager}}]

For every bounded domain $D$,
\begin{align}

|D|-\int_D u_0(t,x)\d x\gtrsim t^{1/2}.
\end{align}
In other words, the total mass cannot converge to $|D|$ at a faster rate than $t^{1/2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2608.07879, 'Sharp Wasserstein Convergence Rates for Empirical Path Laws of It\^o Processes'] Let $p\ge1$, and let $Z$ be a $\Cc^d$-valued random variable with law
$\eta$. Assume that, for some $\rho>p$ and $A>0$,
\begin{equation}
    \E\|Z\|_\infty^\rho<\infty,
    \qquad
    e_{n,p}(Z)
    \le
    A(\log n)^{-1/2},
    \qquad n\ge2.
\end{equation}
Let $Z_1,\dots,Z_N$ be independent copies of $Z$, and set
\begin{equation}
    \eta_N:=\frac1N\sum_{i=1}^N\delta_{Z_i}.
\end{equation}
Set
\begin{equation}
    \beta_{\rho,p}
    :=
    \min\left\{\frac{\rho}{p}-1,\frac{\rho}{2p}\right\}.
\end{equation}
There exist constants $C_{p,\rho,A,\eta}>0$ and $c_p>0$, where
$C_{p,\rho,A,\eta}$ depends on $\eta$ only through
$\E\|Z\|_\infty^\rho$, such that, for every $N\ge2$ and $t>0$,
\begin{equation}
    \P\left(
        \Wc_p(\eta_N,\eta)>C_{p,\rho,A,\eta}(\log N)^{-1/2}+t
    \right)
    \le
    \exp\left(
        -\frac{c_pNt^{2p}}{(\log N)^{p^2/(\rho-p)}}
    \right)
    +C_{p,\rho,A,\eta}N^{-\beta_{\rho,p}}t^{-\rho}.

\end{equation}

