[Prp 25 of arXiv:2608.13976, 'Boundary Harnack principle for diffusion with jumps on metric measure spaces'] Let $D$ be an  open subset in $\R^d (d\geq 3)$ and  $R_0>0$.
Assume for each $x\in\R^d,$ $z\mapsto j(x, z)$ is positive and for each  $R\in (0, R_0)$ and $x_0\in\R^d,$
\begin{equation}
\inf_{z\in \R^d:  R/16\leq |z|<R/2} j(x_0, z)>0.
\end{equation}
Suppose  for each  $x_0\in\R^d, R\in (0, R_0)$ and $0<p<q\leq 1,$ there exists $c_1=c_1(x_0, R, p, q)>1$  such that  for any $x\in B(x_0, pR)$ and $y\in B(x_0, qR)^c,$
\begin{equation}
c_1^{-1}J(x_0, y)\leq J(x, y) \leq c_1J(x_0, y).
\end{equation}
Then  for each $z_0\in \partial D$ and $R\in (0, \tfrac{1}{16}R_0),$
there exists a constant  $C=C(z_0, R)\geq 1$   independent of the geometry of $D$ such that   for   any  nonnegative  regular harmonic functions $f$ and $g$
on $D\cap B(z_0, R)$   vanishing  on  $(D^c)^r\cap B(z_0, R),$
\begin{equation}
f(x)g(y)\leq Cf(y)g(x)  \quad \hbox{for } x, y\in D\cap B(z_0, R/32).
\end{equation}
Furthermore, if \eqref{e:4.27} and \eqref{e:4J} hold uniformly for $x_0\in\R^d,$
then BHP \eqref{e:Xb} holds with $C=C(R)\geq 1$ uniformly for $z_0\in \partial D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma TSP-E-L-A-1 of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Suppose $\left| {t - {t_0}} \right|{\left\| u \right\|_1} \lesssim 1$. Let $w{\left( t ,x \right)}$ be the solution of the transport equation
\begin{equation*}
\left\{ {\begin{array}{*{20}{l}}
{\partial _t}w + \left( {v \cdot \nabla } \right)w = u ,   &\mbox{on}\ \left[ {{t_0}, T } \right]  \times  \mathbb{T}^2, \\
w\left( {{t_0}} \right) = {w_0} ,
\end{array}} \right.
\end{equation*}
where $v\left( t, x \right)$ and $u\left( t, x \right)$ are the vector functions on $\left[ {{t_0}, T } \right]  \times   \mathbb{T}^2$. Then, for any $\alpha \in \left[ {0,1} \right)$ and $N \in {\mathbb{Z}^ + } $, we have
\begin{equation}
{\left\| {w\left( t \right)} \right\|_\alpha } \lesssim {\left\| {{w_0}} \right\|_\alpha } + \int_{{t_0}}^t {{{\left\| {u\left( s  \right)} \right\|}_\alpha }} \mathrm{d}s  ,
\end{equation}
and
\begin{equation}
{\left[ {w\left( t \right)} \right]_{N + \alpha }} \lesssim  {\left[ {{w_0}} \right]_{N + \alpha }} + \left| {t - {t_0}} \right|{\left[ v \right]_{N + \alpha }}{\left[ {{w_0}} \right]_1}  + \int_{{t_0}}^t {{{\left[ {u\left( s  \right)} \right]}_{N + \alpha }} + \left| {t - s } \right|{{\left[ v \right]}_{N + \alpha }}{{\left[ {u\left( s  \right)} \right]}_1}} \mathrm{d}s  .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 (Local $C^0$ estimate) of arXiv:2608.29736, '2608.29736'] There exists a constant \(C>0\), independent of \(t\), such that
\begin{equation}
u_t\geq\rho-C\qquad\text{on }M\setminus Z.
\end{equation}
Consequently, for every \(K\Subset M\setminus Z\), there exists
\(C_K>0\), independent of \(t\), such that
\begin{equation}
-C_K\leq u_t\leq0\qquad\text{on }K.
\end{equation}

[Cor 158 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For all $\ell\leq \ubl$, we have 
  \begin{equation}

  \lim_{\eta\downarrow 0}
  \bbE\big[
  \hat{b}^{\chaos,\ell}(\hat X^{\ell,\eta})
  \big]
  =
  \lim_{\eta\downarrow 0}
  \bbE\big[
  \hat{b}^{\chaos,\ell}(\hat{\prxX}^{\ell,\eta}) \big]
  =
  0\,.
  \end{equation}

[Lem many_to_one of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] Let $t \geq s_0 \geq 0$ and $f \colon \mathcal{C}([s_0,t],\mathbb{R}^2) \to [0,\infty)$ be a measurable functional. Then, for any $x,y \in \mathbb{R}^2$,
	\begin{align*}
	    & \mathbb{E}_{(s_0,x,y)} \mathopen{}\mathclose\bgroup\originalleft[\sum_{u \in \mathcal{N}(t)} f\mathopen{}\mathclose\bgroup\originalleft((X_u(s),Y_u(s))_{s\in [s_0,t]} \aftergroup\egroup\originalright) \aftergroup\egroup\originalright] \\
	    & = \mathbb{E}_{(s_0,x,y)} \mathopen{}\mathclose\bgroup\originalleft[f\mathopen{}\mathclose\bgroup\originalleft((X_s,Y_s)_{s\in [s_0,t]} \aftergroup\egroup\originalright) \exp\mathopen{}\mathclose\bgroup\originalleft( \int_{s_0}^t b(\theta_s) \mathop{}\mathopen{}\mathrm{d} s \aftergroup\egroup\originalright) \aftergroup\egroup\originalright],
	\end{align*}
	where $(X_s,Y_s)_{s\in [s_0,t]}$ is a Brownian motion on $\mathbb{R}^2$ starting from $(x,y)$ at time $s_0$ under $\mathbb{P}_{(s_0,x,y)}$, and $(R_s,\theta_s)_{s\in [s_0,t]}$ is a representation of its polar coordinates. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:conv_mart of arXiv:2512.12902, 'Non-equilibrium fluctuations for the \\stirring process with births and deaths'] For $H \in\mathbb S$, the sequence of martingales $\{M_t^\epsilon(H);t\in [0,T]\}_{\epsilon}$ converges in the topology of $\mathcal  D([0,T], \mathbb R)$, as $\epsilon\to 0$, towards a mean-zero Gaussian process $ W_t(H)$ with  quadratic variation given by 
\begin{equation*}
\int_0^t \|\ T_{t-s}H\|_{L^2(\rho_s)}^2\,ds,
\end{equation*}
where $\rho(u,s)$ is the solution of the hydrodynamic equation (equation eq:Robin_equation of the paper) and the $\mathbb L^2$-norm is defined in (equation eq:norm of the paper).

