[Theorem 14 of arXiv:2506.15044, '2506.15044'] Let $V\in\mathcal{V}^\mathbb{B}$, and $a,b\in \mathbf{R}$. Suppose that $H\in \mathcal{L}^\mathbb{B}_s(A)\cap\mathcal{L}^\mathbb{B}_s(V)$ and $K\in \mathcal{L}^\mathbb{B}_s(A)$.
\begin{itemize}
\item[$(1)$] $aH+bK\in \mathcal{L}^\mathbb{B}_s(A)$, and in this case, we have
  \begin{equation}
   (aH+bK)_{\bullet}A=a(H_{\bullet}A)+b(K_{\bullet}A).
  \end{equation}
\item[$(2)$] $H\in \mathcal{L}^\mathbb{B}_s(aA+bV)$, and in this case, it holds that
  \begin{equation}
   H_{\bullet}(aA+bV)=a(H_{\bullet}A)+b(H_{\bullet}V).
  \end{equation}
\item[$(3)$] Let $\widetilde{H}\in \mathcal{P}^\mathbb{B}$. Then $\widetilde{H}\in \mathcal{L}^\mathbb{B}_s(H_{\bullet}A)$ if and only if $\widetilde{H}H\in \mathcal{L}^\mathbb{B}_s(A)$.
  Furthermore, if $\widetilde{H}\in \mathcal{L}^\mathbb{B}_s(H_{\bullet}A)$ (or equivalently, $\widetilde{H}H\in \mathcal{L}^\mathbb{B}_s(A)$), then
  \begin{equation}
  (\widetilde{H}H)_{\bullet}A=\widetilde{H}_{\bullet}(H_{\bullet}A).
  \end{equation}
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 (Weak-$L^2$ logarithmic force estimate) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] There is a universal $C$ such that
