[Lemma lem:rep_W of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] For any $\mathbf{q} \in \mathcal{Q}$, $k \in {\mathbb{N}}$, $0 \le \ell \le k - 1$, $i \in {\mathbb{Z}}$ and $n \in {\mathbb{Z}}_{\ge 0}$, we have
                \begin{align}
                    &Y^{{i}}_{k-\ell}\left(\Psi_{\ell}\left(\eta\right),n\right) \\
                    &= \frac{v^{\mathrm{eff}}_{k-\ell}\left(\theta^{\ell}\mathbf{q}\right)}{v^{\mathrm{eff}}_{1}\left(\theta^{k-1}\mathbf{q}\right)} \left(n -  M^{{i}}_{k}\left(\eta,n\right) \right) \\
                    & \ + 2\sum_{h = \ell + 1}^{k - 1} \frac{v^{\mathrm{eff}}_{h-\ell}\left(\theta^{\ell}\mathbf{q}\right)}{v^{\mathrm{eff}}_{1}\left(\theta^{h-1}\mathbf{q}\right)} \sum_{j = X^{{i}}_{k - h}\left(\Psi_{h}\left(\tilde{\eta}\right), 0 \right)  + 1}^{X^{{i}}_{k - h}\left(\Psi_{h}\left(\tilde{\eta}\right), n \right) } \left( \zeta_{h}\left({\eta,}j\right) - \alpha_{h}\left(\mathbf{q}\right) \right) ,
                \end{align}
            with convention $\sum_{\ell = 1}^{0} = 0$. In particular, we have 
                \begin{align}
                    Y^{{i}}_{k}\left(\eta,n\right) 
                    &= \frac{v^{\mathrm{eff}}_{k}\left(\mathbf{q}\right)}{v^{\mathrm{eff}}_{1}\left(\theta^{k-1}\mathbf{q}\right)}\left(n -  M^{{i}}_{k}\left(\eta,n\right) \right) \\
                    & \ + 2\sum_{h = 1}^{k - 1} \frac{v^{\mathrm{eff}}_{h}\left(\mathbf{q}\right)}{v^{\mathrm{eff}}_{1}\left(\theta^{h-1}\mathbf{q}\right)} \sum_{j = X^{{i}}_{k - h}\left(\Psi_{h}\left(\tilde{\eta}\right), 0 \right)  + 1}^{X^{{i}}_{k - h}\left(\Psi_{h}\left(\tilde{\eta}\right), n \right) } \left( \zeta_{h}\left({\eta,}j\right) - \alpha_{h}\left(\mathbf{q}\right) \right) .
                \end{align}

