[Lemma lem.maximalCluster of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Every ${\scaleobj{1}{\square}} \in \mathcal{G}^{(N)}_k$ is $N$-$\mathsf{stable}$ for the following property: for every ${\scaleobj{1}{\square}}', {\scaleobj{1}{\square}}'' \in \mathcal{S}^{loc}_{\mathcal{G}^{(N)}_{k-1}}({\scaleobj{1}{\square}})$ with ${\dist({\scaleobj{1}{\square}}',{\scaleobj{1}{\square}}'')\leqslant 1}$, there exists a cluster $\mathscr{C}^\#$ such that
		\begin{equation}

			\mathscr{C}^\#_*({\scaleobj{1}{\square}}') \cup \mathscr{C}^\#_*({\scaleobj{1}{\square}}'') \subseteq \mathscr{C}^\# \subseteq {\scaleobj{1}{\square}}' \cup {\scaleobj{1}{\square}}''.
		\end{equation} 
		Moreover, for any integer $0 \leqslant h \leqslant k-1$ and $\widehat{{\scaleobj{1}{\square}}} \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}})$, we have
		\begin{equation}

			\mathscr{C}^\#_*(\widehat{{\scaleobj{1}{\square}}}) \subseteq	\mathscr{C}^\#_*({\scaleobj{1}{\square}}).
		\end{equation}

[Lemma 20 (Binomial resolvents) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[lemma]{lem:binomial-resolvents}
If $N\sim\mathrm{Binomial}(t,p)$ and $\kappa\ge1$, then
    \begin{equation}
    \E\sbr[3]{\frac1{\kappa+N}}
    \le\frac C{\kappa+tp},
    \qquad
    \E\sbr[3]{\frac1{(\kappa+N)^2}}
    \le\frac C{(\kappa+tp)^2}
    \end{equation}
for some absolute constant $C>0$.

