[Lemma lmm:maxcorr-CLT of arXiv:2602.14998, 'Random geometric graphs with smooth kernels: sharp detection threshold and a spectral conj'] Let $x=(x_1,\ldots,x_d)$ be a random vector in $\mathbb{R}^d$ with i.i.d.\ components from a fixed distribution on $\mathbb{R}$ with zero mean, unit variance, and $\mathbb{E}[|x_i|^3]<\infty$. Fix $y,z\in\mathbb{R}^d$.
There is a constant $C>0$ such that for any CDF $f$ on $\mathbb{R}$, we have 
\[
\mathrm{Cov}(f(\Iprod{x}{y}), f(\Iprod{x}{z}))
\leq  C \pth{|\rho| + (1-\rho^2)^{-3/2} 
\pth{\frac{\|y\|^2+\|z\|^2}{
\|y\|^2 \|z\|^2}}^{3/2} (\|y\|_3^3+\|z\|_3^3)
}
\]
where $\rho \equiv \frac{\Iprod{y}{z}}{\|y\|\|z\|}$.

[Defi 17 of arXiv:2606.27035, 'R\'emy's diffusion on Brownian trees'] We say that a random marked tree $\boldsymbol{\mathcal{T}}^{\, \bullet}$ with mass $1$ is \emph{$\varepsilon$-good} where $\varepsilon \in (0, 1)$, if it is composed of three parts, as illustrated in Figure~\ref{fig:good_Brownian_tree}:
\begin{enumerate}
\item a \emph{spine}, in red, which is a segment started from the root and with length smaller than $\varepsilon$;
\item a \emph{good tree}, in green, grafted at the extremity of the spine, with mass greater than $1-\varepsilon$, which has the law of a scaled marked Brownian CRT, whose marked point is that of the entire tree;
\item a \emph{bad} part made of an arbitrary forest of blue trees grafted all along the spine.
\end{enumerate}

[Lemma lem:heat_decay of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] Fix $T, K > 0$, write $\varepsilon \overset{\mathrm{\scriptscriptstyle def}}{=} \frac18$, and let $\Gamma_r$ be as in~(equation eq:gamma_r of the paper). For every $m > 0$ there is a constant $ C(m, K, T) > 0$ such that the following holds for every $N \geqslant 1$, every $\varrho \in [0,1]$ and all $0 \leqslant s \leqslant t \leqslant T$. Let $\phi \colon [s,t] \to \mathcal{H}$ solve
    \begin{equation}
      \partial_r \phi_r = \Delta\phi_r + F_r , \qquad \phi_s = Q_N\phi_s ,
    \end{equation}
and suppose that on the event $E_K$ of~(equation eq:good_event_EK of the paper):
    \begin{enumerate}[label=(\alph*)]
      \item The flow obeys the a priori bound
        \begin{equation}
          \sup_{r\in[s,t]}\|\phi_r\|^2 + \int_s^t \|\phi_r\|_{H^1}^2 \mathrm{\,d} r
          \leqslant m \|\phi_s\|^2 .
        \end{equation}
      \item The forcing splits as $F_r = a_r\phi_r + G_r + R_r$, where $a_r \leqslant m\Gamma_r$, and
        \begin{equation}
          \|G_r\|_{H^{-1}} \leqslant m\,\Gamma_r^{1/2}\|\phi_r\|_{H^\varepsilon} ,
        \end{equation}
and the remainder satisfies for some $\varsigma_r \geqslant 0$,
        \begin{equation}
          |\langle R_r, Q_N\phi_r\rangle| + |\langle R_r, P_N\phi_r\rangle|
          \leqslant \varsigma_r , \qquad
          \int_s^t \varsigma_r \mathrm{\,d} r \leqslant \varrho \, \|\phi_s\|^2 .
        \end{equation}
    \end{enumerate}
Then, pathwise on $E_K$,
    \begin{equation}
      \|\phi_t\| \leqslant C(m, K, T)\bigl( e^{-N^2(t-s)/2} + N^{-3/8} + \varrho^{1/2} \bigr)
      \|\phi_s\| .
    \end{equation}

