[Lemma 10 of arXiv:2607.13379, 'Quantitative Propagation of Chaos and Fluctuations for Kinetic McKean--Vlasov SDEs with Si'] Let $\beta\in[0,2)$,  $\eps\in(0,2-\beta)$ and $f:\mR^{2d}\to\mR$ be a time independent function. 
\begin{enumerate}[(i)]
\item If $f\in\mK_\beta$, then $f\in \bC^{\beta-2}_a$. More precisely,
for every $\lambda>0$, there is a constant $C=C(d,\lambda,\beta)>0$ such that for every $\delta\in(0,1)$,
\begin{equation}
\|f\|_{\bC^{\beta-2}_a}
    \leq
    C\delta^{(\beta-2)/2}\cK^{(\beta)}_\lambda(f;\delta).
\end{equation}
\item If $0\leq f\in L^1_{\rm loc}(\mR^{2d})\cap\bC^{\beta-2+\eps}_a$, then $f\in\mK_\beta$. More precisely,
for every $\lambda>0$, there is a constant $C=C(d,\lambda,\beta,\eps)>0$ such that for every $\delta\in(0,1)$,
\begin{equation}
    \cK^{(\beta)}_\lambda(f;\delta)\leq {C} \delta^{\eps/2}
    \|f\|_{\bC^{\beta-2+\eps}_a}.
\end{equation}
\end{enumerate}

