[Definition 66 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Given $(\md,q,\omega,L)$ as above, we let $w_0$ be a point in $\mL_q$ satisfying the following conditions: 
  \begin{itemize}
  \item When $\bd=\md$, let $w_0 \in \mathfrak{L}_q$ be any point (which is not necessarily unique) satisfying 
	\begin{flalign}

		\mathfrak{d}_{w_0} =  \bd; \qquad L^{-1} \be \le \mathfrak{e}_{w_0;q} \le L \be
	\end{flalign} 
	so that, by \eqref{ede}, we have
        \begin{flalign}

        L^{-1} N^{2B\delta} \omega (qN)^{-1} \le \mathfrak{d}_{w_0} \mathfrak{e}_{w_0;q} \le L N^{2B\delta} \omega (qN)^{-1}.  
        \end{flalign}
      \item  When $\bd>\md$, let $w_0 \in \mathfrak{L}_q$ denote the point with
        $\md_{w_0}=\bd$, such that the orthogonal projection of $w_0$ to $\ell_{w_0}$ is the tangency point $\mathfrak{A}_q \cap \ell_{w_0}$. 

  \end{itemize}

[Theorem 6tdiv1 of arXiv:2609.03926, 'Overcolored Partition $k$-tuples Restricted by Parity of the Parts'] Let $j\ge2$, $r,s,k,\alpha,m\ge 1$ be integers with $gcd(2,m)=1$ and $p$ be any prime such that $p^{j-1}(p^2-1)\ge 3k(r+s)$. If $r=2^\alpha m$ or $k=2^\alpha m$, then the set
	\begin{align*}
		\{n\in\mathbb{N}:\bar{b}^k_{r,s}(n)\equiv 0\pmod{p^j}\} 
	\end{align*}
	has arithmetic density $1$, namely, 
	\begin{align*}
		\lim_{X\to\infty}\frac{\#\{0\le n\le X:\bar{b}^k_{r,s}(n)\equiv 0\pmod{p^j}\}}{X}=1.
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2506.08910, 'Critical points of random polynomials and finite free cumulants'] For any $j\in\N$,\begin{equation}
			\kappa_{j}^{N}(p_N)=\kappa_{j}(p_N)+O\left(\frac{1}{N}\right),
		\end{equation} almost surely.

