body:
[Lemma 15 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Suppose $(\mathcal{Z}_T$, $\mathcal{T})$ be fixed as in \eqref{def-zt}. Then, a set $\wtilde{\K}\subset\mathcal{Z}_T$ is $\mathcal{T} - $relatively compact if the following three conditions hold:
		\begin{itemize}
			\item[(i)] \begin{equation}
				\sup_{u\in\wtilde{\K}}\sup_{t\in[0,T]}\|u(t)\|_{\Vp}<\infty.
			\end{equation}
			\item[(ii)] $\wtilde{\K}$ is bounded in the space  $L^2(0,T;D(A))$, i.e., 
			\begin{equation}
				\sup_{u\in\wtilde{\K}}\bigg(\int_0^T\|\Delta u(t)\|_{L^2(\bO)}^2dt \bigg) < \infty.
			\end{equation}
			\item[(iii)] \begin{equation}
				\lim_{\delta\to 0}\sup_{u\in\wtilde{\K}}\sup_{s,t\in[0,T],|t-s|\leq\delta}\|u(t) -u(s)\|_{L^2(\bO)} = 0.
			\end{equation}
		\end{itemize}

[Conjecture BigConj of arXiv:2504.18739, 'discrete analogues of second-order Riesz transforms'] For all $j, k=1,2,\ldots,d$, $j\neq k$, 
\begin{align}
    \|\mathcal{R}^{(jk)}\|_{\ell^p\to\ell^p}
    =\|R_{\mathrm{dis}}^{(jk)}\|_{\ell^p\to\ell^p}
    =\|R^{(jk)}\|_{L^p\to L^p}, 
\end{align} 
and
\begin{align}
    \|\mathcal{R}^{(jj)}-\mathcal{R}^{(kk)}\|_{\ell^p\to\ell^p}
    =\|R_{\mathrm{dis}}^{(jj)}-R_{\mathrm{dis}}^{(kk)}\|_{\ell^p\to\ell^p}
    =\|R^{(jj)}-R^{(kk)}\|_{L^p\to L^p}. 
\end{align}
For all $j=1, 2, \dots d$, 
\begin{align}
    \|\mathcal{R}^{(jj)}\|_{\ell^p\to\ell^p}
    =\|R_{\mathrm{dis}}^{(jj)}\|_{\ell^p\to\ell^p}
    =\|R^{(jj)}\|_{L^p\to L^p}.
\end{align} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem 3 of arXiv:2606.24485, 'On the convex hull of a planar Brownian bridge with a random Gaussian endpoint'] For $0\le \sigma<1$,
	\begin{equation}
		\E [M_\sigma]
		=
		\frac{1}{\sqrt{2\pi}}
		\ob{\sigma+\frac{\arccos\sigma}{\sqrt{1-\sigma^2}}}.
	\end{equation}
	At $\sigma=1$, the continuous extension is
	\begin{equation}
		\E [M_1]=\sqrt{\frac{2}{\pi}}.
	\end{equation}

[Lemma 20 of arXiv:2506.19064, 'Variational formula for the logarithmic potential of free additive convolutions'] Let $\mu,\nu$ be compactly supported probability measures on $\mathbb{R}$.
    \begin{enumerate}[label=\alph*)]
        \item  If $z \ge z^*_{\mu\boxplus\nu}$, then $E_{\mu,\nu,z}$ is strictly decreasing in $\mathcal{E}_{\mu,\nu,z}\cap(0,g^*_{\mu \boxplus \nu})$.

        \item  If $z<z^*_{\mu\boxplus\nu}$, then $E_{\mu,\nu,z}$ has exactly one critical point in $\mathcal{E}_{\mu,\nu,z}\cap(0,g^*_{\mu \boxplus \nu})$, which is a non-degenerate local minimum, and the global minimum inside that set. Furthermore, the minimum equals
        \begin{equation}
            g = G_{\muplusnu}(z) \in \hat{\mathcal{E}}_{\mu,\nu,z} \cap (0,g^*_{\mu \boxplus \nu}).
        \end{equation}
        In particular,
        \begin{equation}
            \inf_{g \in \hat{\mathcal{E}}_{\mu,\nu,z} \cap (0,g^*_{\mu\boxplus\nu})}
            E_{\mu,\nu,z}(g)
            =
            \inf_{
                g
                \in
                \mathcal{E}_{\mu,\nu,z}            
                \cap(0,g^*_{\mu \boxplus \nu})
            }
            E_{\mu,\nu,z}(g)
            =
            E_{\mu,\nu,z}(G_{\muplusnu}(z)).
        \end{equation}
    \end{enumerate}

