\begin{eqnarray*}
:\Phi^{n}_{\varepsilon}:(z)&=&
Q_{n}(\nu_{A,\varepsilon}(z),V_{A,\varepsilon}(z)) +
Q_{n}(\Phi_{D\setminus A,\varepsilon}(z),G_{D,\varepsilon,\varepsilon}(z,z))
\\
&&-\ind_{n \text{ even}}(-1)^{n/2}
\dfrac{n!}{2^{n/2} (n/2)!}
V_{A,\varepsilon}(z)^{n/2}
\\&& +
\sum_{\substack{0\leq j\leq n-1\\0\leq k <\lfloor j/2\rfloor}}
(-1)^{k}\dfrac{n!}{2^{k} (n-j)! k! (j-2k)!}
V_{A,\varepsilon}(z)^{k}
\nu_{A,\varepsilon}(z)^{n-j}
\,
:\Phi_{D\setminus A,\varepsilon}^{j-2k}:(z).
\end{eqnarray*}

