body:
[Lemma lem-correspondence of arXiv:2411.12623, 'Random signed measures'] There exists a one-to-one almost sure correspondence between a purely atomic random signed measures $\xi$ and a marked signed point process on $\mathcal{S}$, $N_\xi$ say, satisfying
	\begin{equation}
		\int_{A\times \mathbb{R}\setminus\{0\}} |s|N_{\xi}(ds\times dx)<\infty\quad\textnormal{a.s.}
	\end{equation}
	for every $A\in\hat{\mathcal{S}}$; the correspondence is the following: almost surely we have that for every $A\in\hat{\mathcal{S}}$ and every $B\in \mathcal{B} (\mathbb{R}\setminus\{0\})$ such that $0\notin\bar{B}$
	\begin{equation}
		\xi(A)=	\int_{A\times \mathbb{R}\setminus\{0\}} sN_{\xi}(ds\times dx)
	\end{equation}
	and
	\begin{equation}
		N_{\xi}(A\times B)=\lim\limits_{\varepsilon\to 0}\lim\limits_{n\to\infty}\sum_{j}\delta_{\xi(A_{nj})}(B_{\varepsilon}),\quad\text{for $B$ open,}
	\end{equation}
	\begin{equation}
		N_{\xi}(A\times B)=\lim\limits_{\varepsilon\to 0}\lim\limits_{n\to\infty}\sum_{j}\delta_{\xi(A_{nj})}(B^{\varepsilon}),\quad\text{for $B$ closed,}
	\end{equation}
	where $(A_{nj})$ is a dissection system of measurable subsets of $A$. Moreover,  almost surely we have that for every $A\in\hat{\mathcal{S}}$ 
	\begin{equation*}
		\xi_+(A)=	\int_{A\times (0,\infty)} sN_{\xi}(ds\times dx),\quad\text{and}\quad 	\xi_-(A)=	-\int_{A\times (-\infty,0)} sN_{\xi}(ds\times dx)
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 22 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[proposition]{prop:LDP}
   Assume \cref{hp:noise} and fix $R>0$. The family of processes $\Psi^{\tau,\psi_0},\ \tau\in (0,1),\ \psi_0\in \mathcal{E}_0$, solving \eqref{eq:simplified_model} with initial condition $\psi_0$, satisfies a Laplace principle on $\mathcal{E}$ uniformly on compact subsets of $\mathcal E_0$, at scale $\tau$ (equivalently, with speed $1/\tau$), with rate function
   \begin{align}
       I_{\psi_0}(\psi):=\inf\bigg\{\frac{1}{2}\|f\|_{L^2(0,T;\mathcal{H}_{0,1})}^2+&\frac{1}{2}\|g\|^2_{L^2(0,T;\mathcal{H}_{0,2})}:\notag\\ &\hspace{-1cm} f\in L^2(0,T;\mathcal{H}_{0,1}),\ g\in L^2(0,T;\mathcal{H}_{0,2}),\ \psi=\psi^{\psi_0,f,g} \bigg\}.
   \end{align}
In particular, $\Psi^{\tau,\psi_0}$ also satisfies a large-deviation principle on $\mathcal{E}$ uniformly on compact subsets of $\mathcal E_0$, with speed $1/\tau$ and the same rate function. (Proof in the paper; no proof environment follows the statement in the TeX.)

