[Definition def:liftdiffusion of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $P_t = \exp(tL)$ and $\hat{P}_t = \exp(t \hat{L})$ be the Markov diffusion processes defined as above. We say that $\hat{P}_t$ is a lift of $P_t$ if
    it holds that $\dom(L) \subset \dom(\hat{L})$, and 
        \begin{align} 
            \langle f \circ \pi, \hat{L} (g \circ \pi)  \rangle_{L^2(\hat{\mu})} = 0\,,\quad \forall f \in L^2(\mathcal{S},\mu)\,,\ g \circ \pi \in \dom(\hat{L})\,,
        \end{align}
    and for a positive bounded operator $\mathsf{S}: L^2(\mathcal{S}, \mu)^\perp \to L^2(\mathcal{S}, \mu)^\perp$, 
    \begin{align} 
        \langle \hat{L}(f \circ \pi), \mathsf{S}\, \hat{L} (g \circ \pi)  \rangle_{L^2(\hat{\mu})} = - \langle f, L g  \rangle_{L^2(\mu)}\,, \quad \forall f \circ \pi \in \dom(\hat{L})\,,\ g \in \dom (L)\,.
    \end{align}

[Theorem finite of arXiv:2412.04396, 'Superdiffusive Scaling Limits for the Symmetric\\ Exclusion Process with Slow Bonds'] Fix $T>0$ and speed up the process by $k^2n^{1+\beta}$.
	Assume that $k$ is fixed.  Then, for every $t\in[0,T]$, the sequence of random measures $\pi^n_{t}$ converges in probability to the measure
	\begin{equation}
		\pi_t(du)\;=\;\sum_{i=0}^{k-1}\rho_t(i)\delta_{i/k}(du)
	\end{equation}
	on the continuous torus ${\mathbb T}$, where $\rho_t(\cdot)$ is the unique solution of the following discrete heat equation:
	\begin{equation}
		\begin{cases}
			\partial_t\rho_t(i)=\alpha \Delta_k\rho_t(i), \quad i\in {\mathbb T}_k, \vspace{4pt}\\
			\rho_0(i)=k\int_{i/k}^{(i+1)/k}\gamma(u)du,  \quad i\in {\mathbb T}_k
		\end{cases}
	\end{equation}
	where $\Delta_k$ is the discrete Laplacian, i.e., $\Delta_k\rho_t(i):= k^2\big[ \rho_t(i+1)+\rho_t(i-1)-2\rho_t(i)\big]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition lem:29 of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Suppose  that there exist $\lambda, C>0$ and $r\in {\mathbb N}$  such that for every $\mu \in 
		\mathcal{P}_{p}({\mathbb R}^d)$and every $k>r$
		\begin{equation}  
			\qquad\qquad\qquad \left\Vert \Theta_{k}(\mu )\right\Vert _{p}^{p}\leq
			(1-\lambda \gamma _{k})\left\Vert \mu \right\Vert _{p}^{p}+C\gamma _{k}.
		\end{equation}
		Then for every $k\geq r$,
		\begin{equation*}  
			{\mathbb{E}}[|X_{r,k}(X)|^p]=\left\Vert \Theta_{t_{r},t_{k}}^{\pi
			}(\mu)\right\Vert _{p}^p\leq e^{-\lambda(t_{k}-t_r)}\left\Vert \mu\right\Vert
			_{p}^p+C_{\lambda}.
		\end{equation*}
		Here $\mathcal{L}(X)=\mu$ and $C_{\lambda}$ is a constant depending on $\lambda$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Suppose that $\E[\omega_e] = 0$ and $\beta \geq 0$. If almost surely
    \begin{equation} 
        \Big| F^\omega_n(\beta) - \E\big[F^\omega_n(\beta)\big] \Big| \xrightarrow{n \to \infty} 0,
    \end{equation}
    then almost surely the infinite volume free energy
    \begin{equation*}
        F(\beta) := \limn F^\omega_n(\beta) = \limn \E \big[  F^\omega_n(\beta)\big].
    \end{equation*}
    exists and is finite.

