[Defi 2 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $0\leq s<T<\infty$. 
    A probability $\eta\in \mathcal{P}\left(C([s,T];\mathbb{R}^d))\right)$ is called a solution to the canonical martingale problem (canonical MP) associated to $\left({\sf L}_t\right)_{t\in [s,T]}$, with initial distribution $\nu_s\in \mathcal{P}(\mathbb{R}^d)$ if
    \begin{equation*}
        \int_s^T\int_{B(0,R)} \|b(t,x)\|+\|a(t,x)\| \; \eta_t(dx) dt <\infty, \quad R>0,
    \end{equation*}
    and for all $f\in C_c^{1,2}((s,T)\times \mathbb{R}^d)$ the process $(M(t))_{t\in [s,T]}$ given by
    \begin{equation*}
        M(t):=f(t,\Pi_s(t))-f(s,\Pi_s(s))-\int_s^t\overline{{\sf L}}f(r,\Pi_s(r))\;dr, \quad t\in [s,T]
    \end{equation*}
    is an $\left(\mathcal{F}_s(t)\right)$-martingale with respect to $\eta$, where $\mathcal{F}_s(t):=\sigma\left(\Pi_s(r),s\leq r\leq t\right), t\in [s,T]$.

[Theorem sec2-thm.2 of arXiv:2602.04303, '\Large\textbf{Strong solutions to SDEs with singular drifts driven by fractional Brownian '] Assume $C>0$ and that the sequence of $\mathcal{F}_T$-measurable random variables $\{F_n\}_{n=1}^\infty\subset L^2(\Omega)$ satisfies the following three conditions:
		\begin{align*}
			&\sup_n\mathbb{E}\Vert F_n\Vert^2\leq C,\\
			&\sup_n\int_0^T\mathbb{E}\Vert\boldsymbol{\mathrm{D}}_{\theta}F_n\Vert^2\mathrm{d} \theta\leq C,
		\end{align*}
		and there exists a constant $\beta>0$ such that
		\begin{equation*}
			\sup_n\int_0^T\int_0^T\frac{\mathbb{E}\Vert\boldsymbol{\mathrm{D}}_{\theta}F_n-\boldsymbol{\mathrm{D}}_{\theta'}F_n\Vert^2}{|\theta-\theta'|^{1+2\beta}}\mathrm{d} \theta\leq C.
		\end{equation*}
		Then, the sequence $\{F_n\}_{n=1}^\infty$ is relatively compact in $L^2(\Omega)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:RelaxationTimeInduced of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] We can bound the relaxation time $t_{\textup{rel}}^{\textup{ind},+}$ of the additive reversibilisation $\mathbf{X}^{\textup{ind},+}$ of the induced chain $\mathbf{X}^{\textup{ind}}$ by
    \begin{equation}
            t_{\textup{rel}}^{\textup{ind},+} \leqslant C_0n/\Phi_{\ast},
        \end{equation}
     where $C_0$ is a constant which depends only on $d$, $m$, and $C$.

