[Definition def:Bnset of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Define the set  
\begin{equation*} 

    \mathcal A_3 = \{ 1,2,3,12,23,123 \}.
\end{equation*} 
For $\mathbf{n}=(n_1, n_2, n_3)\in {\mathbb N}^3$, define $\mathcal S_{\mb{n}}$ to be the set of lists ${\boldsymbol \sigma}=\sigma_1\sigma_2\cdots \sigma_k$ of elements $\sigma_j\in \mathcal A_3$ such that, for each $i=1,2,3$, the total
number of times $i$ appears in any of $\sigma_1, \sigma_2, \cdots,  \sigma_k$ is equal to $n_i$. We denote
\begin{equation*}
    |{\boldsymbol \sigma}|=k \qquad \text{if ${\boldsymbol \sigma}= \sigma_1\sigma_2\cdots \sigma_k$.}
\end{equation*}
Let $\mathcal{S}=\cup_{\mathbf{n}\in {\mathbb N}^3} \mathcal S_{\mb{n}}$. 
The type of a list ${\boldsymbol \sigma}\in \mathcal{S}$ is the vector 
\begin{equation} 
    \type({\boldsymbol \sigma}) = (a_{123}, a_{12}, a_{23}, a_1, a_2, a_3) \in {\mathbb N}_0^6
\end{equation}
where $a_*$ is the number of $\sigma_i$ in $\boldsymbol \sigma = \sigma_1 \cdots \sigma_k$ such that $\sigma_i = *$ for each $* \in \mathcal A_3$.

[Lemma 45 of arXiv:2606.17859, 'Full $\Gamma-$expansion for the level-two large deviation rate functionals of non-reversib'] Fix $1\leq p\leq \mf q$. Then, for every $x\in \bb T$
\begin{equation*}
\bb P_{x}^\epsilon\big[\, \tau(m_p^-(x))< \tau(m_p^+(x)\,\big]
= \frac{\int_{m_p^{-,*}(x)}^{x^{*}}e^{S(y)/\epsilon}\,dy}
{\int_{m_p^{-,*}(x)}^{m_p^{+,*}(x)}e^{S(y)/\epsilon}\,dy}\,\cdot
\end{equation*}
In particular, for every $k\in S_p$,
$x^-\in (m_{p,k}^+, \sigma_{k,k+1}^{p,-})$, and
$x^+\in (\sigma_{k,k+1}^{p,+}, m_{p,k+1}^-)$, there exist positive
constant $C_{x^{\pm}}$, $h_{x^{\pm}}$ which depend on $x^{\pm}$, but
not on $\epsilon$, such that
\begin{equation*}
\bb P_{x^-}^\epsilon\big[\, \tau(m_{p,k+1}^-)<\tau(m_{p,k}^+)\,\big]
\leq \frac{C_{x^-}}{\sqrt{\epsilon}}e^{-h_{x^-}/\epsilon}\,,
\quad  \bb P_{x^+}^\epsilon \big[\, \tau(m_{p,k}^-)<\tau(m_{p,k+1}^+)\,\big]
\leq \frac{C_{x^{+}}}{\sqrt{\epsilon}}e^{- h_{x^+}/\epsilon}
\end{equation*}
for all $\epsilon>0$.

