[Theorem 3.01 of arXiv:2512.12902, 'Non-equilibrium fluctuations for the \\stirring process with births and deaths'] There is  $c$ so that for all $\epsilon>0$
                    \begin{equation}

\sup_{|x_1-x_2|=1} \mathbb{P}_\epsilon\big[\tau_{x_1,x_2} \geq t\big] \leq \frac{c}{(\epsilon^{-2}t)^{1/2}+1}.
             \end{equation}
Moreover, given any $T>0$, for any $\zeta>0$ and $k\ge 1$ there is
$c$ so that for all $t\leq T$ and  for all $\epsilon>0$
                      \begin{equation}

\sup_{x_1,x_2} \mathbb{P}_\epsilon\big[N_{x_1,x_2,t} \geq (\epsilon^{-2}t)^{1/2+\zeta}\big] \le  c (\epsilon^{-2}t)^{-k}.
             \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2606.16259, 'Super-Arrhenius relaxation of the triangular plaquette model in any dimension'] There exist $\alpha_2>0$ and $n_2\in\mathbb N$ such that, for any $n\geqslant n_2$, there exists $w\in\{a,x^{\pm1},y^{\pm1}\}$ with the following properties:
  \begin{itemize}
      \item it represents the identity in $\Gamma$;
      \item it has configuration diameter at most $n$;
      \item it contains $L$ letters $a$ or $a^{-1}$;
      \item its $a$-filling length function $\lambda_a(w)$ is at least $L+n^{\alpha_2}$.\qed
   \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 12 of arXiv:2506.08775, 'Markovian multivariate Hawkes population processes: Efficient evaluation of moments'] Under Assumption \ref{ass_sym}, for a random vector $\bm{X}$, we have as $\theta \uparrow 1$
\begin{align*}
    (1-\theta)\bm{\lambda} \overset{d}{\to} \bm{X},
\end{align*}
where each marginal $X_i \sim \Gamma(\sigma\overline{\lambda}, \sigma)$ and $\text{\rm Cov}(X_i,X_j) = \overline{\lambda} /\sigma$ for any $i,j\in[d]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2609.01333, '2609.01333'] There exists $\gamma_* \in \big(0, \, \frac{1}{2\pi} \tfrac{1}{\frac{1}{\kappa} - \frac{1}{\sqrt{\kappa^2+1}}}\big)$
such that the following assertions hold.
\begin{itemize}
\item For every $\gamma\in (0,\gamma_*)$  and $\lambda>0$ the sequence $k\mapsto \sigma_{\lambda,\gamma}(k)$ is strictly increasing.
\item
For each $\gamma\in (0,\gamma_*)$ there exists a unique parameter $\lambda _*=\lambda _*(\gamma)>0$  satisfying

\begin{align}
\sigma_{\lambda _*(\gamma),\gamma}(1)=0.
\end{align}
In particular, it satisfies
\begin{align}
\sigma_{\lambda _*(\gamma),\gamma}(0)<0=\sigma_{\lambda _*(\gamma),\gamma}(1)<\sigma_{\lambda _*(\gamma),\gamma}(k)  \quad \textrm{ for all $k\geq 2$}
\end{align}

\end{itemize}

