body:
[Theorem thm: Heat Kernel Bound of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Let $M$ be a Hadamard manifold.

    Suppose $t>0,x,y\in M$. If $\sec_M\leq -K_1<0$, the heat kernel $P_t(x,y)$ satisfies \begin{equation}
      P_t(x,y)\leq C h(K_1t,\sqrt{K_1}d(x,y))
    \end{equation}
    where $C>0$ depends on $n$ and $K_1$. Similarly, if $\sec_M\geq-K_2>-\infty$, we have \begin{equation}
        P_t(x,y)\geq ch(K_2t,\sqrt{K_2}d(x,y))
    \end{equation}
    where $c>0$ depends on $n$ and $K_2$.

[Lem lemma:M-contraction-map of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] Let $K_* : \mathcal{P}_{\mathbb{Z}^d} \rightarrow \mathbb{N}$ be a plaquette assignment and $M_* \geq 1$ an integer.
For any $\lambda \in (0, 1/2)$ and $\gamma \in (0, \infty)$, we have that
\begin{align}
	\|M f\|_{\lambda, \gamma} &\leq \frac{\lambda}{1-2\lambda} + (4\lambda + 4d \upbeta \gamma \lambda^{-4}) \|f\|_{\lambda, \gamma},\qquad\forall f \in \Theta_{K_*, M_*}, 
\end{align}
where we recall that the norm $\|\cdot\|_{\lambda, \gamma}$ is defined using the parameters $K_*, M_*$, which we fixed. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition arf_prop of arXiv:2608.25513, 'Adaptive Regularization for Random Features: A Neighboring Early-Stopping Rule with Oracle'] Suppose Assumptions (ass1 of the paper)--(ass5 of the paper) hold. Let $0<\widetilde\lambda\leq\lambda\leq1$ satisfy
\begin{align}
\tilde{\lambda} \geq 4\kappa^2/|D| \ \text{and} \ \max\{{\cal U}_{D,\lambda,\delta},{\cal U}_{D,\tilde{\lambda},\delta} \}\leq 1/2,
\end{align} 
If the number of random features $M$ satisfies
\begin{align}
M\gtrsim 
\begin{cases}
c_{\mathrm{RF}}\widetilde\lambda^{-\alpha}\log\frac{384\kappa^3|D|}{\delta}, & 0<r<\frac12,\\
c_{\mathrm{RF}} \widetilde\lambda^{-[(2r-1)(1+\gamma-\alpha)+\alpha]}\log\frac{384\kappa^3|D|}{\delta}, & \frac12\leq r\leq1,
\end{cases}
\end{align}
then with probability at least $1-\delta$, there holds that
\begin{align}
\|(C_{M,D}+\lambda I)^{1/2}({\boldsymbol{u}}_{M,D,\lambda}-{\boldsymbol{u}}_{M,D,\widetilde\lambda})\|_2
\leq C_2\frac{\lambda-\widetilde\lambda}{\widetilde\lambda}
\left({\cal W}_{M,D,\lambda}+\widetilde\lambda^r\right)\log^2\frac{16}{\delta},
\end{align}
where $c_{\mathrm{RF}}, C_2$ are some positive constants independent of $M$, $\lambda$, $\tilde{\lambda}$, $|D|$ and $\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:pureweak-nonstrong2 of arXiv:2507.14676, 'On the critical parameters of branching random walks'] {cf:BZ17}}]  
Let $(X,K)$ and $(X,K^*)$ two irreducible continuous-time BRWs such that $k_{xy}=k^*_{xy}$ for all $x \in X \setminus A$
where $A$ is a finite nonempty set.  Suppose that $\lambda^*_w<\lambda_w < \lambda_s$, and let $B\subseteq X$ be nonempty.

Then, for the BRW $(X,K^*)$
\begin{enumerate} 
\item if $\lambda \le \lambda_w^*$ there is a.s.~extinction in $B$;

\item if $\lambda \in (\lambda_w^*, \lambda_w)$ there is strong survival in $B$; 

\item if $\lambda =\lambda_w$ and $(X,K)$ dies out globally, then there is strong survival in $B$;

conversely, if $(X,K)$ survives globally and $B$ is finite; there is non-strong survival in $B$;

\item if $\lambda \in (\lambda_w, \lambda_s]$ and $B$ is finite, then

there is non-strong survival in $B$;

\item if $\lambda > \lambda_s$ and $B$ is finite, then survival is strong (resp.~non-strong) in $B$

if and only if 
the same holds for $(X,K)$.  
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:HRmixing of arXiv:2412.07643, 'Ballistic Convergence in Hit-and-Run Monte Carlo and a Coordinate-free Randomized Kaczmarz'] Let $\varepsilon>0$, $\nu\in\mathcal P(\mathbb R^d)$ and $\rho$ as defined in (equation eq:rate of the paper).
Then, there exist absolute constants $C,C'>0$ such that the mixing time of Hit-and-Run with respect to the Gaussian measure $\gamma^\mathcal{C}$ starting from $\nu$ to accuracy $\varepsilon$ satisfies
\begin{equation}
\begin{aligned}
    \tau_{\operatorname{mix}}(\varepsilon,\nu)\ &=\ \inf\bigr\{ n \in \mathbb{N}\,:\,\mathcal \mathsf{TV}\bigr(\nu\pi_{\mathrm{H\&R}}^n,\,\gamma^\mathcal{C}\bigr)\leq \varepsilon \bigr\} \\
    &\leq\  C\,\rho^{-1}\,\log\Bigr(C'\max(\kappa,M,m^{-1})\,d\,\varepsilon^{-1}\,\boldsymbol{\mathcal{W}}^2_{\mathcal{C}^{-1/2}}(\gamma^{\mathcal{C}}, \nu)\Bigr)
\end{aligned}
\end{equation}
where $\kappa,M,m$ denote condition number, largest and smallest eigenvalue of $\mathcal{C}^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $\XX$ be a quasi-normed space and let $\emptyset\ne\SC\subset \XX$.
  We then say that $\SC$ satisfies {\ConditionZetaText}
  if there exist constants $C, \alpha > 0$ satisfying
  \begin{equation}
    \sum_{n=1}^{\infty} \frac{x_n}{C \cdot n^\alpha}
    \in \SC
    \quad \text{whenever} \quad x_1,x_2,\dots \in \SC
    .

    \tag{$\zeta$}
  \end{equation}
  More precisely, we then say that $\SC$ satisfies \ConditionZetaTextAlphaC{(\alpha,C)}.

[Theorem 55 (Low-endpoint all-cut recovery) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $m\ge1$, $1\le r\le2$, and $1\le p<\infty$.  There are constants
$0<a_{m,p,r}\le b_{m,p,r}<\infty$, depending only on the displayed
parameters, such that every $K\in\mathfrak T_{m,r}^{\Sigma}$ satisfies
\begin{equation}

 a_{m,p,r}\norm K_{\mathfrak T_{m,r}^{\Sigma}}
 \le\norm{\cT_K^{(m)}}_{L^p(\Omega;\Sch_r)}
 \le b_{m,p,r}\norm K_{\mathfrak T_{m,r}^{\Sigma}}.
\end{equation}
The evaluation is a Banach-space isomorphism onto a closed subspace.
At $r=2$ and $p=2$, both constants may be taken equal to one.

[Definition def:entropies of arXiv:2411.16913, 'Entropies of the Poisson distribution as functions of intensity: ``normal'' and ``anomalou'] Let $\mathtt{p}:=\{p_i, i \geq 0\}$ be a non-degenerate discrete probability distribution.
\begin{enumerate}
\item 
The Shannon entropy of $\mathtt{p}$ is given by the formula
\begin{equation}
\mathbf H_{SH} (\mathtt{p}) =-\sum_{i = 0}^{\infty}  p_i\log {p_i}  =  \sum_{i = 0}^{\infty}   p_i \log\left(\frac{1}{p_i}\right)  .
\end{equation}
\item
The R\'{e}nyi entropy with parameter $\alpha>0,$ $\alpha\ne1$ of $\mathtt{p}$ is given by the formula
\begin{equation}
\mathbf H_{R}(\alpha, \mathtt{p}) = \frac{1}{1-\alpha} \log
\left(\sum_{i=0}^\infty p_i^{\alpha}\right).
\end{equation}

 \item  The generalized R\'enyi entropy with parameter $\alpha > 0$ of $\mathtt{p}$ is given by the formula
    \begin{equation}
    \mathbf H_{GR}(\alpha, \mathtt{p}) = - \frac{\sum_{i = 0}^{\infty} p_i^\alpha   \log{p_i}  }{\sum_{i = 0}^{\infty} p_i^\alpha}
    = \frac{\sum_{i = 0}^{\infty} p_i^\alpha   \log{\frac{1}{p_i}}  }{\sum_{i = 0}^{\infty} p_i^\alpha}.
    \end{equation}

\item
    The generalized R\'enyi entropy with parameters $\alpha > 0$, $\beta > 0$, $\alpha \neq \beta$ of $\mathtt{p}$ is given by the formula
    \begin{equation}
    \mathbf H_{GR}(\alpha, \beta, \mathtt{p}) = \frac{1}{\beta - \alpha}  \log\left(\frac{\sum_{i = 0}^{\infty} p_i^\alpha }{\sum_{i = 0}^{\infty} p_i^\beta}\right).
    \end{equation}

\item
    The Tsallis entropy with parameter $\alpha > 0$, $\alpha \neq 1$ of $\mathtt{p}$ is given by the formula 
    \begin{equation}
    \mathbf H_T(\alpha, \mathtt{p}) = \frac{1}{1-\alpha} \left( \sum_{i = 0}^{\infty} p_i^\alpha - 1 \right).
    \end{equation}

\item
    The Sharma--Mittal entropy with parameters $\alpha > 0$, $\beta > 0$, $\alpha \neq 1$, $\beta \neq 1 $ of $\mathtt{p}$ is given by the formula
    \begin{equation}
    \mathbf H_{SM}(\alpha, \beta, \mathtt{p}) = \frac{1}{1-\beta} \left( \left( \sum_{i = 0}^{\infty} p_i^\alpha \right)^{\frac{1- \beta}{1 - \alpha}} - 1 \right).
    \end{equation}
\end{enumerate}

[Lemma 30 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Fix $\theta \in (0,\xi_c / 8)$. Then, there exists $\xi_0 \in (0,\xi_c)$ depending only on $\theta$ and a choice of the functions $b,M$ (depending only on $\theta$) such that the following is true for all $\xi \in [\xi_0,\xi_c]$. Fix $\varepsilon \in (0,1)$ and a bounded open set $U \subseteq \CC$. Then, there exists deterministic constant $C>0$ (depending only on $\varepsilon,\theta$, and $U$) such that with probability at least $1-\varepsilon$, we have that
\begin{equation*}
    \widetilde{D}_h^{\xi}(\partial B_{e^{-n-50}}(z) , \partial B_{e^{-n/2 - 1}}(z)) \leq C n^{-\theta}\,\,\text{for all}\,\, n \in \NN,z \in U.
\end{equation*}

