[Lemma priori-4 of arXiv:2609.01488, 'Stabilization by a background magnetic field: global well-posedness of the full compressib'] Assume that all the conditions of Lemma (priori-combine of the paper) hold, and that the integers $M,N$ satisfy $N\geq M+2(r+1)$. Then there is a positive constant $\epsilon_0<1$, depending only on $\mathbb T^3$, $|\mathbf n|$, $M$, $N$, $\mu$, $\lambda$, $\gamma$, $\bar P$, $\underline{\rho}^{-1}$, $\bar\rho$, $M_0$, $r$ and $c$, with the following property. If
\begin{align}
 (1+\|\rho_0\|_M)\sup_{t\in[0,T]}\|(\mathbf u,p,\mathbf h)\|_{N}^{\frac{2(r+1)}{N-M+r+1}}+ M_{\rho}^{\frac{N-M+r+1}{N-M}}\sup_{t\in[0,T]}\|(\mathbf u,p,\mathbf h)\|_{N}^{\frac{2(r+1)}{N-M}}\leq\eta_0\end{align}
holds for some $\eta_0\in(0,\epsilon_0]$, then the following estimates hold:
\begin{equation}\begin{split}
\|(\mathbf u,p,\mathbf h)\|^2_M\leq \Big(\frac{r+1}{N-M}t+\big(B_4M_\rho\|(\mathbf u_0,p_0,\mathbf h_0)\|^2_M\big)^{-\frac{r+1}{N-M}}\Big)^{-\frac{N-M}{r+1}},
\end{split}\end{equation}
and
\begin{align}
\sup_{t\in[0,T]}&\beta(t)\|(\mathbf u,p,\mathbf h)\|^2_M+\int_0^T\beta(t)\Big(\frac{1}{2}\underline\rho\|\mathbf u_t\|^2_{M-1}+\frac12\|\mathbf u\|_{M+1}^2+\frac{1}{2}\delta_0\|(p,\mathbf h)\|^2_{M-1-r}\Big)dt\nonumber\\
&\lesssim M_\rho\|(\mathbf u_0,p_0,\mathbf h_0)\|^2_M,
\end{align}
where  $\beta(t):=\big(\frac{r+1}{N-M}\|(\mathbf u_0,p_0,\mathbf h_0)\|_M^{\frac{2r+2}{N-M}}t+1\big)^{\frac{N-M-1}{r+1}}$  and the  two positive  constants  $B_4,\delta_0$ are defined as in Lemma (priori-combine of the paper).

