[Definition def2.5 of arXiv:2411.13266, '\bf A new maximal regularity for parabolic equations and an application'] An increasing continuous  function $\rho: \mathbb{R}_+\rightarrow \mathbb{R}_+$  is called  a Dini function if
\begin{eqnarray*}
\int\limits_0^1\frac{\rho(r)}{r}dr<+\infty.
\end{eqnarray*}
A measurable function $\rho: \mathbb{R}_+\rightarrow \mathbb{R}_+$  is called a slowly varying function at zero  (in Karamata's sense [BGT]) if for
all $\upsilon>0$,
\begin{eqnarray*}
\lim_{r\rightarrow 0}\frac{\rho(\upsilon r)}{\rho(r)}=1.
\end{eqnarray*}
A measurable function $h:{\mathbb R}^n\rightarrow \mathbb{R}$  is said to be locally Dini continuous if there is a Dini function~$\rho$ such that
\begin{eqnarray*}
|h(x)-h(y)|\leqslant \rho(|x-y|), \ \ x,y\in {\mathbb R}^n, \ |x-y|\leqslant 1.
\end{eqnarray*}

[Lem 75 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Setting $\mathsf{t}' = \mathsf{t}/2$, we have w.o.p. that, for any $z \in \mathfrak{X}$ and $t \in [\mathsf{t}', N^5]$,
			\begin{flalign}

				H_t (z) \le \mathcal{H}_{q'} (z) + N^{\delta-1}, \quad \text{if either $q-q' \le \mathtt{d}_z^{-1/3} N^{A\delta-2/3}$ or $\mathtt{d}_z^{1/2} \mathtt{e}_{z;q'}^{3/2} \ge N^{4A\delta-1}$.}
			\end{flalign}

[Lemma 40 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Assume $A>A_c(N)$, with $A_c(N)$ defined in
  \cref{eq:fixed-width-critical}. Then there is a unique
  $\beta_{A,N}\in(0,N)$ satisfying
  \begin{equation}
    r_{A,N}(\beta_{A,N})=1.
  \end{equation}
  Equivalently, $\beta_{A,N}$ is the unique positive solution of
  \begin{equation}
    A^{-\beta}
    N^{\beta/2}
    2^{-\beta/2}
    \frac{\Gamma((N-\beta)/2)}{\Gamma(N/2)}
    =
    1,
    \qquad 0<\beta<N.
