body:
[Proposition 47 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $(b,i) \in \mathbb{R}^d \times \{0,1\}$ and consider an $\text{ooBM}(c, \Tilde{c})$, $(U_r, I_r)_{r \geq 0}$, started from $(b,i)$. Then, for any continuous bounded function $\Phi: \mathbb{R}^d \rightarrow [0,\infty)$ we have 
    \begin{equation*}
        \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})} (\langle \mathcal{Y}^{(\rm a)}_s, \Phi \rangle ) = \int_{b \in \mathbb{R}^d} E^{\%}_{(b,1)}[\Phi(U_s)\mathbbm{1}_{I_s=1}] \mu_{\rm a}(db) + \int_{b \in \mathbb{R}^d} E^{\%}_{(b,0)}[\Phi(U_s)\mathbbm{1}_{I_s = 1}] \mu_{\rm d}(db);
    \end{equation*}
    \begin{equation*}
        \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})} (\langle \mathcal{Y}^{(\rm d)}_s, \Phi \rangle ) = \int_{b \in \mathbb{R}^d} E^{\%}_{(b,1)}[\Phi(U_s)\mathbbm{1}_{I_s=0}] \mu_{\rm a}(db) + \int_{b \in \mathbb{R}^d} E^{\%}_{(b,0)}[\Phi(U_s)\mathbbm{1}_{I_s=0}] \mu_{\rm d}(db).
    \end{equation*}
    \begin{proof}
    We first consider the case $\gamma = 4$ and we deal with the active component. Recall from Definition \ref{definition oo snake} the on/off Brownian snake $\sum_{i \in I} \delta_{((b_i,s_i), f^i, x^i)}$ and also recall that $w^i$ denotes the Brownian component of the snake $x^i$. From Theorem \ref{theorem ooSBM ffd convergence} we have that
    \begin{equation*}
        \langle \mathcal{Y}^{(\rm a)}_s, \Phi \rangle = \sum_{i \in I: s_i<s} \int_{t=0}^{\sigma(f^i)} \Phi(\hat{w}^i_t)\ell^{\rm a}_{s, i}(dt)
    \end{equation*}
    and therefore we have
    \begin{equation*}
        \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})} (\langle \mathcal{Y}^{(\rm a)}_s, \Phi \rangle) = \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})} \Big(\sum_{i \in I: s_i<s} \int_{t=0}^{\sigma(f^i)} \Phi(\hat{w}^i_t)\ell^{\rm a}_{s, i}(dt)\Big).
    \end{equation*}
    By the compensation formula for Poisson random measures this is equal to 
    \begin{equation*}
            \int_{b \in \mathbb{R}^d} \mathbb{N}_{(b,0)}\Big(\int_{t=0}^{\sigma(f)} \Phi(\hat{W}_t)\ell^{\rm a}_s(dt)\Big) \mu_{\rm a}(db) + \int_{b \in \mathbb{R}^d} \int_{q=0}^s \mathbb{N}_{(b,q)}\Big(\int_{t=0}^{\sigma(f)} \Phi(\hat{W}_t)\ell^{\rm a}_s(dt)\Big) \nu_s(dq) \mu_{\rm d}(db)
        \end{equation*}
    where $\nu_s(dq) \coloneqq \mathbbm{1}_{0 \leq q \leq s}\Tilde{c}e^{-\Tilde{c}q}$. For the first excursion measure we can define $D = \mathbb{R}^d \times [0,\infty) \backslash \{s\}$ and set $\tau(\xi) = \inf\{y \geq 0: \xi_y \notin D\}$. Then by \eqref{equation local time general} from Lemma \ref{lemma snake exit open set general} we have, (recalling that $\xi =(B,S)$ and $\tau = H^{(s)}(\xi)$ and that the subordinator component in this case does not jump over the level $s$, meaning that $\tau < \infty$ iff $A^{(s)} = 1$) that
    \begin{equation}
        \mathbb{N}_{(b,0)}\Big(\int_{t=0}^{\sigma(f^i)} \Phi(\hat{W}_t)\ell^{\rm a}_s(dt)\Big) = E^\xi_{(b,0)}\Big[\Phi(B(\tau)) \mathbbm{1}_{\tau < \infty}\Big] = E^\xi_{(b,0)}\Big[\Phi(B(H^{(s)}(\xi)))\mathbbm{1}_{A^{(s)}(\xi) = 1}\Big].
    \end{equation}
    We have similar expressions for the other term and so we obtain
        \begin{multline*}
            \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})} (\langle \mathcal{Y}^{(\rm a)}_s, \Phi \rangle) = \int_{b \in \mathbb{R}^d} E^\xi_{(b,0)}[\Phi(B(H^{(s)}(\xi)))\mathbbm{1}_{A^{(s)}(\xi) = 1}] \mu_{\rm a}(db) \\ + \int_{b \in \mathbb{R}^d} \int_{s=0}^q E^{\xi}_{(b,q)}[\Phi(B(H^{(s)}(\xi)))\mathbbm{1}_{A^{(s)}(\xi) = 1}] \Tilde{c}e^{-\Tilde{c}q} dq \mu_{\rm d}(db);
        \end{multline*}
    For the dormant case (with $\gamma = 4$) we cannot immediately apply Lemma \ref{lemma snake exit open set general} as we did for the active case. As in Theorem \ref{theorem ooSBM ffd convergence} we can apply the same result with $D = \mathbb{R}^d \times (s,\infty)$ and obtain
    \begin{equation}
        \mathbb{N}_{(b,0)}\Big(\int_{t=0}^{\sigma(f^i)} \Phi(\hat{W}_t)\ell_s(dt)\Big) = E^\xi_{(b,0)}\Big[\Phi(B(\tau)) \mathbbm{1}_{\tau < \infty}\Big] = E^\xi_{(b,0)}\Big[\Phi(B(H^{(s)}(\xi)))\Big],
    \end{equation}
    and it is the difference of  (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prp lemmaMeasureSLInv of arXiv:2607.29423, 'Schwarzian Field Theory at High Temperatures'] The measure $\widetilde{\mathscr{M}}_{\sigma^2}$ is invariant under post-composition by elements of $\mathrm{PSL}(2, \mathbb{R})$. 
In other words, for any $\psi \in \mathrm{PSL}(2, \mathbb{R})$ and Borel $A\subset \mathrm{Diff}^1(\mathbb{T})$ we have
\begin{equation}
  \widetilde{\mathscr{M}}_{\sigma^2}\big(\psi\circ A\big) = \widetilde{\mathscr{M}}_{\sigma^2}\big(A\big),
\end{equation}
where  $\psi\circ A \coloneqq \left\{\psi\circ \phi\, \big | \, \phi \in A \right\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Root law and multi-root factorization) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] Let $x,r\in V$. If $(S_t)_{t\geq0}$ is the ordinary evolving set in $V$ started from
$S_0=\{x\}$, then, we find :
\begin{equation}
  \Pp\bigl(\rho_q(x)=r\bigr)
  =\frac{\pi(r)}{\pi(x)}
  \Pp_{\{x\}}\bigl(r\in S_{T_q}\bigr).
\end{equation}
Consequently, one gets:
\begin{equation}
  \Ee\bigl[\pi(B_q(r))\bigr]=\pi(r).
\end{equation}
More generally, let $x_1,\ldots,x_k$ be distinct vertices of $V$ and set
\begin{equation*}
  A_0=\emptyset,
  \quad \forall i \in [[1,k]]\,,\quad 
  A_i=\{x_1,\ldots,x_i\},
  \quad \text{and}\quad 
  D_{i-1}=V\setminus A_{i-1}.
\end{equation*}
Then, one finds:
\begin{equation}
  \Pp(x_1,\ldots,x_k\in\Root)
  =\prod_{i=1}^k
  \Pp^{D_{i-1}}_{\{x_i\}}
  \bigl(x_i\in S_{T_q}^{D_{i-1}}\bigr).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:eigen-laplacian-detailed of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] On $W$,
\begin{align}
 \Delta_\omega^{\mathbb C}\ell_a={}&-
 \left(\sqrt{-1}\Lambda_\omega
 \bar\partial(g^{-1}\partial^{h_{\rm ref}}g)\right)^a_a\\
 &+\sum_b(e^{\ell_a-\ell_b}-1)C_{ab}
 -\sum_b(e^{\ell_b-\ell_a}-1)C_{ba}.\notag
\end{align}

[Cor sufficient-inequalities-new of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $({\mathbf{a}},{\mathbf{b}})$ be a $(d,0)$-non-degenerate weight pair with $d\geq 1$ and assume that $r=r_{d,0}({\mathbf{a}})$ is finite.
	Assume that the following inequalities hold for all $n\geq 0$, all $q\leq q'$ in $\{0,\dots,r-1\}$, and all $s \leq s'$ in $\{0,\dots,d-1\}$,
	\begin{equation}
	\frac{b_{nd+1}}{b_{(n-1)d+1}}
	\leq
	\frac{
		\PFComp{\shift{q' d+s'}{\mathbf{a}},{\mathbf{b}}}{nd+(d-s')}
	}{
		\PFComp{\shift{q' d+s'}{\mathbf{a}},{\mathbf{b}}}{(n-1)d+(d-s')}}
	\leq
	\frac{
		\PFComp{\shift{q d+s}{\mathbf{a}},{\mathbf{b}}}{nd+(d-s)}
	}{
		\PFComp{\shift{q d+s}{\mathbf{a}},{\mathbf{b}}}{(n-1)d+(d-s)}}
	\leq
	\frac{b_{(n+1)d+1}}{b_{nd+1}},
	\end{equation}
	where we omit the ill-defined inequality on the left when $n=0$.
	Then $({\mathbf{a}},{\mathbf{b}})$ is $(d,0)$-admissible, and $(\shift{qd+s}{\mathbf{a}},{\mathbf{b}})$ is $(d,\overline{d-s})$-admissible for every $s\in\{0,\dots,d-1\}$ and $q\in\{0,\dots,r-1\}$.

[Corollary gt_V_pm_rec of arXiv:2412.07258, 'Permuton limit of a generalization of the Mallows and $k$-card-minimum models'] For any $s \in (0,1)$ and $t \in \mathbb{R}$ we have
\begin{multline}
    \lim_{\alpha \to \infty} \frac{g_\alpha(s)}{g_\alpha\left( V_\alpha\Big(s+\frac{t}{\gamma(\alpha)}, s - \frac{t}{\gamma(\alpha)}\Big) \right)} = \\
 \lim_{\alpha \to \infty} \frac{g_\alpha(s)}
 {g_\alpha\left( s+ \frac{1}{\gamma(\alpha)} \frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)} \right)} \cdot \frac{g_\alpha\left( s+ \frac{1}{\gamma(\alpha)} \frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)} \right)}
 {g_\alpha\left( V_\alpha\Big(s+\frac{t}{\gamma(\alpha)}, s - \frac{t}{\gamma(\alpha)}\Big) \right)}
        \stackrel{(equation psi_exp of the paper), (equation ugly_logarithm of the paper)}{=} \\
    \lim_{\alpha \to \infty}
  \frac{g_\alpha(s)}{g_\alpha\left( s+ \frac{1}{\gamma(\alpha)} \frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)} \right)} \cdot 1 \stackrel{(equation psi_exp of the paper)}{=}  e^{\psi(s)t}+e^{-\psi(s)t}.
\end{multline}

