[Lemma 53 (One-cut low-endpoint evaluation) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $1\le r\le2$, let $S\subset[m]$, and let $K$ be algebraic.  Then
\begin{equation}

 \norm{\cT_K^{(m)}}_{L^2(\Omega;\Sch_r)}
 \le\norm{\Flat_S(K)}_{\Sch_r}.
\end{equation}
Consequently,
\begin{equation}

 \norm{\cT_K^{(m)}}_{L^2(\Omega;\Sch_r)}
 \le\norm K_{\mathfrak T_{m,r}^{\Sigma}}.
\end{equation}

[Lem 1 of arXiv:2607.03924, 'Tree Coordinates and Range Martingales for Positive Operator-Valued Measures'] Let $0\leq F\leq G$ in $B\left(H\right)$, and set
\begin{equation}
H_{G}=\overline{ran}\,(G^{1/2}).
\end{equation}
Then there is a unique positive contraction $A$ on $H_{G}$ such
that 
\begin{equation}
F=G^{1/2}AG^{1/2},
\end{equation}
where $A$ is extended by zero on $H^{\perp}_{G}$.

[Lemma sec4-lm.5 of arXiv:2602.04303, '\Large\textbf{Strong solutions to SDEs with singular drifts driven by fractional Brownian '] Assume (equation cond1 of the paper) and (equation cond2 of the paper). Let $\{b_n\}_{n=1}^\infty$ and $X_t^n$ be the same quantities as in Lemma (sec4-lm.4 of the paper). Then, there exists a constant $\beta>0$ such that
			\begin{equation}
				\sup_n\int_0^T\int_0^T\frac{\mathbb{E}\Vert\boldsymbol{\mathrm{D}}_\theta X_t^n-\boldsymbol{\mathrm{D}}_{\theta'}X_t^n\Vert^2}{|\theta-\theta'|^{1+2\beta}}\mathrm{d} \theta\mathrm{d} \theta'\leq C(H,d,p,q,T,\Vert b\Vert_{L^p_xL^q_t}).
