body:
[Definition def:Laplacian of arXiv:2605.01444, 'From second moments to pairwise negative correlation: \\applications to minimal and unifor'] Let $G=(V,E)$ be a finite graph with $|V|=n$.
	The adjacency matrix $A_G$, degree matrix $D_G$ and Laplacian matrix $L_G$ are $n\times n$ matrices indexed by $V$ defined as follows:
	\begin{itemize}
		\item $(A_G)_{u,v}$ is the number of edges between $u$ and $v$;
		\item $(D_G)_{u,u}=\deg(u;G)$ and $(D_G)_{u,v}=0$ for $u\neq v$; 
		\item $L_G=D_G-A_G$.
	\end{itemize}

[Corollary 16 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $T = \E X >0$ and $X \sim f \dd \pi_{T}.$  
     \begin{enumerate}
         \item If $f : \N \rightarrow [0, \infty),$ then
         \begin{displaymath}
             H \Big( \sum_{i=1}^{n} T_{1/n}(X_{i}) |\pi_{T} \Big) \le \frac{I(X | \pi_{T})}{n}
         \end{displaymath}
         \item and if $f : \N \rightarrow (0,\infty) $ is ultra log-concave, then 
         \begin{displaymath}
             H \Big( \sum_{i=1}^{n} T_{1/n}(X_{i}) |\pi_{T} \Big) \le 
         \frac{1}{n} \Big( I(X | \pi_{T}) - T^{2} C^{2} \Big) + \frac{1}{n^{2}} T^{2} C^{2}
         \end{displaymath}
         where $C = \frac{f(0)}{f(1) + f(0)}.$
     \end{enumerate}

