[Proposition 5 ({\cite[\S 3.2) of arXiv:2608.27450, 'Koszul duality and Morita categories'] {blansblom2025chainrulegoodwilliecalculus}}]
    There is a $2$-category $\pressymstc$ such that:
    \begin{enumerate}[\upshape{(}\arabic*\upshape{)}]
        \item The objects of $\pressymstc$ are stable presentable categories;
        \item The category of $1$-morphisms from $\sA$ to $\sB$ in $\pressymstc$ is given by $\SSeqnu(\sA, \sB)$;
        \item Composition is given by the composition product.
    \end{enumerate}
    Moreover, the composition product commutes with sifted colimits in both variables. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Total variation bound) of arXiv:2605.02713, '2605.02713'] For any $q \in \N$, there exists a positive constant $C(q)$ such that the following bounds are satisfied.
	\begin{align*}
		(i) &\quad d_{TV} \left( \mathcal{L}\big(W_{q,\gamma}(1)\big) , \mathcal{N}(0,1) \right) \leq C(q) \gamma^{-1/2}  (1+a_q(\gamma)), \qquad \hspace{10mm}\gamma \geq 1,\\
		(ii) &\quad d_{TV} \left( \mathcal{L}\big(W_{q,\gamma}(1)\big) , \mathcal{L} \left(  \frac{H_q(Z)}{\sqrt{q!}} \right) \right) \leq  C(q) \gamma^{1/(4q)} (1+b_q(\gamma)) ,
	\end{align*}
	where $a_q(\gamma) \to 0$ as $\gamma \to \infty$ and $b_q(\gamma) \to 0$ as $\gamma \to 0$ for every $q \in \N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 24 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] \begin{displaymath}
        I \big( \pi_{x} | \pi_{y} \big) = \frac{(x-y)^{2}}{y}, \quad \forall x,y>0.
    \end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

