body:
[Definition def:LMP of arXiv:2604.25851, '{Non-uniqueness of nonlinear Markov processes in the sense of McKean associated with parab'] A \emph{(normal, time-homogeneous) linear Markov process} is a family $\{P^z
\}_{z\in \mathbb{R}^d} \subset \mathcal P(\mathcal C)$  such that 
\begin{enumerate}[label=(\roman*), font=\normalfont]
        \item $P_0^z = \delta_z$ for all $z \in \mathbb{R}^d$; 
        \item $z\mapsto P^z(G)$ is Borel measurable for all $G \in \mathcal B(\mathcal C)$;
        \item  the \emph{(time-homogeneous) linear Markov property} holds, i.e., 
\begin{equation}
    P^{z} (\pi_{t+s} \in A | \mathcal{F}_s)(\cdot) = P^{\pi_s(\cdot)} (\pi_t\in A) \quad P^z-\text{a.s.},\quad \forall s,t \geq 0, \, A \in \mathcal{B}(\mathbb{R}^d).
\end{equation}
\end{enumerate}

[Lemma exx of arXiv:2412.04013, 'Rate estimates for total variation distance with applications\thanks{The author gratefully'] Let $X_{1},X_{2}$ be such that, for some $r,C_{r}>0$, 
\begin{equation} 
E[e^{r|X_{i}|}]\leq C_{r},\quad  
\int_{\mathbb{R}^{d}}|\phi_{i}(u)|e^{r|u|}\, du\leq C_{r},\ i=1,2.
\end{equation}
Then there are constants $G,G'$, depending only on $d,r,C_{r}$, such that
\begin{equation}
d_{TV}(X_{1},X_{2})\leq G d_{FM}(X_{1},X_{2})|\ln d_{FM}(X_{1},X_{2})|^{2d+1}
\end{equation}
and 
\begin{equation}
\sup_{x\in\mathbb{R}^{d}}|f_{1}(x)-f_{2}(x)|\leq G' d_{FM}(X_{1},X_{2})|\ln d_{FM}(X_{1},X_{2})|^{d+1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem sharplem of arXiv:2411.00629, '\Large Transformation of Stochastic Recursions and Critical Phenomena in the Analysis of t'] Assume $\alpha >1$ in the $\alpha$-Riccati equation. Suppose that $v(t)$, $t>0$ solves
\begin{equation}
{{v}}^\prime(t) = -{{v}}(t) + 2{{v}}(\alpha t)-{{v}}^2(\alpha t),  \quad v(0)=0,
\end{equation}
and assume that $|{{v}}(t)|= O(e^{-\rho t})$ as $t\to\infty$ for some $\rho>0$.

\begin{enumerate}
\item[(i)] \ If $0<\rho<1$ then ${{v}}(t) = O(e^{-t})$ as $t\to\infty$.
\item[(ii)]\ If $\rho >1$ then ${{v}}(t) \equiv 0$.
\end{enumerate}

[Lem central_midpoint_stability of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Let $(X,\rho)$ be a metric space, let $L>0$, and let $f:X\to\mathbb{R}$ be $L$-Lipschitz. Let $K\in\mathbb{N}_+$, let $x_1,\ldots,x_K\in X$, and suppose that there exists $\eta\ge0$ such that
\begin{equation}

    \sup_{x\in X}
    \min_{k\in[K]_+}
    \rho(x,x_k)
    \le
    \eta.
\end{equation}
Let $v_1,\ldots,v_K\in\mathbb{R}$ and suppose that, for some $\Delta\ge0$, one has $\max_{k\in[K]_+}|v_k-f(x_k)|\le\Delta$.
For every $x\in X$, define
\begin{equation*}
\begin{aligned}
    U(x)
    &\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \min_{k\in[K]_+}
    \left\{
        v_k+L\rho(x,x_k)
    \right\},
    \\
    W(x)
    &\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \max_{k\in[K]_+}
    \left\{
        v_k-L\rho(x,x_k)
    \right\},
    \\
    \hat{f}(x)
    &\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \frac{U(x)+W(x)}{2}.
\end{aligned}
\end{equation*}
Then $U$, $W$, and $\hat{f}$ are $L$-Lipschitz and for every $x\in X$
\begin{equation}

    |\hat{f}(x)-f(x)|
\le
    \Delta+L\eta.
\end{equation}

[Lemma convergence of s-periods of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $(\lambda_n,C^2_n) \to (\lambda, C^2) \in S^0 \cup \partial S_{1}^0$ such that $(\lambda,C^2) \neq (\frac{p-1}{2},0)$ and $\lambda<p-1$. 
  Moreover, let $g_n:=g_{\lambda_n,C^2_n}$ and $g:=g_{\lambda,C^2}$. Then 
  \begin{equation*}
    S_n: [0,1] \to \R: w\mapsto \begin{cases}
      \int_{w_{m,n}}^w \frac{1}{\sqrt{g_n(x)}}dx &\text{if }w_{m,n}<w\leq1, \\ 0  &\text{if }0\leq w\leq w_{m,n},
    \end{cases}
  \end{equation*}
  converges pointwise to 
  \begin{equation*}
    S:[0,1] \to \R: w \mapsto \begin{cases}
      \int_{w_{m}}^w \frac{1}{\sqrt{g(x)}}dx &\text{if }w_{m}<w\leq 1, \\ 0  &\text{if }0\leq w\leq w_{m},
    \end{cases}
  \end{equation*}
  for any $w \in [0,1]$.

