[Corollary 68 (Quantitative comparison) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] In the setting of Theorem~\ref{thm:dominated-stability}, suppose directly
that
\begin{equation}

 \norm{(\Prof_{m,r}(K_{\nu;i}-K_{\mu;i}))_{i\in I}}_{E(I)}
 \le\varepsilon_{\nu,\mu}.
\end{equation}
Then
\begin{equation}

 \Prof_{m,r}(K_\nu-K_\mu)
 \le C_{E,r}\varepsilon_{\nu,\mu}.
\end{equation}
For $2\le r<\infty$, in the symmetric same-field setting and for every
$1\le p<\infty$,
\begin{equation}

 \norm{I_m(K_\nu)-I_m(K_\mu)}_{L^p(\Omega;\Sch_r)}
 \le A_m(p+r)^{m/2}C_{E,r}\varepsilon_{\nu,\mu}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:level_line_hits_right_side_with_positive_prob of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Fix $j \in \{1,\ldots,N\}$,  $k \in \{0,1,\ldots,\lfloor R \rfloor - 1\}$ and $m \in \{0,1,\ldots,23\}$.  There exists a constant $p \in (0,1)$ depending only on $\mu$ and the constants $a,R_0$ of (lem:rectangles_are_not_wide of the paper) such that the following holds.  Conditional on $U_1,\ldots,U_N$ and $\eta_{j,\widetilde{k}}^{\widetilde{m}}$ for $(\widetilde{k},\widetilde{m}) \neq (k,m)$,  and on the event that the boundary conditions of $\Psi|_{U_j}$ are given by the zero function,  and that $I_j^3 \cap \partial B_{2^{-2 R /3}}(0) = \emptyset,  I_j^4 \cap \partial B_{2^{-R /3}}(0) = \emptyset$,  we have that the curve $\eta_{j,k}^m$ first intersects the right boundary of the rectangle 
	\begin{align*}
		(0 ,  L_j) \times \left(\vert a_{j,k}^m \vert - \frac{1}{48 R} ,  \vert a_{j,k}^m\vert + \frac{1}{48 R} \right)
	\end{align*}
	before hitting either its top or bottom boundaries,  with conditional probability at least $p$.

