body:
[Definition 3 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] We say that a sequence of lower semicontinuous functions $(f_n)$ on $\CC \times \CC$ converges to a function $f$ on $\CC \times \CC$ with respect to the lower semicontinuous topology if and only if the following hold.
\begin{enumerate}
    \item For every sequence of points $(z_n,w_n) \in \CC \times \CC$ converging to a point $(z,w) \in \CC \times \CC$, we have that
    \begin{equation*}
        f(z,w) \leq \liminf_{n \to \infty} f_n(z_n,w_n).
    \end{equation*}
    \item For every point $(z,w) \in \CC \times \CC$, there exists a sequence of points $(z_n,w_n) \in \CC \times \CC$ converging to $(z,w)$ for which
    \begin{equation*}
        f(z,w) = \lim_{n \to \infty} f_n(z_n,w_n).
    \end{equation*}
\end{enumerate}

[Definition of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] We say that a finite connected directed graph $G$ is a \emph{cactus} if every edge belongs to a unique simple cycle. In the case where each such cycle is directed (each edge have the same orientation), then we further specify that $G$ is an \emph{oriented cactus}. We write $\mathcal{C}$ for the set of all \emph{planted cactus-type monomials}, that is, graph monomials with $v_{in}=v_{out}$ whose underlying graph is an oriented cactus. We write $\mathcal{C}_{N}$ for the vector space generated by $(g(\mathbf{A}_{N}))_{g\in\mathcal{C}}$ . More generally, we define $\mathcal{F}$ to be the set of all graph monomials obtained by starting with a directed path
        \begin{equation*}
            \underset{v_{out}}{\cdot}\leftarrow\cdot\leftarrow\cdot  \cdots \cdot\leftarrow \underset{v_{in}}{\cdot}
        \end{equation*}
        and attaching oriented cacti to the vertices of this path
        \begin{equation*}
            \overset{\vee}{\underset{v_{out}}{\cdot}}\leftarrow\overset{\vee}{\cdot}\leftarrow\overset{\vee}{\cdot}  \cdots \overset{\vee}{\cdot}\leftarrow \overset{\vee}{\underset{v_{in}}{\cdot}}.
        \end{equation*}
        Similarly, we write $\mathcal{F}_{N}$ for the vector space generated by $(g(\mathbf{A}_{N}))_{g\in\mathcal{F}}$. We say that an element of $\mathcal{F}$ is a cactus field-type monomial.

[Proposition 34 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] Let $(\mathbf{v}_{\varepsilon})_{\varepsilon}$ be a sequence in $L^{\Phi}(Q\times\Omega)^{d}$ which weakly $\Sigma$-converges (in each component) to $\mathbf{v} \in L^{\Phi}(Q\times\Omega; \mathcal{X}_{A}^{\Phi})^{d}$. Then, for any integer $n\geq 1$,  we have that there exists a constant $C'$ such that
		\begin{equation*}
			\iint_{Q\times\Omega} \pounds_{A}\int \varrho \circ f_{n}(\cdot,\cdot, \mathbf{v}) dydxd\mu   - \dfrac{C'}{n} \leq \lim_{\varepsilon \to 0} \iint_{Q\times\Omega}  f\left(x, T\left(\frac{x}{\varepsilon_{1}}\right)\omega,\frac{x}{\varepsilon_{2}}, \mathbf{v}_{\varepsilon}(x,\omega)\right)  dxd\mu.
		\end{equation*}

[Lem sg-res-limit of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] Let $u\in C_b(X)$. Then 
\begin{equation}
		\lim_{t\downarrow 0} \check{\bf P}_t u(x) =  \lim_{\alpha\to\infty} \alpha \check{R}_\alpha u(x)  
		= \mathbb{E}_x\left[u(\mathbb{X}_{\tau_0})\right] = P_F u(x),\quad x\in X.
\end{equation}

