[Definition 7 ($H^\infty$-calculus for sectorial operators) of arXiv:2606.15425, 'Well-posedness of stochastic parabolic equations with gradient nonlinearities and applicat'] The operator $A$ is sectorial if the domain and the range of $A$ are dense in $\mathcal B$ and 
\begin{enumerate}
    \item[(i)] there exists $\phi\in (0,\pi)$ such that $\sigma(A)\subset \overline{\Sigma}_{\phi}$, where $ \Sigma_{\phi}\coloneqq\{z\in \mathbb C\,:\,|\arg z|< \phi\}$
    \item[(ii)] there exists $C_{\mathrm{res}}>0$ such that
    \begin{equation}

    |\lambda|\norm{(\lambda-A)^{-1}}_{\mathcal L(\mathcal B)}\leq C_{\mathrm{res}}, \qquad \forall \lambda \in \mathbb C\setminus \overline{\Sigma_{\phi}}.
    \end{equation}
\end{enumerate}
Then $\omega(A)\coloneqq\inf\{\phi\in (0,\pi)\,:\,\eqref{eq:sectorial}\,\,\text{holds for some}\; C_{\mathrm{res}}>0\}$ is called the angle of sectoriality of $A$. We say that $A$ has a bounded $H^{\infty}$-calculus of angle $\phi \in (0,\pi)$ if
for all holomorphic functions $f:\Sigma_{\phi} \rightarrow  \mathbb C$ with $$\norm{\frac{f}{\min\{|z|^{\varepsilon},|z|^{-\varepsilon}\}}}_{L^\infty} < \infty$$ for some $\varepsilon > 0$, the bound 
\begin{equation}

\norm{f(A)}_{\mathcal L(\mathcal B)}\leq \const \norm{f}_{L^{\infty}(\Sigma_{\phi})}
\end{equation} 
holds for some constant $C_{\themycounter}$ independent of $f$. Here, the operator $f(A)$ is defined through the line integral
$$
f(A)\coloneqq \frac{1}{2\pi i} \int_{\Gamma} f(z)(z-A)^{-1}\d z \in \mathcal L(\mathcal B)
$$
for a contour $\Gamma \subset \Sigma_\phi$ in an intermediate sector enclosing the spectrum. Then, $$\omega_{H^\infty}(A) \coloneqq \inf\{\phi\in (0,\pi)\,:\,\eqref{eq:H_infinite_calculus}\text{ holds for some }\const >0\}$$ is the angle of the $H^{\infty}$-calculus of $A$.

[Lemma 9 of arXiv:2605.16072, 'Stochastic integration \\with respect to a L\'evy basis'] Let $L$ be a real-valued L\'evy process with characteristics $(b, q, \lambda)$ with respect to the truncation function $\tau$, and let $(\pi_n)_{n \in \mathbb{N}}$ be a normal sequence of partitions $\pi_n=(p_{k,n})_{k=0,\dots, m_n}$ of $[s,t]$. If we put $d_{k,n}=L(p_{k,n})-L(p_{{k-1},n})$, 
	then we have
	\begin{enumerate}
		\item [\rm (a)] $ \displaystyle \lim_{n \rightarrow \infty} \sum_{k=1}^{m_n} E\left[\tau(d_{k,n})\right]=(t-s)b$;
		\item [\rm (b)] $\displaystyle \lim_{n \rightarrow \infty} \sum_{k=1}^{m_n} E\left[ \tau^2(d_{k,n})  \right]= (t-s)\left(\int_{\R} \left( \abs{\beta}^2 \wedge 1 \right)\, \lambda({\rm d}\beta)+ q\right)$.
	\end{enumerate}

[Proposition 1 of arXiv:2608.26693, '2608.26693'] The following facts hold.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.2em]
\item \emph{Mass separation.}  If $\alpha=a\mu_0$ and $\beta=b\mu_1$ with $a,b>0$, then
\begin{equation}
\Ucal_{\tau_0,\tau_1}(\alpha,\beta)
=\tau_0a+\tau_1b-TM_*,
\end{equation}
where
\begin{equation}
M_*=a^{w_0}b^{w_1}\exp\!\left(-\frac{\Acal_*}{T}\right).
\end{equation}

\item \emph{Gaussian reduction.}  If $\nu_0,\nu_1\in\mathcal P_2(\R^p)$ have means $u,v$ and positive-definite covariance matrices $P,Q$, and $g_0=\N(u,P)$, $g_1=\N(v,Q)$, then
\begin{align}
W_2^2(\nu_0,\nu_1)&\ge W_2^2(g_0,g_1),\\
\KL(\nu_0\mid\mu_0)&\ge \KL(g_0\mid\mu_0),\qquad
\KL(\nu_1\mid\mu_1)\ge \KL(g_1\mid\mu_1).
\end{align}
Restricting the two shape measures to nondegenerate Gaussians therefore leaves the infimum defining $\Acal_*$ unchanged, and every finite-objective minimizer is Gaussian.  The Gaussian covariance minimum is attained at an interior pair $(P_*,Q_*)\in\mathbb S_{++}^p\times\mathbb S_{++}^p$.

\item \emph{Mean action.}  The optimal mean contribution is
\begin{equation}
\Acal_{\rm mean}
=\delta^\top\bigl(I+r_0\Sigma_0+r_1\Sigma_1\bigr)^{-1}\delta.
\end{equation}
The adjusted means are
\begin{equation}
u_*=m_0-r_0\Sigma_0h_*,\qquad
v_*=m_1+r_1\Sigma_1h_*,
\end{equation}
where
\[
h_*=(I+r_0\Sigma_0+r_1\Sigma_1)^{-1}\delta.
\]

\item \emph{Covariance stationarity and Riccati reduction.}  If $L_*\succ0$ is the optimal Gaussian transport map, so that $Q_*=L_*P_*L_*$, then
\begin{equation}
P_*^{-1}=A_0+r_0(I-L_*),\qquad
Q_*^{-1}=A_1+r_1(I-L_*^{-1}),
\end{equation}
and $L_*$ is the unique positive-definite solution of
\begin{equation}
L_*C_1L_*-\kappa L_*=C_0.
\end{equation}
Equivalently, the optimal transport map is
\begin{equation}
L_*=C_1^{-1/2}\mathsf S C_1^{-1/2}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 17 of arXiv:2609.00285, 'Multicrossing complex of knot and secant classes'] \begin{enumerate}
    \item $\iota^2=id$;
    \item $\iota d=d\iota$;
    \item $\iota(\widetilde{\mathdutchcal D}(L,n))=\widetilde{\mathdutchcal D}(L,n)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2608.03771, '\vspace{-5ex}\bfseries\scshape{Local law and delocalization for the Sachdev--Ye--Kitaev mo'] For any $\tau\in \{+,-\}$, and any $z\in\mathbb{C}_+$, we have 
    \begin{equation}
    \E[G_\tau(z)]=m_{N,\tau}(z)I_{\mathcal{H}_N^\tau}
    \end{equation}

[Theorem 29 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $t\not=0$ such that $T^{-1}+tT>0$. Then $F\in\mathcal{HP}_{T,t}$ if and only if it can be written as the linear fractional transformation
        \begin{equation}
F(z)=tT^{1/2}S(z)(T^{-1}+tT)^{-1/2}-(tT^2+I_m)^{-1/2},
        \end{equation}
where $S(z)$ is contractive in $\mathbb C_r$ for $t<0$ while it is expansive in $\mathbb C_r$ for $t>0$.

[Thm strictly_smaller_free_energy of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] For $\mathsf{P}_i\in  \mathcal P_{s,1}(\Gamma)$ with  $\mathcal F_{\beta}({\mathsf{P}_i})<\infty$, $i=0,1$, there exists $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$ with \begin{align}  
    \mathcal F_{\beta}(\mathsf{P}_{t})\leq  (1-t)\mathcal F_{\beta}(\mathsf{P}_{0})+t\mathcal F_{\beta}(\mathsf{P}_{1})-\frac{(1-t)t\beta}{2}\int \sum_{(0,0)\neq (x,y)\in \bar\xi} (x-y)^2\inf_{z\in [x,y]}f(\left\lvertz\right\rvert) \mathsf{Q}^0(d\bar\xi),
    \end{align}
     where  $\mathsf U:=\iota( \mathsf{Q})$,  $\mathsf{P}_t:= \mathsf{gap}^{-1}\left((T_t)_{\#}\mathsf U\right)$ and $f$ is chosen as in (equation eq:function_f of the paper).

