[Theorem thm:correction_moments of arXiv:2508.18809, '{\bf Critical long-range percolation III: The upper critical dimension}'] If $d\geq 3\alpha$ and $\alpha<2$  then
\begin{equation}

\sum_{y\in \mathbb Z^d} \mathscr{D}^{(1)}_r(0,y)P\Bigl(\frac{y}{r}\Bigr) =\left[\int_{\mathbb R^d} \kappa^{*3}(y)P(y) \dif y \pm o(1)\right]V_r^2(\mathbb E_r|K|)^4
 \end{equation}
and
\begin{equation}

\sum_{y\in \mathbb Z^d} \mathscr{D}^{(2)}_r(0,y)P\Bigl(\frac{y}{r}\Bigr) =\left[\int_{\mathbb R^d} (\kappa^{*3}(y)+2\kappa^{*4}(y))P(y) \dif y \pm o(1)\right] V_r^3(\mathbb E_r|K|)^7
 \end{equation}
 as $r\to \infty$ for each polynomial $P:\mathbb R^d\to \mathbb R$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:7 of arXiv:2510.13572, 'Coalescence in Markov chains'] {ncftp}}]
Let $S$ be a non-empty, finite set, let $P\in\mathcal{P}_S$, and let $\mathcal S = \{S_r: r\in I\}$  be  a partition of $S$
with index set
$I=\{1,2,\dots,\ell\}$. 
For $i\in S_r$, let
\begin{equation}
\lambda_{r,s}^{(i)}= \sum_{j \in S_s} p_{i,j}.
\end{equation}
If there exists an $\mathcal S$-block measure $\mu\in \mathcal L_P$, then
\begin{letlist}
\item
for $r,s\in I$, 
\begin{equation}
\text{$\lambda_{r,s} := \lambda_{r,s}^{(i)}$ is constant for $i\in S_r$},
\end{equation}

\item
the \lq block-transition matrix'  $\Lambda=(\lambda_{r,s}: 1\le r,s\le \ell)$ is irreducible. Moreover, 
\begin{equation}
\text{$\Lambda$ is doubly stochastic,}
\end{equation}
which may be expressed as
\begin{equation}
\sum_{i\in S}\sum_{j \in S_s} \frac1{|S_{r(i)}|}p_{i,j}=1, \qquad r,s\in I,
\end{equation} 
where $r(i)$ is the index $r\in I$ such that $i \in S_r$.
\end{letlist} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 (Bures--Wasserstein in terms of Cholesky factors) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $A, B \in \mathscr{S}_+(n)$. Write $A = LL^{\intercal}$ and $B = MM^{\intercal}$, where $L, M \in \mathbb{R}^{n\times n}$.\footnote{Given $A$ and $B$, the factors $L, M \in \mathbb{R}^{n \times n}$ always exist but are generally not unique. The stated results hold for each choice of $L$ and $M$.}
\begin{itemize}
\item[(i)] We have
\begin{equation} 
\begin{split}
\dist_{\BW}^2(A, B) &=  \|L\|_{\mathrm{F}}^2 + \|M\|_{\mathrm{F}}^2 - 2 \| L^{\intercal} M \|_*.
\end{split}
\end{equation}
\item[(ii)] Let $L^{\intercal}M$ have singular value decomposition $U \Sigma V^{\intercal}$. Consider a coupling $\tilde{\pi}$ of $(\cN_n(0, A), \cN_n(0, B))$ of the form $\tilde{\pi} = \cL(X, Y)$, where $(X, Y) = (L\epsilon^X, M \epsilon^Y)$ and 
\begin{equation*} 
\pi := \cL(\epsilon^X, \epsilon^Y) \in \Cpl(\cN_n(0, I), \cN_n(0, I)).
\end{equation*}
Then $\tilde{\pi}$ is a Brenier coupling between $\cN_n(0, A)$ and $\cN_n(0, B)$ if and only if
\begin{equation} 
P := \bE_{\pi}[\epsilon^Y (\epsilon^X)^{\intercal}] \in \mathscr{P}(L^{\intercal}M).
\end{equation}
In particular, we may let $\pi$ be the Gaussian coupling
\[
\begin{bmatrix} \epsilon^X \\ \epsilon^Y \end{bmatrix} \sim \cN_{2n} \left( \begin{bmatrix} 0 \\ 0 \end{bmatrix}, \begin{bmatrix} I & P \\ P^{\intercal} & I \end{bmatrix} \right), \quad P \in \mathscr{P}( L^{\intercal}M).
\]
\end{itemize}

[Definition Random Walk of arXiv:2606.14895, 'Effective Resistances and Commute Times in Sparse Random Geometric Graphs'] A random sequence $X_1, ..., X_k$ of vertices in $G$ is a random walk if independently for all $i \in [k-1]$:
\begin{equation*}
    \Pr\left(X_{i+1} = v \mid X_i = u\right) = 
    \begin{cases} 
        \frac{w_{(u,v)}}{\deg(u)} & \text{if } (u,v) \in E\,, \\
        0 & \text{otherwise}.
    \end{cases}
\end{equation*}
Furthermore, let $\mathbf{W} = \mathbf{A}\mathbf{D}^{-1}$ so that 
$\mathbf{W}_{vu} = \Pr\left(X_{i+1} = v \mid X_i = u\right)$. Then
$\mathbf{W}\vec{\mathbf{1}}_u$ is the distribution of vertex locations after one step of a random walk starting from $u$.

