body:
[Proposition deterBrownPlane of arXiv:2411.16541, 'The Hausdorff measure of the boundary of the Brownian disk'] There exists a deterministic constant $\kappa \in[0, \infty]$ such that almost surely:
	\begin{equation}

		\limsup_{\epsilon\downarrow 0}\frac{m^h_{\mathbb D}([0, \epsilon])}{\epsilon}=\limsup_{\epsilon\downarrow 0} \frac{m^h_{\mathbb H}([0, \epsilon])}{\epsilon}=\kappa.
	\end{equation}

[Theorem thm:flow of arXiv:2607.24705, 'Derangetropy Operators'] Along the flow~(equation eq:flow of the paper) the function $V = \tan(\pi F)$
		satisfies the linear equation $\partial_{t}V = -V$ pointwise; hence
		\begin{equation}
			\tan\big(\pi F(x,t)\big) = e^{-t}\tan\big(\pi F_{0}(x)\big),
			\qquad
			f(x,t) = \frac{e^{-t}f_{0}}
			{\cos^{2}(\pi F_{0}) + e^{-2t}\sin^{2}(\pi F_{0})}.

		\end{equation}
		Consequently, for every $f_{0} \in \mathcal{D}_{+}$,
		\begin{equation}
			e^{t}\,(X_{t} - m) \;\xrightarrow{\ d\ }\;
			\mathrm{Cauchy}\Big(0, \frac{1}{\pi f_{0}(m)}\Big),

		\end{equation}
		and, under the integrability hypothesis of
		Lemma~(lem:flow-wellposed of the paper), the differential entropy satisfies
		\begin{equation}
			H(f_{t}) = -t + \log\frac{4}{f_{0}(m)} + o(1),

		\end{equation}
		so that entropy is dissipated at unit asymptotic rate;
		correspondingly $H(f_{n+1}) - H(f_{n}) \to -\log 2$ along the
		discrete iteration. The constant in the entropy
		law~(equation eq:entropy-law of the paper) is the entropy of the limiting Lorentzian
		profile in the limit~(equation eq:lorentz-limit of the paper).

[Proposition 8 (FKG inequalities, {\cite[Propositions~B.1--.2) of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] {random_tangled} and \cite[Corollary~6.4]{LammersOtt2021}}]  Let $\Lambda \subset V$ be finite, $\beta\geq0$,  and $\eta\in \mathbb R^{V}$. Then, for any increasing and bounded functions $F,G:\mathbb{R}^\Lambda\to \mathbb{R}$,
\begin{equation*}
    \langle F(\varphi)G(\varphi)\rangle^{\eta}_{\Lambda,\beta}\geq \langle F(\varphi)\rangle^{\eta}_{\Lambda,\beta}\langle G(\varphi)\rangle^{\eta}_{\Lambda,\beta}.
\end{equation*}
The same holds for the absolute value field if $\eta_x\geq 0$ for every $x \in \Lambda$, namely
\begin{equation*}
    \langle F(|\varphi|)G(|\varphi|) \rangle^{\eta}_{\Lambda,\beta}\geq \langle F(|\varphi|) \rangle^{\eta}_{\Lambda,\beta} \langle G(|\varphi|) \rangle^{\eta}_{\Lambda,\beta}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:global_clt of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] As in (equation eq:sigmadef_global_intro of the paper), set
\begin{equation}

    \sigma_n^2 = 
    \mleft( 1 - 2 p (1-p) \sum_{j=1}^K \beta_j \mathsf{e}_j (\mathsf{e}_j-1) p^{\mathsf{e}_j-2} \mright)^{-1}
    \times p(1-p) \binom{n}{2},
\end{equation}
Then for any $\varepsilon > 0$, if $X$ is distributed as (equation eq:tilt of the paper) with $Y \sim \mathcal{G}(n,p)$ and $\mathsf{g}$ given in
(equation eq:smallgdef of the paper), under the ``phase-uniqueness or forest'' assumption, we have
\begin{equation}
    \mathbf{d} \mleft( \frac{\mathsf{E}(X) - \mathbb{E}[\mathsf{E}(X)]}{\sigma_n}, Z \mright) \lesssim n^{-\frac{1}{2} + \varepsilon},
\end{equation}
for both $\mathbf{d} = \mathbf{d}_\mathrm{Was}$ and $\mathbf{d} = \mathbf{d}_\mathrm{Kol}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] Let $\mathfrak{F}\subset B(\X)$ satisfy Hypothesis $(\mathbf{H_2})$ and $\mu$ be the unique invariant measure of $\Phi$.
    If there exists $z \in \X$ such that 
    \begin{itemize}
        \item [(\runum{1})] $\Phi$ is uniformly eventually continuous w.r.t $\mathfrak{F}$ at $z$;
        \item [(\runum{2})] $\Phi$ satisfies the lower bound condition \eqref{eq:LBC_P} at $z$.
    \end{itemize}
	Then for all $x \in \X$,
    \begin{equation*}
		\limsup\limits_{t \to \infty} \sup_{f\in\mathfrak{F}}|P_tf(x) - \langle f,\mu\rangle | = 0.
	\end{equation*}

