body:
[Theorem 4 (Stability of discrete Schr\"{o}dinger potentials) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $\A \in \R^{m\times n}$ be a matrix with non-negative entries, and let $\r \in \R^m_{>0}$ and $\c \in \R^n_{>0}$ be target margin vectors with strictly positive entries such that $\|\r\|_1 = \|\c\|_1 = N$. 
		Let $\r(\A) = \A \mathbf{1}_n$ and $\c(\A) = \A^T \mathbf{1}_m$ denote the current row and column margins of $\A$. Assume that the target margin $(\r,\c)$ is close to the margin of $\A$ in the sense that 
		\begin{align}
			\r(\A) \in [(1-\eps) \r, (1+\eps)\r], \qquad \c(\A) \in [(1-\eps) \c, (1+\eps)\c]
		\end{align}
		entry-wise for some  $\epsilon \in (0, \epsilon_{\textup{max}})$, where 
		\begin{align}
			\eps_{\max}:=\frac{1}{50C_{\A}^2}, \quad   C_{\A} := 
			1 + \frac{9 \max_i \r_i \max_j \c_j}{\rho_{\A} m n}, \quad  \rho_{\A}:= \min_{i_{1},i_{2}\in \{1,\dots,m\}} n^{-1} \sum_{j=1}^{n}\A_{i_1 j}\A_{i_2 j}.
		\end{align}
		Then there exist exact Schr\"{o}dinger potentials $\balpha_{\A} \in \R^m, \bbeta_{\A} \in \R^n$ such that $\diag(e^{\balpha_{\A}})\A\diag(e^{\bbeta_{\A}})$ has exactly the margins $(\r, \c)$. These potentials are unique up to the one-parameter gauge shift $(\balpha_{\A},\bbeta_{\A})\mapsto(\balpha_{\A}-s\mathbf{1}_m,\bbeta_{\A}+s\mathbf{1}_n)$ with $s\in\R$, and can be chosen (via any canonical gauge-fixing, e.g.\ the one in the proof that projects onto the orthogonal complement of the gauge direction) such that
		\begin{align}
			\|(\balpha_{\A}, \bbeta_{\A})\|_{\infty} \le 4C_{\A} \epsilon.
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 22 of arXiv:2605.15501, 'Well-posedness of the obstacle problem for generalized Dean--Kawasaki equation\thanks{ The'] Let Assumption \ref{assu:assum for F} and Assumption \ref{assu:assu for unique} hold for $\xi^F, \psi, u_{\text{init}},\Phi,\sigma$.
Suppose that the pair $(u,\nu)$ fulfills all items in Definition \ref{def:def of stochastic kinetic solution} except the initial condition (iii), and satisfies the following preservation of energy for all $\phi\in C_c^\infty([0,T))$:
\begin{align}
&-\mathbb{E}\int_0^T\int_{\mathbb{T}^d}u^2(x,s)\partial_s\phi(s)\mathrm{d}x\mathrm{d}s+2\mathbb{E}\int_0^T\int_{\mathbb{T}^d}\phi(s)\psi(x,s)\mathrm{d}\nu(x,s)\\
&\ +2\mathbb{E}\int_0^T\phi(s)\mathrm{d}q(\mathbb{T}^d,[0,\infty),s)+\frac{1}{2}\mathbb{E}\int_{0}^{T}\int_{\mathbb{T}^d}\phi(t)\sigma^2(u)(\nabla_{x}\cdot F_{2}-2F_3)\mathrm{d}x\mathrm{d}s\nonumber\\
&=\mathbb{E}\int_{\mathbb{T}^d}u^2_{\mathrm{init}}(x)\phi(0)\mathrm{d}x.\nonumber
\end{align}
Then, we have almost surely
\begin{align}
\lim_{\tau\to0}\frac{1}{\tau}\int_0^{\tau}\int_{x}|u(x,t)-u_{\mathrm{init}}(x)|^2\mathrm{d}t=0,
\end{align}
which can be viewed as a strong trace result with respect to the initial data.

