[Lemma lem:delmeyer of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{Exponential moment bounds.}  Let $Y_s$ for $s \in [0,t]$ denote a non-decreasing scalar-valued adapted process such that $\mathbb{E}[Y_t - Y_s|\mathcal{F}_s] \leq K$ for all $s \in [0,t]$.  Then for any $L < \frac{1}{K}$, 
\begin{align*}
\mathbb{E}[\exp \left( L Y_t \right)] < \frac{1}{1 - LK}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:conv_appro_1 of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Fix $(a,r)\in{\mathbb R}^2$. Let $(\sigma_n,b_n)_{n\ge1}$ and $(\sigma,b)$ satisfy Assumption~(assu:H of the paper) and conditions~(item:1a of the paper), (item:1b of the paper), (item:2c of the paper), and~(item:2d of the paper). Assume that $(\sigma_n)_{n\ge1}$ has the same sign as $\sigma$, i.e., $\sigma_n\sigma\ge0$ for all $n$. Let $\mathcal S^n_{r,\cdot}(a)$, $n\ge1$, and $\mathcal S_{r,\cdot}(a)$ denote the unique strong solutions to~(equation eq:SDE_gener of the paper) corresponding to $(\sigma_n,b_n)$ and $(\sigma,b)$, respectively. Suppose that:
\vspace{-0.5em}
\begin{enumerate}[label=(\roman*)]
\item for any compact set $K\subset{\mathbb R}$ and all $T\ge r$,
\begin{equation}
\begin{gathered}
\lim_{n\to\infty}\sup_{r\le t\le T}\sup_{x\in K}\int_{{\mathbb R}}(\sigma_n(x,t,s)-\sigma(x,t,s))^2\,\ensuremath{\mathrm{d}} s=0,\\
\lim_{n\to\infty}\sup_{r\le t\le T}\sup_{x\in K}|b_n(x,t)-b(x,t)|=0;
\end{gathered}
\end{equation}
\vspace{-1.5em}
\item for any $T\ge r$, there exist positive constants $K_b'=K_b'(T)$ and $K_\sigma'=K_\sigma'(T)$ such that, for all $x\in{\mathbb R}$, $r\le t\le T$, and $n\ge1$,
\begin{align}
|b_n(x,t)| \le K_b'(1+|x|), \qquad 
\bar\sigma_n(x,t):=\int_{{\mathbb R}}\sigma_n(x,t,s)^2\,\ensuremath{\mathrm{d}} s \le K_\sigma'(1+|x|)^2.
\end{align}
\end{enumerate}
\vspace{-0.5em}
Then $\mathcal S^n_{r,\cdot}(a)\to \mathcal S_{r,\cdot}(a)$ in probability in $C([r,\infty))$. In particular, there exists a subsequence of $\{\mathcal S^n_{r,\cdot}(a)\}$ that converges almost surely uniformly on compact intervals to $\mathcal S_{r,\cdot}(a)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 6 of arXiv:2510.26216, 'A functional Breuer-Major theorem with Poisson noise'] Suppose $M\in\NN$, $\Upsilon$ is a distribution on $\RR^N$. Fix an even function $\zeta\in \sS(\RR^N)$ with $\int_{\RR^N}\zeta(x) dx=1$. For every $\eps>0$, let $\zeta_\eps=\eps^{-N}\zeta(\cdot/\eps)$. Then for any $\lambda>2$, we have
        \begin{equation*}
            \|\Upsilon*\zeta_\eps\|_{M+3, \fR_{\vec{K}}}\lesssim  \sum_{\vec{L}\in\ZZ^N}  \frac{\|\Upsilon\|_{M+2, \fR_{\vec{L}}}}{1+|\vec{L}-\vec{K}|^\lambda}
        \end{equation*}
    and
        \begin{equation*}
            \|\Upsilon*\zeta_\eps-\Upsilon\|_{M+3, \fR_{\vec{K}}}\lesssim \eps \sum_{\vec{L}\in\ZZ^N}  \frac{\|\Upsilon\|_{M+2, \fR_{\vec{L}}}}{1+|\vec{L}-\vec{K}|^\lambda} .
        \end{equation*}
    where the proportionality constants is independent of $\Upsilon$, $\vec{K}\in\ZZ^N$ and $\eps\in(0,1)$.

