[Theorem thm:riesz of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let $ s\in (0,1),\beta >0.$   
  \begin{itemize}
\item Let $ \gamma \in (0,1],\varphi \in   \mathscr  F_{ \gamma }^{ *}$. Then there is $ C_{ \varphi }$ not depending on $ n,R$ such that
\begin{align*}
  \textrm{Var}\left(\mathsf{P}_{ n}^{ s,\beta }(\varphi _{ R})\right) \leqslant C_{ \varphi }R^{ 2-\min(1-s,\gamma )}\ln(R)^{ 1-s = \gamma }.
\end{align*}
\item  Any  limit point $ \mathsf{P}^{ s,\beta }$ of $ \mathsf{P}_{ n}^{ s,\beta }$ is stationary and  $ (1-s)$-hyperuniform, hence for $ \gamma >0,\varphi \in   \mathscr  F_{ \gamma }$, 
\begin{align*}
  \textrm{Var}\left(\mathsf{P}^{ s,\beta }(\varphi _{ R})\right) = O(R^{ 2-\min(1-s,\gamma )}\ln(R)^{ 1-s = \gamma }
).
\end{align*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

