[Theorem thm:linear-sub-D12 of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Let $H$ be separable and let the random field be linear in its substitution variable, $w_r(z) = \Phi_r^{*}\,z$, for some $\Phi \in \mathbb{D}^{1, p^*}(L^2([0,t]; L_2(U, H)))$ at exponent $p^* \geq 2$. Let $G: \Omega \to H$ satisfy
\begin{equation}
  G \;\in\; \mathbb{D}^{1,2}(H) \;\cap\; L^{q}(\Omega; H), \qquad \frac{1}{q} + \frac{1}{p^*} \;\leq\; \frac{1}{2},
\end{equation}
together with the H\"older-pair joint integrability
\begin{equation}
  \mathbb{E}\bigl[\lVert \Phi \rVert_{L^2([0,t]; L_2(U,H))}^2\,\lVert G \rVert_H^2\bigr] + \mathbb{E}\bigl[\lVert \Phi \rVert_{L^2([0,t]; L_2(U,H))}^2\,\norm{\mathcal{D} G}_{L_2(H_W, H)}^2\bigr] \;<\; \infty.
\end{equation}
Then $\Phi^{*}G \in \operatorname{Dom}(\delta_U)$ with the substitution identity
\begin{equation}
  \delta_U(\Phi^{*}G) \;=\; \ip{G}{\mathcal{K}_\Phi}_H \;-\; \int_0^t \operatorname{Tr}_U\bigl[\Phi_r^{*}\,\mathcal{D}_r G\bigr]\,\mathrm{d}r \qquad \text{in } L^2(\Omega),
\end{equation}
where $\mathcal{K}_\Phi \in L^{p^*}(\Omega; H)$ is the Hilbert--Schmidt kernel of Lemma~(lemma:HS-kernel of the paper); both terms on the right-hand side are in $L^2(\Omega)$ (the first by Cauchy--Schwarz on the kernel pairing $L^q \cdot L^{p^*} \subset L^2$, the second by~(equation eq:linear-sub-Holder of the paper)), and $\ip{G}{\mathcal{K}_\Phi}_H$ is the substitution value of~(equation eq:HS-kernel-random of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma-bound-spin-correlations of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] There exists a constant $C>0$ such that for any $k \geq 1$ and any $x_1, \dots , x_k \in D_{\delta}$, 
\begin{equation*}
    \mu_{\delta}^{+}[\prod_{j=1}^{k}\sigma_{x_j}] \leq C^k\delta^{\frac{k}{8}}\exp\bigg( \frac{1}{8}\sum_{j=1}^{k} \log \frac{1}{L(x_j) \wedge {\operatorname{dist}}(x_j, \partial D_{\delta})} \bigg)
\end{equation*}
where for each $j$, $L(x_j) = \frac{1}{2}\min_{p:p \neq j} \vert x_p - x_j \vert$. Above, for $x \in D_{\delta}$, $d_{\delta}(x):={\operatorname{dist}}(x, \partial D_{\delta})$ is the Euclidean distance between $x$ and $\partial D_{\delta}$. Besides, by convention, for $k=1$, $L(x)=\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 28 of arXiv:2506.15044, '2506.15044'] Given $\widetilde{M}\in (\mathcal{M}_{\mathrm{loc}})^{i,\mathbb{B}}$ and $a,b\in\mathbf{R}$, let $H\in \mathcal{L}_m^\mathbb{B}(M)\cap\mathcal{L}_m^\mathbb{B}(\widetilde{M})$ and $K\in \mathcal{L}_m^\mathbb{B}(M)$.
\begin{itemize}
  \item [$(1)$] $aH+bK\in\mathcal{L}_m^\mathbb{B}(M)$, and in this case
  \begin{equation}
      (aH+bK)_{\bullet}M=a(H_{\bullet}M)+b(K_{\bullet}M).
  \end{equation}

  \item [$(2)$] $H\in\mathcal{L}_m^\mathbb{B}(aM+b\widetilde{M})$, and in this case
  \begin{equation}
      H_{\bullet}(aM+b\widetilde{M})=a(H_{\bullet}M)+b(H_{\bullet}\widetilde{M}).
  \end{equation}

  \item [$(3)$] Let $\widetilde{H}\in\mathcal{P}^\mathbb{B}$. Then  $\widetilde{H}\in\mathcal{L}_m^\mathbb{B}(H_{\bullet}M)$ if and only if
      $\widetilde{H}H\in\mathcal{L}_m^\mathbb{B}(M)$. Furthermore, if $\widetilde{H}\in\mathcal{L}_m^\mathbb{B}(H_{\bullet}M)$ (or equivalently, $\widetilde{H}H\in\mathcal{L}_m^\mathbb{B}(M)$), then
  \begin{equation}
     \widetilde{H}_{\bullet}(H_{\bullet}M)=(\widetilde{H}H)_{\bullet}M.
  \end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 59 of arXiv:2608.29086, '2608.29086'] [Vector field $\beta_{\sigma}$]
Given $M \subset H_0$ and edge-continuous $\sigma \in \Gamma(M)$. Then, a vector field $\beta_{\sigma} \in C^1(M)$ is obtained by
\begin{equation*}
\beta_{\sigma}(ab):= \Vert  e_{\sigma(abc)}(ab) \Vert \quad (ab \in C_1(M))),
\end{equation*}
where $abc \in Tri(M)$ is any triangle containing $ab$ as a side, and
\begin{equation*}
\Vert (x,y,z) \Vert :=x+y+z. 
\end{equation*}
 Since $\sigma$ is edge-continuous, the value dose not depend on the choice of $abc$. $\beta_{\sigma}$ is called the \textit{vector field defined by $\sigma$}.

[Lem dis of arXiv:2509.26254, '$K$-Branching Random Walk with Noisy Selection: \\ \Large Large Population Limits and Phas'] For $\gamma, \beta \in(0,1)$,
\begin{itemize}
\item[(i)]  $\bm{\mu}_L \in \Delta_{-1}$ iff $\gamma < \gamma_c(\beta)$, in which case $\Sigma(\bm{\mu}_L) = \beta^{-1}\left((\beta - 1)\nu_L + 1 - \gamma \right).$
\item[(ii)]  $\bm{\mu}_F\in \Delta_{0}$ iff $\gamma \geq\gamma_{c}(\beta)$, in which case $\Sigma(\bm{\mu}_F) = \left\langle \bm{u},\bm{\mu}_F \right\rangle + 1 - 2\gamma$.
\end{itemize}

