body:
[Theorem 1 (Anchored Nash inequality) of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Suppose that Assumption~\ref{a2-2} holds and suppose there exist $p, q \in (1, \infty]$ satisfying

  \begin{align}
    \frac{1}{p} + \frac{1}{q} \;<\; \frac{2}{d},
  \end{align}

  such that

  \begin{align}
    \sup_{R \geq 1} \Norm{\theta}{p, B(R)}
    \,+\,
    \sup_{R \geq 1} \Norm{\theta^{-1}}{1, B(R)}
    \,+\,
    \sup_{R \geq 1} \Norm{\nu}{q, B(R)}
    \;<\;
    \infty.


  \end{align}

  Then for every $m \geq 2$, there exists $C_{1} \in (0, \infty)$ such that

  \begin{align}
    \norm{f}{2}{\boldsymbol{V}, \theta}^2
    \;\leq\;
    C_{1} R_{1}^{m}\, \cM\, \cE(f)^{m/(m+2)}\,
    \norm{\eta^{m/2} f}{2}{\boldsymbol{V}, \theta}^{4/(m+2)},
  \end{align}

  where $\eta\colon \boldsymbol{V} \to [0, \infty)$ is defined by \eqref{e1-4}, $R_{1}$ is the same constant as in Assumption~\ref{a2-2} (associated with some $d'$) and

  \begin{align}
    \cM
    \;\ldef\;
    \sup_{R \geq 1} \Bigl(
      \Norm{1 \vee \theta}{p, B(R)}
      \cdot \Norm{1 \vee \nu}{q, B(R)}
      \,+\,
      \Norm{1 \vee \theta^{-1}}{1, B(R)}
    \Bigr).
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t:averaging set multivariate trigonometric polynomial of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $l,n_1,...,n_l\in\N, m_1,..,m_l\in\N_0$, and suppose that $p$ is a real-valued multivariate trigonometric polynomial of degree $(m_1,...,m_l)$. Then
    \begin{equation}
        \big\{p(2\pi j_1/n_1+u_1, ..., 2\pi j_l/n_l+u_l):j_k\in\{1,...,n_k\} \textnormal{ for } k\in\{1,...,l\}\big\}
    \end{equation}
    is an averaging set of $p$ of degree $\min_{j\in\{1,...,l\}}(\lceil\frac{n_l}{m_l}\rceil)-1$ for all $u\in\R^l$.

    Further, suppose that $p_1,...,p_d$ are real-valued multivariate trigonometric polynomials with degrees bounded by $(m_1,..., m_l)$. Then 
    \begin{equation}
        \left\{\begin{pmatrix}
            p_1(2\pi j_1/n_1+u_1, ..., 2\pi j_l/n_l+u_l)\\
            \vdots\\
            p_d(2\pi j_1/n_1+u_1, ..., 2\pi j_l/n_l+u_l)
        \end{pmatrix}:j_k\in\{1,...,n_k\} \textnormal{ for } k\in\{1,...,l\}\right\}
    \end{equation}
    is an averaging set of $(p_1,...,p_d)$ of degree $\min_{j\in\{1,...,l\}}(\lceil\frac{n_l}{m_l}\rceil)-1$ for all $u\in\R^l$.
    \begin{proof}
        Again, we only show the first assertion, as the second follows in the same way. Additionally, we only show it for a monomial with positive exponents, as the general case can be derived by symmetry and linearity afterwards. Hence, $p(x_1,...,x_l) = e^{im_1x_1+...+im_lx_l}$ for $x\in\R^l$. In this case,
        \begin{equation*}
            \frac{1}{(2\pi)^l}\int_{[0,2\pi)^l} e^{im_1x_1+...+im_lx_l}\, dx = \prod_{k=1}^l\frac{1}{2\pi}\int_0^{2\pi} e^{im_kx}\, dx,
        \end{equation*}
        and
        \begin{equation*}
            \frac{1}{n_1\cdots n_l}\sum_{\substack{j_k\in\{1,...,n_k\}\\\textnormal{for }k\in\{1,...,l\}}} e^{im_1(2\pi j_1/n_1+u_1)+...+im_l(2\pi j_l/n_l+u_l)} = \prod_{k=1}^l \frac{1}{n_k}\sum_{j=1}^{n_k} e^{im_k(2\pi j/n_k+u_k)},\quad u\in\R^l.
        \end{equation*}
        Now, we can derive the equality from the univariate case in Theorem~(t:averaging set trigonometric polynomial of the paper).
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:WishartConcentration of arXiv:2410.23915, 'Asymptotic Bounds and Online Algorithms for Average-Case Matrix Discrepancy'] Let $W$ be an $m \times m$ Wishart matrix of rank $r \leq m$. For $r \ll m$ holds
        \begin{equation*}
            \P{\abs{\frac{1}{rm^2}\left\lVert\ifblank{W}{\:\cdot\:}{W}\right\rVert_F^2 - 1} \leq \frac{1}{2}} \geq 1 - \exp{-\Omega(m)}.
        \end{equation*}
        The same statement also applies if $W$ is replaced by its centered version $\overline{W}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] We call an $ H $-valued, $ \mathbf{F} $-adapted, continuous stochastic process $ X(\cdot) $ a strong solution to (eqSEE of the paper) if 
    \begin{enumerate}[(i)]
        \item $X(t) \in D(A)$ for a.e. $(t, \omega) \in[0, T] \times \Omega$ and $A X(\cdot) \in L^1(0, T ; H)$ a.s.; 
        \item $F(\cdot, X(\cdot)) \in L^1(0, T ; H)$ a.s., $\widetilde{F}(\cdot, X(\cdot)) \in L_{\mathbb{F}}^{2}(0, T ; H)$;  
        \item For all $t \in[0, T]$,
        \begin{align*}
        X(t)=X_0 \!+\! \int_0^t(A X(s)+F(s, X(s))) d s+\int_0^t \widetilde{F}(s, X(s)) d W(s), \text{ a.s. }
        \end{align*}
    \end{enumerate}

[Defn def:non_iden of arXiv:2505.21770, 'Gradient-flow SDEs have unique transient population dynamics'] The SDE (equation eq:overdamped_langevin_SDE of the paper)
with parameters $(-\nabla \Psi_1, \sigma_1^2)$ is identifiable from its marginals $\bigl(p(\cdot, t)\bigr)_{t \in [0,T]}$ if and only if, $\forall (-\nabla \Psi_2, \sigma_2^2)$,
\begin{align*}
&\mathcal{L}^*_{-\nabla \Psi_1, \sigma_1^2}\bigl(p(\cdot, t)\bigr) = \mathcal{L}^*_{-\nabla \Psi_2, \sigma_2^2}\bigl(p(\cdot, t)\bigr) \qquad \forall t \in [0,T]\\ &\implies (-\nabla \Psi_1, \sigma_1^2) = (-\nabla \Psi_2, \sigma_2^2),

\end{align*}
where the first equality holds in the distributional sense and the second equality holds pointwise in $\mathbb R^d \times \mathbb R^+$.

