[Definition eq:Z-def of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[definition]{def:regularized-Z}
For a Borel measurable function \(V\) bounded below,
\(f\in\mathcal F_m\) or \(f=\ell_\eta\) with fixed \(\eta>0\), and
\(\varepsilon>0\), define
\begin{align}
 \mathcal Z_{N,L}^J(V,\varepsilon,f)
 :=\omega_N\int_{\mathcal O_{N,L}}
 &\exp\biggl\{-NV\bigl(h_J(O)\bigr)
 +\sum_{a=1}^n\log\kappa_\varepsilon\bigl(g_{a,J}(O)\bigr)\notag\\
 &\hspace{36mm}+\operatorname{Tr} f\bigl(A_J(O)\bigr)\biggr\}\,\nu_N(\,\mathrm d O).

\end{align}
Its annealed pressure is
\begin{equation}
 \Phi_{N,L}^J(V,\varepsilon,f)
 :=\frac1N\log\mathbb E\mathcal Z_{N,L}^J(V,\varepsilon,f).
\end{equation}

[Theorem thm:LSI:zergalinski of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Fix $n \in \mathbb{N}$ and $\lambda$ be a 1-MRF on $\ensuremath{\mathbb{R}}^{\mathbb{T}_2^n}$. Recall the notation $\mathbf{x}^{(n)}$ defined in Definition (def:results:Tn2 of the paper). For $v \in \mathbb{T}_2^n$ and $\mathbf{x}^{(n)} \in (\ensuremath{\mathbb{R}}^d)^{V_n}$, let $\hat{\mathbf{x}}_v := \{x_u\}_{u \neq v} \in (\ensuremath{\mathbb{R}}^d)^{2n}$. Denote the corresponding family of specifications (i.e. marginal conditional measures) of $\lambda$ by $ \lambda_v(x_v | \hat{\mathbf{x}}_v)$. 

     Suppose the following two properties hold.
    \begin{enumerate}
        \item Expressed in terms of the constant $C_{LS}$ from Definition (def:LSI of the paper), the specifications $\{\lambda_v\}_{v \in \mathbb{T}^n_2}$ satisfy the uniform log-Sobolev inequality,
        \begin{align*}
            \tilde{C}_{LS, n} = \sup_{v \in \mathbb{T}^n_2, \, \hat{\mathbf{x}}_v \in (\ensuremath{\mathbb{R}}^d)^{2n}} C_{LS}\Big(\lambda_v\big(\cdot \big| \hat{\mathbf{x}}_v\big)\Big) < \infty.
        \end{align*}
        \item There exist constants $c^n_{uv}(\lambda) \geq 0$ for every $u, v \in \mathbb{T}_2^n$, such that every smooth strictly positive function $f: \ensuremath{\mathbb{R}}^{\mathbb{T}_2^n} \rightarrow \ensuremath{\mathbb{R}}$ satisfies the following for all $\hat{\mathbf{x}}_v \in (\ensuremath{\mathbb{R}}^d)^{2n}$ :
        \begin{equation}

            \bigg | \nabla_{x_u} \sqrt{ \mathbb E^{\lambda_v}[f^2|\hat{\mathbf{x}}_v]}\bigg| \leq \sqrt{\mathbb E^{\lambda_v}[|\nabla_{x_u}f|^2|\hat{\mathbf{x}}_v]} + c^n_{uv}(\lambda) \sqrt{\mathbb E^{\lambda_v}[|\nabla_{x_v}f|^2|\hat{\mathbf{x}}_v]},
        \end{equation}
        where there exists $\delta \in (0, 1)$ such that
        \begin{equation}
            \sup_{u \in \mathbb{T}_2^n} \max\bigg\{ \sum_{v \in \mathbb{T}_2^n} c^n_{uv}(\lambda), \sum_{v \in \mathbb{T}_2^n} c^n_{vu}(\lambda)\bigg\} \leq \delta < 1.

        \end{equation}
    \end{enumerate} 
    Then $\lambda$ satisfies an LSI with constant
        \begin{align*}
            C_{LS}(\lambda) \leq \frac{\tilde{C}_{LS, n}}{(1 - \delta)^2}.
        \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lm:geo-ordering of arXiv:2604.12963, 'Shocks, instability, and the twenty networks\\ of infinite geodesics in the Directed Lands'] The following holds on a full $\mathbb{P}$-probability event. 
For all $s$, $x<y<z$, and 
$\theta$ in $\mathbb{R}$, 
and all ${\raisebox{-0pt}{\scaleobj{1.1}{\boxempty}}}\in\{-,+\}$ and $S\in\{L,M,R\}$:
\begin{align}
\Gamma_{{(x,s)}}\dir{R}{\theta}{{\raisebox{1.5pt}{\scaleobj{0.6}{\boxempty}}}}\preceq\Gamma_{{(y,s)}}\dir{L}{\theta}{{\raisebox{1.5pt}{\scaleobj{0.6}{\boxempty}}}}
\preceq\Gamma_{{(y,s)}}\dir{M}{\theta}{{\raisebox{1.5pt}{\scaleobj{0.6}{\boxempty}}}}
\preceq\Gamma_{{(y,s)}}\dir{R}{\theta}{{\raisebox{1.5pt}{\scaleobj{0.6}{\boxempty}}}}
