\end{align}

[Proposition 19 (evolution of the gradient; Li--Yau estimate) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Along the flow, each $u := f_i^2$ satisfies
		\begin{equation}
		\big( \partial_t - \Delta \big)\, \big| \nabla u \big|^2 \;=\; -\, 2\, \big| \nabla^2 u \big|^2 \,,
	\end{equation}
	and consequently the Li--Yau quantity \cite{LY} $| \nabla u |^2 / u$ is uniformly bounded:
		\begin{equation}
		\sup_{\widehat{M}} \frac{| \nabla u |^2}{u} (\cdot, t) \;\leq\; C_0 \;:=\; \max \left\{ \sup_{\widehat{M}} \frac{| \nabla u |^2}{u} (\cdot, 0) \,, \; 4\, p_i \right\} \qquad \text{for all } t \in [0, T) \,.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 of arXiv:2605.30560, 'Projected McKean--Vlasov Dynamics for Entropic Weak Optimal Transport'] Suppose $\mathcal{Y}$ is a Polish space. For $\rho,\sigma\in\mathcal{P}(\mathcal{Y})$, the \emph{relative entropy} is defined as 
\[
H(\rho\,\|\,\sigma)
\;:=\;
\begin{cases}
\displaystyle\int \log\frac{d\rho}{d\sigma}\,d\rho & \text{if } \rho\ll\sigma,\\[4pt]
+\infty & \text{otherwise.}
\end{cases}
\]

[Lemma lem:tech:1 of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] { Given $c,c'>0$, the following holds
\begin{equation*}
e^{-ct}\int_0^t e^{-(c'-c)r}\emph{d} r\le Ce^{-\tilde{c} t},\quad t\ge 0,
\end{equation*}
for some positive constants $C=C(c,c'),\tilde{c}=\tilde{c}(c,c')$ independent of $t$.}

