body:
[Lemma lem:Push-TASEP-dressing of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The kernel $K_{t,\mathbf{a},\mathbf{n}}$ is dressing
compatible (Definition~(def:sc-dressing of the paper)) with
$(\Psi, \Phi)$ and $z = 1$ for all $t > 0$,
$1 \leq n_1 < \cdots < n_m$, and
$a_i < y_{n_i}$ for every~$i$.
Explicitly:
\begin{align}
K_{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
- K_{t,\mathbf{a},\mathbf{n}}
&= \Psi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
   \Phi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}},
 \\
\partial_t K_{t,\mathbf{a},\mathbf{n}}
&= 2\Psi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
   \Phi^{t,\mathbf{a},\mathbf{n}},
 \\
K_{t,\mathbf{a},\mathbf{n}+\mathbf{1}}
- K_{t,\mathbf{a},\mathbf{n}}
&= 2\Psi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
   \Phi^{t,\mathbf{a},\mathbf{n}+\mathbf{1}}.

\end{align}

[Lemma 2 of arXiv:2606.23433, 'Emergence of Common Noise: Quantitative Conditional Propagation of Chaos'] Suppose that $\mathbf{A(\beta })$ holds for $\mathcal{X}$ and let $T>0.$ Let 
$0\leq s\leq t$ with $t-s\leq 1$ and $t\leq T,$ and consider a partition $
\pi =\{s=t_{0}<t_{1}<...<t_{n}=t\}$ and a proper sub-partition $\pi ^{\prime
}$ of $\pi .$

\noindent \textbf{A }There exists a constant $C$ not depending on $\pi ,$
such that for any $X\in L_{s}^{2}(H),$ 
\begin{equation}
\left\Vert \mathcal{X}_{s,t}^{\pi }(X)\right\Vert _{2}^{2}\leq C\left(
(t-s)+\Vert X\Vert _{2}^{2}\right).  
\end{equation}
\textbf{B } There exists a constant $C_{T}$ not depending on $\pi $ nor on $
\pi ^{\prime },$ such that for any $X^{1},X^{2}\in L_{s}^{2}(H),$ 
\begin{equation}
\left\Vert \mathcal{X}_{s,t}^{\pi }(X^{1})-\mathcal{X}_{s,t}^{\pi ^{\prime
}}(X^{2})\right\Vert _{2}^{2}\leq   C_{T}(\left\Vert X^{1}-X^{2}\right\Vert
_{2}^{2}+(t-s)\left( 1+\Vert X^{2}\Vert _{2}^{2}\right) \left\vert \pi
\right\vert ^{\beta }),  
\end{equation}
with $\left\vert \pi \right\vert =\max_{i=1,...,n}(t_{i+1}-t_{i}).$

