[Lemma 19 of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] Let $x \in [N]$, $c > 1$, and $\nu > 0$. Introduce
  \begin{equation}
    D^{\nc +}_{x} \deq \# \left( S_{1}^{+}(x)\setminus \cycV(x) \right)\,.
  \end{equation}
  With $\nu$-high probability,
  \begin{equation*}
    D_{x}^{\nc +} \leq c\frac{\nu}{1-\delta}\frac{\log N}{\log \log N}\,.
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 6 of arXiv:2607.15125, '2607.15125'] For every $a\in [-1,1]\setminus \{0\}$, define the maximal radius of convergence  in \Cref{form_solution} as \begin{equation*}
    \rho_a(x) \coloneqq \sup\left\{ r_a(x) \colon L_a(x,z) \text{ is analytic in } \abs{z} < r_a(x) \right\},
\end{equation*}where $r_a(x)$ is as defined in $\Cref{form_solution}$. Then $\rayon$ is given by $\rayon = 1/\fgd$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma compare of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] Let $a<b<c$. For any closed set $A$, we have 
    \begin{equation}
        R(p_{c}^A|_{\mathcal B_b\setminus A\times \partial \mathcal B_c\setminus A})\leq R(p_{b,c}^{A\cup\mathcal B_a})\quad\text{ and }\quad K(p_{c}^A|_{\mathcal B_b\setminus A\times \partial \mathcal B_c\setminus A})\leq K(p_{b,c}^{A\cup\mathcal B_a}).
    \end{equation}
    In particular, for any $d\leq b$, 
    \begin{equation}
        R(p_{d,c}^A)\leq R(p_{b,c}^{A\cup\mathcal B_a})\quad\text{ and }\quad K(p_{d,c}^A)\leq K(p_{b,c}^{A\cup\mathcal B_a}).
    \end{equation}

