[Lemma 24 of arXiv:2607.01629, 'Quadratic fluctuations of speed-change Kawasaki dynamics'] For test function $f$, we have
			\begin{equation*}
				\quad N^2\sum_{i=1}^d\sum_{x}\E_\rho\left[\mathcal R_{2}^N(f,x,i)^2\right]\leq C_fN^{-\gamma},
			\end{equation*}
			for some $\gamma>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Fix $\alpha>0$, $u>-\alpha$,  $|\tilde v|<\alpha$  such that $\tilde v<u$ and $k\geq 1$.
Let $\{Z_k\}_{k\ge 0}$ be the stationary half-line log-gamma polymer \eqref{Half-plane Z} with drift parameter $\tilde v$.
Then     for
  $u>t_1>t_2>\dots>t_k> |\tilde v|$, with $t_{k+1}=0$.
\begin{multline}
 \EE\left[\prod_{r=1}^k Z_r^{2t_{r+1}-2t_r}\right]
 \\= \tfrac{1}{\mathbf{C}_k(\vv t)}
 \int_{(0,\infty)^{k}}
\Big(\prod_{j=1}^{k-1}
\left|
\Gamma(t_j-t_{j+1}+\i y_j+\i y_{j+1})
\Gamma(t_j-t_{j+1}+\i y_j-\i y_{j+1})
\right|^2\Big)
\\ \cdot
 \Big(
\prod_{j=1}^k
\tfrac{|\Gamma(\alpha+t_j+\i y_j)|^2}
     {|\Gamma(2\i y_j)|^2}
\Big)
\left|\Gamma(t_k+\tilde v+\i y_k)\right|^2 \left|\Gamma(t_k-\tilde v+\i y_k)\right|^2
 |\Gamma(u-t_1+\i y_1)|^2    
\,\d \vv y ,
\end{multline}
where
\begin{equation*}
   \mathbf C_k(\vv t)=(2\pi)^k \Gamma(u+\tilde v)\Gamma(u-\tilde v) \Gamma(\alpha+\tilde v)^{k}
   \Gamma(\alpha-\tilde v)^{k}\prod_{j=1}^k \Gamma(2t_j-2t_{j+1}).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 of arXiv:2506.17470, 'The coalescent of a sample from a linear-fractional branching process'] Let $\tau$ be an ultrametric, oriented tree with $n$ tips and node depths $x_1, \dots, x_{n-1}\in \{1,\dots, T\}$. The likelihood function of the parameters $(p,r)$ given the outcome $\{\mathbf{T}^{p,r}=\tau\}$ is
   \begin{equation*} 
     \mathcal{L}(p, r \mid  \tau) := \mathbb{P}(\mathbf{T}^{p,r}=\tau)=\mathbb{P}(H>T)\prod_{i=1}^{n-1} \mathbb{P}(H = x_i).
   \end{equation*}
Moreover, the likelihood of $(p,r)$ conditioned on $\{N_T=n\}$ is given by
      \begin{equation*}
      \mathcal{L}(p, r \mid  \tau, n): = \mathbb{P}(\mathbf{T}^{p,r}=\tau \mid N_T = n)=\prod_{i=1}^{n-1} \frac{\mathbb{P}(H = x_i)}{\mathbb{P}(H\le T)}.
   \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem cas_1 of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] Assume ((drift of the paper)) to ((simple of the paper)). Then, the Green's density function $g^{z_0}$ of this process has the following asymptotics as $\alpha \to \alpha_0$ and $r\to\infty$.
\begin{itemize}
\item If $\alpha^* < \alpha_0 < \alpha^{**}$, then
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha \to \alpha_0}{\sim} 
 {c_{\alpha_0}}h_{\alpha_0}(z_0)\frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))}}{\sqrt{r}}.
  \end{equation}

  \item If $\alpha_0 < \alpha^*$, then
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha \to \alpha_0}{\sim} 
c^*h_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x(\alpha^*) + \sin(\alpha)y(\alpha^*))}.
  \end{equation}

  \item If $\alpha_0 > \alpha^{**}$, then
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha \to \alpha_0}{\sim} 
c^{**}h_{\alpha^{**}}(z_0) e^{-r(\cos(\alpha)x(\alpha^{**}) + \sin(\alpha)y(\alpha^{**}))}.
  \end{equation}
\end{itemize}
where ${c_{\alpha_0} = \frac{1}{\sqrt{2\pi(\cos(\alpha_0) + \sin(\alpha_0))}}}$, $c^*$ and $c^{**}$ are positive explicit constants only depending on the parameters of the degenerate reflected Brownian motion (see (equation eq:c* of the paper)) and where $h_{\alpha}(z_0), h_{\alpha^*}(z_0), h_{\alpha^{**}}(z_0)$ are harmonic functions given in Theorem (thm:main of the paper). Furthermore, $h_{\alpha}(z_0), h_{\alpha^*}(z_0), h_{\alpha^{**}}(z_0)$ are non-zero. (Proof in the paper; no proof environment follows the statement in the TeX.)

