body:
[Lemma 5 of arXiv:2609.01594, '2609.01594'] Let $A\in\Z$ with  $\abs A>2$.  Let $p$ be an odd prime, and let $r,n$ be positive
integers such that $p\mid u_r(A)$ and $p\mid u_n(A)$.  Then
\begin{equation}
 \nu_p(u_n(A))-\nu_p(u_r(A))=\nu_p(n)-\nu_p(r).
\end{equation}
In particular, if $p\mid u_n(A)$ then
\begin{equation}
 \nu_p(u_n(A))\geq \nu_p(n).
\end{equation}

[Lemma l:degree_ak_scaling of arXiv:2606.11503, 'Percolation on hierarchical lattices'] We have, for every $k \in \mathbb{N}$
  \begin{equation}
    \begin{pmatrix}
      \deg^{\mathrm{out}}_{k+1}(a_{k+1}) \\
      \deg^{\mathrm{in}}_{k+1}(a_{k+1})
    \end{pmatrix}
    =
    \begin{bmatrix}
      \deg^{\mathrm{out}}_{1}(a_{1}) & \deg^{\mathrm{out}}_{1}(b_{1}) \\
      \deg^{\mathrm{in}}_{1}(a_{1}) & \deg^{\mathrm{in}}_{1}(b_{1})
    \end{bmatrix}
    \begin{pmatrix}
      \deg^{\mathrm{out}}_{k}(a_{k}) \\
      \deg^{\mathrm{in}}_{k}(a_{k})
    \end{pmatrix}.
\end{equation}
  Furthermore, for every $k \in \mathbb{N}$,
  \begin{equation}
    \deg_{k}(a_{k}) \leq \big( |\mathcal{E}_{1}| - 2 \big)^{k}.
  \end{equation}
  The same relations hold for the degrees of $b_{k}$.

