[Theorem 11 (Dynamical equations) of arXiv:2607.16833, 'Dynamical Equations for Poisson Galton--Watson Trees and Component Densities of Sparse Inh'] Let $F:\cN_f(S)\to\mathbb R$ be bounded and supported on $\cN_N(S)$ for some
$N$.  Then $u\mapsto\int F\dd P_{\alpha,u}^{\Lambda}$ is continuously
differentiable on $(0,\infty)$, and
\begin{equation}
 \frac{\dd}{\dd u}\int F(\mu)P_{\alpha,u}^{\Lambda}(\dd\mu)
 =\int F(\mu)\left\{\frac{T(\mu)-1}{u}-A(\mu)\right\}
     P_{\alpha,u}^{\Lambda}(\dd\mu).
\end{equation}
Moreover,
\begin{equation}
 \int F(\mu)P_{\alpha,u}^{\Lambda}(\dd\mu)
 =\frac1u\int_0^u\int F(\mu){T(\mu)-sA(\mu)}
       P_{\alpha,s}^{\Lambda}(\dd\mu)\dd s.
\end{equation}
Equivalently, on every $\cN_N(S)$, in the sense of finite signed measures,
\begin{align}
 \frac{\dd}{\dd u}P_{\alpha,u}^{\Lambda}(\dd\mu)
 &=\left\{\frac{T(\mu)-1}{u}-A(\mu)\right\}
    P_{\alpha,u}^{\Lambda}(\dd\mu),\\
 P_{\alpha,u}^{\Lambda}(\dd\mu)
 &=\frac1u\int_0^u\{T(\mu)-sA(\mu)\}
    P_{\alpha,s}^{\Lambda}(\dd\mu)\dd s.
\end{align}
Let $I\subset(0,\infty)$ be a compact interval on which
$\sup_{s\in I}\bE_{\alpha,s}T_s<\infty$.  For every bounded $F$, the map
$u\mapsto u\int F\dd P_{\alpha,u}^{\Lambda}$ is absolutely continuous on $I$,
and \eqref{eq:weak-ODE} holds for Lebesgue-a.e. $u\in I$.  If the same moment
bound holds on $[0,u]$, then \eqref{eq:weak-integral} also holds for that $u$.
Here $T_s$ is an extended nonnegative random variable; in particular, the
moment assumptions in this paragraph imply $T_s<\infty$ almost surely at the
parameters under consideration.

