[Theorem of arXiv:2412.04334, 'Fractional counting process at L\'{e}vy times and its applications'] Let $\mathcal{N}_{\mu, \vartheta }^{\zeta ,\theta}(t)$ be the FCP and $\{Y_i, i\in \mathbb{N}\}$ be iid random variables having probability distribution function $G_Y$, 
	\begin{equation*}
\mathbb{P}\left[Y_{(k)}^{\mathcal{N}_{\mu, \vartheta }^{\zeta ,\theta}(t)}<x \;\big{|} \; \mathcal{N}_{\mu, \vartheta }^{\zeta ,\theta}(t)\geq k\right]= \frac{\mathbb{P}\left[\tilde{\mathcal{N}}_{\mu, \vartheta }^{\zeta ,\theta}(t)\geq k\right]}{\mathbb{P}\left[\mathcal{N}_{\mu, \vartheta }^{\zeta ,\theta}(t)\geq k\right]}, \;\;\;\; k\in \mathbb{N},
	\end{equation*}
	where $\tilde{\mathcal{N}}_{\mu, \vartheta }^{\zeta ,\theta}(t)$ is the FCP with parameter $\lambda_{\theta}G_Y >0$.

[Lemma lem:moment-boud:H^1_epsilon of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] Assume the hypotheses of~(thm:well-posed of the paper) and let $U_0=(u_0,\eta_0)\in \mathcal{H}^1_\mu$. Then
\begin{enumerate}
[noitemsep,topsep=0pt,wide=0pt,label=\arabic*.,ref=\theassumption.\arabic*]
\item For all $\beta$ sufficiently small independent of $\mu\in\mathcal{M}_\delta$, 
\begin{equation}
\mathbb{E} \exp\left({\beta\Psi_1(U(t))}\right)\le  e^{-c_{1,0}t}\exp\left({\beta C_{1,0}\Psi_1(U_0)}\right)+C_{1,0},\quad t\ge 0,
\end{equation}
where $\Psi_1(u,\eta)$ is as in (equation form:Psi_1 of the paper) and $c_{1,0}=c_{1,0}(\beta)>0$, $C_{1,0}=C_{1,0}(\beta)>0$ do not depend on $U_0$, $\mu\in\mathcal{M}_\delta$ and $t\ge 0$. 

\item For all $n\ge 1$, there exist positive constants $c_{1,n}$, $C_{1,n}$ independent of $U_0$, $\mu\in\mathcal{M}_\delta$ and $t\ge 0$ such that
\begin{equation}  
\emph{d} \Psi_1(U(t))^n\le -c_{1,n} \Psi_1(U(t))^n\emph{d} t+C_{1,n}\emph{d} t+C_{1,n}\Psi_0(U(t))^{n}\emph{d} t+\emph{d} M_{1,n}(t),
\end{equation} 
where $M_{1,n}(t)$ is the semi-martingale given by
\begin{equation} 
M_{1,n}(t)=\int_0^t n\Psi_1(U(r))^{n-1}\langle A^{1/2}u(t),A^{1/2}Q\emph{d} w(r)\rangle_H. 
\end{equation}
Furthermore,
\begin{equation} 
\mathbb{E}\Psi_1(U(t))^n \le C_{1,n}e^{-c_{1,n}t}\Psi_1(U_0)^n+C_{1,n},\quad t\ge 0.
\end{equation}
\end{enumerate}

