[Theorema WPFLS of arXiv:2608.30777, 'Inhomogeneous nonlinear Schr\"odinger equation \\ in Fourier-Lebesgue and modulation space'] \
\begin{enumerate}
\item Gr\"unrock [Grunrock] proved (equation NLS of the paper) is:
\begin{itemize}
    \item[-] LWP for $\alpha=3$ and $1<p<\infty$. 
    \item[-] GWP  for $\alpha=3$ and $5/3<p<2$. 
\end{itemize}    
    \item Hyakuna-Tsutsumi [hyakuna2012existence] proved (equation NLS of the paper) is:
    \begin{itemize}
     \item[-] LWP for $\alpha \in (1,5)$, $4/3<p<2$ or $2<p<\infty.$ 
    \item[-] GWP for $\alpha \in (1,5)$, $4/3<p<2$ or $2<p<\infty,$ with $p$ sufficiently close to 2.    
\end{itemize}
\item Masaki-Segata [Masaki1] established LWP for $4/3<p<4$ and $p=\alpha+1$.
\item Bhimani-Carles [BhimaniNorm] proved (equation NLS of the paper) is
\begin{itemize}
    \item[-] strong ill-posedness below the expected critical regularities ($s<s_{c}$).
\item[-] norm inflation with infinite loss of regularity. 
\end{itemize}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 7 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] Fix $\La > 0$. Suppose $N$ is sufficiently large such that
	\begin{equation} 
		N^{dm\beta} \geq 4(m+1)\La^{m}.
	\end{equation}
	Let $\mathcal{S}_{N}=\mathcal{S}_N[A]$ be as defined in \eqref{e.SN} with $A(u)=u^{m+1}$. For $n\in \N$, let $\mathcal{S}_{N}^{n}$ be the $n$-fold composition of $\mathcal{S}_{N}$. Then the following holds,
	\begin{enumerate}[(i)]
		\item The scheme $\mathcal{S}_{N}$ is monotone on $L^{\infty}(\xmesh \Z^{d})\cap \mathcal{B}^{+}_{\La}(\R^{d})$.
		\item For $w \in L^{\infty}(\xmesh \Z^{d})\cap\mathcal{B}^{+}_{\La}(\R^{d})$, for any $n\geq 1$, 
		\begin{equation*}
		\norm{\mathcal{S}_{N}^{n}w}_{L^{\infty}(\xmesh \Z^{d})}\leq \norm{w}_{L^{\infty}(\xmesh \Z^{d})}
		\end{equation*}
		and thus $\mathcal{S}_{N}^{n}\in L^{\infty}(\xmesh\Z^{d})\cap\mathcal{B}_{\La}^{+}(\R^{d})$.
		\item For $w, w' \in L^{1}(\R^{d}) \cap \mathcal{B}^{+}_{\La}(\R^{d})\cap L^{\infty}(\xmesh\Z^{d})$,
		$$\norm{\mathcal{S}_{N}^{n}w - \mathcal{S}_{N}^{n}w'}_{L^{1}(\R^{d})} \leq \norm{w - w'}_{L^{1}(\R^{d})}.$$

	\end{enumerate}

