[Lemma 7 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] We have the following identities (under Assumption 1).
		\begin{enumerate}
			\item For any $n_1,n_2\in\bfN^{d+1}$
			\begin{equation}
			D^{n_1} D^{n_2} = D^{n_1+n_2},  \quad 
			\downarrow^{n_1}\hspace{-1pt} \downarrow^{n_2}\hspace{-0pt} = \downarrow^{n_1+n_2}, \quad 
			\downarrow^{n_1}D^{n_2} = D^{n_2}\downarrow^{n_1}.
		\end{equation}
			\item  For any $\tau\in T \sqcup T^+$,  $\sigma\in\mcB^+$ and $n\in\bfN^{d+1}$
			\begin{equation} 
				\downarrow^n(\tau/\sigma) = (\downarrow^n\tau)/\sigma.
			\end{equation}
			\item  We have the Leibniz rules
			\begin{equation} 
			\begin{aligned}	D^n(\tau_1\tau_2) & = \sum_{n=n_1+n_2} \binom{n}{n_1}  D^{n_1}\tau_1 \, D^{n_2}\tau_2,
			\\
				\downarrow^n\hspace{-2pt}(\tau_1\tau_2) & = \sum_{n=n_1+n_2} \binom{n}{n_1} \downarrow^{n_1}\hspace{-2pt}\tau_1 \, \downarrow^{n_2}\hspace{-2pt}\tau_2.
				\end{aligned}
			\end{equation}
			\item For any $n\in\bfN^{d+1}$ and $\tau\in T$, we have the commutation relations
			\begin{equation*} 
				\Delta D^n\tau = (D^n\otimes\id)\Delta \tau, \quad \text{and}\quad
				\Delta \downarrow^n\tau = (\id \, \otimes \downarrow^n)\Delta \tau.
			\end{equation*}
			The same holds true for $\tau \in \CT^+$ and $\Delta$ replaced by $ \Delta^{\!+} $.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:third-bound of arXiv:2511.01058, 'Limit profiles and cutoff for the Burnside process on Sylow double cosets'] For \(p \ge 11\) and \(k \le a < 2k\),
        \begin{equation}
            \frac{f(a;k)}{f(2k;k)} \le \frac{2p^3}{(p-1)!}
        \end{equation}

[Theorem thm:hopf-square of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] With $X$ as in (prop:ito-sums of the paper) and $\mathrm{Sig}^M(X)=\mathrm{Sig}(X^{\mathrm{PL}})$ the signature of its chord interpolation, equivalently the Marcus lift,
\begin{equation}
\mathrm{Sig}^M(X)=\Phi\big(\mathrm{Sig}^I(X)\big).
\end{equation}
Equivalently, $\mathrm{Sig}^M$ is a shuffle character and the square
\begin{equation}
\begin{array}{ccc}
(z_1,\ldots,z_n) & \xrightarrow{\ \mathrm{iterated\ sums}\ } & \mathrm{Sig}^I\quad(\mathrm{quasi\mbox{-}shuffle})\\[1.5mm]
\big\downarrow{\scriptstyle\mathrm{chord\ fill}} & & \big\downarrow{\scriptstyle\Phi}\\[1.5mm]
X^{\mathrm{PL}} & \xrightarrow{\ \mathrm{iterated\ integrals}\ } & \mathrm{Sig}^M\quad(\mathrm{shuffle})
\end{array}

\end{equation}
commutes.

