[Proposition 12 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Suppose $p \ge 2$ and $d(p-1) < 2p$. The distributions $t^{-p} \widetilde{\ell}_t^{\otimes p}$ satisfies an LDP in $(\widetilde{\mathcal{X}}(\mathbb{R}^d), \mathbf{D})$ defined in \eqref{eq:MV-set}, \eqref{eq:MV-metric} with good rate function
    \begin{equation}

        \mathcal{I}^{\ell} (\zeta) = \begin{cases}
            \mathcal{I}(\xi^{\otimes p}) & \text{if } \mathcal{I}(\xi^{\otimes p}) < \infty \text{ and }\prod\limits_{j=1}^p \psi_i^j = \sqrt{\frac{d\gamma_i}{d x}} \\
            \infty & \text{otherwise},
        \end{cases}
    \end{equation}
    where $\zeta = \{ \widetilde{\gamma}_i\}_{i \in I} \in \widetilde{\mathcal{X}}(\mathbb{R}^d)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 67 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Under Assumption \ref{assumption 8.24.1}
for any $\lambda\geq \varkappa_{0}^{2}\rho_{b}^{-2}$ and   Borel nonnegative $f(x)$  
we have on $\{\tau<\infty\}$
\begin{equation}

 E_{\cF_{\tau}}\int_{0}^{\infty}e^{- \lambda s}
f( x_{\tau+s}-x_{\tau}) \,dt\leq 
N(\sfp_{0})\ell\lambda^{-\alpha-1/q} \|\Psi_{\lambda}  f\|_{L_{p}(\bR^{d})},
\end{equation}
where $\Psi _{\lambda}( x)=\exp(- \sqrt{\lambda}  |x|\sfp_{0}/16)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 95 of arXiv:2511.20322, 'Dissertation'] Assume \assref{assum:H} and \assref{assum:barHandSi}. Further, assume we are given $\cR\in \dC \infty(\R^d)$, such that $\bar f = -\nabla \cR$ and $\nabla X_t^0$ is a symmetric matrix for all $t\geq 0$ and initial values. Let $x \in \R^d$, $D\in \set{0, \Si(X_\infty^0), \Si}$ and\footnote{In the case $D = \Si(X_\infty^0)$ we implicitly assume that the limit $X_\infty^0$ exists.} consider the solution $X$ to the family of \tSDE s 
	\[dX_t^h = - \nabla \cR(X_t^h)\,dt + \sqrt{h D(X_t^h)}\,dW_t, \quad X_0^h = x,\quad  t\in [0,T], h\in (0,1).\]
	Then we have
	\begin{align}

		\LE(X) = &\frac 12 \innp{\nabla^2 \cR(X_T^0)}{\al_T^D - T\nabla \cR(X_T^0)^{\otimes 2}} + \frac 12 \innp{\nabla \cR(X_T^0)}{\be_T^D},
	\end{align}
	where 
	\begin{align*}
		\al_T^D = & \int_0^T \nabla X_T^{0,t}(X_t^0) (\Si(X_t^0) - D(X_t^0))  \nabla X_T^{0,t}(X_t^0)\,dt \in \R^{d\times d}, \\
		\be_T^D = &\int_0^T \innp{\nabla^2 X_T^{0,t}(X_t^0)}{\nabla\cR(X_t^0)^{\otimes 2} + \Si(X_t^0) - D(X_t^0)}\,dt \in \R^d.
	\end{align*}
	Moreover,
	\begin{align}

		2|\LE(X)| \leq &d T M_T^2 |\nabla \cR(x)|^2 (|\nabla^2 \cR(X_T^0)| + d^{3/2}|\nabla \cR(x)| \zeta_T) \nonumber\\
		& + d\xi_T^D (|\nabla^2 \cR(X_T^0)| + \sqrt d |\nabla \cR(x)| \zeta_T),
	\end{align}
	where 
	\begin{align*}
		M_t =  \exp\left(-\int_0^t \la_{\min}(\nabla^2 \cR(X_s^0))\,ds\right), & \quad \zeta_t =  \int_0^t M_s |\nabla^3 \cR(X_s^0)|\,ds, \\
		\xi_t^D =  M_t^2 \int_0^t \frac{|\Si(X_s^0) - D(X_s^0)|}{M_s^2}\,ds&, \quad t\in [0,T].
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 31 (the fiber-collapsing case) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Suppose $(\widehat{M}, g(t))$ encounters the finite-time singularity at $T = T_F' < \min_{k \geq 2} \{T_k^0, T_k^\ell\}$. Take $K_j := \big[ 2 ( m + 2 ) ( T - t_j ) \big]^{-1}$, and fix any base point $x_j \equiv \bar{x} \in \widehat{M}$. Define $g_j(t) = K_jg(t_j + K_j^{-1}t)$, where $t \in [-K_jt_j, K_j(T-t_j))$. Then, along a subsequence,

\begin{equation}
\big( \widehat{M}, \; g_j (t), \; \bar{x} \big) \;\longrightarrow\; \Big( \mathbb{CP}^{m+1} \times \mathbb{C}^{n'} \,, \;\; g_{\mathrm{FS}} (t) \oplus g_{\mathbb{C}^{n'}} \Big) \,, \qquad t \in \Big( - \infty, \tfrac{1}{2 ( m + 2 )} \Big) \,,
\end{equation}
in $C^\infty$-Cheeger-Gromov sense, where $g_{\mathbb{C}^{n'}}$ is the flat metric on $\mathbb{C}^{n'}$ with $n' = \dim_{\mathbb{C}}\widehat{M} - (m+1)$, and $g_{\mathrm{FS}} (t)$ is the shrinking Fubini--Study metric.

