body:
[Definition distribution_Mallows of arXiv:2412.07258, 'Permuton limit of a generalization of the Mallows and $k$-card-minimum models'] Let $n \in \mathbb{N}$ and $q \in \mathbb{R}_+\setminus \{1\}$.
    The $(n,q)$-Mallows model can be generated as in Definition (def_gen_perm_model of the paper) if
        we sample $C^{(n),i}$ according to the truncated geometric distribution
\begin{align}
        \mathbb{P}(C^{(n),i} = l) = \frac{q^{l-1} - q^{l}}{1-q^{n-(i-1)}}, \qquad l=1,\dots, n-(i-1).
        \end{align}

[Lemma lem:xi2-lower of arXiv:2609.01311, 'One-Layer Transformer Provably Learns Multiclass\\ One-Nearest Neighbor in Context'] For $\xi_1^t \ge 0$,
\begin{equation*}
\tfrac{1}{\eta}\big(\xi_2^{t+1} - \xi_2^t\big)
\ge \tfrac{K-1}{K}\cdot\tfrac{1}{(N+1)^3 e}\, e^{2 a_{N,d}\xi_1^t - 2\xi_2^t}.
\end{equation*}

[Proposition prop:CSZ20 of arXiv:2608.30829, 'Free energy and phase transition for\\ 2D directed polymers with critical spatial correlat'] Assume $\hat \omega=(\hat \omega_i)_{i \in \mathbb{N}}$ is a sequence of i.i.d.\ standard Gaussian random variables. There exist constants $c_1,c_2\in (0,\infty)$ such that, for any $n \in \mathbb{N}$ and for any differentiable and convex function $f : \mathbb{R}^n \to \mathbb{R}$, the following bound holds for any $b \in \mathbb{R}$ and $t,c \in (0,\infty)$:
    \begin{equation}

      \mathbb{P} \big(\, f(\hat \omega) \le b-t \,\big)\mathbb{P} \big(\, f(\hat \omega) \ge b \,, \ |\nabla f(\hat \omega)| \le c\, \big) \le c_1 \exp \Big\lbrace - \frac{(t/c)^2}{c_2} \Big\rbrace\,,
    \end{equation}
    where $\hat \omega=(\hat \omega_1,\ldots,\hat \omega_n)$ and $|\nabla f(\hat \omega)|=\sqrt{\sum_{i=1}^n (\frac{\partial}{\partial \hat \omega_i} f)^2}$ is the norm of the gradient. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 36 of arXiv:2605.02002, 'Glauber dynamics for random field Ising models on bounded degree graphs and MLSI'] (\cite{el2026fast}, Lemma 3.5)
    Consider a Glauber dynamics with discrete-time Markov chain $(\sigma_k)_{k\geq 0}$. Let $\pi_k$ be the distribution of $\sigma_k$ and $\pi_\infty=\mu_G$ be the invariant measure. Suppose that $\pi_\infty$ satisfies the following weak conductance bound
    \begin{equation}
\pi_\infty(S)(1-\pi_\infty(S))\leq AQ(S,S^c)^{1/p},\quad\forall S\subseteq \{-1,1\}^V,        
    \end{equation}
    where $p\geq 1,A^p\geq 2/4^{p-1}$, and the following warm start condition holds:
    \begin{equation}
    \max_{S\subseteq \{-1,+1\}^V}\frac{\pi_0(S)}{\pi_\infty(S)}\leq M,
    \end{equation} then 
    \begin{equation}
 d_{\operatorname{TV}}(\pi_k,\pi_\infty)\leq M(\frac{A^{2p}\log k}{k})^{1/(2p-1)}       ,\quad k\geq 1.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

