[Theorem 2 of arXiv:2608.13732, '\textbf{On the First Hitting Time Problems \\ for Diffusion Processes: \\ Local Time-Space'] The function $f(t)$ satisfies the linear Volterra integral equation of the first kind
\begin{align}
\mathbb{P}_{T-t,b(t)}\!\left(Y_T>b(0)\right)
=
-\frac{1}{2}
\int_0^t
f(u)\,
q(T-u,b(u);T-t,b(t))
\,du
\end{align}
for $t\in[0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor sufficient-inequalities of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $({\mathbf{a}},{\mathbf{b}})$ be a non-degenerate weight pair and assume that $r=r({\mathbf{a}})$ is finite.
	Assume that the following inequalities hold for all $n\geq 0$ and all $\ell\in\{0,\dots,r-1\}$,
	\begin{equation}
	\frac{b_{n+1}}{b_{n}}
	\leq
	\frac{
		\PFComp{\shift{\ell}{\mathbf{a}},{\mathbf{b}}}{n+1}
	}{
		\PFComp{\shift{\ell}{\mathbf{a}},{\mathbf{b}}}{n}}
	\leq
	\frac{b_{n+2}}{b_{n+1}},
	\end{equation}
	where we omit the ill-defined inequality on the left when $n=0$.
	Then $({\mathbf{a}},{\mathbf{b}})$ is admissible, as well as the pairs $(\shift\ell{\mathbf{a}},{\mathbf{b}})$ for $\ell=0,\dots,r-1$.

[Prop P: properties of L of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Under the assumption that $\mathbf{P}\{f_{+},f_{-} \in \mathcal{S}\} = \mathbf{P} \{ f_{+}(+\infty) = f_{-}(+\infty) = 0 \} = 1$, the function $\mathscr{L}$ has the following two properties:
		\begin{itemize}
			\item[(i)] $(\mathscr{L}F)(+\infty) = (\mathscr{L}F)(-\infty) = 0$ for each $F \in CDF(\overline{\mathbb{R}})$.
			\item[(ii)] Given $F,G \in CDF(\overline{\mathbb{R}})$, if the difference $F - G$ is a constant function, then $\mathscr{L}F = \mathscr{L}G$.
		\end{itemize}
	In particular, $T$ maps constant functions to constant functions: Its action on constants is determined by the dynamical system 
		\begin{align*}
			T q - q =  (1 - 2p) q ( 1 - q) \quad \text{for each} \, \, q \in [0,1].
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2605.13518, 'The inertial It\^{o} drift and its applications to particle collision'] Assume that \eqref{smf105-bis} holds for $\alpha \in\,(0,+\infty)$ and that $x_n$ converges to $x$ in $C([0,T];\mathbb{R}^d)$, $\mathbb{P}$-a.s. Then, 
for every  Lipschitz-continuous and bounded function $g:\mathbb{R}^d\to\mathbb{R}$ and every $l, j=1,\ldots,d$ and $k=1,\ldots,n$ we have
\begin{equation}

\lim_{n\to \infty}\mathbb{E}\sup_{t \in\,[0,T]}\left| \alpha_n\int_0^t g(x	_n(s))[\tilde{u}_n(s)]_l[\tilde{u}_n(s)]_j\,ds-\int_0^t g(x(s))[\alpha N_\alpha(x(s))]_{l,j}\,ds\right|=0,
\end{equation}
and
\begin{equation}

\lim_{n\to \infty}\mathbb{E}\sup_{t \in\,[0,T]}\left|\int_0^t g(x	_n(s))[\tilde{u}_n(s)]_l[\tilde{z}_n(s)]_k\,ds-\int_0^t g(x(s))\,[L_\alpha(x(s))]_{l,k}\,ds\right|=0.
\end{equation}

