[Proposition prop:feasibility of arXiv:2605.19894, 'Sharp Spectral Thresholds for Multi-View Spiked Wigner Models'] \begin{itemize}
        \item[(i)] For any fixed $\Gamma\in\mathsf{Sym}_L(\RR)$ and any $z\in\CC^{+}$, (equation eq: self-consistent eq matrix of the paper) admits a unique valid solution $M(z;\Gamma)\in\mathsf{Sym}_L(\CC)$.

        \item[(ii)] For any fixed $\Gamma\in\mathsf{Sym}_L(\RR)$, there exists a compactly-supported $\mathsf{Sym}_L^+(\RR)$-valued measure $\xi_{\Gamma}$ such that $\xi_{\Gamma}(\RR)=B$, and for any $z\in\CC^+$,
        \begin{equation}
            M(z;\Gamma) = - \int_{\RR} \frac{\xi_{\Gamma}(\ud \tau)}{\tau-z} \in \mathsf{Sym}_L(\CC).
        \end{equation}

    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2609.03793, 'Typical martingale diverges on a co-$\sigma$-porous set'] Let $\f,\g\in\M_\infty$ and $\nu\in 2^\N$. Let also $r>d>0$ be such that 
\begin{equation*}
\osc (f_n(\nu))\leq d\hspace{30pt}\text{and}\hspace{30pt}\osc(g_n(\nu))\geq r.
\end{equation*}
Then it holds that
\begin{equation*}
\osc(f_n+g_n)(\nu)\geq r-d.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:critical-log of arXiv:2607.08551, 'Weighted-threshold Coupon Collection'] Fix $\theta\in(0,1)$. Then
\begin{equation}
    \frac{\log\bigl(\lambda \tau_{N,\theta}^{(1)}/H_N\bigr)}{\log N}
\xrightarrow[N\to\infty]{\mathbb{P}}
\theta.    
\end{equation}
In particular,
\begin{equation}
    \frac{\log \tau_{N,\theta}^{(1)}}{\log N}
\xrightarrow[N\to\infty]{\mathbb{P}}
\theta.
\end{equation}

