[Corollary cor:optimal-finite-modeling of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For all $h\geq1$ and $k\geq2$,
\begin{equation}
 \mathcal R_{\mathbb R}(h,k)=\mathcal R_{\mathbb Q}(h,k)=\mathcal R(h,k),
\end{equation}
and
\begin{equation}
 1+\left\lceil\frac{M_{h,k}-1}{h}\right\rceil
 \leq N(h,k)
 \leq 1+\max\left\{(k-2)h^{k-2},
                    \sum_{j=0}^{k-2}h^j\right\}.
\end{equation}
Consequently, for every fixed $k\geq2$,
\begin{equation}
 N(h,k)=\Theta_k(h^{k-2}).
\end{equation}
More finely, if
\[
 \nu_{h,k}(n)=\min\{\operatorname{ndiam}(A):A\subset\mathbb Z,\ |A|=k,\ |hA|=n\},
\]
then
\begin{equation}
 \nu_{h,k}(n)
 \leq\bigl(k-1-r_{h,k}(n)\bigr)h^{k-2}
 \qquad(n\in\mathcal R(h,k)).
\end{equation}

[Lemma 7 of arXiv:2609.01333, '2609.01333'] For $i\in \{0,1\}$ we let $n\geq i$ and define

\begin{align*}
B_n = \frac{\sqrt{\pi}\,\Gamma\left(\frac{n}{2}\right)}{2\,\Gamma\left(\frac{n+1}{2}\right)} \qquad \text{and} \qquad C^i_n = \int_{0}^\infty r^{n} K_i(r) \mathrm{d}r.
\end{align*}
Then, the following asymptotic limits hold
\begin{align*}
&\lim_{\beta\to \infty} \beta^2(\beta^{n+1}T^i_n(\beta)- 2C^i_n)= 2^{-2}C^i_{n+2},\\
&\lim_{\beta\to 0} (T^1_n(\beta)-2^{n+1}B_n \beta^{-1})=0,\\
&\lim_{\beta\to 0} (T^0_n(\beta)+ 2^{n+2}B_{n+1} (\log(\beta)+\gamma_e))=-2^{n+2}\frac{d}{d n} B_{n+1}.
\end{align*}
In particular we find that
\begin{align}

T_n^i(\beta) &\sim  2\beta^{-n-1}C_n^i  +2^{-2}\beta^{-n-3}C_{n+2}^i
&&\textrm{ as $\beta\to \infty$},\\

T^1_n(\beta) &\sim 2^{n+1}B_n\beta^{-1}\quad \text{and}\quad T^0_n(\beta) \sim
-2^{n+2} B_{n+1}\log(\beta)
&&\textrm{ as $\beta\to 0$}.
\end{align}

[Definition 76 of arXiv:2601.16377, '2601.16377'] We say that $\boldsymbol{\ell}$ has no holes in $[\mathfrak{a},\mathfrak{b}]$ if all spacings between particles indexed by $I$ and their immediate neighbors are minimal. In more detail, $I$ should be nonempty and
the following three conditions should be satisfied
\begin{enumerate}
\item Bulk: $\forall i \in \llbracket i_0+1,i_0 + \#I-1\rrbracket\quad \ell_{i + 1} = \ell_i + \theta_{h,h}$.
\item Left boundary: either\footnote{If $i_0=0$ and $a_1=-\infty$, then there is no way for this condition to be satisfied and there is no way for $\boldsymbol{\ell}$ to have no holes.} $\ell_{i_0+1}= a_h$ or $\ell_{i_0+1}=\ell_{i_0}+\theta_{h,h}$.

\item Right boundary: either\footnote{If $i_0+\#I=N$ and $b_H=+\infty$, then there is no way for this condition to be satisfied and no way for $\boldsymbol{\ell}$ to have no holes.}
$\ell_{i_0 + \#I}=b_h$ or $\ell_{i_0+\# I+1}= \ell_{i_0 + \#I}+\theta_{h,h}$.
\end{enumerate}

[Definition 3 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] For $0 < \delta \le \eps \le 1$, we let $\pi^{\eps, \delta} : \mfL_- \to C^\infty(\mathbb{R}^2)$ be the smooth, stationary random noise assignment defined by
	\begin{align*}
		\pi^{\eps,\delta} \<b0> = \xi_\eps, \quad \pi^{\eps,\delta} \<p0> = \xi_{\delta}, \quad \pi^{\eps,\delta} \<0t> = \eps^{-1/2} \xi_{\eps, \delta}
	\end{align*}
	where we have written $\xi_{\eps, \delta} = \xi_\eps - \xi_{\delta}$. 

	We let $Z^{\eps, \delta} = (\Pi^{\eps, \delta}, \Gamma^{\eps, \delta})$ denote the corresponding BPHZ model, as introduced in \cite[Theorem 6.18]{BHZ}.

[Theorem 2 of arXiv:2609.03961, 'On the exponential sum over squarefree integers'] Let $N\ge2$ and $1\le Q\le N^{1/2}$.  Then
\begin{equation}
  \sup_{\alpha\in\Minor(Q)}|S(\alpha)|\ll\frac NQ(\log 2N)^{5},
\end{equation}
where the implied constant is absolute. (Proof in the paper; no proof environment follows the statement in the TeX.)

