[Lemma lem-entrident of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] For any box $W\Subset \mathbb{R}^d$ and any $\xi\in{\mathcal M }_1({\mathcal L }_W)$, 
\begin{equation}
\begin{aligned}
H&_{{\mathcal L }_W}\big(\xi\mid \Pi_W^{{{\scriptscriptstyle{({\mathcal L }})}}}({\tt Q})\big)\\
&=|W|\,H\big((m_k)_k\,\big|\, \smfrac 1{|W|} (q_{k})_k\big)+ H_{{\mathcal L }_W}\Big(\xi\,\Big|\,\bigotimes_{k\in\mathbb{N}} \Pi_{k}(\xi)\Big)\\
&\quad +  \sum_{k\in\mathbb{N}} H_{\mathbb{N}_0}(\Pi_k(\xi)\circ  \mathfrak N_W^{-1}\mid {\rm Poi}_{m_k|W|})\\
&\quad + \sum_{k\in\mathbb{N}}\sum_{n\in\mathbb{N}} \Pi_k(\xi)(\mathfrak N_W=n)\, H\big(\Pi_{k}^{{{\scriptscriptstyle{({n}})}}}(\xi)\circ (\zeta_k\cap W)^{-1}\mid \overline {\rm Leb}_W^{\otimes n}\big)\\
 &\quad + \sum_{k\in\mathbb{N}}\sum_{n\in\mathbb{N}_0}\int \Pi_k^{{{\scriptscriptstyle{({n}})}}}(\xi)(\zeta_k\cap W \in {\rm d} A)\,\Big[ H\Big(\Pi_k^{{{\scriptscriptstyle{({A}})}}}(\xi)\,\Big|\, \bigotimes_{x\in A} \Pi_{k,x}^{{{\scriptscriptstyle{({A}})}}}(\xi)\Big)+ \sum_{x\in A} H\big(\Pi_{k,x}^{{{\scriptscriptstyle{({A}})}}}(\xi) \mid \overline \mu _{x,x}^{\ssup{W,k,{\rm par}}}\big)\Big],
\end{aligned}
\end{equation}
where we  abbreviate $m_k=m_{W,k}(\xi)$ and $q_k=m_{W,k}(\Pi_W^{{{\scriptscriptstyle{({\mathcal L }})}}}({\tt Q}))$ and denote by $\Pi_k, \Pi_k^{{{\scriptscriptstyle{({n}})}}}, \Pi_k^{{{\scriptscriptstyle{({A}})}}}, \Pi_{k,x}^{{{\scriptscriptstyle{({A}})}}}\colon {\mathcal L }_W\to{\mathcal L }_W^{{{\scriptscriptstyle{({k}})}}}$ the projections on the set of loops of length $k$, respectively on the set of configurations in $W$ with precisely $n$ loops of length $k$ and no loops else, respectively on the set of configurations of loops of length $k$ with set of initial sites equal to $A\subset W$.

