[Theorem 5 of arXiv:2608.23301, 'On a Telegraph Process with Generalized Mittag-Leffler Waiting times and Velocity Driven b'] Conditional on the event that initial velocity is $v_1$, the expected velocity is given by
		\begin{equation*}
			\mathbb{E}(V_{\alpha}(t)|V_{\alpha}(0)=v_1)=v_1 E_{\alpha}(-\lambda t^\alpha)+v_1p\sum_{n=1}^{\infty}\psi_n(t|v_1)-v_2(1-p)\sum_{n=1}^{\infty}\xi_n(t|v_1),
		\end{equation*}
		where 
		{\small\begin{align*}
			\psi_n(t|v_1)
			&=\lambda\sum_{k=0}^{n-1}\binom{n-1}{k}(k+1)p^{k}(1-p)^{n-k-1}\sum_{i=0}^{n-k-1}\sum_{j=0}^{k}(-1)^{i+j}\binom{n-k-1}{i}\binom{k}{j}\nonumber\\
			&\hspace{1.5cm} \cdot\big(H^{\alpha}_{\alpha,1}(-\lambda(j+1),-\mu i;t)-\lambda(n+1)G^{\alpha}_{\alpha,1,\alpha}(-\lambda(j+1),-\mu i,-\lambda(n+1);t)\big)
		\end{align*}}
		and
		{\small\begin{align*}
			\xi_n(t|v_1)
			&=\lambda\sum_{k=0}^{n-1}\binom{n-1}{k}(k+1)p^{k}(1-p)^{n-k-1}\sum_{i=0}^{n-k-1}\sum_{j=0}^{k}(-1)^{i+j}\binom{n-k-1}{i}\binom{k}{j}\nonumber\\
			&\hspace{1.5cm} \cdot\big(H^{\alpha}_{\alpha,1}(-\lambda(j+1),-\mu i;t)-\mu(n+1)G^{\alpha}_{\alpha,1,\alpha}(-\lambda(j+1),-\mu i,-\mu(n+1);t)\big).
		\end{align*}}

