[Proposition prop:firstboundongradsth2 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] There exists  $0<C_\star<C_2$ such that if $t\in [0,1)$  and $x\in \mathbb{R}^d$ satisfy \begin{equation}
1-t^2\leq C_\star^{-1}\log(\epsilon^{-1})^{-C_\star} \text{ and } \|tx\|^2\leq 1-C_2^{-1}\log(\epsilon^{-1}+1)^{-K},
\end{equation}
    then for all $f\in L^2(\mathbb{R}^d)$, $i\in \{1,2\}$ and $\xi\in \mathbb{R}^d$, we have
    \begin{align*}
    \|\int f(y) \nabla_x^i p^{t,x}(y)d\lambda^d(y)\| 
    &\leq \frac{Ct^i}{(1-t^2)^{i/2}}\left(\int \|f(y)-\xi\|^2dp^{t,x}(y)\right)^{1/2}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:lowerboundLRW of arXiv:2607.10801, 'Relaxation times of non-reversible\\ Markov processes'] There exists a universal constant $C\in (0,\infty )$ such that for all $d,n\in\mathbb N$ with $n\ge 2$ and all $\gamma\in (0,\infty )$, 
     \begin{equation}
      s(\mathcal{L} )\ \le \   C\cdot d^{-1}\cdot\min\Big({n^{-2}\max (1,\gamma^{-1} )},{\gamma}\Big)\  \,.
    \end{equation}

[Theorem 1 of arXiv:2608.06392, '2608.06392'] Suppose that the inter-arrival distribution $F$ admits the representation {\eqref{AISR1.2}} corresponding
    to the regime {\hyperref[AISR(iii)]{\textbf{(iii)}}} and ${\mathcal{S}_\mu}:={\mu_2}\big/\left(2\mu^2\right)$
    denote the Stone constant. Then the following refined form of the key renewal theorem holds:
\begin{equation}     
    {\int_{[0,t]}Q_F(t-x)\,dU(x)}={\frac{1}{\,\mu\,}}R(t)+2{\mathcal{S}_\mu}\,Q_F(t)\!\big(1+o(1)\big)
    \qquad \text{as} \quad {t\to\infty},
\end{equation}
    where $R(t)$ is the leading renewal term, defined in {\eqref{AISR2.3}} and
\begin{equation}
    {Q_F}(t)={\frac{1}{\,\mu\beta\,}}t^{-\beta}\,L_Q(t),
\end{equation}
    therein $\beta=\alpha-1$ and $L_Q(t)\big/L(t)\to{1}$ as $t\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Hold-and-jump product-form representation) of arXiv:2607.24533, 'Colored Markov-Modulated Brownian Motion for Preemptive Workload Stacks'] {Suppose that Assumptions~\ref{assump:intensity}, \ref{assump:stability}, and~\ref{assump:first-moment} hold. Then the hold-and-jump model admits a stationary probability law.} On the face $\Theta_{c_1,\dots,c_n}$, the stationary density row vector
of the hold-and-jump model is
\begin{equation}

\vect{\pi}^{\mathrm H}(\bm{x})
=
\vect{p}^{\mathrm H}_0
\Lop{0}{c_1}(x_{c_1})
\prod_{r=1}^{n-1}
\Lop{c_r}{c_{r+1}}(x_{c_{r+1}}).
\end{equation}
The boundary mass vector $\vect{p}^{\mathrm H}_0$ satisfies
\begin{equation}

\vect{p}^{\mathrm H}_0\widetilde{\vect T}^{(0)}
=
\vect{p}^{\mathrm H}_0
\left(
\vect{T}^{(0)}
+
\sum_{c=1}^C\Rop{0}{c}
\right)
=
\vect{0}.
\end{equation}
Moreover, with
\begin{align*}
\mathfrak{M}^{\mathrm H}
=
\begin{bmatrix}
\vect{0} & \vect{M}^{(1,2)} & \cdots & \vect{M}^{(1,C)}\\
\vect{0} & \vect{0} & \cdots & \vect{M}^{(2,C)}\\
\vdots & \ddots & \ddots & \vdots\\
\vect{0} & \cdots & \vect{0} & \vect{0}
\end{bmatrix},
\end{align*}
$\vect{m}^{\mathrm H}=[\vect{M}^{(0,1)},\dots,\vect{M}^{(0,C)}]$, $\e^{\mathrm H}$
the column vector obtained by stacking $C$ copies of $\e$, and $\I^{\mathrm H}$
the identity matrix of the same dimension as $\mathfrak M^{\mathrm H}$, the normalization
condition is
\begin{equation}

\vect{p}^{\mathrm H}_0\e
+
\vect{p}^{\mathrm H}_0\vect{m}^{\mathrm H}
(\I^{\mathrm H}-\mathfrak{M}^{\mathrm H})^{-1}
\e^{\mathrm H}
=
1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:rep of arXiv:2605.03703, 'Scaling Limits of Bivariate Nearly-Unstable Hawkes Processes and Applications to Rough Vol'] Let
$M_t^{T,i}:=N_t^{T,i}-\int_0^t\lambda_s^{T,i}\,ds$.
Then $d\langle M^{T,i}\rangle_t=\lambda_t^{T,i}\,dt$,
$\langle M^{T,1},M^{T,2}\rangle\equiv0$, and
\begin{align}
\lambda_t^{T,1}
  &=\mu_T^1\Bigl(1+\int_0^t\psi_T^1(u)\,du\Bigr)
   +\int_0^t\psi_T^1(t-s)\,dM_s^{T,1},
   \\[2pt]
\lambda_t^{T,2}
  &=\mathbb{E}[\lambda_t^{T,2}]
   +\int_0^t\psi_T^2(t-s)\,dM_s^{T,2}
   +\int_0^t\Psi_T^{12}(t-s)\,dM_s^{T,1},

\end{align}
where
\begin{equation}
\widehat{\Psi_T^{12}}(z)
=\widehat{\phi_T^{12}}(z)
\frac{1}{1-a_T^1\widehat{\phi^1}(z)}
\frac{1}{1-a_T^2\widehat{\phi^2}(z)}
\end{equation}
and
\begin{equation}
\mathbb{E}[\lambda_t^{T,2}]
=\mu_T^2\Bigl(1+\int_0^t\psi_T^2\Bigr)
+\mu_T^1(\Psi_T^{12}*\mathbf 1)(t).
\end{equation}
Consequently the renormalized martingale parts are
\begin{equation}
\mathcal S_t^{T,i}=
\frac{1-a_T^i}{m_iT^{\alpha_i-1}}
\int_0^{Tt}\psi_T^i(Tt-s)\,dM_s^{T,i},
\qquad
\mathcal C_t^{T}=\frac{1-a_T^2}{m_2T^{\alpha_2-1}}
\int_0^{Tt}\Psi_T^{12}(Tt-s)\,dM_s^{T,1}.
\end{equation}
Moreover,
\begin{equation}
\psi_T^i(r)=\frac{\varepsilon_T^i}{1-a_T^i}
 g_T^i(\varepsilon_T^i r),
\qquad
\Psi_T^{12}(r)=
\frac{\varepsilon_T^1}{T^{2\alpha_1-\alpha_2}(1-a_T^1)(1-a_T^2)}
\tilde h_T(\varepsilon_T^1r).
\end{equation}

[Dfn 2 of arXiv:2608.15379, 'Stochastic Jacobi fields along discontinuous martingales on Riemannian submanifolds'] Let $\gamma:M\times M\to TM$ be a Borel measurable map and suppose $\gamma$ is $C^2$ on a neighborhood of $\mathrm{diag}(M)$, that is, there exists an open neighborhood $\mathcal{U} \subset M \times M$ of $\mathrm{diag}(M)$ such that $\gamma|_{\mathcal{U}} \in C^2(\mathcal{U}\, ;TM)$. Then $\gamma$ is called a connection rule if it satisfies the following conditions: For all $x,y\in M$,
\begin{enumerate}
\item[(i)] $\gamma (x,y)\in T_xM$;
\item[(ii)] $\gamma (x,x)=0$;
\item[(iii)] $(d \gamma (x,\cdot))_x=id_{T_xM}.$
\end{enumerate}

