[Theorem 9 (Precise block-energy asymptotics, isotropic nonzero mean case) of arXiv:2607.07712, 'Parameter-Space Heat Flow, Gaussian Density Ratios, and Sharp Hermite Truncation Rates'] Assume \(0<|\sigma|<1\) and \(u\neq0\). Then
\begin{equation}
a_m(u,\sigma)
\sim
C_{d,u,\sigma}\,
m^{\frac d4-\frac34}
\exp\!\left(
\frac{2|u|}{|\sigma|}\sqrt m
\right)
|\sigma|^{2m},
\qquad m\to\infty,

\end{equation}
where
\begin{equation}
C_{d,u,\sigma}
=
\frac{2^{-d/2}}{2\sqrt\pi}
\exp\!\left(
-\frac{|u|^2}{2\sigma^2}
\right)
\left(
\frac{|u|^2}{\sigma^2}
\right)^{\frac14-\frac d4}.

\end{equation}
Consequently,
\begin{equation}
\|\Pi_mK_{u,\sigma}\|_{L^2(\gamma_d)}
\sim
C_{d,u,\sigma}^{1/2}
m^{\frac d8-\frac38}
\exp\!\left(
\frac{|u|}{|\sigma|}\sqrt m
\right)
|\sigma|^m.

\end{equation}

[Theorem th:deviation of arXiv:2510.13733, 'Internal Diffusion Limited Aggregation \\ with Critical Branching Random Walks'] Let $(A(t))_{t\geq 0}$ denote a BIDLA process in  dimension $d>2$ satisfying Assumption (equation assumption of the paper). Then for any $\epsilon>0$,
\begin{equation}
\mathbb{P} \Big( \Big\{ \delta^I(t)> t^{\frac{1}{2}+\epsilon} \Big\} 
\cup \Big\{\delta^O(t)> t^{1-\frac{1}{2d}+\epsilon} \Big\} 
\, \, \text{infinitely often in }t \Big)
=0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop hl_principal_formulas of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] For $J,n \geq 1$ and $\lambda \in \Sig_n^+$,
\begin{align}
\begin{split}
    P_\lambda(x,xt,\ldots,xt^{n-1};t) &= x^{|\lambda|} t^{n(\lambda)} \frac{(t;t)_n}{\prod_{i \in \mathbb{Z}} (t;t)_{m_i(\lambda)}}=\frac{V_n(t)}{V_\lambda(t)}x^{|\lambda|} t^{n(\lambda)}\\
    Q_{\lambda/(0[n])}(x,xt,\ldots,xt^{J-1};t) &= x^{|\lambda|} t^{n(\lambda)} \frac{(t;t)_J}{(t;t)_{m_0(\lambda)+J-n}} \mathbbold{1}(m_0(\lambda)+J-n \geq 0)
\end{split}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2511.01456, 'Zero distribution of multiplicative Hermite and Laguerre polynomials'] For every $k\geq 2$, the $k$-th free cumulant of $\nu_{\beta, \gamma}$ is  given by
\begin{align}
\kappa_k
=
\frac{1}{k} [t^{ k-1}] \eee^{-k \gamma/(1+\beta+t)}
=
\frac {\eee^{- k\gamma/(1 + \beta)}}k \left(\frac {-1}{1+\beta}\right)^{k-1}
L_{k-1}^{(-1)}\left(\frac {k\gamma}{1+\beta}\right).
\end{align}

[Defi 4 (\Adam\ sequence space and \Adam\ effective action function) of arXiv:2606.21433, 'Central limit theorem for\\ the averaged Adam optimizer'] Let $ \alpha, \beta \in [0,1) $, $ \epsilon \in (0,\infty) $
with $ \alpha < \sqrt{\beta} $ be damping factors.
\begin{enumerate}[label=(\roman*)]
\item
We denote by $ \varrho = ( \varrho_k )_{ k \in - \N_0 } \in \R^{ - \N_0 } $ the sequence
which satisfies for all $ k \in - \N_0 $ that
\begin{align}
  \varrho_k =
  \epsilon^{ - 1 }
  ( 1 - \alpha )
  \bigl(
    \alpha^{ - k }
    +
    [ 1 - \alpha^2 / \beta ]^{ - 1 / 2 }
    \beta^{-k/2}
  \bigr)
\end{align}
and we denote by $ \ell^d_{ \varrho } $ the space of all sequences $\mathbf x=(x_{k})_{k\in-\N_{0}}\in(\R^{d})^{-\N_{0}}$ with
\bas{

  \|\mathbf x\|_{\ell_{\varrho}^{d}}:=\sum_{k\in-\N_{0}} \varrho_{k}\, |x_{k}|<\infty.
}
We equip the space with the norm
$
  \left\| \cdot \right\|_{ \ell_{ \varrho }^d }
$
and call $ ( \ell^d_{ \varrho }, \left\| \cdot \right\|_{ \ell_{ \varrho }^d } ) $
the \emph{sequence space associated with the damping factors $ ( \alpha, \beta, \epsilon) $}.

\item
We denote by $ g = ( g^{ (1) }, \dots, g^{ (d) } ) \colon \ell_{ \varrho }^d \to \R^d $ function
which satisfies for all $ \mathbf x = ( x_k )_{ k \in - \N_0 } \in \ell^d_{ \varrho } $, $ i \in \{ 1, \dots, d \} $ that
\bas{
  g^{(i)}(\mathbf x)
  =
  \frac{ 1 - \alpha }{
    \epsilon
    +
    [
      (1 - \beta)
      \sum_{ k = - \infty }^0
      \beta^{ - k }
      ( x^{ (i) }_k )^2
    ]^{ 1 / 2 }
  }
  \biggl[
    \sum_{ k = - \infty }^0
    \alpha^{ - k } x^{ (i) }_k
  \biggr]
}
and we call g the \emph{effective action of the \Adam\ algorithm for the damping factors $(\alpha,\beta,\epsilon)$}.
\end{enumerate}

[Lemma 60 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $q\geq 1$, $j\geq 1$ and $l\geq 0$.
There is a constant $C_{q,j,l}>0$ depending only on $q$, $j$ and $l$
(in particular depending neither on $D$ nor $b$),
such that a.s., for every $z,w\in D$ with $z\neq w$,
\begin{multline*}
\vert\log \CR(z,D)\vert^{q}
\vert\log \CR(w,D)\vert^{q}
V_{A_{0,b}}(z)^{l}V_{A_{0,b}}(w)^{l}
G_{D\setminus A_{0,b}}(z,w)^{j}
\ind_{\{\ell_{0,b}(z)=\ell_{0,b}(w)=b\}}
\leq
\\
C_{q,j,l} 
(1\vee \log \diam (D))^{2q}
(1\vee\diam(D)^{j/8})
\Big(
1\vee\log\Big(\dfrac{2(1\vee\diam(D))}{\vert w-z\vert}\Big)^{j+2l+2q}
\Big)
\,
\ind_{z\stackrel{D\setminus A_{0,b}}{\longleftrightarrow} w,\,\ell_{0,b}(z) = b}.
\end{multline*}

