[Theorem 5 (\cite{10}) of arXiv:2609.02426, 'Deformations of the $\osp(n|2)$-action on the superspace\\ of symbols of differential oper'] For $n\geq3$,
\begin{equation}

\Hd^1_{\mathrm{diff}}\bigl(\osp(n|2),\Dc^n_{\lambda,\mu}\bigr)\simeq
\begin{cases}
\R & \text{if }\mu-\lambda=0,\\[2pt]
\R^2 & \text{if }(\lambda,\mu)=\bigl(-\frac{k+n-2}{2},\frac{k}{2}\bigr),\ k\in\N\setminus\{0\},\\[2pt]
0 & \text{otherwise},
\end{cases}
\end{equation}
the corresponding cohomology classes being spanned by the $1$-cocycles
\begin{align}
f_\lambda(X_F)&=F',\\
h_k(X_F)&=(-1)^{nF}F'\,\eta_1\cdots\eta_n\,\partial_x^{k-1},\\
\widetilde{h}_k(X_F)&=(k-1)F''\eta_1\cdots\eta_n\partial_x^{k-2}
+(-1)^{(n-1)F}\sum_{\sigma\in S_n}\frac{\mathrm{sgn}(\sigma)}{(n-1)!}\eta_{\sigma(1)}(F')\,
\eta_{\sigma(2)}\cdots\eta_{\sigma(n)}\partial_x^{k-1}.
\end{align}
The cocycles $f_\lambda$ are even, while $h_k$ and $\widetilde{h}_k$ have the same parity as $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:NE-conditions2 of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] Consider the following conditions.
\begin{enumerate}[(i)]
\item There exists a point $x_0 \in {B^{g<f<h}} \cup {B^{f\leq g<h}}=\{x \in {\cal I}: f(x) \vee g(x) < h(x)\}$ with
\begin{align}
\sup_{\tau < \tau^{({B^{g<f<h}} \cup {B^{f\leq g<h}})^c}}\mathbb{E}_{x_0}(e^{-r\tau}f(X_\tau)) > f (x_0) \vee g(x_0).
\end{align}

\item  There exists a point $x_0 \in {B^{h<g<f}} \cup {B^{h<f\leq g}}=\{x \in {\cal I}: h(x) < f(x) \wedge g(x)\}$ with
\begin{align}
\inf_{\tau < \tau^{({B^{h<g<f}} \cup {B^{h<f\leq g}})^c}}\mathbb{E}_{x_0}(e^{-r\tau}g(X_\tau)) < f (x_0) \wedge g(x_0).
\end{align}
\end{enumerate}
If (equation asdasda of the paper) or (equation asdasda2 of the paper) holds, then no global Markovian pure Nash equilibrium exists. (Proof in the paper; no proof environment follows the statement in the TeX.)

