[Theorem thm:chenlam19 of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] The following statements hold:
    \begin{enumerate}
    \item There exists a constant $C>0$ such that 
     \begin{equation} 
    	\Var\left(F_N(\beta_c)\right) \leq C \left( N^{-2}(\log N)^2 +1\right).
     \end{equation} 
    \item For fixed $\alpha>0$ and $d>0$, there is a constant $C>0$, depending only on $\alpha$ and $\delta$, such that
     \begin{equation} 
    	\Var\left(F_N(\sqrt{\beta_c^2+dN^{-\alpha}})\right) \leq C \left( N^{-2}(\log N)^2 + N^{-1-\alpha}\right).
     \end{equation} 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 51 of arXiv:2507.08909, 'Annealed almost periodic entropy'] A sequence $Z_\bullet = (Z_1,Z_2,\dots)$ in $\prod_{k\ge 1}\calK(\S_k(\A))$ is the summary of some separable unital representation $\pi$ if and only if it has these two closure properties:
	\begin{itemize}
		\item[i.] if $\phi \in Z_k$ then $\S_\ell(\pi_\phi) \subset Z_\ell$ for every $\ell$;
		\item[ii.] if $\phi \in Z_k$ and $\psi \in Z_\ell$ then some joining of them lies in $Z_{k+\ell}$.
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Recall $\hE_\delta$ from Equation \eqref{eq_hatEdelta}. Under Assumptions \ref{Ass:Half_Step} and \ref{Aspt_new}, for any $M>0$ and $p\ge 1$ it holds that 
   for $j\in\{1,\dots,\frac Th\}$, \begin{align*}
         \Bigl\|\hE_\delta\bigl[ \xi_{jh}^2|\tiX^{h,\delta}_{jh}\bigr]-\E\bigl[ \xi_{jh}^2|\tiX^{h,\delta}_{jh}\bigr] \Bigr\|_{L^p} \lesssim 
        \Bigl(\delta \sqrt{-\log(\delta)}\Bigr)^{\frac1p}.
    \end{align*}

