[Definition 46 (Consistent collection of flows) of arXiv:2608.29086, '2608.29086'] Given $M \subset M_0$, its open covering $V=\{S_i \subset M\  |\  i \in I \}$, and locally defined flows 
\begin{equation*}
CF=\{{\Psi}_i \in FLOW(S_i) \ |\ i \in I\}.
\end{equation*}
$CF$ is called \textit{consistent} if
\begin{equation*}
{\Psi_i}|_{S_i \cap S_j}={\Psi_j}|_{S_i \cap S_j} \quad  (i, j \in I).
\end{equation*}

[Lemma lmm:poly-highsnr of arXiv:2602.14998, 'Random geometric graphs with smooth kernels: sharp detection threshold and a spectral conj'] Suppose the kernel $K(t)$ satisfies the conditions in~\prettyref{thm:highsnr}. 
There exists a degree-$L$ polynomial $\widetilde K(t) = \sum_{\ell\geq 0}^L a_\ell t^\ell$ 
that satisfies
(a) $\widetilde K(t) \in (0,1)$ for all $t \in (-r,r)$;

(b) 
$\mathbb{E}[|K(r\Iprod{x_1}{x_2}) - \widetilde K(r\Iprod{x_1}{x_2})|^2]
\leq (C_0r^2/d)^L$;
(c) $|a_\ell| \leq \frac{C_0^\ell}{\sqrt{\ell!}}$;
(d) $L = \lceil C_1 r^2 \rceil$,
where $C_0,C_1$ are positive constants. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 40 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $p=p(x,\xi)$ be of the form
    \begin{equation}
        p(x,\xi)=\sum_{k\in \Lambda}p_k(x)e^{2i\pi \ps{k}{\xi}}, \quad(x,\xi)\in [0,1]^d\times \T^d,
    \end{equation}
    where $\Lambda=\prod_{j=1}^d\disc{-n_j}{m_j}$, $n_j,m_j\geq 0$, and $p_k:[0,1]^d\to \C$, $k\in \Lambda$ is measurable. Let us denote 
    \begin{equation*}
        S:=\sum_{j=1}^d (n_j+m_j)>0\mm\m\m\text{and}\mm\m\m \Xi:=\prod_{j=1}^d(n_j+m_j+1).
    \end{equation*}
    We assume that: there exists $m>0$ such that for almost every $x\in [0,1]^d$, 
    \begin{equation}
        \sum_{\substack{k\in \Lambda\\k\neq 0}}^{N_+}\bb{p_k(x)}\geq m>0.
    \end{equation}
    Then, for all $z\in \C$, $t\geq 0$, 
    \begin{equation}
        \mathrm{L}\pr{\acc{(x,\xi)\in [0,1]^d\times \T^d\m;\m \bb{p(x,\xi)-z}^2\leq t}}\leq Ct^\kappa
    \end{equation}
    where
    \begin{equation}
        \kappa=\frac{1}{2S}\mm\text{and}\mm C= 14d\pr{\frac{\sqrt{\Xi}}{m}}^{\frac{1}{S}}.
    \end{equation}

