[Theorem 1 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] For $\theta\in[-1,1)$ and $a>-1$, there is some $t\in\{a,-\frac{1}{\theta},0\}$ such that for $y\in[-t,1]$, the limiting process $M'$ in \eqref{def_lim_process} exists and is a time-homogeneous Markov chain on $[-t,1]$ with reduced transition kernel 
\begin{align*}
     p'(x_1,\d x_2)&\coloneqq \mathds{1}_S(x_2,x_1)\frac{h(x_2)}{h(x_1)}\frac{1}{\lambda}\frac{1}{a+1}\,\d x_2,~~~~~~~~x_1,x_2\in[-t,1],
\end{align*}
 where $h:\R\to\R$ is the unique (up to multiplication with a constant) and positive (on the effective state space) eigenfunction satisfying the eigenvalue equation
\begin{align}
    \lambda h(x)=\int_{\{y>\theta x\}\cap[-t,1]} h(y) \frac{1}{a+1}\,\d y,\qquad x\in\R,
\end{align}
corresponding to the largest eigenvalue $\lambda>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma posterior-consistent of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Fix $p \in (0,1)$ and $\cc\in (-\k,\k)$ such that $\cc\neq \smref$. Let $(G_n,X^n)$ be sampled from the Posterior Model 
    with associated $B = B(p)$  and $\beta=\beta(\cc,p)$  as specified therein. 
    Then the local weak limit of the sequence $\{(G_n,X^n)\}_{n\in \N}$  is consistent with the asymptotic conditional limit of $U_n$, given  the event $\Conset_n(c)$, in the following cases:
    \begin{enumerate}
        \item[(1a)] If $\cc>\smref$ and $p>1/2$, then $(G_n,X^n)$ converges locally weakly to $\ising_\k^+(\beta,B)$ a.s.;
        \item[(1b)] If $\cc>\smref$ and $p<1/2$, then $(G_n,X^n)$ converges locally weakly to $\ising_\k^-(\beta,B)$ a.s.;
        \item[(1c)] If $\cc\in (0,\k/(\k-1)]$ and $p=1/2$, then $(G_n,X^n)$ converges locally weakly to $\ising_\k^*(\beta,B)$ a.s.;
        \item[(1d)] If $\cc\in (\k/(\k-1),\k]$ and $p=1/2$, then $(G_n,X^n)$ asymptotically lies in $\{\ising_\k^+(\beta,0),\ising_\k^-(\beta,0)\}$ with high probability
        , that is, for any $\varepsilon>0$,
        \begin{equation*}
            \lim_{n\rightarrow \infty}\bbP\cpr{U(G_n,X^n)\in B_\varepsilon\cpr{\pr{\ising_\k^+(\beta,0),\ising_\k^-(\beta,0)}}}=1.
        \end{equation*}
        \item[(2)] If $\cc<\smref$ and there exists a unique Ising $(T^\k,\beta,B)$ measure, then $(G_n,X^n)$ converges locally weakly to $\ising_\k^\sharp(\beta,B)$ a.s.. 
    \end{enumerate}

[Theorem 33 of arXiv:2606.19115, 'Finite free perpetuities'] Assume $(A,B)$ is $n$-admissible such that
 \begin{itemize}
 \item[(i)] $p_n^{[i]}\in\pols_n(\R_{\geq 0})$, $i=1,\ldots,\kappa_n$,
     \item[(ii)] $| \E[A^m]| = \prod_{i\in\mathcal{I}_n} | \coef{m}{n}(p_{n}^{[i]})|<1$ for all $m=1,\ldots,n$. 
 \end{itemize}
 Then, the finite free perpetuity $p_X$ of order $n$ generated by $(A,B)$ has only real, non-negative roots.

