 \E[ (z-S_N)^n] &=  \E[(z-(A_N S_{N-1}+B_N))^n] \\
&= p_{n}^{[\kappa_n]}\boxast_n^{(\kappa_n)} \left( p_{n}^{[\kappa_n-1]}\boxast_n^{(\kappa_n-1)}\left(\cdots p_n^{[2]}\boxast_n^{(2)}\left( p_{n}^{[1]}\boxast_n^{(1)} p_{S_{N-1}}\right)\cdots \right)\right) (z),
