[Lemma lem:limiting-bridge-identity of arXiv:2607.04264, 'Macroscopic Feynman Cycles and Poisson--Kingman Universality in Bose Condensation'] Let \(h\in\mathcal H\).  Assume that \(T^{(\kappa)}\) and
\(T_h^{(\kappa)}\) have densities \(f_0^{(\kappa)}\) and
\(f_h^{(\kappa)}\), respectively.  Then
\begin{equation}
        \mathbf E
        \left[
            e^{-\langle h,\Pi^{(\kappa)}\rangle};
            T^{(\kappa)}\in da
        \right]
        =
        e^{-A^{(\kappa)}(h)}
        f_h^{(\kappa)}(a)\,da .
\end{equation}
Consequently, for every \(a>0\) such that \(f_0^{(\kappa)}(a)>0\),
\begin{equation}
        \mathbf E
        \exp\left\{
            -\langle h,\Pi_a^{\mathrm{br}}\rangle
        \right\}
        =
        e^{-A^{(\kappa)}(h)}
        \frac{
            f_h^{(\kappa)}(a)
        }{
            f_0^{(\kappa)}(a)
        } .
\end{equation}

[Corollary 12 (The Kähler case) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] If $\kappa_i \equiv 0$ for all $i$ (the Kähler condition \eqref{eq:kahler-condition}), then

	\begin{equation}
		\begin{gathered}
			\operatorname{Ric}(\nu, \nu) \;=\; \operatorname{Ric}(\xi^*, \xi^*) \;=\; -\frac{H''}{H} \;+\; \sum_{i=1}^r n_i \left( \frac{q_i^2 H^2}{2 F_i^4} \;-\; \frac{q_i H'}{F_i^2} \right), \\
			\mathcal{R}_i \;=\; p_i \;-\; q_i H' \;-\; \frac{q_i H^2}{2} \sum_{j=1}^r \frac{n_j\, q_j}{F_j^2} \,,
		\end{gathered}
	\end{equation}

	and the scalar curvature becomes

	\[
	\mathrm{R}_g \;=\; -\frac{2H''}{H} \;+\; \sum_{i=1}^r n_i \left( \frac{2 p_i}{F_i^2} \;-\; \frac{4\, q_i H'}{F_i^2} \;+\; \frac{q_i^2 H^2}{F_i^4} \right) \;-\; \left( \sum_{i=1}^r \frac{n_i\, q_i H}{F_i^2} \right)^{2} .
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 12 of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Let $\rho_1<\rho_2$ be consecutive pivot nodes and set $j:=\rho_2-\rho_1$.
The following statements hold.
\begin{enumeratei}
\item If $j\le 2\ell-2$, then $T(\rho_1,\rho_2)<2a$, where $a$ is the fixed constant satisfying Condition~\textnormal{B.\ref{ass:B1}}.
\item If $j\ge 2\ell-1$, then there exist $\lc=\ell(\ell+1)/2$ paths from $0$ to $j$ such that, after deleting their first and last edges, the remaining edge sets are pairwise disjoint. Moreover, each such truncated path uses at most $j$ edges.
\end{enumeratei}

