body:
[Definition def: CharacterizedPhi of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] The \emph{bivariate characteristic polynomial} of the pair $(\bM,\zeta)$ is defined as 
    \begin{align}
        \Phi_{\bM,\zeta}(\lambda, t) \de \det\bigl(\lambda \bI - \bM - t \zeta \zeta^{\T}\bigr),
    \end{align}
    where $\bI$ is the identity.
    The pair $(\bM,\zeta)$ is said to be \emph{characterized by $\Phi$-spectrum} if every $(\bN,\eta)$ with $\Phi_{\bM,\zeta} = \Phi_{\bN, \eta}$ is isomorphic up to signed permutation.

[Definition 42 (Balanced comparison structure) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] We say that $\xi$ is \textbf{balanced} with respect to $\lambda$ if there exists a one-species covariance function $\xi_\star:\R_+\to\R$ such that, for every $r\in\R_+$,
\begin{equation}

    \xi(r\lambda)=\xi_\star(r),
\end{equation}
and, for every $a=(a_s)_{s\in\sS}\in\R_+^\sS$,
\begin{equation}

    \xi(a)\leq \sum_{s\in\sS}\lambda_s\xi_\star\left(\frac{a_s}{\lambda_s}\right).
\end{equation}

[Lem 19 of arXiv:2510.26216, 'A functional Breuer-Major theorem with Poisson noise'] For every $\gamma \in (\frac{1}{2},1)\cup(1,\infty)$, we have the estimates
    \begin{equation}
        \|\Psi_{\gamma,i}\Psi_{\gamma,j}\|_{L^\infty(\mathbb R)} \le(1+|i-j|)^{-\gamma},
    \end{equation}
    \begin{equation}
        (1+|i-j|)^{(1-2\gamma)\vee(-\gamma)} \lesssim\|\Psi_{\gamma,i}\Psi_{\gamma,j}\|_{L^1(\mathbb R)} \lesssim (1+|i-j|)^{(1-2\gamma)\vee(-\gamma)} ,
    \end{equation}  
    and
    \begin{equation}
        \begin{aligned}
            \|\Psi_{\gamma,i}\Psi_{\gamma,j}\Psi_{\gamma,k}\|_{L^1(\mathbb R)} &\lesssim \|\Psi_{\gamma,i}\Psi_{\gamma,j}\|_{L^1(\mathbb R)} \|\Psi_{\gamma,i}\Psi_{\gamma,k}\|_{L^1(\mathbb R)} +\|\Psi_{\gamma,i}\Psi_{\gamma,j}\|_{L^1(\mathbb R)}\|\Psi_{\gamma,j}\Psi_{\gamma,k}\|_{L^1(\mathbb R)}\\& + \|\Psi_{\gamma,i}\Psi_{\gamma,k}\|_{L^1(\mathbb R)}\|\Psi_{\gamma,j}\Psi_{\gamma,k}\|_{L^1(\mathbb R)},
        \end{aligned}
    \end{equation}
    where the proportionality constants are independent of $i,j,k\in\ZZ$.

