[Proposition prop_downcrosscount of arXiv:2603.29442, 'A compact support property for infinite-dimensional SDEs with Hölder continuous coefficien'] (a) For $t>0$ and $\epsilon>0$, if $\delta$ is sufficiently small, then for sufficiently small $\zeta>0$ and any $\mathbb{P} \in \mathscr{M}_{\gamma,\delta}(0)$,
\begin{equation} 
\mathbb{P}(N_\zeta(t) < \lceil (1-2 \epsilon) \delta t \zeta^{-1}\rceil) < \epsilon.
\end{equation}
(b) For any $t>0$, $\delta>0$ and $\mathbb{P} \in \mathscr{M}_{\gamma,\delta}(0)$,
\[\lim_{\epsilon \downarrow 0}\lim_{\zeta\downarrow 0} \mathbb{P}(N_\zeta(t) < \epsilon \zeta^{-1}) = 0. \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 25 of arXiv:2606.19115, 'Finite free perpetuities'] Let $p\in\pols_n(\C)$ and $U$ be any $U$-transform of $p$. Let $d\in\{0,\dots,n-1\}$. Then 
\begin{itemize}
    \item[(i)] a $U$-transform of $\partial_n^dp$ is any complex-valued random variable $U'$ satisfying $\E[|U'|^{n-d}]<\infty$ and $\E[(U')^m]=\E[U^m]$ for all $m\in\{1,\dots,n-d\}$.
    \item[(ii)] Assume additionally that $p$ is $d$-monic. A $U$-transform of $D_n^dp$ is any complex-valued random variable $U'$ satisfying $\E[|U'|^{n-d}]<\infty$ and $\E[(U')^m]=\E[U^{m+d}]$ for all $m\in\{1,\dots,n-d\}$.
\end{itemize}

[Theorem thm:modularity_function of arXiv:2605.10911, 'The stochastic block model has the overlap graph property for modularity'] Fix $a>b>0$ and integer $k\geq 2$. Let $p=p(n)=\omega\; a / n$ and $q=q(n)=\omega \; b/n$. For any $\varepsilon>0$, there exists $c=c(\varepsilon)$ such that, if $\omega>c$ for $n$ large enough, then the following holds with probability at least $1-\varepsilon$ provided $n$ is large enough.

Let $G \in \mathcal{G}(n,k,p,q)$ and denote the planted partition by $\mathcal{P}$. Then,
\begin{equation}
\left| q_\mathcal{P}(G)  - \frac {a-b}{a+(k-1)b} \left( 1 - \frac {1}{k} \right) \right| \le \frac {\varepsilon}{2}
\end{equation}
and 
\begin{equation}
\Big| q^{\star}(G) - q_\mathcal{P}(G) \Big| \le \frac {\varepsilon}{2}.
\end{equation}
As a result, 
$$
\left| q^{\star}(G)  - \frac {a-b}{a+(k-1)b} \left( 1 - \frac {1}{k} \right) \right| \le \varepsilon.
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition reference-semigroup of arXiv:2609.00425, 'Individual and Uniform Eventual Positivity of Self-Adjoint Semigroups'] The operator $A_0$ generates a self-adjoint $C_0$-semigroup $(\mathrm{e}^{tA_0})_{t \geq 0}$ on $\ell^2(\mathbb{Z})$ which is positive in the Banach lattice sense. Moreover,
\begin{align*}
    \mathrm{e}^{tA_0} \to u \otimes u
\end{align*}
with respect to the operator norm as $t \to \infty$.

