[Lemma lem:stationary-tube-estimate-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume \(
\mathcal G_n^{\mathrm{lim}}\) holds.  If \(
2^n\le\lvert\xi\rvert\le2^{n+1}\), then
\begin{equation}
\left|
\int e^{i\phi_\xi(t)}
\chi_{\xi,\mathrm{stat}}(t)\,d\widetilde\nu(t)
\right|
\le
C2^{-sn/2}2^{-c_{\mathrm{stat}}n}
\end{equation}
for some \(c_{\mathrm{stat}}>0\).

[Lemma lemmanvnowvowv of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Let 
\begin{equation}

w_{\gamma,\nu}(k)=\frac{\Gamma(\gamma-1-k)\Gamma(\nu+k+2)}{\Gamma(\gamma-1)},\ \ k\in \Bbb N.
\end{equation}
then:\\ 
\begin{enumerate}
\item  value for $k\ge K$: $\forall j\ge 0$, 
\begin{equation}

w_{\gamma,\nu_b}(K+j)=(-1)^j\Gamma(\alpha_\gamma)\Gamma(1-\alpha_\gamma)\frac{\Gamma(K+j+\nu_b+2)}{\Gamma(K+\alpha_\gamma)\Gamma(j+1-\alpha_\gamma)}.
\end{equation}
\item $\nu$ dependence:
\begin{equation}

\forall  k\ge 0, \ \ \frac{\gamma w_{\gamma,\nu_b}(k+1)}{w_{\gamma-1,\nu_b+1}(k)}=\frac{\gamma}{\gamma-2}
\end{equation}
\item induction property:
\begin{equation}

\forall k\ge 1, \ \ (\gamma-k-2)w_{\gamma-1,\nu_b+1}(k)-(k+\nu_b+2)w_{\gamma-1,\nu_b+1}(k-1)=0.
\end{equation}
\end{enumerate}

