[Lemma eq:energy-influence of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:energy-gradient-influence}
For \(O\in\mathcal O_{N,L}\), \(I\in[N]^p\), and \(1\le r\le m+1\),
\begin{align}
 \left\lvert\partial_I^r[-NV(h_J(O))]\right\rvert&\le C q_N^r,\\
 \abs{\partial_I^r\sum_{a=1}^n\log\kappa_\varepsilon(g_{a,J}(O))}
 &\le C q_N^r.
\end{align}
The constants are uniform in \(J,N,O,I\).

[Theorem th:local-eq-riemann of arXiv:2604.08154, '\small Hydrodynamic limit of the directed exclusion process'] Let,  for some $\lambda, \rho\in [0,1]$, $\mu_{\lambda,\rho}$ be the product measure on $\mathbf{X}$ associated to $u_0=\lambda\mathds{1}_{(-\infty,0)}+\rho\mathds{1}_{[0,+\infty)}$ (given in (equation eq:initial-riemann of the paper)). Then, letting $u(\,\cdot\,,\,\cdot\,):\mathbb{R}\times [0,+\infty)\to [0,1]$ denote the entropy solution associated to $u_0$ (cf.\ Section (sec:riemann of the paper)), we have, for all $t\ge 0$,
	\begin{equation}
		\lim_{\varepsilon\to \to 0} \tau_{\lfloor x\varepsilon^{-1}\rfloor}\tttonde{\mu_{\lambda,\rho} \ensuremath{\mathcal P}_{t\varepsilon^{-1}}} = \nu_{u(x,t)}\; \text{,}\;\;\qquad \text{for every continuity point $x\in \mathbb{R}$ of $u(\,\cdot\,,t)$}\; \text{.}
	\end{equation}

[Cor 105 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Let $\pi$ be a uniform random $n$-dimensional representation of $\G$, and let $m := \lfloor n/k\rfloor$.  The resulting Gram matrix $Q^\pi[F_i]$ is nonsingular almost surely for all $i =0,1,2\dots,m$, and the corresponding random Verblunsky coefficients
\begin{equation}
C^\pi_{F_0,g_1},\ C^\pi_{F_1,g_2},\ \dots,\ C^\pi_{F_m,g_{m+1}}
\end{equation}
are defined almost surely, are independent, and have respective distributions
\[\s_{n - k|F_i\cap s_{i+1}F_i|,k|F_i\setminus s_{i+1}F_i|,k} \qquad \hbox{for}\ i=0,1,2,\dots,m.\]
\qed (Proof in the paper; no proof environment follows the statement in the TeX.)

