[Lemma L:2.4 of arXiv:2412.09850, 'Averaging principles for time-inhomogeneous multi-scale SDEs via nonautonomous Poisson equ'] Suppose that Assumption {\rm(A1 of the paper)} holds. Let $Y^{s,x,y}:=\{Y_{t}^{s,x,y}\}_{t\ge s}$ be the unique strong solution to the SDE (equation FrozenE of the paper). Then, for any $t\in \mathbb{R}$ and $x\in \mathbb{R}^n$, there exists $\eta^x_{t} \in L^{2} (\Omega ,\mathscr{F},\mathbb{P} )$ such that for all $t\ge s$, $x\in \mathbb{R}^n$ and $y\in \mathbb{R}^m$,
\begin{equation}
\mathbb{E}|Y_{t}^{s,x,y}-\eta^x_{t}|^{2} \le C (1+|x|^2+|y|^{2} )e^{-2\int_{s}^{t}\alpha(u)\,du},\quad \sup_{t\in\mathbb{R}}\mathbb{E}|\eta^x_{t}|^2\leqslant C(1+|x|^2),
\end{equation}
and $\{\eta^x_{t}\}_{t\in\mathbb{R}}$ satisfies that
\begin{equation}
\eta^x_{t}=\eta^x_{s}+\int^t_s f(r,x,\eta^x_{r})\,dr+\int^t_s g(r,x,\eta^x_{r})\,d W^2_r,\quad t\ge s.
\end{equation}
Moreover, $\eta^x_{t}$ is twice differentiable in mean square with respect to $x$, and the first derivative $\partial _x\eta^x_{t}$ and the second derivative $\partial^2_x\eta^x_{t}$ satisfy that for all $t\ge s$, $x\in \mathbb{R}^n$ and $y\in \mathbb{R}^m$
\begin{equation}\begin{split}
& \mathbb{E}\|\partial_x Y^{s,x,y}_t-\partial_x \eta^x_{t}\|^{2} \leqslant C  (1+|x|^2+|y|^{2}  )e^{-2\gamma\int^t_s\alpha(u)\,du},  \\
& \mathbb{E}\|\partial^2_x Y^{s,x,y}_t-\partial^2_x \eta^x_{t}\|^{2} \leqslant C  (1+|x|^2+|y|^{2} )e^{-2\gamma\int^t_s\alpha(u)\,du},\\
& \sup_{t\in \mathbb{R}}\mathbb{E}\|\partial_x\eta^{x}_{t}\|^2\leqslant C,\quad \sup_{t\in \mathbb{R}}\mathbb{E}\|\partial^2_x\eta^{x}_{t}\|^2\leqslant C,
\end{split}\end{equation}
where $\gamma\in(0,1)$ is the constant in (equation A12 of the paper).

