[Lemma 4 of arXiv:2609.04095, '2609.04095'] For \(n\ge0\) and \(0\le p\le2n\),
\begin{equation}
 a_p^{(n)}=
 \begin{cases}
  T_p(0),&0\le p\le n,\\
  T_{2n-p}(p-n),&n\le p\le2n.
 \end{cases}
\end{equation}
The two expressions agree when \(p=n\).

[Definition 45 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] For $k=1,...,n$, define
\begin{align}
\forall t \in \mathbb{R}, \ h_k(t) &:= P\big((X_1,...,X_{k-1},t,X_{k+1},...,X_n) \in V \big) \\ 
       &= P\big((X_1,...,X_{k-1},t,X_{k+1},...,X_n) \in V \cap \{x \in \mathbb{R}^n\}_{x_k = t}   \big) 
\end{align}

[Lem ;laltv of arXiv:2604.12462, 'Stochastic analysis of Beckner's and related functional inequalities'] We have 
\begin{align}
 V(z)=C_{p,\nub }'\int _{0}^{z}du\,\int _{0}^{\infty }d\lambda  \,
 \lambda  ^{(2p-1)\nub +1}K_{\nub }(\lambda  )\exp \!\left( 
 -\frac{q^{2}u}{8}\lambda  ^{2}
 \right) 
\end{align}
for all $z\ge 0$. Here the constant $C_{p,\nub }'$ is given by 
\begin{align}
 C_{p,\nub }'=\frac{1}{
 2^{(2p-1)\nub }\Gamma (1+p\nub )\Gamma (1+(p-1)\nub )
 }.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:chen_mixed of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] We denote by $\mathcal{R}^{\gamma, \beta}([0, 1]; V\times E)$ the collection of all elements ${\color{purp}g}=(g^\bullet, g^\circ, \mathbb{g}^{\bullet\bullet},  \mathbb{g}^{\circ\bullet}, \mathbb{g}^{\bullet\circ})$, such that 
    $(g^\bullet, \mathbb{g}^{\bullet\bullet}) \in  \mathcal{R}^\gamma([0, 1]; V)$,
    $g^\circ \in \mathcal{C}^\beta([0, 1];E)$,     
        $ (\mathbb{g}^{\bullet\circ}, \mathbb{g}^{\circ\bullet}) \in  \mathcal{C}^{\beta+\gamma}_2([0,1]^2;  (V\otimes E) \times (E\otimes V) )$, and that the Chen's relations
        \begin{equs}                
            \mathbb{g}^{\bullet\circ}_{s, t}-\mathbb{g}^{\bullet\circ}_{s, u}- \mathbb{g}^{\bullet\circ}_{u, t}= g^\bullet_{s, u} \otimes g^\circ_{u, t}, \qquad \mathbb{g}^{\circ\bullet}_{s, t}-\mathbb{g}^{\circ\bullet}_{s, u}- \mathbb{g}^{\circ\bullet}_{u, t}= g^\circ_{s, u} \otimes g^\bullet_{u,t}       
        \end{equs}
        hold for all $(s,u,t)\in[0,1]^3_\leq$.
        Moreover, we set 
        \begin{equ}
         \,    [{\color{purp}g}]_{\mathcal{R}^{\gamma, \beta}}= [g^{\bullet}]_{\mathcal{C}^\gamma}+ [g^{\circ}]_{\mathcal{C}^\beta}+[\mathbb{g}^{\bullet \bullet}]_{\mathcal{C}^{2\gamma}_2}+[\mathbb{g}^{\circ  \bullet}]_{\mathcal{C}^{\gamma+ \beta}_2}+[\mathbb{g}^{\bullet \circ}]_{\mathcal{C}^{\gamma+ \beta}_2}.
        \end{equ}

[Lemma lem:odometer-derivative of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Suppose $(\zeta(x))_{x\in\mathbb{Z}^d}$ are independent and atomless. Then,
	$\mathbb{P}$-almost surely, for every $n\geq1$ and $x,z\in\mathbb{Z}^d$,
	\begin{equation}
		\partial_{\zeta(z)}u_n(x)
		=
		\mathbf E_x\sum_{j=0}^{n-1}
		\mathbf{1}_{\{X_j=z\}}
		\prod_{i=0}^j\mathbf{1}_{\{u_{n-i}(X_i)>0\}}
		=
		\mathbf E_x\sum_{j=0}^{n-1}
		\mathbf{1}_{\{X_j=z\}}\mathbf{1}_{\{\tau_n^*>j\}}\, .
	\end{equation}

[Definition def:gPAM-reg of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Let $\rho_\varepsilon$ be a smooth spatial mollifier at scale $\varepsilon > 0$ and set $\xi_\varepsilon = \xi * \rho_\varepsilon$. The \emph{renormalised mollified gPAM} is
\begin{equation}
  \partial_t u^\varepsilon = \Delta u^\varepsilon + f(u^\varepsilon)\xi_\varepsilon - C_\varepsilon f'(u^\varepsilon)f(u^\varepsilon), \qquad u^\varepsilon(0) = u_0 \in C(\mathbb{T}^2),
\end{equation}
where $C_\varepsilon := \mathbb{E}\bigl[(K * \xi_\varepsilon)(z)\,\xi_\varepsilon(z)\bigr]$, independent of $z$ by stationarity, is the renormalisation constant, $K$ being a compactly supported truncation of the heat kernel as in [hairer2014theory] (different truncations change $C_\varepsilon$ by $O(1)$); one has $C_\varepsilon = \tfrac{1}{2\pi}\log(1/\varepsilon) + O(1)$.\footnote{The coefficient of the counterterm is fixed by a single Wick contraction. Along the Picard expansion of (equation eq:gPAM-reg of the paper), the divergent contribution to $f(u^\varepsilon)\xi_\varepsilon$ is $f'(u^\varepsilon)f(u^\varepsilon)\,(K*\xi_\varepsilon)\,\xi_\varepsilon$, whose expectation is precisely $C_\varepsilon$, and the centred product $(K*\xi_\varepsilon)\,\xi_\varepsilon - C_\varepsilon$ converges in probability in a Hölder space of negative regularity. Displayed normalisations of the renormalisation constants vary across the literature; the invariant statement is that the drift correction $-C_\varepsilon\,f'(u^\varepsilon)f(u^\varepsilon)$ with $C_\varepsilon = \mathbb{E}[(K*\xi_\varepsilon)\xi_\varepsilon]$ yields a mollifier-independent limit, the $\rho$-dependent finite part of $C_\varepsilon$ being exactly the mollifier-dependent adjustment required in [hairer2014theory] for mollifier-independence.} Alongside (equation eq:gPAM-reg of the paper) we introduce its \emph{white-in-time companion model} on the Gelfand triple $V = H^1(\mathbb{T}^2) \hookrightarrow H = L^2(\mathbb{T}^2) \hookrightarrow V^* = H^{-1}(\mathbb{T}^2)$, obtained by replacing the time-independent noise $\xi_\varepsilon$ by white-in-time noise smoothed by the same mollifier:
\begin{equation}
  \mathrm{d}u^\varepsilon(t) = \bigl[\Delta u^\varepsilon(t) - C_\varepsilon f'(u^\varepsilon(t))f(u^\varepsilon(t))\bigr]\,\mathrm{d}t + f(u^\varepsilon(t))\,\rho_\varepsilon * \mathrm{d}W(t),
\end{equation}
where $W$ is a cylindrical Wiener process on $U = L^2(\mathbb{T}^2)$. The two equations are distinct. The noise $\xi_\varepsilon$ of (equation eq:gPAM-reg of the paper) is constant in time, whereas $\rho_\varepsilon * \dot W$ is white in time, so no identity of the form $\xi_\varepsilon\,\mathrm{d}t = \rho_\varepsilon * \mathrm{d}W$ holds. The companion model (equation eq:gPAM-variational of the paper) is a well-posed variational SPDE at each fixed $\varepsilon > 0$ and serves below as the variational-subcase representative for the operator-level analysis; no claim is made about its $\varepsilon \downarrow 0$ limit (the two-dimensional multiplicative heat equation with space-time white noise is critical, outside the subcritical scope of [brunedchandrachevyrevhairer2021]). The renormalised solution $u$ of (equation eq:gPAM of the paper) is the limit of the solutions $u^\varepsilon$ of the genuinely mollified equation (equation eq:gPAM-reg of the paper) as $\varepsilon \downarrow 0$, for initial data $u_0 \in \mathcal{C}^\alpha(\mathbb{T}^2)$ with $\alpha \in (1/2, 1)$, in the sense of [hairer2014theory] (convergence in probability of the processes stopped at a large $\mathcal{C}^\alpha$-norm cutoff, for each finite time horizon) and, equivalently, as a special case of [brunedchandrachevyrevhairer2021] (spatial and space-time mollification coincide for the time-independent noise $\xi$; see the discussion of approximation families above); the scalar reduction applies to this family through the time-independent-noise clause of Remark~(rem:abstract-gaussian of the paper).

