[Lemma 18 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Let $Y \in \mathcal{S}^2_{\beta}$ be a strong $\mathcal{E}^f$-supermartingale on $[\sigma,\eta]$ with $\sigma,\eta \in \mathcal{T}_{[0,T]}$ such that $\sigma \leq \eta$ a.s. The following two properties are equivalent:
	\begin{itemize}
		\item[(i)] $Y$ is a strong $\mathcal{E}^f$-martingale on $[\sigma,\eta]$.
		\item[(ii)] $Y_{\sigma}=\mathcal{E}^f_{\sigma,\eta}(Y_{\eta})$.
	\end{itemize}

[Thm POC of arXiv:2411.03104, '{\bf Coupling Methods and Applications on Path Dependent McKean-Vlasov SDEs}\footnote{Supp'] Assume {\bf (C)} with (equation lia of the paper) in place of (equation lip1a of the paper). Let $\mu_0^N\in\mathscr P_{1}((\mathscr C_\infty)^N)$ be exchangeable,  $\mu_0\in \mathscr P_{2}(\mathscr C_\infty)$. Assume that
\begin{align}
K_b<\min\left\{\frac{2\beta^4}{\text{\rm{e}}^{\frac{2\beta^2}{\delta}r_0}(K_2-K_\sigma)\delta^2},
\frac{2(K_2-K_\sigma)\text{\rm{e}}^{-2(K_2-K_\sigma)r_0}}{6}\right\}
 \end{align}
 for $\delta=\int_0^\infty s\text{\rm{e}}^{\frac{1}{2\beta^2}\int_0^s\{\gamma(v)+K_\sigma v\}\text{\rm{d}} v}\text{\rm{d}} s$.
 Then
\begin{align}\nonumber&\mathbb W_1^{\tilde{\Gamma}^{r_0}}((P_t^{m})^\ast\mu^N_0,(P_t^\ast\mu_0)^{\otimes m})\\
&\leq c\text{\rm{e}}^{-\lambda t}\frac{m}{N}\mathbb W_1^{\tilde{\Gamma}^{r_0}}(\mu_0^N,\mu_0^{\otimes N})+cm\{1+\{\mu_0(\|\cdot\|_{\Gamma^{r_0}}^{2})\}^{\frac{1}{2}}\}N^{-\frac{1}{2}},\ \ t\geq 0, 1\leq m\leq N
\end{align}
holds for some constants $c,\lambda>0$.

