\begin{align}
    \int_0^\infty u^{\frac{Q}{2}-1} e^{-t\phi(u)}du<\infty
\end{align}
for some $t>0$. Then,
\begin{enumerate}[leftmargin=*]
\item $\Delta^{\phi,\Omega}_{\mathcal{H}}$ has purely point spectrum in $L^2(\Omega, dx)$ and the first eigenvalue is strictly larger than $\phi(0)$. Moreover, denoting the eigenvalues of $\Delta^{\phi,\Omega}_{\mathcal H}$ by 
\begin{align*}
\lambda_{1,\phi}\leqslant \lambda_{2,\phi}\leqslant \cdots,
\end{align*}
we have
\begin{align} 
    \lambda_{n,\phi}\leqslant 4\phi(\lambda_n) \quad \mbox{for all $n$},
\end{align}
where $0<\lambda_1\leqslant \lambda_2\leqslant \cdots$ denote the eigenvalues of the Dirichlet sub-Laplacian $\Delta^{\Omega}_{\mathcal H}$. 
\item If $\phi$ is a complete Bernstein function, then 
\begin{align} 
    \lambda_{n,\phi}\leqslant \phi(\lambda_n) \quad \mbox{for all $n$}.
\end{align}
If in addition $\Omega$ satisfies the intrinsic exterior cone condition (see Definition~(def:cone_cond of the paper)), then 
\begin{align} 
    \lambda_{n,\phi}\geqslant c(\Omega)\phi(\lambda_n) \quad \mbox{for all $n$},
\end{align}
where $c(\Omega)>0$ is a constant independent of $n$ and $\phi$, and depends only on $\Omega$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

