[Lem 8 of arXiv:2607.27932, '2607.27932'] Define, for $\rho>0$,
\begin{equation*}
\tau^\rho_{\lambda,\varepsilon}(\sigma)=\left\{
\begin{aligned}
&\inf\left\{t\ge 0\,:\,(x_t^\sigma,y_t^\sigma)\in \mathbb B(\lambda;\rho\varepsilon)\times \mathbb
B(\lambda;\varepsilon)\right\}\,\,\mbox{if}\,\| \lambda-\lambda_{1}\| =\varepsilon,\\
&\inf\left\{t\ge 0\,:\,(x_t^\sigma,y_t^\sigma)\in \mathbb B(\lambda;\varepsilon)\times \mathbb
B(\lambda;\rho\varepsilon)\right\}\,\,\mbox{if}\,\| \lambda-\lambda_{2}\| =\varepsilon,\\
&\inf\left\{t\ge 0\,:\,(x_t^\sigma,y_t^\sigma)\in \mathbb B(\lambda;\varepsilon)\times \mathbb
B(\lambda;\varepsilon)\right\}\,\,\mbox{otherwise}\,.
\end{aligned}
\right.
\end{equation*}
Then, for any $\lambda\in\bRb^d$,  $0<\varepsilon<\varepsilon_0$, $0<\rho<1$ and for any $\delta>0$:

\begin{equation}

\lim_{\sigma\to0}\PP\left(\exp\left[\frac{2}{\sigma^2}\left(\widehat\h^\rho_\varepsilon(\lambda)-\delta\right)\right]<
\tau^\rho_{\lambda,\varepsilon}(\sigma)<\exp\left[\frac{2}{\sigma^2}\left(\widehat\h^\rho_\varepsilon(\lambda)+\delta\right)\right]\right)=1\,.
\end{equation}
Moreover \eqref{gouverneur2} still holds true with
$(x^\sigma_{\tau^\rho_{\lambda,\varepsilon}(\sigma)},y^\sigma_{\tau^\rho_{\lambda,\varepsilon}(\sigma)})$ in place of
$(x^\sigma_{\widehat\tau^\rho_{\lambda,\varepsilon}(\sigma)},y^\sigma_{\widehat\tau^\rho_{\lambda,\varepsilon}(\sigma)})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

