[Lemma 22 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Fix a bounded open set $U \subseteq \CC$ and let $\varepsilon \in (0,1), \alpha \in (0,1/4), A \in (2,\infty)$ be such that $\alpha (1+2/A) < 1/4$. Suppose that the functions $b,M$ are chosen such that $b(\xi) \sqrt{M(\xi)} > 20 A$. Then, there exists a constant $C \in (0,\infty)$ depending only on $\varepsilon,\alpha,A$, and $U$, such that the following hold with probability at least $1-\varepsilon$. For all $z \in U$, we have that
\begin{enumerate}
    \item 
    \begin{equation*}
        h_{e^{-t}}(z) \leq 2t - \alpha \log t + C\,\,\text{for all} \,\, t \geq 0.
    \end{equation*}
    \item 
    For all $n,m \in \NN$ with $m<n$, we have
    \begin{align*}
        &\widetilde{D}_h^{\xi}(\partial B_{e^{-n-50}}(z),\partial B_{e^{-m}}(z)) \\
        &\leq C^{\xi +1} e^{C(\xi+1) / A} e^{2\xi Q(\xi)} \sum_{k=m}^{n-1} \min_{t \in [k,k+1]}\left(\exp\left(\xi h_{e^{-t}}(z) - \xi Q(\xi) t + \frac{(2+2\xi) (2t - h_{e^{-t}}(z))}{A}\right)\right).
    \end{align*}
    \item 
    For all $n \in \NN$, we have
    \begin{align*}
        &\widetilde{D}_h^{\xi}(\text{around}\,\, \mathbb{A}_{e^{-n-1},e^{-n}}(z))\\
        &\leq C^{\xi+1} e^{C(\xi+1)/A} e^{2\xi Q(\xi)} \min_{t \in [n+1,n+2]} \exp\left(\xi h_{e^{-t}}(z) - \xi Q(\xi) t + \frac{(2+2\xi) (2t - h_{e^{-t}}(z))}{A}\right).
    \end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop weighted_L2_NEW of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given $\alpha \geqslant 0$ and $N \in \mathbb{N}$, then for all integers $h,k$ satisfying 
		\begin{align}
			h \geqslant  \max \left\{\frac{(\alpha+3)(2+\widetilde{\varepsilon}_{Me})}{\widetilde{\varepsilon}_{Me}}, \widetilde{h}_{Me} \right\}, \qquad k \geqslant h+2,
		\end{align}
		there exists a finite positive constant $C = C(d, N, h, k)$, such that every ${{\scaleobj{1}{\square}}_m \in \mathcal{G}^{(N)}_k}$ is $N$-$\mathsf{stable}$ for the statement: for every $(v_\#, \mathbf{w}_\#, \mathbf{g}_\#)$ satisfying (equation eq.PoissonCluster of the paper) and (equation eq.vg of the paper), and $\mathbf{w}_\#$ an anti-symmetric vector field  supported on $\overrightarrow{E_d}({\scaleobj{1}{\square}}_m)$, then the following weighted estimate holds
		\begin{multline}
			\sum_{\substack{{\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}}_m)}} |{\scaleobj{1}{\square}}|^{\alpha}\sum_{e\in \mathcal{E}\left(\mathscr{C}_{**}^\#(\mathsf{r}{\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}_m)\right)} |\nabla v_\#(e)|^2\\
			\leqslant  C\sum_{\substack{{\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h+1}({\scaleobj{1}{\square}}_m)}}|{\scaleobj{1}{\square}}|^3\sum_{e\in E_d\left(\mathsf{r}{\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}_m\right)} \left(|\mathbf{w}_\#(e)|^2 + \vert \mathbf{g}_\#(e) \vert^2\right).
		\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:MNGridDimTheory of arXiv:2508.08150, 'Recent Progress on Fractal Percolation'] Let $F$ be fractal percolation on the $M\times N$ grid with retention probability $p$. If $p\leq
1/(MN)$ then $F=\varnothing$ almost surely, otherwise, there is a positive probability that $F\neq
\varnothing$. Assuming that $1/(MN)<p\leq 1$, for almost all realisations, conditioned on non-extinction,
\begin{equation*}
\dim_{\mathrm{H}}F=\dim_{\mathrm{B}}F=
\begin{cases}
\log(pMN)/\log M, &\text{if } 1/(MN)<p\leq 1/N; \\
1+\log(pN)/\log N,  &\text{if } 1/N<p\leq 1,
\end{cases}
\end{equation*}
moreover, $\dim_{\mathrm{A}} F=2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

