[Defn defi_kin_measure of arXiv:2608.30548, 'Finite speed of propagation and waiting time phenomena for stochastic porous media equatio'] A kinetic measure is a mapping $q$ from  $\Omega$  to the space of non-negative, locally finite measures on  $\mathbb{T}^d \times (0,\infty)\times[0,T] $ such that
\begin{equation}
(\omega,t) \,\mapsto \int_0^t \int_{\mathbb{R}} \int_{\mathbb{T}^d}  \psi (x,v ) \,\mathrm{d} q(\omega)
\end{equation}
defines an $\mathscr{F}$-predictable process, for all $\psi \in C_c^\infty( \mathbb{T}^d\times(0,\infty))$.

[Cor 39 of arXiv:2608.26698, 'Mapping class groups of simply connected closed spin 5-manifolds with no 2- and 3-torsion '] Let $M$ be a simply connected closed spin 5-manifold, and let $S : S^4 \times D^1 \hookrightarrow M$ be an embedding.
      	\begin{itemize}
      		\item[(1)] The Dehn twist about $S$ acts trivially on $H_*(M)$.

      		\item[(2)] If $H_2(M)$ has no 2-torsion, then the Dehn twist about $S$ is isotopic to $id_M$.

      		\item[(3)] If $H_2(M)$ is isomorphic to $\mathbb{Z}$ or ${(\mathbb{Z}/{p^r})}^2$, where $p$ is a prime number, then the Dehn twist about $S$ is isotopic to $id_M$.
      	\end{itemize}

[Definition anti-shift-functions of arXiv:2412.08400, '\vspace{-1.0cm} Characterization of Exponential Families of \\ Lumpable Stochastic Matrice'] {nagaoka2005exponential}}]

Let
\begin{equation*}
\begin{split}
\mathcal{N}(\mathcal{Y}, \mathcal{E}) \triangleq \bigg\{ &N \in \mathcal{F}(\mathcal{Y}, \mathcal{E}) \colon \exists (c, f) \in (\mathbb{R}, \mathbb{R}^\mathcal{Y}), \forall (y, y') \in \mathcal{E}, N(y, y') = f(y') - f(y) + c \bigg\},
\end{split}
\end{equation*}
and observe that 
$\mathcal{N}(\mathcal{Y}, \mathcal{E})$ forms a $\left| \mathcal{Y} \right|$-dimensional vector subspace.

[Prop 23 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\psi\in \mathscr{C}_c^\infty(\R)$. Let $\alpha, \alpha_1$ and $\alpha_2$ be as in \eqref{Conditions entre alpha 1 et 2, et N - 2} and \eqref{Conditions entre alpha 1 et 2, et N - 3}. Let $\widetilde{m}\in \mathscr{C}^\infty(\mc{T}_{\A{1},\A{2}},]0,+\infty[)$ be an order function on $\mc{T}_{\A{1},\A{2}}$ (as in Definition \ref{Def order function sur le tore biscornu}) such that $\Tilde{m}(\widetilde{\rho})=1$ for all $\widetilde{\rho}=(\widetilde{\rho}_1,\widetilde{\rho}_2)$ satisfying
    \begin{equation}
        \dfrac{\widetilde{q}_0\pr{h^\eta\alpha^{1/2}\widetilde{\rho}_1,\alpha^{1/2}\widetilde{\rho}_2}}{\alpha}\leq \sup\pr{\mathrm{supp}(\psi)}+\dfrac{1}{C}

    \end{equation}
    where $C$ is independent of $\alpha$, and $\widetilde{q}_0$ is given in \eqref{Dvpt de Borel pour le théorème central}. Then, \eqref{Proposition formule Hellfer-Sjös - formule 2} holds in $S(\widetilde{m},\A{1},\A{2})$ for $h$ and $\widetilde{h}$ sufficiently small.

[Lemma lem:two-point-discrepancy of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $\beta\in\mathbb{R}$ and set
	\begin{equation}
		\mathfrak c_\beta\coloneqq \cosh(\beta)\; \text{.}
	\end{equation}
	For $\mathbf x=(x_1,x_2)\in\mathbb{Z}^2$, the two-point discrepancy  $e^{-F_\beta}(\mathbf x)
		\ttonde{\ensuremath{\mathcal L}^{(2)}-\ensuremath{\mathcal L}^{\otimes2}}e^{F_\beta}(\mathbf x)$ in (equation eq:k-discrepancy of the paper) with $k=2$
	depends only on the gap
	$x\coloneqq x_1-x_2\in \mathbb{Z}$ and is given by
	\begin{equation}
    \begin{aligned}
		\left(\mathfrak c_\beta-1\right)
		\set{
			\mathfrak c_\beta \mathbf{1}_{\{x=0\}}
			-
			\frac12\mathbf{1}_{\{x=1\}}
			-
			\frac12\mathbf{1}_{\{x=-1\}}
		}= \left(\mathfrak c_\beta-1\right)\Phi_1(x)+\left(\mathfrak c_\beta-1\right)^2\Phi_2(x)\; \text{,}\;\;
        \end{aligned}
	\end{equation}
	where
	\begin{equation}
		\Phi_1(x)
		\coloneqq
			\mathbf{1}_{\{x=0\}}
			-
			\frac12\mathbf{1}_{\{x=1\}}
			-
			\frac12\mathbf{1}_{\{x=-1\}}\; \text{,}\;\;\qquad \Phi_2(x)=\mathbf{1}_{\{x=0\}}\; \text{.}
	\end{equation}
    Moreover, the terms $\Phi_1$ and $\Phi_2$ satisfy \begin{equation}
    \sum_{x\in \mathbb{Z}}\Phi_1(x)\,\pi(x)=0\qquad \text{and}\qquad \sum_{x\in \mathbb{Z}}\Phi_2(x)\,\pi(x)=1\; \text{.}
\end{equation}

[Theorem thm:staggeredtraces of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Suppose $\lambda=\ell_1\ell_2\ell_3\ell_4$ is in positive parabolic normal form along $B$. Then, as $t \to 0$,
\begin{equation*}
	\tr\rho_t(\ell_1\ell_2) = \epsilon_1\epsilon_2\frac{-a_1a_2}{\theta(t)}(1 + O(t)) \ \ \ \ \tr\rho_t(\ell_1\ell_2\ell_3) = \epsilon_1\epsilon_2\epsilon_3\frac{-a_1a_2}{\theta(t)}(1 + O(t))
\end{equation*}
\begin{equation*}
	\tr\rho_t(\lambda) = \epsilon_1\epsilon_2\epsilon_3\epsilon_4\frac{-a_1a_2}{2\theta(t)}(1 + O(t))
\end{equation*}
In particular, $\rho_t(\ell_1\dots\ell_k)$ is hyperbolic for $k = 2, 3, 4$ and all sufficiently small $t$, and $I_\lambda$ has a pole.

