[Lemma 27 of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] Suppose that
    \begin{align*}
        \frac{W(B_k,B_{k-1})}{m(B_k)}
        \sum_{j=k}^{+\infty}
        \frac{m(B_j)}{W(B_j,B_{j-1})}
        \longrightarrow\kappa_W\in(0,+\infty)
    \end{align*}
    locally uniformly in $x$, where the limit $\kappa_W$ is independent of
    $x$. Then every admissible solution has an $L^2$ normal derivative, and
    \begin{align*}
         \partial_n^{(W)}\varphi=\kappa_Wg_\varphi.
    \end{align*}

