body:
[Lem overtake-bound of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Suppose that $(X_{i})_{i \in \mathbb{N}}$, $(X'_{i})_{i \in \mathbb{N}}$ and $Y$ are mutually independent random variables, with $(X_{i})_{i \in \mathbb{N}} \sim (X'_{i})_{i \in \mathbb{N}}$. Suppose that, for $k \in \mathbb{N}_{0}$, there exists $\lambda > 0$ such that
    \begin{equation} 
    \prod_{i=k}^{\infty}\E{e^{\lambda  (X'_{i} - X_{i})}} < \infty.  
    \end{equation}
    Then, for any $\ell \in \mathbb{N}$
    \begin{equation} 
        \Prob{\exists j \in \mathbb{N}\colon Y + \sum_{i=1}^{k + j} X_{i} \leq \sum_{i=k}^{k+j} X'_{i}} \leq \left(\prod_{i=k}^{\infty}\E{e^{\lambda  (X'_{i} - X_{i})}}\right) \E{e^{- \lambda \left(Y + \sum_{i=1}^{k-1} X_{i}\right)}}.
    \end{equation}

