body:
[Lemma h_bound of arXiv:2411.07878, 'Bernstein-type and Bennett-type inequalities for unbounded matrix martingales'] The inverse function of $h(x) = (x + 1) \ln(x+1) - x$ satisfies
    \begin{equation}

        h^{-1}(u) \le \sqrt{2 u} + \frac{2u}{\hspace{0.2em}\underline{\log}\hspace{0.2em} 2u}.
    \end{equation}

[Prop prop-2-1 of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] Assume that (equation katei-f of the paper). Then, (equation eq-intro-1 of the paper) admits the unique singular radial stationary solution $(\lambda_{*}, U_{*})$. Moreover, $U_{*}\in C^2_{\mathrm{loc}}(0,1]\cap H^{1}_{0}(B_1)$ and $U_{*}$ is
\begin{enumerate}
    \item[(i)] unstable if $N\le 9$;
    \item[(ii)] stable and $u^{*}=U_{*}$ if $N\ge 10$ and $f\le f_H$ in $B_{1}$;
    \item[(iii)] unstable if $N\ge 10$, $f\ge f_H$ in $B_{1}$ and $f\not \equiv f_H$.
\end{enumerate}
In addition, for the case $N\ge 10$, we have 
\begin{equation*}
    K(r):= \lambda_{*}e^{U_{*}}-\frac{2N-4}{r^2}\in C^{0}[0,1].
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Robust1 of arXiv:2606.19313, 'Stability of Khintchine-type inequalities via log-monotonicity'] Suppose $p=2q$ for some integer $q\geq 1$ and $(a_1, a_2, \ldots, a_n)\in \mathbb{R}^n$ satisfies $\sum_ka_k^2=1$. Furthermore, suppose $X$ is a symmetric random variable and $X_1, X_2, \ldots, X_n$ are iid copies of $X$. Let $r_k=r_k(X)$. Then $S=\sum_ka_kX_k$ satisfies the following bounds.
\begin{enumerate}
\item If $(r_k)$ is log-concave, then $r_1r_{q-1}-r_q\geq 0$ and
\begin{align*}
\| S \|_p^p\geq \textstyle\Big(\frac{\| X \|_p}{\| X \|_2}\Big)^p\| S \|_2^p+ \displaystyle 2^q\gamma_p^p(r_1r_{q-1}-r_{q})\Big(1- \sum_ka_k^p\Big);
\end{align*} 

\item If $(r_k)$ is log-convex, then $r_q-r_1r_{q-1}\geq 0$ and
\begin{align*}
\| S \|_p^p\leq \textstyle\Big(\frac{\| X \|_p}{\| X \|_2}\Big)^p\| S \|_2^p- \displaystyle 2^q\gamma_p^p(r_{q}-r_1r_{q-1})\Big(1- \sum_ka_k^p\Big).
\end{align*}  
\end{enumerate}Moreover, the constants are asymptotically sharp near the coordinate extremizers. (Proof in the paper; no proof environment follows the statement in the TeX.)

