[Definition Norm on configuration space of arXiv:2505.16585, 'Expanded regimes of area law for lattice Yang--Mills theories'] For parameters $\lambda, \gamma,\rho, > 0$, define the following norm on $\R^{\Omega}$:
\begin{equs}
\|f\|_{\lambda,\gamma, \rho}:=\sup_{(s,K,Q) \in \Omega} \gamma^{|\mathrm{supp}(B-K) \backslash \ptl Q|}\rho^{\sum_{p \in \mc{P}_{\Lambda}^+ \backslash (P \cup \partial Q)} (B-K(p))}\lambda^{\iota(s)}\exp(10^{-2} B|Q|) |f(s,K,Q)|.
\end{equs}

Since $\Omega$ is finite, every function $f \in \R^{\Omega}$ has finite norm.

[Lemma lem:pairvectors of arXiv:2609.00668, 'Rigidity of Euclidean Minimal Hypersurfaces under Nonuniform Diagonal Dilations'] Along $\Sigma$, every $V_{ij}$ is tangent and
\begin{equation}
C_{ij}[F]=\operatorname{Hess}F(V_{ij},V_{ij})=|\nabla F|\,II(V_{ij},V_{ij}),
\end{equation}
up to orientation. Moreover,
\begin{equation}
\sum_{i<j}V_{ij}V_{ij}^{\!\top}=|\nabla F|^2I-\nabla F\nabla F^{\!\top},
\end{equation}
and consequently
\begin{equation}
\mathcal M[F]=\sum_{i<j}\operatorname{Hess}F(V_{ij},V_{ij}).
\end{equation}

[Lemma 14 (Some estimates due to Aronson) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] There exists a constant $M > 0$ such that, for all $t > 0$ and $z_0 \in \R^2$,
\begin{equation}
\frac{1}{Mt} \, e^{-M|z - z_0|^2 / t - Mt} \leq p_t^{z_0}(z) \leq \frac{M}{t} \, e^{-|z - z_0|^2 / Mt + Mt}.
\end{equation}
Let $g_t^{z_0}(z)$ be defined by
\[
g_t^{z_0}(z) := \int_0^t p_s^{z_0}(u, 0) \, ds.
\]
Then,
\begin{equation}
g_t^{z_0}(z) \leq \frac{M^2 \, e^{ -\frac{|z - z_0|^2}{Mt} + Mt }}{|z - z_0|^2} \, t.
\end{equation}
Finally, for all $z_0 = (a_0, b_0) \in \R^2$ and $x \in \R$,
\begin{equation}
\E_{(a_0, b_0)}\left[e^{x A_t}\right] \leq e^{x^2 M t + a_0 x}.
\end{equation}

[Lemma 11 of arXiv:2506.18063, 'Reduced critical branching processes in non-favorable random environment \thanks{ This wor'] (Theorem 1 in \cite{VD2023B}). Let Conditions B1 and B2 be
valid and let $r_{1},r_{2},...,$ be a sequence of positive integers such
that $r_{n}\leq n$ and $r_{n}\rightarrow \infty $. If $\varphi (n),n\in
\mathbb{N},$ is a deterministic function such that $a_{n}\gg \varphi
(n)\rightarrow \infty $ as $n\rightarrow \infty $, then
\begin{equation*}
\mathcal{L}\left( X_{u}^{r_{n},n},0\leq u\leq 1|S_{n}\leq \varphi
(n),Z_{n}>0\right) \underset{n\rightarrow \infty }{\Longrightarrow }\mathcal{
L}\left( W_{u},0\leq u\leq 1\right) ,
\end{equation*}
where $\left\{ W_{u},0\leq u\leq 1\right\} $ is a stochastic process with
a.s. constant paths, that is
\begin{equation*}
\mathbf{P}\left( W_{u}=W\text{ for all }u\in (0,1]\right) =1
\end{equation*}
for some random variable $W$. Furthermore,
\begin{equation*}
\mathbf{P}\left( 0<W<\infty \right) =1.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem eq:NTn of arXiv:2606.02340, 'Transitivity in Inhomogeneous Random Tournaments'] Let $N_{\triangle}(T_n)$ be as defined in (equation eq:N of the paper). Then 
\begin{align}
N_{\triangle}(T_n)=\sum_{1\le u<v< w\le n}Q(u,\,v,\,w) , 

\end{align} 
where $Q(u,\,v,\,w)=\frac{1}{2}\left(a_{uv}a_{vw}+a_{vw}a_{wu}+a_{wu}a_{uv}+a_{vu}a_{wv}+a_{wv}a_{uw}+a_{uw}a_{vu}-1\right)$.

