[Thm Bennett's inequality of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] [concentration-inequalities-BLMbook]
Let $Y_1,Y_2,...,Y_n$ be independent random variables with finite variances such that  $\forall$ $ i \leq n$, $Y_i \leq b$, for some $b > 0$ almost surely. Let
            \begin{align*}
                S=\sum_{i=1}^n\left(Y_i-\mathbb{E}[Y_i]\right),
            \end{align*}
        and $\nu = \sum_{i=1}^n\mathbb{E}[{Y_i}^2] .$ Then for any $t >0,$ we have
            \begin{align*}
                \mathbb{P}(S > t)\leq \exp\left(-\frac{\nu}{b^2}h\Big(\frac{bt}{\nu}\Big)\right),
            \end{align*}
        where $h(u) = (1 + u) \log(1 + u)- u \textit{, for } u > 0.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 25 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\gamma\in(0,1)$, $\alpha\in\mathbb R$ and 
$h\in Z\hat C^{\gamma}(\Delta^3_T;B_\alpha)$.  If
\begin{equation}

B\in C(\Delta^2_T;B_\alpha),\quad \hat\delta B = h,
\end{equation}
then, for every $\tau\in[0,T]$,
\begin{equation}

\bigl(\hat\Lambda_{S,\gamma,\alpha}^{\mathrm q}h\bigr)^\tau=[\Theta_\tau B]_\tau .
\end{equation}
In particular,
\begin{equation}

\bigl(\hat\Lambda_{S,\gamma,\alpha}^{\mathrm q}h\bigr)^\tau=[b^\tau(h)]_\tau,\quad b^\tau(h)_{ts}:=-h^\tau_{ts0}.
\end{equation}
Consequently, the quotient class $\bigl(\hat\Lambda_{S,\gamma,\alpha}^{\mathrm q}h\bigr)^\tau$ is independent of both the chosen semigroup increment \(B\) and the dyadic normalization used in Section~\ref{sec:dyadic-frozen}.

[Theorem 14 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Assume that:
	\begin{itemize}
		\item $\xi^1 \leq \xi^2$.
		\item $
		f^1\left(t, Y_t^2, Z_t^2,U^2_t\right) \leq f^2\left(t, Y_t^2, Z_t^2,U^2_t\right),~t \in [0,T],~d\mathbb{P}\otimes dt\text{-a.e.}
		$
		\item $\L^1_t \leq \L^2_t$, $\forall t \in [0,T]$ a.s.
	\end{itemize}
	Then, $Y^1_t \leq Y^2_t$, $\forall t \in [0,T]$ a.s.

