[Lemma lem:density evolu of arXiv:2512.12124, 'A discontinuous percolation phase transition on the hierarchical lattice'] \emph{\textbf{Part (A):}}
    Let $\varpi \in \Lambda_{M_{g}+jr,\infty}$ for some $g \geq g_0$ and $jr \in \left\{ r,\ldots, \bar{r}_{g+1} \right\}$. 
    If $\varpi$ is good or mediocre, then there exists a non-bad set $U \subset \Lambda_{M_{g},\infty}$ with
    \begin{equation*}
        |U| \geq L^{jr} - \sum_{k=0}^{j-1} \# \operatorname{Def}_{M_g + kr}(\varpi) L^{kr}
    \end{equation*}
    such that $\sigma \subset \varpi$ for all $\sigma \in U$ and
    \begin{equation}
        S(\varpi) \geq \sum_{\sigma \in U} S(\sigma) \geq (1-\zeta)^2 \theta_g  L^{M_{g}+jr}.
    \end{equation}
    \emph{\textbf{Part (B):}}
    If $\varpi \in \Lambda_{M_g,\infty}$ is good, with a defect at level $n \in \{M_{g-1}, M_{g-1}+r,\ldots,M_{g} - r \}$, then
    \begin{equation}
        |K_{\max}(\varpi)| \geq \theta_g L^{M_{g}} - 2N L^n \geq (1-\zeta) \theta_g L^{M_g}  .
    \end{equation}
    If $\varpi \in \Lambda_{M_g,\infty}$ is mediocre, with a defect at level $n \in \{M_{g-1}, M_{g-1}+r,\ldots,M_{g} - 2r \}$, then
    \begin{equation}
        \sum_{\varphi \in \chi_{r}(\varpi)}  |K_{\max}(\varphi)| \geq \theta_g L^{M_{g}} - 2N L^n \geq (1-\zeta) \theta_g L^{M_g} .
    \end{equation}
    If $\varpi \in \Lambda_{M_g,\infty}$ is good or mediocre, without a defect, then 
    \begin{equation*}
        S(\varpi) \geq \theta_g L^{M_{g}}  .
    \end{equation*}

