[Lemma lem:B-discrete of arXiv:2608.12147, 'The Average Singular Value of a Complex Gaussian Random Matrix Strictly Decreases with Dim'] For every $N\geqslant1$,
\begin{equation}
  B_N=N\left[-h_N+\frac34h_{N-1}
  -3\sum_{j=2}^N\frac{c_j^2}{(2j-3)(2j-1)}h_{N-j}\right].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition type of arXiv:2411.05235, 'A comparative study of three mathematical approaches applied to the reversal of AMR'] \textbf{Equilibrium Point of an Ordinary Differential Equation.}\\
   Consider the ordinary differential equation:
\begin{equation}
  \frac{dx}{dt} = b(x), 
\end{equation}
where $b$ is a continuous function on a non-empty interval $I \subset \mathbb{R}$, and let $\xi \in I$. We say that $\xi$ is an equilibrium point of ((ODE of the paper)), or that $\xi$ is a trivial solution of ((ODE of the paper)), if and only if $b(\xi) = 0$.

[Corollary cor:fin-add-price-equality of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\Omega,\mathcal{Z})$ be an arbitrage-free positive linear gamble space.
  Then
  \begin{equation}

    \overline{\textsf{\textbf{E}}} X
    =
    \overline{\mathbb{E}}^{0,f} X := 
    \sup_{Q\in\Delta_{0,f}(\mathcal{Z})} \mathbb{E}_Q X~,
  \end{equation}
  for all $X\in\mathcal{X}_b$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 30 of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] Let $\beta > 0$. There exists $\varepsilon=\varepsilon(\beta) > 0$ that depends continuously on $\beta$ such that for every $\Lambda \subset V$ finite, every edge $xy \in \overline{E}(\Lambda)$, and every increasing function $f: (\mathbb{R}^{+})^{\overline{\Lambda}} \times \{0,1\}^{\overline{E}(\Lambda)}    \rightarrow \mathbb{R}$,
    \begin{equation*}
        \mathrm{Cov}_{\Lambda, \beta}^{(\xi, \sfb)} \left(f, \frac{2\sfa_x \sfa_y \omega_{xy}}{p_{xy}} - \sfa_x \sfa_y \right) \geq \varepsilon \mathrm{Cov}_{\Lambda, \beta}^{(\xi, \sfb)}(f, \omega_{xy}).
    \end{equation*}

[Defn d:dl of arXiv:2607.18194, 'Temperature chaos in directed polymers'] The \emph{directed landscape} $\mathcal{L}$ is the unique $C(\mathbb{R}^{4}_{\uparrow})$-valued random variable satisfying the following properties. 
\begin{enumerate}
    \item 
    For any finite collection of disjoint time intervals $\{(s_i,t_i)\}_{i=1,\dots,k}$, the random functions $\{\mathcal{L}(s_i,{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}; t_i, {\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}})\}_{i=1,\dots, k}$ are independent.
    \item 
    Almost surely, for all $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$ and all $r\in (s,t)$, we have
    \begin{align*}
        \mathcal{L}(s,x;t,y) = \sup_{z\in \mathbb{R}}\left(\mathcal{L}(s,x;r,z) + \mathcal{L}(r,z;t,y)\right).
    \end{align*}
    \item 
    For all $s<t$, the random function $(x,y)\mapsto \mathcal{L}(s,x;t,y)$ has the same law as $(x,y)\mapsto (t-s)^{1/3}\mathcal{L}(0,(t-s)^{-2/3}x;1,(t-s)^{-2/3}y)$.
    \item $\mathcal{L}(0,{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}};1,{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}})$ is distributed as the Airy sheet (see [dov]).
\end{enumerate}

