[Defn of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] We define a time--dependent $\beta$-stochastic operator formally expressed as
    \begin{equation}
        \mathcal{H}_{\beta}(t) := -\frac{d^2}{dx^2}+x+\frac{2}{\sqrt{\beta}}\xi_1(t).
    \end{equation}
    More precisely, for $f \in H^{1,1}_{0}(0,\infty):= \{u \in L^2(0,\infty): u',xu \in L^2(0,\infty), u(0)=0\}$, define $\mathcal{H}_{\beta}(t)f$ as the distribution such that for any $g \in C_0^{\infty}(0,\infty)$,
    \begin{equation}
        \langle \mathcal{H}_{\beta}(t) f,  g \rangle := \int_{0}^{\infty} (f'(x) g'(x)+xf(x)g(x))dx+\frac{2}{\sqrt{\beta}}\int_{0}^{\infty} f(x)g(x) \xi_1(t)[dx],
    \end{equation}
    with $\int_{0}^{\infty} f(x)g(x) \xi_1(t)[dx] = \langle \xi_1(t), f(x)g(x) \rangle$.

[Defn of arXiv:2411.09988, 'A Study in Markov Chains, Loop-Erased Random Walk and Loop Soups'] If $\omega = [\omega_0, \omega_1, \ldots, \omega_n]$ is a path, then its \textit{(chronological) loop erasure}, denoted by $LE(\omega)$, is the SAW $\eta = [\eta_0, \eta_1, \ldots, \eta_k]$ defined as follows.
    \begin{itemize}
        \item Set $\eta_0: = \omega_0$.
        \item If $\omega_n = \omega_0$, we set $k=0$ and terminate; otherwise, let $\eta_1$ be the first vertex in $\omega$ after the last visit to $\omega_0$, that is, $\eta_1: = \omega_{i+1}$, where $i: = max\{j; \omega_j = \omega_0\}$.
        \item If $\omega_n = \eta_1$, then we set $k=1$ and terminate; otherwise, let $\eta_2$ be the first vertex in $\omega$ after the last visit to $\eta_1$, and so on.
    \end{itemize}

[Defn def-boltzmann-lr of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] For $l , r \in \mathbbm N$, let $\mathcal M_{l ,r}$ be the set of finite bipolar-oriented triangulations with boundary having $l$ edges on their left boundary and $r$ edges on their right boundary. 
We define the \textbf{Boltzmann distribution} on bipolar-oriented triangulations \textbf{with left boundary length $l$ and right boundary length $r$} exactly as in Definition~(def-boltzmann-right of the paper), but with both the left and right boundary lengths fixed. That is, it is the law of a random bipolar-oriented triangulation $M(l,r)$ such that for every bipolar-oriented triangulation $\mathfrak{m}$ with $l$ left boundary edges, $r$ right boundary edges, and $n$ total edges,  
\begin{equation} 
\mathbbm P\mathopen{}\mathclose\bgroup\originalleft[ M(l,r) = \mathfrak m \aftergroup\egroup\originalright] = \frac{3^{-n} }{C_{l,r}},    
\end{equation}
where $C_{l,r}$ is a normalizing constant. Equivalently, $M(l,r)$ is a sample from the conditional law of a Boltzmann bipolar-oriented triangulation with $r$ right boundary edges (Definition~(def-boltzmann-right of the paper)) given that its left boundary length is $l$.

[Definition of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $\Omega = \{0, 1\}^E$ with $E$ at most countable. For $\omega \in \Omega$ and $F, G \subset E$ such that $F \cap G = \emptyset$, we denote
  \begin{equation}
    \omega^F_G : e \in E \mapsto \begin{cases}
      1 & \text{ if } e \in F \\
      0 & \text{ if } e \in G \\
      \omega(e) & \text{ otherwise}
    \end{cases}
  \end{equation}
  If $F$ or $G$ is empty, we omit it. If $F$ or $G$ is a singleton $\{e\}$, we write $e$ instead of $\{e\}$\footnote{We always write $\omega(e)$ for the actual value of the $e$-component of $\omega$ in order to avoid confusion.}.
  Consider an increasing event $A \subset \Omega$. We define the event that $e \in E$ is pivotal for $A$ to be
  \begin{equation}
    \{\omega \in \Omega: (\omega_e \notin A) \wedge (\omega^e \in A)\}.
  \end{equation}

[Lem many-edges-and-gradients-bound of arXiv:2609.01499, 'On the rigidity of sloped height functions in $d\ge 3$ \\ and non-crossing surfaces'] Fix any $\vec{f},\vec{\Delta}$ and compatible $\vec{\mathcal W}$. Let $\Phi$ be the map on configurations on $\mathcal E_{\vec{f},\vec{\Delta},\vec{\mathcal W}}$ as per Definition~(def:Phi-multi-edges of the paper). For any $\phi \in \mathcal E_{\vec{f},\vec{\Delta},\vec{\mathcal W}}$
    \begin{align*}
        H_{\mathcal P}(\phi) - H_{\mathcal P}(\Phi(\phi)) \ge \sum_{f\in E_1({\vec{\mathcal W}})} V_1(W_f) \,.
    \end{align*}
    Further, the number of witnesses $\vec{\mathcal W}$ having $\sum_{f} V_1(W_f) \le V_1(1)  k$ is at most $C^k$ for a constant $C(d)>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Def_FamilyOfLocalResidueConditions of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Here is how to consider local residue conditions in families:
  \begin{enumerate}
  \item
    \begin{enumerate}
    \item
      The \defined{universal branching locus} is the tame Fréchet submanifold
      \begin{equation*}
        \mathbf{Br}
        \coloneq
        \set[\big]{
          ({\mathbf{p}},[{\mathfrak l}];x) \in \mathbf{Dir} \times \mathbf{Ram} \times X : x \in \mathrm{Br}({\mathfrak l})
        }
        \subseteq
        \mathbf{Dir} \times \mathbf{Ram}\times X.
      \end{equation*}
      The projection map $p \mskip0.5mu\colon\thinspace \mathbf{Br} \to \mathbf{Dir} \times \mathbf{Ram}$ is a fibre bundle.
    \item
      The normal bundle ${\mathbf{N}} \coloneq N\mathbf{Br}$ shall be identified with
      \begin{equation*}
        {\mathbf{N}} = \coprod_{({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir} \times \mathbf{Ram}} N\mathrm{Br}({\mathfrak l}).
      \end{equation*}
      It inherits a Euclidean metric from the metrics on $X$ which are part of ${\mathbf{p}} \in \mathbf{Dir}$.
      This induces an isomorphism $(\Lambda^2 {\mathbf{N}})^{\otimes 2} \cong \mathbb{R}$ and endows
      \begin{equation*}
        \mathbb{A} \coloneq \mathbb{R} \oplus i \Lambda^2 {\mathbf{N}}
      \end{equation*}
      with the structure of a bundle of algebras over $\mathbf{Br}$,
      whose fibres are isomorphic to $\mathbb{C}$, but canonically only up to complex conjugation.
    \item
      The construction from  [BeraWalpuski2025] explained in (Sec_ResidueMap of the paper), parametrised by $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir} \times \mathbf{Ram}$, assembles into an $\mathbb{A}$--module ${\mathbf{N}}^{-1/2}$.      
    \item
      Clifford multiplication endows $\mathrm{pr}_X^*S$ to $\mathbf{Br}$ with the structure of an $\mathbb{A}$--module.    
      The \defined{universal residue bundle} is the rank $r$ Euclidean bundle over $\mathbf{Br}$ defined by
      \begin{equation*}
        \check {\mathbf{S}} \coloneq
        \mathrm{pr}_X^*S \otimes_\mathbb{A} {\mathbf{N}}^{-1/2}
        =
        \coprod_{({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir} \times \mathbf{Ram}} \check S_{\mathbf{p}}.
      \end{equation*}
    \end{enumerate}
  \item
    A \defined{family of local residue conditions} $({\mathbf{B}},f,{\mathbf{V}})$ consists of:
    \begin{enumerate}
    \item
      a tame Fréchet manifold ${\mathbf{B}}$,
    \item
      a tame smooth map $f \mskip0.5mu\colon\thinspace {\mathbf{B}} \to \mathbf{Dir} \times \mathbf{Ram}$, and
    \item
      a subbundle ${\mathbf{V}} \subseteq (p^*f)^* \check {\mathbf{S}}$.
    \end{enumerate}
    Here $f^*p \mskip0.5mu\colon\thinspace f^*\mathbf{Br} \to {\mathbf{B}}$ is the pullback of the universal branching locus and $p^*f \mskip0.5mu\colon\thinspace f^*\mathbf{Br} \to \mathbf{Br}$ is the projection map;
    see (Fig_FamiliesOfLocalResidueConditions of the paper).
  \item
    A family of local residue conditions $({\mathbf{B}},f,{\mathbf{V}})$ defines a family of residue conditions $({\mathbf{B}},f,{\mathbf{R}})$
    such that for every $b \in {\mathbf{B}}$ 
    \begin{equation*}
      {\mathbf{R}}_b \coloneq \Gamma(Z_b,{\mathbf{V}}|_{Z_b}) \subseteq \Gamma(Z_b,\check S_{{\mathbf{p}}_b})
      \quad\text{with}\quad    
      ({\mathbf{p}}_b;Z_b,[{\mathfrak l}_b]) \coloneq f(b).
      \qedhere
    \end{equation*}
  \end{enumerate}

[Lemma 22 of arXiv:2608.29501, 'Disorder Thresholds and Free Energy of Brownian Directed Polymers with\\ Product and Radia'] Let \(G_{\bm\alpha}\) be defined by \eqref{eq:Galpha}, and let
\(Z\sim N(0,I_d)\).  There is \(C<\infty\) such that
\begin{equation}
  \sup_{a\in\R^d}
  \E\big[G_{\bm\alpha}(a+\sqrt sZ)\big]
  \le C(1+s)^{-\kappa/2}.

\end{equation}
For every \(L<\infty\), there is \(c_L>0\) such that
\begin{equation}
  |a|\le L\sqrt s
  \quad\Longrightarrow\quad
  \E\big[G_{\bm\alpha}(a+\sqrt sZ)\big]
  \ge c_L(1+s)^{-\kappa/2}.

\end{equation}

