[Theorem th:2 of arXiv:2608.13559, 'Equi-dependence implying independence'] Suppose that condition (equation eq:=p of the paper) holds for all $i\in\mathbb{N}$, and for some $q\in(0,1)$ we have 
\begin{equation*}
	\frac1n\,\sum_{i\in[n]} \operatorname{\mathsf{P}}(A|B_i)\to q
\end{equation*}
as $n\to\infty$, where, as usual, $[n]:=\{1,\dots,n\}$. Then $\operatorname{\mathsf{P}}(A)=q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 13 (Well-posedness, classical cases ($q=p$)) of arXiv:2608.19753, 'Uniform large deviation principles for the stochastic heat equation over unbounded sets of'] Suppose that Assumption \ref{asm} holds. Let $\eps,N \in[ 0,\infty)$  and $u\in \A_N$.  
\begin{enumerate}
\item  If $x\in L^p(D)$ and $\tilde p\in(4,\infty)$, then there exists a unique mild solution $X_x^{\eps,u}$ to \eqref{eq:split X} that belongs to $L^{\tilde p}(\Om;C([0,T]; L^p(D)))$. 
\item If $x\in C(D)$ and $\tilde p\in(6,\infty)$, then there exists a unique mild solution $X_x^{\eps,u}$ to \eqref{eq:split X} that belongs to $L^{\tilde p}(\Om;C([0,T];C(D)))$. 
\end{enumerate}

