[Lemma 15 of arXiv:2604.22567, 'Sign-balance of random Laplace eigenfunctions'] $\, $

\begin{enumerate}[i.] 

\item
For every $T\ge 1$ and $x,y\in\Mcc$, one has
\begin{equation*}
K_{\le T}(x,y) =   c_{d}\cdot \frac{T^{d}}{ N(T)}\cdot \frac{J_{d/2}(rT)}{(rT)^{d/2}}  + O\left(T^{-1}\right) = 
\frac{(2\pi)^{d/2}}{V_{d}}\cdot \frac{J_{d/2}(rT)}{(rT)^{d/2}}  + O\left(T^{-1}\right),
\end{equation*}
where $$c_{d} = \frac{|\Mcc|}{(2\pi)^{d/2}}$$
is a dimensional constant, and the constant implicit in the `$O$'-notation only depends on $\Mcc$.

\item Let $\Mcc=\Sc^{d}$ be the round sphere, and recall the notation in \eqref{eq:N<=ell sphere sum enrg} and \eqref{eq:covar full band sphere}. For every $\ell\ge 1$ and $x,y\in\Sc^{d}$ so that $\theta:= d(x,y)\in \left[0,\frac{\pi}{2}\right]$, one has
\begin{equation}

K_{\le\ell}(\theta) = c_{d}\cdot \frac{\ell^{d}}{N(\ell)} \Big( \mu(\ell)\kappa(\theta)J_{d/2}\Big(\Big(\ell+\frac{d}{2} \Big)\theta \Big) + O\Big(\frac{1}{\theta^{(d-1)/2}\ell^{(d+3)/2}} \Big)   \Big),
\end{equation}
where $$c_{d}=\frac{|\Sc^{d}|}{2^{d}\pi^{d/2}}$$ is a dimensional constant,
\begin{equation}

\kappa(\theta) =  ( \sin(\theta/2))^{-d/2} (\cos(\theta/2))^{-(d-2)/2} \Big(\frac{\theta}{\sin{\theta}}\Big)^{1/2}  = 2^{d/2}\cdot \theta^{-d/2}+O_{\theta\rightarrow 0}\left(\theta^{-d/2+1}\right),
\end{equation}
\begin{equation}

\mu(\ell) = \frac{ (\ell + d/2)^{-d/2+1}  (\ell+d-1)! }{ \ell^d \ell !  } =\ell^{-d/2}\cdot \Big(1+ O \Big( \frac{1}{\ell} \Big)\Big),
\end{equation}
and
\begin{equation*}
\frac{\ell^{d}}{N(\ell)} = \frac{(2\pi)^{d}}{|\Sc^{d}|\cdot V_{d}}\cdot \Big(1+ O \Big( \frac{1}{\ell} \Big) \Big),
\end{equation*}
and the constant implicit in the `$O$'-notation only depends on $d$.
\end{enumerate}

