body:
[Theorem 5 of arXiv:2608.29152, 'Uniform Statistical Convergence of Empirical Sinkhorn Potentials\\ with Exponential and Po'] Suppose Assumption~\ref{ass:metric-entropy} holds.
For any $\delta\in(0,1)$, define the statistical error terms 
\begin{equation}
 q_{\nu,n}(\delta) := \frac{C_{\mathrm D}}{\sqrt n} \left[ \Gamma_{\nu,\eps} + B_\eps\sqrt{\log\frac4\delta} \right], \qquad
 q_{\mu,n}(\delta) := \frac{C_{\mathrm D}}{\sqrt n} \left[ \Gamma_{\mu,\eps} + B_\eps\sqrt{\log\frac4\delta} \right].
\end{equation}
With probability at least $1-\delta$, the estimation errors satisfy:
\begin{equation}
 d_\infty([\widehat f_{\eps,n}],[f_\eps]) \le \frac{\eps B_\eps}{1-\tau_\eps^2} \bigl(\tau_\eps q_{\mu,n}(\delta) + q_{\nu,n}(\delta)\bigr). 
\end{equation}
The analogous bound holds for $d_\infty([\widehat g_{\eps,n}],[g_\eps])$ by swapping variables.
For a fixed $\eps>0$, this implies a rate of $O_{\Prob}(n^{-1/2})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma pointwise-crit-cocomplete of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $\textbf{\textup{U}}\subset\ul\Spc_T\subset\ul\CAT_T$ be any full subcategory. Then a $T$-$\infty$-category ${\mathcal{C}}$ is $\textbf{\textup{U}}$-cocomplete if and only if the following conditions are satisfied:
    \begin{enumerate}
        \item For every $A\in T$ and $(u\colon X\to A)\in\textbf{\textup{U}}(A)\subset\PSh(T)_{/A}$ the restriction $u^*\colon{\mathcal{C}}(A)\to{\mathcal{C}}(X)$ admits a left adjoint $u_!$.
        \item For every $A,B\in T$ and every pullback square
        \[
            \begin{tikzcd}
                Y\arrow[d,"v"']\arrow[r,"g"]\arrow[dr,pullback] & X\arrow[d,"u"]\\
                B\arrow[r,"f"'] & A
            \end{tikzcd}
        \]
        in $\PSh(T)$ such that $u\in\textbf{\textup{U}}(A)$ (whence $v\in\textbf{\textup{U}}(B)$), the Beck--Chevalley map $v_!g^*\to f^*u_!$ is invertible.
    \end{enumerate}
    Moreover, in this case conditions (1) and (2) hold more generally without the representability condition, i.e.\ for all $A,B\in\PSh(T)$.\qed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 of arXiv:2609.01485, 'On the Ramification of Quadratic Fields where the Torsion of a Rational Elliptic Curve Gro'] Let $E/\mathbb{Q}_p$ be an elliptic curve. Let $L|\mathbb{Q}_p^{\mathrm{nr}}$ be the extension previously defined and $\Phi_p:=\Gal(L/\mathbb{Q}_p^{\mathrm{nr}})$. Then for all $p\neq 2,3$ we have:
     {\small
     \begin{enumerate}
         \item $\#\Phi_p = 2\iff \text{ $E$ has Kodaira symbol $I_0^*$} \iff v_p(\Delta) \equiv 6 \mod 12$ 
         \item $\#\Phi_p = 3\iff \text{ $E$ has Kodaira symbol $IV$ or $IV^*$} \iff v_p(\Delta) \equiv 4 \text{ or } 8 \mod 12$
         \item $\#\Phi_p = 4\iff \text{ $E$ has Kodaira symbol $III$ or $III^*$} \iff v_p(\Delta) \equiv 3 \text{ or } 9 \mod 12$
         \item $\#\Phi_p = 6\iff \text{ $E$ has Kodaira symbol $II$ or $II^*$} \iff v_p(\Delta) \equiv 2 \text{ or } 10 \mod 12$
     \end{enumerate}}
If $p=2,3$, then 
\begin{enumerate}
         \item If $p = 3$,  $\Phi_p$ is a cyclic group of order $2,3,4,5,6$ or a non-abelian semidirect product of a cyclic group of order $4$ with a normal subgroup of order $3$.
         \item If $p = 2$, $\Phi_p$ is isomorphic to a subgroup of $\SL_2(\mathbb{F}_3)$ and its order is $2,3,4,6,8$ o $24$. Moreover, $\#\Phi_p = 3$ if, and only if, the Kodaira symbol of $E$ is $IV$ or $IV^*$.
     \end{enumerate}

[Theorem prop:chfuntheta2 of arXiv:2411.19192, 'Characteristic function and Esscher transform of a switching Levy model for the temperatur'] Let $(T_t)_{t \geq 0}$ be the temperature process given by equations ((eq:tempdyna of the paper)), ((eq:seass2 of the paper)) and ((eq:tchlevy2 of the paper)) starting at regime one. Then,  the Esscher measure $\mathcal{Q}^{\theta}$ is an EMM  if  for any $t>0$ the parameter $\theta$ verifies under the conditions $\lambda_{12}>max(\alpha+\theta,0)$ and  $\lambda_{12} < \lambda_{21}$ the equation:
 \begin{equation}
R(t,\theta)= \sigma^{-1} e^{\alpha t}(e^{rt} T_0-C_1(t, \alpha))
   \end{equation}
   where:
  \begin{eqnarray*}
 R(t,\theta)&=& -i  \left[ D_1(t,\theta) C_5(0, \theta)+ D_2(t,\theta) \right]\\

  \end{eqnarray*}
  The expressions $D_1(t,\theta)$ and $D_2(t,\theta)$  are given  by:
  \begin{eqnarray*}
  D_1(t,\theta) &=&  -i \alpha \left[\left(A_{12}(\theta, \alpha)+A_{21}(\theta, \alpha)\right)E_{\theta}[N_t]+
 A_{12}(\theta, \alpha) p^{\theta}_O(t) \right] \\ 
 && \\
 D_2(t,\theta) &:=&  \frac{dC_5(u \sigma^{1}e^{\alpha t}, \theta,k)}{du}|_{u=0} = \sum_{k=0}^{+\infty}   \frac{dJ^{\theta}_3(u \sigma^{-1}e^{\alpha t},k)}{du}|_{u=0}  p^{\theta}_{2k}(t)\\ \nonumber
  &+&  \sum_{k=0}^{+\infty}  \frac{dJ^{\theta}_4(u \sigma^{-1}e^{\alpha t},k)}{du}|_{u=0}p^{\theta}_{2k+1}(t) \\ 
 &&
  \end{eqnarray*}
 where $p^{\theta}_{O}(t)$ is the probability to observe an odd number of regime changes in the  interval $[0,t)$.

