[Definition def-condlim of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Fix an edge potential $h$, and $c \in \R$, $c \neq \sref.$ Let $\Conset_n(h,c)$ and  $(c_\delta)_{\delta > 0}$ be  as in Definition (\oldref{def-rareevent}) and  (equation sdelta of the paper), respectively. 
\begin{enumerate}
\item Given $\rho^*\in \P(\Gstar[\X])$, we say  that {\em   $U_n$  given $\Conset_n(h,c)$ converges to $\rho^*$ } if  
   \begin{align}
\lim_{\delta\downarrow0}\lim_{n\to \infty}\mathbb{P}(U_n\in \cdot\mid \Conset_n(h, c_\delta))=\delta_{\rho^*}(\cdot).
\end{align}
    \item 
For any $\mathcal{U}\subset \P(\Gstar[\X]),$ we say that {\em  $U_n$ given $\Conset_n(h,c)$ lies in $\mathcal{U}$ asymptotically} if for every open set $U\supset \mathcal{U}$, the following holds:
    \begin{align}
        \lim_{\delta\downarrow 0}\limsup_{n\to \infty}\frac{1}{n}\log\mathbb{P}\left(U_n\notin U\ \vert\ 
        \Conset_n(h,c_\delta) \right)<0.
    \end{align} 
\end{enumerate}

[Lem 26 (\textit{cf.} {\cite[THEOREM 5.4) of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] {Shigekawa}}]
Let $n \in \N$ and $F$ be a random variable. 
Suppose that, for every $m \in \{1, \ldots, n\}$, there exists $K_m \in L^p(\Omega)$ with $p > 1$ such that for all $\varphi \in C^{\infty}_{\mathrm{c}}(\R)$, 
\begin{equation}
    \E[\varphi^{(m)}(F)] = \E[\varphi(F)K_m]. 
\end{equation}
Then, the law of $F$ has a density function $\rho_F \in C_{\mathrm{b}}^{n-1}(\R)$ that satisfies
\begin{align}
    \norm{\rho_F}_{C_{\mathrm{b}}^{n-1}(\R)} \lesssim_{n,p} 
    \begin{cases}
        \norm{K_1}_{L^p(\Omega)}, &\text{when $n = 1$},\\
        \left( 1 + \sum_{m=1}^{n} \norm{K_m}_{L^p(\Omega)} \right)\norm{K_1}_{L^p(\Omega)}^{1-\frac{1}{p}}, &\text{when $n \geq 2$}.
    \end{cases}

\end{align}
Moreover, $\rho^{(j)}_{F} \in \bigcap_{r \in [1,\infty)}L^r(\R)$ holds for every $j \in \{0, \ldots, n-1\}$.

