\begin{enumerate}
    \item[(i)] \textbf{\emph{Probabilistic {\color{black}rarity}:}}
        Let $\mu_G$ be a centred Gaussian measure on $\mathcal{H}_T^2(\mathbb R^{d_X})$ whose covariance operator $Q$ is diagonal in some orthonormal basis $(\eta_n)_{n=1}^{\infty}$, with strictly positive eigenvalues $(\lambda_n)_{n=1}^{\infty}$. Then, $\mu_G(\mathfrak{B}) = 0$,
    \item[(ii)] \textbf{\emph{Topological {\color{black}rarity}:}}
        $\mathfrak{B}$ is meagre in $\mathcal{H}_T^2(\mathbb R^{d_X})$.
\end{enumerate}

