body:
[Theorem 1 of arXiv:2604.01701, '\bf Chung-type laws of the iterated logarithm for $m$-fold weighted integrated fractional '] For all  $m\ge 0$, $\gamma\ge 0$, $\alpha_1+\cdots+\alpha_i<H+\gamma+i$, $i=1,\ldots,m$, and $\alpha<H+\gamma+m$, we have that
\begin{align}
& \lim_{\epsilon\to 0} \epsilon^{1/(H+\gamma+m)}\log \pr\left(\sup_{0\le  t\le 1}\left|\frac{ J_{m,\bm\alpha}(I_{\gamma}B_H)(t)}{t^{\alpha-\alpha_1-\cdots-\alpha_m}}\right|<a_H \epsilon\right)\nonumber\\
=& \lim_{\epsilon\to 0} \epsilon^{1/(H+\gamma+m)}\log \pr\left(\sup_{0\le  t\le 1}\left|\frac{J_{m,\bm\alpha}(W_{H+\gamma})(t)}{t^{\alpha-\alpha_1-\cdots-\alpha_m}}\right|< \epsilon\right) 
=-\frac{\kappa_{H+\gamma+m}}{1-\alpha/(H+\gamma+m)}
\end{align}
and
\begin{align}
 &\liminf_{T\to \infty}  \frac{(\log\log T)^{H+\gamma+m}}{T^{H+\gamma+m-\alpha}}\sup_{0\le  t\le T}\left|\frac{ J_{m,\bm\alpha}(I_{\gamma}B_H)(t)}{t^{\alpha-\alpha_1-\cdots-\alpha_m}}\right|\nonumber\\
 =&a_H\liminf_{T\to \infty} \frac{(\log\log T)^{H+\gamma+m}}{T^{H+\gamma+m-\alpha}}\sup_{0\le  t\le T}\left|\frac{J_{m,\bm\alpha}(W_{H+\gamma})(t)}{t^{\alpha-\alpha_1-\cdots-\alpha_m}}\right|\nonumber\\
 = &a_H\left( \frac{\kappa_{H+\gamma+m}}{ 1-\alpha/(H+\gamma+m)}\right)^{H+\gamma+m}\;\; a.s.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2DHD-the5.3 of arXiv:2604.21591, '\bf Long-time dynamics of stochastic 2D hydrodynamic-type evolution equations driven by mu'] Under the hypotheses of Lemma $(2DHD-lem5.1 of the paper)$. There exists $
		\varepsilon_0=\sqrt{\frac{\mu \lambda_1}{2L_g}}$ such that for any $\varepsilon_1, \varepsilon_2 \in (0,\varepsilon_0]$, system  (equation 2DHD-1.01 of the paper) with initial value $u(0)=u_{0}$ has an invariant measure $\tilde{\mu}$ on $H$, that is to say, there exists a probability measure $\tilde{\mu}$ in $H$ such that for any $\phi\in C_b(H)$ and $t\geq 0$,
		\begin{equation}
			\int_{H}\left(\int_{H}\phi(x)p(0,y;t,dx)\right)d\tilde{\mu}(y)=\int_{H} \phi(y)d\tilde{\mu}(y).
		\end{equation}

[Lem 53 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $X$ be a right process on $E$, $u\in b\mathcal{B}$, $A \in \mathcal{B}$ and $\alpha\geq 0$. 
The following assertions hold:
\begin{enumerate}
    \item[(i)] The function $B_{\alpha}^A u$ is finely continuous on $({E\setminus A})^{\circ_f}$, where $B^{\circ_f}$ denotes the interior of a set $B\subset E$ with respect to the fine topology.
    \item[(ii)] If $u$ is finely continuous then $B_{\alpha}^A u$ is finely continuous.
\end{enumerate}

[Theorem thm:local_clt_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
\begin{equation}

    \varsigma_n^2 = \mleft( 1 - p(1-p) \sum_{j=1}^K \beta_j p^{\mathsf{e}_j-2} \sum_{\rho \in \mathcal{V}_j} \mathsf{d}_\rho (\mathsf{d}_\rho-1) \mright)^{-1} \times p (1-p) (n-1).
\end{equation}
Then for any deterministic vertex $v \in [n]$ and any $\varepsilon > 0$, we have
\begin{equation}
    \mathbf{d} \mleft( \frac{\mathsf{deg}_v(X) - \mathbb{E}[\mathsf{deg}_v(X)]}{\varsigma_n}, Z \mright) \lesssim n^{-\frac{1}{4}+\varepsilon},
\end{equation}
for both $\mathbf{d} = \mathbf{d}_\mathrm{Was}$ and $\mathbf{d} = \mathbf{d}_\mathrm{Kol}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:1st-pivotal of arXiv:2506.06559, 'Bi-infinite incipient cluster in high dimensions'] For $x \not= x'$ and $x, x' \not\in W$, we have

\eqnspl{e:1st-expansion-1st-stage}
{ \sigma(F;x,x')
  &= \mathbf{P}_0 [ E(F;x, x') ]
    + \sum_{\{u_0,v_0\} \not\in E_W} p D(u_0,v_0) 
      \mathbf{E}_0 \Big[ I [ \widetilde{E}(F;u_0,v_0,x') ] \tau^{\widetilde{\mathcal{C}}_0}(v_0,x) \Big]. }

[Lemma 28 of arXiv:2609.00285, 'Multicrossing complex of knot and secant classes'] Let links $L=K_1\cup\cdots\cup K_m$ and $L'$ obtained from $L$ by switching a crossing $c$ on components $K_p$ and $K_q$, $1\le p,q\le m$. Then for any $i\ne j\ne k\ne l$
\begin{equation}
   I^+_{ijkl}(L)-I^+_{ijkl}(L')=\left\{\begin{array}{cl}
        \sgn(c)lk_{kl}, & \{i,j\}=\{p,q\}, \{k,l\}\ne\{p,q\}, \\
        \sgn(c)lk_{ij}, & \{i,j\}\ne\{p,q\}, \{k,l\}=\{p,q\}, \\
        2\sgn(c)lk_{ij}-1, & \{i,j\}=\{k,l\}=\{p,q\}, \\
        0, &   \{i,j\}\ne\{p,q\}, \{k,l\}\ne\{p,q\}.
    \end{array}\right.
\end{equation}

