body:
[Thm t:converge_Airy_details of arXiv:2411.10586, 'A convergence framework for Airy$_\beta$ line ensemble\\ via pole evolution'] For each $n\in\mathbb{N}$, let $\{\lambda^{(n)}_i(t)\}_{i=1}^n$ be either the stationary DBM (equation e:DBMV of the paper) with fixed general potential $V$ satisfying (a:Vasump of the paper), Laguerre process (equation e:stationary_Laguerre of the paper), or Jacobi process (equation e:Jacobi of the paper).
Take $n\to\infty$, with
\begin{itemize}
    \item $\limsup m/n<\infty$ and $\liminf m/n >1$ in the Laguerre case;
    \item $\limsup p/n, \limsup q/n <\infty$, $\liminf p/n>1$, $\liminf q/n>0$ in the Jacobi case.
\end{itemize}
Then we have that
$\{(\lambda^{(n)}_i(\zeta t) - E)/\chi \}_{i=1}^\infty$
converges to ALE$_\beta$, under the uniform in compact topology. Here we take the convention of $\lambda^{(n)}_i=-\infty$ for $i>n$, and $E, \zeta, \chi$ are as follows:
\begin{itemize}
    \item[DBM:] 
    \begin{equation}   
        E=Bn^{1/2}, \zeta=R^{-4/3}n^{-1/3}, \chi=R^{-2/3}n^{-1/6},
    \end{equation}
    where $B$, $R$, and $\varrho_V$ from (a:Vasump of the paper);
    \item[Laguerre:]
    \begin{equation}   
        E=(\sqrt{m}+\sqrt{n})^2, \zeta=2^{-1}(\sqrt{m}+\sqrt{n})^{2/3}(mn)^{-1/3}, \chi=(\sqrt{m}+\sqrt{n})^{4/3}(mn)^{-1/6};
    \end{equation}
    \item[Jacobi:] 
    \begin{equation}   
        E=\left(\frac{\sqrt{p(m-n)}+\sqrt{qn}}{m}\right)^2, \zeta=\frac{(E(1-E))^{1/3}}{2(pq(m-n))^{1/3}}n^{-1/3}, \chi=\frac{(E(1-E))^{2/3}}{(pq(m-n))^{1/6}}n^{-1/6}.
    \end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm1stResult of arXiv:2606.13615, 'Data-Driven Subsampling Rates for Diffusion Parameter Estimation of SDEs'] Suppose that Assumption (Assumptions of the paper) holds, let $\mathbf{X}_0$ be an initial random variable independent of $\mathbf{W}$, and let $\mathbf{X} = (\mathbf{X}_t)_{t \geq 0}$ be the corresponding solution to (equation eqGenSDEIntro of the paper) with $d$-th component $X = (X_t)_{t \geq 0}$. Then the probability distribution of the length of the first monotone run of the sampled process $(X_{n\delta})_{n \in \mathbb{N}_0}$ converges to the geometric distribution with parameter $1/2$ as $\delta \rightarrow 0$ , i.e., for all $\ell \in \mathbb{N} \cup \lbrace \infty \rbrace$ it holds that
\begin{equation*}
\lim_{\delta \rightarrow 0} P( T_{1,\delta}(X) = \ell) = \frac{1}{2^\ell},
\end{equation*}
where we set $1/2^\infty \coloneq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm domination2GeneralOlD of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] The probability measure $\ensuremath{\mathbb{P}}^{(1)}_{I^{(1)}}( \cdot \;|\; \ensuremath{\mathcal{C}}^{(1)})$ is equal, in law, to  
\begin{equation}\sum_{\mathbf{y}} \ensuremath{\mathbb{P}}^{(1)}_{I^{(1)}}(\mathbf{y} \;|\; \ensuremath{\mathcal{C}}^{(1)}) \sum_{k=1}^{\kappa}\ensuremath{\mathcal{L}}(Y^{(k)}|\mathbf{y}), \quad \text{ where:}\end{equation}
\begin{itemize}
    \item $\mathbf{y} = (y_1,...,y_K)$ with $K\leq \kappa$, and $\ensuremath{\mathbb{P}}^{(1)}_{I^{(1)}}(\mathbf{y} \;|\; \ensuremath{\mathcal{C}}^{(1)})$ is the probability that the iteration of Lemma (lemma:decomposition of the paper) using Corollary (lemma:decompositionK of the paper) terminates after $K$ steps and $Y^{(k,k)}=y_k$, $k=1,...,K$;
    \item For $k=1,\dots,K$, $\ensuremath{\mathcal{L}}(Y^{(k)}|\mathbf{y}) =\ensuremath{\mathcal{L}}(Y^{(1,k)}|\mathbf{y})$ is the law of the random lifts $Y^{(1)}_k \in I^{(1)}$ of $Y^{(k,k)} = y_k$ given $\mathbf{y} = (y_1,...,y_K)$.
    \item For $k>K$, $\ensuremath{\mathcal{L}}(Y^{(k)}|\mathbf{y})$ is the law of the additional random lifts of points appearing from the iteration procedure.
    \item Given $\mathbf{y}$, the random variables $(Y^{(k)}|\mathbf{y})$ are independent.
\end{itemize}
Furthermore, there is an $n \in \ensuremath{\mathbb{N}}$ such that $\ensuremath{\mathbb{P}}^{(1)}_{I^{(1)}}( \cdot \;|\; \ensuremath{\mathcal{C}}^{(1)})$ is stochastically dominated by 
\begin{align}
\ensuremath{\mathbb{P}}^{(1)}_{I^{(1)}}  \bigoplus \sum_{\mathbf{y}} \ensuremath{\mathbb{P}}^{(1)}_{I^{(1)}}(\mathbf{y} \;|\; \ensuremath{\mathcal{C}}^{(1)}) \sum_{k=1}^{|\mathbf{y}|}\sum_{j=1}^{n}\ensuremath{\mathcal{L}}(Y_j^{(1,k)}|\mathbf{y}),
\end{align}
where, given $\mathbf{y} = (y_1,...,y_K)$, the $Y_j^{(1,k)}$ are independent random lifts  of $Y^{(k,k)} = y_k$.

[Lemma lem:ybound of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] Denoting $\tilde C=C+\log(d+1)+10$, for any $y \in \tilde \Omega_C$ we have that $\tilde w(y) +h(y) \geq 0$, and 
\begin{align}
&\textstyle e^{-\tilde C}-1 < y_i <e^{\tilde C/2},\, \quad \quad \quad i=1,\dotso, k, \\
&\textstyle e^{-\tilde C/2 } < y_j < 1, \, \quad  \quad \quad \quad \quad  j=k+1, \dotso, d, \notag \\
&\textstyle e^{-\tilde C/2 } < 1-\sum_{l=1}^dT_l(y)<1. \notag
\end{align}

