[Proposition lem:char of arXiv:2509.23086, 'On Optimal Markovian Couplings of L\'evy Processes'] \leavevmode
	\begin{enumerate}[label=(\roman*)]
		\item Let $\mu,\mu_n \in \Lambda(\mathbb{R}^d)$ for $n \geq 1$. The following are equivalent:
		\begin{itemize}
			\item $\mu_n \xrightarrow{\Lambda} \mu$ ($\Lambda$-weak convergence);
			\item $\tilde{\mu}_n \to \tilde{\mu}$ weakly on $\mathbb{R}^d \setminus \{0\}$.
		\end{itemize}

		\item Let $\mathcal{N} \subset \Lambda(\mathbb{R}^d)$ be a family of Lévy measures. The following are equivalent:
		\begin{itemize}
			\item $\mathcal{N}$ is $\Lambda$-tight;
			\item $\tilde{\mathcal{N}} := \{\tilde{\mu} : \mu \in \mathcal{N}\}$ is tight on $\mathbb{R}^d \setminus \{0\}$.
		\end{itemize}
	\end{enumerate}

