[Proposition TFA:Controles_demandes_pour_le_RMS_et_le_CPS of arXiv:2504.03627, 'Richardson’s model and the contact process with stirring: long time behavior.'] \begin{enumerate}
    \item Let $\lambda>2d\lambda_c^{\mathrm{CP}}(d)$ and $(\xi_t)_{t\ge 0}$ be a $\mathrm{RMS}(\lambda,1)$. There exist some constants $A,B,M_1,M_2>0$ such that, for all $t\ge 0$ and $x\in \mathbb Z^d$:
\begin{align*}
\mathbb P(\exists y\in \mathbb Z^d,~t(y)\le t \text{ and } ||y||\ge M_1t)&\le A\exp(-Bt),\\
\mathbb P(t(x)>M_2||x||+t)&\le A\exp(-Bt).
\end{align*}
    \item  Let $\nu>0$, $\lambda>(2d\nu+1)\lambda_c^{\mathrm{CP}}(d)$ and $(\xi_t)_{t\ge 0}$ be a $\mathrm{CPS}(\lambda,1,\nu)$. There exist some constants $A,B,M_1,M_2>0$ such that, for all $t\ge 0$ and $x\in \mathbb Z^d$:
\begin{align*}
\mathbb P(\exists y\in \mathbb Z^d,~t(y)\le t  \text{ and } ||y||\ge M_1t)&\le A\exp(-Bt),\\
\mathbb P(t<\tau<+\infty)&\le A\exp(-Bt),\\
\mathbb P(t(x)>M||x||+t)&\le A\exp(-Bt).
\end{align*}
\end{enumerate}

