body:
[Defin eq:def_h of arXiv:2605.31054, 'On the empirical spectral distribution of matrix perpetuities'] Let $({\mathbf A}_n)_{n\ge 1}$ be iid copies of ${\mathbf A}$ and set
\[
\Pi_n:={\mathbf A}_n\cdots {\mathbf A}_1,\qquad {\bf M}_n:=\Pi_n \Pi_n^\top\in\mathrm{Sym}_{\geq0}(N).
\]
Fix $k\in\{1,\ldots,N\}$ and define 
\begin{align}
h_k(s):=    \inf_{n\in\mathbb{N}} {\mathbb E}\left[ \prod_{i=1}^k \lambda_i({\bf M}_n)^{s/k}\right]^{1/n}
\end{align}
for nonnegative $s$ such that $ {\mathbb E}\left[ \prod_{i=1}^k \lambda_i({\mathbf A} {\mathbf A}^\top)^{s/k}\right]<\infty$.

[Lemm 8 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] Let $\Tz := (X,Y,Z)$ be the unique solution to the FBSDEs satisfying all the conditions in Lemma~\ref{p-exist}.
    Then, the following a priori estimate holds:
    \begin{align}
        \|\Tz\|^p_{p,*} \leq c_{\eqref{p-estimate}}
        &\E\Biggl[|\xi|^p + |g(0)|^p + \Biggl(\int_t^T |b^0(s)|\,\od s\Biggr)^p \notag\\
        &\quad + \Biggl(\int_t^T |\mu^0(s)|^2\,\od s\Biggr)^{p/2} + \Biggl(\int_t^T |f^0(s)|\,\od s\Biggr)^p\Biggr] < \infty,
    \end{align}
    where the constant $c_{\eqref{p-estimate}}$ depends only on $p$, $\dz$, and all the Lipschitz constants.

    Furthermore, consider another set of coefficients
    $(\wt{\xi},\wt{b},\wt{\mu},\wt{f},\wt{g})$ that satisfies all the conditions in Lemma~\ref{p-exist},
    and shares the same Lipschitz constants as $(\xi,b,\mu,f,g)$.
    Let $\wt{\Tz} = (\wt{X},\wt{Y},\wt{Z})$ be the corresponding solution to the modified FBSDEs.
    Then, the following stability estimate holds:
    \begin{align}
        \|\wt{\Tz} - \Tz\|^p_{p,*}
        \leq c_{\eqref{p-var:equ}} 
        &\E\Biggl[|\xi - \wt{\xi}|^p + |g(X_T) - \wt{g}(X_T)|^p + V_p([t,T])\Biggr],
    \end{align}
    where
    \begin{align*}
        V_p([t,T]) 
        &:= \Biggl(\int_t^T |\Delta b(s,\Tz_s)|\,\od s\Biggr)^p 
        + \Biggl(\int_t^T |\Delta \mu(s,\Tz_s)|^2\,\od s\Biggr)^{p/2}\\
        &\quad\quad + \Biggl(\int_t^T |\Delta f(s,\Tz_s)|\,\od s\Biggr)^p,
    \end{align*}
    with
    \begin{equation*}
        \Delta h := h - \wt{h}, \quad h\in\{b,\mu,f\}.
    \end{equation*}
    The constant $c_{\eqref{p-var:equ}}$ depends only on $p$, $\dz$, and all the Lipschitz constants. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 6 of arXiv:2506.10650, 'Admitted symmetries of Backward Stochastic Differential Equations'] \cite[p.~12]{sym11091153}
     For any $(X_t,Y_t,Z_t)$ solution of the FBSDE \eqref{FBSDE int form Meleshko}, we have that 
     \begin{equation}
         \Tilde{Y}_{\Tilde{T}} = H(\Tilde{X}_{\tilde{T}}) \,\,\text{holds if and olny if}\,\, \gamma(t,x,H(x))=H_x \xi(t,x,H(x))
     \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:cpconstr of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $g$ be sufficiently small and denote ${\bm\rho}_0 = C_{\cD} g$.
Let $p^1 \vec{\textbf{a}} = ( \textbf{a}^{(\km)} : \km \in \kA_1  )$ and $\overline{B}_{\epsilon_p /2} = \{ p^1 \vec{\textbf{a}} : \norm{ p^1 \vec{\textbf{a}} } \le \epsilon_p /2 \}$.

Then there exists a set-valued function
\begin{align}
	\vec{N}_c :  [0,\epsilon_p / 2] \rightarrow 2^{ [-{\bm\rho}_0 , {\bm\rho}_0] \times \overline{B}_{\epsilon_p /2} } ,
	\qquad \textbf{a}^{(\emptyset)} \mapsto \vec{N}_c ( \textbf{a}^{(\emptyset)} )
\end{align}
with the following property.  
For each $\tilde\textbf{a}^{(\emptyset)} \in [0, \epsilon_p /2]$ and $\vec{b} \in \vec{N}_c (\tilde\textbf{a}^{(\emptyset)})$,
if $\vec{\nu}, \vec{\textbf{a}} \in \R^{\kA_0 \cup \kA_1}$ are given by
\begin{align}
\begin{cases}
	\nu^{(\emptyset)} =  b^{(\emptyset)}  \text{ and } \nu^{(\km)} = - b^{(\km)} \text{ for each } \km \in \kA_1 \\
	\textbf{a}^{(\emptyset)} = \tilde\textbf{a}^{(\emptyset)}  \text{ and }  \textbf{a}^{(\km)} = b^{(\km)} \text{ for each } \km \in \kA_1
\end{cases}
\end{align}
then for $\vec{\nu}_{pc}$ given by Proposition~(prop:nupcctty of the paper),
\begin{align}
	\vec{\nu}  = \vec{\nu}_{pc} ( \vec\textbf{a} ) ,

\end{align}
i.e.,  $(\nu^{(\emptyset)} ,  - p^1 \vec{\textbf{a}} )$ is critical for the RG flow with mass $(\tilde\textbf{a}^{(\emptyset)} ,   p^1 \vec{b})$. 
Moreover, the graph of $\vec{N}_c$ is compact.

