[Proposition 43 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] We suppose that $u$ can be developed in a paracontrolled system associated with \eqref{eq_gPAM} at order $\gamma$ with random data $\mcZ=(Z_\tau)_{\tau\in\mcT}$. For any $\tau\in\mcT$ and $k\in\bfN^{d+1}$ such that $|k| < \gamma-|\mcI(\tau)|$, we have
		\begin{equation} \begin{split}
			\partial_*^ku_\tau= u_{(\downarrow^k)^* \tau}.
		\end{split}\end{equation}
	For any $k\in\bfN^{d+1}$ with $|k|<\gamma$, 
	\begin{equation} \begin{split}

			\widetilde\partial^k_{*}u = \partial^k_* u.
	\end{split}\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:log-deriv of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] For $h \in H$, the \emph{logarithmic derivative} of $\mu_t$ along $h$ is the function $\beta_h: H \to \mathbb{R}$ defined $\mu_t$-almost everywhere by the integration-by-parts identity
\begin{equation}
  \int_H \ip{\nabla\phi(u)}{h}_H\,\mathrm{d}\mu_t(u) = -\int_H \phi(u)\,\beta_h(u)\,\mathrm{d}\mu_t(u)
\end{equation}
for all $\phi \in C_b^1(H)$, provided such a $\beta_h \in L^1(\mu_t)$ exists.

[Corollary 17 of arXiv:2607.17943, 'Coadjoint averaging and cross-scale fluxes in a fast-slow stochastic Euler-Arnold system o'] We have
\begin{equation}
\begin{array}{ll}
\displaystyle{\int_{\mathcal{O}^*(\Lambda)}}\mathcal{E}_{\leq K}(\Omega)dm_{\mathrm{KKS}}(\Omega) & = \dfrac{\|\Lambda\|^2}{2c_N(N^2-1)}\cdot \sum\limits_{0<|k|\leq K} \dfrac{1}{|k|^2} \ ,
\\
\displaystyle{\int_{\mathcal{O}^*(\Lambda)}}\mathcal{Z}_{\leq K}(\Omega)dm_{\mathrm{KKS}}(\Omega) & = \dfrac{\|\Lambda\|^2}{2c_N(N^2-1)}\cdot \left|\{k: 0<|k|\leq K\}\right| \ .
\end{array}
\end{equation}
Here the cumulative energy and enstrophy $\mathcal{E}_{\leq K}(\Omega)$, $\mathcal{Z}_{\leq K}(\Omega)$ are defined as in \emph{(\ref{Eq:FluxZeitlin:CumulativeLowFreqEnergyEnstropy})}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2506.19064, 'Variational formula for the logarithmic potential of free additive convolutions'] Let $\rho$ be a probability measure on $\mathbb{R}$ and $k\ge0$. Then
    \begin{equation}
        G_\rho^{(k)}(z)
        =
        k!\int\frac{1}{(x-z)^{k+1}}\rho(dx)
        \quad\text{for all}\quad
        z \notin \supp\,\rho.
    \end{equation}
    Furthermore $G_\rho^{(k)}$ is real-valued and real analytic on $(\overline{\supp}\,\rho)^c$, strictly monotone on $(\supp_+ \rho,\infty)$,



    \begin{equation}
        \text{ positive and strictly increasing on } (-\infty,\supp_-\rho),
    \end{equation}    
    \begin{equation}
        \text{ and }
        G^{(k)}_\rho(-\infty)
        \overset{\eqref{eq:f_well_defined_at_endpoints}}{=}
        \lim_{ z \downarrow -\infty} G_\rho^{(k)}(z) = 0.


    \end{equation}

