[Proposition prop:gaussian-equivalences of arXiv:2606.25976, 'Gaussian rigidity for infinite exchangeable sequences'] Suppose that \(X_1\sim\mathcal{N}(m,\sigma^2)\).
Set \(a:=2(\sigma^2-c)\), which is nonnegative by Lemma~(lem:scalar-second-moment of the paper), and let \(\gamma_a\) denote the centered Gaussian law \(\mathcal{N}(0,a)\) on \(\mathbb{R}\).  Then the following are equivalent.
\begin{enumerate}
\renewcommand{(\roman{enumi})}{(\roman{enumi})}
\renewcommand{\roman{enumi}}{\roman{enumi}}
\item \((X_i)_{i\ge1}\) is a Gaussian process.
\item \(\eta*\widetilde\eta=\gamma_a\) a.s., where \(\widetilde\eta(B)=\eta(-B)\).
\item \(M_\eta\sim\mathcal{N}(m,c)\) and \(\eta\) is the Gaussian law \(\mathcal{N}(M_\eta,\sigma^2-c)\) a.s.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2608.27374, '\Large \bf Distribution-constrained optimal multiple stopping: the Root-type solution'] For every \(t\in[t_0,r_\xi^\beta)\) and \(x\in\mathbb R\),
\begin{equation}

    u^\beta(t,x)
    =
    \inf_{\rho\in\mathcal T_t^\Gamma}
    \E^x\!\left[
        v^\xi(t-\rho,Y_\rho)
        +
        w^\beta(t-\rho)\mathbf 1_{\{\rho<t\}}
    \right].
\end{equation}

[Proposition 7 of arXiv:2609.02581, '\bfseries Interior Curvature Estimates for the Graphical Scalar Curvature Equation in All '] Let $n\geq3$. Suppose that $u$ satisfies \eqref{eq:intro-equation} and $H\geq2$. Then at a point where $h_i^j$ is diagonal, the following Jacobi-type inequality holds:
\begin{equation}
\Delta_{T_u}b\geq 2H-\frac{4}{H}-T_u^{ij}h_i^kh_{kj}+\sum_{i=1}^n\Theta_iT_u^{ii}b_i^2,
\end{equation}
where
\begin{equation}
\Theta_i:=\frac{H}{H-\kappa_i}
 \left[
 \frac{3\bigl((n+1)H^2-4H\kappa_i+2\kappa_i^2-2\bigr)}
 {(n+1)H^2-4H\kappa_i+2n\kappa_i^2-2(n+2)}-1
 \right]-1.
\end{equation}

