[Proposition prop:WicksWigner of arXiv:2510.01021, '\Large Random Matrices, Intrinsic Freeness, and Sharp Non-Asymptotic Inequalities\relatedv'] Let $W_1,\dots,W_n$ be $N\times N$ independent standard Wigner matrices (recall Definition~(def:standardWignerMatrix of the paper)). Given a partition $\nu\in\mathbb{P}[2p]$ let $u_\nu$ be the $\nu$-assignment (see Definition~(def:pairpartition of the paper)). We have
    \begin{equation}
            \mathbb{E}\left[\tr W_{u_\nu(1)}\cdots W_{u_\nu(2p)}\right]  = 1,
    \end{equation}
    if $\nu\in \mathrm{NC}[2p]$ is non-crossing, and 
\begin{equation}
            \lim_{N\to\infty} \mathbb{E}\left[\tr W_{u_\nu(1)}\cdots W_{u_\nu(2p)}\right] = 0,
    \end{equation}
if $\nu\in \mathbb{P}[2p]\setminus \mathrm{NC}[2p]$ is crossing.

    Furthermore, $W_1,\dots,W_n$ enjoy (in the limit) a Wick's formula summing only over non-crossing partitions: For $u:[2p]\to[n]$ we have
    \begin{equation}
\lim_{N\to\infty}\mathbb{E}\left[\tr W_{u(1)}\cdots W_{u(2p)}\right] = \sum_{\nu\in \mathrm{NC}_2[2p]} 1_{u \sim \nu}.
    \end{equation}
The identities (equation eq:WignerNONcrossingpairings of the paper)--(equation eq:WicksforWigner of the paper) hold for a free semicircular family $s_1,\dots,s_n$ (without needing to take a limit). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $p=1$ and~\eqref{co:1} and~\eqref{co:2} be valid. Then pathwise uniqueness holds for~\eqref{eq:SIS epidemic model}, and any two solutions $I$ and $\tilde{I}$ to~\eqref{eq:SIS epidemic model} satisfy
\begin{equation}
\E\big[|I_{t} - \tilde{I}_{t}|\big] \leq e^{\int_{0}^{t}(\hat{b}_{k+1} + \hat{\lambda}_{k+1})(s,N(s))\,\mathrm{d}s}\E\big[|I_{0} - \tilde{I}_{0}|\big]
\end{equation}
for all $t\geq 0$. In particular, if $(\hat{b}_{k+1} + \hat{\lambda}_{k+1})^{+}(\cdot,N)$ is integrable, then $\sup_{t\geq 0} \E[|I_{t} -\tilde{I}_{t}|]$ is finite. If additionally
\begin{equation*}
\int_{0}^{\infty}(\hat{b}_{k+1}+\hat{\lambda}_{k+1})^{-}(s,N(s))\,\mathrm{d}s = \infty,\quad\text{then}\quad \lim_{t\uparrow\infty} \E\big[|I_{t}-\tilde{I}_{t}|\big] = 0.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 29 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] For every fixed $a>0$, every $s\ge0$, and every integer $k\ge1$,
\begin{equation}
 \int_0^\infty e^{-a\lambda u}
 (1-e^{-\lambda u})^{a(k-1)}\dd u\ll_a(1+k)^{-a}.
\end{equation}
Moreover, for $k>e^{\lambda s}$,
\begin{equation}
 \int_0^s e^{-a\lambda u}
 (1-e^{-\lambda u})^{a(k-1)}\dd u
 \ll_a(1+k)^{-a}e^{-a k e^{-\lambda s}/4}.
\end{equation}

[Proposition Prop:Chaos of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] Let $F = \bracketsig[T]{\bm{\ell}}$ with $\bm{\ell} \in \TA$. Then $F \in \mathbb{D}^{\infty,2}$ and the kernel functions $f_{{\color{NavyBlue}{\mathbf{i_1\ldots i_n}}}}$ in the chaos expansion are given by
    \begin{equation}
        f_{{\color{NavyBlue}{\mathbf{i_1\ldots i_n}}}}(s_1, \ldots, s_n)
        = \frac{1}{n!}
        \left\langle
            \bm{\ell},\,
            \widehat{\mathcal{E}}_{s_1} 
            \otimes {\color{NavyBlue}{\mathbf{i_1}}}
            \otimes \widehat{\mathcal{E}}_{s_2 - s_1}
            \otimes {\color{NavyBlue}{\mathbf{i_2}}}
            \otimes \cdots
            \otimes {\color{NavyBlue}{\mathbf{i_n}}}
            \otimes \widehat{\mathcal{E}}_{s_n - s_{n-1}}
        \right\rangle.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 of arXiv:2604.15753, 'The truncation property and continuity for \\ the long-range contact process on $\mathbb{Z'] Let $\lambda \in \Lambda$  satisfy  $\lambda_{o,y} =\mathcal{O}( \|y\|^{-\alpha})$ for some $\alpha>2d+1$. Then, for each $\epsilon>0$, there exists 
$\theta_0 \in (0,\infty)$ and $N_0 \in \bN$ so that, for all $n\geq N_0$, and for every $A \subset B_n$ and $\delta\geq 0$, 
\begin{equation}
    \bP_{\lambda,\delta} \left( A_t^{A} \subset B_{n\theta_0/2 + t \theta_0}(o) \text{ for all } t>0 \right) \geq 1- \epsilon. 
\end{equation}

