body:
[Definition 6 ({${p}$-ary entropy function and the Johnson radius}) of arXiv:2609.00483, 'On Embedding Hamming Spheres with Applications to Positive Curvature'] Let $\delta \in [0,\frac{p-1}{p}]$.
The \emph{\bf $\mathbf{p}$-ary entropy function} $H_p(x)$ and the \emph{\bf Johnson radius} $J_p(\delta)$ are respectively defined by
\begin{align*}
H_p(x) &= x \log_p(p-1) - x \log_p x - (1 - x) \log_p(1 - x), \,\,\text{and}\\
J_p(\delta) &= \left(1 - \frac{1}{p} \right) \left(1 - \sqrt{1 - \frac{p}{p-1} \delta} \right).
\end{align*}

[Thm 5 (The Hausdorff--Young Inequality on $h\mathbb{Z}$) of arXiv:2608.16144, 'Central limit theorem in R\'enyi divergence for lattice random variables'] Suppose $1\le p\le 2$ and $1/p+1/q=1$. If $f\in \ell^p(h\mathbb Z)$, then we have
\begin{equation*}
\widehat f\in L^q\left(\left[-\frac{\pi}{h},\frac{\pi}{h}\right),\frac{h}{2\pi}\,dt\right),
\end{equation*}
and moreover
\begin{equation*}
\left(\frac{h}{2\pi}\int_{-\pi/h}^{\pi/h}|\widehat f(t)|^q\,dt\right)^{1/q}\le\left(
\sum_{k\in\mathbb Z}|f(kh)|^p\right)^{1/p}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Standard weak transport costs) of arXiv:2604.02312, 'A weak transport approach to the Schrödinger--Bass bridge'] A function $C : \mathcal X \times \Pcal_p(\mathcal Y) \to \R \cup \{+\infty\}$ is called a standard weak transport cost function if it satisfies the following properties:
\begin{enumerate}[label=(\roman*)]
    \item $C$ is lower semicontinuous;
    \item $C$ is bounded from below;
    \item for each $x \in \mathcal X$, the map $\rho \mapsto C(x,\rho)$ is convex;
    \item $C$ is proper, i.e., the effective domain of $C$,
    \[
        \operatorname{dom}(C) := \bigl\{ (x,\rho) \in \mathcal X \times \mathcal P_p(\mathcal Y) : C(x,\rho) < \infty \bigr\},
    \]
    is non-empty.
\end{enumerate}

Moreover, we say that $C$ admits a $p$-growth bound, if there exist $c>0$, $x_0 \in \mathcal{X}$, $y_0 \in \mathcal Y$ such that
\begin{equation}
    C(x,\rho) \leq c \left( 1 + d_\mathcal{X}(x_0,x)^p + \int d_\mathcal{Y}(y_0,y)^p \,\rho(\rmd y)\right), \qquad \forall \, (x,\rho) \in \mathcal X\times\cP_p(\mathcal Y).
\end{equation}

[Proposition eq:SBBS_R_formula of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] For $j=1,\dots,d-1$, $R_{j}$ in (equation eq:reflection_def of the paper) is given by 
    \begin{align}
    R_{j}  =
    \begin{cases}
    (1-\varepsilon)(0,\dots, 0, \varepsilon,0,\dots, 0)^{\top}\quad &\text{for $c=1$},\\
    (1-\varepsilon)(0,\dots, 0, (1-\varepsilon), 1,0,\dots, 0)^{\top}  \quad &\text{for $c\ge 2$},
\end{cases}
\end{align}
where $\varepsilon$ and $1$ appears in the $j+1$st coordinate, respectively. In particular, $(1-\varepsilon)\hat R^{c,\varepsilon} = [R_1,R_2,\dots, R_{d-1}]$, where $\hat{R}^{c,\varepsilon}$ is in (equation eq:sigma_R of the paper).

[Theo UniformConvergencePotOPerator of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] Let $(\mu_n)_{n\in\mathbb{N}_\infty}\subset\mathscr{K}(X)$ satisfy assumption ((PotentialConvergence of the paper)). Then for all $u\in {C}_0(X)$, it holds
\begin{enumerate} 
\item[\rm(1)] 	$\lim_{n\to\infty}\|G^{\mu_n} u - G^{\mu_\infty} u\|_\infty =0$.
\item[\rm(2)] $\lim_{n\to\infty}\|\check{R}_\alpha^n u - \check{R}_\alpha^\infty  u\|_\infty =0$ for all $\alpha\geq 0$.
\end{enumerate}

[Defn LDC of arXiv:2411.10633, 'A Geometric Perspective on the Injective Norm of Sums of Random Tensors'] A code $\mathcal{C} : \{0,1\}^n \rightarrow \{0,1\}^d$ is $(q, \delta, \varepsilon)$-locally decodable if there exists a randomized decoding algorithm $\mathsf{Dec}(\cdot)$, which takes an $i \in [k]$ as input and given oracle access to some $y \in \{0,1\}^d$ satisfies the following properties: 
\begin{enumerate}
    \item[(1)] The algorithm $\mathsf{Dec}$ never makes more than $q$ queries to the string $y$; 
    \item[(2)] For all $b \in \{0,1\}^n$, $i \in [n]$, and $y \in \{0,1\}^d$ such that $\Delta(y, \mathcal{C}(b)) \leq \delta n$, one has $\mathbb P[\mathsf{Dec}^{y}(i) = b_i] \geq \frac{1}{2} + \varepsilon$, where $\Delta(x,y)$ is the Hamming distance between $x$ and $y$. 
\end{enumerate}

[Lemma 14 of arXiv:2604.03548, 'Degree-preserving conservative processes and a unified approach for their hydrodynamics'] Assume $N\ge 4$. 
Then, there exists some $C=C(D,\mathsf{a} )>0$ such that 
\begin{equation*}
\sup_{0\le t\le T} \max_{i\in\mathbb I_N}
\mathcal T^{(1)}_N(t,i)
\le CT/N.  
\end{equation*}

