[Theorem 3 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, $p\in [1,2]$ and $q\in [1,2)$,
\begin{equation}
    \sum_{J\subseteq[n]:|J|=k}\frac{\left\|\Dop_J f\right\|_{\Leb^p}^{p}}{\big[1+\frac{q}{2k(2-q)} \ln^{+}(\left\|\Dop_J f\right\|_{\Leb^p}^{p}/\left\|\Dop_J f\right\|_{\Leb^q}^{2})\big]^{k}} \geq C^{\text{\rm\ref{thm:high-order-Lp-Lq-inf-Boolean}}}(q)^k \Wop^{\geq k}(f),
\end{equation}
where $C^{\text{\rm\ref{thm:high-order-Lp-Lq-inf-Boolean}}}(q) = \big(1+\frac{q}{2\upe(2-q)}\big)^{-1} \gtrsim 2-q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:basic_properties of arXiv:2608.27313, 'A Finite Sample Analysis for Quantile Temporal Difference Learning in Distributional Reinf'] \emph{[bdr2022]}
The following statements hold:
\begin{itemize}
    \item ${\mathcal{T}}^\pi$ is  $\gamma$-contractive under the $\bar{W}_p$ metric for every $p\in[1,\infty]$, namely for every $\bm\eta,\bm\eta^\prime\in{\mathscr{P}}^{\mathcal{S}}$, 
    \[
    \bar{W}_p({\mathcal{T}}^\pi\bm\eta,{\mathcal{T}}^\pi\bm\eta^\prime)\leq\gamma\bar{W}_p(\bm\eta,\bm\eta^\prime); 
    \]
    \item ${\bm{\Pi}}_m$ is non-expansive under the $\bar{W}_\infty$ metric, namely $\bar{W}_\infty({\bm{\Pi}}_m\bm\eta,{\bm{\Pi}}_m\bm\eta^\prime)\leq \bar{W}_\infty(\bm\eta,\bm\eta^\prime)$ for every $\bm\eta,\bm\eta^\prime\in{\mathscr{P}}^{\mathcal{S}}$.  
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

