=(B_1(\bu_n,\phi_n), \tilde{\pi}_{1,n} z_2)_{\newone{H}}
\\
&=b_1(\bu_n,\phi_n, \tilde{\pi}_{1,n} z_2)
= b_1(\bu_n - \bu,\phi_n, \tilde{\pi}_{1,n} z_2) + b_1(\bu,\phi_n - \phi, \tilde{\pi}_{1,n} z_2) + b_1(\bu,\phi, \tilde{\pi}_{1,n} z_2),
