[Defn Neutrality condition of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] A divisor $\boldsymbol{\sigma}: \widehat{\mathbb{C}} \rightarrow \mathbb{R}$ satisfies the neutrality condition if
\begin{equation}
\int \boldsymbol{\sigma}=-2.
\end{equation}
\begin{thm}
Under the neutrality condition $\int\boldsymbol{\sigma}=-2$, the normalized Coulomb gas correlation differentials $C[\boldsymbol{\sigma}]$ are Möbius invariant on $\hat{\mathbb{C}}$.
\end{thm}

\begin{proof}
By direct computation, similar to the $\kappa>0$ case.
\end{proof}

\begin{defn}[Coulomb gas correlation for a double divisor in a simply connected domain]
For a double divisor $(\boldsymbol{\sigma^+},\boldsymbol{\sigma^-})$, let $\boldsymbol{\sigma}=\boldsymbol{\sigma^+}+ \boldsymbol{\sigma}_*^{-}$ be its corresponding divisor in the Schottky double $S$, we define the Coulomb gas correlation of the double divisor $(\boldsymbol{\sigma^+},\boldsymbol{\sigma^-})$ by:

[Definition def:Gd of arXiv:2509.15446, 'On the pair correlation function of the $\Sineb$ process'] We define the operator ${\mathcal G}_\delta:{\mathbb R}^{{\mathbb Z}_{+}}\to {\mathbb R}^{{\mathbb Z}_{+}}$ acting on sequences $(a_1,a_2,\dots)$ as 
\begin{align}
    \left({\mathcal G}_\delta(a)\right)_k=\frac{k(k+\delta)}{2}a_{k-1}-k^2 a_k+\frac{k(k-\delta)}{2} a_{k+1}, \qquad k\ge 1,
\end{align}
where we set $a_0$ to be 1.

[Definition 7 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] For a given linear order $X$, we define $\varphi_\alpha(X)$ as a linear order given as follows.
    We simultaneously define principal terms of $\varphi_\alpha(X)$.
    \begin{enumerate}
        \item $0\in \varphi_\alpha(X)$.
        \item $E_x\in \varphi_\alpha(X)$ is a principal term for every $x\in X$.
        \item If $i\in\alpha$ and $\xi\in\varphi_\alpha(X)$, then $\varphi_i(\xi)$ is a principal term, provided that $\xi$ is not a single principal term of one of the following forms:
        \begin{enumerate}
            \item $E_x$ for some $x\in X$.
            \item $\varphi_j(\eta)$ for some $j\in\alpha$ with $i<j$.
        \end{enumerate}
        \item If $p_0,\ldots,p_{m-1}$ are principal terms of $\varphi_\alpha(X)$, $\varphi_\alpha(X)\vDash p_0\ge\cdots\ge p_{m-1}$, and $m>1$, then
        \begin{equation*}
        p_0+\cdots+p_{m-1}\in\varphi_\alpha(X).
        \end{equation*}
    \end{enumerate}

    Then we define $\varphi_\alpha(X)$-order as follows:
    \begin{enumerate}
        \item $\varphi_\alpha(X)\vDash 0<E_x$ for every $x\in X$.
        \item $\varphi_\alpha(X)\vDash 0<\varphi_i(\xi)$ for every $i\in\alpha$ and every $\xi\in\varphi_\alpha(X)$.
        \item $\varphi_\alpha(X)\vDash 0<p_0+\cdots+p_{m-1}$ for every sum term $p_0+\cdots+p_{m-1}$.
        \item $\varphi_\alpha(X)\vDash E_x<E_y$ iff $x<y$.
        \item For $i\in\alpha$, $\xi\in\varphi_\alpha(X)$, and $x\in X$, we have
        \begin{equation*}
        \varphi_\alpha(X)\vDash \varphi_i(\xi)<E_x \iff \varphi_\alpha(X)\vDash \xi<E_x.
        \end{equation*}
        \item For $i\in\alpha$, $\xi\in\varphi_\alpha(X)$, and $x\in X$, we have
        \begin{equation*}
        \varphi_\alpha(X)\vDash E_x<\varphi_i(\xi) \iff 
        \varphi_\alpha(X)\vDash E_x<\xi.
        \end{equation*}
        \item For $i,j\in\alpha$ and $\xi,\eta\in\varphi_\alpha(X)$, we have
        \begin{equation*}
        \varphi_\alpha(X)\vDash \varphi_i(\xi)<\varphi_j(\eta)
        \end{equation*}
        iff one of the following holds:
        \begin{enumerate}
            \item $i<j$ and $\varphi_\alpha(X)\vDash \xi<\varphi_j(\eta)$.
            \item $i=j$ and $\varphi_\alpha(X)\vDash \xi<\eta$.
            \item $j<i$ and $\varphi_\alpha(X)\vDash \varphi_i(\xi)<\eta$.
        \end{enumerate}
        \item We have
        \begin{equation*}
        \varphi_\alpha(X)\vDash p_0+\cdots+p_{m-1}<q_0+\cdots+q_{n-1}
        \end{equation*}
        iff
        \begin{enumerate}
            \item $m<n$ and $p_i=q_i$ for every $i<m$, or
            \item there is $i<\min(m,n)$ such that $\varphi_\alpha(X)\vDash p_i<q_i$ and $p_j=q_j$ for every $j<i$.
        \end{enumerate}
    \end{enumerate}

[Lemma 12 of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Let $\emprashomonset$, $\rretailset$, and $x$ satisfy Assumption \ref{assume:rashomon} for parameters $\sigma > 0$. Let $\rlocaltestmat =  \{\rlocaltest_{j}: j \in [\nogaussianpts]\}$ be a random set of perturbations of $x$, distributed $\iid \Unif(\ltwohsphere(x,\sigma))$. 
Define
    \begin{align}
    \condavg(\retailset,x)
        = \expect_{\rlocaltestmat}*{ 
            \frac{1}{\Nretail} \sum_{k=1}^{\Nretail}
            \frac{1}{\nogaussianpts} \sum_{j=1}^{\nogaussianpts}
                \abs*{f_{k}(x) - f_{k}(\rlocaltest_{j})} 
             }.
    \end{align}
Then for all $\slackparam > 0$
    \begin{align}

    \prob_{\rretailset}*{
        \abs*{
        \condavg(\rretailset,x) 
            - \expallavg(x)
            }
        \ge
        \slackparam
    }
    \le
    2 \exp\parens*{\frac{-2\Nretail\slackparam^2}{\eta^2\sigma^{2}} }.
    \end{align}

