[Proposition 191 of arXiv:2601.16377, '2601.16377'] The Green function $\textnormal{Gr}$ on $\Sigma^{\textnormal{half}}$ with Dirichlet boundary conditions has the following expression\footnote{One should compare this with (4.21), (4.22) in \cite{BuGo3} and note a sign error in that paper --- one needs to multiply $\frac{1}{4\pi}$ by $(-1)$ in both formulae. In the proofs of \cite{BuGo3} this sign error compensates with wrong signs in (4.25), (4.26) and in the computation of mixed partial derivative above (4.58).} for non-real $z_i\in \Sigma^{(q_i)}$ ($i = 1,2$):
 \begin{equation} 
 \textnormal{Gr}(z_1,z_2)= \left\{\begin{array}{lll} -\dfrac{1}{4\pi} \displaystyle\int_{z_1^*}^{z_1}\displaystyle\int_{z_2^*}^{z_2} \mathcal{F}^{(q,q)}(w_1,w_2) \dd w_1 \dd w_2- \dfrac{1}{2\pi} \log\left|\frac{z_1-z_2}{z_1-z_2^*}\right|& & \textnormal{ if }\, q_1 = q_2 = q,\\[12pt] - (-1)^{\textnormal{par}(q_1,q_2)}\dfrac{1}{4\pi} \displaystyle\int_{z_1^*}^{z_1}\displaystyle\int_{z_2^*}^{z_2} \mathcal{F}^{(q_1,q_2)}(w_1,w_2) \dd w_1 \dd w_2 && \textnormal{ if }\,\, q_1\neq q_2,\end{array}\right.
 \end{equation}
 where the parity $(-1)^{\textnormal{par}(q_1,q_2)}$ is $(+1)$ if $\mathcal T_{q_1},\mathcal T_{q_2}$ are both left, or both right trapezoids, and $(-1)$ otherwise. In particular, \eqref{eq_Green_function_explicit} extends to a continuous function of $\Sigma^{\textnormal{half}} \times \Sigma^{\textnormal{half}}$ minus the diagonal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Sparse regime) of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] Under \Cref{ass:cri-pot}, let $\nu=\gamma_1-1$. Then, there exist $\beta_0$ and $\beta_1$ (depending only on $\kappa$) such that
$$ \beta_L(x)
:=
L^{\rho+1}
\Big(
\kappa_L(x)
-1
+\beta_0 L^{-\rho}
-\beta_1 L^{-(\rho+1)} \log L
\Big) \to \beta(x), \qquad  x\in[-1,1) $$

where $\beta\in L^Q(\mu)$  if and only if $Q<d/(2\nu)$. Moreover,  the following conclusions hold:
\begin{enumerate}
\item[(i)] \textbf{Gaussian case.} If $Q>\frac{d}{2\nu}$, then
\begin{align*}
\Var(F_L) &\asymp L^{-\frac{d}{2\nu}},
&\dW(\widetilde F_L,Z) &\lesssim (\log L)^{-d/4}.
\end{align*}

\item[(ii)]\textbf{Critical case.} If $Q=\frac{d}{2\nu}$, then
\begin{align*}
\Var(F_L) &\asymp L^{-\frac{d}{2\nu}}\log L,
&\dW(\widetilde F_L,Z) &\lesssim (\log L)^{-1/2}.
\end{align*}

\item[(iii)] \textbf{Non-central case.} If $Q<\frac{d}{2\nu}$, then $\beta$ is $Q$-admissible and
\begin{align*}
\Var(F_L) &\asymp L^{-Q},
&\widetilde F_L &\xrightarrow{d} {\rm sgn}(\varphi_Q)\,\widetilde Z_Q(\widehat \beta)\,\,.
\end{align*}
where $\widehat \beta: = \beta - \int_{-1}^1 \beta(u) \di \mu(u)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 10 of arXiv:2608.29086, '2608.29086'] [$|\psi |$]
Given $M \subset M_0$ and $\psi \in TRAJ(M)$. The \textit{extended region} $|\psi|$ is defined by
\begin{equation*}
|\psi |:=|\psi |_0 \cup \left(\bigcup_{r \in HOLE(\psi)} r\right) \quad \in  REG(M_0).
\end{equation*}
The \textit{extended length} $len(\psi)$ of $\psi$ is the number of triangles in $|\psi |$, i.e.,
\begin{equation*}
len(\psi):=\sharp\{abc \in Tri(M) \  |\ abc \subset |\psi| \} \quad \in \mathbf{Z}.
\end{equation*}
Note that $|\psi |$ has no holes inside.

[Theorem 19 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Let $\{X_n;n=1,2,\cdots\}$ be a m-dependent stationary sequence in a sub-linear space $\sles$ satisfying following conditions :
\begin{itemize}
    \item[(1)] $\bE[X_1] = \be[X_1] = 0$;
    \item[(2)] $\bE[X_1^2]<\infty$;
    \item[(3)] $C_{\V}\left[\frac{X_1^2}{\log\log|X_1|}\right]<\infty$.  
\end{itemize}
Then we have 
\begin{equation}
\mvstar\left(\lsigma\le\limsup_{n\to\infty}\frac{S_n}{\sqrt{2n\log\log n}}\le\usigma\right)=1
\end{equation}
for some $0\le \lsigma\le\usigma<\infty$ where the following limits exist:
\begin{equation}
    \usigma^2:=\lim_{n\to\infty}\frac{\bE[S_n^2]}{n},\quad \lsigma^2:=\lim_{n\to\infty}\frac{\be[S_n^2]}{n}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2608.06392, '2608.06392'] Suppose that the inter-arrival distribution $F$ admits a density $f$ and the representation \eqref{AISR1.2}
    corresponding to the regime {\hyperref[AISR(iii)]{\textbf{(iii)}}}. Then the renewal density $u(t)=U'(t)$
    satisfies the asymptotic relation
\begin{equation}       
    u(t)=\frac{1}{\,\mu\,}+\frac{1}{\,\mu^2\beta\,}\,t^{-\beta}L_{\beta}(t),
\end{equation}
    where $\beta=\alpha-1$ and $L_{\beta}(t)\big/L(t)\to{1}$ as $t\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 3 of arXiv:2605.21005, 'Double-transform Tauberian method\\ for precise large deviations'] Let $(S_n,C_n)_{n\in\N_0}$ be as in Section~\ref{sec:leapGut}, with $Y_1=X_1$ and $\P(X_1>x)\sim \ell(x) x^{-\beta}/\Gamma(1-\beta)$ as $x\to\infty$ for some $\beta\in(0,1)$, $\ell$ positive slowly varying function at infinity. Then, for $(x_t)_{t\geq 0}$ such that $x_t\to\infty $ and $t/ x_t\to 0$ as $t\to\infty$, we have
\begin{equation*}
\lim_{t\to\infty} \sup_{x\geq  x_t}\left|\Gamma(1-\beta)\Gamma(1+\beta) \frac{\ell(t)\P(L_t>x)}{t^{\beta}x^{-\beta}\ell(x)}- 1 \right| =0.
\end{equation*}

