[Theorem 12 of arXiv:2606.02036, 'Self-intersection local times for Volterra Gaussian processes in stochastic flows with int'] Assume that the coefficients $a$ and $b$ of \eqref{eq:Eq_interaction} are continuously differentiable with respect to $v$ for all $\mu\in\cM_m$. Moreover, assume there exist constants $C, L>0$ such that for all $v_1,v_2\in\mbR^d,\ \mu^{(1)},\mu^{(2)}\in\cM_m, $
\begin{align*}

\norm{\D a(v_2,\mu^{(2)})-\D a(v_1,\mu^{(1)})}+\left(\int_{\mbR^d}\|\D b(v_2,\mu^{(2)},z)-\D b(v_1,\mu^{(1)},z)\|^2_{HS}\differential{z}\right)^{\frac{1}{2}} &{}\leq L \dist_m((v_1, \mu^{(1)}), (v_2, \mu^{(2)})), 
\\

\sup_{\mu\in\cM_m}\sup_{v\in\mbR^d}\left(\norm{\D a(v,\mu)}+\Big(\int_{\mbR^d}\|\D b(v,\mu,z)\|^2_{HS}\differential{z}\right)^{\frac{1}{2}}\Big)&{} \leqslant C.
\end{align*}
Then, there exists a modification of the solution to \eqref{eq:Eq_interaction} that is a stochastic flow of diffeomorphisms (see Appendix \ref{def:stochastic flows}) such that $\det\D x(v,t)$, the determinant of the Jacobian,  satisfies the following equation 
\begin{align*}

\det\D x(v,t) &{} =\exp\left(\int^t_0 \trace\  \D a(x(v,s),\mu_s)\differential{s}

-\frac{1}{2} \trace\int^t_0\int_{\mbR^d}\D b(x(v,s),\mu_s,z)\odot \D b(x(v,s),\mu_s,z)\differential{z}\differential{s}\right.\\
&{}\quad\quad\quad  \left.+\trace\int^t_0\int_{\mbR^d}\D b(x(v,s),\mu_s,z)W(\differential{s},\differential{z})\right).
\end{align*}

