[Thm 3 (The superposition principle; \cite{BoRoSh21}, \cite{Tr16}) of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] \label[thm]{rem:Trevisan_superposition}
Let $\left(\mu_t\right)_{t\in [s,T]}$ be a weakly continuous solution to \eqref{eq:LFPshort}, and suppose further that
\begin{equation}
    \int_s^T\int_{B(0,R)} \frac{|\langle b(t,x),x\rangle|+\|a(t,x)\|}{(1+\|x\|)^2} \; \mu_t(dx) dt <\infty.
\end{equation}
Then, according to \cite[Theorem 1.1]{BoRoSh21}, there exists $\eta\in \mathcal{P}\left(C\left([s, T];\mathbb{R}^d\right)\right)$ a solution to the canonical martingale problem associated to $({\sf L}_t)_{t\in [s,T]}$ on $[s,T]$ such that the one-dimensional time marginals $(\eta_t)_{t\in[s,T]}$ satisfy $\eta_t=\mu_t,t\in[s,T]$.
Moreover, by \cite[Proposition 2.8]{Tr16}, for each $x\in \mathbb{R}^d$ there exists a probability $\eta^{x}\in \mathcal{P}\left(C\left([s, T];\mathbb{R}^d\right)\right)$ such that
\begin{enumerate}[(i)]
    \item For every $A\in \mathcal{B}\left(C\left([s,T];\mathbb{R}^d\right)\right)$
    \begin{equation*}
       \mbox{ the mapping } \mathbb{R}^d\ni x\mapsto \eta^{x}(A) \mbox{ is Borel measurable and } \eta(A)=\int_{\mathbb{R}^d}\eta^{x}(A) \;\mu_s(dx).  
    \end{equation*}
    \item For $\mu_s$-a.e. $x\in \mathbb{R}^d$, $\eta^{x}$ is a solution to the martingale problem associated to $({\sf L}_t)_{t\in [s,T]}$ on $[s,T]$, with initial distribution $\delta_x$. 
\end{enumerate}
As a consequence, if $\nu_s\in \mathcal{P}(\mathbb{R}^d)$ satisfies $\nu_s\leq c\mu_s$ for some constant $c\in (0,\infty)$, then 
\begin{equation*}
    \eta^{\nu_s}(\cdot):=\int_{\mathbb{R}^d}\eta^{x}(\cdot)\;\nu_s(dx)
\end{equation*}
is also a solution to the martingale problem associated to $({\sf L}_t)_{t\in [s,T]}$ on $[s,T]$, with initial distribution $\nu_s$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 (Two-parameter Banach-valued chaining) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Let $X(u)$, $u\in\Delta_T$, take values in a separable Banach space $B$.  Suppose that for some $p_0\ge2$, $0<\theta\le1$, and constants $R_0,R_1$,
\[
 \sup_u\norm{X(u)}_{L^{p_0}(\Omega;B)}\le R_0,
 \qquad
 \norm{X(u)-X(v)}_{L^{p_0}(\Omega;B)}
 \le R_1d_\Delta(u,v)^\theta.
\]
If $p_0>4/\theta$, then $X$ has a separable continuous modification and, for every $2\le p\le p_0$,
\begin{equation}
 \left\|\norm{X}_{C(\Delta_T;B)}\right\|_{L^p(\Omega)}
 \lesssim_{p,p_0,\theta,T}R_0+R_1.
\end{equation}

[Coro 23 (Comparison of the onset amplitudes for $n\geq3$) of arXiv:2608.30578, 'Compactly Supported Solutions near a Nehari Critical Value'] Let $0<\alpha<1$, and let $A_n$ denote the $L^\infty$-amplitude of
the flat positive solution at the threshold $\lambda=\lambda_{c,n}$,
as in the preceding theorem. Then, $A_n<A_\infty$ if and only if
\begin{equation}
	\left(
	1+\frac{1+\alpha}{n(1-\alpha)}
	\right)^2
	\cos^{1+\alpha}
	\left(
	\frac{\pi}{n(1-\alpha)+(1+\alpha)}
	\right)
	<1.

\end{equation}
In particular, $A_n>A_\infty\hbox{ for every integer }n\geq3$. (Proof in the paper; no proof environment follows the statement in the TeX.)

