[Proposition uniform_bound_derivative_and_A of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] For any $\mu_g \underset{g \to +\infty}{\rightarrow}\mu_c$ such that $\mu_c - \mu_g = o(g^{-2})$ and any $n\ge 0$, we have for $g$ large enough
    \begin{align*}
&\forall \mathbf{p}\in (\mathbb{N}^{*})^{k}, \hspace{0.3cm}\big|\alpha_{n,g,\mathbf{p}}(\mathbf{M})\big| \le C_n \bigg( \frac{-M_1}{M_0}\bigg)^{n-|\mathbf{p}|}g^{n+k}A^{k}\varphi(g),\\& \forall\mathbf{p}\in (\mathbb{N}^{*})^{k}, \hspace{0.2cm} \forall j \in \{1,\cdots,k\}, \hspace{0.3cm}\big|\mathcal{A}_{g,n,\mathbf{p},j}(\mathbf{M})\big| \le C^{'}_n \bigg( \frac{-M_1}{M_0}\bigg)^{n+1-|\mathbf{p}|}g^{n+k}A^{k}\varphi(g),
    \end{align*}
where $C_n,C^{'}_n > 0$ only depend on $n$ and $A > 1$ is an absolute constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 22 (Global length--dimension formula) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] The all-lattice directed formal logarithmic solution space is finite-dimensional, and
\begin{equation}

\begin{aligned}
\dim_{\C}\Sol_{\bm{\beta},\bm{w}}^{\mathrm{dir,all}}\bigl(H_{A}(\bm{\beta})\bigr)
&=\length_{S}\left(M_{\bm{\beta},\bm{w}}^{\mathrm{dir,all}}\right)\\
&=\sum_{\Lambda\in\mathfrak{L}_{\bm{\beta},\bm{w}}^{\mathrm{adm}}}\length_{S}\left(M_{\Lambda,\bm{w}}^{\mathrm{dir}}\right).
\end{aligned}
\end{equation}

[Corollary 13 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] Suppose that $Z\colon \bN\to\cX$ is a Markov set. 
  Let $B\in\cX$ and $k\in\N$. Then
  \begin{equation} 
    \sum^k_{i=0}\binom{k}{i}\,\BE \big[\eta_Z(B)^{(i)}
    \lambda_{Z^c}(B)^{k-i}\big]=\lambda(B)^k.
  \end{equation}
  If $B\in\cX_0$, then we have moreover,
  \begin{align} 
    \sum^k_{i=0}(-1)^i\binom{k}{i}\,\BE
    \big[\eta_Z(B)^{(i)}\lambda_{Z}(B)^{k-i}\big]=0.
  \end{align}

