[Theorem thm:ergodicity of upper v.s. invariant functions of arXiv:2411.02030, 'Finite ergodic components for upper probabilities'] Let $(\Omega,\mathcal{F},V,T)$ be an UPPS. Then the following three statements are equivalent:
	\begin{enumerate}
		\item [(i)] $V$ is of finite ergodic components;
		\medskip
		\item [(ii)]there exists a measurable partition $\{A_1,\ldots,A_n\}$ of $\Omega$ with  $V(A_i)=1$, $i=1,2,\ldots,n$ such that for any $T$-invariant function $f$, i.e., $f\circ T=f$, there exists $c_1,\ldots,c_n\in\mathbb{C}$ such that 
		\[f=\sum_{j=1}^nc_j1_{A_j},\text{ }V\text{-a.s.};\]

		\item [(iii)] there exists a measurable partition $\{A_1,\ldots,A_n\}$ of $\Omega$ with  $V(A_i)=1$, $i=1,2,\ldots,n$ such that the eigenspace of the Koopman operator $U_T$ corresponding to eigenvalue $1$ is spanned by $\{1_{A_i}:i=1,2,\ldots,n\}$ and  the eigenvalue $1$ of $U_T$ is of multiplicity $n$.
	\end{enumerate}

[Proposition 3 of arXiv:2605.05864, 'Classification and Metrization of Classes of Smooth measures'] We assume that \(1_K \mu \in \mathcal{T}\) for any \(\mu \in \mathcal{T}\) and compact set \(K\). Then the following holds.
\begin{enumerate}
\item \(\mathcal{T}\subset \mathcal{T}_{loc} \subset \mathcal{T}_{col}\).
\item \((\mathcal{T}_{loc})_{col} = (\mathcal{T}_{col})_{loc}= \mathcal{T}_{col}\).
\end{enumerate}

