[Definition of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] The {\em second counting function} $\ell$ is defined by
\begin{align*}
\ell(\gamma^{(k)})=
\begin{cases}
0, & \gamma^{(k)}=0, \ k\ge1; \\
1, & \gamma^{(1)}=1; \\
1+\sum_{j=1}^{3}\ell(\gamma_j^{(k-1)}), & \gamma^{(k)}=(\gamma_j^{(k-1)})_{j=1}^3,\ k\ge2.
\end{cases}
\end{align*}

[Lemma 14 (Properties of $v_\beta$) of arXiv:2606.24887, '2606.24887'] Let $\beta = (\beta_1, \beta_2) \in [0,\infty)^2$ and let $v_\beta$ be defined as in \eqref{eq:def_v_beta}. 
		Then, for all $\eta \in (0, \infty)$, $w \in \C$ and $\beta=(\beta^1,\beta^2) \in [0,\infty)^2$, we have 
		\begin{align}
			|v-v_{\beta}| & \leq v_\beta|\beta^{1} -1| + |\beta^{2} -1 |, \\ 
			v_\beta & \leq \eta^{-1}.   
		\end{align} 
		Moreover, if $L >0$ and $\delta \in (0,1)$ are fixed, then for all $\eta \in (0,L]$ and $w \in \mathrm{D}_{1-\delta}$, we have 
		\begin{equation}
			v_\beta \asymp_{\delta,L} \frac{\eta + \beta^{2}}{\abs{w}^2 + (\eta + \beta^1)(\eta + \beta^{2})} \leq \frac{1 + \beta^{2}}{\abs{w}^2 + \beta^{1} \beta^{2}}  .  
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

