[Proposition 8 (Kallianpur--Striebel formula) of arXiv:2506.09637, 'Nonlinear Stochastic Filtering with Volterra Gaussian Noises'] Suppose that Conditions~\ref{condition_covariance_rho_var},
\ref{cameron_martin_condition}, \ref{condition_filtration}, and
\ref{vf_condition_section_well_posedness} hold. Then, for every bounded
measurable function \(\phi:\mathbb R^{d_X}\to\mathbb R\) and every
\(t\in[0,T]\),
\[
    \pi_t(\phi)
    =
    \frac{
        \mathbb E^{\mathbb Q}
        \bigl[\phi(X_t)\Lambda_t\mid\mathcal Y\bigr]
    }{
        \mathbb E^{\mathbb Q}
        \bigl[\Lambda_t\mid\mathcal Y\bigr]
    }
    \qquad \mathbb Q\text{-a.s.}
\]

[Definition 16 (Short-range factorization property) of arXiv:2602.14618, 'Finitary coding and Gaussian concentration\\ for random fields'] We say that a coding satisfies the short-range factorization property with constant $\alpha \in (0,1]$ if, for all $k,\ell,i  \in \Z^d$ such that $\max\{\|\ell-i\|,\|k-i\|, \|\ell-k\|\} = \|\ell-i\|$ 
the following holds
 \begin{align*}
&\E\Big[
\1\!\left\{\|k-i\|_\infty\le r_k(X)\right\}
\1\!\left\{\|\ell-k\|_\infty\le r_\ell(X)\right\}\Big] \\
&\leq \E\Big[
\1\!\left\{\|k-i\|_\infty\le r_k(X)\right\}\Big] \E\Big[
\1\!\left\{\alpha \|\ell-k\|_\infty\le r_\ell(X)\right\}\Big].
 \end{align*}

[Lem prop:3.6-CP of arXiv:2412.00708, 'Stochastic PDE approach to fluctuating interfaces'] For some $C>0$, we have
\begin{align} 
-1 < v^\varepsilon(m_1)\le -1+ C \sqrt{\varepsilon}, \quad 1- C \sqrt{\varepsilon} \le v^\varepsilon(m_2)<1.
\end{align}
Moreover, we have
\begin{align} 
\begin{aligned}
& 0\le v^\varepsilon(x)- \hat v^\varepsilon(x) \le C\sqrt{\varepsilon}, \quad x\in [0,h_2].\\
& 0\le \hat v^\varepsilon(x)- v^\varepsilon(x) \le C\sqrt{\varepsilon}, \quad x\in [h_2,1].
\end{aligned}
\end{align}

[Lemma 8 (\cite{BuckdahnPeng2017} Lemma 2.1) of arXiv:2606.06193, 'Peng's Maximum Principle for McKean-Vlasov Stochastic Differential Equations with Common N'] Let $\varphi \in C_b^{2,1}(\mathcal{P}_2(\mathbb{R}^d),\R)$. Then, for any given $X \in L^2(\Omega, \mathbb{R}^d)$ we have the following second-order expansion, for all $Y \in L^2(\Omega, \mathbb{R}^d)$,
        \begin{equation*}
            \begin{aligned}
                \varphi(\cL(Y))- & \varphi(\cL(X)) \\
                = & \E\left[\varphi_{\mu}(\cL(X))( X) [\eta]\right]
                +\frac{1}{2} \E\left[\tilde{\E}\left[\varphi_{\mu\mu}(\cL(X))(\tilde{X}, X)[\tilde{\eta},\eta]\right]\right] \\
                & +\frac{1}{2} \E\left[\varphi_{y\mu}(\cL(X))( X) [\eta , \eta]\right]+R(\cL(Y), \cL(X)),
            \end{aligned}
        \end{equation*}
        where $\eta:=Y-X$. Further, for all $Y \in L^2(\Omega, \mathbb{R}^d)$, the remainder satisfies the estimate
        \begin{equation*}
            \begin{aligned}
                |R(\cL(Y), \cL(X))| & \leq C((\E[|Y-X|^2])^{3 / 2}+\E[|Y-X|^3]) \\
                & \leq C \E[|Y-X|^3],
            \end{aligned}
        \end{equation*}
        and the constant $C \in \mathbb{R}_{+}$ only depends on the Lipschitz constants of $\varphi_{\mu\mu}$ and $\varphi_{y\mu}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 (Finite torus-bundle covers of the three geometries) of arXiv:2608.30027, 'Under Ricci flow, a 3-torus goes flat'] Let \(M\) be a closed connected three-manifold modeled on \(\RR^3\),
\(\Nil\), or \(\Sol\).  Then \(M\) has a finite regular orientable cover
\(M_{\mathrm{fin}}\) which is the total space of a \(\TT^2\)-bundle over
\(S^1\), with monodromy \(H\in\SL(2,\ZZ)\).  The cover may be chosen so
that the following hold:
\begin{enumerate}
\item if \(M\) is modeled on \(\RR^3\), then
      \(M_{\mathrm{fin}}\cong\TT^3\) and \(H=I\);
\item if \(M\) is modeled on \(\Nil\), then \(H\) is nontrivial unipotent;
\item if \(M\) is modeled on \(\Sol\), then \(H\) is hyperbolic.
\end{enumerate}
In particular, the monodromy is elliptic, parabolic, or hyperbolic according
as the original geometry is \(\RR^3\), \(\Nil\), or \(\Sol\).

