[Lemma lem:xi1-refined of arXiv:2609.01311, 'One-Layer Transformer Provably Learns Multiclass\\ One-Nearest Neighbor in Context'] For $\xi_1^t \ge 0$,
\begin{equation*}
\tfrac{d}{\eta}\big(\xi_1^{t+1} - \xi_1^t\big)
\ge \tfrac{K-1}{K}\big[\big(1 - \tfrac{1}{2N}\big)C_d\, e^{-6\xi_1^t}
- 2\, e^{2\xi_1^t - 2\xi_2^t}\big].
\end{equation*}

[Proposition comp_pena of arXiv:2607.29548, 'Generalized reflected BSDEs with irregular obstacles driven by RCLL increasing processes o'] Let be $\{\sigma_{q,i}\}_{i=0,1,\cdots,k_q+1}$ be a finite sequence of arrays stopping times such that $0=\sigma_{q,0} <\sigma_{q,1}<\sigma_{q,2}<\cdots<\sigma_{q,k_q+1}=T$ for $q \in \{1,2\}$. Let $\{(Y^q,M^q)\}_{q=1,2}$ be a solution of the following GBSDE associated with $(B,\xi_T,\mathfrak{f}_q)$:
		\begin{equation}
			\begin{split}
				Y^q_t=\xi_T&+\int_{t}^{T} \mathfrak{f}_q(s,Y^q_{s-})dB_s
				-\int_{t}^{T} dM^q_s +\sum_{t \leq \sigma_{q,i} < T} \left(Y^q_{\sigma_{q,i}+}-\xi_{\sigma_{q,i}}\right)^{-},\qquad t \in [0,T].
			\end{split}
		\end{equation}
		Suppose that
		$$
		\xi^1_T\geq \xi^2_T,
		\quad \mathbb{P}\text{-a.s.},
		$$
		and that the following conditions hold:
		\begin{itemize}
			\item[\textnormal{(i)}] $\mathfrak{f}_1(\omega,t,y)\geq \mathfrak{f}_2(\omega,t,y)$ for every $(\omega,t,y)\in\Omega\times[0,T]\times\mathbb{R}$;
			\item[\textnormal{(ii)}] for every $(\omega,t)\in\Omega\times[0,T]$, the mapping $y\mapsto \mathfrak{f}_1(\omega,t,y)$ is nonincreasing;
			\item[\textnormal{(iii)}] $\bigcup_i \llbracket \sigma_{2,i}  \rrbracket \subset \bigcup_i \llbracket \sigma_{1,i}  \rrbracket$
		\end{itemize}
		Then
		$$
		Y^1_t\geq Y^2_t,
		\qquad \forall t\in[0,T],
		\quad \mathbb{P}\text{-a.s.}
		$$

