\begin{equation}
Z(\mathcal{K}f)\leq Z(f)  
\end{equation}
for every continuous function $f$ on $[0,\tfrac{1}{2}]$.

[Definition 27 of arXiv:2608.29086, '2608.29086'] [$Part(m)$]
Given $P, m \in Obj(Mol)$. $P$ is called a \textit{partition} of $m$ if
\begin{enumerate}
\item $P \rightarrow_M m$, and
\item $|P|=|m|$. 
\end{enumerate} 
Given $m \in Obj(Mol)$. $Part(m)$ denotes the collection of all partitions of $m$, i.e,
\begin{equation*} 
Part(m):=\{P \in Obj(Mol)\ |\  P \text{ is a partition of } m\} \quad \subset Obj(Mol).
\end{equation*}

