[Corollary 7 (Conditional form) of arXiv:2608.20337, 'Information on trajectories:\\ martingales and random times'] \begin{equation}
  \log Z_T(\alpha)
  = \max_{\widetilde Q \ll P}
    \left\{
      \sum_{t=1}^T \E_{\widetilde Q}\!\left[
        \alpha_t \log R_t - \KL(\widetilde Q_t \| P_t)
      \right]
    \right\}
\end{equation}
where $\widetilde Q_t = \widetilde Q_t(\cdot \mid X_{1:t-1})$ and $P_t = P_t(\cdot \mid X_{1:t-1})$.
The maximizer $R^*_\alpha$ has one-step conditional densities
\begin{equation}
  r^*_{\alpha,t}(x_t \mid x_{1:t-1})
  \propto p_t(x_t \mid x_{1:t-1}) \,
          R_t(x_t; x_{1:t-1})^{\alpha_t}\,
          h_t(x_{1:t}),
  \qquad
  h_t(x_{1:t}) := \E_P\!\Bigl[{\textstyle\prod_{s > t}} R_s^{\alpha_s}
                    \,\Big|\, \cF_t\Bigr],
\end{equation}
where $h_t$ is the forward factor. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor cortau of arXiv:2605.01878, '\Large Random trade timing and power-law tails in realized prices'] Let $X$ be a real-valued random variable whose Laplace transform $\varphi_X$ satisfy the conditions (lemxpluda of the paper)--(lemxpludc of the paper) of Lemma (lemxplus of the paper). Then there exist finite constants $C_1$ and $C_2$, depending only on
$\alpha$, $\ell$, and $\delta$, such that
\begin{align}
A_\ell C_1
&\le \liminf_{x\to\infty} x^{-\ell+1} e^{\alpha x} \mathbb{P}(X>x) \notag\\
&\le \limsup_{x\to\infty} x^{-\ell+1} e^{\alpha x} \mathbb{P}(X>x)
\le A_\ell C_2. 
\end{align}
If, in addition, $\ell=1$ and $-\alpha$ is the unique singularity of $\varphi_X$ on the
axis $\mathrm{Re} (s)=-\alpha$, then
\begin{align}
\lim_{x\to\infty} e^{\alpha x}\mathbb{P}(X>x) = A_1/\alpha. 
\end{align}

