[Lem 30 of arXiv:2608.20552, 'One-point fluctuations for exponential last passage percolation under upper-tail condition'] We have
\beqq
	\lim_{L\to\infty}
	\frac{1}{\tP}
	\sum_{n=1}^\infty
	\frac{1}{(n!)^2} \QQ_{2,L}^{(1,n)}
	=\prob(\TW_2>\rr).
\eeqq

[Theorem 11 of arXiv:2606.25494, 'A functional central limit theorem for kernel gradient flow and infinitesimal gradient boo'] In addition to \Cref{ass:loss}, assume that \begin{equation}
    \sup_{x\in\mathcal{X}} \mathbb{E}[|\partial_1\ell(0,Y)|^2 \,\mid\, X=x]<\infty.
\end{equation}
Then:
\begin{itemize}
\item[(i)] The vector fields converge almost surely:
\[
(\mathcal{T}_n(F))_{F\in\mathcal{H}} \stackrel{a.s.}{\longrightarrow} (\mathcal{T}(F))_{F\in\mathcal{H}}
\qquad \text{in  $C_b^0(\mathcal{H},\mathcal{H})$ as $n\to\infty$}.
\]
\item[(ii)] As a consequence, if $F^n_0 \stackrel{a.s.}{\longrightarrow} F_0$, then the infinitesimal gradient boosting processes converge almost surely:
\[
(F_t^n)_{t\geq 0} \stackrel{a.s.}{\longrightarrow} (F_t)_{t\geq 0}
\qquad \text{in $C^1([0,+\infty),\mathcal{H})$ as $n\to\infty$},
\]
where the limit $F=(F_t)_{t\geq 0}$ is the unique solution of the ODE 
\begin{equation}
\frac{\mathrm{d}}{\mathrm{d}t} F_t = \mathcal{T}(F_t),\qquad t \ge 0,
\end{equation}
with initial condition $F_0$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 32 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] For a local section $\mathfrak{v}$ of $A_U$ we use the notation from \Cref{setup:PF_PB}. 
Then, for every $x \in U$ for which the expressions are defined, 
\begin{align}
\left. \frac{\partial}{\partial t} \right|_{t=s} (\mathfrak{F}^{t,s}_\mathfrak{u})^*\mathfrak{v}(x) = \LB[\mathfrak{u}_s,\mathfrak{v}]_A(x). 
\end{align}

[Defn 10 ({\cite[Definition 2.2 and 2.9) of arXiv:2609.02561, 'NON-NEF LOCI IN MIXED CHARACTERISTIC'] {Keeler},\cite[Definition 3.1]{Ushiro}}]
Let $L$ be a line bundle on $X$.
We say that $L$ is:
\begin{enumerate}
\item $f$-ample
if there exists an affine open cover $\{ U_{\lambda} \}$ of $S$ such that $L|_{f^{-1}(U_{\lambda})}$ is ample for every $\lambda$;
\item $f$-nef
if $(L.C)\geq 0$ for every irreducible curve $C\subset X$ that is closed in $X$ and satisfies that $f(C)$ is a closed point of $S$;
\item $f$-semiample if $f^{*}f_{*}L^{\otimes m}\rightarrow L^{m}$ is surjective for some $m\in\Z_{>0}$;
\item $f$-$\Q$-effective if $f_{*}L^{\otimes m}\neq 0$ for some $m\in\Z_{>0}$;
\item $f$-big if $f_{*}(L^{\otimes m}\otimes A^{-1})\neq 0$
for some $m\in\Z_{>0}$ and some $f$-ample line bundle $A$.
\end{enumerate}
These notions extend to $\Q$-Cartier $\Q$-divisors $D$ by requiring that some positive multiple $L:=\sO_X(mD)$ satisfies the corresponding properties.

[Proposition prop:recursive_contraction of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] Fix an initial density $\rho_0 > 0$. There exists a constant $C_{\textnormal{\tiny (C:recursive_contraction of the paper)}} > 0$ such that if $L_0 > C_{\textnormal{\tiny (C:recursive_contraction of the paper)}}$, $p_0 \le L_0^{-5d}$,  and for all $k \ge 0$ the decoupling error satisfies
  \begin{equation}
    C_{\textnormal{\tiny (C:decoupling of the paper)}} \ell_k^{2d+2} L_{k+1}^{5d} \varepsilon_k \le \frac{1}{2},
  \end{equation}
  then $p_{k} \le L_{k}^{-5d}$ for all $k \ge 0$.

