[Proposition comu-prop-1 of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Let $\phi$ be a $C^{1}$-diffeomorphism of $\mathbb{R}^{d}$.  Assume that there exist $\beta \in(0,1)$ and $p\geq 1$ such that 
 \begin{trivlist}
\item[(i)] $v \in C_{\mathrm{loc }}^{\beta}(\mathbb{R}^{d}, \mathbb{R}^{d})$,
\item[(ii)]
$\operatorname{div} v \in L_{\mathrm{loc}}^{1}(\mathbb{R}^{d})$,
\item[(iii)]
$g \in L_{\mathrm{loc}}^{\infty}(\mathbb{R}^{d})$ and 
\item[(iv)]
$J \phi^{-1} \in W_{\mathrm{loc}}^{1-\beta,p}\left(\mathbb{R}^{d}\right)$.
  \end{trivlist}
 Then for  all $r>0$ and any $R>0$, 
 there exist  constants $C_R>0$ and $C_{R,p}>0$ such that if 
 $\rho \in C_{r}^{\infty}$  such that $\operatorname{supp}\left(\rho \circ \phi^{-1}\right) \subseteq B_R$, then 
\begin{align}
&\quad\left|\int_{\mathbb R^d} \mathcal{R}_{\ensuremath{\varepsilon}}[ v,g](\phi(x)) \rho(x) d x\right|\\
&\leq C_{R}\Vert g\Vert_{L_{R+1}^{\infty}}\Vert\rho\Vert_{L_{r}^{\infty}}
\Vert\operatorname{div} v\Vert_{L_{R+1}^{1}}\Vert J \phi^{-1}\Vert_{L_{R}^{\infty}}\\
&\quad+C_{R,p}\Vert g\Vert_{L_{R+1}^{\infty}}[v]_{C_{R+1}^{\beta}}\left(\Vert D \rho\Vert_{L_{r}^{p}}\left\Vert D \phi^{-1}\right\Vert_{L_{R}^{\infty}}\left\Vert J \phi^{-1}\right\Vert_{L_{R}^{\infty}}+\left[J \phi^{-1}\right]_{W_{R}^{1-\beta, p}}\Vert\rho\Vert_{L_{r}^{\infty}}\right).
\end{align}
Moreover, 
\begin{equation}
\lim _{\ensuremath{\varepsilon} \to  0} \int_{\mathbb R^d} \mathcal{R}_{\ensuremath{\varepsilon}}[v, g](\phi(x)) \rho(x) d x=0.
\end{equation}

