[Lemma lem:logLargeScaleCancellation of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Let $K\ge1$, and recall the $L^\infty L^2(\mu)$ and integral-operator norms of (rem:Ustattail of the paper).
\begin{enumerate}[(i)]
\item\emph{(Riesz case $0<\mathsf{s}<\mathsf{d}/2$.)}  The centered kernels of the splitting (equation eq:FourierLowHighDef of the paper) satisfy, uniformly in $0<\eta\le\eta_0$,
\begin{align}
\|\tilde{\mathsf{g}}_{\eta,>K}\|_{L^2(\mu^{\otimes2})}^2 &\le C_\mu \int_{|\xi|>K}\widehat{{\mathsf{g}}}(\xi)^2\,\mathop{}\!\mathrm d\xi \le C_\mu K^{2\mathsf{s}-\mathsf{d}},\\
\|\tilde{\mathsf{g}}_{\eta,>K}\|_{L^\infty L^2(\mu)}^2 &\le C_\mu \int_{|\xi|>K}\widehat{{\mathsf{g}}}(\xi)^2\,\mathop{}\!\mathrm d\xi \le C_\mu K^{2\mathsf{s}-\mathsf{d}},\\
\|\mathcal{T}_{\tilde{\mathsf{g}}_{\eta,>K}}\|_{\mathrm{op}} &\le C_\mu \sup_{|\xi|>K}\widehat{{\mathsf{g}}}(\xi) \le C_\mu K^{-(\mathsf{d}-\mathsf{s})},
\end{align}
together with the low-mode diagonal bound
\begin{align}
\sup_x \tilde{{\mathsf{g}}}_{\eta,\le K}(x,x) \le 4\int_{|\xi|\le K}\widehat{{\mathsf{g}}}(\xi)\,\mathop{}\!\mathrm d\xi \le C_1 K^\mathsf{s},
\end{align}
for a constant $C_1=C_1(\mathsf{d},\mathsf{s})$.
\item\emph{(Logarithmic case $\mathsf{s}=0$.)}  Assume (equation eq:logEnergyAssumption of the paper).  There is a constant $C_{\mu,K}<\infty$ such that, for every $N\ge1$, every $T\ge2$, every $0<\eta\le\eta_0$, and every configuration $X_N$,
\begin{align}
\frac1N\sum_{i=1}^N h_{\mu,T}(x_i)
-\frac1{2N}\sum_{1\le i\ne j\le N}\tilde{\mathsf{g}}_{\eta,T,\le K}(x_i,x_j)
\le C_{\mu,K}.
\end{align}
Moreover,
\begin{align}
\|\tilde{\mathsf{g}}_{\eta,T,>K}\|_{L^2(\mu^{\otimes2})}^2+\|\tilde{\mathsf{g}}_{\eta,T,>K}\|_{L^\infty L^2(\mu)}^2&\le C_\mu K^{-\mathsf{d}},
\qquad
\|\mathcal{T}_{\tilde{\mathsf{g}}_{\eta,T,>K}}\|_{\mathrm{op}}\le C_\mu K^{-\mathsf{d}},\nonumber\\
\|\tilde{\mathsf{g}}_{\eta,T,>K}\|_{L^\infty}&\le C\pa[\big]{1+\log(1/\eta)}.
\end{align}
\end{enumerate}

[Definition def:mapping_into_the_good_direction of arXiv:2505.07145, 'Nonamenable Poisson zoo'] Let $A \subset \subset V(G)$ connected, $x \in \partial_{\mathrm{ext}} A$ and $y \in \mathcal{N}_1(x)$ and $z \in \mathcal{N}_2(x)$ fixed in an arbitrary way. Then
\begin{equation}

	\Psi_1(x,A) := 
	\begin{cases}
		x, & \text{if} \quad \mathcal{N}_1(x) \cap \overline{A} = \emptyset, \\
		z, & \text{otherwise}, 
	\end{cases}
	\quad \text{and} \quad
	\Psi_2(x,A) := 
	\begin{cases}
		x, & \text{if} \quad \mathcal{N}_2(x) \cap \overline{A} = \emptyset, \\
		y, & \text{otherwise}.
	\end{cases}
\end{equation}
These can be also extended to any subset $B \subseteq \partial_{\mathrm{ext}} A$ of the exterior boundary as 
\begin{equation}

	\Psi_1(B, A) := \big\{ \Psi_1(x,A) : x \in B \big\}
	\quad \text{and} \quad
	\Psi_2(B, A) := \big\{ \Psi_2(x,A) : x \in B \big\}.
\end{equation}

[Theorem thm:R1a of arXiv:2509.17319, 'Non-directed polymers in random environments with range penalties: the high-dimensional ca'] Let $\alpha\in(2\vee\frac{d}{2},d)$ (in particular $d\geq 3$) and $(\zeta,\gamma)\in R_1$ (see Figure (diagram2 of the paper)). Then $(S_n)_{0\leq n \leq N}$ has end-to-end fluctuations of order $N^{\xi}$ under ${\ensuremath{\mathbf P}} _N$ with $\xi=\frac12$. Without loss of generality, we assume that ${\rm Var_\mathbb{P}}(\omega)=1$. Take $a_N=N^{1/4}$ for $d=3$, $a_N=(\log N)^{1/2}$ for $d=4$, and $a_N=1$ for $d\geq 5$. Then as $N\to\infty$,
\begin{equation}
\frac{1}{a_N\beta_N}\left({\ensuremath{\mathbf Z}} _N-{\ensuremath{\mathbf E}} \left[e^{(\frac{1}{2}\beta_N^2-h_N)|{\ensuremath{\mathcal R}} _N|}\right]\right)\overset{(d)}{\longrightarrow}\begin{cases}
{\ensuremath{\mathcal N}} (0,\sigma_d^2),\quad&\text{for}~d=3,4,\\
{\ensuremath{\mathcal X}} ,\quad&\text{for}~d\geq5,
\end{cases}
\end{equation}
where ${\ensuremath{\mathcal N}} (0,\sigma_d^2)$ is a centered Gaussian distribution with an explicit variance $\sigma_d^2$ and
\begin{equation}
{\ensuremath{\mathcal X}} :=\sum\limits_{x\in{\ensuremath{\mathbbm Z}} ^d}\omega_x{\ensuremath{\mathbf P}} (x\in{\ensuremath{\mathcal R}} _\infty)={\ensuremath{\mathbf E}} \left[\sum\limits_{x\in{\ensuremath{\mathcal R}} _\infty}\omega_x\right],
\end{equation}
which is a well-defined random variable. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem-inequality for H of arXiv:2412.08932, 'Gaussian heat kernel asymptotics for conditioned random walks'] For any $x\geqslant 0$ and $\varepsilon\geqslant0$, we have 
\begin{align} 
H(x(1+\varepsilon)) \leqslant H(x) (1+\varepsilon)
\end{align}
and 
\begin{align} 
H(x(1-\varepsilon)) \geqslant H(x) (1-\varepsilon).
\end{align}

[Lemma 18 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exists $c>0$ such that for any $a>0$, $v\neq w\in \widetilde{\mathbb{Z}}^d$ with $|v-w|\le 1$, and $D\subset \widetilde{\mathbb{Z}}^d$ with $\mathrm{dist}(D,w)\ge |v-w|$,
	\begin{equation}
	   	\mathbb{P}^{D}\big( \{ v\xleftrightarrow{\ge 0} w \}^c \mid \widetilde{\phi}_v=a \big) \le  e^{-ca^2|v-w|^{-1}}. 
	\end{equation}

