\begin{equation}

\begin{split}
\{ \xi_s^\varepsilon \le t\} =  \cup_{i \ge 1} \Big (\{ \tau_i^\varepsilon \le t\} \cap \{\tau_i^\varepsilon \ge s\} \Big) \ . 
\end{split}
\end{equation}
But $\{ \tau_i^\varepsilon \ge s\} = \cap_{k \ge 1} \{\tau_i^\varepsilon \le s-1/k\}^c \in \mathcal F^\varepsilon_s \subset \mathcal F_t^\varepsilon$ since $(\mathcal F_t^\varepsilon)_{t \ge 0}$ is increasing and $\tau_i^\varepsilon$ is a stopping time. Hence $\{ \xi_s^ \varepsilon \le t\} \in \mathcal","release_manifest_digest":"sha256:7c326d686c7ab757e4846cffcea390902165d4dd5410bd58d4e0f47a26fde31f","revision_digest":"sha256:f020dc6056aabbff5000eb29c8f10d8b03636f0d6c09d24bb9e197065bf51e62","source_id":"arxiv:2512.19517","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

