[Corollary 19 (First-row ancestry bound) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] For every \(\lambda\vdash n\),
\begin{equation}
 m_{\lambda,n,r}=0
 \quad\text{if}\quad
 r>n-\lambda_1
 \quad\text{or}\quad
 2r>n.

\end{equation}
Consequently,
\begin{equation}
 a_n(\lambda)\leq
 \min\!\left\{n-\lambda_1,\left\lfloor\frac n2\right\rfloor\right\}.

\end{equation}

[Proposition of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] Let $B$ be a $\mathbb{R}^{d}$-valued Gaussian process with stationary increments. Then,
		\begin{itemize}
			\item $B$ is ergodic if and only if $B^{(i)}$ is ergodic, $1\leq i \leq d$,
			\item $B$ is weakly-mixing if and only if $B^{(i)}$ is weakly-mixing, $1\leq i \leq d$,
			\item  $B$ is mixing if and only if $B^{(i)}$ is mixing, $1\leq i \leq d$,
		\end{itemize}

[Lemma 31 (Multilinearity, coordinates, and covariance) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] For every $q\ge1$, the map
\[
  (h_1,\ldots,h_q)
  \longmapsto \wick{W(h_1)\cdots W(h_q)}
\]
is symmetric and $q$-linear from $\cH^q$ to $L^2(\Omega)$.  For $q=0$,
the map is the constant $1$.  In formulas involving $q=0$, we use
$\mathfrak S(\varnothing)=\{\Id\}$ and the empty product equals $1$.  Let
$(e_a)_{a=1}^N$ be an orthonormal basis of a finite-dimensional subspace of
$\cH$, put $g_a=W(e_a)$, and let
$\mathbf i=(i_1,\ldots,i_q)\in\{1,\ldots,N\}^q$.  Then
\begin{equation}

  \wick{g_{i_1}\cdots g_{i_q}}
  =\prod_{a=1}^N H_{\alpha_a(\mathbf i)}(g_a),
  \qquad
  \alpha_a(\mathbf i):=\#\{\nu:i_\nu=a\}.
\end{equation}
For $h_1,\ldots,h_q,k_1,\ldots,k_\ell\in\cH$,
\begin{equation}

  \E\left[
    \wick{W(h_1)\cdots W(h_q)}
    \wick{W(k_1)\cdots W(k_\ell)}
  \right]
  =\mathbf 1_{q=\ell}
  \sum_{\sigma\in\mathfrak S([q])}
  \prod_{\nu=1}^q\ip{h_\nu}{k_{\sigma(\nu)}}_{\cH}.
\end{equation}

[Prop 18 of arXiv:2606.21433, 'Central limit theorem for\\ the averaged Adam optimizer'] Under the assumptions of \cref{thm-1} there exists $R,c_1\in(0,\infty)$ and a norm $\|\cdot\|$ on $\R^d$ induced by a scalar product $\llangle\cdot,\cdot\rrangle$ such that for all $x\in \overline {\IB(\theta^*,R)}$ one has
\bas{
\llangle f(x)-f(\theta^*),x-\theta^*\rrangle \le -c_1\|x-\theta^*\|^2.
}
The matrices $(\bar\Pi[m,n])_{1\le m\le n}$ (as defined in~\cref{def:bar_Pi}) converge to $-H^{-1}$ when letting
 $m,n\to\infty$ with $t_n-t_m\to\infty$. Furthermore,  the matrices $(\bar\Pi[m,n])_{1\le m\le n}$  are uniformly bounded.

