body:
[Corollary 6 of arXiv:2604.10266, 'A singular SDE driven by additive fractional Brownian motion with Hurst parameter $H<\frac'] There exists a nonnegative process $L^H=\{L_t^H, t\geq 0\}$ such that
\begin{equation}
X_t=X_0+a\int_0^t\frac{s^{2H-1}}{X_s}dsds-b\int_0^tX_sds+\si B_t^H+L_t^H, \ \forall t\geq 0.
\end{equation}

[Dfn 176 (approximate drift processes) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Define
$\barvD$ to be the process which starts from 
$\barvD(q_0)=\vY(q_0)$, is linear on each interval $q_d \le s \le q_{d+1}$, and has increments given by
	\beq
	\Delta\bar{D}^\sigma(q_d)
	\equiv \begin{cases}
	\displaystyle
	\Delta\bar{D}^\sigma\Big(q_d,B(q_d,a(q_d))\Big)
	\equiv
	\sum_{a\in B(q_d,a(q_d))}
	\frac{\Delta X^{\trunc,\sigma}(q_d,a)}
		{|B(q_d,a(q_d))|} 
	& \textup{for $\sigma\in\{\RomI,\RomII,\RomIII\}$,}\\
	\displaystyle
	\Delta\bar{D}^\sigma\Big(q_d,B^\Ising(q_d,i(q_d))\Big)
	\equiv \sum_{i\in B^\Ising(q_d,i(q_d))}
	\frac{\Delta X^{\trunc,\Ising}(q_d,i)}
		{|B^\Ising(q_d,i(q_d))|} 
	& \textup{for $\sigma=\Ising$.}\\
		\end{cases}
	\eeq
Similarly, we define $\barvD^\frozen$ to be the process which starts from 
$\barvD^\frozen(q_0)=\vY^\frozen(q_0)$, is linear on each interval $q_d \le s \le q_{d+1}$, and has increments given by
	\beq
	\Delta\bar{D}^{\frozen,\sigma}(q_d)
	\equiv \begin{cases}
	\displaystyle
	\sum_{a\in B^\frozen(q_d,a^\frozen(q_d))}
	\frac{\Delta X^{\frozen,\sigma}(q_d,a)}
		{|B^\frozen(q_d,a^\frozen(q_d))|}
	& \textup{for $\sigma\in\{\RomI,\RomII,\RomIII\}$,}\\
	\displaystyle
	\sum_{i\in B^{\Isplus}(q_d,i^\frozen(q_d))}
	\frac{\Delta X^{\Isplus}(q_d,i)}
		{|B^\Isplus(q_d,i^\frozen(q_d))|} 
	& \textup{for $\sigma=\Ising$.}\\
		\end{cases}
	\eeq
Write $B^\frozen=B^\frozen(q_d,a^\frozen(q_d))$, and note that 
if $B^\frozen\cap[M]=\emptyset$ then $
\Delta\bar{D}^{\frozen,\sigma}(q_d)=0$ for all $\sigma\in\{\RomI,\RomII,\RomIII\}$. Otherwise,
if $B^\frozen\cap[M]=B\ne\emptyset$, then we have
	\beq
	\Delta\bar{D}^{\frozen,\sigma}(q_d,B^\frozen)
	=
	\frac{|B|}{|B^\frozen|}
	\Delta\bar{D}^\sigma(q_d,B)
	\eeq
for all $\sigma\in\{\RomI,\RomII,\RomIII\}$. A similar relation holds for $\sigma=\Ising$.

[Prop 37 (Poles of $\phi^{z_0}$ on $(\m,\M)$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] On $[\m,\M]$, the equation $(E) : \gamma(x,Y^-(x),Z^+(x)) = 0$ has at most one solution, denoted by $x^*$. If this equation has no solution, we adopt the convention $x^* = +\infty$. Then, on $(\m,\M)$, the extended function $\phi^{z_0}$ has a pole if and only if $(E)$ has a solution, and the pole is located at $x^*$ whenever it exists. In that case, $(x^*,\, Y^-(x^*),\, Z^+(x^*))$ solves the system
\begin{equation} 
\begin{cases}   \gamma(x,y,z) = 0 \\
\gamma_+(x,y) = 0\\
\gamma_-(x,z) = 0
\end{cases}
\end{equation}
and $$res_{x=x^*}\phi^{z_0}(x) = -\frac{e^{x^*a_0 + Y^-(x^*)b_0\fc_{b_0> 0} +  Z^+(x^*)b_0\fc_{b_0<0}}}{\frac{d}{dx}\gamma(x,Y^-(x), Z^+(x))\big|_{x=x^*}}.$$ Furthermore, if $x^* > 0$ (resp. $x^* < 0$), then $x^*$ is the unique pole of $\phi^{z_0}$ in the strip $\{\m - \e <\Re(x) <x^* + \e \}$ (resp. $\{x^* - \e <\Re(x) <\M + \e \}$) for sufficiently small $\e > 0.$

[Lemma 5 of arXiv:2608.30859, 'Conservation Laws with Discontinuous Flux:\\ A First Application to Traffic Flow'] Assume that $f'(u_{\max})\neq g'(u_{\max})$. Then the tangent point $u^*$ defined in \eqref{eq:ustar} exists if and only if $u^-<u^-_{\mathrm{lim}}$, where $u^-_{\mathrm{lim}}$ is defined by
\begin{equation}
g'(u_{\max})
=
\frac{f(u^-_{\mathrm{lim}})-g(u_{\max})}{u^-_{\mathrm{lim}}-u_{\max}}
=
\frac{f(u^-_{\mathrm{lim}})}{u^-_{\mathrm{lim}}-u_{\max}}.
\end{equation}

Similarly, assume that $f'(0)\neq g'(0)$. Then the tangent point $v^*$ defined in \eqref{eq:vstar} exists if and only if $u^+>u^+_{\mathrm{lim}}$, where $u^+_{\mathrm{lim}}$ is defined by
\begin{equation}
g'(0)
=
\frac{f(u^+_{\mathrm{lim}})-g(0)}{u^+_{\mathrm{lim}}}
=
\frac{f(u^+_{\mathrm{lim}})}{u^+_{\mathrm{lim}}}.
\end{equation}
If, however, $f'(0)=g'(0)$ and $f'(u_{\max})=g'(u_{\max})$, then
$u^+_{\mathrm{lim}}=0$ and $u^-_{\mathrm{lim}}=u_{\max}$.

[Lemma lem:alive-tree-supercritical-support-witness of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume the minimal Kahane--Peyri\`ere regime. Then \(\mathbb{P}(W>0)>1/2\). Hence
\begin{equation*}
\mathcal T^{+}:=\{v\in\mathcal T:Q_v>0\}
\end{equation*}
is a supercritical Galton--Watson tree with offspring law \(\operatorname{Binomial}(2,\mathbb{P}(W>0))\). Moreover, with
\begin{equation*}
A_n:=\#\{v\in\{0,1\}^{n}:Q_v>0\},
\end{equation*}
one has \(A_n\to\infty\) almost surely on \(\{\mu_\circ(\mathbb S^1)>0\}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

