[Thm Semicircular system asymptotics of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For each $n$, let $(M_1,\dots,M_k)$ be a jointly Gaussian family of GOE random matrices such that
    \begin{equation}
        \begin{split}
            \mathbb{E}\left[(M_i)_{\ell_1,\ell_2} (M_j)_{\ell_1',\ell_2'}\right]= \left(\delta_{(\ell_1,\ell_2),(\ell_1',\ell_2')}+\delta_{(\ell_1,\ell_2),(\ell_2',\ell_1')}\right) \varphi_{i,j}.
        \end{split}
    \end{equation}
    Then,
    \begin{equation}
        \begin{split}
            \frac{1}{n^{1+\ell/2}}\mathbb{E}\left[\mathrm{Tr}(M_{i_1}\dots M_{i_{\ell}})\right] = \sum_{\pi \in NC_2[\alpha]} \prod_{(j,j') \in \pi} \varphi_{i_j,i_{j'}}+O(n^{-1}),
        \end{split}
    \end{equation}
    as $n \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition discover_balls of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] For any $r \ge 0$ and any $\varepsilon > 0$, there exists $k > 0$ such that, for $n$ large enough, 
    \begin{align*}
        \mathbb{P}(\sigma_n(k) \ge r)\ge 1-\varepsilon.
    \end{align*}

