[Lemma lem:solution_PDE of arXiv:2607.13748, 'Load Balancing with Individually Heterogeneous Servers'] For $m_1, m_2, \beta > 0$ with $m_1\neq m_2$ define the linear operator $\mathcal{L}$ acting on functions $f:\mathbb{R}^2 \to \mathbb{R}$ as 
\begin{equation}
    \mathcal{L }f(\mathbf{y}) = \left(-\frac{\beta}{n^{1/2}} -m_{1}y_1 + m_{2}y_2\right)f_1(\mathbf{y}) -m_{2}y_2f_2(\mathbf{y}),

\end{equation}
where $f_i\equiv\partial f /\partial y_i$ for each $i\in [2]$.
Furthermore, define $\Omega=(-\infty,0]\times [0,\infty)$. Then, for each fixed $\kappa>\beta/m_{2}$ there exists a function $f^*(\mathbf{y})$ that solves the PDE 
\begin{align}
    \mathcal{L} f^*(\mathbf{y}) &= -(y_2-\kappa/n^{1/2})_+, \mbox{ for all } \mathbf{y}\in \Omega,\\
    f_1^*(0,y_2) &= f_2^*(0,y_2)=\frac{n^{1/2}}{\beta}\left(y_2-\frac{\kappa}{n^{1/2}}\right)_+, \mbox{ for all }y_2\geq 0,
\end{align}

with absolutely continuous first order derivatives $f_1^*(\cdot, y_2)$ and $f_2^*(y_1, \cdot)$. Moreover, we have
\begin{align}
f_1^*(\mathbf{y})\geq 0, f_{12}^*(\mathbf{y})\geq 0, f_{11}^*(\mathbf{y})\geq 0, f_{22}^*(\mathbf{y})\geq 0, \ \ \ \ \ \mathbf{y}\in \Omega, \\
f_{11}(\mathbf{y})=f_{22}(\mathbf{y})=0, \ \  y_2 \in [0,\kappa/n^{1/2}],\\
f_{11}^*(\mathbf{y})\leq C_5(\kappa)n^{1/2}, f_{22}^*(\mathbf{y})\leq C_6(\kappa)n^{1/2}, \ \ \ \ \ \mathbf{y}\in \Omega,
\end{align}
where $f_{ij}^*\equiv \partial^2 f^*/ \partial y_i \partial y_j $, for $i,j\in [2]$, $C_5(\kappa)= \frac{1}{\beta}\frac{m_{2}+m_{1}}{m_{2}} \frac{\kappa}{\kappa-\beta/m_{2}}$ and $$C_6(\kappa)=\frac{1}{m_{2} \kappa}+ \frac{1}{\beta}\brac{\frac{m_1\vee m_{2}}{m_{1}-m_{2}}}^2\frac{\kappa}{\kappa-\beta/m_{2}}+ \frac{1}{\beta}\frac{(m_{1}\vee m_{2})^2}{(m_{1}-m_{2})^2}.$$

