[Lem spectral_NStable of arXiv:2606.29829, ''] {[Forsstrom_arXiv]}
	A sequence $\{\mathfrak{f}_n\}_n$ of Boolean functions, $\mathfrak{f}_n:\Omega_n\rightarrow\{0, 1\}$, is noise stable with respect to $\{(X_n(t),\Omega_n,\pi_n)\}_n$ if and only if for all $\delta>0$ there is a positive integer $k$  such that
	\[\sup_n\sum_{j:\;\theta_{n,j}\geq k\theta_{n,1}}|\langle \mathfrak{f}_n,\psi_{n,j}\rangle|^2<\delta.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop.phasetransitionextended of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] The following hold true:
\begin{itemize}
    \item In dimension $d = 2$, there exists an inverse temperature $\beta_{\mathrm{KT}}^{\mathrm{XY/Vil}} < \infty$ such that, for any $\beta_1 , \beta_2 \geq \beta_{\mathrm{KT}}^{\mathrm{XY/Vil}}$,
    \begin{equation*}
        \left\langle \cos(\theta_0 - \theta_x) \right\rangle_{\beta_1 , \beta_2}^{\mathrm{XY/Vil}} ~\mbox{decays polynomially fast as } |x| \to \infty. 
    \end{equation*}
    \item In dimension $d \geq 3$, there exists an inverse temperature $\beta_{ c}^{\mathrm{XY/Vil}}(d) < \infty$ such that, for any $\beta_1 , \beta_2 \geq \beta_{c}^{\mathrm{XY/Vil}}$,
    \begin{equation*}
        \left\langle \cos(\theta_0 - \theta_x) \right\rangle_{\beta_1 , \beta_2}^{\mathrm{XY/Vil}} ~\mbox{remains bounded away from } 0 \mbox{ as } |x| \to \infty.
    \end{equation*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

