body:
[Lemma 12 of arXiv:2608.26259, 'Cutoff with an $O(1)$ window for Potts Glauber Dynamics\\on lattice at High Temperature'] For every \(\ell\ge1\),
\begin{equation}
    \frac{p_{\mathrm{stop}}}{2}(1-p_{\mathrm{stop}})^{\ell-1}
    \le
    w_\ell
    \le
    \frac{3p_{\mathrm{stop}}}{2}(1-p_{\mathrm{stop}})^{\ell-1}.
\end{equation}
Moreover,
\begin{equation}
    Z_p
    =
    1+\frac{\alpha}{p_{\mathrm{stop}}}+O_{d,q}(\alpha^2)=1+2\alpha+O_{d,q}(\alpha^2).
\end{equation}
In particular, when $\alpha$ is small enough, \(1<Z_p\le2\).

[Proposition 1 of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] Suppose that $\E[U]=1$ and $\Var(U)<\infty$. Then, for every $t>0$,
\begin{equation*}
 \sup_{\substack{h\in C^2([0,\infty))\\ \lVert h''\rVert_\infty\leq1}}
 \left|\E[h(tU)]-h(t)\right|
 =\frac{t^2}{2}\Var(U).
\end{equation*}
Here $C^2([0,\infty))$ denotes the space of functions on
$[0,\infty)$ with two continuous derivatives, and
$\lVert h''\rVert_\infty=\sup_{x\geq0}|h''(x)|$ is the supremum norm of the
second derivative.

[Thm WeiLvWang of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] {[WeiLvWang]}
				Suppose that $f\in L^{\infty}([0,T];C_b(\mathbb{R}^d))$ and $\tilde{f}\in L^{\infty}([0,T];C_b(\mathbb{R}^d;\mathbb{R}^d))$. Suppose that $r_0 \in (0,1)$ and there is a Dini function $h$ such that for all $x \in \mathbb{R}^d$
				\begin{align*}
					|f(t,x)-f(t,y)| + |\tilde{f}(t,x)-\tilde{f}(t,y)| \leq h(|x-y|), \text{ for all } y \in B_{r_0}(x), t \in [0,T].
				\end{align*}
				Then the cauchy problem (equation PDE1 of the paper) has a unique strong solution $u(t,x)$ such that
				\begin{align}
					\|u\|_{L^{\infty}([0,T];C_b^2(\mathbb{R}^d))} \leq C(d,T)\left( 1+ 	\|f\|_{L^{\infty}([0,T];C_b(\mathbb{R}^d))} + 	\|\tilde{f}\|_{L^{\infty}([0,T];C_b(\mathbb{R}^d;\mathbb{R}^d))}\right).
				\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 116 (temporal smoothing of domain constraint) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $\tvvv^N$ and $\tuuu^N$ be the temporally smoothed quantities from Definition~\ref{d:t.smooth}. Let $J^N\equiv J(p^N,\tep,\lambda)$ be as defined by \eqref{e:bad.times.J}. Then, analogously to 
\eqref{e:domain.plus.coarse} and the bound from Lemma~\ref{l:sp.smooth.domain}, with high probability we have
	\[
	\Tvvv^N(t,y)
	\ge
	\Tuuu^N(t,y)^2
	-\frac{\eta^2}{2}\]
for all $(t,y)\in[q_*,1]\times\R$. We have additionally
	\[\max\left\{
	\begin{array}{c}
	|\tbbb^N(t,y)^2
		-\Tbbb^N(t,y)^2|,\\
	|\tvvv^N(t,y)-\Tvvv^N(t,y)|,\\
	|\tuuu^N(t,y)^2-\Tuuu^N(t,y)^2|
	\end{array}
	\right\}
	\le \bar{\lambda}_N
	\equiv \bigg(\frac{ \trK L}{\sep}\bigg)^{O(1)} 
	(\MAX_N)^2 \lambda\,.
	\]
for all $(t,y)\in ([q_*,1]  \setminus J^N)\times \bbR$.

\begin{proof}
As discussed in Definition~\ref{d:t.smooth}, 
the coefficients $\tuuu^N$, $\tvvv^N$,  $\Tuuu$, $\Tvvv$, etc.\ are well-defined for all times $t\in[q_*,1]$. The first conclusion follows from Lemma~\ref{l:sp.smooth.domain}: for all $t\in[q_*,1]$,
    \begin{align*}
    \Tvvv^N(t,y)
    &=\tE\bigg[ \frac{\sV^N(t-\sss,y)}
        {p^N(t-\sss)}\bigg]
    \ge
    \tE\bigg[ 
    \frac{\sU^N(t-\sss,y)^2}
        {p^N(t-\sss)
        \cdot (t-\sss)
        (p^N)'(t-\sss)
        }
        \bigg]
         - \frac{\eta^2}{2}\\
    &= \tE[ \suuu^N(t-\sss,y)^2]
    - \frac{\eta^2}{2}
    \ge (\tE[\suuu^N(t-\sss,y)])^2
    - \frac{\eta^2}{2}
    = \Tuuu^N(t,y)^2 -\frac{\eta^2}{2}
    \,.
    \end{align*} 
From Definition~\ref{d:t.smooth}, we have 
	\[\tvvv^N(t,y)
	= \frac{\tV^N(t,y)}{p^N(t)}
	= \frac{\tE[\sV^N(t-\sss,y)]}{p^N(t)}\]
Since $(p^N)'\le L^2$ by \eqref{e:sdelimits.pprime},
the difference between
$p^N(t)$ and $p^N(t-\sss)$ is at most
$L^2\tep$. Moreover, since we restrict to $t\ge q_*$ as defined by \eqref{e:qbar.and.qstar}, it follows by recalling \eqref{e:breve.q.bounds} that 
\beq
p^N(t)\ge \brep=\frac1{L^{\breve{c}}}\,.\eeq
Combining with the bound on $\sV^N$ from Lemma~\ref{l:sp.smooth.reg} gives, for $t\in [q_*,1]$, 
	\[
	\Big|\tvvv^N(t,y)
	-\Tvvv^N(t,y)\Big|
	=\bigg|
	\frac{\tE[\sV^N(t-\sss,y)]}
		{p^N(t)}
	-\tE\bigg[ \frac{\sV^N(t-\sss,y)}
		{p^N(t-\sss)}\bigg]\bigg|
	\le \bigg(\frac{ \trK L}{\sep}\bigg)^{O(1)} 
	(\MAX_N)^2 \tep\,.\]
Now applying Lemma~\ref{l:sp.smooth.domain} gives, for all $t\in[q_*,1]$,
	\[
	\frac{\sU^N(t,y)^2}
		{p^N(t)
		\cdot t
		(p^N)'(t)
		} - \frac{\eta^2}{2}
	\le \frac{\sV^N(t,y)}
		{p^N(t)}
	\le \bigg(\frac{ \trK L}{\sep}\bigg)^{O(1)} 
	(\MAX_N)^2\,,
	\]
which also implies a bound on $\sU^N$. 
Finally we note that if $t\in [q_*,1]  \setminus J^N$, then
	\begin{align*}
	\Big|\tuuu^N(t,y)
	-\Tuuu^N(t,y)\Big|
	&=\bigg|
	\frac{\tE[\sU^N(t-\sss,y)]}
		{p^N(t) \cdot t (p^N)'(t)}
	-\tE\bigg[\frac{\sU^N(t-\sss,y)}
		{p^N(t-\sss) \cdot
		(t-\sss) (p^N)'(t-\sss)}
		\bigg]
	\bigg| \\
	&\le
	\bigg(\frac{ \trK L}{\sep}\bigg)^{O(1)} 
	(\MAX_N) \lambda\,,
	\end{align*}
using the bound on $\sU^N$ noted above. It follows that
for $t\in [q_*,1] \setminus J^N$ we have
	\[
	\Big|\tuuu^N(t,y)^2
	-\Tuuu^N(t,y)^2\Big|
	\le
	\Big|\tuuu^N(t,y)
	-\Tuuu^N(t,y)\Big|
	\Big|\tuuu^N(t,y)^2
	+\Tuuu^N(t,y)^2\Big|
	\le \bigg(\frac{ \trK L}{\sep}\bigg)^{O(1)} 
	(\MAX_N)^2 \lambda\,.
	\]	
The discrepancy between $\tbbb^N$ and $\Tbbb^N$ can be bounded similarly.
Combining the above bounds proves the claim, recalling the order of parameters from Assumption~\ref{a:params}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 9 of arXiv:2609.03993, 'The Endpoint Fractional Riesz Estimate on the Hamming Cube'] Let $A$ be the positive generator of a quantum Markov semigroup $(T_t)_{t\ge0}$.  On a common
		$*$-algebra contained in the domain of $A$, define the carr\'{e} du champ by
		\begin{equation}
			\Gamma_A(x,y)= \frac{1}{2} ( A(x^*)y+x^*A(y)-A(x^*y) ).

		\end{equation}
		The semigroup satisfies $\Gamma_2\ge0$ if
		\begin{equation}
			\Gamma_A(T_tx,T_tx)\le T_t\Gamma_A(x,x)

		\end{equation}
		for every $t>0$ and every $x$ in that algebra.

[Definition def:codiff of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] For jointly S$\alpha$S random variables $X$ and $Y$ with
$\alpha \in (1,2]$, the \emph{codifference} is
\begin{equation}

\tau(X,Y) := \|X\|_\alpha^\alpha + \|Y\|_\alpha^\alpha
- \|X - Y\|_\alpha^\alpha.
\end{equation}

[Corollary 10 (Profile remainders) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Suppose
\begin{equation}
 |r_{ij,N}|\le\varepsilon_Ns_{ij}^2,
 \qquad \varepsilon_N\to0.
