\begin{align*}
\| \Phi(Y,Y') - \Phi(Z,Z') \|_{X,2\alpha} &\leq \| (\Gamma(Y),0) - (\Gamma(Z),0) \|_{X,2\alpha}
\\ &\quad + \| (\Psi(Y),f(Y)) - (\Psi(Z),f(Z)) \|_{X,2\alpha}.
\end{align*}
By Proposition \ref{prop-reg-conv-Hoelder} we have
\begin{align*}
\| (\Gamma(Y),0) - (\Gamma(Z),0) \|_{X,2\alpha} = \| \Gamma(Y) - \Gamma(Z), 0 \|_{X,2\alpha} \leq \| f_0(Y) - f_0(Z) \|_{\infty} t^{1-2\alpha}.
\end{align*}
Furthermore, noting that $Y_0 = Z_0$ and $Y_0' = Z_0'$, by Lemma \ref{lemma-lin-growth} and Lemma \ref{lemma-norm-of-Y} we obtain
