[Proposition pro.ak-inputs of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Fix any $\beta_h\in(0,1/8]$. There exist deterministic constants $C=C(d,\Lambda,r_0,\beta_h)<\infty$ and $c=c(d,\Lambda,r_0,\beta_h)>0$, a deterministic exponent $\sigma=\sigma(d,\Lambda,r_0,\beta_h)\in(0,1)$, and a random scale $\mathcal{X}_{\beta_h}\colon\Omega\to[0,\infty)$ with the following properties. First, the random scale has a stretched-exponential tail:
		\begin{equation}
			\mathbb{Q}\bigl(\mathcal{X}_{\beta_h}\ge M\bigr)\le C\exp\bigl(-c M^\sigma\bigr)\qquad\text{for every }M\ge 0\, .
		\end{equation}
		Second, on a $\mathbb{Q}$-full-probability event, the following estimates hold for every integer $M\ge \mathcal{X}_{\beta_h}(\omega)$.
		\begin{itemize}
			\item Let $k\in\{1,d\}$, let $u\in H^1(\square_M;\mathbb{R}^k)$, and let $f\in H^{1/6}(\square_M;\mathbb{R}^k\otimes\mathbb{R}^d)$ satisfy $-\nabla\cdot(\mathbf{a}\nabla u)=\nabla\cdot f$ componentwise in $\square_M$. Then
			\begin{equation}
				3^{-M/6}\|(\mathbf{a}-\bar{\mathbf{a}})\nabla u\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-1/6}(\square_M)}\le C 3^{-\beta_h M}\bigl(\|\nabla u\|_{\underline L^2(\square_M)}+3^{M/6}[f]_{\underline H^{1/6}(\square_M)}\bigr)\, .
			\end{equation}
			\item For every $j$ with $1\le j\le d$,
			\begin{equation}
			\begin{aligned}
				&3^{-M}\|w_{j,M}-x_j\|_{\underline L^2(\square_M)}
				+3^{-M/6}\|\nabla w_{j,M}-e_j\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-1/6}(\square_M)}\\
				&\qquad
				+3^{-M/6}\|\mathbf{a}\nabla w_{j,M}-\bar{\mathbf{a}} e_j\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-1/6}(\square_M)}
				\le C 3^{-\beta_h M}\, .
			\end{aligned}
			\end{equation}
		\end{itemize}

[Corollary cor:caccioppoli_combined_decay of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] In the setting of Lemma (l:control_mesoscopic of the paper), there exists a constant $C$ 
depending only on $\mu,p,q,r,p_0,d$ and $\gamma_0$ such that, for any local solution $(v^N,\pi^N,(\widetilde{\pi}^N_{k,\alpha})_{k,\alpha})$ to (equation eq:turbulent_Stokes_scaling_original_iteration of the paper), it holds that
\begin{align}

\Big({\mathbf E}\sup_{ \eta^{\ell+1} I} \Big\|v^N-\fint_{\eta^{\ell+1} B} v^N\Big\|_{\underline{L}^2(\eta^{\ell+1} B)}^r\Big)^{1/r}
&\leq 
C\eta^{\ell \gamma_0} \mathcal{L}_Q^{\#},\\

\eta^{\ell+1} \Big( {\mathbf E}\Big\|\pi^N-\fint_{\eta^{\ell+1} B} \pi^N\Big\|_{\underline{L}^2(\eta^{\ell+1} Q)}^r\Big)^{1/r}
&\leq 
C \mathcal{L}_Q^\#,
\end{align}
where $0\leq \ell\leq m$ and $m\geq 1$ is such that $N^{-1}\leq \eta^{m-1} L_0^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 (Uniform half-line stability) of arXiv:2608.30211, '2608.30211'] The map $\varrho\mapsto\mu_\varrho$ is continuous on $[0,1]$ and
\begin{equation}
 \mu_*:=\min_{\varrho\in[0,1]}\mu_\varrho>0.
\end{equation}
Lemma~\ref{lem:product} transfers the same lower bound to the
linearized operators on $\Hh^d$.

