\begin{equation}

    f_a(x) \coloneqq \rho_{\cN}^{}(a)e^{\frac{x^2}{2}}\left( \int_x^{\infty}e^{-\frac{y^2}{2}}dy \ind_{(a, \infty)}(x) - \int_{-\infty}^{x}e^{-\frac{y^2}{2}}dy \ind_{(-\infty, a)}(x) \right).
\end{equation}

