		\begin{align}
			\mathbb{E}\left(\left\vert \int_{s}^{t}B_{u-\sigma,u-\tau}\otimes \mathrm{d}^{\circ}B_{u}\right\vert^{2}\right)\lesssim \big{(}sgn(\sigma)\vert \sigma\vert ^{2H-1}-sgn(\tau)\vert\tau\vert^{2H-1}\big{)}^2(t-s)^{2}+\sum_{1\leqslant i\leqslant 7}(t-s)^{\frac{i}{2}H}(\sigma-\tau)^{(4-\frac{i}{2})H} .
		\end{align}

