body:
[Lemma 7 of arXiv:2604.00692, 'Uniform-in-time diffusion approximations for multiscale stochastic systems'] Under {\bf (A$^\beta_{\rm SK}$)}, the unique centered solution to the Poisson equation
\begin{equation*}
\sL_1\Phi(\cdot,y)=-H(\cdot,y)=-x
\end{equation*}
is given by
\begin{equation}
\Phi(x,y)=A(y)^{-1}x.
\end{equation}
Consequently, the effective diffusion matrix and drift are
\begin{align}
\cG(y)&=A(y)^{-1}\sigma(y)\sigma(y)^*(A(y)^{-1})^*,\\
\cF(y)&=-A(y)^{-1}\nabla U(y)+\mathfrak B(y),
\end{align}
where $\mathfrak B(y)$ is called the noise-induced term given componentwise by
\begin{equation}
\mathfrak B_i(y)
=
\sum_{j,k=1}^d \Sigma_{jk}(y)\,\partial_{y_j}(A(y)^{-1})_{ik},
\qquad i=1,\dots,d.
\end{equation}

[Lemma 10 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] Let  $(h_{\ell})_{\ell\in\N}$ be
	the white noise truncation  given in \eqref{eq: white noise trunc}. The associated covariance kernels $(k_{\ell})_{\ell\in\N}$ satisfy
	\begin{enumerate}[$(i)$]
		\item as ${\ell}\to\infty$, 
		\begin{align}
			k_{\ell}\to k \quad\text{ in }L^1(M^2,\vol\otimes \vol),
		\end{align}
		\item there exist $C\geq0$ such that for all ${\ell}\in \N$ and all $x,y\in M$,
		\begin{align}
			k_{\ell}(x,y)\leq C\log\left(\frac1{d(x,y)}\wedge \ell\right)+C,
		\end{align}
		\item for all ${\ell}\in\N$ there exists a constant $C_{\ell}>0$ such that
		\begin{align}
			|k_{\ell}(x,x)+k_{\ell}(y,y)-2k_{\ell}(x,y)|\leq C_{\ell} d(x,y), \quad x,y\in M.
		\end{align}
	\end{enumerate}

