\begin{align}
\Bigl\{\sup_{x\in\mathbb Z^d}\#\mathcal J_x>M\Bigr\}
=
\bigcup_{k=0}^{\widehat n}
\bigl\{S_k\notin S[1,k-1],\ \#\mathcal J_{S_k}>M\bigr\}.
\end{align}
Fix \(1\le i\le K\) and \(k\in I_i\), and define stopping times
\[
\tau_0(k):=i,
\qquad
\tau_r(k):=\inf\{m\in[\tau_{r-1}(k)+2,K]:S_k\in S(I_m)\},
\qquad r\ge1.
\]
