[Definition of arXiv:2509.23069, 'Every cutoff profile is possible'] Let $((X^{(n)}_t)_{t\geq 0})_{n\geq 1}$ be a sequence of continuous-time Markov chains. If there exists $((t_n), (w_n),p) \in \CTST$ such that for every $c\in {\ensuremath{\mathbb R}} $ we have
\begin{equation}
    \mathrm{d}^{(n)}\left( t_n + cw_n \right) \xrightarrow[n\to \infty]{} p(c),
\end{equation}
then the function $p$ is called \textbf{cutoff profile} and $w_n$ is called  \textbf{window size}.

[Def +measure spin finite volume of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $\Lambda \subset \mathbb Z^d$ be finite, $\beta\geq 0$, and $\mathsf{h}\in \mathbb R^\Lambda$. Let also $\zeta$ be a measure supported on $\mathbb R^+$ that has all Gaussian moments. We abuse notation, and denote by $\nu^\zeta_{\Lambda,\beta, \mathsf{h}}$ the probability measure on $\mathbb R^{\overline{\Lambda}}$ defined by the Radon--Nikodym density
\begin{equation}
\mathrm{d}\nu^\zeta_{\Lambda,\beta,\mathsf{h}}(\tau) = \frac{1}{\mathbf{Z}^\zeta_{\Lambda,\beta,\mathsf{h}}} \exp\Big(\beta \sum_{xy\in \overline E(\Lambda)} \tau_x \tau_y
+\beta \sum_{x\in \Lambda}\mathsf{h}_x\tau_x\Big)\prod_{x\in \Lambda}\mathrm{d}\rho(\tau_x) \prod_{x \in \partial^{\textup{ext}} \Lambda} \mathrm{d}\zeta (\tau_x), \qquad \forall \tau \in \mathbb R^{\overline \Lambda},
\end{equation}
where $\mathbf{Z}^\zeta_{\Lambda,\beta,\mathsf{h}}$ is a normalisation constant. We write $\langle \cdot \rangle^\zeta_{\Lambda,\beta,\mathsf{h}}$ for the expectation with respect to $\nu^\zeta_{\Lambda,\beta,\mathsf{h}}$.

[Theorem 36 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and~\ref{ass:rand_ent}, fix $\tau>0$ sufficiently small. Let $z=E+\ii\eta$ satisfy
        \begin{align}
                z\in\mb D(\tau,\eta_0), \qquad \eta\geq N^{-1+\tau}, 
        \end{align}
        and suppose that $\|\Pi(z)\|\lesssim1$. Let $\phi\in[N^{-1},N^{\tau/10}]$ and $\vphi>0$ be deterministic, with
        \begin{align}
                0<\vphi\lesssim\|\Im\Pi(z)\|+\phi, 
        \end{align}
        and assume that $ G(z)-\Pi(z)=O_\prec(\phi)$ and $ \Im G(z)=O_\prec(\vphi)$.
        Then, we have
        \begin{align}
                \Om(G(z),z) = O_\prec \left((1+\phi)^3\sqrt{\frac{\vphi+\eta}{N\eta}}\right). 
        \end{align}
        Moreover, for every deterministic matrix $B\in\C^{L\times L}$ with $\|B\| = O(1)$, we have
        \begin{align}
                \avg{B\Om(G(z),z)}_L = O_\prec \left((1+\phi)^6\frac{\vphi+\eta}{N\eta}\right). 
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: integrals below the threshold of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] Suppose that $\boldsymbol{\mu} \in \mathcal{S}_{\bar \boldsymbol{y}}[0, b]$ for a given threshold function $\bar \boldsymbol{y}$.
	\begin{enumerate}
		\item[(a)] Assume that there exists $y_0 \in (0, \infty]$ such that $\bar \boldsymbol{y}_t \geq y_0$ for all $t \in [0, b]$ and $\boldsymbol{\mu}_0$ is the null measure. If $t \in [0, b]$ and $\phi \in C_c^1(\mathbbm{R}_+ \times [0, y_0))$, then
		\begin{equation}

			\angled{\phi}{\boldsymbol{\mu}_t} =  \lambda_0 \int_0^t \phi(u, u)S_g(u, u)du.
		\end{equation}
		Furthermore, if $t \in [0, b]$ and $y \in [0, y_0)$, then
		\begin{equation*}
			\boldsymbol{\mu}_t\left(\mathbbm{R}_+ \times [0, y]\right) = \lambda_0 \int_0^{t \wedge y} S_g(u, u)du,
		\end{equation*}
		and this equation holds for $y = y_0$ when $y_0 < \infty$.

		\item[(b)] Suppose that there exists $y_0 \in (0, \infty]$ such that $\bar \boldsymbol{y}_t \geq t \wedge y_0$ for all $t \in [0, b]$; here $\boldsymbol{\mu}_0$ need not be null. If $t \in [0, b]$ and $\phi \in C_c^1(\mathbbm{R}_+ \times [0, t \wedge y_0))$, then
		\begin{equation}

			\angled{\phi}{\boldsymbol{\mu}_t} = \lambda_0 \int_0^t \phi(u, u) S_g(u, u)du.
		\end{equation}
		Moreover, if $t \in [0, b]$ and $y \in [0, t \wedge y_0]$, then
		\begin{equation*}
			\boldsymbol{\mu}_t\left(\mathbbm{R}_+ \times [0, y]\right) = \lambda_0 \int_0^y S_g(u, u)du.
		\end{equation*}
	\end{enumerate}

[Lemma L:UST_path_inside of arXiv:2512.21977, 'Repeat times and a two-weight UST model'] {MSS24}}] 
    Denote by $\pi_{\ensuremath{\mathcal T}} (u,v)$ the path in the tree ${\ensuremath{\mathcal T}} $ connecting the vertices $u$ and $v$. Then
    \begin{equation*}
        \ensuremath{\boldsymbol{\mathrm{P}}}_{\ensuremath{\mathcal T}}  \Big( \exists u,v \in V(K_n), e \in E(K_n) \text{ with } v \in {\ensuremath{\mathcal C}} (u), e \in \pi_{\ensuremath{\mathcal T}} (u,v), \textup{\textrm{w}}(e) = 1 \Big) \leq n^{4-\gamma}.
    \end{equation*}

