body:
[Lem 2 of arXiv:2510.21446, '{Uniqueness of adapted solutions to scalar BSDEs\\ with Peano-type generators}\tnoteref{fo'] For $\rho(\cdot)\in \Sbb$, let $\rho_c(x):=\rho(x)+c$ for $x\in\R_+$ and some constant $c\in\R_+$, and let
$$
H_c(u):=\int_0^u \frac{1}{\rho_c(x)}{\rm d}x=\int_0^u \frac{1}{c+\rho(x)}{\rm d}x,\ \ u\in\R_+.\vspace{0.1cm}
$$
Then, $H_c(\cdot)$ is well-defined and strictly increasing on $\R_+$, $H_c(0)=0$ and $\lim\limits_{u\To +\infty} H_c(u)=+\infty$. Moreover, for each $k_1\geq H_c(1)$ and $k_2,k_3>0$, we have
\begin{equation}
H_c^{-1}(k_1+k_2)\leq 2{\rm e}^{k_2(\rho(1)+c)}H_c^{-1}(k_1)
\end{equation}
and
\begin{equation}
\rho_c(k_3H_c^{-1}(k_1+k_2))\leq 2{\rm e}^{k_2(\rho(1)+c)} \rho_c(k_3H_c^{-1}(k_1)),\vspace{0.1cm}
\end{equation}
where $H_c^{-1}(\cdot):\R_+\To \R_+$ denotes the inverse function of $H_c(\cdot)$.

[Lemma Measure change Relationship 1 of arXiv:2605.20800, 'On the maximal displacement of subcritical branching random walk in random environment'] For any integer $x\geqslant 1$, for any measurable function $\phi$, we have
		\begin{equation}
			e^{\lambda_1 x}P_E\otimes P_{\overline{Y}} (e^{R_x}\phi(B_x,R_x)) = Q_E\otimes P_{\overline{Y}} ( \phi(B_x,R_x) ).
		\end{equation}
		where $B_x$ is defined in (def of overlineA of the paper) from branching system $(\mathcal{T},V)$.
		Especially, we have
		\begin{equation}
			e^{\lambda_1 x} P_E\otimes P_\xi(M\geqslant x)
			=
			e^{\lambda_1 x} P_E\otimes P_{\overline{Y}}(e^{R_x}B_x)
			=
			Q_E\otimes P_{\overline{Y}} (B_x).
		\end{equation}

