[Lemma lemvitl2 of arXiv:2605.11785, 'Regularization of a mean-field SDE by an additive common noise: the conditional expectatio'] For initial positions $(X^j_0)_{j\ge 1}$ i.i.d. according to $\mu_0$,
   $$\sup_{N\in{\mathbb N}^*,\ j\in\{1,\cdots,N\},\ {\bm{x}}\in {\mathcal C}}\mathbb{E}\left[\left(\sqrt{N}\sup_{t\in[0,T]}|{\mathcal Y}^{j,N}(t,(X^1_0,\cdots,X^N_0),{\bm{x}})-{\mathcal Y}^{\mu_0}(t,X^j_0,  \bm{x})|\right)^\rho\right]<\infty$$
   for any $\rho\geq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $K' = (K'_n)$ be a sequence of random graphs with vertex set $[n]$.
    \begin{itemize}
         \item If $K \simeq_{n \to +\infty} K'$ then $SOV(K) = SOV(K')$.
        \item If $K \subseteq K'$ whp then $SOV(K) \leq SOV(K')$.
    \end{itemize}

[Lm 41 (Generalized de Bruijn's integration formula) of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $\ell\geq m>0$ be fixed integers and let $\mu$ be an appropriate measure on a region $X$. Let $f_1,\dots,f_{\ell-m},g_1,\dots, g_m$ be functions and let $h$ be an skew-symmetric function of two variables which are all integrable over $X$ with respect to $\mu$. Additionally let $S$ be a constant skew-symmetric matrix of dimension $(\ell-m)\times(\ell-m)$. Then the following identities hold: when $\ell$ is even
	\begin{multline}

		\frac{(-1)^{\binom{\ell-m}{2}}}{m!}\int_{X} \dd \mu(w_1) \cdots \int_{X} \dd\mu(w_{m}) \det \left[g_j(w_i)\right]_{1\leq i,j\leq m}\pf\left[\begin{array}{cc}
			h(w_i,w_j)_{1\leq i,j\leq m}  &  f_k(w_i)_{1\leq i\leq m\atop1\leq k\leq \ell-m} \\[8pt]
			-f_k(w_j)_{1\leq k\leq \ell-m\atop1\leq j\leq m} & S
		\end{array}\right] \\
		= \pf\left[\begin{array}{cc}
			A & C \\[5pt]
			-C^T & S
		\end{array}\right]
	\end{multline}
	and when $\ell$ is odd
	\begin{multline}

		\frac{(-1)^{\binom{\ell-m}{2}}}{m!}\int_{X} \dd \mu(w_1) \cdots \int_{X} \dd\mu(w_{m}) \det \left[g_j(w_i)\right]_{1\leq i,j\leq m}
		\pf\left[\begin{array}{ccc}
			h(w_i,w_j)_{1\leq i,j\leq m} & \vec{\bm1}_{m} & f_k(w_i)_{1\leq i\leq m\atop1\leq k\leq \ell-m} \\[8pt]
			-\vec{\bm1}^T_{m} & 0 & 0 \\[8pt]
			-f_k(w_j)_{1\leq k\leq \ell-m\atop1\leq j\leq m} & 0 & S
		\end{array}\right] \\
	=  \pf \left[\begin{array}{ccc}
		A & \vec{b} & C \\[5pt]
		-\vec{b}^T & 0 & 0 \\[5pt]
		-C^T & 0 & S
	\end{array}\right] .
	\end{multline}
    where $A$ is a skew-symmetric $m\times m$-dimensional matrix, $C$ is an $m\times(\ell-m)$-dimensional matrix and $\vec{b}$ is a vector of length $m$.
	The matrix elements are given as:
	\begin{align*}
	\left[A\right]_{i,j} & = \int_X \dd \mu(u) \int_X \dd \mu(w) g_i(w)g_j(u)h(w,u), \\
	\left[C\right]_{i,k} & = \int_X \dd \mu(w) g_i(w)f_k(w), \\
		\left[\vec{b}\right]_{i} & = \int_X \dd \mu(w) g_i(w),
	\end{align*}
    for each $1\leq i,j\leq m$ and $1\leq k\leq \ell-m$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def.func of arXiv:2607.10105, 'The four-dimensional Anderson model: a case study for critical SPDEs'] Define $\mathcal E$ to be the class of functions $f$ on $\mathbb T^4$ (or generally $(\mathbb T^4)^n$) that is symmetric in all variables and even in each variable; i.e.
\begin{equation} f(\cdots,x^i,\cdots,x^j,\cdots)=f(\cdots,x^j,\cdots,x^i,\cdots);\qquad f(\cdots,x^i,\cdots)=f(\cdots,-x^i,\cdots).
\end{equation}

[Proposition prop:equivalence of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] For any disjoint $S_1,..,S_n\subset\mathbbm{R}$ and $\widehat{G}(x_1,...,x_n)$ defined in~(equation eq:gf-fz of the paper), there exists $C\in(0,\infty)$ such that
    \begin{equation*}
        \int_{S_1\times...\times S_n}\widehat{G}(x_1,...,x_n)\prod_{i=1}^ndx_i=C^n\mathbbm{E}\left[\prod_{i=1}^n\nu_{\eta\cap\mathbbm{R}}(S_i)\right].
    \end{equation*}
    Here the expectation $\mathbbm{E}$ is with respect to the chordal $\SLE_\kappa$ curve $\eta$.
    Hence, $\widehat{G}(x_1,...,x_n)=CG(x_1,...,x_n)$, where $G(x_1,...,x_n):=G_{\mathbbm{H},0,\infty}(x_1,...,x_n)$ is defined in~(equation eq:gf of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_D_t_zeta_L^infty of arXiv:2609.01250, 'Global regularity for 2D gravity water waves with two retreating point vortices'] Assume the bootstrap assumptions. There holds
    \begin{equation}
    \begin{aligned}
    \left\lVertD_t\zeta\right\rVert_{L^\infty}\lesssim&\ \epsilon t^{-\frac{1}{4}},\\
        \norm{\partial_\alpha^{s-1}D_t\zeta}_{L^\infty}\lesssim&\ \epsilon t^{-\frac{1}{4}}\ln (2+t),\\
        \norm{\partial_\alpha ^{s-1}D^2_t\zeta}_{L^\infty}+\left\lVert\partial_\alpha^s \zeta\right\rVert_{L^\infty}\lesssim&\ \epsilon t^{-\frac{1}{6}}\ln (2+t).
    \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p:irreg of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] For every $\alpha > 0$, $g_T \to \infty$, and $\rho > 1$, there exists a smooth stationary Gaussian process $f$ satisfying 
\begin{equation}

\mu[B(\delta)] \asymp \delta^\alpha  
\end{equation}
as $\delta \to 0$, for which 
 \begin{equation}

    \limsup_{T \to \infty} \frac{ \text{\textup{Cap}}_f(B(T + g_T)) }{ \text{\textup{Cap}}_f(B(T)) }  > \rho . 
    \end{equation}

[Lem H comp of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] Assume $\hat{d}_{\mathrm{s}} > 2$.
  For each $a > 0$ and $t > 0$, set
  \begin{equation}
    F(a,t)
    \coloneqq
    \left\{
      x \in \supp \Pi_t \,\middle|\,
      \varlimsup_{r \downarrow 0}
      \frac{\Pi_t(B(x,r))}{\Psi_{\mathrm{cp}}(r)}
      <a
    \right\}.
  \end{equation}
  Then, for all sufficiently small $a>0$,
  $\mathcal{H}_{\Psi_{\mathrm{cp}}}(F(a,t))=0$ for all $t > 0$, $\hat{P}_{\bm{\rho}}$-a.s.

