[Lemma 12 of arXiv:2603.26936, 'Sharp Riemannian heat kernel estimates on the cut locus and the Parabolic Anderson model'] Fix any $\epsilon>0$. Suppose  $0<a<\frac{1}{2}$ and $0<\alpha<\frac{d}{2}$. The following inequalities hold for any $t>0$ and $0<\epsilon'\leq\epsilon$, with the constants on the right hand side possibly depending on $\epsilon$ if the left hand side involves $\epsilon'$.
\begin{equation}
     {  \sup_{x\in M}} \int_{M} G^{\epsilon'}_t(d(x,y)) m(dy)\leq C,
    \end{equation}
    \begin{equation}
    { \sup_{x\in M}}   \int_{M} d(x,y)^{2\alpha-d} m(dy)\leq C,
    \end{equation}
    \begin{equation}
     { \sup_{x,x'\in M} } \int_{M} G^{\epsilon'}_t(d(x,y)) d(x',y)^{2\alpha-d} m(dy)\leq C(t^{\frac{2\alpha-d}{2}}+1).
    \end{equation}
    In addition, for all $0<t\leq 1$ and {all $a\in(0,\frac{1}{2})$},
    \begin{equation}
    {\sup_{x,x'\in M}}    \int_{M} G^{\epsilon'}_{t,x,x'}(at,y) m(dy)\leq C,
    \end{equation}
    \begin{equation}
    {\sup_{x,x',x_0\in M}}  \int_{M} {G^{\epsilon'}_{t,x,x'}(at,y)}d(y,x_0)^{2\alpha-d} m(dy)\leq C\left[\left(a(1-a)t\right)^{\frac{2\alpha-d}{2}}+1\right].
    \end{equation}

