body:
[Lemma lem:root of arXiv:2609.00889, 'Dominant-Degree Conditions for Ramsey--Tur\'an Factors of Non-Directed Cycle Orientations'] For $D(z,Q,R)$, the following hold.
\begin{enumerate}
 \item If $\Delta^+(Q)\le1$, then there is no $C_4^{\mathrm{ad}}$ containing the vertex $z$.
 \item If $s\ge3$ and the matching number of the underlying graph of $Q$ is at most $1$, then there is no $C_{2s}^{\mathrm{ad}}$ containing the vertex $z$.
\end{enumerate}

[Definition Eq: star product of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Let $\curvearrowright:\mathcal{H}\times\mathcal{H}\to\mathcal{H}$ be the Guin-Oudom extension of grafting. We define the bilinear associative product $\star:\mathcal{H}\times\mathcal{H}\to\mathcal{H}$ as
		\begin{align}
			w\star v=\sum_{w_1\cdot w_2=w}w_1\cdot(w_2\curvearrowright v)\,, \qquad w,v\in{\mathcal F}.
		\end{align}

[Lemma lem: grid of arXiv:2509.04349, 'Precise asymptotics for the norm of large random rectangular Toeplitz matrices'] For any $\tau\in(0,3/4)$, there exist positive integers $T=T(\tau), k=k(\tau)$, and vectors $\mathbf{u}^{(1)},\dots,\mathbf{u}^{(T)}$ from the interior of the unit ball in $\mathbb{C}^k$ such that, for any $t\in\{1,\dots,T\}$ and all $p/n\in\left(\tau_{t-1},\tau_t\right]$,
    \begin{equation}
        \frac{\|\Pi_{p/N}^{[k]}\operatorname{diag}\{\mathbf{u}^{(t)}\}\Pi_{n/N}^{[k]}\|}{\sqrt{p/N}}>K_{1,n/p}-\tau/2.
    \end{equation}
    Moreover, for all $p/n\in\left[\log^{-\alpha} n,\tau\right]$ and all sufficiently large $n$, we have:
    \begin{equation}
        \frac{\|\Pi_{p/N}^{[2L_n+1]}\operatorname{diag}\{\mathbf{u}^{(0)}\}\Pi_{n/N}^{[2L_n+1]}\|}{\sqrt{p/N}}>K_{1,n/p}-3\tau/4,
    \end{equation}
    where  $L_n:=\lceil \log n\rceil$ and $\mathbf{u}^{(0)}=(0,\dots,0,1-\tau/15,0,\dots,0)^\top$ with $L_n$ zeros on both sides of the term $1-\tau/15$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2609.03243, 'Weighted Ces\`aro type operators on the weighted Bergman spaces in the unit ball'] Let $\alpha>-1$, $\theta>0$ and $\mu$ be a positive Borel measure on $[0,1)$. Then
\begin{equation}
\int_{\mathbb{B}_n}\left|V_{\mu}^{\xi}(z)\right|^{\theta}{\rm d}v_{\alpha}(z)\simeq \int_{\mathbb{D}}\left|V_{\mu}(u)\right|^{\theta}(1-|u|^2)^{n+\alpha-1}{\rm d}A(u),
\end{equation}
where ${\rm d}A$ is the normalized area measure on $\mathbb{D}$.

