[Definition DUFJ-INT-SJ-B of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] A random function $v\left( {x} \right)$ is said to be inertial-range intermittent, if for two positive exponents ${p_1} > {p_2}$, there exists an increasing function $\mathfrak{h}_2\left( r \right)$ such that
\begin{equation}
\frac{{{{\left\| {v\left( { \cdot  + l\mathbf{n}} \right) - v\left(  \cdot  \right)} \right\|}_{{L^{{p_1}}}}}}}{{{{\left\| {v\left( { \cdot  + l\mathbf{n}} \right) - v\left(  \cdot  \right)} \right\|}_{{L^{{p_2}}}}}}} \sim {\mathfrak{h}_2}\left( {r} \right) \to  \infty , \ \  \forall \, l \in \left[ {{l_D},{l_I}} \right] , \  \mbox{as}\ r \to  \infty , \ \mathbb{P}\mbox{-a.s.} 
\end{equation}

[Lemma 16 of arXiv:2604.04823, '2604.04823'] There exists a constant~$C$, independent of~$a,\epsilon$, such that for any~$a,\epsilon$ with~$a\sqrt{\epsilon}$ sufficiently small, the perturbation satisfies the global bound
\begin{equation}
\norm{D^i\hat{P}}_{L^\infty(\T^d)} \le C\paren*{a\sqrt{\epsilon}}^{2-i}\,, \quad \forall 1\leq i\leq3\,,
\end{equation}
and consequently,
\begin{gather}
    \norm{\hat U}_{C^2(\T^d)}
    \leq C\,, \qquad \norm{D^3\hat U}_{L^\infty(\T^d)} \leq C\paren*{a\sqrt\epsilon}^{-1}\,.
\end{gather} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 4 of arXiv:2604.20323, '2604.20323'] For $u\ge 1$, $\theta\in\{0,1\}$ and $k\in\N$, there exists $C<\infty$ such that 
  \begin{align}
    \forall t\in(0,T],\;\|\partial_t^\theta\nabla^kp_\alpha(t,\cdot)\|_{L^u}+\|\partial_t^\theta\nabla^k\bar p_\alpha(t,\cdot)\|_{L^u}\le Ct^{-(\theta+\frac k\alpha +\frac d{\alpha u'})}.\end{align}For $k\in\N$, there exists $C<\infty$ such that
  \begin{equation}
   \forall (t,y)\in(0,T]\times \R^d,\;|\nabla^kp_\alpha(t,{y})|\le Ct^{-\frac k\alpha}\bar p_\alpha(t,y).
  \end{equation}

  For $k\in\{0,1\}$, there exists $C<\infty$ such that \begin{align}
\mbox{for }0<s<t\le T\mbox{ and }y\in\R^d,\;|\nabla^kp_\alpha(t,y)-\nabla^kp_\alpha(s,y)|\le C\frac{(t-s)\wedge s}{s^{1+\frac k \alpha}}(1+(t/s)^{\frac d\alpha})\bar p_\alpha(t,y).
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] For $\Pp$-a.e.~$\omega$,
\begin{equation*}     \max_{0\le k<b^n}\abs{\xi_{n,k}(\omega)}\le C(\omega)n     \qquad\text{for all sufficiently large }n.                 
\end{equation*}

[Lemma Lem:ProjectionLemma of arXiv:2609.03762, '\vspace*{-2cm} Projected Riemannian Gradient Descent for the Bures--Wasserstein Barycenter'] For any positive definite matrix $P$, the unique BW projection onto the geodesically convex set $[\alpha I, \beta I]$ (for $0<\alpha \leq \beta < \infty$) is given by eigenvalue-clipping:
        \begin{equation}
            \mathrm{clip}_{\alpha, \beta}(P) = \argmin_{Q \in [\alpha I, \beta I]} \mathrm{B}(P, Q).
        \end{equation}
        Moreover, the projection $\mathrm{clip}_{\alpha, \beta}$ is non-expansive (1-Lipschitz) with respect to the BW distance.
        For all $P, Q \in \mathrm{PD}(d)$,
        \begin{equation}
            \mathrm{B}(\mathrm{clip}_{\alpha, \beta}(P), \mathrm{clip}_{\alpha, \beta}(Q)) \le \mathrm{B}(P, Q).
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 (Shifted Wasserstein recursion) of arXiv:2605.24937, '2605.24937'] Assume~\eqref{eq:one-step-w2-framework}. For all $0\le n\le N-2$,
\begin{equation}
  d_{n+1}^{\,2}
  \;\le\;
  L^{2}(1-\eta_n)^{2}\,d_n^{\,2}
  +2\,(1-\eta_n)\,\overline a_1\,d_n
  +\overline a_0^{\,2},
\end{equation}
where
$\overline a_0:=\sup_{0\le k<N}\|a_0(\widehat X_k)\|_{L^{2}}$
and
$\overline a_1:=\sup_{0\le k<N}\|a_1(\widehat X_k,\widetilde Y_k)\|_{L^{2}}$.

