body:
[Definition 79 of arXiv:2609.03875, 'Measure theory without infinities'] We say that a nonempty set $\mathcal Q$ is an $\alpha$-class if it satisfies the following conditions:
  \begin{enumerate}
  \item[(1)] If $A,B\in \mathcal Q$ and $A\cap B=\varnothing$, then $A\cup B\in \mathcal Q$.
  \item[(2)] If $A,B\in \mathcal Q$ and $B\subset A$, then $A\setminus B\in \mathcal Q$.
  \item[(3)] If $\mb A\colon\N\to\mathcal{Q}$ is a decreasing sequence of sets, then $\bigcap_{n\in\N} \mb A(n)\in \mathcal Q$.
  \end{enumerate}

[Lem 37 of arXiv:2608.30990, 'Convergence of symmetries: nilpotency, dimension, and perfectness'] Let  $k \leq 200 $ and $g_i \in B^{k}_i$.  If $\phi_i (g_i) \to g \in G$, then $g \in \overline{B}^k$, $g_i \in W_i$ for $i$ large enough, and  
 \begin{equation}
     \psi_i ( \pi _i (g_i)) \to \pi (g)  .         
 \end{equation}

[Definition 32 of arXiv:2608.29086, '2608.29086'] [$Spec(m)$]
Given $m \in RAT(Mol)$. $Spec(m)$ denotes the collection of all minimal integral closures of $m$, i.e.,
\begin{equation*}
Spec(m):=\{\lambda \in Cl(m) \ |\ \lambda \text{ is minimal} \} \quad \subset INT(Mol) \cap MOL(M_0)
\end{equation*}
Elements of $Spec(m)$ are called the \textit{spectra} of $m$.

[Proposition prop:fik-is-weaker-than-ik of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] $\textbf{FIK} \subsetneq \textbf{IK}$, that is,
  (1) $\textbf{IK} \vdash \textsf{wCD}$ and (2) $\textbf{FIK} \nvdash \textsf{FS2}$.
  \begin{proof}
    (1) Follows from the derivation below:
    \begin{center}
      \AxiomC{$ $}
      \RightLabel{\scriptsize{$\textsf{FS2}$}}
      \UnaryInfC{$(\Diamond \varphi \to \Box \psi) \to \Box (\varphi \to \psi)$}

      \AxiomC{$ $}
      \RightLabel{\scriptsize{}}
      \UnaryInfC{$(\varphi \to \psi) \to ((\varphi \lor \psi) \to \psi)$}
      \RightLabel{\scriptsize{$\textsf{M}_\Box$}}
      \UnaryInfC{$\Box(\varphi \to \psi) \to (\Box(\varphi \lor \psi) \to \Box\psi)$}

      \RightLabel{\scriptsize{Syll.}}
      \BinaryInfC{$(\Diamond \varphi \to \Box \psi) \to (\Box (\varphi \lor \psi) \to \Box \psi)$}
      \UnaryInfC{$\Box (\varphi \lor \psi) \to ((\Diamond \varphi \to \Box \psi) \to \Box \psi)$}
      \DisplayProof
    \end{center}
    (2) By soundness, it suffices to construct a $\Diamond$-p model that falsifies $\textsf{FS2}$.
    Let $\mathfrak{M}_{\textsf{FS2}} = (\set{x, y, y'}, \leq, \sqsubset, V)$, where
    $\mathord{\leq} = \set{ (x,x), (y,y), (y,y'), (y',y') }$,
    $\mathord{\sqsubset} = \set{ (x,y) }$,
    $V(p) = \set{ y' }$, and $V(q) = \emptyset$,
    then $\mathfrak{M}_{\textsf{FS2}}$ is clearly a $\Diamond$-p model.
    The model $\mathfrak{M}_{\textsf{FS2}}$ is visualized in Figure (fig:fs2-countermodel of the paper).
    \begin{figure}[htb]
      \centering
      \begin{tikzpicture}
      \fill (0, 2) circle (2pt);
      \draw (0, 2) node[left]{$x$};

      \fill (2, 2) circle (2pt);
      \draw (2, 2) node[right]{$y \not \Vdash^{\text{h}} p, q$};

      \draw [thick, ->, squig, rel] (0,2) to (2, 2);
      \draw (1, 2) node[below]{$\sqsubset$};

      \draw [thick, ->, rel] (2, 2) to (2, 4);
      \draw (2, 3) node[right]{$\leq$};

      \fill (2, 4) circle (2pt);
      \draw (2, 4) node[right]{$y' \Vdash^{\text{h}} p,\, \not \Vdash^{\text{h}} q$};

      \end{tikzpicture}
      \caption{The model $\mathfrak{M}_{\textsf{FS2}}$.}

    \end{figure}

    Here, $x \sqsubset y \not \Vdash^{\text{h}} p$ implies $x \not \Vdash^{\text{h}} \Diamond p$, so $x \Vdash^{\text{h}} \Diamond p \to \Box q$.
    On the other hand, $y \leq y'$, $y' \Vdash^{\text{h}} p$, and $y' \not \Vdash^{\text{h}} q$ imply $y \not \Vdash^{\text{h}} p \to q$,
    so $x \not \Vdash^{\text{h}} \Box(p \to q)$. Therefore, $x \not \Vdash^{\text{h}} \textsf{FS2}$.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 (Attached-tree mass inputs) of arXiv:2607.13183, '2607.13183'] For the tree attached to a core vertex $z$, the random mass
$W_z=\sum_{u:r(u)=z}d(u)$ satisfies, conditionally on $\Core$,
\begin{equation}
        \bar W_z:=\Egr[W_z\mid\Core]\le C(\eps^{-1}+d_{\Core}(z)),
        \qquad
        \Vargr(W_z\mid\Core)=O(\eps^{-3}),
\end{equation}
and
\begin{equation}
        \Egr\bigl[(W_z-\bar W_z)^4\mid\Core\bigr]=O(\eps^{-7}).
\end{equation}
Also
\begin{equation}
        S=\sum_zW_z=2|E(H)|=\Theta(N_c/\eps)=\Theta(\eps n)
\end{equation}
with high probability.

[Lemma 47 of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] There exist constants $C,c$ such that for all $n\in \NN$, all $\beta>0$ and $r\leq n^{1/10}$ , we have
  \begin{equation}

       \PP(\Gamma_{\0}^{(\beta n,n),t}\not\subseteq B_{\beta r n^{2/3}}(\LL_{\0}^{(\beta n, n)}) \textrm{ for some }t\in [0,1])\leq (1+C\beta n^2)e^{-cr^3}.
  \end{equation}

