[Lemma simple of arXiv:2412.04013, 'Rate estimates for total variation distance with applications\thanks{The author gratefully'] Let $X$, $X_{n}$, $n\in\mathbb{N}$ be $\mathbb{R}^{d}$-valued
random variables with $X_{n}\to X$ in law as $n\to\infty$. Let $\phi_{n}$ denote the
characteristic function of $X_{n}$. 
Assume that
\begin{equation}
\sup_{n\in\mathbb{N}}|\phi_{n}(u)|\leq \psi(u),\ u\in\mathbb{R}^{d}\mbox{ and }
\int_{\mathbb{R}^{d}}\psi(u)\, du<\infty
\end{equation}
for some measurable $\psi:\mathbb{R}^{d}\to\mathbb{R}_{+}$. 
Then $d_{TV}(X_{n},X)\to 0$, $n\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:sparse-row-sum of arXiv:2609.03264, 'Certified Spherical MUSIC for 3D Localization under Adversarial Subspace Perturbations'] The coherence row sum defined as
		\[
		\sigma_X:=
		\max_{1\le j\le s}
		\sum_{k\ne j}\abs{K_\kappa(\bm{x}_j-\bm{x}_k)}
		\]
		satisfies the bound
		\begin{equation}
			\sigma_X       \le \mu_X. 
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 6 ($\delta$-smooth margins \cite{barvinok2010does}) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] An $m\times n$ margin $(\r,\c)$ with total sum $N := \|\r\|_1 = \|\c\|_1$ is \textit{$\delta$-smooth} for some $\delta>0$ if 
		\begin{align}
			\frac{\delta N}{m} \leq \r(i) \leq \frac{N}{\delta m}, \qquad \frac{\delta N}{n} \leq \c(j) \leq \frac{N}{\delta n}
		\end{align}
		for all $i \in [m]$ and $j \in [n]$.

[Proposition of arXiv:2606.16609, 'On stability of outliers from the circular law'] Let $K$ be a compact such $K \subset \{\lvert z \lvert >1\}$. Then, a.s,
     \begin{equation*}
         \sup_{z\in K}\lvert b_N^*\mathbf{R}^2_{N}(z)c_N\lvert \rightarrow0.
     \end{equation*}

