[Lemma lemma-6.16 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Let $\Sigma_0$ be defined using $A>\sqrt{\frac2{b-1}}$ and~$\delta\in(0,\delta_0)$, for~$\delta_0$ as in Lemma~(lemma-6.14 of the paper). Given~$t>0$ and $\beta>0$ with~$0<b\theta-1<(t bA^2)^{-1}$, we have
\begin{equation}

\varrho(\boldsymbol\lambda,\boldsymbol\lambda'):=\sum_{q\ge1}(t bA)^{q-1}(b\theta-1)^{\frac{q-1}2}\bigl|\lambda(q)-\lambda'(q)\bigr|< \infty
\end{equation}
for all~$\boldsymbol\lambda,\boldsymbol\lambda'\in\Sigma_0$. Moreover, if~$t$ obeys
\begin{equation}

\frac1{\sqrt{2}}\,\frac{\sqrt{1-b^{-3}}}{(1-b^{-2})\sqrt{1+b^{-1}}}\, b^2>t A
\end{equation}
and 
\begin{equation}

\sup_{\ell\ge2}\biggl(b^{1-\ell^2}+\sum_{q=1}^{\ell-1} t^{q-\ell}b^{1-q^2}\biggr)<1,
\end{equation}
then there exist~$\delta_1>0$, $\epsilon_1>0$ and~$\eta>0$ such that
\begin{equation}

\varrho\bigl(F(\boldsymbol\lambda),F(\boldsymbol\lambda')\bigr)\le \bigl[1-\eta(b\theta-1)\bigr]\varrho(\boldsymbol\lambda,\boldsymbol\lambda')
\end{equation}
holds for all~$\boldsymbol\lambda,\boldsymbol\lambda'\in\Sigma_0$ provided $\delta<\delta_1$ and $b\theta-1\le\epsilon_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2607.18104, '2607.18104'] Let $\varepsilon>0$ and $n\in \N$. Consider the rectangles 
$$\widetilde{\mathcal{R}}^{i,j}_{\varepsilon}=\Big[\frac{j-1}{16},\frac{j+1}{16}\Big]\times [(i-1)\varepsilon,i\varepsilon]$$ 
for $j\in \Z$ and $i \in \lbr \varepsilon^{-1}\rbr$, and define the events
 \begin{equation*}
     \mathsf{E}^{i,j}_{n,\varepsilon} :=\left\{ |\Lpat(x,s;y,t)|\leq  \log^{4/3}(\varepsilon^{-1}) \text{ for all } (x,s;y,t) \in (\widetilde{\mathcal{R}}^{i,j}_{\varepsilon})^2_{\uparrow}\cap \mathcal{D}_{\varepsilon} \right\} . 
\end{equation*} 
There exist $c,C>0$ such that for all $\varepsilon>0$ and all $n\in \N$ with $n \geq \varepsilon^{-2}$, 
\begin{equation}
    \P\bigg( \mathsf{E}^{i,j}_{n,\varepsilon} \text{ holds for all } i \in \lbr \varepsilon^{-1}\rbr \text{ and } j\in \Z\bigg) \geq 1- C \varepsilon^{-1}\exp\big(-c \varepsilon^{-1/2}\big). 
\end{equation}

