[Prp 38 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] \quad\par
  \begin{itemize}
    \item [$\rm{(i)}$]Suppose that there exists a measure $\nu$ satisfying $\rm{Reg}_{s_0,s_1}$.
    Then $\rm{UP}$ implies $\rm{LRES}(1+s_0-s_1)$ with 
    $c_{\rm{LR}}=\left[\frac{4c_u(\frac{1}{4}c_{\rm{UP}}+1)^{s_1}}{c_l(\frac{1}{16}c_{\rm{UP}})^{s_0}c_{\rm{UP}}}\right]^{-1}$.
     In particular, $\rm{(A3)}$ implies $\rm{(A2)}$.
\item [$\rm{(ii)}$]The assumption $\rm{(A1)}$ implies 
\begin{align}
  p(t,x,x)\lesssim c_{\rm{A1}} t^{-\frac{s_0}{1+s_0}},\qquad t<(\diam F)^{1+s_0},\;x\in F,
\end{align}
where $c_{\rm{A1}}=1+c_l^{-1}$.
\item[$\rm{(iii)}$] The assumption $\rm{(A2)}$ implies 
\begin{align}
  c_{\rm{A2}}t^{-\frac{s_1}{(1+s_0)\theta}}\lesssim p(t,x,x),\qquad t>0,\;x\in F.
\end{align}
Moreover, if $t<\frac{D_F^{(1+s_0)\theta}}{5c_{\rm{Exit}}}$, we can take $c_{\rm{A2}}=\frac{1}{100}\left[c_u(5c_{\rm{Exit}})^{\frac{s_1}{(1+s_0)\theta}} \right]^{-1}$.
Here, $D_F$ and $c_{\rm{Exit}}$ are given by
\begin{align*}
  D_F=\frac{1}{2}\diam F\wedge (2c_{\rm{LR}}^{-1}\diam F)^{1/\theta},\qquad c_{\rm{Exit}}=\frac{4^{2+s_0}}{3c_l c_{\rm{LR}}^{1+s_0}}.
\end{align*} 
\item[$\rm{(iv)}$]The assumption $\rm{(A3)}$ implies 
\begin{align}
  c_{\rm{A3}}t^{-\frac{\beta s_1}{1+\beta}}\lesssim p(t,x,x),\qquad t>0,\;x\in F,\;\beta=\frac{1-(2+s_0)(s_0-s_1)}{s_1+2(2+s_0)(s_0-s_1)}.
\end{align}
Moreover, if $t<2\left[  \frac{C (\frac{1}{2}\diam F)^{1+\beta}}{\log 4}  \right]^{1/\beta} $, we can take $c_{\rm{A3}}=\frac{1}{4c_u}\left[ \frac{\log 4}{2^{\beta}C}\right]^{\frac{\beta s_1}{1+\beta}}$.
Here, $C$ is given by $C=\frac{c_l(c_{\rm{LR}}/4)^{1+s_0}}{4c_u c_{\rm{UR}}} \left( \frac{1}{256}\frac{[c_l(c_{\rm{LR}}/4)^{1+s_0}]^2}{c_u c_{\rm{UR}}} \right)^{\beta}$. 
\item[$\rm{(v)}$]Assume $\rm{(A3)}$. Then, for any $r<\frac{1}{2}\diam F$,
\begin{align*}
  P_x(\sigma_{B(x,r)^c}\leq t)\leq 2 \exp\left[ -\g{c}{summ}\frac{r^{1+\beta}}{t^{\beta}}\right],
\end{align*}
where $\beta=\frac{1-(2+s_0)(s_0-s_1)}{s_1+2(2+s_0)(s_0-s_1)}>0$ and $\g{c}{summ}=\frac{c_l(c_{\rm{LR}}/4)^{1+s_0}}{4c_u c_{\rm{UR}}} \left( \frac{1}{256}\frac{[c_l(c_{\rm{LR}}/4)^{1+s_0}]^2}{c_u c_{\rm{UR}}} \right)^{\beta}$.
\end{itemize}

[Defi 33 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $0\leq s< T<\infty$. 
\begin{enumerate}
    \item[(i)] A family $\left(\mu_t\right)_{t\in (s,T)}\subset \mathcal{M}(\mathbb{R}^d)$ is called a (weak, or distributional) solution on $(s,T)$ to the nonlinear Fokker-Planck equation  \begin{equation}
        \frac{d}{dt} \mu_t = {\sf L}^\ast_{t,\mu_t} \mu_t, \quad t\in (s,T),
    \end{equation}
    if $\left(\mu_t\right)_{ t\in (s,T)}$ is a Borel curve in $\mathcal{M}(\mathbb{R}^d)$,
    \begin{align}
        \scalebox{0.7}{$\bullet\quad$}
        &[0,\infty)\times\mathbb{R}^d\ni(t,x)\mapsto b(t,x,\mu_t)\in \mathbb{R}^d \mbox{ and } (t,x)\mapsto a(t,x,\mu_t)\in \mathbb{R}^{d\times d} \mbox{ are Borel measurable},\nonumber\\
        \scalebox{0.7}{$\bullet\quad$}
        &\int_{(s,T)\times B(0,R)} \|b(t,x,\mu_t)\|+\|A(t,x,\mu_t)\| \; \mu_t(dx) dt <\infty, \quad R>0 \\
        \scalebox{0.7}{$\bullet\quad$}
        &\int_{(s,T)\times \mathbb{R}^d} \left[\frac{d}{dt}f(t,x)+ {\sf L}_{t,\mu_t} f(t,x)  \right] \;\mu_t(dx) dt = 0, \quad f\in C_c^\infty \left((s,T)\times \mathbb{R}^d\right).
    \end{align}
\item[(ii)] We say that $\left(\mu_t\right)_{t\in [s,T)}\subset \mathcal{M}(\mathbb{R}^d)$ is a solution to the nonlinear Fokker-Planck equation \eqref{eq:NLFPshort} with initial condition $\mu_s$ if $\left(\mu_t\right)_{t\in (s,T)}$ is a solution on $(s,T)$ as in (i), and $\lim\limits_{t\searrow s} \mu_t=\mu_s$ weakly.
\item[(iii)] We say that $\left(\mu_t\right)_{t\in [s,T)}\subset \mathcal{M}(\mathbb{R}^d)$ is a weakly continuous solution to the nonlinear Fokker-Planck equation \eqref{eq:NLFPshort} if it is a solution on $(s,T)$ in the sense of (i), and the curve of measures $[s,T)\ni t\mapsto \mu_t\in \mathcal{M}(\mathbb{R}^d)$ is weakly continuous; this definition is obviously extended when $(\mu_t)_{t\in [s,T)]}$ is merely weakly right-continuous. 
\end{enumerate}

[Definition def:stationary solution of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] A steady state to (equation eq:weak form master trunc of the paper) is a $g \in \mathcal P ( \mathbb N^M ) $ that satisfies  
\begin{align} 
0= \sum_{ n \in \mathbb N ^M }  g ( n)  \mathcal L_s [\varphi] ( n ) +  \sum_{ n \in \mathbb N ^M }   g ( n)  \mathcal L_r   [\varphi] (n ) 
\end{align}
for every $ \varphi \in c_{ 00}( \mathbb N^M)$.

[Lemma lemma-1.4 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Let~$\beta>0$ and  let $v_\star$ be a $1$-periodic continuous function such that  (equation Eq:3.33 of the paper) holds.  Let~$\nu_\star$ be the Borel measure  on~$[0,1)$  defined by
\begin{equation}

\nu_\star(\text{\rm d}\mkern0.5mu z):=\Bigl[\int_{[0,1]}\text{\rm  e}\mkern0.7mu^{-(b+1)v_\star(z')}\text{\rm d}\mkern0.5mu z'\Bigr]^{-1}\text{\rm  e}\mkern0.7mu^{-(b+1)v_\star(z)}1_{[0,1)}(z)\text{\rm d}\mkern0.5mu z.
\end{equation}
For~$k=1,\dots,n$, abbreviate
\begin{equation}

\begin{aligned}
A_{n,k}:=(b+1)&\sup_{z\in\mathbb R}\bigl|v_\star(z)\bigr|+\sup_{z,z'\in\mathbb R}\bigl|v_k(z)-b v_{k-1}(z')\bigr|
\\&+\frac\beta2\max\{\sigma_k^{-2},1\} 
+ \frac12\log(2\pi/\beta)+\log\max\{\sigma_k,1\}
\end{aligned}
\end{equation}
and
\begin{equation}

\delta_k:=\sup_{z,z'\in\mathbb R}\Bigl| \bigl[v_k(z)-bv_{k-1}(z')\bigr] - \bigl[v_\star(z)-bv_\star(z')\bigr]\Bigr|+\log\max\{\sigma_k,\sigma_k^{-1}\}.
\end{equation}
Then for all $k=1,\dots,n$,
\begin{equation}

\begin{aligned}
\bigl\Vert P(\phi_k\text{\rm\ mod }1\in\cdot) - \nu_\star\bigr\Vert_{\text{\rm TV}}
\le \prod_{i=k}^n (1-\text{\rm  e}\mkern0.7mu^{-A_{n,i}}) +\sum_{j=k+1}^n (1-\text{\rm  e}\mkern0.7mu^{-\delta_{j-1}})\prod_{i=k}^{j-2}(1-\text{\rm  e}\mkern0.7mu^{-A_{n,i}}),
\end{aligned}
\end{equation}
 where the last product is interpreted as~$1$ when~$j=k+1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] Fix $T,\beta,\varepsilon>0$ and $\delta>0$. There exist constants
$C,c>0$, depending only on $(T,\beta,\varepsilon,\delta)$, such that the following hold.

\begin{enumerate} [(i)]
    \item For every $0\le s<t\le T$ and every $x\in E_\varepsilon$ satisfying
$|x|-\varepsilon\ge \delta$, we have
\begin{align}
\int_{\{|y|\le \varepsilon\}}
p^{T,\beta}_{s,t}(x,y)\,dy
\;\le\;
C\,e^{-c/(t-s)}\,.
\end{align}

\item For every $0\le r<s<t\le T$ and every $x\in E_\varepsilon$ with
$|x|-\varepsilon\ge \delta$, we have
\begin{align} 
\int_{\{0<|y|-\varepsilon<\delta\}}
\int_{\{|z|\le \varepsilon\}}
p^{T,\beta}_{r,s}(x,y)\,
