[Lemma 2 of arXiv:2604.15874, 'On Continuous Data Assimilation for a class of 2D and 3D stochastic non-Newtonian fluids o'] In this lemma, we collect some inequalities that will be used later on:
	\begin{itemize}
		\item  We can find a positive constant $C_{S,d}$ (\cite[Subsection 2.4]{Kesavan_1989}) such that 
		\begin{align}
			\|\w\|_{\infty} \leq C_{S,d} \|\nabla\w\|_{4}, \quad \text{	for all } \;	\w\in	\mathbb{W}_0^{1,4}(\Ocal).
		\end{align}

		\item  We can find a positive constant $C_{K,d}$ (see \cite[Theorem 2 (ii)]{DiFratta+Solombrino_Arxiv}, a Korn-type inequality) such that 
		\begin{align}
			\Vert	\nabla \w \Vert_{4}	\leq	C_{K,d}\Vert	\Arm(\w)	\Vert_4,\quad \text{	for all } \;	\w\in	\mathbb{W}_0^{1,4}(\Ocal).
		\end{align}		
		\item In view of \eqref{Sobolev-embedding3} and \eqref{Korn-ineq}, we can find a positive constant $\mathrm{N}_d$ such that
		\begin{align}
			\|\w\|_{\infty} \leq \mathrm{N}_d \|\Arm(\w)\|_{4}, \quad \text{	for all } \;	\w\in	\mathbb{W}_0^{1,4}(\Ocal).
		\end{align}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.26288, 'Muon with Finite Newton--Schulz: The Smoothing Benefit in Nonsmooth Nonconvex Optimization'] Suppose~\cref{ass:general-spectral-link} holds.
For any $t\geq1$, let $(C_s)_{s=1}^t$ be positive reals satisfying $C_{s+1}\geq\beta C_s$ for $s \in [t-1]$.
Then the online learner~\cref{eq:general-spectral-action} achieves
\begin{equation}
  \DReg_t(D)
  \leq D\left(
    \frac{rC_t\Delta(h)}{1-\beta}
    +
    \frac{1}{1-\beta}
    \sum_{s=1}^t\beta^{t-s}B_{\widetilde\Phi_{h,C_s}}(M_s\Vert M_{s-1})
  \right).

\end{equation}
If, in addition, \cref{ass:oracle} holds and $C_s=C$ for all $s\in[t]$, then
\begin{equation}
  \E[\DReg_t(D)]
  \leq D\left(
    \frac{r C \Delta(h)}{1-\beta}
    +\frac{2 \Gamma^2 \Lip(h)}{C}
  \right).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

