body:
[Proposition 141 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and the additional Assumption~\ref{Assumptions_extra}. For any $n \geq 3$, $h,h_2,\ldots,h_n \in [H]$, any $z\in \amsmathbb M_h\setminus \amsmathbb{A}_h^{\mathfrak{m}}$ and $z_i\in\amsmathbb C\setminus \amsmathbb{A}_{h_i}^{\mathfrak{m}}$ for $i \in \llbracket 2,n\rrbracket$, we have
\begin{equation}

\begin{split}
& \quad Q_{h}^{-}(z)\big\langle \bth_{h}\cdot \boldsymbol{W}_{n;\bullet,h_2,h_3,\ldots,h_n}(z,z_2,z_3,\ldots,z_n)\big\rangle \\
& = \widetilde R_{h;h_2,\ldots,h_n}(z;z_2,\ldots,z_n)+ \mathbbm{Err}_{h;h_2,\ldots,h_n}^{(1)}(z;z_2,\ldots,z_n)+ \mathbbm{Err}^{(2)}_{h;h_2,\ldots,h_n}(z;z_2,\ldots,z_n).
\end{split}
 \end{equation}
Here, $R_{h;h_2,\ldots,h_n}(z;z_2,\ldots,z_n)$ is a meromorphic function of $z\in \amsmathbb M_h$ with only possible singularities being simple poles at $z=z_i \pm \frac{1}{2\N}$ for $i \in \llbracket 2,n\rrbracket$. It is also holomorphic in $z_i\in\amsmathbb C\setminus \amsmathbb{A}^{\mathfrak{m}}_{h_i}$ for $i \in \llbracket 2,n\rrbracket$ except for the singularities we just mentioned. If $\hat a'_h \in \amsmathbb{S}_h$, then $\widetilde R_{h;h_2,\ldots,h_n}(\hat a'_h; z_2, \ldots z_n)=0$; if $\hat b'_h\in \amsmathbb{S}_h$, then $\widetilde R_{h;h_2,\ldots,h_n}(\hat b'_h; z_2,\ldots,z_n)=0$.

Besides, for any $\N$-independent $\eps > 0$, any $\N$-independent compact sets $\amsmathbb{K}_h \subset \amsmathbb{M}_h \setminus \amsmathbb{A}_{h}^{\mathfrak{m}}$ and $\amsmathbb{K}^{(i)}_{h_i} \subset \amsmathbb{C} \setminus (\amsmathbb{A}_{h_i}^{\mathfrak{m}} \cup \amsmathbb{K}_h)$ indexed by $i \in \llbracket 2,n\rrbracket$, there exists a constant $C > 0$ depending only on $\eps$, these compacts and the constants in the assumptions, such that
\[
\sup_{\substack{z\in \amsmathbb{K}_h \\ z_i \in \amsmathbb{K}_{h_i}^{(i)}}} \big|\mathbbm{Err}^{(1)}_{h;h_2,\ldots,h_n}(z;z_2,\ldots,z_n)\big|\leq C \N^{-\frac{1}{2}+\eps}.
\]
The function $\mathbbm{Err}^{(2)}_{h;h_2,\ldots,h_n}(z;z_2,\ldots,z_n)$ is a finite sum --- with a number of terms that only depends on $n$ --- of expressions of the form
  \begin{equation}

  \frac{F(z)}{\N^{q}} \cdot \prod_{i=1}^k \E\Bigg[ \prod_{m=2}^n \big(\Delta G_{h_m}(z_m)\big)^{\tilde{l}_{i,m}} \cdot \prod_{j=1}^{l_i} \big(\partial_z^{d_{i,j}} \Delta G_{g_{i,j}}(z)\big) \Bigg],
  \end{equation}
  for some $q,k \in \amsmathbb{Z}_{> 0}$, $l_1,\ldots,l_k \in \amsmathbb{Z}_{\geq 0}$, $\tilde{l}_{i,m} \in \{0,1\}$ satisfying\footnote{In fact, for each $m \in \llbracket 2,n\rrbracket$, there is exactly one $\tilde{l}_{i,m}$ equal to $1$ and the other are equal to $0$.}
  \begin{equation}

  q+1\leq \sum_{i=1}^k \bigg(l_i+\sum_{m=2}^{n} \tilde{l}_{i,m}\bigg)\leq q+n,
  \end{equation}
some function $F(z)$ holomorphic for $z \in \amsmathbb{K}_h$ and bounded from above in absolute value by $C$, and some $d_{i,j} \in \{0,1\}$ and $g_{i,j} \in [H]$.

