[Thm th 2.5 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Assume that the drift $b$ satisfies the assumption (A1). Then, for every $s\geq 0$, $x \in \mathbb{R}^d$ the SDE (equation 2.1 of the paper) has a unique continuous adapted solution $X^{s,x}= (X_t^{s,x}(\omega), t\geq s, \omega \in \Omega)$ which forms a stochastic quasi-diffeomorphisms flow. For any $p \geq 1$, there is a constant $C$ only depending on $p,d$ and $T$ such that 
				\begin{align*}
					\sup_{x\in \mathbb{R}^d}\sup_{0\leq s \leq T }\mathbb{E} \big[\sup_{ s\leq t\leq T} (|X_t^{s,x}|^p + |\nabla_x X_t^{s,x}|^p)\big] \leq C (1+\|b\|_{L^{\infty}([0,T];C_b(\mathbb{R}^d))})
				\end{align*}
				Moreover, for any $p \geq 1$ and for any $x,y \in \mathbb{R}^d$
				\begin{align*}
					\sup_{0\leq s\leq T}\mathbb{E} \big[\sup_{s\leq t\leq T} |X_t^{s,x}- X_t^{s,y}|^p \big] \leq C(1+\|b\|_{L^{\infty}([0,T];C_b(\mathbb{R}^d))}) |x-y|^p,
				\end{align*}
				and 
				\begin{align*}
					&\sup_{0\leq s\leq T}\mathbb{E} \big[\sup_{s\leq t\leq T} \|\nabla_{x}X_t^{s,x}- \nabla_{x}X_t^{s,y}\|^p \big]\\
					& \leq C \Big[ \int_{0<r\leq |x-y|} \frac{h(r)}{r}\mathrm{d}r + h(|x-y|) +|x-y| \int_{|x-y|<r\leq r_0} \frac{h(r)}{r^2}\mathrm{d}r  \Big]^p 1_{\{|x-y|<r_0\}}+ C |x-y|^p.
				\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 (Continuous-time commute and target identities) of arXiv:2607.13183, '2607.13183'] Let $G$ be a finite connected multigraph, viewed as a unit-conductance
network under the conventions above. Let $(X_t)_{t\ge0}$ be a continuous-time simple
random walk with total jump rate $1$. Then, for all vertices $u,v$,
\begin{equation}
        \E_u\tau_v+\E_v\tau_u=2|E(G)|\Reff(u,v).
\end{equation}
Consequently,
\begin{equation}
        \Kemeny(G) = \sum_v\pi(v)\E_\pi\tau_v
        =|E(G)|\sum_{u,v}\pi(u)\pi(v)\Reff(u,v).
\end{equation}

[Theorem 5 (Exact $\MAX_5$ identity) of arXiv:2608.25221, 'Representing MAX functions using two-hidden-layer ReLU networks'] We have the following identity.
\begin{align}
2\MAX_5={}&-\frac25 G_{\mathcal O[P_0]}
+\frac1{30} G_{\mathcal O[P_3]}
+\frac1{120} G_{\mathcal O[P_{16}]}
+\frac1{60} G_{\mathcal O[P_{22}]}\notag\\
&+\frac1{60} G_{\mathcal O[P_{37}]}
-\frac1{60} G_{\mathcal O[P_{45}]}
-\frac1{60} G_{\mathcal O[P_{81}]},
\end{align} where
\begin{align*}
 P_0&=[11,11\mid 11,11],\\
 P_3&=[11,11\mid 11,23],\\
 P_{16}&=[11,11\mid 23,45],\\
 P_{22}&=[11,12\mid 11,34],\\
 P_{37}&=[11,12\mid 13,45],\\
 P_{45}&=[11,12\mid 23,45],\\
 P_{81}&=[11,23\mid 12,45].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

