[Definition def:R of arXiv:2601.20502, 'Optimal matching under size priority'] Take $\mu_v \in \mathcal{L}(\mathcal{G}^{\star})$ such that $0<m := \int_{\mathcal G^{\star}} \deg (o) \, \mathrm{d} \mu_v(G,o) < \infty$. Let $R(\mu_v) \in \mathcal{L}(\hat{\mathcal{G}}^{\star})$  be the unique measure such that,
    for every $f$ measurable from $\hat{\mathcal{G}}^{\star}$ to $\mathbb{R}_+$,
\[
\int_{\hat{\mathcal{G}}^{\star}}f(G,(o_-,o_+)) \, \mathrm{d} R(\mu_v)(G,(o_-,o_+)) =
\int_{\mathcal{G}*} 
 \frac{1}{m} 
\sum_{u \sim o} f(G,o,u) \, \mathrm{d} \mu_v(G,o).
\]

[Lemma le:estforpsi of arXiv:2411.16913, 'Entropies of the Poisson distribution as functions of intensity: ``normal'' and ``anomalou'] Let $\gamma_*:=\exp\left(-\dfrac{\pi}{e}\bigl(e^{\frac16}-1\bigr)\right)\approx 0.811$. 
For each $\alpha>0$, $\alpha\neq1$ and each $\gamma\in(\gamma_*,1)$, we define
\begin{equation*}
    D(\alpha,\gamma):=\left(\frac{\pi|\alpha-1|}{-e\alpha\log\gamma}\right) ^{\frac{|\alpha-1|}{2}}.
\end{equation*}
Then
\begin{enumerate}[label=\arabic*)]
    \item for $\alpha\in(0,1)$,
    \begin{equation*}

        \psi(\alpha,\lambda) < C_1(\alpha,\gamma)e^{-\alpha\lambda}E_\alpha\left(\Bigl(\dfrac{\alpha}{\gamma}\lambda\Bigr)^{\alpha } \right), \quad\lambda>0,
    \end{equation*}
where
    \begin{equation*}

        C_1(\alpha,\gamma):=\sqrt{\alpha}e^{\frac{1}{12\alpha}} D(\alpha,\gamma);
    \end{equation*}
\item for $\alpha>1$, 
\begin{equation*}    
    \psi(\alpha,\lambda)> 
C_2(\alpha,\gamma)e^{-\alpha\lambda}E_\alpha\left(\bigl(\alpha\gamma\lambda\bigr)^{\alpha } \right),    
\end{equation*}
where
    \begin{equation*}

        C_2(\alpha,\gamma) := \sqrt{\alpha} e^{-\frac{\alpha }{12}}\frac{1}{D(\alpha,\gamma)}.
    \end{equation*}
\end{enumerate}

