[Theorem thm:global_nonasymptotic of arXiv:2608.27313, 'A Finite Sample Analysis for Quantile Temporal Difference Learning in Distributional Reinf'] Suppose $\bm\theta^{(0)}\in[0,(1-\gamma)^{-1}]^{{\mathcal{S}}\times[m]}$ and $cC_0\le1$. For every $\delta\in(0,1)$ and $T\ge T_0(\delta)$, where the explicit threshold $T_0(\delta)$ is given in Equation~(equation eq:T0_conditions of the paper), with probability at least $1-\delta$,
\begin{equation}
\begin{aligned}
    \norm{\bm\theta^{(T)}-\bm\theta_m}_\infty
    \lesssim{}&
    r_{\mathrm{out}}
    \exp\left\{-\frac{c\lambda_mT^{1-a}}{C}\right\}
    +\varepsilon_T(\delta)
    +\frac{L(1+\gamma)^2}{\lambda_m}\varepsilon_T^2(\delta),
\end{aligned}
\end{equation}
where $C$ is a universal constant. In particular, the definition of $T_0(\delta)$ ensures that the last term is absorbed by $\varepsilon_T(\delta)$, and hence
\begin{equation}
    \norm{\bm\theta^{(T)}-\bm\theta_m}_\infty
    \lesssim
    r_{\mathrm{out}}
    \exp\left\{-\frac{c\lambda_mT^{1-a}}{C}\right\}
    +\sqrt{\frac{cv_m\ell_T(\delta)}{(1-\gamma)T^a}}
    +\frac{c\ell_T(\delta)}{T^a}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 4 of arXiv:2608.26642, '2608.26642'] Let $f\in C(\R)$. The following assertions are equivalent:
\begin{enumerate}
\item There exists a constant $C$ such that the function $f$ satisfies the Fredholm equation
\begin{align}

f(x)
=C+\int_K f(y)h(x-y)\,\mu(dy)\qquad \text{for}\ x\in \R,
\end{align}
with the normalization condition
\begin{align}

  \mu[f]=1.
\end{align}
\item The function $f$ satisfies the growth condition
\begin{align}

f-h\in C_b(\R)
\end{align}
(which implies $f\in \mathscr{A}_0$) and the Sturm--Liouville equation
\begin{align}

\mathscr{L}f
=f\cdot \mu,
\end{align}
that is,
\begin{align}
\langle \mathscr{L} f,g\rangle =\int_\R g(x) f(x)\,\mu(dx)\qquad \text{for}\ g\in C_c^\infty(\R).
\end{align}
\end{enumerate}
If either, and hence both, of these conditions holds, then we have $f=\varphi^\mu.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

