[Lemma 14 of arXiv:2609.02423, '2609.02423'] Let $b\in C^\infty(\R)$ be bounded with $b'\in\Sscr(\R)$.  On
Schwartz functions,
\begin{equation}
 i[-D_x|D_x|,b]
 =-\bigl(b'|D_x|+|D_x|b'\bigr)+\mathcal R_b,
\end{equation}
where the Fourier kernel of the remainder is
\begin{equation}
 \widehat{\mathcal R_b f}(\xi)
 =i\int_\R
 \bigl(\xi|\xi'|-\xi'|\xi|\bigr)
 \widehat b(\xi-\xi')\widehat f(\xi')\dd\xi'.
\end{equation}
The kernel vanishes when $\xi$ and $\xi'$ have the same sign, and
\begin{equation}
 \norm{\mathcal R_b}_{L^2\to L^2}
 \le \frac12\norm{\widehat{b''}}_{L^1}.
\end{equation}
For $b(x)=a(\lambda(x-x_0)/R)$, with $a$ defined by
\eqref{eq:aprime-square}, the remainder is supported in
\begin{equation}
 |\xi-\xi'|\lesssim \lambda/R,
 \qquad
 \sgn\xi\ne\sgn\xi',
 \qquad
 \max\{|\xi|,|\xi'|\}\lesssim\lambda/R.
\end{equation}
Moreover, for every Hilbert-valued $f$,
\begin{align}
 |\ip{\mathcal R_bf}{f}|
 \lesssim{}&\left(\frac\lambda R\right)^2
 \sum_{d\in\Z}\langle d\rangle^{-2}
 \int_\R
 a'\left(\frac{\lambda(x-x_0-dR/\lambda)}R\right)
 \norm{P^x_{\lesssim\lambda/R}f(x)}_H^2\dd x.
\end{align}

[Definition def: FITstates of arXiv:2509.23069, 'Every cutoff profile is possible'] Let $(k, \boldsymbol{\ell},\boldsymbol{\rho}) \in {\ensuremath{\mathcal P}} $. The fruit-inosculated-tree state space with parameters $(k, \boldsymbol{\ell},\boldsymbol{\rho})$, denoted by $\FITStates(k, \boldsymbol{\ell},\boldsymbol{\rho})$ is the set of the following states: 
\begin{itemize}
    \item $x_{j}$ for $0\leq j \leq \ell_0$,
    \item $y_{j}^i$ for $1\leq i \leq k$ and $\ell_0 + 1 \leq j \leq \ell_0 + \ell_i - 1$,
    \item $z$.
\end{itemize}

[Thm 85 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For the generation $m=0$ and $n\geq 1$ odd,
\begin{displaymath}
\psi^{\rm gen}_{n,m=0} = 
\sum_{j=0}^{+\infty}
\Big(
\sigma_{m=0,j}
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{0}}^{k}\psi_{n-2k,m=0,j}
\Big),
\end{displaymath}
where the infinite sum in $j$ converges in $L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ for $\eta>0$.
Moreover,
\begin{displaymath}
\E\Big[\Vert \psi^{\rm gen}_{n,m=0}\Vert_{H^{-\eta}(\C)}^{2}\Big] = 
\sum_{j=0}^{+\infty}
\E\Big[
\Big\Vert
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{0}}^{k}\psi_{n-2k,m=0,j}
\Big\Vert_{H^{-\eta}(\C)}^{2}
\Big].
\end{displaymath}
For $n\geq 2$ even,
\begin{multline*}
\psi^{\rm gen}_{n,m=0} =
\\
\sum_{j=0}^{+\infty}
\Big(
\Big(
\sum_{0\leq k < \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{0}}^{k}\psi_{n-2k,m=0,j}
\Big)
+
(-1)^{n/2} \dfrac{n!}{2^{n/2} (n/2)! }
\ind_{\inter(\Gamma_{m=0,j})}
V_{A^{\rm gen}_{0}}^{n/2}
\Big).
\end{multline*}
For the generations $m\geq 1$ and $n\geq 1$ odd,
\begin{multline*}
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
=
\\
\sum_{j=0}^{+\infty}
\Big(
\sigma_{m,j}
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{m}}^{k}\psi_{n-2k,m,j}
\Big),
\end{multline*}
and
\begin{multline*}
\E\Big[
\Big\Vert
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
\Big\Vert_{H^{-\eta}(\C)}^{2}
\Big]
=
\\
\sum_{j=0}^{+\infty}
\E\Big[
\Big\Vert
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{m}}^{k}\psi_{n-2k,m,j}
\Big)
\Big\Vert_{H^{-\eta}(\C)}^{2}
\Big].
\end{multline*}
For $n\geq 2$ even,
\begin{multline*}
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
=
\\
\sum_{j=0}^{+\infty}
\Big(
\Big(
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{m}}^{k}\psi_{n-2k,j}
\Big)
+
\ind_{\inter(\Gamma_{m,j})}
(-1)^{n/2} \dfrac{n!}{2^{n/2} (n/2)! }
(V_{A^{\rm gen}_{m}}^{n/2} - V_{A^{\rm gen, +}_{m-1}}^{n/2})
\Big)
.
\end{multline*}

[Proposition prop convergence of deterministic of arXiv:2603.09008, 'On the statistics of random-to-top shuffles'] Let $\pi$ be a uniformly random permutation of $[n]$ and let $0<a\leq 1$ be a constant. Then, we have
    \begin{equation}

    L_{a,n}:=n-\max_{1\leq i\leq \lfloor an \rfloor} (\pi(i))+\sum_{i=1}^{\lfloor an \rfloor} \1(\pi(i)=i)\Rightarrow_d X+Y
    \end{equation}
    where $X$ and $Y$ are independent random variables with $X\sim\operatorname{Poisson}(a)$ and $Y$ is a geometric random variable with parameter equal to $a$ and $P(Y=k)=a(1-a)^k$. If $a_n\in(0,1]$ is a sequence with $a_n\to a\in(0,1]$ as $n\to\infty$ such that for some $\alpha>0$, we have $a_n>\alpha>0$ for all $n$, then $L_{a_n,n}$ has the same limiting distribution as $L_{a,n}$ in equation $(equation convergence of deterministic model of the paper)$.

