[Lemma 56 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $A\in\mathbb C^{N\times N}$ and let $X(z)$ and $Y(z)$ be respectively $\mathbb C^{N\times m}$-valued and $\mathbb C^{m\times m}$-valued, and analytic on the spectrum
  of $A$. Then, for $a\in\sigma(A)$,
  \begin{equation}
    {\rm Res}_{z=a}(zI_N-A)^{-1}
    X(z)Y(z)={\rm Res}_{z=a}(zI_N-A)^{-1}PY(z)
\end{equation}
where
\begin{equation}
P={\rm Res}_{z=a}(zI_N-A)^{-1}X(z).
\end{equation}

[Theorem thm:mass-speed of arXiv:2509.08430, 'One-dimensional particle clouds with elastic collisions'] For the process $G$ as defined at~(equation eq:centre-of-mass of the paper), it holds that
\begin{equation}

  \Exp [ G(t+h) - G(t) \mid X(t) = x ] = -h U_N/M_N, \text{ for all $t, h \in {\mathbb R}_+$ and all } x \in {\mathbb X}_N. \end{equation}
Moreover, $\lim_{t \to \infty} t^{-1} G(t) = -U_N/M_N$, a.s. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 (Chain rule) of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Let $\mathbf{J} \in\cC^k(X_1,\dots,X_d)$ and $\mathbf{f}_1,\dots,\mathbf{f}_d\in\cC^k(\cB)_{\sa}$, and write $\mathbf{f} \coloneqq (\mathbf{f}_1,\ldots,\mathbf{f}_d)$. Let $\mathbf{g} \coloneqq \mathbf{J} \circ \mathbf{f}$ be defined by
\begin{align*}
    g^{\cA} &\coloneqq J^{\cA} \circ f^{\cA} = \big(x \mapsto J^{\cA}(f_1^{\cA}(x),\ldots,f_d^{\cA}(x))\big),
\end{align*}
then $\mathbf{J} \circ \mathbf{f} \in \cC^k(\cB)$.\footnote{More precisely, if $(P_n(X_1,\ldots,X_d))_{n \in \N}$ is a sequence of trace polynomials converging in $\cC^k(X_1,\ldots,X_d)$ to $\mathbf{J}$ and $(Q_n(X)) = (Q_{1,n}(X),\ldots,Q_{d,n}(X))_{n \in \N}$ is a sequence of $d$-tuples of self-adjoint trace polynomials converging in $\cC^k(\cB)_{\sa}^d$ to $\mathbf{f}$, then $(P_n(Q_n(X)))_{n \in \N}$ converges in $\cC^k(\cB)$ to a limit, $\mathbf{J} \circ \mathbf{f}$, independent of the choice of approximating sequences.}
Besides, if we define
$$ \Lambda^s_R(\cf) = \sup_{\substack{1\leq i_1,\dots,i_m\leq d \\ s_1+\dots+s_m = s \\ s_l\geq 1,\ m\geq 2 }}\ \prod_{l=1}^m\ \norm{\cf_{i_l}}_{s_l,c,R}\ ,\quad\quad S\coloneqq \max_{1\leq i\leq d} \norm{\cf_i}_{0,c,R}, $$
then there exists a constant $C_k$ such that, if $j_0>0$, $j\coloneqq j_0+\dots+j_n$,
\begin{align}

    &\norm{\widetilde{\partial}^{(j_n)}\circ\cdots\circ\widetilde{\partial}^{(j_1)}\circ\partial^{(j_0)}\mathbf{g} - \sum_{i=1}^d  (\partial_i \mathbf{J})\circ\cf\ \sh_1 \left(\widetilde{\partial}^{(j_n)}\circ\cdots\circ\widetilde{\partial}^{(j_1)}\circ\partial^{(j_0)}\mathbf{f_i} \right)}_{0,c,R} \\
    &\leq C_k\times \Lambda^j_R(\cf) \times \sup_{s\in [2, j]} \norm{\mathbf{J}}_{s,S}, \nonumber
\end{align}
and if $j_0=0$,
\begin{align}

    &\Bigg\| \widetilde{\partial}^{(j_n)}\circ\cdots\circ\widetilde{\partial}^{(j_1)}\mathbf{g} - \sum_{i=1}^d  (\partial_i \mathbf{J})\circ\cf\ \sh_2 \left(\widetilde{\partial}^{(j_n)}\circ\cdots\circ\widetilde{\partial}^{(j_1)}\mathbf{f_i} \right) - \sum_{i=1}^d  (\widetilde{\partial}_i \mathbf{J} )\circ\cf\ \sh_3 \left(\widetilde{\partial}^{(j_n)}\circ\cdots\circ\widetilde{\partial}^{(j_1)} \mathbf{f_i} \right) \Bigg\|_{0,c,R} \\

    &\leq C_k\times \Bigg( \Lambda_R^j(\cf) \times \sup_{s\in [2, j]} \norm{\mathbf{J}}_{s,S} + \sup_i\ \norm{\widetilde{\partial}^{(j_n)}\circ\cdots\circ\widetilde{\partial}^{(j_2)} \circ \partial^{(j_1)}\mathbf{f_i} }_{0,c,R} \times \sup_i\ \norm{\widetilde{\partial}_i\mathbf{J}}_{0,S}\Bigg). \nonumber
\end{align}
Where if we set,
$$ \cX = A\otimes B \otimes \tr(R_1)\otimes \cdots\otimes \tr(R_m), $$
$$ \cY = h_1\otimes\dots\otimes h_{k-1}\otimes C_1\otimes \dots\otimes C_k \otimes \tr(R_{m+1})\otimes \cdots\otimes \tr(R_n), $$
then
\begin{align*}
    &\cX\sh_1\cY = h_1\otimes\dots\otimes h_{k-1}\otimes AC_1\otimes C_2\otimes\dots\otimes C_{k-1}\otimes C_k B \otimes \tr(R_1)\otimes \cdots\otimes \tr(R_n), \\
    &\cX\sh_2\cY = h_1\otimes\dots\otimes h_{k-1}\otimes C_1\otimes \dots\otimes C_{k-1}\otimes A C_k B \otimes \tr(R_1)\otimes \cdots\otimes \tr(R_n), \\
    &\cX\sh_3\cY = h_1\otimes\dots\otimes h_{k-1}\otimes C_1\otimes \dots\otimes C_{k-1} \otimes B \otimes \tr(AC_k) \otimes \tr(R_1)\otimes \cdots\otimes \tr(R_n).

\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

