[Lemma 11 (Stability lemma) of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] There exist $\delta_0,C>0$ depending only on $p>2$ such that the following bounds hold true for any $\alpha \in [0,1]$. 
		Let 
		\begin{equation} 
			\cR \coloneqq [-1-\delta_0,1+\delta_0]+\ii(0,\delta_0] 
			\qquad \text{and} \qquad 
			\cT \coloneqq \{ x + \ii y \in \cR : \abs{x} \leq 1+y \}.
		\end{equation}
		Let $\zeta\in \C$, $z\in\cR$ and $u\in \C$ such that
		\[
		u^2+\frac{g_\alpha(z)}{z}u+\frac{h_\alpha(z)}{z}=\zeta.
		\]
		Then, recalling \eqref{def:s_tilde},
		\begin{equation}

			\abs{u-s_{V_\alpha}(z)} \wedge \abs{u-\widetilde{s}_{V_\alpha}(z)} 
			\leq C\left( \frac{\abs{\zeta}}{\abs{b(z)}} \wedge  \abs{\zeta}^{1/2} \right).
		\end{equation}
		If $\im(u)>0$, then
		\begin{equation}

			\abs{\im(u-s_{V_\alpha}(z))}
			\leq C\left( \abs{u-s_{V_\alpha}(z)} \wedge \abs{u-\widetilde{s}_{V_\alpha}(z)} \right).
		\end{equation}
		If $\im(u)>0$ and $z \in \cT$, then
		\begin{equation}

			\abs{u-s_{V_\alpha}(z)} 
			\leq C\left( \frac{\abs{\zeta}}{\abs{b(z)}} \wedge \abs{\zeta}^{1/2} \right).
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm: Wasserstein-$p$ distance JSQ of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{(Wasserstein-$p$ distance for JSQ)} In the heavily overloaded regime (ass:heavy_overload of the paper), with $\gamma\leq\gamma_1$ (equation eq: gamma assumption for JSQ W-p of the paper), the Wasserstein-$p$ distance between law $\mathcal{L}(\tilde{q}_{\Sigma})$ and standard normal distribution $\mathcal{L}(Z):=\mathcal{N}(0,1)$ is bounded in:







    \begin{subnumcases}{\mathcal{W}_p(\mathcal{L}(\tilde{q}_{\Sigma}), \mathcal{L}(Z)) \leq E'_{\lambda,\mu,n} \cdot}
     p\sqrt{\gamma}, & if $p \in (1, 1/\gamma^{\delta}]$ \\
     \sqrt{p} , & if $p \in [1/\gamma^{1/2-\alpha}, 1/\gamma)$ \\
     \frac{p\sqrt{\gamma}}{\log(1+\frac{n\gamma}{\lambda}p)}, & if $p \in [1/\gamma, \infty)$ 
    \end{subnumcases}
    \begin{subnumcases}{\mathcal{W}_p(\mathcal{L}(\tilde{q}_{\Sigma}), \mathcal{L}(Z)) \geq}
        C_{OT,\lambda,\mu}' \cdot \sqrt{\gamma} \exp\left(-\frac{\lambda }{p\gamma}\right), & $p \in [1, D_{5,\lambda,\mu}/\gamma]$\\
        D_{4,\lambda,\mu}' \cdot \frac{p\sqrt{\gamma}}{\log(1+\gamma p/\lambda)} & $p \in [D_{5,\lambda,\mu}/\gamma, \infty)$
    \end{subnumcases}
    Where $\delta \in(0,1/2-\alpha)$ is any small constant, and all constants independent of $p,\gamma$, with closed forms in (equation eq: D_4, lambda, mu SSQ of the paper), (equation eq: constants for Wasserstein-$p$ JSQ of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2606.18866, 'Cram\'er-Type Moderate Deviations for Engel's Series via a Martingale Approach'] For every $n\ge2$, $j\ge2$, and $t\ge0$,
\begin{equation}
 \Pp(\log r_n>t\mid q_{n-1}=j)
 =\Pp(q_n\ge\lfloor je^t\rfloor+1\mid q_{n-1}=j)
 =\frac{j-1}{\lfloor je^t\rfloor}.
\end{equation}
Consequently,
\begin{equation}
 \left(1-\frac1j\right)e^{-t}
 \le \Pp(\log r_n>t\mid q_{n-1}=j)
 \le\frac{j-1}{je^t-1}
 \le2e^{-t}.
\end{equation}
Moreover, there is an absolute constant $C>0$ such that
\begin{equation}
 \left|\Pp(\log r_n>t\mid q_{n-1}=j)-e^{-t}\right|
 \le\frac{C}{j}e^{-t}.
\end{equation}

