[Lemma lem:merge_term_asymptotics of arXiv:2508.18809, '{\bf Critical long-range percolation III: The upper critical dimension}'] If $d\geq 3\alpha$ and $\alpha<2$ then 
\begin{multline*}
\mathbb E_r \sum_{y\in \mathbb Z^d}\sum_{x\in K} \sum_{z\in K_y} \mathbbm{1}(0\nleftrightarrow y, \|x-z\| \leq r) |K||K_y| P(y)
\\= \left[\int_{\mathbb R^d} [\kappa^{*4} * \mathbbm{1}_B](y) P(y) \dif y \pm o(1)\right] |B_r| V_r^2 r^{\deg(P)}(\mathbb E_r|K|)^6
\end{multline*}
and
\begin{multline*}
\mathbb E_r\sum_{y\in \mathbb Z^d} \sum_{x\in K} \sum_{z\in K_y} \mathbbm{1}(0\nleftrightarrow y, \|x-z\| \leq r) |K||K_y|^2 P(y)
\\= \left[\int_{\mathbb R^d} [(2\kappa^{*5}+\kappa^{*4}) * \mathbbm{1}_B](y) P(y) \dif y \pm o(1)\right] |B_r| V_r^3 r^{\deg(P)}(\mathbb E_r|K|)^8
\end{multline*}
as $r\to \infty$ for each monomial $P:\mathbb R^d\to\mathbb R$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2608.10415, 'Continuous random variables'] The geometric law $c_p$ has the following properties:
\begin{enumerate}
\item The mean is $E=\frac{(1-p)}{p}$.

\item The variance is $V=\frac{(1-p)}{p^2}$.
\end{enumerate}

[Lemma hNtNlmt of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Following hold for ${\sf h}_N$ when $\textbf{a}^{(\emptyset)} = 0$.

\begin{enumerate}
\item $\lim_{N\rightarrow \infty} ({\sf h}_N,   w_N {\sf h}_N) = (f - \Phi(f) , (-\Delta)^{-1+\eta/2} (f- \Phi(f))) \times \begin{cases}
(1 + \bar{\textbf{a}}_{\Delta})^{-1} &(\eta=0) \\
1 & (\eta >0) 
\end{cases}$.
\item For any $r \in [0,\infty]$,  there is a constant $C_n >0$ such that
\begin{align}
	\norm{\nabla^n \tilde{\sf h}_N}_{\ell^{2+r}} \le C_{n} L^{(\frac{2-\eta}{2} - n)N} L^{-\frac{d r}{2(2 +r)} N} \norm{\nabla^n f}_{\ell^{\infty}}  
\end{align}
uniformly in $N$,  with $\frac{r}{2+r} = 1$ when $r = \infty$.
\end{enumerate}

