[Theorem THM:1 of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Let $s<-\frac 12$, $D>0$, and let $F$ be a bounded and continuous function on $H^{s}_\mu(\mathbb{R})$. Then, we have
\begin{align}
\int F\big(L(\phi-\pi_L(\phi))\big) \rho_L(d\phi)  \longrightarrow \int F(\phi) \nu(d\phi)

\end{align}

\noindent
as $L \to \infty$. Here, $\pi_L$ is the projection map in $H^1(\mathbb{T}_L)$ onto the soliton manifold $\mathcal{M}_L$ 
\begin{align}
\mathcal{M}_L:=\big\{ e^{i \theta} \eta(\cdot-x_0) LQ(L(\cdot-x_0)): \theta \in [0,2\pi], \; x_0 \in \mathbb{T}_L  \big\}, 

\end{align}

\noindent 
defined in (equation project of the paper), where $\eta$ is the cutoff function\footnote{Here, the cutoff function is necessary to ensure that the solitons preserve the periodic boundary condition and that the manifold remains smooth.} in (equation cutoffeta of the paper),  and $\nu$ is the white noise measure on $H^s_\mu(\mathbb{R})$ 
\begin{align*}
\nu(d\phi)=Z^{-1} e^{-\frac{1}{2} \int_{\mathbb{R}} |\phi|^2 dx } \prod_{x\in \mathbb{R}} d\phi(x).
\end{align*}

\noindent
Hence, the scaled field under the Gibbs measure $\rho_L$ converges in distribution to white noise in the infinite volume limit. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop_new_QM of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, there exist constants $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d)>
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d)>0$ such that the following hold. When $3\le d\le 5$, for any $N\ge 1$, $A_1,D_1\subset  \widetilde{B}(\ensuremath{c_{\ref*{const_new_QM2}}}N)$ and $A_2,D_2\subset [\widetilde{B}(\ensuremath{C_{\ref*{const_new_QM1}}}N)]^c$,
		\begin{equation}
	\begin{split}
			\mathbb{P}^{D_1\cup D_2}\big( A_1\xleftrightarrow{\ge 0} A_2\big) 
			 \asymp  \mathbb{P}^{D_1}\big( A_1 \xleftrightarrow{\ge 0} \partial B(N) \big) \mathbb{P}^{D_2}\big( A_2 \xleftrightarrow{\ge 0} \partial B(N) \big).	
			 \end{split}
	\end{equation}
When $d=6$, for any $N\ge 1$, $A_1,D_1\subset  \widetilde{B}(\ensuremath{c_{\ref*{const_new_QM2}}}N^{1-\varsigma(N)})$ and $A_2,D_2\subset [\widetilde{B}(\ensuremath{C_{\ref*{const_new_QM1}}}N^{1+\varsigma(N)})]^c$,
\begin{equation}
N^{-10\varsigma(N)}	\lesssim \frac{\mathbb{P}^{D_1\cup D_2}\big( A_1\xleftrightarrow{\ge 0} A_2\big)}{\mathbb{P}^{D_1}\big( A_1 \xleftrightarrow{\ge 0} \partial B(N) \big) \mathbb{P}^{D_2}\big( A_2 \xleftrightarrow{\ge 0} \partial B(N) \big)}\lesssim N^{\varsigma(N)}.
\end{equation}
When $d\ge 7$, for any $N\ge 1$, $A_1,D_1\subset  \widetilde{B}(\ensuremath{c_{\ref*{const_new_QM2}}}N^{\frac{2}{d-4}})$ and $A_2,D_2\subset [\widetilde{B}(\ensuremath{C_{\ref*{const_new_QM1}}}N^{\frac{d-4}{2}})]^c$,
	\begin{equation}
	\begin{split}
			\mathbb{P}^{D_1\cup D_2}\big( A_1\xleftrightarrow{\ge 0} A_2\big)
			 \asymp  N^{6-d} \mathbb{P}^{D_1}\big( A_1 \xleftrightarrow{\ge 0} \partial B(N) \big) \mathbb{P}^{D_2}\big( A_2 \xleftrightarrow{\ge 0} \partial B(N) \big).	
			 \end{split}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 128 (Cutoff tails for the integrated first-chaos kernel) of arXiv:2607.10813, '2607.10813'] Fix the projection flags
$(\epsilon_{\mathrm P},\epsilon_{\mathrm O})\in\{0,1\}^2$.  Let
$\mathcal K_{a,>\Lambda}$ denote any term in the difference between the
cutoff kernel in \eqref{eq:cubic-integrated-kernel} and its limiting kernel,
after the finite-product telescope of
\cref{lem:finite-product-cutoff}.  Put
\[
 N:=\langle\xi\rangle,
 \qquad
 L_\Lambda(N):=\max\{N,c\Lambda\},
\]
where $c>0$ depends only on the cutoff plateau and the resonant support.  For
every sufficiently small $\varepsilon>0$,
\begin{equation}
 \sup_{0\le u\le t\le T}
 |\mathcal K_{a,>\Lambda}(\xi;t,u)|
 \lesssim_{T,\varepsilon}
 N^{-1+\beta_{a^\perp}}
 L_\Lambda(N)^{-1+2\beta_a+\varepsilon}.
\end{equation}
Let $0<\theta<1/2$ and assume
$2\beta_a+\theta+\varepsilon<1$.  Then
\begin{align}
 \sup_{0\le u\le t}
 |\mathcal K_{a,>\Lambda}(\xi;t',u)
  -\mathcal K_{a,>\Lambda}(\xi;t,u)|
 &\lesssim_{T,\varepsilon,\theta}
 |t'-t|^\theta
 N^{-1+\beta_{a^\perp}}
 L_\Lambda(N)^{-1+2\beta_a+\theta+\varepsilon},
 \\
 \sup_{t<u\le t'}
 |\mathcal K_{a,>\Lambda}(\xi;t',u)|
 &\lesssim_{T,\varepsilon,\theta}
 |t'-t|^\theta
 N^{-1+\beta_{a^\perp}}
 L_\Lambda(N)^{-1+2\beta_a+\theta+\varepsilon}.

\end{align}
Consequently the static and increment covariance-density differences admit
majorants
\begin{align}
 q_{a,>\Lambda}^{(1)}(t,\xi)
 &\lesssim_{T,\varepsilon}
 N^{-2+2\beta_{a^\perp}}
 L_\Lambda(N)^{-2+4\beta_a+\varepsilon},
 \\
 \frac{q_{a,>\Lambda}^{(1),\Delta}(t,t';\xi)}
 {|t-t'|^{2\theta}}
 &\lesssim_{T,\varepsilon,\theta}
 N^{-2+2\beta_{a^\perp}}
 L_\Lambda(N)^{-2+4\beta_a+2\theta+\varepsilon}.

\end{align}
The bounds are uniform over the four projection conventions.

[Proposition prop-Ito integral of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Let $C \in {
\mathscr B}(\mathbb R^d \setminus \{ 0\})$ and consider    a ${
\mathscr P} \otimes {
\mathscr B}(C)/{
\mathscr B}(\mathbb R^d)$-measurable mapping
 \begin{equation}
 F :
 [0, \infty) \times \Omega\times C  \to \mathbb R^d.
 \end{equation}
  If
  \begin{equation}
  \mathbb{E} \int_0^T \int_C |F(s,z )\vert^2 \nu (dz ) ds< \infty, \mbox{ for every }T>0,
  \end{equation}
    then one can define
  the stochastic integral
 \begin{equation}
 Z_t =  \int_0^t \int_{C} F(s,z)  \tilde{\mu}(ds, dz), \;\; t \in [0,\infty),
 \end{equation}
and  the process $Z = (Z_t)_{t\geq0}$ is an $L^2$-martingale with a c\`adl\`ag modification. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 5 of arXiv:2609.02334, '2609.02334'] Let $G$ be a simple graph of maximum degree at most $\Delta$ and let $t$ be the distance in $G$ between two vertices $x,y$. Then
\begin{align*}
n_G(x,y) \le
\begin{cases}
1, & \text{if $t=1$,} \\[2mm]
\Delta, & \text{if $t = 2$,} \\[2mm]
\Delta(\Delta - 1)\left(\a\b\right)^{(t-3)/2}, & \text{if $t\ge 3$ is odd,} \\[2mm]
2(\Delta -1)\left(\a\b\right)^{(t-2)/2}, & \text{if $t\ge 4$ is even.}
\end{cases}
\end{align*}
These upper bounds are sharp. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is $r$-demicontinuous;
\item[(ii)] The common order and uo adherence of $\Ba_{F}$ is contained in $r\Ba_{F}$;
\item[(iii)] Whenever $f_{p}\too f$, then $\|f\|\le r\liminf\|f_{p}\|$;
\item[(iii')] Whenever $f_{p}\touo f$, then $\|f\|\le r\liminf\|f_{p}\|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm:time_const of arXiv:2411.13030, 'Classification of the limit shape for 1+1-dimensional FPP'] Let $G$ be any probability measure on $[0, \infty)$. Then there exists a convex, deterministic function $\Lambda: [0,\infty) \to [0, \infty)$ depending on $G$ such that 
\begin{equation}
\Lambda(\nu)=\lim_{n\to \infty} \frac 1 n T((0,0),(n,{\lceil v n \rceil})).
\end{equation}
almost surely and in $L^1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 31 of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] Suppose $n \geq 1$ and $\Lambda \supset \Lambda_{2n}$. Let $\mu$ be a measure on $(\mathbb{R}^{+})^{\Lambda} \times \{0, 1\}^{\overline{E}(\Lambda)}$ that satisfies weak monotonicity and \eqref{eq: zero conditioning}. Then
    \begin{align*}
        \sum_{e \in \overline{E}(\Lambda)} \mathrm{Cov}_\mu(\mathbbm{1}_{\{o \longleftrightarrow \partial \Lambda_n\}}, \omega_{e}) \geq \frac{n \min_{x \in \Lambda_n} \mu[C_x]}{(4D+6) Q_n} \mu[o \longleftrightarrow \partial \Lambda_n] (1 - \mu[o \longleftrightarrow \partial \Lambda_n] ),
    \end{align*}
    where $Q_n \coloneq \max_{x \in \Lambda_n} \sum_{k=0}^{n-1} \mu[x \longleftrightarrow \partial \Lambda_k(x)]$.

